\section{The shadowing property}\label{section:shadowing}
We first introduce the shadowing property for topological dynamical systems, then generalise to CR-dynamical systems in the next section. To define the shadowing property, we require the notion of pseudo-orbits and shadowing points. We first consider $\p{X, d}$ to be a metric space. 

\begin{definition}
Let $\p{X, f}$ be a topological dynamical system and $\delta > 0$.  A sequence $\sequenceOf{x_n}:{n \in \omega}$ in $X$ is a {\color{blue} \emph{$\delta$-pseudo-orbit}}, provided $d\of{f\of{x_n}, x_{n+1}} \leq \delta$ for each $n \in \omega$. 
\end{definition}


\begin{definition}
Let $\p{X, f}$ be a topological dynamical system and $\epsilon > 0$. A point $y \in X$ {\color{blue} \emph{$\epsilon$-shadows}} a sequence $\sequenceOf{x_n}:{n \in \omega}$, provided $d\of{f^n\of{y}, x_n} < \epsilon$ for each $n \in \omega$. 
\end{definition}

\begin{definition}\label{def:metric-shadowing-topological}
A topological dynamical system $\p{X, f}$ has the {\color{blue} \emph{shadowing property}}, if for every $\epsilon > 0$ there exists a $\delta > 0$ such that every $\delta$-pseudo-orbit is  $\epsilon$-shadowed by a point in $X$. 
\end{definition}

We now define the shadowing property for uniform spaces $\p{X, \collection{U}}$. 

\begin{definition}
Let $\p{X, f}$ be a topological dynamical system and $V \in \collection{U}$. A sequence $\sequenceOf{x_n}:{n \in \omega}$ in $X$ is a {\color{blue} \emph{$V$-pseudo-orbit}}, provided $\p{f\of{x_n}, x_{n+1}} \in V$ for each $n \in \omega$. 
\end{definition}

\begin{definition}
Let $\p{X, f}$ be a topological dynamical system and $U \in \collection{U}$. A point $y \in X$ {\color{blue} \emph{$U$-shadows}} a sequence $\sequenceOf{x_n}:{n \in \omega}$, provided $\p{f^n\of{y}, x_n} \in U$ for each $n \in \omega$.
\end{definition}

\begin{definition}\label{def:uniform-shadowing-topological}
A topological dynamical system $\p{X, f}$ has the {\color{blue} \emph{shadowing property}}, if for every $U \in \collection{U}$ there exists an entourage $V \in \collection{U}$ such that every $V$-pseudo-orbit is  $U$-shadowed by a point in $X$. 
\end{definition}


Indeed, if $X$ is a non-empty compact metric space, Definition~\ref{def:metric-shadowing-topological} and Definition~\ref{def:uniform-shadowing-topological} are equivalent. 

In this paper, we generalise the following three well-known results to CR-dynamical systems. Note Lemma~\ref{lem:invariance-under-comp-topological} has been generalised in set-valued dynamical systems for metric spaces~\cite[Proposition $3.2$]{Luo2020}. 

\begin{lemma}\label{lem:invariance-under-comp-topological}
Let $\p{X, f}$ be a topological dynamical system. Then $\p{X, f}$ has the shadowing property if, and only if, $\p{X, f^n}$ has the shadowing property for all $n \geq 1$. 
\end{lemma}


\begin{theorem}\label{thm:id-shadowing-iff-totally-disconnected}
Let $\p{X, \emph{id}_X}$ be a topological dynamical system, where $\emph{id}_X$ is the identity map on $X$. Then, $\p{X, \emph{id}_X}$ has the shadowing property if, and only if, $X$ is totally disconnected. 
\end{theorem}

%Below is a generalisation of Theorem $5$ in~\cite{meddaugh_shadowing_recurrence} to uniform spaces. 

\begin{theorem}\label{thm:periodic-shadowing-iff-totally-disconnected}
Suppose $\p{X, f}$ is a topological dynamical system with $f^n = \emph{id}_X$ for some $n \geq 1$.  Then, $\p{X, f}$ has the shadowing property if, and only if, $X$ is totally disconnected.   
\end{theorem}
