\section{$\p{i, j}$-shadowing properties}\label{section:ij-shadowing}
\subsection{Basic definitions}

We firstly go over basic definitions, generalising the shadowing property to CR-dynamical systems (for both metric and uniform spaces). Further, we show these properties are robust in the sense they are invariant under topological conjugacy (see~\cite[Definition $9.3$]{minimality_CR}), and that the definitions for metric and uniform spaces coincide when our non-empty compact Hausdorff spaces are metrizable. We first consider $\p{X, d}$ a metric space. 

\begin{definition}
Let $\p{X, G}$ be a CR-dynamical system and $\delta > 0$. We say a sequence $\sequenceOf{x_n}:{n \in \omega}$ in $\nondegenerate{G}$ is a {\color{blue} \emph{$\p{\delta, i}$-pseudo-orbit}}, provided $d\of{x_{n+1}, y} \leq \delta$ for
\begin{itemize}
    \item[{\color{red} $\p{i = 1}$}] \textbf{all}  $y \in G\of{x_n}$,
    \item[{\color{red} $\p{i = 2}$}] \textbf{some}  $y \in G\of{x_n}$,
\end{itemize}
for all $n \in \omega$. 
\end{definition}


\begin{observation}
Let $\p{X, G}$ be a CR-dynamical system and $\delta > 0$. Every $\p{\delta, 1}$-pseudo-orbit is a $\p{\delta, 2}$-pseudo-orbit. 
\end{observation}



\begin{definition}
Let $\p{X, G}$ be a CR-dynamical system and $\epsilon > 0$. We say $y \in \legal{G}$ {\color{blue} \emph{$\p{\epsilon, j}$-shadows}} a sequence $\sequenceOf{x_n}:{n \in \omega}$, provided for
\begin{itemize}
    \item[{\color{red} $\p{j = 1}$}] \textbf{all}  $\sequenceOf{y_n}:{n \in \omega} \in T_G^+\of{y}$,
    \item[{\color{red} $\p{j = 2}$}] \textbf{some}  $\sequenceOf{y_n}:{n \in \omega} \in T_G^+\of{y}$,
\end{itemize}
we have $d\of{x_n, y_n} < \epsilon$ for each $n \in \omega$.
\end{definition}

\begin{observation}
Let $\p{X, G}$ be a CR-dynamical system and $\epsilon > 0$. Every $\p{\epsilon, 1}$-shadowing-point is an $\p{\epsilon, 2}$-shadowing-point. 
\end{observation}



\begin{definition}\label{def:metric-ij-shadowing}
A CR-dynamical system $\p{X, G}$ has the {\color{blue} \emph{$\p{i, j}$-shadowing property}}, if for every $\epsilon > 0$ there exists a $\delta > 0$ such that every $\p{\delta, i}$-pseudo-orbit is $\p{\epsilon, j}$-shadowed by a point in $X$. 
\end{definition}

\begin{note}
The shadowing property examined in set-valued dynamical systems~\cite{specification, yin_shadowing_property_set_valued_map, yu_rieger, yin2024finitetypefundamentalobjects, Luo2020} corresponds to the $\p{2, 2}$-shadowing property. As such, we make the following observation. 
\end{note}

\begin{observation}
Let $\p{X, f}$ be a set-valued dynamical system and $F = \Graph{f}$. Then, $\p{X, f}$ has the shadowing property if, and only if, $\p{X, F}$ has the $\p{2, 2}$-shadowing property. 
\end{observation}

We now consider $\p{X, \collection{U}}$ a uniform space. 

\begin{definition}
Let $\p{X, G}$ be a CR-dynamical system and $V \in \collection{U}$. We say a sequence $\sequenceOf{x_n}:{n \in \omega}$ in $\nondegenerate{G}$ is a {\color{blue} \emph{$\p{V, i}$-pseudo-orbit}}, provided $\p{y, x_{n+1}} \in V$ for
\begin{itemize}
    \item[{\color{red} $\p{i = 1}$}] \textbf{all}  $y \in G\of{x_n}$,
    \item[{\color{red} $\p{i = 2}$}] \textbf{some}  $y \in G\of{x_n}$,
\end{itemize}
for all $n \in \omega$. 
\end{definition}


\begin{definition}
Let $\p{X, G}$ be a CR-dynamical system and $U \in \collection{U}$. We say $y \in \legal{G}$ {\color{blue} \emph{$\p{U, j}$-shadows}} a sequence $\sequenceOf{x_n}:{n \in \omega}$, provided for
\begin{itemize}
    \item[{\color{red} $\p{j = 1}$}] \textbf{all}  $\sequenceOf{y_n}:{n \in \omega} \in T_G^+\of{y}$,
    \item[{\color{red} $\p{j = 2}$}] \textbf{some}  $\sequenceOf{y_n}:{n \in \omega} \in T_G^+\of{y}$,
\end{itemize}
we have $\p{y_n, x_n} \in U$ for each $n \in \omega$.
\end{definition}


\begin{definition}\label{def:uniform-ij-shadowing}
A CR-dynamical system $\p{X, G}$ has the {\color{blue} \emph{$\p{i, j}$-shadowing property}}, if for every $U \in \collection{U}$ there exists $V \in \collection{U}$ such that every $\p{V, i}$-pseudo-orbit is $\p{U, j}$-shadowed by a point in $X$. 
\end{definition}

\begin{proposition}
The $\p{i, j}$-shadowing properties in Definition~\ref{def:metric-ij-shadowing} and Definition~\ref{def:uniform-ij-shadowing} coincide for non-empty compact metric spaces. 
\end{proposition}
\begin{proof}
Suppose $\p{X, G}$ is a CR-dynamical system, where $\p{X, d}$ is a compact metric space and $\collection{U}$ is a uniformity on $X$. Suppose $\p{X, G}$ has the $\p{i, j}$-shadowing property as in Definition~\ref{def:metric-ij-shadowing}. Let $U \in \collection{U}$. There exists $\epsilon > 0$, such that $d^{-1}\of{[0, \epsilon]} \subseteq U$. It follows that there exists $\delta > 0$ satisfying Definition~\ref{def:metric-ij-shadowing}. Let $V = d^{-1}\of{[0, \delta]}$. Suppose $\sequenceOf{x_n}:{n \in \omega}$ is a $\p{V, i}$-pseudo-orbit. Then, $\sequenceOf{x_n}:{n \in \omega}$ is a $\p{\delta, i}$-pseudo-orbit, which means that there exists $y \in \legal{G}$ that $\p{\epsilon, j}$-shadows $\sequenceOf{x_n}:{n \in \omega}$. Indeed, by choice of $\epsilon$, $y$ $\p{U, j}$-shadows $\sequenceOf{x_n}:{n \in \omega}$. Thus, $\p{X, G}$ has the $\p{i, j}$-shadowing property as in Defintion~\ref{def:uniform-ij-shadowing}. 

Now, suppose $\p{X, G}$ has the $\p{i, j}$-shadowing property as in Definition~\ref{def:uniform-ij-shadowing}. Let $\epsilon > 0$, and $U = d^{-1}\of{[0, \Fraction \epsilon / 2]}$. There exists entourage $V \in \collection{U}$ satisfying Definition~\ref{def:uniform-ij-shadowing}. There exists $\delta > 0$, such that $d^{-1}\of{[0, \delta]} \subseteq V$. Suppose $\sequenceOf{x_n}:{n \in \omega}$ is a $\p{\delta, i}$-pseudo-orbit. Then, $\sequenceOf{x_n}:{n \in \omega}$ is a $\p{V, i}$-pseudo-orbit, which means that there exists $y \in \legal{G}$ that $\p{U, j}$-shadows $\sequenceOf{x_n}:{n \in \omega}$. Indeed, by choice of $U$, $y$ $\p{\epsilon, j}$-shadows $\sequenceOf{x_n}:{n \in \omega}$. Thus, $\p{X, G}$ has the $\p{i, j}$-shadowing property as in Definition~\ref{def:metric-ij-shadowing}. 
\end{proof}
\begin{note}
Due to this result, for metric spaces we use these definitions interchangeably. Otherwise, we implicitly use the uniformity definitions. 
\end{note}

\begin{proposition}
The $\p{i, j}$-shadowing properties are invariant under topological conjugacy. 
\end{proposition}
\begin{proof}
Suppose $\p{X, G}$ and $\p{Y, H}$ are CR-dynamical systems which are topologically conjugate to one another. Then, there is a homeomorphism $\varphi : X \to Y$ such that $\p{x, y} \in G$ if, and only if, $\p{\varphi\of{x}, \varphi\of{y}} \in H$. Suppose $\p{X, G}$ has the $\p{i, j}$-shadowing property. We show $\p{Y, H}$ has the $\p{i, j}$-shadowing property. To this end, suppose $U_Y$ is an entourage of $Y$. Since $X$ is a non-empty compact Hausdorff space and $Y$ is a uniform space, $\varphi$ is uniformly continuous. So, there exists entourage $U_X$ of $X$ such that if $\p{x, y} \in U_X$, then $\p{\varphi\of{x}, \varphi\of{y}} \in U_Y$. Now, since $\p{X, G}$ has the $\p{i, j}$-shadowing property, there exists entourage $V_X$ of $X$ such that every $\p{V_X, i}$-pseudo-orbit is $\p{U_X, j}$-shadowed by a point in $X$. Since $Y$ is a non-empty compact Hausdorff space and $X$ is a uniform space, $\varphi^{-1}$ is uniformly continuous. So, there exists entourage $V_Y$ of $Y$ such that if $\p{x, y} \in V_Y$, then $\p{\varphi^{-1}\of{x}, \varphi^{-1}\of{y}} \in V_X$. 

Now, suppose $\sequenceOf{\varphi\of{x_n}}:{n \in \omega}$ is a $\p{V_Y, i}$-pseudo-orbit in $Y$. Since $H\of{\varphi\of{x_n}} = \varphi\of{G\of{x_n}}$, it follows $\sequenceOf{x_n}:{n \in \omega}$ is a $\p{V_X, i}$-pseudo-orbit in $X$. Hence, there exists $y \in \legal{G}$ which $\p{U_X, j}$-shadows $\sequenceOf{x_n}:{n \in \omega}$. Clearly, $\varphi\of{y} \in \legal{H}$, and $\p{U_Y, j}$-shadows $\sequenceOf{\varphi\of{x_n}}:{n \in \omega}$. Thus, $\p{Y, H}$ has the $\p{i, j}$-shadowing property.  
\end{proof}

