Let $\p{X, G}$ be a CR-dynamical system, where $X = [0, 1]$ and $G = \p{X \times \set{0}} \union \Delta_X$, depicted in Figure~\ref{fig:diag-const-11}. By Proposition~\ref{prop:diagonal-plus-horizontal}, $\p{X, G}$ has the $\p{1, 1}$-shadowing property. We show $\p{X, G}$ does not have the $\p{2, 2}$-shadowing property. Let $\epsilon = \Fraction 1 / 2$, and $\delta > 0$ be arbitrary. There exists $n \in \omega$ such that $\Fraction 1 / n \leq \delta$. Consider $\sequence{0, \Fraction 1 / n, \Fraction 2 / n, \ldots, 1, 1, \ldots}$, which is a $\p{\delta, 2}$-pseudo-orbit. To derive a contradiction, suppose there exists $y \in X$ which $\p{\epsilon, 2}$-shadows our sequence. Then, $d\of{0, y} < \Fraction 1/ 2$, and $d\of{1, y} < \Fraction 1 / 2$ (for $d\of{1, 0} \geq \Fraction 1 / 2$). But by the triangle inequality, we obtain $1 < 1$, a contradiction. It follows $\p{X, G}$ does not have the $\p{2, 2}$-shadowing property. 
\end{example}

These previous three examples show the $\p{i, j}$-shadowing properties are distinct. We now go over basic results in the next sub-section, including a generalisation of Lemma~\ref{lem:invariance-under-comp-topological}. 





\subsection{Basic results}
\begin{proposition}\label{prop:topological-relation-correspondence}
Suppose $\p{X, f}$ is a topological dynamical system. Then, $\p{X, f}$ has the shadowing property if, and only if, $\p{X, \Graph{f}}$ has the $\p{i, j}$-shadowing property for all $i, j \in \set{1, 2}$. 
\end{proposition}
\begin{proof}
Follows by definition. 
\end{proof}

\begin{lemma}\label{lem:extension}
Suppose $\p{X, G}$ and $\p{X, H}$ are CR-dynamical systems such that $G \subseteq H$ and  $\nondegenerate{G} = \nondegenerate{H}$. If $\p{X, G}$ has the $\p{1, 2}$-shadowing property, then $\p{X, H}$ has the $\p{1, 2}$-shadowing property. 
\end{lemma}
\begin{proof}
Suppose $\p{X, G}$ has the $\p{1, 2}$-shadowing property. Let $U$ be an entourage of $X$. In $\p{X, G}$, there exists entourage $V$ of $X$ such that every $\p{V, 1}$-pseudo-orbit is $\p{U, 2}$-shadowed by a point in $X$. Suppose $\sequenceOf{x_n}:{n \in \omega}$ is a $\p{V, 1}$-pseudo-orbit in $\p{X, H}$.  Then, $\sequenceOf{x_n}:{n \in \omega}$ is a sequence in $\nondegenerate{H} = \nondegenerate{G}$ where $G\of{x_n} \times \set{x_{n+1}} \subseteq H\of{x_n} \times \set{x_{n+1}} \subseteq V$ for each $n \in \omega$. It follows $\sequenceOf{x_n}:{n \in \omega}$ is a $\p{V, 1}$-pseudo-orbit in $\p{X, G}$. Therefore, $\sequenceOf{x_n}:{n \in \omega}$ is $\p{U, 2}$-shadowed by a legal point $y$ in $\p{X, G}$. Since $T_G^+\of{y} \subseteq T_H^+\of{y}$, $\sequenceOf{x_n}:{n \in \omega}$ is $\p{U, 2}$-shadowed by $y$ in $\p{X, H}$. Thus, $\p{X, H}$ has the $\p{1, 2}$-shadowing property. 
\end{proof}

\begin{corollary}
Let $\p{X, f}$ be a topological dynamical system with the shadowing property. If $\p{X, G}$ is a CR-dynamical system with $\Graph{f} \subseteq G$, then $\p{X, G}$ has the $\p{1, 2}$-shadowing property.  
\end{corollary}
\begin{proof}
Follows from Proposition~\ref{prop:topological-relation-correspondence} and Lemma~\ref{lem:extension}.  
\end{proof}


\begin{lemma}\label{lem:contraction}
Suppose $\p{X, G}$ and $\p{X, H}$ are CR-dynamical systems such that $G \subseteq H$ and $\legal{G} = \legal{H}$. If $\p{X, H}$ has the $\p{2, 1}$-shadowing property, then $\p{X, G}$ has the $\p{2, 1}$-shadowing property.
\end{lemma}
\begin{proof}
Suppose $\p{X, H}$ has the $\p{2, 1}$-shadowing property.  Let $U$ be an entourage of $X$. In $\p{X, H}$, there exists entourage $V$ of $X$ such that every $\p{V, 2}$-pseudo-orbit is $\p{U, 1}$-shadowed by a point in $X$. Suppose $\sequenceOf{x_n}:{n \in \omega}$ is a $\p{V, 2}$-pseudo-orbit in $\p{X, G}$. Then $\sequenceOf{x_n}:{n \in \omega}$ is a $\p{V, 2}$-pseudo-orbit in $\p{X, H}$. There exists $y \in \legal{H} = \legal{G}$ which $\p{U, 1}$-shadows $\sequenceOf{x_n}:{n \in \omega}$ in $\p{X, H}$. Since $\emptySet \neq T_G^+\of{y} \subseteq T_H^+\of{y}$, $\sequenceOf{x_n}:{n \in \omega}$ is $\p{U, 1}$-shadowed by $y$ in $\p{X, G}$. Thus, $\p{X, G}$ has the $\p{2, 1}$-shadowing property. 
\end{proof}

