\begin{proposition}\label{prop:diagonal-plus-horizontal}
Let $\p{X, G}$ be a CR-dynamical system such that $G = \Delta_X \union \p{X \times \set{x}}$ for some $x \in X$. Then $\p{X, G}$ has the $\p{1, 1}$-shadowing property. 
\end{proposition}
\begin{proof}
Suppose $V \in \collection{U}$. Then there exists entourage $U$ of $X$ such that $U^2 \subseteq V$. Let $W = \p{U \intersect V} \intersect \p{U \intersect V}^{-1}$.  If $\sequenceOf{x_n}:{n \in \omega}$ is a $\p{W, 1}$-pseudo-orbit, then $G\of{x_n} \times \set{x_{n+1}} \subseteq W$ for each $n \in \omega$. That is, $\set{x, x_n} \times \set{x_{n+1}} \subseteq W$, yielding $\p{x, x_{n+1}}, \p{x_{n+1}, x_n} \in W \subseteq U$ for each $n \in \omega$. Hence, $\p{x, x_n} \in V$ for all $n \in \omega$, implying $x$ $\p{V, 1}$-shadows $\sequenceOf{x_n}:{n \in \omega}$. Thus, $\p{X, G}$ has the $\p{1, 1}$-shadowing property. 
\end{proof}

We now show Theorem~\ref{thm:diagonal-totally-disconnected}, the generalisation of Theorem~\ref{thm:id-shadowing-iff-totally-disconnected}, cannot be improved.

\begin{proposition}\label{prop:id-shadowing-diagonal-totally_disconnected-counterexamples}
Suppose $\p{X, G}$ is a CR-dynamical system with $\Delta_X \subseteq G$ and $j \in \set{1, 2}$. Then, 
\begin{enumerate}
    \item if $\p{X, G}$ has the $\p{2, 2}$-shadowing property, then $X$ need not be totally disconnected; 
    \item if $\p{X, G}$ has the $\p{1, j}$-shadowing property, then $X$ need not be totally disconnected;
    \item if $X$ is totally disconnected, then $\p{X, G}$ need not have the $\p{2, 1}$-shadowing property; 
    \item if $X$ is totally disconnected, then $\p{X, G}$ need not have the $\p{1, 1}$-shadowing property;
    \item if $X$ is totally disconnected, then $\p{X, G}$ need not have the $\p{2, 2}$-shadowing property.  
\end{enumerate}
\end{proposition}
\begin{proof}
For $\p{1}$, take $X = [0, 1]$ and $G = X \times X$. Suppose $U$ is an entourage. Then, every $\p{U, 2}$-pseudo-orbit is a trajectory, and thus $\p{U, 2}$-shadows itself. It follows $\p{X, G}$ has the $\p{2, 2}$-shadowing property, but indeed $X$ is not totally disconnected. 

For $\p{2}$, take $X = [0, 1]$ and $G = \Delta_X \union \p{X \times \set{0}}$, then apply Proposition~\ref{prop:diagonal-plus-horizontal}. 

For $\p{3}$, take $X = \set{0, 1}$ with discrete topology and $G = X \times X$, then apply Proposition~\ref{prop:dom-G-finite-21} to obtain $\p{X, G}$ does not have the $\p{2, 1}$-shadowing property. 

For $\p{4}$, take $X$ to be the Cantor set and $G = \Delta_X \union \p{X \times \set{0}} \union \p{\set{0} \times X}$. Choose $\epsilon = \Fraction 1 / 2$, and let $\delta > 0$ be arbitrary. There exists $n \in \omega$ such that $\Fraction 4 / {3^n} \leq \delta$. Observe $\sequenceOf{\Fraction 2 / {3^k}}:{k \geq n}$ is a $\p{\delta, 1}$-pseudo-orbit. To derive a contradiction, suppose there exists $y \in X$ which $\p{\epsilon, 1}$-shadows $\sequenceOf{\Fraction 2 / {3^k}}:{k \geq n}$. Notice $0, 1 \in G^2\of{y}$. But this means $d\of{\Fraction 2 / {3^{n+2}}, 0} < \epsilon$ and $d\of{\Fraction 2 / {3^{n+2}}, 1} < \epsilon$. Applying the triangle inequality yields $d\of{0, 1} < 1$, a contradiction. Thus, $\p{X, G}$ does not have the $\p{1, 1}$-shadowing property. 

For $\p{5}$, take $X$ to be the Cantor set, and $G = \Delta_X \union \setOf{\p{a_n, a_{n+1}}}:{n \in \omega} \union \setOf{\p{b_n, b_{n+1}}}:{n \in \integers}$, where $\sequenceOf{a_n}:{n \in \omega}$ and $\sequenceOf{b_n}:{n \in \integers}$ are sequences in $X$ with the properties,
\begin{itemize}
    \item for each $\p{n, m} \in \omega \times \integers$, $a_n < a_{n+1}$ and $b_m < b_{m+1}$;
    \item $a_0 = 0$, $\lim_{n \to +\infinity} a_n = \Fraction 2 / 9 = \lim_{n\to -\infinity} b_n$ and $\lim_{n \to +\infinity} b_n = \Fraction 1 / 3$. 
\end{itemize}
Indeed, $\p{X, G}$ is a CR-dynamical system. Now, let $\epsilon = \Fraction 1 / {27}$, and $\delta > 0$ be arbitrary. There exists $\p{n, m} \in \omega \times \integers$ such that $\sequence{a_0, \ldots, a_n, b_m, b_{m+1}, \ldots}$ is a $\p{\delta, 2}$-pseudo-orbit. However, it is not $\p{\epsilon, 2}$-shadowed by any point in $X$: to derive a contradiction, suppose $y$ $\p{\epsilon, 2}$-shadows $\sequence{a_0, \ldots, a_n, b_m, b_{m+1}, \ldots}$. Then, $d\of{0, y} < \Fraction 1/ {27}$. This implies $G^k\of{y} \subseteq [0, \Fraction 2 / 9] \intersect X$ for all $k \in \omega$. Since $\lim_{k \to +\infinity} b_k = \Fraction 1 / 3$, there exists $\ell \geq m$ such that $d\of{\Fraction 1 /3, b_\ell} < \Fraction 1/ {27}$. There exists $y_\ell \in G^k\of{y}$ for some $k \in \omega$, such that $d\of{b_\ell, y_\ell} < \Fraction 1 / {27}$, by the assumption $y$ $\p{\epsilon, 2}$-shadows our sequence. But then
\[
\Fraction 1 / 3 = d\of{\Fraction 1 / 3, 0} \leq d\of{\Fraction 1 / 3, b_{\ell}} + d\of{b_\ell, y_\ell} + d\of{y_\ell, 0} < \Fraction 1 / {27} + \Fraction 1 / {27} + \Fraction 2 / {9} = \Fraction 8 / {27}, 
\]
a contradiction. 
\end{proof}

We now make an observation on $\p{1}$ in Theorem~\ref{thm:diagonal-totally-disconnected}, which generalises the forward direction in Theorem~\ref{thm:id-shadowing-iff-totally-disconnected}, showing the condition implies $G$ is the graph of a continuous function. Indeed, the same holds when generalising the forward direction of Theorem~\ref{thm:periodic-shadowing-iff-totally-disconnected}. 

\begin{proposition}\label{prop:21-implies-diagonal}
Suppose $\p{X, G}$ is a CR-dynamical system with $\Delta_X \subseteq G$. If $\p{X, G}$ has the $\p{2, 1}$-shadowing property, then $G = \Delta_X$. 
\end{proposition}
\begin{proof}
Suppose $\p{X, G}$ has the $\p{2, 1}$-shadowing property. To derive a contradiction, suppose $G \neq \Delta_X$. Then, there exists $x \in X$ such that there are $y \neq z \in G\of{x}$. There exists entourage $W$ of $X$ such that $\p{y, z} \notin W$. Let $U \subseteq W$ be a symmetric entourage of $X$ such that $U^4 \subseteq W$. There exists entourage $V$ of $X$ satisfying the $\p{2, 1}$-shadowing property for $U$. Observe $\sequence{x, y, y, \ldots}$ and $\sequence{x, z, z, \ldots}$ are both $\p{V, 2}$-pseudo-orbits. There exists $u, v \in X$ which $\p{U, 1}$-shadow $\sequence{x, y, y, \ldots}$ and $\sequence{x, z, z, \ldots}$, respectively. Then, $\p{y, u}, \p{u, x}, \p{x, v}, \p{v, z} \in U$. But this implies $\p{y, z} \in U^4 \subseteq W$, a contradiction. Thus, it must be the case $G = \Delta_X$. 
\end{proof}


\begin{corollary}\label{cor:21-implies-function}
Suppose $\p{X, G}$ is a CR-dynamical system with $\Delta_X \subseteq G^n$ for some positive integer $n$. If $\p{X, G}$ has the $\p{2, 1}$-shadowing property, then $G = \Graph{f}$ for some continuous self-map $f$ on $X$.
\end{corollary}
\begin{proof}
Suppose $\p{X, G}$ has the $\p{2, 1}$-shadowing property. By Lemma~\ref{lem:invariance-under-comp}, $\p{X, G^n}$ has the $\p{2, 1}$-shadowing property. By Proposition~\ref{prop:21-implies-diagonal}, $G^n = \Delta_X$. Result now follows by Proposition~\ref{prop:G^n=diagonal-implies-G-single-valued}. 
\end{proof}

We now work towards generalising Theorem~\ref{thm:periodic-shadowing-iff-totally-disconnected}. 



\begin{lemma}\label{lem:set-valued-construction}
Suppose $\p{X, G}$ is a CR-dynamical system with $\Delta_X \subseteq G^n$ for some positive integer $n$. Let $k \in [n]$.  Define $F_k : X \to 2^X$ by 
\[
F_k\of{x} = \setOf{y \in X}:{y \in G^k\of{x} \text{ and } x \in G^{n-k}\of{y}}
\]
for each $x \in X$. Then, $\p{X, \Graph{F_k}}$ is a CR-dynamical system. 
\end{lemma}
\begin{proof}
We first show $F_k$ is well-defined (i.e., $F_k\of{x}$ is a non-empty closed subset of $X$ for each $x \in X$). Since $\Delta_X \subseteq G^n$, $F_k\of{x}$ is non-empty for each $x \in X$. Observe
\[
F_k\of{x} = \pi_k\of{\pi_0^{-1}\of{x} \intersect \pi_n^{-1}\of{x} \intersect \mahavier{n}{G}}.
\]
Indeed, the projection maps are continuous implying $\pi_0^{-1}\of{x} \intersect \pi_n^{-1}\of{x}$ is closed in $\prod_{i=0}^n X$, and thus $\pi_0^{-1}\of{x} \intersect \pi_n^{-1}\of{x} \intersect \mahavier{n}{G}$ is closed in $\prod_{i=0}^n X$ ($\mahavier{n}{G}$ is closed by Lemma~\ref{lem:mahavier-closed}). Since $X$ is compact and Hausdorff, it easily follows $F_k\of{x}$ is closed. 

Now, it remains to show $\Graph{F_k}$ is closed in $X \times X$. Suppose $\p{x, y} \in \p{X \times X} \setMinus \Graph{F_k}$. We consider two cases. First, suppose $y \notin G^k\of{x}$. Since $X$ is regular, there exist disjoint open nhoods $U$ and $V$ of $G^k\of{x}$ and $y$, respectively. As the set-valued function with graph $G^k$ is upper semi-continuous, there exists open nhood $W$ of $x$ such that if $z \in W$, then $G^k\of{z} \subseteq U$. Hence, $W \times V \subseteq \p{X \times X} \setMinus \Graph{F_k}$ is an open nhood of $\p{x, y}$. On the other hand, we now suppose $y \in G^k\of{x}$. It must be the case $x \notin G^{n-k}\of{y}$, for otherwise $y \in F_k\of{x}$ (contradicting $\p{x, y} \notin \Graph{F_k}$). Since $X$ is regular, there exist disjoint open nhoods $U$ and $V$ of $x$ and $G^{n-k}\of{y}$, respectively. As the set-valued function with graph $G^{n-k}$ is upper semi-continuous, there exists open nhood $W$ of $y$ such that if $z \in W$, $G^{n-k}\of{z} \subseteq V$. Observe $U \times W \subseteq \p{X \times X} \setMinus \Graph{F_k}$ is an open nhood of $\p{x, y}$. For if $\p{a, b} \in \p{U \times W} \intersect \Graph{F_k}$, then $a \in G^{n-k}\of{b} \subseteq V$ (but $a \in U$, and $U$ is disjoint from $V$, a contradiction). It follows $\Graph{F_k}$ is closed, and thus $\p{X, \Graph{F_k}}$ is a CR-dynamical system. 
\end{proof}

\begin{proposition}
Suppose $\p{X, G}$ is a CR-dynamical system. If $X$ is totally disconnected, and there exists positive integer $n$ such that for each $x \in X$ there exists unique $\sequence{x_0, \ldots, x_n} \in \mahavier{n}{G}$ with $\set{x_0, x_n} = \set{x}$, then $\p{X, G}$ has the $\p{1, 2}$-shadowing property.
\end{proposition}
\begin{proof}
Suppose $X$ is totally disconnected, and there exists positive integer $n$ such that for each $x \in X$ there is exactly one $\sequence{x_0, \ldots, x_n} \in \mahavier{n}{G}$ with $\set{x_0, x_n} = \set{x}$. Define $f : X \to X$ by $f\of{x} = x_1$, where $\sequence{x_0, \ldots, x_n} \in \mahavier{n}{G}$ such that $\set{x_0, x_n} = \set{x}$, for each $x \in X$. We have $f^n = \text{id}_X$ and $\Delta_X \subseteq G^n$. Observe $\Graph{f} = \Graph{F_1}$, where $F_1$ is as defined in Lemma~\ref{lem:set-valued-construction}, and thus $\Graph{f}$ closed in $X$ (implying $f$ is continuous). 

By Theorem~\ref{thm:periodic-shadowing-iff-totally-disconnected}, $\p{X, f}$ has the shadowing property. Hence, the CR-dynamical system $\p{X, \Graph{f}}$ has the $\p{1, 2}$-shadowing property. By Lemma~\ref{lem:extension}, $\p{X, G}$ has the $\p{1, 2}$-shadowing property.
\end{proof}

\begin{note}
In the metric space setting, the proof of Theorem~\ref{thm:periodic-shadowing-iff-totally-disconnected} uses uniform continuity (see~\cite[Theorem $5$]{meddaugh_shadowing_recurrence}). Recently, uniform continuity has been generalised to set-valued functions on metric spaces~\cite{set_valued_uniform_continuity}. We generalise further, providing a notion of uniform continuity for usc set-valued functions on uniform spaces, which we use in our proof to generalise Theorem~\ref{thm:periodic-shadowing-iff-totally-disconnected}. 
\end{note}

\begin{definition}
Suppose $F : X \to 2^Y$ is an upper semi-continuous set-valued function with uniform spaces $\p{X, \collection{U}}$ and $\p{Y, \collection{V}}$. We will say $F$ is {\color{blue} \emph{uniformly upper semi-continuous}}, if for each entourage $V \in \collection{V}$, there exists entourage $U \in \collection{U}$ such that if $\p{x, y} \in U$, then $F\of{x} \subseteq V^{-1}\of{F\of{y}}$. 
\end{definition}


\begin{theorem}
Suppose $\p{X, G}$ is a CR-dynamical system with $\Delta_X \subseteq G^n$ for some positive integer $n$, and $F_k$ is as defined in Lemma~\ref{lem:set-valued-construction} for each $k \in [n]$. Then, 
\begin{enumerate}
    \item if $\p{X, G}$ has the $\p{2, 1}$-shadowing property, then $X$ is totally disconnected; 
     \item if $X$ is totally disconnected and $F_k$ is uniformly upper semi-continuous for each $k \in [n]$,
     then $\p{X, G}$ has the $\p{1, 2}$-shadowing property.
\end{enumerate}
\end{theorem}
\begin{proof}
Suppose $\p{X, G}$ has the $\p{2, 1}$-shadowing property and $\Delta_X \subseteq G^n$ for some positive integer $n$.  By Lemma~\ref{lem:invariance-under-comp}, $\p{X, G^n}$ has the $\p{2, 1}$-shadowing property. By Theorem~\ref{thm:diagonal-totally-disconnected}, $X$ is totally disconnected, establishing $\p{1}$. 



