We now generalise the equivalence between $\p{1}$ and $\p{2}$ in Theorem~\ref{thm:isometry-mahavier}. 

\begin{theorem}
Let $\p{X, G}$ be a CR-dynamical system, such that there exists an isometry $f : X \to X$ with $\Graph{f} \subseteq G$. Then, 
\begin{enumerate}
\item if $\p{X, G}$ has the $\p{2, 1}$-shadowing property, then $\p{X_G^+, \sigma_G^+}$ has the shadowing property;
\item if $\p{X_G^+, \sigma_G^+}$ has the shadowing property, then $\p{X, G}$ has the $\p{1, 2}$-shadowing property. 
\end{enumerate}
\end{theorem}
\begin{proof}
If $\p{X, G}$ has the $\p{2, 1}$-shadowing property, then $G = \Graph{f}$ by Proposition~\ref{prop:21-isometry-implies-single-val}. It follows $\p{X, f}$ has the shadowing property, and thus $\p{X_G^+, \sigma_G^+} = \p{X_\Graph{f}^+, \sigma_\Graph{f}^+}$ has the shadowing property by Theorem~\ref{thm:isometry-mahavier}.  

We now prove $\p{2}$. To this end, suppose $\p{X_G^+, \sigma_G^+}$ has the shadowing property.  Let $\epsilon > 0$. There exists $\delta > 0$ satisfying the shadowing property for $\p{X_G^+, \sigma_G^+}$, such that every $\delta$-pseudo-orbit is $\Fraction \epsilon / 2$-shadowed. Suppose $\sequenceOf{x_n}:{n \in \omega}$ is a $\p{\delta, 1}$-pseudo-orbit in $\p{X, G}$. Then, for each $n \in \omega$, $d\of{z, x_{n+1}} \leq \delta$ for every $z \in G\of{x_n}$. In particular, $d\of{f\of{x_n}, x_{n+1}} \leq \delta$ for each $n \in \omega$. Observe $\sequenceOf{\p{f^k\of{x_n}}_{k \in \omega}}:{n \in \omega}$ is a $\delta$-pseudo-orbit in $\p{X_G^+, \sigma_G^+}$, since
\begin{align*}
&&  \rho\of{\sigma_G^+\of{\sequence{x_n, f\of{x_n}, \ldots}}, \sequence{x_{n+1}, f\of{x_{n+1}}, \ldots}} &= \sum_{k = 0}^\infinity \Fraction d\of{f^{k+1}\of{x_n}, f^k\of{x_{n+1}}} / {2^{k+1}} && \\
&& &= \sum_{k=0}^\infinity \Fraction d\of{f\of{x_n}, x_{n+1}} / {2^{k+1}} && \\
&& &\leq \sum_{k=0}^\infinity \Fraction \delta / {2^{k+1}} && \\
&&  &= \delta &&
\end{align*}
for each $n \in \omega$. Hence, there exists $\sequenceOf{y_n}:{n \in \omega} \in X_G^+$ which $\Fraction \epsilon / 2$-shadows our $\delta$-pseudo-orbit, i.e., 
\[
\sum_{k=0}^\infinity \Fraction d\of{f^k\of{x_n}, y_{n+k}} / {2^{k+1}} < \Fraction \epsilon / 2
\]
for each $n \in \omega$. It follows 
\[
d\of{x_n, y_n} < \epsilon
\]
for each $n \in \omega$, implying $y_0$ $\p{\epsilon, 2}$-shadows $\sequenceOf{x_n}:{n \in \omega}$. Thus, $\p{X, G}$ has the $\p{1, 2}$-shadowing property, and we are done. 
\end{proof}

