\[
\sum_{k = 0}^\infinity \Fraction d\of{x_{n, k + 1}, x_{n + 1, k}} / {2^{k+1}} \leq \delta
\]
for each $n \in \omega$. Let $y_n := x_{n, 0}$ for each $n \in \omega$. We claim $\sequenceOf{y_n}:{n \in \omega}$ $\epsilon$-shadows $\sequenceOf{\p{x_{n, k}}_{k \in \omega}}:{n \in \omega}$. That is to say, we claim
\[
\sum_{k = 0}^\infinity \Fraction d\of{x_{n, k}, x_{n+k, 0}} / {2^{k+1}} = \sum_{k = 0}^\infinity \Fraction d\of{x_{n, k}, y_{n + k}} / {2^{k+1}} < \epsilon
\]
for each $n \in \omega$. First, we observe using the triangle inequality
\[
d\of{x_{n, k}, x_{n+k, 0}} \leq \sum_{j = 0}^{k - 1} d\of{x_{n + j, k - j}, x_{n + j + 1, k - j - 1}}
\]
for each $n, k \in \omega$. Hence, for each $n \in \omega$,
\begin{align*}
&& \sum_{k = 0}^\infinity \Fraction d\of{x_{n, k}, x_{n+k, 0}} / {2^{k+1}} &\leq \sum_{k = 0}^\infinity \sum_{j = 0}^{k - 1} \Fraction  d\of{x_{n + j, k - j}, x_{n + j + 1, k - j - 1}} /  {2^{k+1}} && \\
&& &= \sum_{j = 0}^\infinity \sum_{k = j + 1}^\infinity \Fraction  d\of{x_{n + j, k - j}, x_{n + j + 1, k - j - 1}} /  {2^{k+1}}  && \\
&& &= \sum_{j = 0}^\infinity \Fraction 1 / {2^{j + 1}} \sum_{k = j + 1}^\infinity \Fraction  d\of{x_{n + j, k - j}, x_{n + j + 1, k - j - 1}} /  {2^{k - j}} && \\
&& &= \sum_{j = 0}^\infinity \Fraction 1 / {2^{j + 1}} \sum_{m = 0}^\infinity \Fraction  d\of{x_{n + j, m + 1}, x_{n + j + 1, m}} /  {2^{m+1}}  && \\
&& &\leq \sum_{j = 0}^\infinity \Fraction \delta / {2^{j+1}} && \\
&& &= \delta && \\
&& &< \epsilon, &&
\end{align*}
establishing our claim. Thus, $\p{X_G^+, \sigma_G^+}$ has the shadowing property. 
\end{example}

\begin{example}
Let $\p{X, G}$ be the CR-dynamical system for $\p{5}$ in Proposition~\ref{prop:id-shadowing-diagonal-totally_disconnected-counterexamples}. That is, $X$ is the Cantor set, and $G = \Delta_X \union \setOf{\p{a_n, a_{n+1}}}:{n \in \omega} \union \setOf{\p{b_n, b_{n+1}}}:{n \in \integers}$, where $\sequenceOf{a_n}:{n \in \omega}$ and $\sequenceOf{b_n}:{n \in \integers}$ are sequences in $X$ with the properties,
\begin{itemize}
    \item for each $\p{n, m} \in \omega \times \integers$, $a_n < a_{n+1}$ and $b_m < b_{m+1}$;
    \item $a_0 = 0$, $\lim_{n \to +\infinity} a_n = \Fraction 2 / 9 = \lim_{n\to -\infinity} b_n$ and $\lim_{n \to +\infinity} b_n = \Fraction 1 / 3$. 
\end{itemize}
Notice $G$ contains the graph of the identity map on $X$, which is an isometry. By Theorem~\ref{theorem:graph-contains-isometry-then-X-totally-disconnected-iff-Mahavier-totally-disconnected}, $X_G^+$ is totally disconnected. We show $\p{X_G^+, \sigma_G^+}$ does not have the shadowing property. This tells us the implication from $\p{4}$ to $\p{2}$ in Theorem~\ref{thm:isometry-mahavier} does not generalise.

Now, let $\epsilon = \Fraction 1 / {54}$, and $\delta > 0$ be arbitrary. There exists $\p{n, m} \in \omega \times \integers$ such that $\sequence{a_0, \ldots, a_n, b_m, b_{m+1}, \ldots}$ is a $\p{\delta, 2}$-pseudo-orbit in $\p{X, G}$.  It follows 
\[
\sequence{\p{a_0, a_0, \ldots}, \ldots, \p{a_n, a_n, \ldots}, \p{b_m, b_m, \ldots}, \p{b_{m+1}, b_{m+1}, \ldots}, \ldots}
