\begin{corollary}
Let $\p{X, G}$ be a CR-dynamical system such that $\Delta_X \subseteq G^n$ for some positive integer $n$. Then,  $\p{X, G}$ has the $\p{2, 1}$-shadowing property if, and only if, $\p{X, G^{-1}}$ has the $\p{2, 1}$-shadowing property. 
\end{corollary}
\begin{proof}
Since $\Delta_X \subseteq G^n$, $\Delta_X \subseteq G^{-n}$. Consequently, it suffices to prove the forward direction. To this end, suppose $\p{X, G}$ has the $\p{2, 1}$-shadowing property. By Corollary~\ref{cor:21-implies-function}, there exists a continuous self-map $f$ on $X$ such that $\Graph{f} = G$ and $f^n = \text{id}_X$. Furthermore, this means $f$ is a bijection, and so $f^{-1}$ is well-defined. By Theorem~\ref{thm:diagonal-totally-disconnected}, $X$ is totally disconnected and consequently $\p{X, G^{-1}}$ has the $\p{1, 2}$-shadowing property.  As $G^{-1} = \Graph{f^{-1}}$, it follows $\p{X, G^{-1}}$ has the $\p{2, 1}$-shadowing property. 
\end{proof}

\begin{example}\label{ex:G-inverse-11}
Let $\p{X, G}$ be a CR-dynamical system, where $X = [0, 1]$ and $G = \p{X \times \set{1}} \union \Delta_X$ (shown in Figure~\ref{fig:G-inverse-11}). By Proposition~\ref{prop:diagonal-plus-horizontal}, $\p{X, G}$ has the $\p{1, 1}$-shadowing property. However, $\p{X, G^{-1}}$ does not have the $\p{1, 2}$-shadowing property. 
\end{example}

\begin{question}
Let $\p{X, G}$ be a CR-dynamical system such that $\Delta_X \subseteq G$. If $\p{X, G}$ has the $\p{2, 2}$-shadowing property, must $\p{X, G^{-1}}$ have the $\p{1, 2}$ or $\p{2, 2}$-shadowing property? 
\end{question}

\begin{corollary}
Let $\p{X, G}$ be a CR-dynamical system such that there exists an isometry $f : X \to X$ with $\Graph{f} \subseteq G$. Then, $\p{X, G}$ has the $\p{2, 1}$-shadowing property if, and only if, $\p{X, G^{-1}}$ has the $\p{2, 1}$-shadowing property. 
\end{corollary}
\begin{proof}
Since $\Graph{f} \subseteq G$ where $f : X \to X$ is an isometry, it follows $\Graph{f^{-1}} \subseteq G^{-1}$ where $f^{-1} : X \to X$ is an isometry.  Consequently, it suffices to prove the forward direction. To this end, suppose $\p{X, G}$ has the $\p{2, 1}$-shadowing property. By Proposition~\ref{prop:21-isometry-implies-single-val}, $G = \Graph{f}$. Since $\p{X, G}$ has the $\p{2, 1}$-shadowing property, $\p{X, f}$ has the shadowing property by Proposition~\ref{prop:topological-relation-correspondence}. By Theorem~\ref{thm:isometry-mahavier}, $X$ is totally disconnected and  $\p{X, f^{-1}}$ has the shadowing property. By Proposition~\ref{prop:topological-relation-correspondence}, $\p{X, G^{-1}}$ has the $\p{2, 1}$-shadowing property. 
\end{proof}

