\begin{theorem}\label{P4_thrm2}
    Consider the system of fractional differential equations \eqref{P4_problem} subject to the conditions \eqref{P4_condition_case2}. Suppose that the functions $D^{\alpha_1+1} \y(\x)$ and $D^{\alpha_2+1} \z(\x) $ are continuous functions on the interval $[0,1].$ Additionally, assume that there exist positive constants $\delta_1$ and $\delta_2$ such that $ |D^{\alpha_1+1} \y(\x) | \leq \delta_1, ~| D^{\alpha_2+1} \z(\x) | \leq \delta_2$ for all $\x \in [0,1]$ and $k$ be any positive real value. Then, for $\alpha_1 = \alpha_2 =\alpha ,$ the error $E_{M1}$ and $E_{M2}$ in the solutions $\y(\x)$ and $\z(\x)$ respectively satisfy the bounds,
\begin{equation*}
    \| E_{M1} \|_2 \leq  \left( \frac{d_1 k}{2(2^\alpha -1)} \right) \left( \frac{1}{2^{J+1}} \right)^\alpha,
\end{equation*}
\begin{equation*}
    \| E_{M2} \|_2 \leq  \left( \frac{d_2 k}{2(2^\alpha -1)} \right) \left( \frac{1}{2^{J+1}} \right)^\alpha.
\end{equation*}
