    \frac{2 \mu_3 \eta_1 \left(1-\frac{d}{c} \right) \left(\nu_1 -\frac{d}{c} \right) \left(\frac{b^2}{a^2} -\frac{b}{a} + \frac{1}{3} \right)}{\left[ \left(1-\frac{b}{a} \right) \left(1-\frac{d}{c} \right) -\mu_3 \mu_4 \eta_1 \eta_2 \left(\nu_1-\frac{d}{c} \right) \left(\nu_2 - \frac{b}{a}\right) \right]^2} \left\{ \left(\mu_3 \mu_4 \eta_1 \eta_2 +1 \right) \delta_1 \delta_2 - \mu_4 \eta_2 \delta_1^2 - \mu_3 \eta_1 \delta_2^2 \right\}  \right. \\&  \left. + \frac{2 \left(\frac{1}{2} -\frac{b}{a} \right)}{ \left[ \left(1-\frac{b}{a} \right) \left(1-\frac{d}{c} \right) -\mu_3 \mu_4 \eta_1 \eta_2 \left(\nu_1-\frac{d}{c} \right) \left(\nu_2 - \frac{b}{a} \right) \right]} \left\{ \delta_1 \delta_2 \left\{ \left(1-\frac{d}{c} \right) \mu_3 \eta_1 - \mu_3 \eta_1 \left(\nu_1 -\frac{d}{c} \right) \right\} \right. \right.\\&  \left. \left. + \delta_1^2 \{ \mu_3 \mu_4 \eta_1 \eta_2 (\nu_1-\frac{d}{c}) - (1- \frac{d}{c}) \} \right\} \right]^{\left(1/2 \right)}.
