    \begin{split}
        d_2 &=\left[  \delta_2^2 + \frac{\mu_4^2 \eta_2^2 \left(\nu_2 -\frac{b}{a} \right)^2 \left(\frac{d^2}{c^2} -\frac{d}{c} + \frac{1}{3} \right)}{ \left[ \left(1-\frac{b}{a} \right) \left(1-\frac{d}{c} \right) -\mu_3 \mu_4 \eta_1 \eta_2 \left(\nu_1-\frac{d}{c} \right) \left(\nu_2 - \frac{b}{a} \right) \right]^2} \left\{ \mu_3^2 \eta_2 \delta_2^2 + \delta_1^2 - 2 \mu_3 \eta_1 \delta_1 \delta_2 \right\} \right. \\ &
        \hspace{0.5cm} \left.  + \frac{ \left(1-\frac{b}{a} \right)^2 \left(\frac{d^2}{c^2} -\frac{d}{c} + \frac{1}{3} \right) }{ \left[ \left(1-\frac{b}{a} \right) \left(1-\frac{d}{c} \right) -\mu_3 \mu_4 \eta_1 \eta_2 \left(\nu_1-\frac{d}{c} \right) \left(\nu_2 - \frac{b}{a} \right) \right]^2}  \left\{ \mu_4^2 \eta_2^2 \delta_1^2 + \delta_2^2 - 2 \mu_4 \eta_2 \delta_1 \delta_2 \right\}  \right. \\ &
          \hspace{1cm} \left.  + \frac{2 \mu_4 \eta_2 \left(1-\frac{b}{a} \right) \left(\nu_2 -\frac{b}{a} \right) \left(\frac{d^2}{c^2} -\frac{d}{c} + \frac{1}{3} \right)  }{ \left[ \left(1-\frac{b}{a} \right) \left(1-\frac{d}{c} \right) -\mu_3 \mu_4 \eta_1 \eta_2 \left(\nu_1-\frac{d}{c} \right) \left(\nu_2 - \frac{b}{a} \right) \right]^2} \left\{ \left(\mu_3 \mu_4 \eta_1 \eta_2 +1 \right) \delta_1 \delta_2 - \mu_4 \eta_2 \delta_1^2 - \mu_3 \eta_1 \delta_2^2 \right\} \right. \\ &
          \hspace{1cm} \left.  + \frac{2 \left(\frac{1}{2}- \frac{d}{c} \right) \left\{ \mu_4 \eta_2 \left(\nu_2 -\frac{b}{a} \right) \left[\mu_3 \eta_1 \delta_2^2 - \delta_1 \delta_2 \right] + \left(1-\frac{b}{a} \right) \left[\mu_4 \eta_2 \delta_1 \delta_2 - \delta_2^2 \right] \right\} }{ \left[ \left(1-\frac{b}{a} \right) \left(1-\frac{d}{c} \right) -\mu_3 \mu_4 \eta_1 \eta_2 \left(\nu_1-\frac{d}{c} \right) \left(\nu_2 - \frac{b}{a}\right) \right]} \right]^{\left(1/2 \right)}.
    \end{split}
\end{equation*}
\end{theorem}
\begin{proof} The proof is similar, as done in above Theorem \ref{P4_thrm1}.
\end{proof}
\section{Numerical Experiments}\label{P4_Examples}
In this section, we present numerical experiments to validate the proposed method by considering five test problems of the form \eqref{P4_problem}. Additionally, we introduce stability analysis and maximum residual error, which will be utilized throughout this section. All the experiments are conducted using \textit{Mathematica 11.3} on a system with a 64-bit Intel Core i7 CPU and 16GB of RAM.\\

\noindent \textbf{Stability analysis:-} To ensure the stability of the proposed algorithm, it is essential to evaluate the condition number of the resulting nonlinear system of algebraic equations. These equations arise from coupled fractional differential equations after applying the proposed method. The algorithm is considered stable if the condition number of the coefficient matrix remains bounded \cite{SUN_2021106732}. In this context, the coefficient matrix is constructed using Haar functions, the unknown variables correspond to wavelet coefficients, and the right-hand side consists of known values. A commonly used criterion for numerical stability \cite{narendra2025} states that the method remains stable if the norm of the inverse of the coefficient matrix exists and is bounded by a fixed constant. This guarantees that small variations in input do not cause significant errors in the solution.\\

\noindent \textbf{Maximum residual error:} For Lane-Emden-type equations, where exact solutions are unavailable, the maximum residual error is defined as:
$$E = \max_{\x_i \in [0, 1]} r(x_i), \quad r(x_i) = \sqrt{r_1(\x_i)^2 + r_2(\x_i)^2},$$
where $r(x_i)$ denotes the total residual error at a given point $x_i$. The component residual errors $r_1(\x)$ and $r_2(\x)$ for the system are defined as follows:
\begin{align*}
    r_1(\x) &= \left|\D^{\alpha_1} \y^J(\x) + \frac{k_1}{\x^{\gamma_1}} \D^{\beta_1} \y^J(\x) -f_1(\x,\y^J,\z^J) \right|, \\
    r_2(\x) &= \left|\D^{\alpha_2} \z^J(\x) + \frac{k_2}{\x^{\gamma_2}} \D^{\beta_2} \z^J(\x) -f_2(\x,\y^J,\z^J) \right|,
\end{align*}
where, $\y^J(\x)$ and $\z^J(\x)$ denote the numerical solutions at the $J^{th}$ resolution level. 

\subsection{Fractional Initial Value Problem(FrIVP)}\label{P4_IVP}
We consider the following FrIVP:
\begin{equation}
\begin{aligned}
& \D^{\alpha_1} \y(\x) +\frac{1}{\x} \D^{\beta_1} \y(\x) = \z^3 \left(\y^2+1 \right),\\
& \D^{\alpha_2} \z(\x) + \frac{3}{\x} \D^{\beta_2} (\z (\x))= -\z^5 \left(\y^2+3 \right),\\
& \y(0)=1, ~\y'(0)=0, \quad \z(0)=1, ~\z'(0)=0.
\end{aligned}
\end{equation}
\begin{itemize}
    \item[\textbf{(a)} ]We present our findings systematically through figures and tables. Figure \ref{P4_IVP_fig} illustrates the Haar solution and residual error, arranged column-wise for different values $\alpha_1, ~\beta_1, ~\alpha_2, ~\beta_2.$ The first column displays the Haar solutions $\y(\x), \z(\x)$ along with the residual errors in $r_1(\x)$ and $r_2(\x)$ for varying values of $J$ at $\alpha_1=1.58, ~\beta_1=0.58,~ \alpha_2=1.59, ~ \beta_2=0.59$ respectively.
    \item[\textbf{(b)}]The second column presents the same components for $\alpha_1=1.7,~ \beta_1=0.7,~ \alpha_2=1.71, ~\beta_2=0.71,$ while the third column follows with solutions and residual errors at $\alpha_1=1.85,~ \beta_1=0.85,~ \alpha_2=1.86,~ \beta_2=0.86.$ The fourth column showcases results for $\alpha_1=1.98,~ \beta_1=0.98,~ \alpha_2=1.99,~ \beta_2=0.99.$
    \item[\textbf{(c)} ]Finally, the last column presents the Haar solutions $\y(\x), \z(\x)$ alongside the absolute error in $\y(\x)$ and $\z(\x)$ for various values of $J$ at $\alpha_1=2,\; \beta_1=1,\; \alpha_2=2,\; \beta_2=1.$ At $\alpha_1 = \alpha_2 =2,~ \beta_1 = \beta_2=1$, the proposed problem reduces to the classical coupled Lane-Emden equations considered by Narendra et al. \cite{kumar2023hybrid}.
    \item[\textbf{(d)} ]In Table \ref{P4_table1_IVP}, we present the total residual error of problem \ref{P4_IVP} for  $J=3, \; 4,\; 5$ at  $\alpha_1=1.58,\; 1.7, ~\alpha_2=1.59, \;1.71 , ~ \beta_1=0.58,\; 0.7,~ \beta_2=0.59,~ 0.71.$ Similarly, Table \ref{P4_table2_IVP} displays the total residual error for  $J=3,\; 4,\; 5$ at  $\alpha_1=1.85,\; 1.98, ~\alpha_2=1.86, \; 1.99 , ~\beta_1=0.85, \; 0.98, ~\beta_2=0.86, \; 0.99.$
    \item[\textbf{(e)} ]The tables and plots demonstrate that the residual error decreases as $J$ increases for the given values of parameters $\alpha_1,\; \beta_1, \; \alpha_2,\; \beta_2,$ A similar trend is observed when $J$ remains fixed while varying $\alpha_1,\; \beta_1, \; \alpha_2, \; \beta_2,$ which validates the accuracy of the proposed method. The residual error shown in Figure \ref{P4_IVP_fig} serves as a measure of the precision of our method. These results demonstrate the effectiveness of the fractional Haar wavelet collocation method in tackling the problem.
    \item[\textbf{(f)} ]We also observe that the condition number of the coefficient matrix remains bounded across all considered cases. Additionally, the norm of the inverse of this matrix is bounded as well. Hence, we conclude that the proposed method demonstrates numerical stability.
    \item[\textbf{(g)} ]Despite changes in the initial solution, the final solution remains unchanged across all cases of $(\alpha_1, ~\beta_1, ~\alpha_2, ~\beta_2)$. This consistency confirms the stability of the proposed method.
    \end{itemize}
