\section{Borel summation}\label{sec:padeborel}
In this section, we review the background of Borel summation and some known facts about it. We also discuss our new proposals on the singularities in the Borel plane and the corresponding discontinuities partially in \autoref{padeborelsol} and also in \autoref{sec:borel4d} and \autoref{sec:disc}.
\subsection{All-orders WKB}
\label{allorder}
The all-orders WKB analysis of \begin{equation}
\label{maindex2}
\left(-\epsilon^2\partial_z^2+P(z,\epsilon)\right)\psi(z)=0,
\end{equation}
 uses the following ansatz for a solution of 
\eqref{maindex2}:
\begin{equation}
\label{ansatzo}
\psi(z)=\exp\left(\frac{1}{\epsilon}\int_{z_0}^zY(z,\epsilon) \de z\right).
\end{equation}
Plugging in \eqref{maindex2}, $Y(x,\epsilon)$ satisfies the Ricatti equation
\begin{equation}\label{ricattix}
-\left(Y(z,\epsilon)\right)^2-\epsilon {\frac{\rd}{\rd z}} Y(z,\epsilon)+P(z,\epsilon)=0\, .
\end{equation}
$Y(z,\epsilon)$ can be solved formally as a power series in $\epsilon$
\begin{equation}\label{wkbY}
Y(z,\epsilon) = \sum_{n=0}^\infty Y^{n}(z)\epsilon^{n}\, ,
\end{equation}
where $Y^{0}=\pm\sqrt{P(z,0)}$.
We denote the two choices of sign by $Y^{0,(1)}$ and $Y^{0,(2)}$.
Note that the choice of $i=1,2,$ in $Y^{0,(i)}$ determine all the higher-order terms, so we denote \eqref{ansatzo} by the same label 
\begin{equation}\label{psidefori} \psi^{(i)}(z)=\exp\left(\frac{1}{\epsilon}\int_{z_0}^zY^{(i)}(z,\epsilon) \de z\right),
\end{equation}
with the relation
\begin{equation}\label{symsol}
\psi^{(1)}(z,\epsilon)=-\ri \psi^{(2)}(z,-\epsilon).
\end{equation}
The label $i$ can be identified with different sheets of $\Sigma$. In this paper we mainly study the sheet $i=1$. The point $z_0$ in \eqref{psidefori} is actually subtle. In this paper, we choose the normalization with $z_0=b_0$, where $b_0$ is a branch point of the projection map $\Sigma\xrightarrow[]{2:1} C$. We define
\begin{equation}\label{Upsilonallorder}
I^{(i)}(z,\epsilon)=\sum_{n=0}^\infty I^{n,(i)}(z)\epsilon^n=\sum_{n=0}^\infty \text{Reg}\left(\int_{b_0}^z Y^{n,(i)}(z)\rd z\right)\epsilon^{n}=\sum_{n=0}^\infty(\frac12\int\limits_{-\gamma_{ji}} Y^{n,(i)})\epsilon^n,
\end{equation}
where $\text{Reg}$ means the regularization of the integral, which is needed because $\int_{b_0}^z Y^{n,(i)}(z)\rd z$ for $n>1$ diverges at $b_0$ and $\gamma_{ji}\in H_1(\overline{\Sigma},\{z^{(j)},z^{(i)}\},\mathbb{Z})$ is the charge of BPS soliton. 
