\subsection{Discontinuities of Borel summation}\label{sec:disc}
There are 2 types of discontinuities corresponding to the two types of singularities 
described in \autoref{padeborelsol} and \autoref{sec:borel4d} respectively.
They are conveniently described by 
\begin{equation}\label{eqn:defdisc1}
{\rm disc}(\frac{\Upsilon^{(i)}_{\rm red}}{\epsilon})(z,\epsilon)= s_+(\frac{I^{(i)}_{\rm red}}{\epsilon})(z,\epsilon)-s_-(\frac{I^{(i)}_{\rm red}}{\epsilon})(z,\epsilon),
\end{equation}
\begin{equation}\label{eqn:defdisc2}
{\rm disc}(\Psi^{(i)}_{\rm red})(z,\epsilon)= \E^{s_+(\frac{I^{(i)}_{\rm red}}{\epsilon})}(z,\epsilon)-\E^{s_-(\frac{I^{(i)}_{\rm red}}{\epsilon})}(z,\epsilon).
\end{equation}
where we use the lateral Borel summation \eqref{sdeflat}. 



\subsubsection{The discontinuity corresponding to \texorpdfstring{$-Z_{\gamma_{ji_n}}$}{-Z[gammajin]}}

\label{disccomp}

We propose that the discontinuity of $\Psi^{(i)}_{\rm red}(z,\epsilon)$ corresponding to a minus BPS soliton central charge $-Z_{\gamma_{ji_n}}$ supported at $z$ is

\begin{equation}\label{sec2:jumpsol2}
\boxed{
\begin{aligned} 
&{\rm disc}(\Psi^{(i)}_{\rm red})(z,\epsilon)=\mu(\gamma_{{ji}_n})\Psi^{(j)}_{\rm red}(z,\epsilon)\e^{\frac{Z_{\gamma_{ji_n}}}{\epsilon }+\frac{1}{\pi\ri}\sum\limits_{\gamma>0}\langle\gamma_n,\gamma\rangle\Omega(\gamma)\mathcal{I}_{\gamma}(\epsilon)},\\
&\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\text{at }\arg(\epsilon)=\arg(-Z_{\gamma_{{ji}_n}}(z)),
\end{aligned}}
 \end{equation}
 where 
 $\mu({\gamma_{ji_n}})$ is the BPS soliton degeneracy,  $\Omega(\gamma)$ is the 4d BPS degeneracy (also known as 4d BPS index), $\langle-,-\rangle$ is the intersection number,
 \begin{equation}\label{sec2:gamma4d}
 \gamma_n=\gamma_{\gamma_{ji_n}}-\gamma_{\gamma_{ji_1}}
 \end{equation} is obtained by concatenation of the two soliton charges,
\begin{equation}
\label{Idefm} \mathcal{I}_{\gamma}(\epsilon)=\int_{\ell_\gamma}d \epsilon' \frac{\epsilon}{(\epsilon')^2- \epsilon^2}
\log(1 - \sigma(\gamma)\cX_{\gamma}(\epsilon'))\, ,
\end{equation}
\begin{equation}\label{deflgamma}
\ell_{\gamma}=\{\epsilon':\frac{Z_{\gamma}}{\epsilon'}\in\mathbb{R}_-\},
\end{equation}
and $\sigma(\gamma)$ is quadratic refinement.
Beyond second-order ODE \eqref{maindex2}, \eqref{sec2:jumpsol2} should also apply to solutions of generic differential equations within the framework of the supersymmetric theory/ differential equation correspondence.


In the simplest case when $n=1$, the discontinuity  
\begin{equation}\label{sec2:jumpsol}
 {\rm disc}(\Psi^{(i)}_{\rm red})(z,\epsilon)=\mu({\gamma_{21_1}})\Psi^{(j)}_{\rm red}(z,\epsilon)\e^{\frac{Z_{{\gamma_{ji_1}}}}{\epsilon }}
 \end{equation}
at $\arg(\epsilon)=\arg(-Z_{{\gamma_{ji_1}}})$ has been proven for $\arg(\epsilon)\neq\arg(Z_{\gamma})$, $\forall \gamma$ and $\mu({\gamma_{ji_1}})=1$ \cite{Voros1983, 10.1007/978-4-431-68170-0_1,Iwaki:2014vad}.

To get \eqref{sec2:jumpsol2} for generic $n$, we pick another normalization $\Psi^{(i)}_{{\rm red},n}(z,\epsilon)$ regularized by $-{\gamma_{ji_n}}$. Then, according to \eqref{sec2:jumpsol} its discontinuity corresponding to $-Z_{\gamma_{ji_n}}$ is simplified to
\begin{equation}\label{dispsip}
 {\rm disc}(\Psi^{(i)}_{{\rm red},n})(z,\epsilon)=\mu({\gamma_{ji_n}})\Psi^{(j)}_{{\rm red},n}(z,\epsilon)\e^{\frac{Z_{{\gamma_{ji_n}}}}{\epsilon }}.
 \end{equation}
 We also know that $\Psi^{(i)}_{{\rm red},n}(z,\epsilon)$ and $\Psi^{(i)}_{\rm red}(z,\epsilon)$ are related by
 \begin{equation}\label{rationnorm}
 \frac{\Psi^{(i)}_{\rm red}(z,\epsilon)}{\Psi^{(i)}_{{\rm red},i}(z,\epsilon)}=(\cX_{\gamma_n}(\epsilon))^{\frac12}\e^{-\frac{ Z_{\gamma_n}}{2\epsilon}},
 \end{equation}
 where 
 \begin{equation}\label{QPdef} 
 \cX_{\gamma_n}(\epsilon)=\exp\Bigg(s\Big(\frac{1}{\epsilon}\sum_{m=0}^\infty\oint\limits_{\gamma_n} Y_m(z) \de z\,\epsilon^m\Big)(\epsilon)\Bigg)
 \end{equation}
is the quantum period for the charge $\gamma_n$. Furthermore, we use an equivalent exact WKB method to the Borel summation -- the conjectured GMN closed TBA to  substitute $\cX_{\gamma_n}(\epsilon)$ in \eqref{rationnorm} by
\begin{equation} \label{sec2:closetbe}
\log\cX_{\gamma_n}(\epsilon) = \frac{Z_{\gamma_n}}{\epsilon} +
\frac{1}{\pi \ri}\sum_{\gamma>0} \Omega(\gamma) \langle\gamma_n,\gamma\rangle
\mathcal{I}_{\gamma}(\epsilon).
\end{equation}
In total, \eqref{sec2:jumpsol2} is obtained by combining \eqref{dispsip}, \eqref{rationnorm} and \eqref{sec2:closetbe}.

\subsubsection{The discontinuity for \texorpdfstring{$-Z_{\gamma}$}{-Z_gamma}}

For the discontinuity corresponding to a 4d BPS state at $\arg(\epsilon)=\arg(-Z_{\gamma})$, our proposal is
\begin{equation}\label{sec2:jumppi} \boxed{
{\rm disc}(\frac{\Upsilon_{\rm red}^{(i)}}{\epsilon})(z,\epsilon)= \frac{\langle-\gamma_{{ji_1}},\gamma\rangle\Omega(\gamma)}{2}\log(1-\sigma(\gamma)\cX_{\gamma}(\epsilon)), \quad\quad\text{at }\arg(\epsilon)=\arg(-Z_{\gamma}).}
\end{equation}
