\subsection{Open TBA equations}

Using the discontinuities of the solution $\Psi^{(1)}_{\rm red}$ -- \eqref{jumppi},\eqref{jumpni} and \eqref{weberjumpsol}, together with the leading asymptotic $\Psi^{(1)}_{\rm red}\sim\frac{1}{(-\sqrt{P(z,0)})^{\frac12}}$, $\Psi^{(1)}_{\rm red}$ at $z\in\circled{1}$ satisfies an open TBA equation  
\begin{align}\label{Weber1soltba}
\nonumber\Psi^{(1)}_{\rm red}(z,\epsilon)=&\E^{-\frac{1}{2\pi\ri}\mathcal{I}_{\gamma_f}(\epsilon)}\Bigg(\frac{1}{\left(-\sqrt{P(z,0)}\right)^{\frac{1}{2}}}\\
&+\frac{1}{2\pi}\int\limits_{\ell_{\gamma_{21_+}}}\frac{\epsilon}{\epsilon'}\frac{1}{\epsilon'-\epsilon}\Psi^{(1)}_{\rm red}(z,-\epsilon')\mathbb{X}_{\gamma_{21_+}}(z,\epsilon')\rd\epsilon'\Bigg),
 \end{align}
as proposed in \eqref{natTBA}. Here we define
\begin{equation}\label{mathfrakX}
\mathbb{X}_{\gamma_{21_\pm}}(z,\epsilon)=\e^{\frac{Z_{\gamma_{21_\pm}}}{\epsilon }+\frac1 {2\pi\ri}\mathcal{I}_{\gamma_f}(\epsilon)}
\end{equation}
and $\mathcal{I}_{\gamma}(\epsilon)$ is defined in \eqref{Idefm}.
Using the relation \eqref{relateTBAborel} which in this example is
\begin{equation}\label{GMNwkbnorm}
g_1(z,\epsilon)=N_{\rm GMN}(\epsilon)\Psi^{(1)}_{\rm red}(z,\epsilon),
\end{equation}
where 
\begin{equation}\label{nweber}
N_{\rm GMN}(\epsilon)=\E^{\frac{1}{2\pi\ri}\mathcal{I}_{\gamma_f}(\epsilon)},
\end{equation}
$g_1(z,\epsilon)$ satisfies the GMN open TBA equation 
\begin{align}\label{weberGMN}
g_1(z,\epsilon)=&\frac{1}{\left(-\sqrt{P(z,0)}\right)^{\frac{1}{2}}}+\frac{1}{2\pi}\int\limits_{\ell_{\gamma_{21_+}}}\frac{\epsilon}{\epsilon'}\frac{1}{\epsilon'-\epsilon} g_1(z,-\epsilon')X_{\gamma_{21_+}}(z,\epsilon')\rd\epsilon',
 \end{align}
 where 
\begin{equation}
X_{\gamma_{21_\pm}}(z,\epsilon)=\e^{\frac{Z_{\gamma_{21_\pm}}}{\epsilon }+\frac1 {\pi\ri}\mathcal{I}_{\gamma_f}(\epsilon)}.
\end{equation}


Similarly, when $z\in\circled{2}$ we have
\begin{align}\label{Weber2soltba}
\nonumber\Psi^{(1)}_{\rm red}(z,\epsilon)=&\E^{-\frac{1}{2\pi\ri}\mathcal{I}_{\gamma_f}(\epsilon)}\Bigg(\frac{1}{\left(-\sqrt{P(z,0)}\right)^{\frac{1}{2}}}\\
&+\frac{1}{2\pi}\int\limits_{\ell_{\gamma_{21_+}}}\frac{\epsilon}{\epsilon'}\frac{1}{\epsilon'-\epsilon}\Psi^{(1)}_{\rm red}(z,-\epsilon')\mathbb{X}_{\gamma_{21_+}}(z,\epsilon')\rd\epsilon'\\
&+\frac{1}{2\pi}\int\limits_{\ell_{\gamma_{21_-}}}\frac{\epsilon}{\epsilon'}\frac{1}{\epsilon'-\epsilon}\Psi^{(1)}_{\rm red}(z,-\epsilon')\mathbb{X}_{\gamma_{21_-}}(z,\epsilon')\rd\epsilon'\Bigg),
 \end{align}
 Or using \eqref{GMNwkbnorm}, the corresponding GMN open TBA reads
 \begin{align}\label{WeberGMN2}
\nonumber g_1(z,\epsilon)=&\frac{1}{\left(-\sqrt{P(z,0)}\right)^{\frac{1}{2}}}+\frac{1}{2\pi}\int\limits_{\ell_{\gamma_{21_+}}}\frac{\epsilon}{\epsilon'}\frac{1}{\epsilon'-\epsilon}g_1(z,-\epsilon')X_{\gamma_{21_+}}(z,\epsilon')\rd\epsilon'\\
&+\frac{1}{2\pi}\int\limits_{\ell_{\gamma_{21_-}}}\frac{\epsilon}{\epsilon'}\frac{1}{\epsilon'-\epsilon} g_1(z,-\epsilon')X_{\gamma_{21_-}}(z,\epsilon')\rd\epsilon'\Bigg).
 \end{align}


We compare the results of open TBA with the ones of Pad\'{e}-Borel summation at $z=\e^{\frac{\pi\ri}{30}}\in\circled{1}$ in \autoref{openTBA3} using \eqref{Weber1soltba} and at $z=2\ri \in\circled{2}$ in \autoref{openTBA2i} using \eqref{WeberGMN2}. We see that both TBA equations of $\Psi^{(1)}_{\rm red}(z,\epsilon)$ and $g_1(z,\epsilon)$ work and in practice, it’s easier to work with the GMN open TBA. So in future calculations, we will only use the GMN open TBA.
