\begin{align}
\label{Zgammad}Z_{\gamma_{d}}=&8 \sqrt{2 \Lambda - u}\, \textbf{E}\left(\frac{4 \Lambda }{2 \Lambda - u}\right)+8 \ri \sqrt{2 \Lambda - u} \left(\textbf{K}\left(\frac{- u-2 \Lambda }{2
   \Lambda - u}\right)-\textbf{E}\left(\frac{- u-2 \Lambda}{2 \Lambda - u}\right)\right),\\
\label{Zgammam}Z_{\gamma_{m}}=&8 \ri \sqrt{2 \Lambda - u} \left(\textbf{K}\left(\frac{- u-2 \Lambda }{2 \Lambda - u}\right)-\textbf{E}\left(\frac{- u-2 \Lambda }{2 \Lambda -
   u}\right)\right),
\end{align}
where \textbf{E} and \textbf{K} are the complete elliptic integrals and the corresponding BPS indices are
\begin{equation}
\Omega(\pm \gamma_m)=\Omega(\pm \gamma_d)=1.
\end{equation}
