As proposed in \autoref{padeborelsol} and \autoref{sec:borel4d}, we find that the singularities on the Borel plane are at:
\begin{itemize}
\item minus 4d BPS state central charge 
\begin{equation}-Z_{\pm\gamma_d}=\eqref{Zgammad}\sim \mp 6.7777,\end{equation}
and
\begin{equation}-Z_{\pm\gamma_m}=\eqref{Zgammam}\sim \pm 6.7777\ri.\end{equation}
\item minus BPS soliton central charge
\begin{equation}
- Z_{\gamma_{21_1}}=4 \sqrt{\frac{1}{z^3}} z \, _2F_1\left(-\frac{1}{2},-\frac{1}{4};\frac{3}{4};-z^2\right)-\frac{(1-\ri) \sqrt{2 \pi } \Gamma \left(\frac{3}{4}\right)}{\Gamma
   \left(\frac{5}{4}\right)},
\end{equation}
and
\begin{equation}
 -Z_{\gamma_{21_2}}=4 \sqrt{\frac{1}{z^3}+\frac{1}{z}} z \left(z^2+1\right) \, _2F_1\left(1,\frac{5}{4};\frac{3}{4};-z^2\right)-\frac{(1+\ri) \sqrt{2 \pi } \Gamma
   \left(\frac{3}{4}\right)}{\Gamma \left(\frac{5}{4}\right)}.
\end{equation}
\end{itemize}


We summarize  the numerically checked discontinuities  corresponding to BPS soliton central charges in \autoref{su2jump2d4d} and the discontinuities corresponding to 4d BPS state central charges in \autoref{su2jump4d}. They all match the proposals in \eqref{sec2:jumpsol2} and \eqref{sec2:jumppi}. 
We show an example of the numerical checks for \autoref{su2jump4d} in \autoref{disc4d} and some examples of the numerical checks for
\autoref{su2jump2d4d} in \autoref{disc2d4d}, where
 we use
 \begin{align}
\label{defjumpmn1}
 \bX_{\gamma_{21_1}}^{m,n}(z,\epsilon)&=\E^{\frac{Z_{\gamma_{21_1}}}{\epsilon}+m\frac{1}{\pi\ri}\mathcal{I}_{\gamma_m}(\epsilon)+n\frac{1}{\pi\ri}\mathcal{I}_{\gamma_d}(\epsilon)},\\
\label{defjumpmn2}\bX_{\gamma_{21_2}}^{m,n}(z,\epsilon)
&=\E^{\frac{Z_{\gamma_{21_2}}}{\epsilon}+m\frac{1}{\pi\ri}\mathcal{I}_{\gamma_m}(\epsilon)+n\frac{1}{\pi\ri}\mathcal{I}_{\gamma_d}(\epsilon)},
\end{align}
which are labeled by $m,n=\pm 1,\pm2$ and $\mathcal{I}_{\gamma}(\epsilon)$ is defined in \eqref{Idefm}. 




