\section{WKB series for \texorpdfstring{$\Upsilon_{\rm red}^{{\rm norm}_{\rm tot},(1)}(z,\epsilon)$}{Upsilon_red^(norm_tot,1)(z,epsilon)}}
\label{appen:obtainnormtot}
In general, we can use the exact WKB methods to obtain the quantum periods $\cX_{\gamma_d}(\epsilon)$ and $\cX_{\gamma_m}(\epsilon)$ and then substitute the $\cI_{\gamma_d}(\epsilon)$ and $\cI_{\gamma_m}(\epsilon)$ in \eqref{normfac1su2}. An example of the exact WKB methods is the GMN closed TBA equations in \autoref{sec:su2closetba}. However, in the $u=0$ case, there is a simpler procedure to obtain \eqref{normfac1su2} directly at the WKB series level using \eqref{rationnorm}.
More precisely, we define
\begin{equation}\label{su2f1}
f_1(\epsilon)\equiv\frac{1}{2\pi\ri}\int\limits_{\ell_{\gamma_d}}\frac{\epsilon}{\epsilon'^2-\epsilon^2}\log(1+\cX_{\gamma_d}(\epsilon'))=-\frac{1}{2\pi}\int\limits_{\ell_{\gamma_m}}\frac{\epsilon}{\epsilon'^2+\epsilon^2}\log(1+\cX_{\gamma_m}(\epsilon')).
\end{equation}
$f_1(\epsilon)$ can be obtained by
\begin{equation}
f_1(\epsilon)=\frac{1}{2}\Upsilon^{\text{norm}_1,(1)}_{\rm red}(z=b_0=-\ri,\epsilon).
\end{equation}
Thus
\begin{equation}
\begin{aligned}
&\quad\ \Upsilon_{\rm red}^{\text{norm}_{\rm tot},(1)}(z,\epsilon)\\
&=\Upsilon_{\rm red}^{\text{norm}_1,(1)}(z,\epsilon)-\frac{1}{2\pi\ri}\int\limits_{\ell_{\gamma_d}}\frac{\epsilon}{\epsilon'^2-\epsilon^2}\log(1+\cX_{\gamma_d}(\epsilon'))-\frac{1}{2\pi\ri}\int\limits_{\ell_{\gamma_m}}\frac{\epsilon}{\epsilon'^2-\epsilon^2}\log(1+\cX_{\gamma_m}(\epsilon'))\\
&=\Upsilon_{\rm red}^{\text{norm}_1,(1)}(z,\epsilon)-f_1(\epsilon)-f_1(\ri\epsilon).
\end{aligned}
\end{equation}
Similarly, $\Upsilon^{\text{norm}_{\tot},(1)}_{\rm red}$ can also be obtained as
\begin{align}\label{su2psitot}
\Upsilon_{\rm red}^{\text{norm}_{\rm tot},(1)}(z,\epsilon)=\Upsilon_{\rm red}^{\text{norm}_2,(1)}(z,\epsilon)+f_1(\epsilon)- f_1(\ri\epsilon).
\end{align}


