    \centering
    \includegraphics[width=0.7\linewidth]{exponential_LGAE.pdf}
    \caption{\label{fig:exponential}Hardware results after exponential LGAE, in the same setting as in Fig.~\ref{fig:hardware}. The mitigated results for $Jt=0.8$ have very large variance and are outside of the plotted window.}
