% \begin{equation}
%      \langle X \otimes \mathcal{O}\rangle=\lambda \Re \mathbb{E}_{\rm err}[\langle 0|e^{-iHt_-}\mathcal{O} e^{iHt_+}|0\rangle]\,,
% \end{equation}
% with $t_+=t_1+t_3-t_2+t_5-t_4+\dots$ and $t_-=t_2-t_1+t_4-t_3+\dots$ for the times $0<t_1<t_2<...<t$ at which $X$ errors occur. The occurrences of errors follow a Poisson process with rate $p_X$, whose average is denoted by $\mathbb{E}_{\rm err}$. When $\mathcal{O}=I$, we see then that
% \begin{equation}
