\begin{theorem}
	\label{thm:168puntofijo}
	Rules $168$ and $172$ always reach fixed points under update schedules different than the parallel.
\end{theorem}

\begin{proof}
Let $x$ be an arbitrary initial configuration. Since we know that $x=0^n$ and $x=1^n$ are fixed points, let us assume that $x$ can be written as
$$x=0^{a_1}1^{b_1}\dots0^{a_k}1^{b_k}$$
such that $a_1+b_1+\dots+a_k+b_k=n$.\\
Since $f_{r}(001)=f_{r}(100)=0$, for $r\in\{168,172\}$, groups of ones separated by two zeros cannot increase in size.\\
When there exists a $j\in\{1,\dots,k\}$ such that $a_j=1$, those $0$'s will disappear for rules $168$ and $172$ ($f_{168}(101)=f_{172}(101)=1$) if said $0$ is updated \textbf{before} its neighbours. However, if either of its neighbours updates \textbf{first}, then we have two consecutive $0$'s.\\
On the other hand, since $f_{r}(110)=0$ for $r\in\{168,172\}$, groups of $1$'s always decrease in size at the right side by at least one cell per iteration.\\
In every iteration, groups of ones will continue to decrease in size until only isolated $1$'s remain.\\
In the case of rule $168$ those ones will disappear(because $f_{168}(010)=0$) finally reaching $0^n$ which is a fixed point.\\
And for rule $172$ the isolated $1$'s will be preserved, since $f_{172}(010)=1$; with the fixed points being written as $x=0^{a_1}10^{a_2}\dots0^{a_{k-1}}0^{a_k}1$.\\
\end{proof}

\begin{theorem}
\label{thm:168paralelo}
	Rules $(40,\p)$, $(168,\p)$ and $(172,\p)$ can reach cycles $\mathcal{O}(n)$.
\end{theorem}
\begin{proof}
For rules $40$ and $168$\\
Starting with an initial configuration $x=(10)^{\frac{n}{2}-1}11$, $f(x)=(01)^{\frac{n}{2}-1}11$, $f^2(x)=(10)^{\frac{n}{2}-2}11(10)$.
\begin{equation*}
\begin{split}
f^3(x)&=(01)^{\frac{n}{2}-2}11(01)\\
f^4(x)&=(10)^{\frac{n}{2}-3}11(10)^2\\
\vdots&\\
f^{t}(x)&=(10)^{\frac{n}{2}-\frac{t}{2}-1}11(10)^{\frac{t}{2}}\text{  if t is even}\\
f^{t}(x)&=(01)^{\frac{n}{2}-\frac{t-1}{2}-1}11(01)^{\frac{t-1}{2}}\text{  if t is odd}\\
\vdots&\\
f^{n-4}(x)&=(10)^{\frac{n}{2}-\frac{n-4}{2}-1}11(10)^{\frac{n-4}{2}}=(10)11(10)^{\frac{n-4}{2}}\\
f^{n-3}(x)&=(01)^{\frac{n}{2}-\frac{n-4}{2}-1}11(01)^{\frac{n-4}{2}}=(01)11(01)^{\frac{n-4}{2}}\\
f^{n-2}(x)&=(10)^{\frac{n}{2}-\frac{n-2}{2}-1}11(10)^{\frac{n-2}{2}}=11(10)^{\frac{n-4}{2}}\\
f^{n-1}(x)&=(01)^{\frac{n}{2}-\frac{n-2}{2}-1}11(01)^{\frac{n-4}{2}}=11(01)^{\frac{n-4}{2}}\\
\end{split}
\end{equation*}
And finally, $f^n(x)=(10)^{\frac{n}{2}-1}11$. Note that if $n$ is an odd number, then we can start from $x=(10)^{\frac{n-1}{2}}1$.

For rule $172$, starting with an initial configuration $x=1^{n-1}0$, we have $f(x)=1^{n-2}01$, $f^2(x)=1^{n-3}01^2$
\begin{equation*}
\begin{split}
f^3(x)&=1^{n-4}01^3\\
\vdots&\\
f^t(x)&=1^{n-(t+1)}01^t\\
\vdots&\\
f^{n-1}(x)&=1^{n-(n-1+1)}01^{n-1}=01^{n-1}\\
\end{split}
\end{equation*}
And finally, $f^n(x)=1^{n-1}0$.

In all three cases cases, if there is just one cell that does not update at the same time as all the others all configurations reach a fixed point.
\end{proof}

