\begin{lemma}
	\label{lem:156wall01}
	ECA rule $156$ admits only one wall, namely the word $w = 01$.
\end{lemma}

\begin{proof}
	For all $a, b \in \B$, $f_{156}(a01) = 0$ and $f_{156}(01b) = 1$. 
	By definition of the rule, no other word of length $2$ gets this property. 
	Thus $w$ is the unique wall for ECA rule $156$.\qed
\end{proof}

\begin{lemma}
	\label{lem:156wallcreation}
	ECA rule $156$ can dynamically create new walls only if the underlying update mode makes two consecutive cells update their state simultaneously. 
\end{lemma}

\begin{proof}
	Remark that to create walls in the trajectory of a configuration $x 
	\in \B^n$, $x$ need to have at least one wall. 
	Indeed, the only configurations with no walls are $0^n$ and $1^n$, and they are 
	fixed points.
	Thus, with no loss of generality, let us focus on a subconfiguration $y \in \B^k$, 
	with $k \leq n-2$, composed of free state cells surrounded by two walls.
	Notice that since the configurations are toric, the wall ``at the left'' and ``at 
	the right'' of $y$ can be represented by the same two cells.\smallskip

	Configuration $y$ is necessarily of the form $y = (1)^\ell(0)^r$, with $k = \ell + 
	r$. 
	Furthermore, since $f_{156}(000) = 0$ and $f_{156}(100) = 1$, the only cells whose 
	states can change are those where $1$ meets $0$, i.e. $y_{\ell-1}$ and $y_\ell$.
	Such state changes depends on the schedule of updates between these two cells.
	Let us proceed with case disjunction:
	\begin{enumerate}
	\item Case of $\ell \geq 1$ and $r \geq 1$:
		\begin{itemize}
		\item if $y_\ell$ is updated strictly before $y_{\ell-1}$, then $y^1 = 
			(1)^{\ell+1}(0)^{r-1}$, and the number of $1$s (resp. $0$s) increases 
			(resp. decreases);
		\item if $y_\ell$ is updated strictly after $y_{\ell-1}$, then $y^1 = 
			(1)^{\ell-1}(0)^{r+1}$, and the number of $1$s (resp. $0$s) decreases 
			(resp. increases);
		\item if $y_\ell$ and $y_{\ell-1}$ are updated simultaneously, then $y^1 = 
			(1)^{\ell-1}(01)(0)^{r-1}$, and a wall is created.
		\end{itemize}
	\item Case of $\ell = 0$ (or of $y = 0^k$): nothing happens until $y_0$ is updated. 
		Let us admit that this first state change has been done for the sake of 
		clarity and focus on $y^1 = (1)^{\ell = 1}(0)^{r = k-1}$, which falls into Case 
		1.
	\item Case of $r = 0$ (or of $y = 1^k$): symmetrically to Case 2, nothing happens 
		until $y_{k-1}$ is updated. 
		Let us admit that this first state change has been done for the sake of 
		clarity and focus on $y^1 = (1)^{\ell = k-1}(0)^{1}$, which falls into Case 
		1.
	\end{enumerate}
	As a consequence, updating two consecutive cells simultaneously is a necessary 
	condition for creating new walls in the dynamics of ECA rule $156$.
\end{proof}

\begin{theorem}
	\label{thm:156parallel}
	$(156, \p{})$ has only fixed points and limit cycles of length two.
\end{theorem}

\begin{proof}
	We base the proof on Lemmas~\ref{lem:156wall01} and~\ref{lem:156wallcreation}.
	So, let us analyze the possible behaviors between two walls, since by definition, 
	what happens between two walls is independent of what happens between two other 
	walls.

	Let us prove the results by considering the three possible distinct cases for a 
	configuration between two walls $y \in \B^{k+4}$:
	\begin{enumerate}
	\item Consider $y = (01)(0)^k(01)$ the configuration with only $0$s between the two 
		walls. 
		Applying the rule twice, we obtain $y^2 = (01)^2(0)^{k-2}(01)$.
		So, a new wall appears every two iterations so that, for all $t < \frac{k}{2}$,  
		$y^{2t} = (01)^{t+1}(0)^{k-2t}(01)$, until a step is reached where there is no 
		room for more walls. 
		This step is reached after $k$ (resp $k-1$) iterations when $k$ is even (resp. 
		odd) and is such that there is only walls if $k$ is even (which implies that 
		the dynamics has converged to a fixed point), and only walls except one cell 
		otherwise.
		In this case, considering that $t = \lfloor \frac{k}{2} \rfloor$, because 
		$f_{156}(100) = 1$ and $f_{156}(110) = 0$, we have that 
		$y^{2t} = (01)^{t+1}(0)(01) \to y^{2t+1} = (01)^{t+1}(1)(01) \to 
		y^{2t} = (01)^{t+1}(0)(01)$, which leads to a limit cycle of length 
		$2$.
	\item Consider now that $y = (01)(1)^k(01)$. 
		Symmetrically, for all $t < \frac{k}{2}$, $y^{2t} = (01)(0)^{k-2t}(01)^{t+1}$. 
		The same reasoning applies to conclude that the length of the largest limit 
		cycle is $2$. 
	\item Consider finally configuration $y$ where $k = \ell + r$ such that 
		$y = (01)(1)^\ell(0)^r(01)$. 
		Applying $f_{156}$ on it leads to $y^1 = (01)(1)^{\ell-1}(01)(0)^{r-1}(01)$, 
		which falls into the two previous cases.
	\end{enumerate}
\end{proof}

\begin{theorem}
	\label{thm:156BIP}
	$(156, \bip{})$ applied over a grid of size $n$ has largest limit cycles of length 
	$\Theta(2^{\sqrt{n\log(n)}})$.
\end{theorem}

\begin{proof}
	First, by definition of a bipartite update mode and by Lemmas~\ref{lem:156wall01} 
	and~\ref{lem:156wallcreation}, the only walls appearing in the dynamics are the 
	ones present in the initial configuration. 
	Let us prove that, given two walls $u$ and $v$, distanced by $k$ cells, the largest
	limit cycles of the dynamics between $u$ and $v$ are of length $k+1$. 
	We proceed by case disjunction depending on the nature of the subconfiguration $y 
	\in \B^{k+4}$, with the bipartite update mode $\mu = (\{i \in \integers{k+4} \mid i 
	\equiv 0 \mod 2\}, \{i \in \integers{k+4} \mid i \equiv 0 \mod 2\})$:\smallskip

	\begin{enumerate}
	\item Case of $y = (01)(0)^k(01)$: we prove that configuration $(01)(1)^k(01)$ is 
		reached after $\lceil \frac{k}{2} + 1 \rceil$ steps:\\
		\begin{minipage}{.4\textwidth}
			\begin{enumerate}
			\item If $k$ is odd, we have:\\[-3mm]
				\begin{equation*}
					\begin{array}{ccc}
						y & = & (01)(0)^k(01)\\
						y^1 & = & (01)(1)(0)^{k-1}(01)\\
						y^2 & = & (01)111(0)^{k-3}(01)\\
						& \vdots & \\
						y^{\lfloor\frac{k}{2}\rfloor} & = & (01)(1)^{k-2}(00)(01)\\
						y^{\lceil\frac{k}{2}\rceil} & = & (01)(1)^{k}(01)\\
					\end{array}
				\end{equation*}
			\end{enumerate}
		\end{minipage}
		\quad
		\begin{minipage}{.4\textwidth}
			\begin{enumerate}
			\item If $k$ is even, we have:\\[-3mm]
				\begin{equation*}
					\begin{array}{ccc}
						y & = & (01)(0)^k(01)\\
						y^1 & = & (01)(1)(0)^{k-1}(01)\\
						y^2 & = & (01)(111)(0)^{k-2}(01)\\
						& \vdots & \\
			            y^{\frac{k}{2}} & = & (01)(1)^{k-1}(0)(01)\\
						y^{\frac{k}{2}+1} & = & (01)(1)^{k}(01)\\
					\end{array}
				\end{equation*}
			\end{enumerate}			
		\end{minipage}\smallskip

	\item Case of $y = (01)(1)^k(01)$: we prove that configuration $(01)(0)^k(01)$ is 
		reached after $\lceil \frac{k}{2} + 1 \rceil$ steps:\\
		\begin{minipage}{.4\textwidth}
			\begin{enumerate}
			\item If $k$ is odd, we have:\\[-3mm]
				\begin{equation*}
					\begin{array}{ccc}
						y & = & (01)(1)^k(01)\\
						y^1 & = & (01)(1)^{k-1}(0)(01)\\
						y^2 & = & (01)(1)^{k-3}(000)(01)\\
						& \vdots & \\
						y^{\lfloor\frac{k}{2}\rfloor} & = & (01)(11)(0)^{k-2}(01)\\
						y^{\lceil\frac{k}{2}\rceil} & = & (01)(0)^{k}(01)\\
					\end{array}
				\end{equation*}
			\end{enumerate}
		\end{minipage}
		\quad
		\begin{minipage}{.4\textwidth}
			\begin{enumerate}
			\item If $k$ is even, we have:\\[-3mm]
				\begin{equation*}
					\begin{array}{ccc}
						y & = & (01)(1)^k(01)\\
						y^1 & = & (01)(1)^{k-2}(00)(01)\\
						y^2 & = & (01)(1)^{k-4}(0000)(01)\\
						& \vdots & \\
						y^{\frac{k}{2}} & = & (01)(11)(0)^{k-2}(01)\\
						y^{\frac{k}{2}+1} & = & (01)(0)^{k}(01)\\
					\end{array}
				\end{equation*}
			\end{enumerate}
		\end{minipage}\smallskip

	\item Case of $y = (01)(1)^\ell(0)^r(01)$: this case is included in Cases 1 and 2.
	 \end{enumerate}\smallskip

	As a consequence, the dynamics of any $y$ leads indeed to a limit cycle of length 
	$k+1$. 
	Remark that if we had chosen the other bipartite update mode as reference, 
	the dynamics of any $y$ would have been symmetric and led to the same limit 
	cycle.\smallskip 

	Finally, since the dynamics between two pairs of distinct walls of independent 
	of each other, the asymptotic dynamics of a global configuration $x$ such that 
	$x = (01)(0)^{k_1}(01)(0)^{k_2}(01)\dots(01)(0)^{k_m}$ is a limit cycle whose 
	length equals to the least common multiple of the lengths of all limit cycles 
	of the subconfigurations $(01)(0)^{k_1}(01), (01)(0)^{k_2}(01), \dots, (01)
	(0)^{k_m}(01)$.
	We derive that the largest limit cycles are obtained when the $(k_i+1)$s are 
	distinct primes whose sum is equal to $n - 2m$, with $m$ is constant.
	As a consequence, the length of the largest limit cycle is lower- and upper-bounded  
	by the primorial of $n$ (that is, the maximal product of distinct primes whose sum is 
	$\leq n$.), denoted by function $h(n)$.
	In~\cite{Deleglise2015}, it is shown  in Theorem~$18$ that when $n$ tends to infinity, $\log h(n) \sim \sqrt{n \log n}$.
	Hence,  we deduce that the length of the largest limit cycles of $(156, \bip{})$ of 
	size $n$ is $\Theta(2^{\sqrt{n\log(n)}})$. 
	\end{proof}

\begin{corollary}
	\label{cor:156other}
	The families $(156, \bs{})$, $(156, \bp{})$ and $(156, \lc{})$ of size 
	$n$ have largest limit cycles of length $\Omega(2^{\sqrt{n\log(n)}})$.
\end{corollary}

\begin{proof}
	Since the bipartite update modes are specific block-sequential and block-parallel 
	update modes, and since both block-sequential and block-parallel update modes are 
	parts of local-clocks update modes, all of them inherit the property stating that 
	the lengths of the largest limit cycles are lower-bounded by 
	$2^{\sqrt{n\log(n)}}$. 
\end{proof}

