\begin{center}
\begin{tabular}{cccccccccccc}
0&1&$\dots$& $k-\ell$&$k-\ell+1$&$\dots$ &$k-2$&$k-1$&$k$&$k+1$&$\dots$&n-1\\\hline
1&1&$\dots$&1        &1         &$\dots$ &1  &1  &0&0  &$\dots$&0\\\hline
1&1&$\dots$&1        &0         &$\dots$ &0  &0  &0&0  &$\dots$&0\\\hline
$\vdots$\\\hline
0&0&$\dots$&0        &0         &$\dots$ &0  &0  &0&0  &$\dots$&0\\\hline
\end{tabular}
\end{center}
\caption{Representation of Cases 1 and 3: $\mu_{0}>\mu_{1}$ or $\mu_{0}<\mu_{1}$ and $\mu_{k-1}<\mu_k$.}
\begin{center}
\begin{tabular}{cccccccccccc}
