\begin{lemma}
	\label{lem:108walls}
	ECA rule $108$ admits two walls, $001$ and $100$.
\end{lemma}

\begin{proof}
	By definition of the rule, $f_{108}(a00)=0$, $f_{108}(001)=0$ and $f_{108}(01b)=1$, for all $a,b\in\{0,1\}$, which means that $\omega_1=001$ is a wall. Also by definition, $f_{108}(a10)=1$, $f_{108}(100)=0$ and $f_{108}(00b)=0$, meaning that $\omega_2=100$ is also a wall.
\end{proof}
We will now show that there exists one sequential update mode for which there are cycles of length $\Omega\left(2^{(\sqrt{n\log(n)})}\right)$
\begin{theorem}
	\label{thm:108seq}
	Rule $(108, \seq)$  applied over a grid of size $n$  can reach largest limit cycles of length $\Omega\left(2^{(\sqrt{n\log(n)})}\right)$
\end{theorem}
\begin{proof}
Let $\mu_{\seq}=(0,1,2,3,\dots,n)$ a sequential update schedule.
Let $x$ be an initial configuration such that $x=\omega_1 1^k \omega_2=(001) 1^k (100)$, with $k$ an even number. We need to calculate the state for the configuration $f(x)$.\\
Since $f_{108}(111)=0$, and $f_{108}(011)=1$, we have that
\begin{equation*}
\begin{matrix}
x     &= &001& 1^k                      & 100\\
f(x)  &= &001& (01)^{\frac{k}{2}}       & 100\\
f^2(x)&= &001& 1^{k-2}(10)              & 100\\
f^3(x)&= &001& (01)^{\frac{k-2}{2}}(1)^2& 100\\
f^4(x)&= &001& 1^{k-4}(10)^2            & 100\\
\end{matrix}
\end{equation*}
It is easy to see that on odd iterations there is a number of words $(01)$ that appears in the configuration, but that amount goes down as the numbers of $1$'s to the right side increases. And for the even iterations, we can see the number of ones going down to the left, while the number of words $(10)$ increases. This can be written as
\begin{equation*}
\begin{matrix}
f^t(x)    &= &001& (01)^{\frac{k-(t-1)}{2}}(1)^{t-1}& 100\\
f^{t+1}(x)&= &001& (1)^{k-t}(10)^{\frac{t}{2}}      & 100\\
\end{matrix}
\end{equation*}
when $t$ is odd. Which means that the $(k-1)$-th iteration is
\begin{equation*}
\begin{matrix}
f^{k-1}(x)&= &001& (01)^{\frac{k-((k-1)-1)}{2}}(1)^{(k-1)-1}& 100\\
		  &= &001& (01)^{1}(1)^{k-2}                        & 100\\
\end{matrix}
\end{equation*}
And then $k-$th
\begin{equation*}
\begin{matrix}
f^{k}(x)&= &001& (1)^{k-k}(10)^{\frac{k}{2}}& 100\\
        &= &001& (10)^{\frac{k}{2}}         & 100\\
\end{matrix}
\end{equation*}
And finally, the $(k+1)$-th iteration:
\begin{equation*}
\begin{matrix}
f^{k+1}(x)&= &001& 1^k                      & 100\\
\end{matrix}
\end{equation*}
Which brings us back to the original configuration, meaning that between two walls we can find cycles of length $k$ when $k$ is even.\\

If $k$ is odd, $x=\omega_1 1^k\omega_2$ results in cycles of length 2. We will instead focus on an initial configuration $x$ such that $x=\omega_1 1^{k-1}0\omega_2=(001)(1)^{k-1}0(100)$.
\begin{equation*}
\begin{matrix}
f(x)  &=& 001& (01)^{\frac{k-1}{2}}1^2    &100\\
f^2(x)&=& 001& (1)^{k-2}01                &100\\
f^3(x)&=& 001& (01)^{\frac{k-3}{2}}1(10)  &100\\
f^4(x)&=& 001& (1)^{k-4}0(1)^3            &100\\
f^5(x)&=& 001& (01)^{\frac{k-5}{2}}1(10)^2&100\\
f^6(x)&=& 001& (1)^{k-6}0(1)^5            &100\\
\end{matrix}
\end{equation*}
From where we can deduce that after $t$ iterations (with $t$ odd) we will have
\begin{equation*}
\begin{matrix}
f^t(x)    &=& 001& (01)^{\frac{k-t}{2}}1(10)^{\frac{t-1}{2}}&100\\
f^{t+1}(x)&=& 001& (1)^{k-t}0(1)^{t-1}                      &100\\
\end{matrix}
\end{equation*}
Which means that after $k-1$ iterations we will have
\begin{equation*}
\begin{matrix}
f^{k-1}(x)&=& 001& (1)0(1)^{(k-1)-1}    &100\\
f^{k}(x)  &=& 001& 1(10)^{\frac{k-1}{2}}&100\\
f^{k+1}(x)&=& 001& 0(1)^{k-1}           &100\\
f^{k+2}(x)&=& 001& (10)^{\frac{k-1}{2}}1&100\\
f^{k+3}(x)&=& 001& (1)^{k-1}0           &100\\
\end{matrix}
\end{equation*}
Which brings us back to the starting configuration, meaning that between two walls we can find cycles of length $k+2$ when $k$ is odd.\\
Using the same argument used for Theorem \ref{thm:156BIP}, we conclude that the largest limit cycles of the family $(108,\seq)$ when applied over a ring of length $n$ is $\Omega\left(2^{\sqrt{n\log n}}\right)$.
\end{proof}

\begin{corollary}\label{thm:108bloques}
    $(108,\bs),(108,\bp),(108,\lc)$ have largest limit cycles of length $\Omega\left(2^{\sqrt{n\log n}}\right)$.
\end{corollary}
\begin{proof}
    The family of sequential update schedules are a subset of block parallel and block sequential, which themselves are a subset of local clocks, so they inherit the result.
\end{proof}

