\begin{theorem}\label{thm:1bip}
$(1,\bip)$ of size $n$ can reach cycles of length at least $\Theta(n)$
\end{theorem}
\begin{proof}
Let $x$ be an initial configuration such that $x=0^k01$.
Then, for $\mu_{\bip}$ we have 
\begin{equation*}
\begin{matrix} 
x     &= & 0^k    01                 \\
f(x)  &= & 00(10)^{\frac{k}{2}-1}   00    \\
f^2(x)&= & (10)(01)^{\frac{k}{2}-2} 00(10)\\
\end{matrix}
\end{equation*}
\begin{equation*}
\begin{matrix} 
f^3(x)&= & (01)0^{k-4}  (01)^2                 \\
f^4(x)  &= & 0^4(10)^{\frac{k}{2}-3}   0^4    \\
f^5(x)&= & (10)^2(01)^{\frac{k}{2}-4} 00(10)^2\\
\end{matrix}
\end{equation*}
\begin{equation*}
\begin{matrix} 
f^6(x)&= & (01)^20^{k-8}  (01)^3                 \\
f^7(x)&= & 0^6(10)^{\frac{k}{2}-5}   0^6    \\
f^8(x)&= & (10)^3(01)^{\frac{k}{2}-6} 00(10)^3\\
\end{matrix}
\end{equation*} 
Since the shape of the configuration depends on the multiplicity of the number of step with respect to 3, let $T=\left\lfloor\frac{t}{3}\right\rfloor$.
\begin{equation*}
\begin{matrix} 
f^T(x)&= & (01)^T 0^{k-4T}  (01)^{T+1}                 \\
f^{T+1}(x)&= & (00)^{T+1}(10)^{\frac{k}{2}-(2T+1)}(00)^{T+1}    \\
f^{T+2}(x)&= & (10)^{T+1}(01)^{\frac{k}{2}-2(T+1)} 00(10)^{T+1}\\
\end{matrix}
\end{equation*} 
From where we can deduce that there are two times on which we reach a cycle, depending on the length of $k$.\\
If $k\mod 4=0$, then for $T^*=\frac{k-8}{4}$ we have
\begin{equation*}
\begin{matrix} 
f^{T^*}(x)&= & (01)^{T^*} 0^{k-4T^*}  (01)^{T^*+1}                 \\
          &= & (01)^{\frac{k-8}{4}} 0^{k-4(\frac{k-8}{4})}  (01)^{\frac{k-8}{4}+1}                 \\
          &= & (01)^{\frac{k-8}{4}} 0^{8}  (01)^{\frac{k-8}{4}+1}                 \\
f^{T^*+1}(x)&= & (00)^{T^*+1}(10)^{\frac{k}{2}-(2T^*+1)}(00)^{T^*+1}    \\
          &= & (00)^{\frac{k-8}{4}+1}(10)^{\frac{k}{2}-(2(\frac{k-8}{4})+1)}(00)^{\frac{k-8}{4}+1}    \\
          &= & (00)^{\frac{k-8}{4}+1}(10)^{\frac{k}{2}-((\frac{k-8}{2})+1)}(00)^{\frac{k-8}{4}+1}    \\
          &= & (00)^{\frac{k-8}{4}+1}(10)^{3}(00)^{\frac{k-8}{4}+1}    \\
f^{T^*+2}(x)&= & (10)^{T^*+1}(01)^{\frac{k}{2}-2(T^*+1)} 00(10)^{T^*+1}\\
            &= & (10)^{\frac{k-8}{4}+1}(01)^{\frac{k}{2}-(\frac{k-8}{2}+2)} 00(10)^{\frac{k-8}{4}+1}\\
            &= & (10)^{\frac{k-8}{4}+1}(01)^{2} 00(10)^{\frac{k-8}{4}+1}\\
f^{T^*+3}(x)&= & (01)^{T^*+1} 0^{k-4(T^*+1)}  (01)^{T^*+2}                 \\
          &= & (01)^{\frac{k-8}{4}+1} 0^{4}  (01)^{\frac{k-8}{4}+2}                 \\
f^{T^*+4}(x)&= & (00)^{T^*+2}(10)^{\frac{k}{2}-(2T^*+2)}(00)^{T^*+2}    \\
          &= & (00)^{\frac{k-8}{4}+2}(10)^{\frac{k}{2}-(2(\frac{k-8}{4})+2)}(00)^{\frac{k-8}{4}+2}    \\
          &= & (00)^{\frac{k}{4}}(10)(00)^{\frac{k}{4}}    \\
\end{matrix}
\end{equation*} 
It is easy to see that $f^{T^*+4}(x)$ is similar to $x$ up to translation, and if we repeat the previous analysis, we obtain that the overall cycle is of length $p=2(3(\frac{k-8}{4})+4)=\frac{3k}{2}-4$.

If instead $k\mod 4=2$, then for $T^*=\frac{k-6}{4}$ we have
\begin{equation*}
\begin{matrix} 
f^{T^*}(x)&= & (01)^{T^*} 0^{k-4T^*}  (01)^{T^*+1}                 \\
          &= & (01)^{\frac{k-6}{4}} 0^{6}  (01)^{\frac{k-6}{4}+1}                 \\
f^{T^*+1}(x)&= & (00)^{T^*+1}(10)^{\frac{k}{2}-(2T^*+1)}(00)^{T^*+1}    \\
          &= & (00)^{\frac{k-6}{4}+1}(10)^{2}(00)^{\frac{k-6}{4}+1}    \\
f^{T^*+2}(x)&= & (10)^{T^*+1}(01)^{\frac{k}{2}-2(T^*+1)} 00(10)^{T^*+1}\\
            &= & (10)^{\frac{k-6}{4}+1}(01)^{1} 00(10)^{\frac{k-6}{4}+1}\\
f^{T^*+3}(x)&= & (01)^{T^*+1} 0^{k-4(T^*+1)}  (01)^{T^*+2}                 \\
          &= & (01)^{\frac{k-6}{4}+1} 0^{2}  (01)^{\frac{k-6}{4}+2}                 \\
f^{T^*+4}(x)&= & (00)^{\frac{k-2}{4}}(01)(00)^{\frac{k+2}{4}}    \\
\end{matrix}
\end{equation*} 
From where we can follow the same reasoning as before, which gives us overall cycles of length $p=2(3(\frac{k-6}{4})+4)=\frac{3k}{2}-5$
\end{proof}


