We will now show that there exists (at least) one initial configuration for which a block-parallel update mode can reach cycles of length $\Omega\left(2^{(\sqrt{n\log(n)})}\right)$
\begin{theorem}
	\label{thm:1bp}
	Rule $(1, \bp)$  applied over a grid of size $n$  can reach largest limit cycles of length $\Omega\left(2^{(\sqrt{n\log(n)})}\right)$
\end{theorem}
\begin{proof}
Without loss of generality, let $\mu_{\bip}=(\{i|i\mod 2\equiv 0\},\{i|i\mod 2\equiv 1\})$ a bipartite update schedule.\\
Let $x$ be an initial configuration such that $x=\omega_1 0^k 1 \omega_0=(010) 0^k 01 (000)$, with $k$ an even number. We need to calculate the state for the configuration $f(x)$.\\
Since $f_{1}(000)=1$, and $f_{1}(101)=0$, we have that
\begin{equation*}
\begin{matrix} 
&x     &= &010& (10) 0^k                  & 000\\
&f(x)  &= &010& (00)(01)^{\frac{k}{2}}    & 000\\
&f^2(x)&= &010& (01)00(10)^{\frac{k}{2}-1}& 000\\
\end{matrix}
\end{equation*}
\begin{equation*}
\begin{matrix} 
&f^3(x)&= &010& (10)^2 0^{k-2}                & 000\\
&f^4(x)&= &010& (00)^2(01)^{\frac{k}{2}-1}    & 000\\
&f^5(x)&= &010& (01)^2 00(10)^{\frac{k}{2}-2} & 000\\
\end{matrix}
\end{equation*}
\begin{equation*}
\begin{matrix} 
&f^6(x)&= &010& (10)^3 0^{k-6}                & 000\\
&f^7(x)&= &010& (00)^3(01)^{\frac{k}{2}-2}    & 000\\
&f^8(x)&= &010& (01)^3 00(10)^{\frac{k}{2}-3} & 000\\
\end{matrix}
\end{equation*}
Let $T=\left\lfloor\frac{t}{3}\right\rfloor$
\begin{equation*}
\begin{matrix}
f^T(x)    &= &010& (10)^T 0^{k-2T}                   & 000\\
f^{T+1}(x)&= &010& (00)^T(01)^{\frac{k}{2}-T}        & 000\\
f^{T+2}(x)&= &010& (01)^T 00(10)^{\frac{k}{2}-(T+1)} & 000\\
\end{matrix}
\end{equation*}
Now, let $T^*=\frac{k-2}{2}$
\begin{equation*}
\begin{matrix} 
f^{T^*}(x)  &= &010& (10)^{\frac{k-2}{2}} 0^{k-2(\frac{k-2}{2})}         & 000\\
            &= &010& (10)^{\frac{k-2}{2}} 0^{2}                          & 000\\
f^{T^*+1}(x)&= &010& (00)^{\frac{k-2}{2}}(01)^{\frac{k}{2}-\frac{k-2}{2}}& 000\\
            &= &010& (00)^{\frac{k-2}{2}}(01)^{1}                        & 000\\
\end{matrix}
\end{equation*}
We have that $f^{T^*+1}(x)$ is $x'= \omega_1 0^k 1 \omega_0$, and through an analysis symmetrical to what we just did, we obtain that $f^{T^*+1}(x')=x$, meaning that when $k$ is even, the length of the cycle between walls can reach at least a length of $k$ (with the distance between walls equal to $k+2$).\\
Analogously, if $k$ is odd we have that:\\
\begin{equation*}
\begin{matrix} 
x     &= &010& (10)0^k                   & 010\\
f(x)  &= &010& 000(10)^{\frac{k-1}{2}}   & 010\\
f^2(x)&= &010& (01) 0(01)^{\frac{k-1}{2}}& 010\\
\end{matrix}
\end{equation*}
\begin{equation*}
\begin{matrix} 
f^3(x)&= &010& (10)^2 0^{k-2}                 & 010\\
f^4(x)&= &010& (00)^2 0(10)^{\frac{k-1}{2}-1} & 010\\
f^5(x)&= &010& (01)^2 0(01)^{\frac{k-1}{2}-1} & 010\\
\end{matrix}
\end{equation*}
\begin{equation*}
\begin{matrix} 
f^{T}(x)  &= &010& (10)^{T+1} 0^{k-2T}            & 010\\
f^{T+1}(x)&= &010& (00)^{T+1} 0(10)^{\frac{k-1}{2}-T} & 010\\
f^{T+2}(x)&= &010& (01)^{T+1} 0(01)^{\frac{k-1}{2}-T} & 010\\
\end{matrix}
\end{equation*}
\begin{equation*}
\begin{matrix} 
f^{T^*}(x)  &= &010& (10)^{T^*+1} 0^{k-2T^*}            & 010\\
            &= &010& (10)^{\frac{k-1}{2}+1} 0^{k-2(\frac{k-1}{2})}& 010\\
            &= &010& (10)^{\frac{k-1}{2}+1} 0^{1}            & 010\\
f^{T^*+1}(x)&= &010& (00)^{T^*+1} 1 & 010\\
            &= &010& (00)^{\frac{k-1}{2}+1} 1 & 010\\
\end{matrix}
\end{equation*}
with $T^*=\frac{k-1}{2}$.\\
Using the same argument used for \ref{thm:156BIP}, we conclude that the overall limit cycle of the family $(1,\bp)$ when applied over a ring of length $n$ can reach $\Omega\left(2^{\sqrt{n\log n}}\right)$.
\end{proof}

