\begin{lemma}
	\label{lem:73walls}
	ECA rule $73$ admits one wall, $0110$.
\end{lemma}

\begin{proof}
	By definition of the rule, $f_{73}(a01)=0$, with $a\in\{0,1\}$, $f_{73}(011)=f_{73}(110)=1$ and $f_{73}(10b)=0$, with $b\in\{0,1\}$. From where we know that $f_{73}(a0110b)=0110$, regardless of the update mode.
\end{proof}

We will now show that there exists (at least) one initial configuration for which a bipartite update mode can reach cycles of length $\Omega\left(2^{(\sqrt{n\log(n)})}\right)$
\begin{theorem}
	\label{thm:73bip}
	Rule $(73, \bip)$  applied over a grid of size $n$  can reach largest limit cycles of length $\Omega\left(2^{(\sqrt{n\log(n)})}\right)$
\end{theorem}
\begin{proof}
Without loss of generality, let $\mu_{\bip}=(\{i|i\mod 2\equiv 0\},\{i|i\mod 2\equiv 1\})$ a bipartite update schedule.\\
Let $x$ be an initial configuration such that $x=\omega 0^k 1 \omega=(0110) 0^k 01 (0110)$, with $k$ an even number. We need to calculate the state for the configuration $f(x)$.\\
Since $f_{73}(000)=1$, and $f_{73}(101)=0$, we have that
\begin{equation*}
\begin{matrix} 
x     &= &0110& 0^k    01                 & 0110\\
f(x)  &= &0110& (10)^{\frac{k}{2}}    00  & 0110\\
f^2(x)&= &0110& (01)^{\frac{k}{2}-1} 0010 & 0110\\
\\
f^3(x)&= &0110& 0^{k-2}  (01)^2                 & 0110\\
f^4(x)&= &0110& (10)^{\frac{k}{2}-1} 0000     & 0110\\
f^5(x)&= &0110& (01)^{\frac{k}{2}-2}(00)(10)^2& 0110\\
\end{matrix}
\end{equation*}
We can see that a pattern emerges, depending on the number of iteration $\mod 3$. Let $T=\lfloor\frac{t}{3}\rfloor$, with $t\in\N$, then we can write
\begin{equation*}
\begin{matrix} 
f^T(x)    &= &0110& 0^{k-2T}   (01)^{T+1}                 & 0110\\
f^{T+1}(x)&= &0110& (10)^{\frac{k}{2}-T}(00)^{T+1}        & 0110\\
f^{T+2}(x)&= &0110& (01)^{\frac{k}{2}-(T+1)}(00)(10)^{T+1}& 0110\\
\end{matrix}
\end{equation*}
Now, let $T^*=\frac{k-2}{2}$
\begin{equation*}
\begin{matrix} 
f^{T^*}(x)  &= &0110& 0^{k-2T^*}   (01)^{T^*+1}                    & 0110\\
            &= &0110& 0^{k-2(\frac{k-2}{2})}(01)^{\frac{k-2}{2}+1} & 0110\\
            &= &0110& 0^{2}   (01)^{\frac{k}{2}}                   & 0110\\
f^{T^*+1}(x)&= &0110& (10)^{\frac{k}{2}-T^*}(00)^{T^*+1}           & 0110\\
            &= &0110& (10)^{1}(00)^{\frac{k}{2}}                   & 0110\\
\end{matrix}
\end{equation*}
We have that $f^{T^*+1}(x)$ is $x'= \omega 1 0^k \omega$, and through an analysis symmetrical to what we just did, we obtain that $f^{T^*+1}(x')=x$, meaning that when $k$ is even, the length of the cycle between walls can reach at least a length of $k$ (with the distance between walls equal to $k+2$).\\
Analogously, if $k$ is odd we have that:\\
\begin{equation*}
\begin{matrix} 
x     &= &0110& 0^k    01               & 0110\\
f(x)  &= &0110& (10)^{\frac{k+1}{2}} 0  & 0110\\
f^2(x)&= &0110& (01)^{\frac{k-1}{2}} 001& 0110\\
\\
f^3(x)&= &0110& 0^{k-1}  (10)                 & 0110\\
f^4(x)&= &0110& (10)^{\frac{k+1}{2}-1} 000    & 0110\\
f^5(x)&= &0110& (01)^{\frac{k-1}{2}-1} 0(01)^2& 0110\\
\vdots\\
f^T(x)    &= &0110& 0^{k-T}  (10)^T                   & 0110\\
f^{T+1}(x)&= &0110& (10)^{\frac{k+1}{2}-T} 0(00)^T    & 0110\\
f^{T+2}(x)&= &0110& (01)^{\frac{k-1}{2}-T} 0(01)^{T+1}& 0110\\
\vdots\\
f^{T^*}(x)  &= &0110& 0^{k-T^*}  (10)^{T^*}               & 0110\\
            &= &0110& 0^{3}  (10)^{\frac{k-1}{2}}         & 0110\\
f^{T^*+1}(x)&= &0110& (10)^{\frac{k+1}{2}-T^*} 0(00)^{T^*}& 0110\\
            &= &0110& (10)^{1} 0(00)^{\frac{k-1}{2}}      & 0110\\
\end{matrix}
\end{equation*}
with $T^*=\frac{k-1}{2}$.\\
Using the same argument used for \ref{thm:156BIP}, we conclude that the largest limit cycles of the family $(73,\bip)$ when applied over a ring of length $n$ is $\Omega\left(2^{\sqrt{n\log n}}\right)$.
\end{proof}

\begin{corollary}\label{thm:73bloques}
    $(73,\bs),(73,\bp),(73,\lc)$ have largest limit cycles of length $\Omega\left(2^{\sqrt{n\log n}}\right)$.
\end{corollary}
\begin{proof}
    The family of sequential update schedules are a subset of block parallel and block sequential, which themselves are a subset of local clocks, so they inherit the result.
\end{proof}


