		& \quad + 15\dfrac{ \dif^3 E}{\dif \boldsymbol{f}^3} \cdot \left(\dfrac{ \dif^4 \boldsymbol{f}}{\dif \boldsymbol{\rho}^4} \odot \dfrac{ \dif \boldsymbol{f}}{\dif \boldsymbol{\rho}} \odot \dfrac{ \dif \boldsymbol{f}}{\dif \boldsymbol{\rho}} \right) + 60 \dfrac{ \dif^3 E}{\dif \boldsymbol{f}^3} \cdot \left(\dfrac{\dif^3 \boldsymbol{f}}{\dif \boldsymbol{\rho}^3} \odot \dfrac{\dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \odot \dfrac{ \dif \boldsymbol{f}}{\dif \boldsymbol{\rho}} \right) + 15 \dfrac{ \dif^3 E}{\dif \boldsymbol{f}^3} \cdot \left(\dfrac{\dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2}\right)^{\otimes 3} \\
		& \quad + 20 \dfrac{ \dif^4 E}{\dif \boldsymbol{f}^4} \cdot \left(\dfrac{\dif^3 \boldsymbol{f}}{\dif \boldsymbol{\rho}^3} \odot \left(\dfrac{ \dif \boldsymbol{f}}{\dif \boldsymbol{\rho}}\right)^{\odot 3} \right) + 45 \dfrac{ \dif^4 E}{\dif \boldsymbol{f}^4} \cdot \left(\dfrac{\dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \odot \dfrac{\dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \odot \dfrac{ \dif \boldsymbol{f}}{\dif \boldsymbol{\rho}} \odot \dfrac{ \dif \boldsymbol{f}}{\dif \boldsymbol{\rho}} \right) \\
		& \quad + \left. 15 \dfrac{ \dif^5 E}{\dif \boldsymbol{f}^5} \cdot \left(\dfrac{\dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \odot \left(\dfrac{ \dif \boldsymbol{f}}{\dif \boldsymbol{\rho}}\right)^{\odot 4} \right) + \dfrac{ \dif^6 E}{\dif \boldsymbol{f}^6} \cdot \left(\dfrac{ \dif \boldsymbol{f}}{\dif \boldsymbol{\rho}}\right)^{\otimes 6} \right) \cdot (\boldsymbol{\rho}')^{\otimes 6}  \\
	\end{aligned}
\end{equation*}

\section{Coefficients in the transition of $(1, k)$ flex} \label{appendix: coefficients}

We prove Proposition \ref{prop: 1k flex} from direct calculation and induction. The calculation below also shows how to efficiently check the rigidity order of a geometric constraint system when the rigidity matrix has nullity one.

Up to a scaling, let $\boldsymbol{\rho}' = \boldsymbol{v}_1$, $\|\boldsymbol{v}_1\| = 1$. From the linear system over $\boldsymbol{\rho}''$:
\begin{equation*}
	\dfrac{ \dif \boldsymbol{f}}{\dif \boldsymbol{\rho}} \cdot \boldsymbol{\rho}'' = \boldsymbol{b}_1, \quad \boldsymbol{b}_1 = -\dfrac{ \dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \cdot \left(\boldsymbol{v}_1 \otimes \boldsymbol{v}_1 \right)
\end{equation*}
If the rank of the augmented matrix formed by $\dif \boldsymbol{f}/\dif \boldsymbol{\rho}$ and $\boldsymbol{b}_1$ is $n_\rho$, the configuration $\boldsymbol{\rho}$ is second-order rigid. Otherwise, if the rank of the above augmented matrix is $n_\rho -1$, the configuration $\boldsymbol{\rho}$ is second-order flexible. The space for second-order flex is a one-dimensional linear space:
\begin{equation*}
	\begin{gathered}
		\boldsymbol{\rho}'' = \boldsymbol{v}_2 + c_1\boldsymbol{v}_1 \\
		\boldsymbol{v}_2 =  \left(\dfrac{ \dif \boldsymbol{f}}{\dif \boldsymbol{\rho}}\right)^{+}\boldsymbol{b}_1 \\ 
	\end{gathered}
\end{equation*}
where $(\dif \boldsymbol{f}/\dif \boldsymbol{\rho})^{+}$ is the (unique) Moore-Penrose pseudoinverse of $\dif \boldsymbol{f}/\dif \boldsymbol{\rho}$. $\boldsymbol{v}_2$ is in the orthogonal complement space of $\mathrm{Null}(\dif \boldsymbol{f}/\dif \boldsymbol{\rho})$.   

To check whether a second-order flex is extendable to a third-order flex, check the equation for a $(1, 3)$ flex:
\begin{equation*}
	\begin{gathered}
		\begin{aligned}
			\dfrac{ \dif \boldsymbol{f}}{\dif \boldsymbol{\rho}} \cdot \boldsymbol{\rho}''' & = -3\dfrac{ \dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \cdot \left(\left(\boldsymbol{v}_2 + c_1\boldsymbol{v}_1\right) \otimes \boldsymbol{v}_1\right) - \dfrac{ \dif^3 \boldsymbol{f}}{\dif \boldsymbol{\rho}^3} \cdot \left(\boldsymbol{v}_1\right)^{\otimes 3} \\
			& = \boldsymbol{b}_2 + 3c_1\boldsymbol{b}_1 
		\end{aligned} \\
		\boldsymbol{b}_2 = - 3\dfrac{ \dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \cdot \left(\boldsymbol{v}_2 \otimes \boldsymbol{v}_1\right) - \dfrac{ \dif^3 \boldsymbol{f}}{\dif \boldsymbol{\rho}^3} \cdot \left(\boldsymbol{v}_1\right)^{\otimes 3}
	\end{gathered}
\end{equation*}
If the rank of the augmented matrix formed by $\dif \boldsymbol{f}/\dif \boldsymbol{\rho}$ and $\boldsymbol{b}_2$ is $n_\rho$, the configuration $\boldsymbol{\rho}$ is third-order rigid. Otherwise, if the rank of the above augmented matrix is $n_\rho-1$, the configuration $\boldsymbol{\rho}$ is third-order flexible. Therefore, the indeterminacy $c_1$ has \textbf{no effect} in determining the third-order rigidity. The space for $\boldsymbol{\rho}'''$ is a two-dimensional linear space:
\begin{equation*}
	\begin{gathered}
		\boldsymbol{\rho}''' = \boldsymbol{v}_3 + 3c_1\boldsymbol{v}_2+c_2\boldsymbol{v}_1 \\
		\boldsymbol{v}_3 = \left(\dfrac{ \dif \boldsymbol{f}}{\dif \boldsymbol{\rho}}\right)^{+} \boldsymbol{b}_2 
	\end{gathered}
\end{equation*}

To check whether a third-order flex is extendable to a fourth-order flex, check the equation for a $(1, 4)$ flex:
\begin{equation*} 
	\begin{aligned}
		\dfrac{ \dif \boldsymbol{f}}{\dif \boldsymbol{\rho}} \cdot \boldsymbol{\rho}^{(4)} & = - 4\dfrac{ \dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \cdot \left(\boldsymbol{\rho}''' \otimes \boldsymbol{\rho}'\right) - 3\dfrac{ \dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \cdot \left(\boldsymbol{\rho}'' \otimes \boldsymbol{\rho}''\right) - 6\dfrac{ \dif^3 \boldsymbol{f}}{\dif \boldsymbol{\rho}^3}\cdot \left(\boldsymbol{\rho}'' \otimes \boldsymbol{\rho}' \otimes \boldsymbol{\rho}' \right) - \dfrac{ \dif^4 \boldsymbol{f}}{\dif \boldsymbol{\rho}^4} \cdot \left(\boldsymbol{\rho}'\right)^{\otimes 4}  \\ 
		& = - 4\dfrac{ \dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \cdot \left(\left(\boldsymbol{v}_3 + 3c_1\boldsymbol{v}_2+c_2\boldsymbol{v}_1 \right) \otimes \boldsymbol{v}_1\right) - 3\dfrac{ \dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \cdot \left((\boldsymbol{v}_2 + c_1\boldsymbol{v}_1) \otimes (\boldsymbol{v}_2 + c_1\boldsymbol{v}_1)\right) \\ 
		& \quad - 6\dfrac{ \dif^3 \boldsymbol{f}}{\dif \boldsymbol{\rho}^3}\cdot \left((\boldsymbol{v}_2 + c_1\boldsymbol{v}_1) \otimes \boldsymbol{v}_1 \otimes \boldsymbol{v}_1 \right) - \dfrac{ \dif^4 \boldsymbol{f}}{\dif \boldsymbol{\rho}^4} \cdot \left(\boldsymbol{v}_1\right)^{\otimes 4} \\
	\end{aligned}
\end{equation*}
Combine the terms we obtain:
\begin{equation*} 
	\begin{gathered}
		\dfrac{ \dif \boldsymbol{f}}{\dif \boldsymbol{\rho}} \cdot \boldsymbol{\rho}^{(4)}  = \boldsymbol{b}_3 + 6c_1 \boldsymbol{b}_2 + (3c_1^2+4c_2) \boldsymbol{b}_1 \\
		\boldsymbol{b}_3 = - 4\dfrac{ \dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \cdot \left(\boldsymbol{v}_3 \otimes \boldsymbol{v}_1\right) - 3\dfrac{ \dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \cdot \left(\boldsymbol{v}_2  \otimes \boldsymbol{v}_2\right) - 6\dfrac{ \dif^3 \boldsymbol{f}}{\dif \boldsymbol{\rho}^3}\cdot \left(\boldsymbol{v}_2  \otimes (\boldsymbol{v}_1)^{\otimes 2}\right) - \dfrac{ \dif^4 \boldsymbol{f}}{\dif \boldsymbol{\rho}^4} \cdot \left(\boldsymbol{v}_1\right)^{\otimes 4}
	\end{gathered}
\end{equation*}
If the rank of the augmented matrix formed by $\dif \boldsymbol{f}/\dif \boldsymbol{\rho}$ and $\boldsymbol{b}_3$ is $n_\rho$, the configuration $\boldsymbol{\rho}$ is fourth-order rigid. Otherwise, if the rank of the above augmented matrix is $n_\rho-1$, the configuration $\boldsymbol{\rho}$ is fourth-order flexible. Therefore, the indeterminacy $c_1, ~c_2$ has no effect in determining the fourth-order rigidity. The space for $\boldsymbol{\rho}^{(4)}$ is (not a linear space):
\begin{equation*}
	\begin{gathered}
		\boldsymbol{\rho}^{(4)} = \boldsymbol{v}_4 + 6c_1\boldsymbol{v}_3 + (3c_1^2+4c_2)\boldsymbol{v}_2+c_3\boldsymbol{v}_1 \\
		\boldsymbol{v}_4 = \left(\dfrac{ \dif \boldsymbol{f}}{\dif \boldsymbol{\rho}}\right)^{+} \boldsymbol{b}_3 
	\end{gathered}
\end{equation*}

To check whether a fourth-order flex is extendable to a fifth-order flex, check the equation for a $(1, 5)$ flex:
\begin{equation*} 
	\begin{aligned}
		\dfrac{ \dif \boldsymbol{f}}{\dif \boldsymbol{\rho}} \cdot \boldsymbol{\rho}^{(5)} & = - 5\dfrac{ \dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \cdot \left(\boldsymbol{\rho}^{(4)}\otimes\boldsymbol{\rho}'\right) - 10\dfrac{ \dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \cdot \left(\boldsymbol{\rho}'''\otimes\boldsymbol{\rho}''\right) - 10 \dfrac{ \dif^3 \boldsymbol{f}}{\dif \boldsymbol{\rho}^3} \cdot \left(\boldsymbol{\rho}'''\otimes\boldsymbol{\rho}'\otimes\boldsymbol{\rho}'\right) \\
		& \quad - 15 \dfrac{ \dif^3 \boldsymbol{f}}{\dif \boldsymbol{\rho}^3} \cdot \left(\boldsymbol{\rho}''\otimes\boldsymbol{\rho}''\otimes\boldsymbol{\rho}'\right) 
		- 10 \dfrac{ \dif^4 \boldsymbol{f}}{\dif \boldsymbol{\rho}^4} \cdot \left(\boldsymbol{\rho}''\otimes (\boldsymbol{\rho}')^{\otimes 3} \right) - \dfrac{ \dif^5 \boldsymbol{f}}{\dif \boldsymbol{\rho}^5} \cdot (\boldsymbol{\rho}')^{\otimes 5} \\ 
	\end{aligned}
\end{equation*} 
Plug in everything:
\begin{equation*}
	\begin{aligned}
		\dfrac{ \dif \boldsymbol{f}}{\dif \boldsymbol{\rho}} \cdot \boldsymbol{\rho}^{(5)} & = - 5\dfrac{ \dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \cdot \left((\boldsymbol{v}_4 + 6c_1\boldsymbol{v}_3 + (3c_1^2+4c_2)\boldsymbol{v}_2+c_3\boldsymbol{v}_1) \otimes \boldsymbol{v}_1 \right) \\
		& \quad - 10\dfrac{ \dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \cdot \left((\boldsymbol{v}_3 + 3c_1\boldsymbol{v}_2+c_2\boldsymbol{v}_1)\otimes(\boldsymbol{v}_2 + c_1\boldsymbol{v}_1)\right) \\
		& \quad - 10 \dfrac{ \dif^3 \boldsymbol{f}}{\dif \boldsymbol{\rho}^3} \cdot \left((\boldsymbol{v}_3 + 3c_1\boldsymbol{v}_2+c_2\boldsymbol{v}_1)\otimes\boldsymbol{v}_1 \otimes \boldsymbol{v}_1 \right) - 15 \dfrac{ \dif^3 \boldsymbol{f}}{\dif \boldsymbol{\rho}^3} \cdot \left((\boldsymbol{v}_2 + c_1\boldsymbol{v}_1)\otimes(\boldsymbol{v}_2 + c_1\boldsymbol{v}_1)\otimes\boldsymbol{v}_1\right) \\
		& \quad - 10 \dfrac{ \dif^4 \boldsymbol{f}}{\dif \boldsymbol{\rho}^4} \cdot \left((\boldsymbol{v}_2 + c_1\boldsymbol{v}_1)\otimes (\boldsymbol{v}_1)^{\otimes 3} \right) - \dfrac{ \dif^5 \boldsymbol{f}}{\dif \boldsymbol{\rho}^5} \cdot (\boldsymbol{v}_1)^{\otimes 5}
	\end{aligned}
\end{equation*}
Combine the terms we obtain:
\begin{equation*} 
	\begin{gathered}
		\dfrac{ \dif \boldsymbol{f}}{\dif \boldsymbol{\rho}} \cdot \boldsymbol{\rho}^{(5)}  = \boldsymbol{b}_4 + 10c_1 \boldsymbol{b}_3 + (15c_1^2+10c_2) \boldsymbol{b}_2 + (10c_1c_2+5c_3) \boldsymbol{b}_1 \\
	\end{gathered}
\end{equation*}
\begin{equation*}
	\begin{aligned}
		\boldsymbol{b}_4 & = - 5\dfrac{ \dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \cdot \left(\boldsymbol{v}_4 \otimes \boldsymbol{v}_1\right) - 10\dfrac{ \dif^2 \boldsymbol{f}}{\dif \boldsymbol{\rho}^2} \cdot \left(\boldsymbol{v}_3  \otimes \boldsymbol{v}_2\right) - 10\dfrac{ \dif^3 \boldsymbol{f}}{\dif \boldsymbol{\rho}^3}\cdot \left(\boldsymbol{v}_3  \otimes (\boldsymbol{v}_1)^{\otimes 2}\right) \\ 
		& \quad - 15\dfrac{ \dif^3 \boldsymbol{f}}{\dif \boldsymbol{\rho}^3}\cdot \left( (\boldsymbol{v}_2)^{\otimes 2} \otimes \boldsymbol{v}_1 \right) - 10\dfrac{ \dif^4 \boldsymbol{f}}{\dif \boldsymbol{\rho}^4} \cdot \left(\boldsymbol{v}_2  \otimes (\boldsymbol{v}_1)^{\otimes 3}\right) - \dfrac{ \dif^5 \boldsymbol{f}}{\dif \boldsymbol{\rho}^5} \cdot \left(\boldsymbol{v}_1\right)^{\otimes 5}
	\end{aligned}
\end{equation*}
If the rank of the augmented matrix formed by $\dif \boldsymbol{f}/\dif \boldsymbol{\rho}$ and $\boldsymbol{b}_4$ is $n_\rho$, the configuration $\boldsymbol{\rho}$ is fifth-order rigid. Otherwise, if the rank of the above augmented matrix is $n_\rho-1$, the configuration $\boldsymbol{\rho}$ is fifth-order flexible. Therefore, the indeterminacy $c_1, ~c_2, ~c_3$ has no effect in determining the fifth-order rigidity. The space for $\boldsymbol{\rho}^{(5)}$ is:
\begin{equation*}
	\begin{gathered}
		\boldsymbol{\rho}^{(5)} = \boldsymbol{v}_5 + 10c_1\boldsymbol{v}_4 + (15c_1^2+10c_2)\boldsymbol{v}_3 + (10c_1c_2+5c_3)\boldsymbol{v}_2+c_4\boldsymbol{v}_1 \\
		\boldsymbol{v}_5 = \left(\dfrac{\dif \boldsymbol{f}}{\dif \boldsymbol{\rho}}\right)^{+} \boldsymbol{b}_4 
	\end{gathered}
\end{equation*}

Follow our calculation to the fifth order, we conclude that the coefficients for $\boldsymbol{\phi}^{(i)}$ ($i \in \mathbb{Z}_+$) in Proposition~\ref{prop: 1k flex} are determined by the Faà di Bruno formula applied to $\mathrm{d}^i \boldsymbol{f}/\mathrm{d} t^i$. To illustrate:

\begin{itemize}
	\item $\boldsymbol{\phi}''' = \boldsymbol{\rho}''' - 3c_1 \boldsymbol{\phi}'' - c_2 \boldsymbol{\rho}'$
	\begin{itemize}
		\item $3c_1$: from the coefficient 3 in $3 \mathrm{d}^2 \boldsymbol{f}/\mathrm{d} \boldsymbol{\rho}^2 \cdot (\boldsymbol{\rho}'' \otimes \boldsymbol{\rho}')$, with $c_1$ comes from $\boldsymbol{\rho}''$.
	\end{itemize}

	\item $\boldsymbol{\phi}^{(4)} = \boldsymbol{\rho}^{(4)} - 6c_1 \boldsymbol{\phi}''' - (3c_1^2 + 4c_2) \boldsymbol{\phi}'' - c_3 \boldsymbol{\rho}'$
	\begin{itemize}
		\item $6c_1$: from $6 \mathrm{d}^3 \boldsymbol{f}/\mathrm{d} \boldsymbol{\rho}^3 \cdot (\boldsymbol{\rho}'' \otimes \boldsymbol{\rho}' \otimes \boldsymbol{\rho}')$, with $c_1$ comes from $\boldsymbol{\rho}''$.
		\item $3c_1^2$: from $3 \mathrm{d}^2 \boldsymbol{f}/\mathrm{d} \boldsymbol{\rho}^2 \cdot (\boldsymbol{\rho}'' \otimes \boldsymbol{\rho}'')$, with $c_1$ comes from $\boldsymbol{\rho}''$.
		\item $4c_2$: From $4 \mathrm{d}^2 \boldsymbol{f} /\mathrm{d} \boldsymbol{\rho}^2 \cdot (\boldsymbol{\rho}''' \otimes \boldsymbol{\rho}')$, with $c_2$ comes from $\boldsymbol{\rho}'''$.
	\end{itemize}
\end{itemize}

By applying this pattern, we derive the coefficients for all higher-order terms $\boldsymbol{\phi}^{(i)}$ in Proposition~\ref{prop: 1k flex}.

