\section{Algorithm}
\label{sec:algorithm}
% ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
The algorithm below summarizes the steps involved in calculating $\kappa_{\mathrm{SCE}}$.\\

\begin{algorithm}[H]
\caption{$\kappa_{\mathrm{SCE}}$ for the solutions to $u = G(u)$}
\label{alg:sce_roots}
\begin{algorithmic}
\Require PGF $G(x)$ generating the distribution $\{p_\ell\}_{\ell=0}^m$ representing the probability a random individual has $\ell$ neighbors or the number of offspring in a branching process.
\Ensure Statistical condition estimate $\kappa_{\mathrm{SCE}}$
\State Solve for solution $u^*$ to $u = G(u)$.

\State Generate the $m\times r$  matrix $\widetilde{Z}$ by drawing $\tilde{z}_{ij} \stackrel{iid}{\sim} \mathrm{N}(0,1)$ and orthonormalize this matrix to obtain $[\mathbf{z}^{(1)}, \dots, \mathbf{z}^{(r)}]$ via QR decomposition.
\State Choose $\delta$.
\For{$i = 1, \dots, r$}
    \State (a) Solve $\tilde{u}$ = $\tilde{G}(\tilde{u})$, where $\tilde{G}(u)$ has coefficients:
    \[
    \tilde{p}_\ell  = \frac{p'_\ell}{\sum p'_\ell} , \quad p'_\ell = p_\ell(1 + \delta \mathbf{z}_\ell^{(i)}).
    \]

    \State (b) Calculate the component-wise sensitivity:
    \[
    \nu^{(i)} = \frac{|\tilde{u} - u^*|}{\delta |u^*|}.
    \]
\EndFor
\State Compute the $r$-sample component-wise $\kappa_{\textrm{SCE}}$ vector:
\[
\kappa_{\mathrm{SCE}} = \frac{\omega_r}{\omega_m} \sqrt{|\nu^{(1)}|^2 + \dots + |\nu^{(r)}|^2}.
\]
\end{algorithmic}
\end{algorithm}



