\subsection{Notation}~~



Next we introduce some notation that will be used throughout the paper.


\begin{itemize}
\item For some positive constant \(C\) independent of the main parameters, we denote \(A \lesssim B\) to mean that \(A \leq CB\), and \(A \approx B\) to indicate that \(A \lesssim B\) and \(B \lesssim A\). Additionally, \(A \lesssim_{\alpha, \beta} B\) signifies that \(A \leq C_{\alpha,\beta} B\), where \(C_{\alpha,\beta}\) depends on \(\alpha\) and \(\beta\).
\item 
We say \(\omega: X \rightarrow [0, \infty]\) is a weight, if $\omega$ is a locally integrable function satisfying \(0 < \omega(x) < \infty\) almost everywhere. We define the measure \(d\omega(x) = \omega(x)d\mu(x)\) and \(\omega(E) = \int_E \omega \,d\mu\) for measurable \(E \subseteq X\).
\item 
Let \(\vec{r} = (r_i)_{i=1}^m\) and \(\vec{p} = (p_i)_{i=1}^m\). We write \(\vec{r} \leq \vec{p}\) if \(r_j \leq p_j\) and \(\vec{r} < \vec{p}\) if \(r_j < p_j\) for all \(j = 1, \dots, m\). We write \((\vec{r}, s) \stackrel{}{\prec} (\vec{p}, q)\) if \(\vec{r} < \vec{p}\) and \(q < s\); we write \((\vec{r}, s) \stackrel{}{\prec^*} (\vec{p}, q)\) if \(\vec{r} \leq \vec{p}\) and \(q < s\), and we write \((\vec{r}, s) \preceq^{} (\vec{p}, q)\) if \(\vec{r} \leq \vec{p}\) and \(q \leq s\).
\item
We denote $\vec{f}=\left(f_1, \ldots, f_m\right)$ and $\vec{f} \chi_E=\left(f_1 \chi_E, \ldots, f_m \chi_E\right)$ for any measurable set $E$. Let $r \in[1, \infty)$, $0 \leq \eta <1$ such that $0\leq\eta r <1$. For any $B \in \mathcal{B}$, 
the fractional average bump of $f$ is defined by 
$$\langle f\rangle_{\eta,r,B}:=\left(\frac{1}{\mu(B)^{1-\eta r}}\int_Bf^r d \mu\right)^{\frac{1}{r}};$$
the fractional maximal average bump of $f$ is set by
\begin{align}\label{avggg}
{{{\left\langle {\left\langle {{f}} \right\rangle } \right\rangle }_{\eta ,r,B}}}:=\sup _{B^{\prime} \in \mathcal{B}: B^{\prime} \supseteq B}\langle |f|\rangle_{\eta,r,B^{\prime}}.
\end{align}
%The notation $d \cdot$ means that the integral variable of the mean integral is $`` \cdot ''$. Unless otherwise stated, it is generally omitted.
When $r=1$, we always denote ${{{\left\langle {\left\langle {{f_i}} \right\rangle } \right\rangle }_{\eta,B}}}:={{{\left\langle {\left\langle {{f_i}} \right\rangle } \right\rangle }_{\eta ,r,B}}}$ and $\langle f\rangle_{\eta,B}:=\langle f\rangle_{\eta,r,B}$.
When $\eta=0$, we denote them by ${{{\left\langle {\left\langle {{f_i}} \right\rangle } \right\rangle }_{r,B}}}$ and $\langle f\rangle_{r,B}$ respectively.
\item  A subset \(E \subseteq X\) is termed \textbf{bounded} if there exists some \(B \in \B\) satisfying  $ E \subseteq B$.
When \(E\) and \(F\) are measurable, we say that \(E\) is \textbf{almost surely} contained in \(F\), written $E \subseteq F \ \text{a.s.}$
precisely when $  \mu\bigl(E \setminus F\bigr) \;=\; 0.$
For any finite set \(A\), its cardinality is denoted by \(\#A\).  
\end{itemize}

\subsection{Some conceptions}~~

\begin{definition}

Let $(X,\mu,\mathcal{B})$ is a ball-basis measure space. Set $\delta \in (0,1)$ and we say $\mathcal{S} \subseteq \mathcal{B}$ is a $\delta$-sparse family, if for each $Q \in \mathcal{S}$, there exists a measurable subset $E_Q \subseteq Q$ with $\mu(E_Q) \geq \delta \mu(Q)$, and $\{E_Q\}_{Q \in \mathcal{S}}$ is a pairwise disjoint family.

\end{definition}



\begin{definition}
Let $m \in \mathbb{N}$, $ r_1,\ldots,r_m \in [1, \infty)$, $\eta_i \in [0,1)$ with \( 0 \le \eta_i r_i \leq 1\), for $i=1,\cdots,m$, and the fractional total order $\eta := \sum\limits_{i=1}^{m}\eta_i \in [0,m)$. Suppose that ${\bf t,k }\in \N_0^m$ with \(\mathbf{0} \le \mathbf{t} \leq \mathbf{k}\), and multi-symbol $\mathbf{b}=\left(b_1, \ldots, b_m\right) \in\left(L_{l o c}^1(X)\right)^m$. For a sparse family $\mathcal{S} \subseteq \mathcal{B}$, we define the \textbf{higher-order multi-symbol $m$-linear fractional sparse operator} 
$\mathscr{A}_{\vec{\eta},\mathcal{S},\vec{r}}^{\mathbf{b},\mathbf{k},\mathbf{t}}$   defined by
\begin{align*}
{\mathscr A}_{\vec{\eta},\S,{\vec r}}^\mathbf{b,k,t}(\vec{f})(x)=&\sum_{B \in \mathcal{S}} \mu(B)^{\eta} \prod_{i = 1}^m\left|b_i(x) - b_{i,B}\right|^{k_i - t_i} \left\langle\left|f_i (b_i - b_{i,B})^{t_i}\right|\right\rangle_{r_i,B}  \chi_B(x)\\
=&\sum_{B \in \mathcal{S}}  \prod_{i = 1}^m\left|b_i(x) - b_{i,B}\right|^{k_i - t_i} \left\langle\left|f_i (b_i - b_{i,B})^{t_i}\right|\right\rangle_{\eta_i,r_i,B}  \chi_B(x).
\end{align*}
We tend to denote ${\mathscr A}_{\vec{\eta},\S,{\vec r}}^\mathbf{b,k,t}$ by ${\mathscr A}_{\eta,\S,{\vec r}}^\mathbf{b,k,t}$.
When ${\bf k}=(0,\cdots,k_i,\cdots,0)$, we denote it by ${\mathscr A}_{{\eta},\S,{\vec r}}^{b_i,k_i,t_i}$. When $\bf k=0$, we denote it by ${\mathscr A}_{{\eta},\S,{\vec r}}$.
\end{definition}





