Let ${\bf b} \in {\left( {L_{loc}^1\left( X \right)} \right)^m}$. Given a $m$-sublinear operator $T$ and a multi-index \(\mathbf{k} = (k_1, \ldots, k_{m}) \in (\N_0)^m \), its generalized commutator can be defined by 
\begin{align*}
T^{{\bf b, k}}(\vec{f})(x):=T\left((b_1(x) - b_1)^{k_1}f_1,\ldots,(b_m(x) - b_m)^{k_m}f_m\right)(x),
\end{align*}

All of our main results pertain to the study of the generalized commutators $T^{\bf b,k}$ of order $|\bf k|$. Here, we need to clarify:
\begin{itemize}
\item When $|{\bf k}|=0$, $T^{\bf b,k}=T$ called '0-order commutator'.
\item When $|{\bf k}|=1$, $T^{\bf b,k}=T^{b_i,1}$ for $i=1,\cdots,m$, called "1-order commutator". 
The classcial multilinear commutator $T^{\sum \bf b}:=\sum\limits_{i = 1}^m {T^{{b_i},1}}$ is initially introduced in \cite{Perez2009} for multilinear Calder\'{o}n--Zygmund operators and multilinear maximal operators.

\item When $|{\bf k}| \ge 2$, $T^{\bf b,k}$ is called "higher-order commutator" studied in \cite{Xue2021} for multilinear Calder\'{o}n--Zygmund operators and multilinear Littlewood-Paley square operators.

\item When $|{\bf k}|=m$ with $k_1=\cdots=k_m$=1, $T^{\bf b,k}$ is called "multilinear iterated commutators" initially introduced in \cite{Perez2013,Xue2013} for multilinear Calder\'{o}n--Zygmund operators, multilinear fractional maximal operators, and multilinear fractional integral operators.
\end{itemize}
Over the past 15 years, researchers have often considered multilinear singular integral operators with (fractional) Calder\'{o}n--Zygmund kernels. Our main results below center on generalized commutators $T_{\vec{\eta}}^{\bf b,k}$, which cover all of the above cases and extend their work.  Because of the different applicable spaces of the theorems, we always set the ball-basis measure space $(X,\mu,\mathcal{B})$, space of homogeneous type $(X,d,\mu,\mathcal{D})$, and classical Euclidean space $(\rn,|\cdot|,dx,\mathcal{D})$ as the base space we need at the beginning, where $\mathcal{D}$ is a fixed dyadic grid of the base spaces and $|\cdot|$ is the Euclidean distance.  These base spaces form successively specialized cases.




\begin{definition}\label{def:FBMOO}
Let \(r_i \in [1, \infty)\), \(s_1, s_2,s_3\in [1, \infty]\), $\eta_i \in [0,1)$ with \( 0 \le \eta_i r_i \leq 1\), for $i=1,\cdots,m$, and the fractional total order $\eta := \sum\limits_{i=1}^{m}\eta_i \in [0,m)$. Set \(\mathbb{V}\) is a quasi-Banach space and \((X, \mu, \mathcal{B})\) is a ball-basis measure space. We say \({T}_{\vec\eta}\) is a \(\mathbb{V}\)-valued  {\bf $m$-(sub)linear  fractional bounded mean oscillation operator} {\rm ($m$-FBMOO)} on \((X, \mu, \mathcal{B})\), if there exists  uniform contants \({C}_{1}:={C}_{1}({T}_{\vec \eta})>0, {C}_{2}:={C}_{2}({T}_{\vec \eta}) > 0\),
such that for all nonnegative $\vec f \in \prod\limits_{i = 1}^m {{L^{{r_i}}}(X)}$,
\begin{list}{\rm (\theenumi)}{\usecounter{enumi}\leftmargin=1.2cm \labelwidth=1cm \itemsep=0.2cm \topsep=.2cm \renewcommand{\theenumi}{m-FBMOO-\Roman{enumi}}}
    \item\label{M_1.condi.} 
    For every $B_0 \in \B$ with $B_0^{\dagger} \subsetneq X$, there exists $B \in \B$ with $B \supsetneq B_0$ such that 
    \begin{align*} 
{\left\langle\|T_{\vec\eta}(\vec{f} \chi_{B^\dagger})(\cdot)-T_{\vec\eta}(\vec{f} \chi_{B^\dagger_0})(\cdot)\|_{\mathbb{V}}\right\rangle_{s_1,B_0}} \leq {{C}_{1}}{\prod\limits_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B^\dagger}},
	\end{align*}

	\item\label{M_2.condi.} For every $B \in \B$,  
	\begin{align*}
{\left \langle \left\langle \left\|\left(T_{\vec\eta}(\vec{f})(x)-T_{\vec\eta}(\vec{f}\chi_{B^\dagger})(x) \right)- \left(T_{\vec\eta}(\vec{f})(x') -T_{\vec\eta}(\vec{f}\chi_{B^\dagger})(x')\right)\right\|_\mathbb{V}\right\rangle_{s_2,B \ni x'} \right\rangle_{s_3,B \ni x}} \leq {{C}_{2}} \prod\limits_{i = 1}^m {{{\left\langle {\left\langle {{f_i}} \right\rangle } \right\rangle }_{{\eta _i},{r_i},B}}}.
	\end{align*}
	\end{list}
%When $T_{\eta}$ is a complex-valued operator, that is, $\mathbb{V}=\mathbb{C}$, we will drop $\mathbb{V}$-valued and $\|\cdot\|_{\mathbb{V}}$.
In the absence of ambiguity, we omit the "$\mathbb{V}$-valued" from the narrative and denote \( T_{\vec{\eta}} \) as \( T_{\eta} \).
	\end{definition}

%where the $\langle \cdot \rangle_{s_2,B,x}$ denotes the mean integral over the independent variable $x$.

\begin{remark}\label{rem:key1}
The liberalization of {\rm $m$-FBMOOs} is reflected in the significant reduction of the oscillation requirements. In fact, if $s_1=s_2=s_3=\infty$ and at the same time setting $\vec{\eta}=0$, Definition \ref{def:FBMOO} can return to \cite[Definition 1.3]{K2019} and \cite[Definition 1.4]{Cao23}. Here, we tend to describe their definition as \textbf{\textsf{full uniform upper bound}}, while \eqref{M_1.condi.} and \eqref{M_2.condi.} are more general and called, \textbf{\textsf{mean uniform upper bound}}. This consideration extends the diversity and complexity of operators.
\end{remark}







We introduce our key precondition, called local weak-type estimate, as follows. This idea was partly inspired by Lerner and Ombrosi, cf. \cite[p.1012]{Lerner19}, although it is indeed somewhat different from theirs.

\begin{definition}\label{def:multilinear_W}
%Let $\mathcal{T}_{\eta}$ be an $m$-linear fractional operator satisfying the weak $(\vec{p}, q)$ type estimate with indices $\vec{p} = (p_1, \dots, p_m)$ and $q$ related by $\frac{1}{q} = \sum_{i=1}^m \frac{1}{p_i} - \eta$, $\eta \in [0,m)$.
Let \((X, \mu, \mathcal{B})\) be a ball-basis  measure space. Let \(m \in \mathbb{N}\), $\eta \in [0,m)$, $r_i \in (1,\infty)$ for \(i =1,\cdots,m\), and $\frac{1}{\tilde{r}}:=\sum\limits_{i = 1}^m {\frac{1}{{{r_i}}}}  - \eta>0$. Set $\mathbb{V}$ be a quasi-Banach spaces, and $G$ be a $\mathbb{V}$-valued $m$-sublinear operator. We write $G \in W_{\vec{r},\tilde{r}}$, if there exists a function $\Phi_{G,\vec{r}, \tilde{r}}:\left( {0,1} \right) \to \left( {0,\infty } \right) $, such that for every $Q \in \B$, any $R \in \B$ with $ R  \supseteq Q$, and any $f_i \in L^{r_i}(R)$, $1 \leq i \leq m$,
\[
 \mathop {\sup }\limits_{\lambda  \in \left( {0,1} \right)} \lambda^{-1} \mu\left(\left\{ x \in Q : 
 \|G(f_1\chi_R, \dots, f_m\chi_R)(x)\|_{\mathbb{V}} > \Phi_{G,\vec{p}, q}(\lambda) \mu(Q)^{\eta} \prod_{i=1}^m \langle f_i\rangle_{r_i, Q} \right\}\right) \leq \mu(Q).
\]
When $G:{L^{{r_1}}} \times  \cdots  \times {L^{{r_m}}} \to {L^{\tilde r,\infty }(\mathbb{V})}$ is bounded, then $G \in W_{\vec{r},\tilde{r}}$ with $$\Phi_{G,\vec{r},\tilde{r}}(\lambda) = \|G\|_{L^{r_1}(X) \times \cdots \times L^{r_m}(X) \to L^{\tilde{r},\infty}(X,\mathbb{V})} \cdot \lambda^{-1/\tilde{r}}.$$
\end{definition}





