\subsection{Multilinear fractional sparse $T1$ theorem}
~~

Next, since operators in this subsection always assumes a definite kernel representation, the operator only depends on the fractional total order $\eta$ of the kernel. For convenience, we replace $T_{\vec \eta}$ with $T_{\eta}$.

Under the setting of $(\rn, |\cdot|, dx,\d)$, cf. Remark \ref{example_0}. The multilinear fractional sparse $T1$ theorem for the generalized commutators of {\rm $m$-FBMOO} is established as follows.

\begin{theorem}\label{thm:sparse-T1}
Let \( \eta \in [0,m) \) and \( \mathbf{k} \in \mathbb{N}_0^m \). Let \( T_\eta \) be a \( \mathbb{V} \)-valued \textit{$m$-FBMOO} on \( (\mathbb{R}^n, |\cdot|, dx, \mathcal{D}) \), which admits a \textbf{\textsf{$\mathbb{V}$-valued $m$-linear fractional Calderón-Zygmund kernel representation}} (cf. Definition \ref{def:full}).  Suppose that
\begin{align}
\mathcal{N} := {\left\| T_{\eta}^{\bf{b,k}} \right\|_{{WBP}_{\eta}^{\bf b,k}(\mathbb{V})}} + \sum\limits_{j = 0}^m {{{\left\| {T_{\eta}^{{\bf{b,k}},j*}(1, \cdots ,1)} \right\|}_{\BMO_{2,\eta}(\mathbb{V})}}}. \label{cond.N}
\end{align}
If $\vec b \in (\BMO)^m$ and $\mathcal{N} < \infty$, then there is a sparse family $\calS \subseteq \d$, such that for any nonnegative $f_i \in L_b^\infty$, $i=1,\cdots,m$, and nonnegative $\psi \in L_b^\infty$,
\begin{align*}
\left\langle {\Big\|T_{\eta }^{\bf{b,k}} (\vec f)\Big\|_{\mathbb{V}},\psi} \right\rangle { \lesssim _{\eta ,n,\delta ,\mathcal{N} }} \prod\limits_{i = 1}^m {\left\| {{b_i}} \right\|_{\BMO}^{{k_i}}} \cdot{{\calA}_{\eta ,\calS,\vec 1,1}}\left( {\vec f,\psi} \right).
\end{align*}

where
$
\calA_{\eta,\mathcal{S},\vec{1},1}\left(\vec{f}, \psi\right):=\sum_{Q \in \mathcal{S}}|Q|^{\eta+1}\prod_{i=1}^m\langle | f_i| \rangle_Q\langle |\psi| \rangle_Q .
$
\end{theorem} 

\begin{remark}\label{rem:key3}
We note that once an {\rm $m$-FBMOO} has a fractional Calderón-Zygmund kernel representation, we can replace the condition $W_{\vec{r},\tilde{r}}$ by the condition $\mathcal{N}$, which is indeed more interesting than the previous sparse bounds results.
\end{remark}

Theorem \ref{thm:sparse-T1} indeed can be deduced from the dyadic representation result--Theorem \ref{thm:DT} and the dyadic sparse bounds result--Theorem \ref{thm:d.s.d.} for dyadic model operators. 
Thus, it suffices to prove the two theorems in Sect. \ref{T1}.

%Now we introduce the multilinear dyadic representation for the generalized commutators of $m$-FBMOO.
\begin{theorem}\label{thm:DT} 
Let \( \eta \in [0,m) \) and \( \mathbf{k} \in \mathbb{N}_0^m \). Fix a random dyadic grid \( \mathcal{D}_\omega \), and let \( T_\eta \) be a \( \mathbb{C} \)-valued \textit{$m$-FBMOO} on \( (\mathbb{R}^n, |\cdot|, dx, \mathcal{D}_\omega) \) as in Definition \ref{def:FBMOO}, which admits a \textbf{\textsf{$\mathbb{C}$-valued $m$-linear Calderón-Zygmund kernel representation}}. Suppose that
\[\mathcal{N} = {\left\| T_{\eta}^{\bf{b,k}} \right\|_{{{WBP}_{{\eta}}^{\bf b, k}}(\mathbb{C})}} + \sum\limits_{j = 0}^m {{{\left\| {T_{\eta}^{{\bf{b,k}},j*}(1, \cdots ,1)} \right\|}_{\BMO_{2,\eta}(\mathbb{C})}}}.\]
If $\vec b \in (\BMO)^m$ and $\mathcal{N} < \infty$, then 
$T_{\eta}^{\bf{b,k}}$ admits an $m$-linear dyadic  representation. That is, there is a constant $C_{n,\delta}<\infty$, such that for every $f_i \in L_b^\infty$, $i=1,\cdots,m$, and $\psi \in L_b^\infty$, we have
\begin{align*}
\left\langle {T_{\eta }^{\bf{b,k}}(\vec{f}),\psi} \right\rangle  = C_{\eta,n,\delta,\mathcal{N},C_{K_\eta}}\cdot{\mathbb{E}_\omega }\sum\limits_{l = 0}^\infty  {{2^{ - \delta k/2}}\left\langle {U_{\eta, \omega }^{{\bf{b,k}},l}\left( {\vec f} \right),\psi} \right\rangle }  
\end{align*}
where $U_{\eta, \omega}^{{\bf{b,k}},l}$ is a finite sum of $U_{\eta, \omega}^{{\bf{b,k}},i, l}$ that denotes some fractional dyadic model operators and their adjoints of such operators, cf. Sect. \ref{T1}.
\end{theorem}






\subsection{Multiparameter multilinear fractional weight class and multilinear off-diagonal extrapolation theorem}~~

In this subsection, we first introduce a class of multiparameter multilinear fractional weights.

\begin{definition}\label{def:weight}
Let $(X, \mu,\B)$ be a ball-basis measure space. 
Let $\eta \in [0,m)$, $\vec{r}=(r_i)_{i=1}^m$ with $0<r_1, \ldots, r_m <\infty$, $\vec{p}=(p_i)_{i=1}^m$ with $0 <p_1, \ldots, p_m,s \leq \infty$, and $\frac{1}{\tilde{p}}=\sum\limits_{i=1}^m \frac{1}{p_i} - \eta $ such that $(\vec{r}, s) \preceq (\vec{p},\tilde{p})$.  

We say that $\vec{\omega} \in A^{\B}_{(\vec{p},\tilde{p}),(\vec{r}, s)}$, if
$$
[\vec{\omega}]_{A^{\B}_{(\vec{p},\tilde{p}),(\vec{r}, s)}}:=\sup _{B \in \B}\left(\prod_{j=1}^m\left\langle \omega_j^{-1}\right\rangle_{{\frac{1}{\frac{1}{r_j}-\frac{1}{p_j}}},B}\right)\langle \omega \rangle_{\frac{1}{\frac{1}{\tilde{p}}-\frac{1}{s}},B}<\infty,
$$
where $\omega:=\prod\limits_{i = 1}^m {{\omega _i}}$.
We say that $\vec{\omega} \in A^{\star,\B}_{(\vec{p},\tilde{p}),(\vec{r}, s)}$, if
\begin{align*}
[\vec{\omega}]_{A^{\star,\B}_{(\vec{p},\tilde{p}),(\vec{r}, s)}}&:=[\omega^{\frac{1}{\tilde{p}}},\omega_1^{\frac{1}{p_1}},\ldots,\omega_m^{\frac{1}{p_m}}]^{\tilde{p}}_{A^{\B}_{(\vec{p},\tilde{p}),(\vec{r}, s)}}\\
	&=\sup _{B \in \B}\left(\prod\limits_{j=1}^m\left\langle \omega_j^{-\frac{1}{p_j}}\right\rangle^{\tilde{p}}_{{\frac{1}{\frac{1}{r_j}-\frac{1}{p_j}}},B}\right)\langle \omega^{\frac{1}{\tilde{p}}} \rangle^{\tilde{p}}_{\frac{1}{\frac{1}{\tilde{p}}-\frac{1}{s}},B}<\infty,
\end{align*}
where $\omega:=\prod\limits_{i=1}^{m}\omega_i^{\frac{\tilde{p}}{p_i}}$. 

For the sake of convenience, we denote $A^{\B}_{(\vec{p},\tilde{p}),(\vec{r}, s)}$ by $A_{(\vec{p},\tilde{p}),(\vec{r}, s)}$ and denote $A^{\star,\B}_{(\vec{p},\tilde{p}),(\vec{r}, s)}$ by $A^{\star}_{(\vec{p},\tilde{p}),(\vec{r}, s)}$. 


% Moreover when $\vec r = \vec 1$, $s = \infty$, we denote ${\left[ \vec{\omega} \right]_{{A^{\star,\B}_{(\vec{p},\tilde{p}),(\vec{r}, s)}}}}$ by $[\vec \omega]_{A_{\vec p,\tilde{p}}^{\star,\B}}$.

