   \item[(2)] Let $B \in \B$ and $E_B \subseteq B$ such that $\mu(B) \leq \delta\mu(E_B)$ with $\delta \in (0,1)$. Then
\begin{align}\label{def.of.weighted.condi._2}
\left\langle v\right\rangle_{1, B}^{\frac{1}{s'}}\left(\prod_{j=1}^{m}\left\langle v_j\right\rangle_{1,B}^{\frac{1}{r_j}}\right)\mu(B)^{1 + \eta} \leq C_{\delta} [\vec{\omega}]_{A^{\B}_{(\vec{p},\tilde{p}),(\vec{r}, s)}}^{\varTheta} v(B)^{\frac{1}{\tilde{p}'}} \prod_{j=1}^{m} v_j(E_B)^{\frac{1}{p_j}},
   \end{align}
   where $C_\delta = \delta^{(\varTheta - 1)\left[\sum\limits_{i=1}^m\left(\frac{p_i - r_i}{r_ip_i}\right)+ \frac{\tilde{p}'-s'}{\tilde{p}'s'}\right]}$ and $\varTheta =\max \left\{ {\frac{{{p_1}}}{{{p_1} - {r_1}}}, \cdots ,\frac{{{p_m}}}{{{p_m} - {r_m}}},\frac{{\tilde{p}'}}{{\tilde{p}' - s'}}} \right\}$.
\end{itemize}
\end{remark}










Next, we establish multilinear off-diagonal extrapolation theorem for multiparameter multilinear fractional weight class $A_{(\vec{p},\tilde{p}), (\vec{r},s)}$.
\begin{theorem}\label{thm:Ex_1}
Let $(X,d,\mu,\mathcal{D})$ be a space of homogeneous type. Let $\eta \in [0,m)$, $\vec{r} = (r_i)_{i=1}^m \in [1, \infty)^m$, and \(s' \in [1, \infty)\). Let $\mathcal{G}$ be a collection of $(m+1)$--tuples of non-negative functions. Given $\vec{p} := (p_i)_{i=1}^m$, $\frac{1}{\tilde{p}} := \sum\limits_{i=1}^{m}\frac{1}{p_i} - \eta>0$ satisfying \((\vec{r}, s)  \preceq (\vec{p}, \tilde{p})\), assume that for all $\vec{\omega}= (\omega_i)_{i=1}^m \in A_{(\vec{p},\tilde{p}), (\vec{r},s)}$, 
\begin{align}\label{eq:iioo:1.2}
	\|g\|_{L^{\tilde{p}}(\omega^{\tilde{p}})} \le C\left([\vec \omega]_{A_{(\vec{p},\tilde{p}),(\vec r,s)}}\right) \prod_{i=1}^m \|f_i\|_{L^{p_i}(\omega_i^{p_i})}, \quad \text{for every } (g, f_1, \dots, f_m) \in \mathcal{G}, 
	\end{align}
	where $\omega=\prod\limits_{i=1}^m \omega_i$. Then, for all $\vec{q}:= (q_i)_{i=1}^m$, $\frac{1}{\tilde{q}} := \sum\limits_{i=1}^{m}\frac{1}{q_i} - \eta>0$ with $(\vec{r},s) \prec (\vec{q},\tilde{q})$ and for all $\vec{v}=(v_i)_{i=1}^m \in A_{(\vec{q},\tilde{q}), (\vec{r},s)}$, 
	\begin{align}\label{eq:iioo:1.3}
	\|g\|_{L^{\tilde{q}}(v^{\tilde{q}})} \le C\left([\vec v]_{{(\vec{q},\tilde{q}), (\vec{r},s)}}\right) \prod_{i=1}^m \|f_i\|_{L^{q_i}(v_i^{q_i})}, \quad \text{for every }(g, f_1, \dots, f_m) \in \mathcal{G}, 
	\end{align}
	where $v=\prod\limits_{i=1}^m v_i$. 
Moreover, for the same family of exponents and weights, and for all exponents $\vec{t}= \left(t_1, \ldots, t_m\right)$ with $(\vec{r},s) \prec (\vec{t},\tilde{t})$
\begin{align}\label{eq:iioo:1.4}
\left\|\left(\sum_j\left(g^j\right)^{\tilde{t}}\right)^{\frac{1}{\tilde{t}}}\right\|_{L^{\tilde{q}}(v^{\tilde{q}})}  
\leq C\left([\vec{v}]_{A_{(\vec{q},\tilde{q}), (\vec{r},s)}}\right) 
\prod_{i=1}^m\left\|\left(\sum_j\left(f_i^j\right)^{t_i}\right)^{\frac{1}{t_i}}\right\|_{L^{q_i}\left(v_i^{q_i}\right)},
\end{align}
for all $\left\{\left(g^j, f_1^j, \ldots, f_m^j\right)\right\}_j \subseteq \mathcal{G}$ and where $\frac{1}{\tilde{t}}:=\frac{1}{t_1}+\cdots+\frac{1}{t_m}-\eta>0$.


\end{theorem}


\begin{remark}\label{li:remark:1.8}
Fixed $i \in \{1,\dotsc,m\}$, if we let $p_i = r_i$ in Theorem~\ref{thm:Ex_1}, then we can replace $q_i > r_i$ with $q_i \geq r_i$ to ensure that our conclusion is also valid. 

To justify this relaxation, we proceed in two steps:
\begin{itemize}
    \item On the one hand, for $q_i = p_i = r_i$, the result follows immediately from \eqref{eq:iioo:1.2} combined with  $\vec{r} \preceq \vec{q}$.
    \item On the other hand, for $q_i > p_i = r_i$, the result will be obtained by applying the extrapolation argument specifically to the $i$-th component.
\end{itemize}
\end{remark}




\begin{remark}\label{R:1}
Similar to the classical vector-valued extropolation theory, we can conclude that \eqref{eq:iioo:1.3} is equivalent to \eqref{eq:iioo:1.4}. We just show that \eqref{eq:iioo:1.3} implies \eqref{eq:iioo:1.4} since \eqref{eq:iioo:1.3} is obviously deduced from \eqref{eq:iioo:1.4}.

In fact, assume that \eqref{eq:iioo:1.3} is valid and fix $\vec{t}=\left(t_1, \ldots, t_m\right)$ with $(\vec{r},s) \prec (\vec{t},\tilde{t})$ where $\frac{1}{\tilde{t}}:=\sum_{i=1}^m \frac{1}{t_i} - \eta>0$. Define a new family $\mathcal{F}_{\vec{t}}$ consisting on the $m+1$-tuples of the form
\[
\left(G, F_1, \ldots, F_m\right)=\left(\left(\sum_j\left(g^j\right)^{\tilde{t}}\right)^{\frac{1}{\tilde{t}}},\left(\sum_j\left(f_1^j\right)^{t_1}\right)^{\frac{1}{t_1}}, \ldots,\left(\sum_j\left(f_m^j\right)^{t_m}\right)^{\frac{1}{t_m}}\right)
\]
where $\left\{\left(g^j, f_1^j, \ldots, f_m^j\right)\right\}_j \subseteq \mathcal{F}$. 
By monotone convergence theorem, it suffices to consider that all of the sums are finite. For all $\vec{v} \in A_{(\vec{t},\tilde{t}), (\vec{r},s)}$ with $v:=\prod_{i=1}^m v_i$ and every $\left(G, F_1, \ldots, F_m\right) \in \mathcal{F}_{\vec{t}}$, it follows from \eqref{eq:iioo:1.3} with $\vec{t}$ in place of $\vec{q}$ and Hölder's inequality that
\begin{align}\notag
\|G\|_{L^{\tilde{t}}(v^{\tilde{t}})}&=\left(\sum_j\left\|g^j\right\|_{L^{\tilde{t}}(v^{\tilde{t}})}^{\tilde{t}}\right)^{\frac{1}{\tilde{t}}} \lesssim\left(\sum_j \prod_{i=1}^m\left\|f_i^j\right\|_{L^{\tilde{t_i}}\left({v_i}^{t_i}\right)}^{\tilde{t}}\right)^{\frac{1}{\tilde{t}}} \\ \label{eq:iioo:4.8}
& \leq \prod_{i=1}^m\left(\sum_j\left\|f_i^j\right\|_{L^{t_i}\left({v_i}^{t_i}\right)}^{\tilde{t_i}}\right)^{\frac{1}{\tilde{t_i}}}
\le \prod\limits_{i = 1}^m {{{\left( {\sum\limits_j {\left\| {f_i^j} \right\|_{{L^{{t_i}}}\left( {{v_i}^{t_i}} \right)}^{{t_i}}} } \right)}^{\frac{1}{{{t_i}}}}}}
=\prod_{i=1}^m\left\|F_i\right\|_{L^{t_i}\left({{v_i}^{t_i}}\right)},
\end{align}
where $\frac{1}{{{\tilde t_i}}}: = \frac{1}{{{t_i}}} - \frac{\eta }{m} \le \frac{1}{{{t_i}}}.$



%We can now apply the first part of Theorem \ref{thm:Ex_1} to $\mathcal{F}_{\vec{t}}$ where we use as our initial estimate \eqref{eq:iioo:4.8} in place of \eqref{eq:iioo:1.2}. 
Thus, \eqref{eq:iioo:1.3} is valid for $\mathcal{F}_{\vec{t}}$ and then \eqref{eq:iioo:1.4} derives from applying \eqref{eq:iioo:1.3} again for all $\vec{v} \in A_{(\vec{q},\tilde{q}), (\vec{r},s)}$ with $v:=\prod_{i=1}^m v_i$.
\end{remark}

Based on Remark \ref{R:1}, we further have
\begin{remark}
Under the same assumption of Theorem \ref{thm:Ex_1}, for the same family of exponents and weights, and for all exponents $\vec{R}= \left(R_1, \ldots, R_m\right)$ with $(\vec{r},s) \prec (\vec{R},\tilde{R})$, it follows from \eqref{eq:iioo:1.4} that
\begin{align}\label{eq:iioo:1.5}
{\left\| {{{\left( {\sum\limits_k {{{\left( {\sum\limits_j {{{\left( {{g^{j,k}}} \right)}^{\tilde t}}} } \right)}^{\frac{{\tilde R}}{{\tilde t}}}}} } \right)}^{\frac{1}{{\tilde R}}}}} \right\|_{{L^{\tilde q}}({v^{\tilde q}})}} \le C\left( {{{[\vec v]}_{{A_{(\vec q,\tilde q),(\vec r,s)}}}}} \right)\prod\limits_{i = 1}^m {{{\left\| {{{\left( {\sum\limits_k {{{\left( {\sum\limits_j {{{\left( {f_i^{j,k}} \right)}^{{t_i}}}} } \right)}^{\frac{{{R_i}}}{{{t_i}}}}}} } \right)}^{\frac{1}{{{R_i}}}}}} \right\|}_{{L^{{q_i}}}\left( {v_i^{{q_i}}} \right)}}},
\end{align}
for all $\left\{\left(g^{j,k}, f_1^{j,k}, \ldots, f_m^{j,k}\right)\right\}_{j,k} \subseteq \mathcal{G}$ and where $\frac{1}{\tilde{R}}:=\frac{1}{R_1}+\cdots+\frac{1}{R_m}-\eta>0$.
\end{remark}

We can apply Theorems \ref{est:form} and \ref{thm:Ex_1} to obtain
\begin{corollary}\label{cor:key1}
Let $(X,d,\mu,\mathcal{D})$ be a space of homogeneous type. Let $m \in \N$, $\eta \in [0,m)$, $r_1,\cdots,r_m ,s' \in [1,\infty)$, $p_1,\dots,p_m \in (1,\infty)$, and $\frac{1}{{{\tilde{p}}}}:=\sum\limits_{i = 1}^m {\frac{1}{{{p_i}}}}- \eta >0$. 
Assume that $T_\eta$ is an $m$-sublinear operator satisfying for any nonnegative functions $f_1,\cdots,f_m, \psi \in L_b^\infty(X)$,  
\[\left| {\left\langle {T_{\eta}(\vec f),\psi } \right\rangle } \right| \lesssim \sup_{\mathcal{S} \subseteq \mathcal{D}} \mathcal{A}_{\eta, \mathcal{S},\vec{r}, s'}(\vec{f},\psi).\]
If $(\vec{r}, s) \prec (\vec{p},\tilde{p})$ and $\vec{\omega} \in A_{(\vec{p},\tilde{p}),(\vec{r}, s)}$, then 
\begin{align*}
{\left\| T_{\eta} \right\|_{\prod\limits_{i = 1}^m {{L^{{p_i}}}(\omega _i^{{p_i}}) \to } {L^{\tilde{p}}}({\omega ^{\tilde{p}}})}}
&\lesssim 
\begin{cases}
[\vec{\omega}]^{\varTheta}_{A_{(\vec{p},\tilde{p}),(\vec{r}, s)}} & \text{if } \tilde{p}>1;\\
C\left( [\vec{\omega}]_{A_{(\vec{p},\tilde{p}),(\vec{r}, s)}}\right) & \text{if } 0<\tilde{p} \le 1,
\end{cases}
\end{align*}
where $\varTheta:=\max \left\{ {\frac{{{p_1}}}{{{p_1} - {r_1}}}, \cdots ,\frac{{{p_m}}}{{{p_m} - {r_m}}},\frac{{\tilde{p}'}}{{\tilde{p}' - s'}}} \right\}$.

Further, for the same family of exponents and weights, and for all exponents $\vec{t}= \left(t_1, \ldots, t_m\right)$ with $(\vec{r},s) \prec (\vec{t},\tilde{t})$,
\begin{align*}
\left\| \left\{ T_{\eta}(f_1^j, \cdots , f_m^j) \right\}_{\ell^{\tilde t}} \right\|_{L^{\tilde{p}}(\omega^{\tilde{p}})} 
&\lesssim \prod_{i=1}^m \left\| \left\{ f_i^j \right\}_{\ell^{t_i}} \right\|_{L^{p_i}(\omega_i^{p_i})}
\end{align*}

\end{corollary}

The quantitative multilinear off-diagonal extrapolation for the generalized commutators is given as the end of this part.
\begin{theorem}\label{op.to.jh}
Let $m \in \N$, $\eta \in [0,m)$, $r_1,\cdots,r_m ,s' \in [1,\infty)$, $p_1,\dots,p_m \in [1, \infty)$ and $\frac{1}{{\tilde{p}}}:=\sum\limits_{i = 1}^m {\frac{1}{{{p_i}}}} - \eta >0$, such that $(\vec{r}, s) \prec (\vec{p}, \tilde{p})$. Let $T_{\vec \eta}$ be an $m$--sublinear operator. 
Moreover, suppose that there exists an increasing functions $\phi:[1, \infty) \rightarrow[0, \infty)$. If for all weights $\vec{\omega} \in A_{(\vec{p},\tilde{p}),(\vec{r},s)}$ with $\omega:=\prod\limits_{i=1}^m \omega_i$, then 
\begin{align}\label{1t1}
	\left\|{T}_{\vec{\eta}}(\vec{f})\right\|_{L^{\tilde{p}}(\omega^{\tilde{p}})} \lesssim \phi\left([\vec \omega]_{A_{(\vec{p},\tilde{p}),(\vec{r},s)}}\right) \prod_{i=1}^m\left\|f_i\right\|_{L^{p_i}(\omega_i^{p_i})},
\end{align}
If ${\bf k }\in \N_0^m$ and ${\bf b}=\left(b_1, \ldots, b_m\right) \in \mathrm{BMO}^m$, then
\begin{align}\label{1tb}
\left\|{T}_{\vec{\eta}}^{{\bf b, k}}(\vec{f})\right\|_{L^{\tilde{p}}(\omega^{\tilde{p}})} \lesssim {\bf k}!{\phi}\left(\boldsymbol{c}_0[\vec \omega]_{A_{(\vec{p},\tilde{p}),(\vec{r},s)}}\right) [\vec{\omega}]^{{|\bf k}|\Xi}_{A_{(\vec{p},\tilde{p}),(\vec{r}, s)}}\prod_{i=1}^m\left\|b_i\right\|_{\mathrm{BMO}}^{k_i}\left\|f_i\right\|_{L^{p_i}(\omega_i^{p_i})},
\end{align}
where $\boldsymbol{c}_0=4^{ \sum_{i=1}^m \min \left\{p_i / \delta_i, p/ \delta_{m+1}\right\} / p_i}$ with $\frac{1}{p}:=\sum\limits_{i = 1}^m {\frac{1}{{{p_i}}}}$, $\Xi=\max \left\{ {\frac{{{p_1r_1}}}{{{p_1} - {r_1}}}, \cdots ,\frac{{{p_mr_m}}}{{{p_m} - {r_m}}},\frac{{\tilde{p}'s'}}{{\tilde{p}' - s'}}} \right\}$, and the notation is defined below Sect. \ref{Sec.extro}. 

Moreover, set $\vec{t}=(t_1,\cdots,t_m)$ and $\frac{1}{\tilde{t}}:=\sum_{i=1}^{m}\frac{1}{t_i}-\eta>0$ satisfying  $(\vec{r},s) \prec (\vec{t},\tilde{t})$. Then for all $(\vec{r}, s) \preceq (\vec{q}, \tilde{q})$ and for all $\vec{v} \in A_{(\vec{q},\tilde{q}),(\vec{r},s)}$ with $v:=\prod\limits_{i=1}^m v_i$, it follows from Theorem \ref{thm:Ex_1} that
\begin{align}\label{1tbv}
\left\|\left\{{T}_{\vec{\eta}}^{{\bf b, k}}\left(f_1^j, f_2^j, \ldots, f_m^j\right)\right\}_{\ell^{\tilde t}}\right\|_{L^{\tilde{q}}(v^{\tilde{q}})}  
\lesssim  \prod_{i=1}^m \|b_i\|_{\mathrm{BMO}}^{k_i} \cdot 
\prod_{i=1}^m\left\|\left\{f_i^j\right\}_{\ell^{\tilde t}}\right\|_{L^{q_i}\left(v_i^{q_i}\right)}.
\end{align}
\end{theorem}

