\subsection{Quantitative weighted estimates theorem}\label{weighted-estimates}
~~

\subsubsection{Sharp-type estimates}
~

We can realize the sharp quantitative weighted estimates by following ways.
The first theorem derives from $$\text{Theorem \ref{S.d.main} + Theorem \ref{thm:sparse-dom_1} + Theorem \ref{op.to.jh} + Theorem \ref{thm:Ex_1}}.$$
\begin{theorem}\label{thm:weighted1}
Let $(X,d,\mu,\mathcal{D})$ be a space of homogeneous type. Let $m \in \N$, $\eta \in [0,m)$, $r_1,\cdots,r_m ,s' \in [1,\infty)$, $p_1,\dots,p_m \in (1,\infty)$, and $\frac{1}{{{\tilde{p}}}}:=\sum\limits_{i = 1}^m {\frac{1}{{{p_i}}}}- \eta > 0$.
Set $T_{\vec \eta}$ be a $\mathbb{V}$-valued {\rm $m$-FBMOO} on $(X,d,\mu,\mathcal{D})$ as in Theorem \ref{S.d.main}, and ${T}_{\vec \eta} \in W_{\vec{r},\tilde{r}}$ with $\frac{1}{\tilde{r}} :=\sum\limits_{i=1}^{m}\frac{1}{r_i} -\eta>0$. 
If multi-symbol \(\mathbf{b} = (b_1, \ldots, b_{m}) \in (\BMO(X))^m\), $(\vec{r}, s) \prec (\vec{p},\tilde{p})$ and $\vec{\omega} \in A_{(\vec{p},\tilde{p}),(\vec{r}, s)}$, then  
\begin{align*}
{\left\| T_{\vec{\eta}}^{{\bf b, k}} \right\|_{\prod\limits_{i = 1}^m {{L^{{p_i}}}(\omega _i^{{p_i}}) \to } {L^{\tilde{p}}}({\omega ^{\tilde{p}}},\mathbb{V})}}
&\lesssim 
\prod_{i=1}^m \|b_i\|_{\mathrm{BMO}}^{k_i} \cdot [\vec{\omega}]^{\varTheta+{|\bf k}|\Xi}_{A_{(\vec{p},\tilde{p}),(\vec{r}, s)}},
\end{align*}
where $\varTheta:=\max \left\{ {\frac{{{p_1}}}{{{p_1} - {r_1}}}, \cdots ,\frac{{{p_m}}}{{{p_m} - {r_m}}},\frac{{\tilde{p}'}}{{\tilde{p}' - s'}}} \right\}$, $\Xi=\max \left\{ {\frac{{{p_1r_1}}}{{{p_1} - {r_1}}}, \cdots ,\frac{{{p_mr_m}}}{{{p_m} - {r_m}}},\frac{{\tilde{p}'s'}}{{\tilde{p}' - s'}}} \right\}$, and $\varTheta$ is sharp, i.e. it cannot be reduced.
For all exponents $\vec{t}= \left(t_1, \ldots, t_m\right)$ with $(\vec{r},s) \prec (\vec{t},\tilde{t})$,
\begin{align*}
{\left\| {{{\left\{ {T_{\vec{\eta}}^{{\bf b, k}}(f_1^j, \cdots ,f_m^j)} \right\}}_{{l^{\tilde t}}}}} \right\|_{{L^{\tilde{p}}}\left( {{\omega ^{\tilde{p}}}} ,\mathbb{V}\right)}} \lesssim \prod_{i=1}^m \|b_i\|_{\mathrm{BMO}}^{k_i} \cdot \prod\limits_{i = 1}^m {{{\left\| {{{\left\{ {f_i^j} \right\}}_{{l^{{t_i}}}}}} \right\|}_{{L^{{p_i}}}(\omega _i^{{p_i}})}}}.
\end{align*}
\end{theorem}

The sharpness of $\varTheta$ can be proved as follows. When $(X,d,\mu,\mathcal{D})=(\rn,|\cdot|,dx,\mathcal{D})$ and ${\bf k=0}$, since the $m$-linear fractional integral operator $I_\alpha$ is a $\mathbb{C}$-valued {\rm $m$-FBMOO}, cf. Theorem \ref{FCZO}, the classical sparse operators theory manifests the fact that ${I_\alpha }(\vec f) \approx \sum\limits_{i = 1}^{{3^n}} {{{\mathscr{A}}_{\frac{\alpha}{n} ,\mathcal{S}_i,\vec 1}}(\vec f)}.$  This implies that the sharpness of $\varTheta$ for $I_\alpha$ is the same as that of Theorem \ref{thm:sparse-dom_1}. 



The second can be deduced from 
$$\text{Theorem \ref{thm:sparse-T1}+ Corollary \ref{cor:key1} (Theorem \ref{thm:sparse-T1} + Theorem \ref{est:form} +Theorem \ref{thm:Ex_1})}.$$

\begin{theorem}\label{thm:weighted3}
Let \( m \in \mathbb{N} \), \( \eta \in [0,m) \), \( p_1, \dots, p_m \in (1, \infty) \), and \( \frac{1}{{\tilde{p}}} := \sum\limits_{i = 1}^m \frac{1}{{p_i}} - \eta > 0 \). Let \( T_\eta \) be a \( \mathbb{R} \)-valued \rm{$m$-FBMOO} on \( (\mathbb{R}^n, |\cdot|, dx, \mathcal{D}_\omega) \), which admits a \textbf{\textsf{$\mathbb{V}$-valued $m$-linear fractional Calderón-Zygmund kernel representation}}. Suppose that \( \mathbf{k} \in \mathbb{N}_0^m \) and
\[\mathcal{N} := {\left\| T_{\eta}^{\bf{b,k}} \right\|_{{WBP}_{\eta}^{\bf b,k}(\mathbb{V})}} + \sum\limits_{j = 0}^m {{{\left\| {T_{\eta}^{{\bf{b,k}},j*}(1, \cdots ,1)} \right\|}_{BMO_{2,\eta}}}} < \infty.\]
If multi-symbols \(\mathbf{b} = (b_1, \ldots, b_{m}) \in (\BMO)^m\) and $\vec{\omega} \in A_{\vec{p},\tilde{p}}$, then 
\begin{align*}
{\left\| T_{\eta}^{{\bf b, k}} \right\|_{\prod\limits_{i = 1}^m {{L^{{p_i}}}(\omega _i^{{p_i}}) \to } {L^{\tilde{p}}}({\omega ^{\tilde{p}}},\mathbb{V})}}
&\lesssim 
\begin{cases}
\prod_{i=1}^m \|b_i\|_{\mathrm{BMO}}^{k_i} \cdot [\vec{\omega}]^{\varTheta}_{A_{(\vec{p},\tilde{p})}} & \text{if } \tilde{p}\ge1;\\
\prod_{i=1}^m \|b_i\|_{\mathrm{BMO}}^{k_i} \cdot C\left( [\vec{\omega}]_{A_{(\vec{p},\tilde{p})}}\right) & \text{if } 0<\tilde{p} < 1,
\end{cases}
\end{align*}
where $\varTheta:= \max \left\{ {{p_1'}, \cdots ,{p_m'},\tilde p} \right\}$. Indeed, $\varTheta$ is still sharp.

Further, for the same family of exponents and weights, and for all exponents $1<t_1,\dots,t_m<\infty$, and $\frac{1}{{{\tilde{t}}}}:=\sum\limits_{i = 1}^m {\frac{1}{{{t_i}}}}- \eta >0$,
\begin{align*}
\left\| \left\{ T_{\eta}^{{\bf b, k}}(f_1^j, \cdots , f_m^j) \right\}_{l^{\tilde{t}}} \right\|_{L^{\tilde{p}}(\omega^{\tilde{p}},\mathbb{V})} 
&\lesssim \prod_{i=1}^m \| b_i \|_{\mathrm{BMO}}^{k_i} \cdot \prod_{i=1}^m \left\| \left\{ f_i^j \right\}_{l^{t_i}} \right\|_{L^{p_i}(\omega_i^{p_i})}
\end{align*}

\end{theorem}

\begin{remark}
In obtaining Theorem \ref{thm:weighted3}, we used the fact that ${A_{(\vec p,\tilde p),(\vec 1,\infty )}} = {A_{\vec p,\tilde p}}$ introduced by Moen \cite{Moen09} (2009).
\end{remark}


\begin{remark}
%It is immediately to find that the needful conditions and conclusions of Theorems \ref{thm:weighted1} and \ref{thm:weighted2} are quite similar, but there are indeed some differences. 
We roughly make this judgment: considering sharp weighted bounds of some appropriate operators and their generalized commutators, we have that
\begin{align*}
&\text{\bf\small The sharp weighted bounds for the generalized commutators} \\
\approx &\text{\bf\small (1) pointwise sparse bounds + sharp weighted estimates for sparse operators} \\
&\text{\bf\small + extrapolation}\\
\approx &\text{\bf\small (2) form sparse bounds + sharp weighted estimates for sparse forms} \\
