\subsection{$\mathbb{V}$-valued multilinear fractional Calderón--Zygmund operators}
~~


In this subsection, $(X,d,\mu,\mathcal{D})$ is the base space.

\begin{definition}\label{def:full}
Let $m \in \N$, $\eta \in [0,m)$, $\V$ be a quasi-Banach space, and $B(\cc,\V)$ be the space of all bounded operators from $\cc$ to $\V$. Set an operator-valued function $K_{\eta}:(X^{m+1} \backslash \Delta ) \to B(\cc,\V),$ where $\Delta = \{ (x,\vec y) \in X^{m+1} :x = {y_1} =  \cdots  = {y_m}\}$. An $m$-linear operator $T$ admits a
\textbf{\textsf{$\mathbb{V}$-valued $m$-linear fractional Dini-type Calderón-Zygmund kernel representation}}, if for any \( \vec{f} \in (L_b^\infty(X))^m \) and each \( x \notin \bigcap_{i = 1}^m \text{supp}(f_i) \),


	\begin{align*}
T_{\eta}(\vec{f})(x):=\int_{X^m} K_{\eta}\left(x, \vec y\right) \left(\prod_{j=1}^{m}f_j\left(y_j\right)\right) d\mu (\vec y),
	\end{align*}

where $\Dini$ type kernel $K_{\eta}$ satisfies that for 

\begin{enumerate}
 \item \textbf{Size Condition}: 
\begin{align}
{\left\| {{K_{\eta} }\left( {x,\vec y} \right)} \right\|_{B(\cc,\V)}} \le C_{K_\eta} {\left( {\sum\limits_{i = 1}^m {\mu (B(x,d(x,{y_i})))} } \right)^{{\eta}  - m}}  \label{S1} ,
\end{align}
\item \textbf{Hölder Smoothness Condition}: 

For each $j \in \left\{ {0, \cdots ,m} \right\}$, whenever $d\left( {{{y_j'}},{y_j}} \right) \le \frac{1}{2}\max \left\{ {d\left( {{y_0},{y_i}} \right):i = 1, \cdots ,m} \right\}$,
\begin{align}
&{\left\| {{K_{\eta} }\left( {{y_0}, \cdots ,{{y_j'}}, \cdots ,{y_m}} \right) - {K_{\eta} }\left( {{y_0}, \cdots ,{y_j}, \cdots ,{y_m}} \right)} \right\|_{B(\cc,\V)}}, \notag \\
\le C_{K_\eta} & {\left( {\sum\limits_{i = 1}^m {\mu (B({y_0},d({y_0},{y_i})))} } \right)^{{\eta}  - m}}w\left( {\frac{{d\left( {{{y'}_j},{y_j}} \right)}}{{\sum\limits_{i = 1}^m {d\left( {{y_0},{y_j}} \right)} }}} \right), \label{S2}
\end{align}
\end{enumerate}
where $w$ is increasing, $w(0)=0$, and ${\left[ w \right]_{\Dini}} = \int_0^1 {\frac{{w\left( t \right)}}{t}dt}  < \infty$.
Once $w(t)=t^{\delta}$ for some $\delta \in (0,1]$, then we call that $T$ admits a \textbf{\textsf{$\mathbb{V}$-valued $m$-linear fractional Calderón-Zygmund kernel representation}}.


Suppose that \( T \) admits a \textbf{\textsf{$\mathbb{V}$-valued $m$-linear fractional (Dini-type) Calderón-Zygmund kernel representation}}. \( T_{\eta} \) is called a \textbf{\textsf{$\mathbb{V}$-valued multilinear fractional (Dini-type) Calderón-Zygmund operator}} ({\rm $m$-F(D)CZO}), if for some \( r_1, \dots, r_m \geq 1 \), with
$\frac{1}{\tilde r}:=\sum\limits_{i = 1}^m \frac{1}{{{r_i}}}-\eta >0$, such that $T_{\eta}$ is bounded from $\prod\limits_{i = 1}^m {{L^{{r_i}}}(X)}$ to ${L^{\tilde r,\infty }}(X,\V)$.
\end{definition}



Let $\alpha \in (0,mn)$, (or take $\eta:=\alpha/n \in (0,m)$), and we define the $m$-linear fractional integral operator by
\[{I_\alpha }(\vec f)(x): = \int_{{\mathbb{R}^{mn}}} {\frac{{\prod\limits_{i = 1}^m {{f_i}({y_i})} }}{{{{\left( {\sum\limits_{i = 1}^m {\left| {x - y_i} \right|} } \right)}^{mn - \alpha }}}}d\vec y}.\]
This is a special case of {\rm $m$-FDCZO} on $(\rn, |\cdot|,dx, \mathcal{B})$ where $\mathcal{B}$ is the set of all balls or a dyadic lattice of $\rn$. 
In addition, as another special case of {\rm $m$-FDCZO}, we can define the first kind of $m$-linear fractional Littlewood--Paley square operator by  
\[{\T_\eta^{(1)} }(\vec f)(x): = \left\| {{T_{\eta}}(\vec f)}(x) \right\|_{L^2((0,\infty),\frac{dt}{t})},\]
where ${T_{\eta}}$ is a ${L^2((0,\infty),\frac{dt}{t})}$-valued {\rm $m$-FDCZO}.


The second kind of $m$-linear fractional Littlewood--Paley square operator is defined by 
\[{\T_\eta^{(2)} }(\vec f)(x): = \left\| {{T_{\eta,z,t}}(\vec f)}(x) \right\|_{L^2((\R^n \times (0,\infty),\frac{{dzdt}}{{{t^{n + 1}}}})},\]
where ${T_{\eta,z,t}}$ is a ${L^2((\R^n \times (0,\infty),\frac{{dzdt}}{{{t^{n + 1}}}})}$-valued {\rm $m$-FDCZO}, for any $(z,t) \in \R^n \times (0,\infty)$.

From the past literature (e.g. \cite{Xue2015,Xue2021}), we can provides specific definitions of the kernel functions of $m$-linear fractional Littlewood--Paley square operator. However, from the current perspective, these definitions can be seen as derivable from the statement above, regardless of how the kernel is defined.

\begin{theorem}\label{FCZO}
Let the fractional total order ${\eta} \in [0,m)$. 
Then $\V$-valued {\rm $m$-FDCZO} $T_{\eta}$ is a $\V$-valued {\rm $m$-FBMOO} on $(X,d,\mu,\mathcal{D})$ satisfying ${W_{\vec r,\tilde r}}$ for some $r_1,\cdots,r_m \ge 1$, with 
$\frac{1}{\tilde r}:=\sum\limits_{i = 1}^m \frac{1}{{{r_i}}}-\eta >0$. 
In particular, $m$-linear fractional integral operator ${I_\alpha }$ is a $\mathbb{C}$-valued {\rm $m$-FBMOO} on $(\rn,|\cdot|,dx, \mathcal{B})$, satisfying ${W_{\vec r,\tilde r}}$, for any $r_1,\cdots,r_m \ge 1$, with 
$\frac{1}{\tilde r}:=\sum\limits_{i = 1}^m \frac{1}{{{r_i}}}-\eta >0$, where $\eta:=\alpha/n \in (0,m)$.
In addition, the $m$-linear fractional Littlewood--Paley square operators ${\T_\eta^{(1)}},{\T_\eta^{(2)}}$ are both $\R$-valued {\rm $m$-FBMOOs} on $(\rn,|\cdot|,dx, \mathcal{B})$ and also satisfy ${W_{\vec r,\tilde r}}$, for some $r_1,\cdots,r_m \ge 1$, with 
$\frac{1}{\tilde r}:=\sum\limits_{i = 1}^m \frac{1}{{{r_i}}}-\eta >0$, where $\eta:=\alpha/n \in [0,m)$.
\end{theorem}



\begin{remark}
In this subsection, all operators can be viewed as \( \mathbb{V} \)-valued {\rm $m$-FBMOOs} on the spaces \( (X,d,\mu,\mathcal{D}) \) and \( (\mathbb{R}^n, |\cdot|, dx, \mathcal{B}) \), satisfying condition \( W_{\vec{r},\tilde{r}} \). All results in Sect. \ref{Main} apply to them, except for Theorems \ref{thm:sparse-T1} and \ref{thm:DT}. However, if these operators additionally admit a \textbf{\textsf{$\mathbb{V}$-valued $m$-linear fractional Calderón-Zygmund kernel representation}}, then Theorems \ref{thm:sparse-T1} and \ref{thm:DT} also hold for them.
\end{remark}

\begin{proof}
It suffices to prove for $\V$-valued {\rm $m$-FDCZO} $T_{\eta}$. Due to its definition, ${W_{\vec r,\tilde r}}$ follows from the weak-type boundedness. Next, we present why $T_\eta$ can be regarded as a $\V$-valued {\rm $m$-FBMOO} on $(X,d,\mu,\mathcal{D})$.


Once \eqref{M_1.condi.} and \eqref{M_2.condi.} are valid on $(X,d,\mu,\mathcal{B})$, where $\mathcal{B}$ is the set of all balls in $(X,d,\mu)$, we can transform them to $(X,d,\mu,\mathcal{D})$ to make them effective. This is possible due to the inclusion equivalence between $\mathcal{D}:=\cup_{j=1}^N \mathcal{D}^j$ and $\mathcal{B}$ in $(X,d,\mu)$; see subsection \ref{dyadic}, Lemma \ref{cubeeq}, and Lemma \ref{lem.covering}.
Thus, it is enough to verify \eqref{M_1.condi.} and \eqref{M_2.condi.} on $(X,d,\mu,\mathcal{B})$.

From \cite[Theorem 7.1]{K2019}, $\B^{\dagger}$ is a ball-basis satisfying doubling property, cf. subsection \ref{more.information}. For any $B_0=B(x_0,r_0) \in \B$, $B_0^\dagger=B(x_0, R_0)$ with $2r_0 \le R_0 \le \infty$. Set 
$
B := B(x_0, 2R),
\text{ where }
R := \sup\{r \ge R_0:\, B(x_0, r)=B(x_0, R_0)\}. 
$
Since $B_0^\dagger=B(x_0, R_0) \subsetneq X$, we have $R_0<\infty$ and 
\begin{align}\label{BB}
B_0^{\dagger}=B(x_0, R_0) \subsetneq B(x_0, 2R)=B.
\end{align}
For any $\vec{y} \in (B^{\dagger})^m \setminus (B_0^{\dagger})^m$, 
we firstly can obtain that there is a $j \in \{1,\cdots,m\}$, such that $y_j \in B^\dagger \backslash B_0^\dagger$.

For any $x \in B_0$ and $\vec{y} \in (B^{\dagger})^m \setminus (B_0^{\dagger})^m$, we have that $d(x,y_j)>r_0$.
Note that the fact that $B(x_0,r_0) \subseteq B(x,2r_0)$ and $B(x,r_0) \subseteq B(x_0,2r_0)$.
It follows from \eqref{S1}, this fact, and the doubling property of $\mu$ that 
\begin{align}
\|K_\eta(x, \vec{y})\|_{B(\cc,\V)}  
\lesssim \frac{C_{K_\eta}}{\mu(B(x, d(x, y_j)))^{m-\eta}} 
\lesssim \frac{C_{K_\eta}}{\mu(B_0)^{m-\eta}}, \label{KB}
\end{align}
Thus, \eqref{M_1.condi.} with $C_1 \lesssim C_{K_\eta}$ will derive instantly from the following statement.

Collecting \eqref{BB} and \eqref{KB}, for any $x\in B_0$, 
\begin{align*}
&\left\|T_\eta(\vec{f}\mathbf{1}_{{B^\dagger}\backslash {B_0^\dagger}})(x)\right\|_{\mathbb{V}} 
\le\int_{(B^\dagger)^m \setminus (B_0^\dagger)^m} \left\|K(x, \vec{y})\right\|_{B(\cc,\V)} \left(\prod_{i=1}^m |f_i(y_i)|\right) d\mu(\vec{y})\\
&\lesssim C_{K_\eta} \prod_{i=1}^m \frac{1}{\mu(B_0)^{1-\eta_i}} \int_{B^\dagger}|f_i(y_i)| \, d\mu(y_i) 
\lesssim C_{K_\eta} \prod_{i=1}^m \frac{1}{\mu(B^\dagger)^{1-\eta_i}}\int_{B^\dagger}|f_i(y_i)| \, d\mu(y_i)\\
&\le C_{K_\eta} {\prod\limits_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B^\dagger}}
\end{align*}
where we used the doubling property of $\mu$ and H\"older's inequality. 

Analogously, \eqref{M_2.condi.} with $C_2 \lesssim [\omega]_{{\rm Dini}}$ will be deduced from the following statement.


For any $B \in \B$ with $B \subsetneq X$ and for any $x,x_0 \in B$, it is derived from \eqref{S2} and H\"older's inequality that 
\begin{align*}
&{\left\| {{T_\eta }(\vec f{{\bf{1}}_{{{({B^\dagger })}^c}}})(x) - {T_\eta }(\vec f{{\bf{1}}_{{{({B^\dagger })}^c}}})({x_0})} \right\|_\mathbb{V}}
\\ 
& = {\left\|\int_{X^m \setminus (B^{\dagger})^m} 
(K_\eta(x, \vec{y}) - K_\eta(x_0, \vec{y}) ) \left(\prod_{i=1}^m f_i(y_i)\right) d\mu(\vec{y}) \right\|_\mathbb{V}}
\\ 
& \leq\sum_{k=0}^{\infty} \int_{(2^{k+1}B^{\dagger})^m \setminus (2^k B^{\dagger})^m} 
{\left\|K_\eta(x, \vec{y}) - K_\eta(x_0, \vec{y})\right\|_{B(\cc,\V)}} \left(\prod_{i=1}^m |f_i(y_i)|\right) d\mu(\vec{y}) 
\\
& \lesssim \sum_{k=0}^{\infty} \int_{(2^{k+1}B^{\dagger})^m \setminus (2^k B^{\dagger})^m} 
\frac{w\big(\frac{d(x, x_0)}{\max\limits_{1 \le i \le m} d(x_0, y_i)}\big) 
\left(\prod_{i=1}^m |f_i(y_i)|\right) d\mu(y_i)}{\left(\sum_{i=1}^m \mu(B(x_0, d(x_0, y_i)))\right)^{m-\eta}} 
\\
& \lesssim \sum_{k=0}^{\infty} \omega(2^{-k-1}) 
\prod_{i=1}^m {\left\langle {{f_i}} \right\rangle _{{\eta _i},1,{2^{k + 1}}B^\dagger}}
\lesssim [\omega]_{{\rm Dini}} \prod_{i=1}^m {\left\langle {\left\langle {{f_i}} \right\rangle } \right\rangle _{{\eta _i},{r_i},B}}, 
\end{align*}
where we used the definition of ${\left\langle {\left\langle {{f_i}} \right\rangle } \right\rangle _{{\eta _i},{r_i},B}}$ and the fact that
\[
\sum_{k=1}^{\infty} \w(2^{-k}) 
\approx \int_0^1 \w(t) \frac{dt}{t}
= \|\omega\|_{{\rm Dini}} <\infty. \qedhere
\] 
\end{proof}



\subsection{Variation operators associated with fractional Calderón--Zygmund operators}~~

In this subsection, the base space is $(\rn,|\cdot|,dx, \mathscr{Q})$. In this space, for any cube $Q \in \mathscr{Q}$,  $Q^\dagger:=5Q$. 

Let $\mathbb{V}$ is a quasi-Banach space, $q \ge 1$, and a family of real numbers $a := \{a_{\eta}\}_{\eta>0}$, the $\rho$-variation norm of $a$ is defined by
\[{\left\| a \right\|_{{V_\rho}(\mathbb{V})}}: = \mathop {\sup }\limits_{\left\{ {{\varepsilon _i}} \right\} \downarrow 0} {\left( {\sum\limits_{i= 0}^\infty  {{{\left\| {{a_{{\varepsilon _i}}} - {a_{{\varepsilon _{i + 1}}}}} \right\|_{\mathbb{V}}}^\rho}} } \right)^{\frac{1}{\rho}}},\]
where the supremum takes over all number sequences $\{\eta_j\}$ decreasing to 0. 
It is obviously to see that ${\left\| \cdot \right\|_{{V_\rho}}}$ is only a seminorm.






Let $T_\eta$ be a $\mathbb{V}$-valued {\rm $1$-FDCZO} on $(\rn, |\cdot|,dx, \mathscr{Q})$, cf. Definition \ref{def:full}. 
Let $\epsilon>0$, we define the truncated operator of $T_\eta$ by 
\begin{equation*}
T_{\eta,\epsilon}f(x) :=\int_{|x-y| >\epsilon} K_\eta (x, y) f(y) \, dy.
\end{equation*}
Given $b \in \BMO$ and $k \in \N_0$, we denote
\begin{align*}
&\T_\eta f(x) := \big\{T_{\eta,\epsilon}f(x) \big\}_{\epsilon > 0}, \quad 
\T_{\eta}^{b,k} f(x) := \big\{T_{\eta,\epsilon}^{b,k}f(x) \big\}_{\epsilon > 0}, 
\\
&\text{and} \quad
\mathscr{K}_\eta(x, y) :=\big\{K_{\eta,\epsilon}(x, y) := K_\eta(x, y) \chi_{\{|x-y|>{\epsilon}\}}\big\}_{{\epsilon}>0}.
\end{align*}
For $1 \le \rho < \infty$, the $\rho$-variation operator of $T_\eta$ and its gerneralized commutator are defined as
\begin{align*}
(\V_\rho\circ \T_\eta)(f)(x) :=\|\T_\eta f(x) \|_{V_\rho(\mathbb{V})} \text{ and }
(\V_\rho\circ \T_\eta)^{b,k} (f)(x) :=\| \T_\eta^{b,k} f(x) \|_{V_\rho(\mathbb{V})}=(\V_\rho\circ \T_\eta^{b,k}) (f)(x).
\end{align*}



\begin{theorem}\label{thm:Var}
Let the fractional total order ${\eta} \in [0,1)$ and $r \in (1,\rho)$ with $\frac{1}{{\tilde r}}: = \frac{1}{r} - \eta  > 0$. If $\rho>2$, then $\V_\rho \circ \T_\eta$ is a $\R$-valued {\rm $m$-FBMOO} on $(\rn,|\cdot|,dx, \mathscr{Q})$ with constants $C_1(\V_\rho \circ \T_\eta) \lesssim C_{K_\eta}$ and $C_2(\V_\rho \circ \T_\eta) \lesssim 1+[\w]_{\mathrm{Dini}}$.
\end{theorem}



\begin{remark}
In this subsection, $\V_\rho\circ \T_\eta$ can be regarded as a $\V$-valued {\rm $m$-FBMOO} on the space $(\rn, |\cdot|,dx, \mathscr{Q})$.
If we assume that $\V_\rho\circ \T_\eta \in {W_{r,\tilde r}}$ where $r \in (1,\rho)$ as in Theorem \ref{thm:Var}, with 
$\frac{1}{\tilde r}:=\frac{1}{r}-\eta >0$.
All results in Sect. \ref{Main} apply to it, except for Theorems \ref{thm:sparse-T1} and \ref{thm:DT}. However, if it additionally admits a \textbf{\textsf{$\mathbb{V}$-valued $m$-linear fractional Calderón-Zygmund kernel representation}}, then Theorems \ref{thm:sparse-T1} and \ref{thm:DT} also hold for it.
\end{remark}


\begin{proof}
Let $Q_0 \in \mathscr{Q}$, $x \in Q_0$, and take $Q:= 2Q_0$. Observe that 
\begin{align*}
\|\mathscr{K}_\eta (x, y)\|_{V_\rho({B(\cc,\V)})}
&=\sup_{\{\epsilon_j\} \downarrow 0} \bigg(\sum_{j=0}^{\infty}
\left\|K_{\eta,\epsilon_j}(x, y) - K_{\eta,\epsilon_{j+1}}(x, y) \right\|_{{B(\cc,\V)}}^\rho \bigg)^{\frac{1}{\rho}}
\\
&\le \left\|K_\eta(x, y)\right\|_{B(\cc,\V)} \sup_{\{\epsilon_j\}\downarrow 0} \sum_{j=0}^{\infty} 
\mathbf{1}_{\{\eta_{j+1} < |x-y| \le \eta_j \}} 
\le \left\|K_\eta(x, y)\right\|_{B(\cc,\V)}.
\end{align*}
\eqref{M_1.condi.} follows from \eqref{S1} the fact that
\begin{align*}
\|&\T_{\eta}(f \chi_{Q^\dagger})(x) - \T_{\eta}(f \chi_{Q_0^\dagger})(x)\|_{V_\rho(\mathbb{V})}
=\bigg\|\int_{Q^\dagger \setminus Q_0^\dagger} \mathscr{K}_\eta(x, y) f(y) \, dy \bigg\|_{V_\rho(\V)}
\\ 
&\le \int_{Q^\dagger \setminus Q_0^\dagger} \|\mathscr{K}_\eta(x, y)\|_{V_\rho(B(\mathbb{C},\mathbb{V}))} |f(y)| \, dy 
\le C_{K_\eta} \int_{Q^\dagger \setminus Q_0^\dagger} \frac{|f(y)|}{|x-y|^{n(1-\eta)}} \, dy \\
&\lesssim C_{K_\eta} \langle f \rangle_{\eta, 1,Q^\dagger} \le C_{K_\eta} \langle f \rangle_{\eta,r,Q^\dagger},
\end{align*}
which implies that $C_1 \lesssim C_{K_\eta}$.

Last, we verify \eqref{M_2.condi.} as follows.
Let $Q \in \mathscr{Q}$ and $x, x' \in Q$. 
\begin{align*}
\|&(\T_\eta(f \chi_{(Q^\dagger)^c}))(x) - (\T_\eta(f \mathbf{1}_{(Q^\dagger)^c}))(x')\|_{V_\rho(\mathbb{V})}
\\
&\le \sum_{k=1}^{\infty} \bigg\|\int_{2^k Q \setminus 2^{k-1} Q} (\mathscr{K}_\eta(x, y) - \mathscr{K}_\eta(x', y)) f(y) dy \bigg\|_{V_q(\mathbb{V})}
=: \sum_{k=1}^{\infty} \mathcal{T}_k,  
\end{align*}
Set $f_k := f \chi_{2^k Q \setminus 2^{k-1} Q}$ and $R_j=(\epsilon_{j+1}, \epsilon_j]$. Note that 
$$\mathcal{T}_k= \sup_{\{\epsilon_j\} \downarrow 0}  \left(\sum\limits_{j = 1}^\infty \left| {\int_{{2^k}Q \setminus {2^{k - 1}}Q} \left\|{\left( {{{\mathcal{K}}_\eta }(x,y){\chi _{{R_j}}}(x - y) - {{\mathcal{K}}_\eta }(x',y){\chi _{{R_j}}}(|x' - y|)} \right)}\right\|_{B(\cc,\V)}f(y)dy }\right|^\rho\right)^{\frac{1}{\rho}},$$
and
\begin{align}\label{GGkk}
\mathcal{T}_k 
\le \mathcal{T}_k^1 +\mathcal{T}_k^2,   
\end{align}
where 
\begin{align*}
\mathcal{T}_k^1 
&:=\sup_{\{\epsilon_j\} \downarrow 0} \bigg(\sum_{j=0}^{\infty} \left|\int_{\Rn}
\left\|{K}_\eta(x, y) - {K}_\eta(x', y)) \right\|_{B(\cc,\V)}\chi_{R_j}(|x-y|) f_k(y) dy\right|^\rho \bigg)^{\frac{1}{\rho}},
\end{align*}
and 
\begin{align*}
\mathcal{T}_k^2 
&:=\sup_{\{\epsilon_j\} \downarrow 0} \bigg(\sum_{j=0}^{\infty} \left|\int_{\Rn}
\left\|{K}_\eta(x', y) \right\|_{B(\cc,\V)}\left(\chi_{\{\epsilon_{j+1}<|x-y| \le \epsilon_j\}} - \chi_{\{\epsilon_{j+1}<|x'-y| \le \epsilon_j\}}\right) f_k(y) \, dy\right|^\rho \bigg)^{\frac{1}{\rho}}. 
\end{align*}
It follows immediately from \eqref{S2} that 
\begin{align}\label{GGkk-1}
\mathcal{T}_k^1 
\le \int_{\Rn} \left\|K_\eta(x, y) - K_\eta(x', y)\right\|_{B(\cc,\V)} |f_k(y)| \, dy
\lesssim \w(2^{-k}) \langle f \rangle_{\eta,1,2^k Q} \le \w(2^{-k}) \langle\langle f \rangle\rangle_{\eta,r,Q}. 
\end{align}
It derives from the methods of \cite[p.10]{DLY} and \cite[p.401]{MTX} that
\begin{align}\label{GGkk-2}
\mathcal{T}_k^2 
&\lesssim \ell(Q)^{\frac{1}{r'}} \bigg(\int_{\Rn} \frac{|f_k(y)|^r}{|x-y|^{r+n(1-\eta)-1}} dy \bigg)^{\frac1r}
\nonumber \\ 
&\approx \ell(Q)^{\frac{1}{r'}} \bigg(\frac{1}{(2^{k-1}\ell(Q))^{r+n(1-\eta)-1}} \int_{2^k Q} |f(y)|^r dy \bigg)^{\frac1r}
\nonumber \\
&\lesssim 2^{-k/r'} \langle f \rangle_{\eta,r,2^k Q} \le 2^{-k/r'} \langle\langle f \rangle\rangle_{\eta,r,Q}.
\end{align}
Consequently, these estimates above implies that 
\eqref{M_2.condi.} is valid with $C_2(\V_\rho \circ \T_\eta) \lesssim 1 + [\w]_{\mathrm{Dini}}$. 
\end{proof}

