\subsection{Multilinear fractional Ahlfors-Beurling operators}
~~

In this subsection, $(\mathbb{C},|\cdot|, dA, \mathscr{B})$ is the base space. In this space, for any cube $B \in \mathscr{B}$,  $B^\dagger:=5B$. 

\begin{definition}
 Let ${\eta _1}, \cdots ,{\eta _m} \in [0,1)$, and $\eta:= \sum\limits_{i = 1}^m {{\eta _i}} \in [0,m)$. Let $r_1,\cdots,r_m \ge1$ and $\frac{1}{{\tilde r}}: = \sum\limits_{i = 1}^m {\frac{1}{{{r_i}}}}  - \eta>0.$ Define $m$-linear fractional Ahlfors-Beurling operator $\mathscr{C}_{\vec{\eta}}:C_b^\infty(\mathbb{C})\times\cdots\times C_b^\infty(\mathbb{C})\to (C_{b}^\infty(\mathbb{C}))'$ by 
\[
\mathscr{C}_{\vec{\eta}}(\vec{f})(z) = \int_{\mathbb{C}^m} K_{\vec{\eta}}(z, \zeta_1, \dots, \zeta_m) \prod_{i=1}^{m} f_i(\zeta_i) dA(\zeta_1) \dots dA(\zeta_m).
\]
where $z \notin \mathop  \cap \limits_{i = 1}^m \supp{f_i}$.


%We always suppose that $\mathscr{C}_{\vec{\eta}} \in W_{\vec{r},\tilde{r}}$ for some $r_1,\cdots,r_m \ge1$ and $\frac{1}{{\tilde r}}: = \sum\limits_{i = 1}^m {\frac{1}{{{r_i}}}}  - \eta>0,$ 
The kernel $K_{\vec{\eta}}: \mathbb{C}^{m+1} \setminus \Delta \to \mathbb{C}$, where $\Delta : = \left\{ {\left( {z,{\xi _1} \cdots ,{\xi _m}} \right) \in {\mathbb{C}^{m + 1}}:z = {\xi _i}}, \text{ for some } i \in \{1,\cdots,m\} \right\}$ satisfying

\begin{enumerate}
    \item \textbf{Size Condition}: 
    \[
    |K_{\vec{\eta}}(z, \zeta_1, \dots, \zeta_m)| \lesssim {\prod_{i=1}^{m} |z - \zeta_i|^{2\eta_i-2}},
    \]

    \item \textbf{Hölder Smoothness Condition}: there exists a $\delta > 0$, such that for any $z, z' \in \mathbb{C}$, with $|z - z'| \leq \frac{1}{2} \max_i |z - \zeta_i|$, 
    \[
    |K_{\vec{\eta}}(z, \zeta_1, \dots, \zeta_m) - K_{\vec{\eta}}(z', \zeta_1, \dots, \zeta_m)| \lesssim \frac{|z - z'|^\delta}{\prod_{i=1}^{m} |z - \zeta_i|^{2-2\eta_i + \delta}},
    \]
\end{enumerate}
\end{definition}

\begin{theorem}
Let ${\eta _1}, \cdots ,{\eta _m} \in [0,1)$, and the fractional total order $\eta:= \sum\limits_{i = 1}^m {{\eta _i}}$. Then  $\mathscr{C_{\vec{\eta}}}$ is a $\mathbb{C}$-valued {\rm $m$-FBMOO} on $(\mathbb{C},|\cdot|, dA, \mathscr{B})$.
\end{theorem}

