\begin{definition}\label{MFPDO}
Given a function $a: \R^{n(m+1)} \to \mathbb{C}$, for all $f_i \in \mathscr{S}(\Rn)$, $i=1,\ldots,m$, the $m$-linear pseudo-differential operator $T_a$ is defined as
\begin{align*}
T_a(\vec{f})(x) := \int_{\R^{nm}} a(x, \vec{\xi})
\widehat{f}_1(\xi_1) \cdots \widehat{f}_m(\xi_m) e^{2\pi i x \cdot (\xi_1+\cdots+\xi_m)}  \, d\vec{\xi},
\end{align*}
where $\widehat{f}=\F(f)$ is the Fourier transform of $f$, and we always set $a(x, \vec{\xi})= \mathcal{F}\left( {{K_{a}}(x, \cdot )} \right)(\vec \xi )$.
If $a(x, \vec{\xi}) \equiv \sigma(\vec{\xi})$ for all $x \in \Rn$, $T_\sigma$ is called $m$-linear Fourier multiplier. 
\end{definition}


In 2024, Mondal et al. introduce the following multi-parameter Hörmander symbol class.
\begin{definition}[\cite{Mondal2024}, Definition 2.5]
Letting $(\tau_1,\cdots,\tau_m) \in \R^m$ and $\rho, \delta \in [0, 1]$, we write $a \in S_{\rho,\delta}^{\tau_1,\cdots,\tau_m}$, if for every multi-indices $\gamma, \beta_1,\ldots,\beta_m$, 
\begin{align*}
{\left[ a \right]_{S_{\rho,\delta}^{\tau_1,\cdots,\tau_m}(\gamma,\vec{\beta})}}: = \mathop {\sup }\limits_{x,{\xi _1}, \cdots ,{\xi _m} \in \rn} \prod\limits_{i = 1}^m {{{\left( {1 + \left| {{\xi _i}} \right|} \right)}^{ - \left( {{\tau _i} - \rho \left| {{\beta _i}} \right| + \delta |\gamma |} \right)}}}|\partial _x^\gamma \partial _{{\xi _1}}^{{\beta _1}} \cdots \partial _{{\xi _m}}^{{\beta _m}}a(x,\vec \xi )| <\infty.
\end{align*}

\end{definition}


