\begin{proposition}\label{lem:M_0}
Let $(X,\mu,\mathcal{B})$ be a ball-basis measure space. Let $\eta \in [0,1)$, $r \in [1,\infty)$ with $\frac{1}{\tilde{r}}=\frac{1}{r} - \eta$, then
\begin{align}
\|M^{\B}_{\eta,r}\|_{L^r(X, \mu) \to L^{\tilde{r}, \infty}(X, \mu)} \le \C_0^{\frac{1}{\tilde{r}}}\label{Mr-1} 
\end{align}
\end{proposition}

%\label{Mr-2} & \|M^{\B}_{\eta, r}\|_{L^p(X, \mu) \to L^{\tilde{p}}(X, \mu)} \lesssim_{\tilde{p}} 1,  \quad r<p < \infty \text{ with } 1/{\tilde{p}}=1/{p} - \eta.

\begin{proof}
For a fixed \( \lambda > 0 \), define the level set: $E = \{ x \in X : M_{\eta,r}^{\mathcal{B}} f(x) > \lambda \}.$
For each \( x \in E \), there exists a ball \( B(x) \in \B \) such that \( x \in B(x) \) and
\[
\int_{B(x)} |f(t)|^r \, d\mu(t) > \lambda^r \mu(B(x))^{1 - \eta r}.
\]
Thus, \( E = \bigcup_{x \in E} B(x) \). Given \( B \in \mathcal{B} \) with \( \mu(B) < \infty \), \cite[Lemma 3.1]{K2019} applied to \( \{ B(x) : x \in E \cap B \} \) yields disjoint \( \{ B_k \}_k \) with \( E \cap B \subseteq \bigcup_k B_k^1 \). The union \( Q(B) = \bigcup_k B_k^1 \) is measurable. Therefore, it follows that
\begin{align*}
    \mu(Q(B)) \leq \sum_k \mu(B_k^{1}) \leq \C_0 \sum_k \mu(B_k) < \C_0 \sum_k \frac{1}{\lambda^{\tilde{r}}} \left( \int_{B_k} |f(t)|^r \, d\mu(t) \right)^{\tilde{r} / r}.
\end{align*}
Considering \( \tilde{r} / r > 1 \) and the \( B_k \) are disjoint, we have
\[
\sum_k \left( \int_{B_k} |f|^r \, d\mu \right)^{\tilde{r} / r} \leq \left( \sum_k \int_{B_k} |f|^r \, d\mu \right)^{\tilde{r} / r} = \left( \int_{\bigcup_k B_k} |f|^r \, d\mu \right)^{\tilde{r} / r} \leq \| f \|_{L^r}^{\tilde{r}},
\]
Thus, $\mu(Q(B)) < \frac{\C_0}{\lambda^{\tilde{r}}} \| f \|_{L^r}^{\tilde{r}}$.

Next, we extend the local construction to $X$ via \cite[Lemma 3.2]{K2019}, which provides a sequence $\{G_k\}$ satisfying 
$X = \bigcup_{n=1}^\infty \bigcap_{k=n}^\infty G_k,$
and consequently $E \subseteq \bigcup_{n=1}^\infty \bigcap_{k=n}^\infty Q(G_k)$
and
\[
\mu^*(E)=\mu\left(\bigcup_{n \geq 1} \bigcap_{k \geq n} Q\left(G_k\right)\right) \leq \frac{\C_0}{\lambda^{\tilde{r}}} \| f \|_{L^r}^{\tilde{r}}.
\]


