= \bigg\|\prod_{i=1}^m M^{\B}_{\eta_i,r_i} (f_i) \bigg\|_{L^{\tilde{r}, \infty}(X, \mu)} 
\\
\le (\tilde{r})^{-\frac{1}{\tilde{r}}} \prod_{i=1}^m \tilde{r_i}^{\frac{1}{\tilde{r_i}}} \left\|M^{\B}_{\eta_i,r_i}(f_i)\right\|_{L^{\tilde{r_i}, \infty}(X, \mu)}
\le \left(\frac{\C_0}{\tilde{r}}\right)^{\frac{1}{\tilde{r}}} \prod_{i=1}^m \tilde{r_i}^{\frac{1}{\tilde{r_i}}} \|f_i\|_{L^r(X, \mu)}. 
\end{align*}
The proof is complete. 
\end{proof}




\begin{theorem}\label{ca:2.1}
Let $(X,\mu,\mathcal{B})$ be a ball-basis measure space. Let $\eta_i \in [0,1)$ with the fractional total order $\eta:=\sum\limits_{i=1}^m\eta_i$, and $1 \le r_1,\cdots,r_m < \infty$ with 
$\frac{1}{\tilde r}:=\sum\limits_{i = 1}^m \frac{1}{{{r_i}}}-\eta >0$. Then multilinear fractional maximal operator \(\mathcal{M}^{\B}_{\vec{\eta},\vec{r}}\) is a $\mathbb{R}$-valued {\rm $m$-FBMOO} satisfying $W_{\vec{r},\tilde{r}}$.
\end{theorem}



\begin{remark}
In this subsection, \(\mathcal{M}^{\B}_{\vec{\eta},\vec{r}}\) can be regarded as a $\R$-valued {\rm $m$-FBMOO} on  ball-basis measure $(X,\mu,\mathcal{B})$, satisfying condition ${W_{\vec r,\tilde r}}$ with $
