Based on the construction of $\B^{\prime}$, by \eqref{list:B4}, we can find a ball $B_1 \in \B^{\prime}$ such that
\begin{align*}
b \leq \mu\left(B_1\right)<2 b \text{\quad and \quad}
	B_0 \subseteq \bigcup_{B' \in \B: B' \cap B_1 \neq \emptyset \atop \mu(B') \le 2\mu(B_1)} B' \subseteq B_1^{\dagger},
	\end{align*}
 where $b:=\inf\limits_{B \in \B^{\prime}} \mu(B)$. Since $ B_0 \subsetneq B_1 $, then we take $B:=B_1^{\dagger}$.
%For $x \in B_0$, consider the definition of $\mathcal{M}^{\B}_{\eta,\vec{r}}$, 


For any $\varepsilon > 0$ and any nonnegative $f_i \in L^{r_i}(X, \mu)$, $i=1,\cdots,m$, there exists $B_2 \in \B$ with $B_2 \ni x$, such that
 \begin{align}\label{eq:ca:2.2:setpre}
\mathcal{M}^{\B}_{\vec{\eta},\vec{r}}\left(\vec{f} \chi_{B^\dagger}\right)(x) -\varepsilon  \leq \prod_{i=1}^m\left\langle f_i \chi_{B^\dagger}\right\rangle_{\eta_i,r_i,B_2}.
 \end{align}

\emph{{\textbf{\textsf Case 1: $\mu\left(B_2\right) \leq \mu\left(B_0\right)$}}}

It follows from \eqref{list:B4} that 
$B_2 \subseteq B_0^{\dagger} \subseteq B^\dagger,$
and then we have
\begin{align*}
0 \le & \mathcal{M}^{\B}_{\vec{\eta},\vec{r}}\left(\vec{f} \chi_{B^\dagger}\right)(x)-\mathcal{M}^{\B}_{\vec{\eta},\vec{r}}\left(\vec{f} \chi_{B_0^\dagger}\right)(x) \le\varepsilon+\prod_{i=1}^m\left\langle f_i \chi_{B^\dagger}\right\rangle_{\eta_i,r_i,B_2}-\mathcal{M}^{\B}_{\vec{\eta},\vec{r}}\left(\vec{f} \chi_{B_0^\dagger}\right)(x)\\
\le& \varepsilon+\prod_{i=1}^m\left\langle f_i \chi_{B^\dagger}\right\rangle_{\eta_i,r_i,B_2}-\prod_{i=1}^m\left\langle f_i \chi_{B_0^\dagger}\right\rangle_{\eta_i,r_i,B_2}= \varepsilon.
\end{align*}
Thus, letting  $\varepsilon<\prod\limits_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B^\dagger}$, the desired is obtained.

\emph{{\textbf{\textsf Case 2: $\mu\left(B_2\right) > \mu\left(B_0\right)$}}}

We can find that $B_2 \in \mathcal{B}'$, then $$\mu\left(B^\dagger\right) \ge \mu\left(B_2\right) \geq b \ge \frac{1}{2}\mu\left(B_1\right) \ge \frac{1}{2C_0} \mu\left(B_1^\dagger\right) \ge \frac{1}{2C_0^2} \mu\left(B_1^2\right)= \frac{1}{2C_0^2} \mu\left({B^\dagger} \right).$$
It derives from \eqref{eq:ca:2.2:setpre} that
\begin{align*}
0 \le& \mathcal{M}^{\B}_{\vec{\eta},\vec{r}}\left(\vec{f} \chi_{B^\dagger}\right)(x)-\mathcal{M}^{\B}_{\vec{\eta},\vec{r}}\left(\vec{f} \chi_{B_0^\dagger}\right)(x) \le\varepsilon+\prod_{i=1}^m\left\langle f_i \chi_{B^\dagger}\right\rangle_{\eta_i,r_i,B_2}\\
\lesssim &\varepsilon+\prod_{i=1}^m\left\langle f_i \chi_{B^\dagger}\right\rangle_{\eta_i,r_i,{B^\dagger}} \lesssim \prod_{i=1}^m\left\langle f_i \right\rangle_{\eta_i,r_i,{B^\dagger}},
\end{align*}
where $\varepsilon<\prod\limits_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B^\dagger}$.

Therefore, \eqref{M_1.condi.} is valid by collecting these estimates. 

Next, we consider \eqref{M_2.condi.} as follows.

Let $B \in \mathcal{B}$ and $x,x' \in B$. For any nonnegative $f_i \in L^{r_i}$, $i=1,\cdots,m$., there is a $B_3 \in \mathcal{B}$ with $B_3 \ni x$, such that
\begin{align}\label{eq:ca:2.5:setpre}
\mathcal{M}^{\B}_{\vec{\eta},\vec{r}}(\vec{f})(x)-\prod_{i=1}^m\left\langle\langle f_i\right\rangle\rangle_{\eta_i,r_i,B}\leq \prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B_3}.
\end{align}


{\emph{{\textbf{\textsf Case 3: $\mu\left(B_3\right) \leq \mu\left(B_0\right)$}}}}

Similar to Case 1, \eqref{list:B4} implies that 
$B_3\subseteq B^\dagger,$ and then 
$$\mathcal{M}^{\B}_{\vec{\eta},\vec{r}}(\vec{f}\chi_{B^\dagger})(x) \ge \prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B_3}.$$
