\begin{align}
0 \le \mathcal{M}^{\B}_{\eta,\vec{r}}(\vec{f})(x)-\mathcal{M}^{\B}_{\eta,\vec{r}}\left(\vec{f} \chi_{B^\dagger}\right)(x) \le& \prod_{i=1}^m\left\langle\langle f_i\right\rangle\rangle_{\eta_i,r_i,B}+ \prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B_3}-\mathcal{M}^{\B}_{\eta,\vec{r}}\left(\vec{f} \chi_{B^\dagger}\right)(x) \notag\\ 
\le& \prod_{i=1}^m\left\langle\langle f_i\right\rangle\rangle_{\eta_i,r_i,B}.\label{eq:n:T2sat}
\end{align}






{\emph{{\textbf{\textsf Case 4: $\mu\left(B_3\right) > \mu\left(B_0\right)$}}}}

\eqref{list:B4} implies that $B \subseteq B_3^{\dagger}$ and 
$$\prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B_3} \lesssim \prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B_3^\dagger} \le \prod_{i=1}^m\left\langle\langle f_i\right\rangle\rangle_{\eta_i,r_i,B},$$
and \eqref{eq:ca:2.5:setpre} gives that 
\begin{align}
0 \le &\mathcal{M}_{\vec{\eta},\vec{r}}^\B(\vec{f})(x)-\mathcal{M}_{\vec{\eta},\vec{r}}^\B\left(\vec{f} \chi_{B^\dagger}\right)(x)
  \leq \prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B_3}+\prod_{i=1}^m\left\langle\langle f_i\right\rangle\rangle_{\eta_i,r_i,B}
\lesssim \prod_{i=1}^m\left\langle\langle f_i\right\rangle\rangle_{\eta_i,r_i,B}. \label{eq:II}
\end{align}

Hence, combining Case 3 and Case 4, \eqref{M_2.condi.} holds by the following that 
\begin{align*}
\left|\left(\mathcal{M}_{\vec{\eta},\vec{r}}^\B(\vec{f})(x)-\mathcal{M}_{\vec{\eta},\vec{r}}^\B(\vec{f}\chi_{B^\dagger})(x) \right)- \left(\mathcal{M}_{\vec{\eta},\vec{r}}^\B(\vec{f})(x') -\mathcal{M}_{\vec{\eta},\vec{r}}^\B(\vec{f}\chi_{B^\dagger})(x')\right)\right| \lesssim \prod_{i=1}^m\left\langle\langle f_i\right\rangle\rangle_{\eta_i,r_i,B}. 
\end{align*}

Finally, by Proposition \ref{lem:M}, we have that $\mathcal{M}_{\vec{\eta},\vec{r}}^\B \in W_{\vec{r},\tilde{r}}$. 
\end{proof}





\section{\bf Preliminaries}\label{Pre}




\subsection{Geometry of measure spaces}~~

Let \((X, \mu, \mathcal{B})\) be a ball-basis  measure space, where $\B$ a basis satisfying property \eqref{list:B4}. This property implies that for any $A, B \in \B$,
\begin{align}\label{ball} 
A \cap B \neq \emptyset \text{ and } \mu(A) \le 2\mu(B) \implies A \subseteq B^\dagger.
\end{align}
For any $B \in \B$, define recursively:
\[
B^0 := B, \quad 
B^{k+1} := (B^k)^\dagger \quad (k \ge 0).
\]
Then \eqref{list:B4} yields the following estimates:
\begin{align}\label{BkBk}
\mu(B^{k+1}) \le \C_0 \mu(B^k) \quad \text{and} \quad \mu(B^k) \le \C_0^k \mu(B) \quad (k \ge 0).
\end{align}

Below we offer a concise account of the geometric features of measure spaces, following \cite{K2019}.

\begin{lemma}\label{lem:BG}
	\noindent Let $(X,\mu,\B)$ be a measure space with ball--basis~$\B$. Suppose there is a sequence of balls $\{G_k\}\subseteq\B$ and a ball $B\in\B$ such that $G_k\cap B\neq\emptyset$ for every $k$ and $\mu(G_k)\to r:=\sup_{A\in\B}\mu(A)$ as $k\to\infty$. Then one shows that $X\subseteq\bigcup_{k=1}^\infty G_k^*$, further, for each ball $A\in\B$ there is a $k_0\in\mathbb{N}$ so that $A\subseteq G_k$ for all $k\ge k_0$.  
\end{lemma}


\begin{lemma}\label{lem:aooa:3.3}
Let \((X, \mu, \mathcal{B})\) is a measure space with a ball-basis. Then the following hold: 
\begin{list}{\rm (\theenumi)}{\usecounter{enumi}\leftmargin=1.2cm \labelwidth=1cm \itemsep=0.2cm \topsep=.2cm \renewcommand{\theenumi}{\alph{enumi}}}

\item\label{list-1} 
Let \(E\subseteq X\) be bounded and satisfy \(E\subseteq\bigcup_{G\in\mathcal{G}}G\) for some \(\mathcal{G}\subseteq\mathcal{B}\).  Then there is a pairwise disjoint subfamily \(\mathcal{G}'\subseteq\mathcal{G}\) (finite or infinite) with $  E\subseteq\bigcup_{G\in\mathcal{G}'}G^*.$



\item\label{list-2} Let \(A\in\mathcal{B}\) and let \(\mathcal{G}\subseteq\mathcal{B}\) be a pairwise disjoint family for which 
\[
A\cap G^{\dagger}\neq\emptyset
\quad\text{and}\quad
0<c_{1}\le\mu(G)\le c_{2}<\infty
\quad\forall G\in\mathcal{G}.
\]
Then one obtains the bound
\[
\#\mathcal{G}\;\le\;\frac{1}{c_{1}}\min\bigl\{\,c_{2}\,\mathbf{C}_{0}^{3},\;\mathbf{C}_{0}\,\mu(A)\bigr\}.
\] 

\item\label{list-4}
If \(\B\) also satisfies property~\eqref{list:B3}, then for every bounded measurable set \(E\) with \(\mu(E)>0\) and each \(\varepsilon>0\), one can select a sequence \((B_k)\subseteq\B\) so that  
\[
\mu\bigl(\bigcup_k B_k\setminus E\bigr)<\varepsilon,
\qquad
\mu\bigl(E\setminus\bigcup_k B_k\bigr)<\alpha\,\mu(E),
\]
where \(\alpha\in(0,1)\) is a fixed constant.  


\item\label{list-5} Moreover, if \(\B\) satisfies property~\eqref{list:B3}, then for every bounded measurable set \(E\) one can find a sequence \((B_k)\subseteq\B\) such that
\[
E\subseteq\bigcup_k B_k\quad\text{a.s.}
\quad\text{and}\quad
\sum_k\mu(B_k)\le2\,\mathbf C_0\,\mu(E).
\]



\item\label{list-3} The density condition is exactly equivalent to property~\eqref{list:B3}.

\end{list} 
\end{lemma}

