\subsection{Spaces of homogeneous type }
~~

\begin{definition}\label{quasi-metric}
	Let $d: X \times X \rightarrow [0, \infty)$ be a positive function and $X$ be a set, then the quasi-metric space $(X, d)$ satisfies the following conditions:
	\begin{enumerate}
		\item  When $x=y$, $d(x, y)=0$.
		\item $d(x, y)=d(y, x)$ for all $x, y \in X$.
		\item  For all $x, y, z \in X$, there is a constant $A_0 \geq 1$ such that $d(x, y) \leq A_0(d(x, z)+d(z, y))$.
	\end{enumerate}
\end{definition}


\begin{definition}\label{def:doubling}
Let $\mu$ be a measure of a space $X$. For a quasi-metric ball $B(x,  r)$ and any $r>0$, if $\mu$ satisfies doubling condition, then there exists a doubling constant $C_\mu \geq 1$, such that  
	\begin{align}\label{def_hom}
    0<\mu(B(x, 2 r)) \leq C_\mu \mu(B(x, r))<\infty.
  \end{align}
\end{definition}

\begin{definition}
	For a non-empty set $X$ with a qusi-metric $d$, a triple $(X, d, \mu)$ is said to be a space of homogeneous type if $\mu$ is a regular measure which satisfies doubling condition on the $\sigma$-algebra, generated by open sets and quasi-metric balls.
\end{definition}

