	&\quad  \left\|T_{\vec \eta}^{{\bf b, k}}(\vec f\chi_{B^3})(x)\right\|_{\mathbb{V}}\\ \notag
    & \lesssim \sum\limits_{0 \le {\bf t} \le {\bf k}}\prod_{i = 1}^m\big|b_i(x)-b_{i,B^3}\big|^{k_i-t_i}   \left\|T_{\vec \eta}^{}\left(\left(b_i-b_{i,B^3}\right)^{t_i}f_i\chi_{B^3}\right)(x)\right\|_{\mathbb{V}} \\ \notag
	&\lesssim \Phi_{\varLambda,\vec{r},\tilde{r}}\left(\frac{1}{\boldsymbol{C}^3_0 \lambda}\right) \sum\limits_{0 \le {\bf t} \le {\bf k}}\prod_{i = 1}^m\big|b_i(x)-b_{i,B^3}\big|^{k_i-t_i} \varLambda\left(\left(b_i-b_{i,B^3}\right)^{t_i}f_i\chi_{B^3}\right)(x) \\ \label{eq5.35}
	&\lesssim \Phi_{\varLambda,\vec{r},\tilde{r}}\left(\frac{1}{\boldsymbol{C}^3_0 \lambda}\right) \sum\limits_{0 \le {\bf t} \le {\bf k}}\prod_{i = 1}^m\big|b_i(x)-b_{i,B^3}\big|^{k_i-t_i} 
 \langle\big|\big(b_i-b_{i,B^3}\big)^{t_i} f_i\big|\rangle_{\eta_{i},r_{i},B^3}
\end{align}
For $\mathbb{D}_2$, from Lemma \ref{est.d2}, for all $x \in B_k$ and $j=0, 1, \ldots, k-1$, it derives that
\begin{align}\notag
    &\left\|T_{\vec \eta}^{{\bf b, k}}(\vec{f} \chi_{B^3_j \backslash B^3_{j+1}})(x)  \right\|_{\mathbb{V}} 
 \\ \label{lem:TFA}
& \leq \Phi_{\varLambda,\vec{r},\tilde{r}}\left(\frac{1}{\boldsymbol{C}^3_0 \lambda}\right)  \sum\limits_{0 \le {\bf t} \le {\bf k}}\prod_{i = 1}^m\big|b_i(x)-b_{i_1,B^3_j}\big|^{k_i-t_i} 
\langle\big|\big(b_i-b_{i_1,B^3_j}\big)^{t_i} f_i\big|\rangle_{\eta_{i},r_{i},B^3_j} 
\end{align}
Setting $\mathcal{S} = \mathcal{S}_1 \cup \mathcal{S}_2$,  \eqref{main0609} follows from \eqref{mainseq}, \eqref{eq5.35},
 and \eqref{lem:TFA}.

\end{proof}


\subsection{More information about $m$-FBMOOs}\label{more.information}
~~


% Given a $\mathbb{V}$-valued operator ${T}_{\vec \eta}$ satisfying $\mathscr{T}_{\vec \eta}(\vec{f})(x)=\|{{T}_{\vec \eta}}(\vec{f})(x)\|_{\mathbb{V}}$, 

We define its localized maximal operator by
\begin{align}\label{txing}
    {T}^{\star}_{\vec \eta,s}(\vec{f})(x):=\sup _{B \in \B}\left\langle\left\|{{T}_{\vec\eta}}\left(\vec{f} \chi_{(B^\dagger)^c}\right)(\cdot)\right\|_{\mathbb{V}}\right\rangle_{s,B}\cdot\chi_B(x),
\end{align}
where $s = \min\{s_1,s_2\}$,  and $s_1,s_2$ referred to Definition \ref{def:FBMOO}.

We say $\mathcal{B}$ is \emph{doubling} if there exists a constant $\gamma > 1$ such that for every ball $B \in \mathcal{B}$ with $B^\dagger \subsetneq X$, there exists $B' \in \mathcal{B}$ containing $B$ with $\mu(B') \leq \gamma \mu(B)$.



\begin{definition}
Let \( A_0 \in \mathcal{B} \). For any \( A, B \in \mathcal{B} \) with \( A \subseteq B \), and the condition \eqref{M_1.condi.}, we define
\begin{align}\label{Deltaaa}
\left\bracevert A, B \right\bracevert_{s_1}:=\sup _{\substack{f_i \in L_b^{r_i}(X) \, i=1, \ldots, m}}  
\frac{\left\langle \left\|{{T}_\eta}\left(\vec{f} \chi_{B^\dagger\backslash A^{\dagger}}\right)(\cdot)\right\|_{\mathbb{V}}\right\rangle_{s_1,A}}{\prod\limits_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B^\dagger}}.
\end{align}
% For convenience, we always denote $\left\bracevert A_0, A, B \right\bracevert_{s_1}$ by $\left\bracevert  A, B \right\bracevert_{s_1}$.
\end{definition}


\begin{theorem}\label{thm:aooa:4.1}
Let \((X, \mu, \mathcal{B})\) be a ball-basis  measure space. Assume that ${T}_{\vec \eta}$ is a $\mathbb{V}$-valued multilinear operator satisfying the condition \eqref{M_2.condi.} and admitting ${T}_{\vec \eta} \in W_{\vec{r},\tilde{r}}$. Then,
\begin{list}{\rm (\theenumi)}{\usecounter{enumi}\leftmargin=1cm \labelwidth=1cm \itemsep=0.2cm \topsep=.2cm \renewcommand{\theenumi}{\roman{enumi}}}
\item ${{T}}^{\star}_{\vec \eta,s} \in W_{\vec{r},\tilde{r}}$.
\item When $\mathcal{B}$ is doubling, ${T}_{\vec \eta}$ satisfies the condition \eqref{M_1.condi.}, i.e. ${T}_{\vec \eta}$ is an {\rm $m$-FBMOO}.



\end{list}
\end{theorem}



\begin{proof}[Proof of Theorem \ref{thm:aooa:4.1}]~~

\emph{{\textbf{\textsf (i):}}}
From Definition \ref{def:multilinear_W}, given $\lambda_1 \in (0,1)$, and setting $\lambda= \frac{2\boldsymbol{C}_0 \lambda_1}{1 - \lambda_1} \in (0,1)$, we define
\begin{align}\label{asetting1}
\Phi_{{T}^{\star}_{\vec \eta,s},\vec{r},\tilde{r}}(\lambda):= \Phi_{\mathcal{M}_{\eta,\vec{r}}^{\B,\otimes},\vec{r},\tilde{r}}\left(\lambda_{1}\right)\left( 2\Phi_{T_{\vec \eta},\vec{r},\tilde{r}}\left(\lambda_1\right)+ {C}_{2}\right)+1,
\end{align}
where $C_2$ is from Definition \ref{def:FBMOO}.



%For any \( \lambda_i \in (0,\frac{1}{4\boldsymbol{C}_0}) \), $i=1,2$, we define \( \lambda := \lambda_1 + \lambda_2.\)

To demonstrate that \( {T}^{\star}_{\vec \eta,s} \in W_{\vec{r},\tilde{r}} \), by Definition \ref{def:multilinear_W}, it suffices to prove that for any $\lambda \in (0,1)$ and every $R \in \B$ with $B_0 \subseteq R$, 
\begin{align}
\mu(E(B_0)) \leq \lambda \mu(B_0)
\label{keyest.2}
\end{align}
where $E(B_0):=\left\{x \in B_0: {T}^{\star}_{\vec \eta,s}(\vec{f})(x)>\Phi_{{T}^{\star}_{\vec \eta,s},\vec{r},\tilde{r}}\left(\lambda\right)\prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B_0}\right\}$, for every $f_i \in L^{r_i}$ with $\supp f_i \subseteq R$, $i=1\cdots,m$. 
%Due to Fatou's Lemma, it is sufficient to consider that $E(B_0)$ is a bounded set.

On the one hand, from the construction of ${T}^{\star}_{\vec \eta,s}$, see \eqref{txing}, if for any \( x \in E(B_0) \), for any $B \in \B$ containing \( x \), the reverse inequality of \eqref{keyest.1} blow is valid, then $E(B_0)=\emptyset$. This implies \eqref{keyest.2} is valid. 

On the other hand, if for any \( x \in E(B_0) \), there exists \( B_x \in \B \) containing \( x \) such that
\begin{align}
\left\langle\left\|T_{\vec \eta}\left(\vec{f} \chi_{(B_x^{\dagger})^c}\right)\right\|_{\mathbb{V}}\right\rangle_{s_2,B_x^{\dagger}} \geq \Phi_{{T}^{\star}_{\vec \eta,s},\vec{r},\tilde{r}}\left(\lambda\right) \prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B_0},\label{keyest.1}
\end{align}
then $E\left( {{B_0}} \right) \subseteq \mathop  \cup \limits_{x \in E\left( {{B_0}} \right)} {B_x}.$ Further, by Lemma \ref{lem:aooa:3.3} \eqref{list-1}, there is a disjoint subfamily \( \{B_k\} \) such that \( E(B_0) \subseteq \bigcup_k B_k^{\dagger} \).



For each \( k \) and any $\lambda_1,\lambda_2 \in (0,1)$, we define the sets
\begin{align*}
B_{k,0}&:=\left\{x \in B_k \cap B_0:\left\|T_{\vec \eta}\left(\vec{f} \chi_{B_k^{\dagger}}\right)(x)\right\|_{\mathbb{V}} \leq \Phi_{T_{\vec \eta},\vec{r},\tilde{r}}\left(\lambda_1\right)\prod_{i=1}^m\left\langle\left\langle f_i\right\rangle\right\rangle_{\eta_i,r_i,B_k}\right\}, \\
B_{1}&:=\left\{x \in B_0:\left\|T_{\vec \eta}(\vec{f})(x)\right\|_{\mathbb{V}} > \Phi_{T^{}_{\vec\eta},\vec{r},\tilde{r}}\left(\lambda_{1}\right)\prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B_0}\right\}, \\
B_{2}&:=\left\{x \in B_0: \mathcal{M}^{\B,{\otimes}}_{\vec{\eta},\vec{r}}(\vec{f})(x)> \Phi_{\mathcal{M}_{\vec{\eta},\vec{r}}^{\B,\otimes},\vec{r},\tilde{r}}\left(\lambda_{2}\right)\prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B_0}\right\}.
\end{align*}
We now claim that 
\begin{align}
\bigcup_k B_{k,0} \subseteq B_{1} \cup B_{2}.\label{keyest.3}
\end{align}
Indeed, for every $k$, for any \( x \in B_{k,0} \setminus B_{1} \), it derives that
\begin{align*}
&\Phi_{{T}^{\star}_{\vec \eta,s},\vec{r},\tilde{r}}\left(\lambda\right) \prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B_0}\\
\le & \left\langle\left\langle\left\|T_{\vec \eta}\left(\vec{f} \chi_{(B_k^{\dagger})^c}\right)(\cdot)\right\|_{\mathbb{V}}\right\rangle_{s_2,B_k^{\dagger}}\right\rangle_{s_3,B^{\dagger}_k \ni x}\\ \notag
 \leq& \left\langle \left\|T_{\vec \eta}(\vec{f})\right\|_{\mathbb{V}}\right\rangle_{s_2,B_k^{\dagger}}+ \left\langle \left\|T_{\vec \eta}\left(\vec{f} \chi_{B_k^{\dagger}}\right)\right\|_{\mathbb{V}}\right\rangle_{s_2,B_k^{\dagger}} + \left\langle\left\langle\left\|T_{\vec \eta}\left(\vec{f} \chi_{(B_k^{\dagger})^c}\right)(x)-T_{\vec \eta}\left(\vec{f} \chi_{(B_k^{\dagger})^c}\right)\left(\cdot\right)\right\|_{\mathbb{V}}\right\rangle_{s_2,B_k^{\dagger}} \right\rangle_{s_3,B_k^{\dagger} \ni x}\\ \notag
= :& I_1 + I_2 + I_3.
\end{align*}
For $I_1$, it is derived from the structure of $B_{1}$ that
\begin{align*}
    I_1 & \leq \Phi_{T^{}_{\vec\eta},\vec{r},\tilde{r}}\left(\lambda_{1}\right)\prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B_0}\leq \Phi_{T^{}_{\vec\eta},\vec{r},\tilde{r}}\left(\lambda_{1}\right) \inf_{x \in B_0}{\mathcal{M}_{\eta,\vec{r}}^{\B,\otimes}}(\vec{f})(x)\\
    &\leq \Phi_{T_{\vec \eta},\vec{r},\tilde{r}}\left(\lambda_1\right) {\mathcal{M}_{\eta,\vec{r}}^{\B,\otimes}}(\vec{f})(x).
\end{align*}
For $I_2$, it follows from the structure of $B_{k,0}$ that
\begin{align*}
I_2 &\leq \Phi_{T_{\vec \eta},\vec{r},\tilde{r}}\left(\lambda_1\right)\prod_{i=1}^m\left\langle\left\langle f_i\right\rangle\right\rangle_{\eta_i,r_i,B_k} \leq \Phi_{T_{\vec \eta},\vec{r},\tilde{r}}\left(\lambda_1\right) {\mathcal{M}_{\eta,\vec{r}}^{\B,\otimes}}(\vec{f})(x).
\end{align*}
For $I_3$, it can be deduced from \eqref{M_2.condi.} that 
\begin{align*}
I_3 \le {C}_{2} \mathcal{M}^{\B,{\otimes}}_{\eta,\vec{r}}(\vec{f})(x).
\end{align*}






Collecting these estimates, we have that 
\begin{align*}
    \mathcal{M}^{\B,{\otimes}}_{\vec{\eta},\vec{r}}(\vec{f})(x)> \Phi_{\mathcal{M}_{\vec{\eta},\vec{r}}^{\B,\otimes},\vec{r},\tilde{r}}\left(\lambda_{2}\right)\prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B_0},
\end{align*}
that is, \eqref{keyest.3} is valid.


Next, from the fact that \( T_{\vec \eta} \in W_{\vec{r},\tilde{r}} \), we get
\begin{align*}
   \mu((B_k \cap B_0) \setminus B_{k,0}) \leq \lambda_1 \mu(B_k) 
%\leq \frac{1}{4\boldsymbol{C}_0}\mu(B_k),
\end{align*}
%where $\boldsymbol{C}_0$ is mentioned in Definition \ref{def:basis}.
Hence, we have \( \mu(B_{k,0}) \geq (1-\lambda_1)\mu(B_k) \).  This implies
\begin{align*}
\mu(E(B_0)) & \leq \sum_k \mu\left(B_k^{\dagger}\right) \leq \boldsymbol{C}_0\sum_k \mu\left(B_k\right) \leq \frac{\boldsymbol{C}_0}{1 - \lambda_1}\sum_k \mu\left(B_{k,0}\right).
\end{align*}

Therefore, for any $\lambda_1,\lambda_2 \in (0,1),$ since $T_{\vec{\eta}},\mathcal{M}^{\B,{\otimes}}_{\vec{\eta},\vec{r}} \in W_{\vec{r},\tilde{r}}$, it follows that
\begin{align*}
\mu(E(B_0))& \leq \frac{\boldsymbol{C}_0}{1 - \lambda_1} \mu\left(\bigcup_k B_{k,0}\right)\leq  \frac{\boldsymbol{C}_0}{1 - \lambda_1} \left(\mu(B_{1}) + \mu(B_{2})\right)\leq \frac{\boldsymbol{C}_0}{1 - \lambda_1}(\lambda_1 + \lambda_2) \mu(B_0),
\end{align*}
where we used the disjointness of \( \{B_k\} \).
We can take $\lambda_2=\lambda_1$ and we have 
\begin{align*}
\mu(E(B_0))\leq \frac{2\boldsymbol{C}_0\lambda_1}{1 - \lambda_1} \mu(B_0):=\lambda \mu(B_0).
\end{align*}


Last, \eqref{keyest.2} derives from the fact that
if for any $\lambda \in(0,1)$, then there is $\lambda_1 = \frac{\lambda }{{2\boldsymbol{C}_0 + \lambda }}\in (0,1)$, such that 
$\lambda= \frac{2\boldsymbol{C}_0\lambda_1}{1 - \lambda_1}$. 

%This fact can be deduced to consider the solution region $\Omega$: $ - {\lambda _1} < {\lambda _2} < \left( { - \frac{1}{{{C_0}}} - 1} \right){\lambda _1} + \frac{1}{{{C_0}}},$ where $\lambda_1,\lambda_2 \in (0,1)$. It is easy to see that $\Omega \neq \emptyset$. 




\emph{{\textbf{\textsf (ii):}}}
Finally, since $\mathcal{B}$ is doubling, for \( A \in \B \) with \( A^{\dagger} \subsetneq X \),  there is a set \( B \supseteq A \) satisfying \( \mu(B) \leq \gamma \mu(A) \). By Lemma \ref{lem:aooa:4.3} \eqref{ABC-1} below, 
\begin{align*}
\left\bracevert A, B \right\bracevert_{s_1} \lesssim \gamma^{\frac{1}{r}-\eta} \left(C_2+\Phi_{{T}_{\vec \eta},\vec{r},\tilde{r}}(\lambda_1)\right).
\end{align*}
This proves \eqref{M_1.condi.} for \( T_{\vec \eta} \). \qedhere
\end{proof}



We provide the auxiliary lemmas required for the above.


 \begin{lemma}\label{lem:aooa:4.2}
	Let $1 \leq r_1,\ldots,r_m < \infty$, $0 \leq \eta_1,\ldots,\eta_m < 1$,
with \( \eta = \sum_{i=1}^{m} \eta_i \), \( 0 \leq \eta_i r_i < 1 \), and \( s_1 \in [0, \infty) \). Let $A, B ,C\in \B$ with $ A \subseteq B \subseteq C$, the following results hold
\begin{list}{ $(\theenumi)$}{\usecounter{enumi}\leftmargin=1.2cm \labelwidth=1cm \itemsep=0.2cm \topsep=.2cm \renewcommand{\theenumi}{\alph{enumi}}}

\item\label{ABF-1}  $ \left\bracevert   A, B \right\bracevert_{s_1} \leq \left\bracevert   A, C \right\bracevert_{s_1}$.

\item\label{ABF-2}For any fixed $i \in \{1,\ldots,m\}$, 
 $
\left\langle \left\langle f_i \chi_{B^\dagger}\right\rangle\right\rangle_{\eta_i,r_i,A} \lesssim \left(\frac{\mu(B)}{\mu(A)}\right)^{\frac{1}{r_i}-\eta_i} \langle f\rangle_{\eta_i,r_i,B^\dagger}.
$
\end{list}
\end{lemma}

\begin{proof}

{\bf \eqref{ABF-1}.}
Let $A,B,C \in \B$ with $A \subseteq B \subseteq C$, $g_i := f_i \chi_{B^{\dagger}}$, and $f_i \in L^{r_i}(\mu)$ for $i = 1,\ldots,m$.
It follows that
\begin{align*}
	& \quad \left\langle\left\|{{T}_{\vec \eta}}\left(\vec{f} \chi_{B^\dagger \backslash A^{\dagger}}\right)\right\|_{\mathbb{V}}\right\rangle_{s_1,A}=\left\langle\left\|{{T}_{\vec \eta}}\left(\vec{f}\chi_{B^\dagger}\cdot \chi_{C^{\dagger} \backslash A^{\dagger}}\right)\right\|_{\mathbb{V}}\right\rangle_{s_1,A}\\
& \leq \left\bracevert   A, C \right\bracevert_{s_1} \prod_{i=1}^m\left\langle g_i\right\rangle_{\eta_i,r_i,C^{\dagger}}=\left\bracevert   A, C \right\bracevert_{s_1} \prod_{i=1}^m\left[\mu\left(B^\dagger\right) / \mu\left(C^{\dagger}\right)\right]^{\frac{1}{r_i}-\eta_i}\left\langle f_i\right\rangle_{\eta_i,r_i,B^\dagger} \\
& \leq \left\bracevert   A, C \right\bracevert_{s_1} \prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B^\dagger} .
\end{align*}
Then part \eqref{ABF-1} can be implied by \eqref{Deltaaa}.


{\bf \eqref{ABF-2}.}
Let $\tilde{A}, A, B \in \B$ with $A \subseteq \tilde{A} \cap B$. On the one hand, if $\mu(\tilde{A}) \leq \mu\left(B^\dagger\right)$, $\tilde{A} \subseteq B^2$ can be deduced from property \eqref{list:B4} and $\tilde{A} \cap B^\dagger \neq \emptyset$. It is derived that
	\begin{align}\notag
		\left\langle f_i \chi_{B^\dagger}\right\rangle_{\eta_i,r_i,\tilde{A}} &\leq\left[\mu\left(B^2\right) / \mu\left(\tilde{A}\right)\right]^{\frac{1}{r_i}-\eta_i}\left\langle f_i \chi_{B^\dagger}\right\rangle_{\eta_i,r_i,B^{2}} \\ \label{0604_1}
&\lesssim_{\boldsymbol{C}_0,\eta_i,r_i} [\mu(B) / \mu(A)]^{\frac{1}{r_i}-\eta_i}\langle f_i\rangle_{\eta_i,r_i,B^\dagger}.
	\end{align}
On the other hand, if $\mu(\tilde{A})>\mu\left(B^\dagger\right)$,  from property \eqref{list:B4} and $\tilde{A} \cap B^\dagger \neq \emptyset$, it can be deduced that $B^\dagger \subseteq \tilde{A}^{\dagger}$.  Then we obtain
\begin{align}\notag
	\left\langle f_i \chi_{B^\dagger}\right\rangle_{\eta_i,r_i,\tilde{A}} & \leq\left[\mu\left(\tilde{A}^{\dagger}\right) / \mu\left(\tilde{A}\right)\right]^{\frac{1}{r_i}-\eta_i}\left\langle f_i \chi_{B^\dagger}\right\rangle_{\eta_i,r_i,\tilde{A}^{\dagger}}\\ \label{0604_2} &\lesssim_{\boldsymbol{C}_0,\eta_i,r_i} \langle f\rangle_{\eta_i,r_i,B^\dagger} .
\end{align}
Since $A$ is arbitrary and $A \subseteq \tilde{A}$, the desired follows from \eqref{0604_1}, \eqref{0604_2}, and \eqref{avggg}.


\end{proof}
%\( 0 \leq \eta_i r_i < 1 \)
\begin{lemma}\label{lem:aooa:4.3}
Let $ \vec{r} = (r_i)_{i=1}^m \in [1, \infty)^m$, $ \vec{\eta} = (\eta_i)_{i=1}^m \in [0, 1)^m$ with $\eta=\sum\limits_{i=1}^m\eta_i$, \( 0 \le \eta_i r_i \leq 1\), and $s_1,s_2,s_3 \in [0,\infty)$ with $s_1 \leq s_3$. Assume that ${T}_{\vec \eta}$ is a $\mathbb{V}$-valued multilinear operator satisfying the condition \eqref{M_2.condi.} and ${T}_{\vec \eta} \in W_{\vec{r},\tilde{r}}$. Then the following statements hold:
\begin{list}{\rm (\theenumi)}{\usecounter{enumi}\leftmargin=1.2cm \labelwidth=1cm \itemsep=0.2cm \topsep=.2cm \renewcommand{\theenumi}{\arabic{enumi}}}

\item\label{ABC-1} 
	$
	 \left\bracevert   A, B \right\bracevert_{s_1} \lesssim\left(C_2+\Phi_{{T}_{\vec \eta},\vec{r},\tilde{r}}(\lambda)\right)[\mu(B) / \mu(A)]^{\frac{1}{r}-\eta}.
	$
\item\label{ABC-2} 
	$
	\left\bracevert   A, C \right\bracevert_{s_1} \lesssim\left(C_2+\Phi_{{T}_{\vec \eta},\vec{r},\tilde{r}}(\lambda)+ \left\bracevert   A, B \right\bracevert_{s_1}\right)[\mu(C) / \mu(B)]^{\frac{1}{r}-\eta}.
	$
\item\label{ABC-3} 
$
\left\bracevert   A, B^k \right\bracevert_{s_1} \lesssim \boldsymbol{C}_0^{\frac{k}{r}-\eta k}\left(C_2+\Phi_{{T}_{\vec \eta},\vec{r},\tilde{r}}(\lambda)+ \left\bracevert   A, B \right\bracevert_{s_1}\right), \quad k \geq 1.$
    \end{list}
where $\Phi_{{T}_{\vec{\eta}},\vec{r},\tilde{r}}:(0,1)\to(0,\infty)$ with $\lambda \in (0,1)$.
\end{lemma}

\begin{proof}

\emph{{\textbf{\textsf (1):}}}
Let $A,B\in \mathcal{B}$, $\lambda \in \left(0,\frac{1}{2}\right)$, setting $J_0=  \Phi_{{T}_{\vec \eta},\vec{r},\tilde{r}}(\lambda) \prod\limits_{i=1}^m\langle f_i\rangle_{\eta_i,r_i,A}$. 
It follows from $T_{\vec \eta} \in W_{\vec{r},\tilde{r}}$ and Definition \ref{def:multilinear_W} that
\begin{align*}
    &\quad  \mu\left(\left\{x \in A:\left\|T_{\vec \eta}\left(\vec{f} \chi_{B^\dagger}\right)(x)\right\|_{\mathbb{V}}>J_0\right\}\right) \leq \lambda \mu(A).
\end{align*}
Analogously,  $\mu\left(\left\{x \in A:\left\|T_{\vec \eta}\left(\vec{f} \chi_{A^{\dagger}}\right)(x)\right\|_{\mathbb{V}}> J_0 \right\}\right) \leq \lambda\mu(A) .$
From above estimates, it derived that
\begin{align}\label{0604_3}
    \mu\left(\{x \in A: \left\|T_{\vec \eta}(\vec{f} \chi_{B^{\dagger}\backslash A^{\dagger}})(x)\right\|_{\mathbb{V}} >2 J_0\}\right)
\le 2\lambda\mu(A). 
\end{align}

Set
\begin{align*}
    \bar{A} = \left\{x \in A:\left\|T_{\vec \eta}(\vec{f} \chi_{B^{\dagger}\backslash A^{\dagger}})(x)\right\|_{\mathbb{V}}\leq J_0\right\}.
\end{align*}
From \eqref{0604_3} and $2\lambda < 1$, we can conclude that $\bar{A} \neq \phi$, It follows that
\begin{align}\label{eq:aooa:4.3}
&\left\langle\left\|T_{\vec \eta}(\vec{f} \chi_{B^{\dagger}\backslash A^{\dagger}})\right\|_{\mathbb{V}}\right\rangle_{s_2,\bar{A}} \leq  2J_0 \lesssim\Phi_{{T}_{\vec \eta},\vec{r},\tilde{r}}(\lambda) [\mu(B) / \mu(A)]^{\frac{1}{r}-\eta} \prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B^\dagger}.
\end{align}
For any $x \in A$, it can be deducted from \eqref{M_2.condi.} and $\bar{A} \subseteq A$ that
\begin{align}\notag
&\quad  \left\langle  \left\langle\left\| T_{\vec \eta}(\vec{f} \chi_{B^{\dagger}\backslash A^{\dagger}})(x)-T_{\vec \eta}(\vec{f} \chi_{B^{\dagger}\backslash A^{\dagger}})\left(\cdot\right)\right\|_{\mathbb{V}}\right\rangle_{s_2,\bar{A}} \right \rangle_{s_3,A\ni x} \\ \label{eq:aooa:4.4}
& \quad \leq C_2 \prod_{i=1}^m\left\langle \left \langle f_i \chi_{B^\dagger}\right\rangle\right\rangle_{\eta_i,r_i,A} \lesssim C_2[\mu(B) / \mu(A)]^{\frac{1}{r}-\eta} \prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B^\dagger},
\end{align}
where we have used Lemma \ref{lem:aooa:4.2} part (b) in the last inequality.

Due to  $s_1 \leq s_3$, it derives from \eqref{eq:aooa:4.3} and \eqref{eq:aooa:4.4}
that
$$
\begin{aligned}
& \left\langle\left\|T_{\vec \eta}\left(\vec{f} \chi_{B^\dagger \backslash A^{\dagger}}\right)\right\|_{\mathbb{V}}\right\rangle_{s_1,A} \lesssim\left(C_2+\Phi_{T_{\vec \eta},\vec{r},\tilde{r}}(\lambda) \right)[\mu(B) / \mu(A)]^{\frac{1}{r}-\eta} \prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B^\dagger}
\end{aligned}
$$
This shows part \eqref{ABC-1}.


\emph{{\textbf{\textsf (2):}}}
Let $A, B, C \in \B$ with $A \subseteq B \subseteq C$. To estimate $\left\bracevert   A, C \right\bracevert_{s_1}$, since $\left\bracevert   A, C \right\bracevert_{s_1} \leq \left\bracevert   A, B \right\bracevert_{s_1} + \left\bracevert   B, C \right\bracevert_{s_1},$
it suffices to estimate $\left\bracevert   A, B \right\bracevert_{s_1}$ and $\left\bracevert   B, C \right\bracevert_{s_1}$. Further, it is sufficient to estimate $\left\langle \left\|T_{\vec \eta}\left(\vec{f} \chi_{C^{\dagger}\backslash B^\dagger}\right)\right\|_{\mathbb{V}} \right\rangle_{s_1,A}$ and $\left\langle \left\|T_{\vec \eta}\left(\vec{f} \chi_{B^{\dagger}\backslash A^\dagger}\right)\right\|_{\mathbb{V}} \right\rangle_{s_1,A}$.


On the one hand, for any $x \in A$, it follows from Definition \ref{Deltaaa} that
\begin{align}\label{eq:aooa:4.5}
   \left\langle \left\|T_{\vec \eta}\left(\vec{f} \chi_{C^{\dagger}\backslash B^\dagger}\right)\right\|_{\mathbb{V}} \right\rangle_{s_1,A}
\lesssim\left(C_2+\Phi_{T_{\vec \eta},\vec{r},\tilde{r}}(\lambda) \right)[\mu(C) / \mu(B)]^{\frac{1}{r}-\eta} \prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,C^{\dagger}}.
\end{align}
On the other hand, it derives from \eqref{M_1.condi.} that
\begin{align}\notag
    & \left\langle \left\|T_{\vec \eta}\left(\vec{f} \chi_{B^{\dagger}\backslash A^\dagger}\right)\right\|_{\mathbb{V}} \right\rangle_{s_1,A}\leq  \left\bracevert   A, B \right\bracevert_{s_1} \prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,B^\dagger} \\ \notag
& \quad \lesssim  \left\bracevert   A, B \right\bracevert_{s_1}\left[\mu\left(C^{\dagger}\right) / \mu\left(B^\dagger\right)\right]^{\frac{1}{r}-\eta} \prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,C^{\dagger}} \\ \label{eq:aooa:4.6}
& \quad \lesssim  \left\bracevert   A, B \right\bracevert_{s_1}[\mu(C) / \mu(B)]^{\frac{1}{r}-\eta} \prod_{i=1}^m\left\langle f_i\right\rangle_{\eta_i,r_i,C^{\dagger}}.
\end{align}
Then part \eqref{ABC-2} follows from \eqref{eq:aooa:4.5} and \eqref{eq:aooa:4.6}.



{\emph{{\textbf{\textsf (3):}}}
 It follows from part \eqref{ABC-2}, \eqref{BkBk}, and $\C_0 \geq 1$ that
\begin{align*}
    \left\bracevert  A, B^k \right\bracevert_{s_1} & \lesssim \C_0^{\frac{1}{r}-\eta}\left(C_2+\Phi_{{T}_{\vec \eta},\vec{r},\tilde{r}}(\lambda)\right) + \C_0^{\frac{1}{r}-\eta}\left\bracevert   A, B^{k-1} \right\bracevert_{s_1}\\
    & \lesssim \C_0^{\frac{1}{r}-\eta}\left(C_2+\Phi_{{T}_{\vec \eta},\vec{r},\tilde{r}}(\lambda)\right) + \C_0^{\frac{2}{r}-2\eta}\left(C_2+\Phi_{{T}_{\vec \eta},\vec{r},\tilde{r}}(\lambda)\right) + \C_0^{\frac{2}{r}-2\eta}\left\bracevert   A, B^{k-2} \right\bracevert_{s_1}\\
    &\lesssim \boldsymbol{C}_0^{\frac{k}{r}-\eta k}\left(C_2+\Phi_{{T}_{\vec \eta},\vec{r},\tilde{r}}(\lambda)+ \left\bracevert   A, B \right\bracevert_{s_1}\right). \qedhere
\end{align*}} 
\end{proof}





\begin{lemma}\label{lem:aooa:4.4}
Let $(X,\mu,\mathcal{B})$ equipped a measure space with a ball-basis $\mathcal{B}$. Let ${T}_{\vec{\eta}}\in W_{\vec{r},\tilde{r}}$, we set
\[
\boldsymbol{C} := C_1 + C_2 + \Phi_{{T}_{\vec{\eta}},\vec{r},\tilde{r}}(\lambda),
\]
with $\Phi_{{T}_{\vec{\eta}},\vec{r},\tilde{r}}:(0,1)\to(0,\infty)$. The following properties hold:
\begin{list}{\rm (\theenumi)}{\usecounter{enumi}\leftmargin=1.2cm \labelwidth=1cm \itemsep=0.2cm \topsep=.2cm \renewcommand{\theenumi}{\alph{enumi}}}

\item\label{DBB-1}
 For any $B \in \B$ with $B^{\dagger}=B$ there exists $\widehat{B} \in \B$ such that
	$$
	 B^2 \subseteq \widehat{B}, \quad \left\bracevert   B^2, \widehat{B} \right\bracevert_{s_1}  \lesssim \boldsymbol{C} , \quad \text { and } \quad \mu(\widehat{B}) \geq 2 \mu(B).
	$$

\item\label{DBB-2} For any $ B \in \B$ there exists $\widehat{B} \in \B$ such that $B^2 \subseteq \widehat{B}$,
	$$
	 \left\bracevert B^2, \widehat{B}\right\bracevert_{s_1} \lesssim \boldsymbol{C} , \quad \text { and either } \widehat{B}^2=\widehat{B} \text { or } \mu(\widehat{B}) \geq 2 \mu(B).
	$$

\item\label{DBB-3} For any $B \in \B$ there exists a sequence $\left\{B_k\right\}_{k \geq 0} \subseteq \B$ such that $X=\bigcup_{k \geq 0} B_k$ with $B_0=B$,
	$$
	B^2_{k-1} \subseteq B_k, \quad \text { and } \quad \left\bracevert B^2_{k-1}, B_k \right\bracevert_{s_1} \lesssim \boldsymbol{C} , \quad k \geq 1.
	$$	
    \end{list}
\end{lemma}

\begin{proof}~~

\emph{{\textbf{\textsf (a):}}}
 %We begin proving part \eqref{DBB-1}. 
 Fix $B \in \mathcal{B}$ with $B^{\dagger}=B$. By \eqref{M_1.condi.}, there exists $\widehat{B} \in \mathcal{B}$ such that $B \subsetneq \widehat{B}$ and $\left\bracevert B, \widehat{B}\right\bracevert_{s_1} \lesssim C_1$. Since $B^{\dagger}=B$, we have $B^2 = B \subsetneq \widehat{B}$ with $\left\bracevert B^2, \widehat{B}\right\bracevert_{s_1} = \left\bracevert B, \widehat{B}\right\bracevert_{s_1} \lesssim C_1$. Moreover, property \eqref{list:B4} implies $\mu(\widehat{B}) \geq 2\mu(B)$, as otherwise we would have the contradiction $\widehat{B} \subseteq B^{\dagger}=B$.

\emph{{\textbf{\textsf (b):}}}
To prove part \eqref{DBB-2}, fix $B \in \mathcal{B}$ and define 
\[
\mathcal{B}_B := \{A \in \mathcal{B} : B \subseteq A^\dagger\},
\]
with the associated quantities
\begin{align}\label{eqoo:4.7}
a := \sup_{\substack{A \in \mathcal{B}_B \\ \mu(A) \leq 2\mu(B)}} \mu(A) \quad \text{and} \quad b := \inf_{\substack{A \in \mathcal{B}_B \\ \mu(A) > 2\mu(B)}} \mu(A).
\end{align}
Note that $a \leq 2\mu(B) \leq b$. Choose $B_1, B_2 \in \mathcal{B}_B$ satisfying
\begin{align}\label{eqoo:4.8}
a/2 < \mu(B_1) \leq a \leq 2\mu(B) \leq b \leq \mu(B_2) < 2b.
\end{align}

First consider the case $b > \boldsymbol{C}_0^2 a$. Taking $\widehat{B} := B_1^\dagger \supseteq B$, it derives from \eqref{eqoo:4.8} that 
\begin{align}\label{eqoo:4.9}
\mu(\widehat{B}^\dagger) = \mu(B_1^2) \leq \boldsymbol{C}_0^2 \mu(B_1) \leq \boldsymbol{C}_0^2 a < b.
\end{align}
By the definition of $a$ and $b$ in \eqref{eqoo:4.7}, there exists no $B' \in \mathcal{B}_B$ with $a < \mu(B') < b$. Combining this with \eqref{eqoo:4.9} yields $\mu(\widehat{B}^\dagger) \leq a \leq 2\mu(B_1)$. Since $\widehat{B}^\dagger \cap B_1 \neq \emptyset$, property \eqref{list:B4} implies $\widehat{B}^\dagger \subseteq B_1^\dagger = \widehat{B} \subseteq \widehat{B}^\dagger$, hence $\widehat{B}^\dagger = \widehat{B}$. Consequently, $B^2 \subseteq \widehat{B}^2 = \widehat{B}$, and \eqref{eqoo:4.8} gives that
\begin{align}\label{eqoo:4.10}
\mu(B^2) \leq \mu(\widehat{B}) = \mu(B_1^\dagger) \leq \boldsymbol{C}_0 \mu(B_1) \leq 2\boldsymbol{C}_0 \mu(B) \leq 2\boldsymbol{C}_0 \mu(B^2).
\end{align}

When $b \leq \boldsymbol{C}_0^2 a$, set $\widehat{B} := B_2^3 = (B_2^\dagger)^2 \supseteq B^2$. From \eqref{eqoo:4.8}, it can be deduced that $\mu(\widehat{B}) \geq \mu(B_2) \geq b \geq 2\mu(B)$ and
\begin{align}\label{eqoo:4.11}
\mu(B^2) &\leq \mu(\widehat{B}) = \mu(B_2^3) \leq \boldsymbol{C}_0^3 \mu(B_2) \leq 2\boldsymbol{C}_0^3 b \\
&\leq 2\boldsymbol{C}_0^5 a \leq 4\boldsymbol{C}_0^5 \mu(B) \leq 4\boldsymbol{C}_0^5 \mu(B^2). \notag
\end{align}
The estimates \eqref{eqoo:4.10} and \eqref{eqoo:4.11} together show that $\mu(\widehat{B}) \approx \mu(B^2)$. 
It follows from Lemma \ref{lem:aooa:4.3} part \eqref{ABC-1} that
\[
\left\bracevert B^2, \widehat{B}\right\bracevert_{s_1} \lesssim \boldsymbol{C}. 
\]

\emph{{\textbf{\textsf (c):}}}
To complete part \eqref{DBB-3}, we set \( B_0 := B \) and use induction to construct the sequence \( \{ B_k \}_{k \geq 0} \). For each \( k \geq 1 \), we establish the following conditions hold
\[
B_{k-1}^2 \subseteq B_k, \quad \left\bracevert B_{k-1}^2, B_k \right\bracevert_{s_1} \lesssim \boldsymbol{C}, \quad \mu(B_k) \geq 2 \mu(B_{k-1}).
\]
Finally, by Lemma \ref{lem:BG}, we conclude that \( X = \bigcup_{k \geq 0} B_k \), completing the proof.

\end{proof}



