\end{align*}
This proof \eqref{GA-2_}.

\end{proof}


\begin{lemma}\label{lem:tree}
Let $\lambda \geq 3\boldsymbol{C}_0^4$, there exists a family $\mathcal{G} = \mathcal{G}(B_0) \subseteq \mathcal{B}$ such that
\begin{list}{$(\theenumi)$}{\usecounter{enumi}\leftmargin=.8cm \labelwidth=.8cm\itemsep=0.2cm\topsep=.1cm
\renewcommand{\theenumi}{\roman{enumi}}}

%这里是第一大块
\item \label{dk_1} For each $A \in \mathcal{G}$, there is  a subfamily $\mathcal{F}(A) \subseteq \mathcal{G}$, the following results hold

\begin{list}{$(\theenumi.\theenumii)$}{\usecounter{enumii}\leftmargin=.4cm \labelwidth=.8cm\itemsep=0.2cm\topsep=.1cm\renewcommand{\theenumii}{\arabic{enumii}}}
\item\label{tree-1} $A^{\dagger} \cap B \neq \emptyset,\quad \forall B \in \mathcal{F}(A);$
\item \label{tree-2} $\mu \left( \bigcup\limits_{B \in \mathcal{F}(A)} B^{\dagger} \right) \le 3\boldsymbol{C}_0^2 \lambda^{-1} \mu(A);$
\item \label{tree-3} $\varLambda(\vec{f} \chi_{A^3})(x) 
\lesssim \Phi_{\varLambda,\vec{r},\tilde{r}}\left(\frac{1}{\boldsymbol{C}_0^3 \lambda}\right) \prod_{i=1}^m \langle f_i \rangle_{\eta_i,r_i,A^3}, \quad a.e.\, x \in A^{\dagger} \setminus \bigcup_{B \in \mathcal{F}(A)} B$.
\end{list}

%这里是第二大块
\item \label{dk_2} For each $B \in\mathcal{F}(A)$ there are $\widehat{B} \in \B$ and $\xi \in \widehat{B}$ such that

\begin{list}{$(\theenumi.\theenumii)$}{\usecounter{enumii}\leftmargin=.4cm \labelwidth=.8cm\itemsep=0.2cm\topsep=.1cm\renewcommand{\theenumii}{\arabic{enumii}}}

\item \label{tree-4} $B^2 \subseteq \widehat{B} \subseteq A^{\dagger};$
\item \label{tree-5} $\varLambda(\vec{f} \chi_{A^3})(\xi) 
\lesssim \Phi_{\varLambda,\vec{r},\tilde{r}}\left(\frac{1}{\boldsymbol{C}_0^3 \lambda}\right) \prod_{i=1}^m \langle f_i \rangle_{\eta_i,r_i,A^3};$
\item \label{tree-6} $\left\| T_{\vec{\eta}}(\vec{f} \chi_{\widehat{B}^{\dagger} \setminus B^3})(x) \right\|_{\mathbb{V}} 
\lesssim \Phi_{\varLambda,\vec{r},\tilde{r}}\left(\frac{1}{\boldsymbol{C}_0^3 \lambda}\right) \prod_{i=1}^m \langle f_i \rangle_{\eta_i,r_i,A^3},\quad \forall x \in B^2.$
