\end{list}



\end{lemma}


\begin{proof}~~

{\emph{{\textbf{\textsf (i) :}}}}
We want to use Lemma \eqref{lem:GA} to prove \eqref{dk_1}. Then we start by the fact that $\mu(F(B_0)) \leq \lambda^{-1} {\mu(B_0)}{}$. 
Indeed, define the set 
\begin{align}\label{FAA}
F(B_0) := \left\{ x \in B_0^3 : \varLambda(\vec{f} \chi_{B_0^3})(x) > \Phi_{\varLambda,\vec{r},\tilde{r}}\left(\frac{1}{\boldsymbol{C}_0^3 \lambda}\right) \prod_{i=1}^m \langle f_i \rangle_{\eta_i,r_i,B_0^3} \right\}.
\end{align}
Since $\varLambda \in W_{\vec{r}, \tilde{r}}$, it derives that $\mu(F(B_0)) \le \left(\boldsymbol{C}_0^3 \lambda\right)^{-1} {\mu(B_0^3)} \le \lambda^{-1} {\mu(B_0)}{}.$


From Lemma \ref{lem:GA} with \( A = B_0 \) and \( F = F(B_0) \), it follows that there exists a collection \( \mathcal{F}(B_0) \subseteq \mathcal{B} \) such that
\begin{align}
\label{GAA-1}
F(B_0) \cap B_0^{\dagger} \cap B \neq \emptyset,
\end{align}
\begin{align}
\label{GAA-2}
F(B_0) \cap B_0^{\dagger} \subseteq \bigcup_{B \in \mathcal{F}(B_0)} B \text{ a.s.},
\end{align}
and
\begin{align}
\label{GAA-3}
\mu\left( \bigcup_{B \in \mathcal{F}(B_0)} B^{\dagger} \right) \le 3\boldsymbol{C}_0^2 \lambda^{-1} \mu(B_0).
\end{align}
To proceed, note that \eqref{GAA-2} yields that
 \( \mu\left( F(B_0) \cap B_0^{\dagger} \setminus \bigcup_{B \in \mathcal{F}(B_0)} B \right) = 0 \). Therefore, for almost every \( x \in B_0^{\dagger} \setminus \bigcup_{B \in \mathcal{F}(B_0)} B \), it can be deduced from \eqref{FAA} with $\varLambda \in W_{\vec{r}, \tilde{r}}$ that
\begin{align}\label{}
\varLambda(\vec{f} \chi_{B_0^3})(x) \lesssim \Phi_{\varLambda,\vec{r},\tilde{r}}\left(\frac{1}{\boldsymbol{C}_0^3 \lambda}\right) \prod_{i=1}^m \langle f_i \rangle_{\eta_i,r_i,B_0^3}.
\end{align}
These prove \eqref{dk_1}  for \( A = B_0 \).


{\emph{{\textbf{\textsf (ii) :}}}}
 For each \( B \in \mathcal{F}(B_0) \), it follows from \eqref{GA-2_} that there exists a set \( \widehat{B} \in \mathcal{B} \) such that
\begin{align}
\label{GAA-4}
\widehat{B} \not\subset F(B_0), \quad B^2 \subseteq \widehat{B} \subseteq B_0^{\dagger}, \quad \text{and} \quad \left\bracevert B^2, \widehat{B} \right\bracevert_{s_1} \lesssim \boldsymbol{C}.
\end{align}

Next we establish \eqref{tree-5} and \eqref{tree-6}.
Since \( \widehat{B} \not\subset F(B_0) \), it derives from \eqref{FAA} and $\varLambda \in W_{\vec{r}, \tilde{r}}$ that
\begin{align}
\label{Gaf}
\varLambda(\vec{f} \chi_{B_0^3})(\xi) \lesssim \Phi_{\varLambda,\vec{r},\tilde{r}}\left(\frac{1}{\boldsymbol{C}_0^3 \lambda}\right) \prod_{i=1}^m \langle f_i \rangle_{\eta_i,r_i,B_0^3}, \quad \xi \in \widehat{B} \setminus F(B_0)
\end{align}
For any \( x \in B^2 \), using \eqref{GAA-4} and \eqref{Gaf}, we obtain
\begin{align*}
&\left\| T_{\vec{\eta}}(\vec{f} \chi_{\widehat{B}^{\dagger}})(x) - T_{\vec{\eta}}(\vec{f} \chi_{B^3})(x) \right\|_{\mathbb{V}} \\
&= \left\| T_{\vec{\eta}}(\vec{f} \chi_{B_0^3 \cap \widehat{B}^{\dagger}})(x) - T_{\vec{\eta}}(\vec{f} \chi_{B_0^3 \cap B^3})(x) \right\|_{\mathbb{V}} \\
&\le \left\bracevert B^2, \widehat{B} \right\bracevert_{s_1}  \prod_{i=1}^m \langle f_i \chi_{B_0^3} \rangle_{\widehat{B}^{\dagger}, r} \lesssim \boldsymbol{C} \inf_{\widehat{B}} \mathcal{M}_{\eta,\vec{r}}^{\otimes,\mathcal{B}}(\vec{f} \chi_{B_0^3}) \\
&\le \varLambda(\vec{f} \chi_{B_0^3})(\xi) \lesssim \Phi_{\varLambda,\vec{r},\tilde{r}}\left(\frac{1}{\boldsymbol{C}_0^3 \lambda}\right) \prod_{i=1}^m \langle f_i \rangle_{\eta_i,r_i,B_0^3}.
\end{align*}
Thus, \eqref{tree-1}--\eqref{tree-6} are valid for \( A = B_0 \).

