\[{\mathcal{F}_{\eta,\nu,P}^\D}\left( {\vec f,f_{m+1}} \right): = \int_{{P^m}} {{\mathcal{K}_{\eta ,\nu,P }^\D}\left( {{x_1}, \cdots ,{x_{m+1}}} \right)\prod\limits_{j = 1}^{m+1} {{f_j}} \left( {{x_j}} \right)d{x_1} \cdots d{x_{m+1}}},\]

and $\mathcal K_{\eta,\nu,P}^\D: P^m \rightarrow \mathbb{C}$  satisfies
\begin{itemize}
\item 
\begin{align}
\left\|\mathcal K_{\eta,\nu,P}^\D\right\|_{L^{\infty}} \le |P|^{\eta-m}. \label{Kernel.1}
