\item there exists  $\eta \in [0,m)$ and exponents $r_1,\cdots, r_m, \widetilde{r} \in(1, \infty)$ such that $1 / r_1 +\cdots +1 / r_{m+1}-1 / \widetilde{r}=\eta$ and a constant $\mathcal{B}$ such that for every dyadic lattice $\mathscr{P} \subseteq \mathscr{D}$, 
$$
\mathbb{F}_{\eta,\nu}^{\mathscr{P}}\left(\vec{f},f_{m+1}\right):=\sum_{P \in \mathscr{P}} \mathcal{F}_{\eta,\nu,P}^\mathscr{P}\left(\vec{f},f_{m+1}\right)
