=& \sum_{\substack{P \in \D \\ P_0 \subsetneq P}} {\mathcal{F}_{\eta,\nu,P}^\D}(f_1,f_2,h) + \mathbb{F}_{\eta,\nu}^\mathscr{H}(f_1,f_2,h) + \sum_{P \in \Omega} \mathbb{F}_{\eta,\nu}^{\mathscr{D}(P)}(f_1 \chi_P,f_2 \chi_P,h\chi_P), \notag \\
=&\sum_{\substack{P \in \D \\ P_0 \subsetneq P}} {\mathcal{F}_{\eta,\nu,P}^\D}(f_1,f_2,h) + \mathbb{F}_{\eta,\nu}^\mathscr{H}(f_1,f_2,h) + \sum_{P \in \Omega} \mathbb{F}_{\eta,\nu}^{\mathscr{D}(P)}(f_1 \chi_P,f_2 \chi_P,h\chi_P), \label{kuohao5.3}
