J \in \mathscr{R}(P)}}\left|{\mathcal{F}_{\eta,\nu,R}^\D}\left(b_{1, P}, F_2, F_3\right)\right| \nonumber\\
& \leq \sum_{J \in \mathscr{H}^{\prime}} \sum_{\substack{P \in \Omega \\
J \in \mathscr{R}(P)}} \frac{\left\|b_{1, P}\right\|_{L^1}\left\|F_2 \chi_J\right\|_{L^1}\left\|F_3 \chi_J\right\|_{L^1}}{|J|^{2-\eta}},\label{kuohao5.6}
