then collecting \eqref{ine.3} and \eqref{kuohao5.6}, we have 

\begin{align*}
\left|\mathbb{F}_{\eta,\nu}^{\mathscr{H}'}\left(b_1, F_2, F_3\right)\right| & \lesssim_\delta \sum_{R \in \mathscr{H}^{\prime}} \sum_{\substack{P \in \Omega \\
J \in \mathscr{R}(P)}}\left\|b_{1, P}\right\|_{L^1}\langle | f_2| \rangle_{P_0}\langle | f_3| \rangle_{P_0} \\
& \lesssim_\delta|P_0|^{\eta+1}\langle | f_1| \rangle_{P_0}\langle | f_2| \rangle_{P_0}\langle | f_3| \rangle_{P_0} .
