\section{\bf Multilinear off-diagonal extrapolation theorem}\label{Sec.extro}
Let $\eta \in [0,m)$ and $\frac{1}{\tilde{p}}=\sum_{i=1}^{m}\frac{1}{p_i} - \eta$.  For convenience, we introduce a new way to express the $\omega \in A_{(\vec{p},\tilde{p}), (\vec{r},s)}$ as follows.
\[
A_{(\vec{p},\tilde{p}), (\vec{r},s)}=\sup _Q\left(\fint_Q \omega^{{\delta_{m+1}}} d x\right)^{\frac{1}{\delta_{m+1}}} \prod_{i=1}^m\left(\fint_Q \omega_i^{-{\delta_i}} d x\right)^{\frac{1}{\delta_i}}<\infty,
\]
where
\begin{align*}
	\frac{1}{\delta_i}=\frac{1}{r_i}-\frac{1}{p_i}, \quad i=1, \ldots, m, \quad \text{and} \quad \frac{1}{\delta_{m+1}} = \frac{1}{\tilde{p}} -\frac{1}{s} .
\end{align*}

Moreover, the condition \((\vec{r}, s) \preceq (\vec{p}, \tilde{p})\) implies \(\sum_{i=1}^{m-1} \frac{1}{\delta_i} \geq 0\). To proceed simplify the proof we introduce some notation and then classify the indices above.

 Let \(\vec{p} = (p_1, \ldots, p_m)\) and \(\vec{r} = (r_1, \ldots, r_m)\) be vectors with components satisfying \(1 \leq p_i < \infty\) and \(1 \leq r_i < \infty\) for all \(i = 1, \ldots, m\), respectively. Additionally, let \(s\) satisfy \(1 \leq s < \infty\) such that \((\vec{r}, s) \preceq (\vec{p}, \tilde{p})\). We then set
	\[
s':=r_{m+1},	\frac{1}{\gamma}:=\sum_{i=1}^{m+1} \frac{1}{r_i} = \sum_{i=1}^{m} \frac{1}{r_i} + \frac{1}{s'}, \quad \frac{1}{p_{m+1}}:=1  -\frac{1}{\tilde{p}},
	\]
    and
\begin{align}\label{zeta}
    	\sum_{i=1}^{m+1} \frac{1}{p_i}=1 + \eta \quad \text { and } \quad \sum_{i=1}^{m+1} \frac{1}{\delta_i}=\frac{1}{\gamma} - (1+\eta)=\frac{1-(1+\eta)\gamma}{\gamma}=\zeta.
\end{align}
Additionally, it follows from \((\vec{r}, s) \preceq (\vec{p}, \tilde{p})\) that $0<\gamma<1 + \eta$.
% Notice that as observed above we have that $0<\gamma<1$ and formally $\frac{1}{p_{m+1}}=\frac{1}{\tilde{p}'}$ which could be negative or zero if $\tilde{p} \leq 1$.




\subsection{Proof of Theorem \ref{thm:Ex_1}}~~

 The proof of Theorem \ref{thm:Ex_1} will consist of two steps.  In the first step we assume a special fact has shown and show how to iterate it to obtain the
desired result. The second step is devoted to proving the fact assumed in the first step. 


\emph{{\textbf{\textsf Step 1: Extrapolation from special to all components.}}}

By Remark~\ref{li:remark:1.8}, when $p_i = r_i$ for some $i$, we may take $r_i \leq q_i$. Thus $\vec{r} \preceq \vec{q}$ with $r_j < q_j$ for all $j$ where $r_j < p_j$.

In view of Remark \ref{li:remark:1.8} if $p_i=r_i$ for some $1 \leq i \leq m$ we can allow $r_i \leq q_i$. This means that $\vec{r} \preceq \vec{q}$ with $r_j<q_j$ for those $j$ 's for which $r_j<p_j$. We assume a special fact that
\begin{align}\notag
&\vec{u}=\left(u_1, \ldots, u_{m-1}, u_m\right) \, \text{with } \vec{r} \preceq \vec{u}\, \\ \label{eq:iioo:4.5}
& \quad \quad \text{extrapolates to}\,
 \vec{t}=\left(u_1, \ldots, u_{m-1}, t_m\right) \text { whenever } (\vec{r},s) \preceq (\vec{t},\tilde{t}) \text { and } r_m<t_m \text {. }
\end{align}
By this we mean that if \eqref{eq:iioo:1.2} holds for the exponent $\vec{u}$ and for all $\vec{\omega} \in A_{(\vec{u},\tilde{u}), (\vec{r},s)}$, then \eqref{eq:iioo:1.2} holds for the exponent $\vec{t}$ and for all $\vec{\omega} \in A_{(\vec{t},\tilde{t}),( \vec{r},s)}$ with $r_m<t_m$. 

Note that in \eqref{eq:iioo:4.5}, the first $m-1$ components of $\vec{u}$ and $\vec{t}$ are frozen. By switching $f_i$ with $f_m$ for some fixed $1 \leq i \leq m-1$ and using the same notation, we may freeze all components except the $i$-th to obtain
\begin{align}\notag
&\vec{u}=\left(u_1, \ldots, u_{i-1}, u_i, u_{i+1}, \ldots, u_m\right) \, \text{with } (\vec{r},s) \preceq (\vec{u},\tilde{u})\, \\ \label{eq:iioo:4.6}
& \quad \quad \text{extrapolates to}\,
\vec{t}=\left(u_1, \ldots, u_{i-1}, t_i, u_{i+1}, \ldots, u_m\right) \text { whenever } (\vec{r},s) \preceq (\vec{t},\tilde{t}) \text { and } r_i<t_i \text {. }
\end{align}

Therefore, to prove the desired result, we iterate \eqref{eq:iioo:4.6}, verifying at each step that $(\vec{r},s) \preceq (\vec{t},\tilde{t})$ and $r_i < t_i$ hold. We only need to consider two cases as follows.

\emph{{\textbf{\textsf Case 1:}}}
Given $p_i \leq q_i$ ($1 \leq i \leq m$), we first prove that  
\begin{align}\label{eq:iioo:4.7}
    \vec{p}=\left(p_1, \ldots, p_m\right) \text { extrapolates to } \vec{u}=\left(u_1, u_2, \ldots, u_m\right)=\left(q_1, p_2, \ldots, p_m\right).
\end{align}


First, if $q_1 = p_1$, the result is immediate. Otherwise, when $p_1 < q_1$, we have
\begin{align*}
r_1 \leq p_1 < q_1 &= u_1, \\
r_i \leq p_i &= u_i \quad \text{for all } 2 \leq i \leq m.
\end{align*} Further, it follows from $(\vec{r},s) \preceq (\vec{q},\tilde{q})$ that
\[
\frac{1}{\tilde{u}} =\sum_{i=1}^m \frac{1}{u_i} - \eta=\frac{1}{q_1}+\sum_{i=2}^m \left(\frac{1}{p_i} - \eta_i\right) \geq \sum_{i=1}^m \frac{1}{q_i} - \eta =  \frac{1}{\tilde{q}} >\frac{1}{s}.
\]
Therefore, $(\vec{r},s) \preceq (\vec{u},\tilde{u})$ holds with $r_1 < u_1$, so \eqref{eq:iioo:4.6} applies for $i=1$, yielding \eqref{eq:iioo:4.7}.

Similar to  \eqref{eq:iioo:4.7}, we can extrapolate to \(\vec{t} = (t_1, t_2, t_3, \ldots, t_m) = (q_1, q_2, p_3, \ldots, p_m)\). If \(q_2 \neq p_2\), we obtain
\[
r_1 \leq t_1, \quad r_2 < t_2, \quad \text{and} \quad r_i \leq t_i \;\; (i \geq 3).
\] Thus, it follows from $(\vec{r},s) \preceq (\vec{q},\tilde{q})$ that
\[
\frac{1}{\tilde{t}}=\sum_{i=1}^m \frac{1}{t_i}-\eta=\frac{1}{q_1}+\frac{1}{q_2}+\sum_{i=3}^m \frac{1}{p_i} - \eta \geq \sum_{i=1}^m \left(\frac{1}{q_i} - \eta_i\right)=\frac{1}{\tilde{q}}>\frac{1}{s}.
\]
Last, $(\vec{r},s) \preceq (\vec{t},\tilde{t})$ with $r_2 < t_2$, so \eqref{eq:iioo:4.6} applies to $i=2$, yielding the desired estimates for $\vec{t} = (q_1, q_2, p_3, \ldots, p_m)$. We iteratively apply this process for $i=3, \ldots, m$, and in the final step transition from $(q_1, \ldots, q_{m-1}, p_m)$ to $(q_1, \ldots, q_m)$. This completes the proof for this case.

\emph{{\textbf{\textsf Case 2:}}}
For some $i \in \{1,\ldots,m\}$, such that $p_i > q_i$. By reordering if necessary, we may assume
\begin{equation*}
\begin{cases}
p_i > q_i & \text{for } 1 \leq i \leq i_0, \\
p_i \leq q_i & \text{for } i_0+1 \leq i \leq m,
\end{cases}
\end{equation*}
where $1 \leq i_0 \leq m$ (with the case $i_0 = m$ corresponding to $p_i > q_i$ for all $1 \leq i \leq m$).

We proceed iteratively as before using \eqref{eq:iioo:4.6}. At the $i$-th step, we transition from $\vec{u} = (q_1, \ldots, q_{i-1}, p_i, p_{i+1}, \ldots, p_m)$ to $\vec{t} = (q_1, \ldots, q_{i-1}, q_i, p_{i+1}, \ldots, p_m)$. Without loss of generality, we may assume $p_i \neq q_i$ (otherwise the step is trivial). 
Observe that since $r_j \leq \min(p_j, q_j)$ for all $j$, we have $r_j \leq t_j$ for each $1 \leq j \leq m$. To verify that \eqref{eq:iioo:4.6} is applicable, we consider two cases:

First, consider $1 \leq i \leq i_0$. Since $r_i \leq q_i < p_i$, we have $p_i \neq r_i$, and thus by Remark~\ref{li:remark:1.8} it follows that $r_i < q_i$. Furthermore, for these indices $i$,
\begin{align}
    \frac{1}{\tilde{t}}=\sum_{j=1}^m \left(\frac{1}{t_j} -\eta_j\right) =\sum_{j=1}^i \frac{1}{q_j}+\sum_{j=i+1}^m \left(\frac{1}{p_j} - \eta_j\right)>\sum_{j=1}^m \left(\frac{1}{p_j} - \eta_j\right)=\frac{1}{\tilde{p}}>\frac{1}{s}.
\end{align}
Altogether, we have seen that $\vec{r} \preceq \vec{s}$ and $r_i<q_i$. Thus we can invoke \eqref{eq:iioo:4.6}.
Consider next the case $i_0+1 \leq i \leq m$ (if $i_0=m$ this case is vacuous). In this scenario, $r_i \leq p_i<q_i$ (recall that we have disregarded the trivial case $q_i=p_i$ ). In addition, since $i_0+1 \leq i \leq m$,
\begin{align}
    \frac{1}{\tilde{t}}=\sum_{j=1}^m \left(\frac{1}{t_j} -\eta_j\right) =\sum_{j=1}^i \frac{1}{q_j}+\sum_{j=i+1}^m \left(\frac{1}{q_j} - \eta_j\right)>\sum_{j=1}^m \left(\frac{1}{q_j} - \eta_j\right)=\frac{1}{\tilde{q}}>\frac{1}{s}.
\end{align}
Therefore, $(\vec{r},s) \preceq (\vec t,\tilde{t})$ and $r_i<q_i$ which justify the use of \eqref{eq:iioo:4.6}.

In both cases we can then perform the $i$-th step of the iteration and this completes the proof of \eqref{eq:iioo:1.3} for a generic $\vec{q}$.


\emph{{\textbf{\textsf Step 2: Extrapolation on one component.}}}


Now we demonstrate the fact \eqref{eq:iioo:4.5}.
We consider $\vec{r} \preceq \vec{q} = (q_1, \ldots, q_{m-1}, q_m)$ where $q_i = p_i$ for $i = 1, \ldots, m-1$ and $q_m > r_m$. 

For $\vec{v} \in A_{(\vec{q},\tilde{q}), (\vec{r},s)}$, define $v := \prod_{i=1}^m v_i$ and set
\[
r_{m+1} := s'; \quad \frac{1}{r} := \sum_{i=1}^{m+1} \frac{1}{r_i}; \quad p_{m+1} := \tilde{p}'; \quad q_{m+1} := \tilde{q}'.
\]
For each $i = 1, \ldots, m+1$, define
\[
\frac{1}{\delta_i} = \frac{1}{r_i} - \frac{1}{p_i}, \quad \frac{1}{\Delta_i} = \frac{1}{r_i} - \frac{1}{q_i}.
\]
Note that $\delta_i = \Delta_i$ for $i = 1, \ldots, m-1$, and we have the summations
\[
\sum_{i=1}^{m+1} \frac{1}{p_{m+1}} = \sum_{i=1}^{m+1} \frac{1}{q_{m+1}} = 1 + \eta.
\]
In view of \eqref{eq3.3}, this yields
\begin{align*}
\frac{1}{\varrho} &:= \frac{1}{r_m} - \frac{1}{r_{m+1}^{\prime}} - \eta + \sum_{i=1}^{m-1} \frac{1}{p_i} = \frac{1}{r_m} - \frac{1}{r_{m+1}^{\prime}} - \eta + \sum_{i=1}^{m-1} \frac{1}{q_i} \\
&= \frac{1}{\delta_m} + \frac{1}{\delta_{m+1}} = \frac{1}{\Delta_m} + \frac{1}{\Delta_{m+1}}.
\end{align*}

Setting $\omega_i := v_i$ for $i = 1, \ldots, m$, we apply Lemma \ref{lemma:main} $(i)$ to $\vec{v} \in A_{(\vec{q},\tilde{q}), (\vec{r},s)}$. Part $(i.1)$ gives for each $1 \leq i \leq m-1$:
