	V := v^{\frac{r_m}{\tilde{q}}} \widetilde{\omega}^{-\frac{r_m}{\delta_{m+1}}} \in A_{\frac{q_m}{r_m}, \frac{\Delta_{m+1}}{r_m}}(\widetilde{\omega}).
