where the second inequality uses the fact $\tilde{t_i}/t_i>1$.
With this estimate in hand the proof can be completed in exactly the same manner and we omit the details.


\begin{lemma}\label{lemma:main}
	Let $\eta \in [0,m)$, \(\vec{p} = (p_i)_{i=1}^m, \vec{r} = (r_i)_{i=1}^m \in [1, \infty)^m\), \(s \in [1, \infty)\), and $\frac{1}{\tilde{p}}=\sum\limits_{i=1}^{m}\frac{1}{p_i} - \eta$ such that \((\vec{r}, s) \preceq (\vec{p}, \tilde{p})\).
	With the notation above, we further assume that 
	%
	\begin{equation}\label{eq3.3}
	\frac1{\varrho}:=\frac 1{r_m}-\frac 1{r_{m+1}'}-\eta+\sum_{i=1}^{m-1}\frac1{p_i}
	=
	\frac1{\delta_m}+\frac1{\delta_{m+1}}
	>0,
	\end{equation}
	and for every $1\le i\le m-1$
	\begin{equation}\label{def:theta}
	\frac1{\theta_i}
	:=
	\zeta -\frac1{\delta_i}
	=
	\left(\sum_{j=1}^{m+1} \frac1{\delta_j}\right)-\frac1{\delta_i}
	>0.
	\end{equation}
	%
Then the following hold:
