\renewcommand{\theenumi}{\roman{enumi}}}
	\item Given  $\vec{\omega}=(\omega_1,\dots,\omega_m)\in A_{(\vec p,\tilde{p}), (\vec{r},s)}$, write $\omega:=\prod\limits_{i=1}^m\omega_i $ and set
		%
	\begin{equation}\label{eq3.4}
	\widetilde{\omega}:=\Big(\prod_{i=1}^{m-1}\omega_i \Big)^{\varrho}
	\qquad
	\mbox{and}
	\qquad
	W:= \omega^{ r_m } \widetilde{\omega}^{- \frac{r_m}{\delta_{m+1}}}= \omega_m^{ r_m }\widetilde{\omega}^{\frac{r_m}{\delta_m}}
