	Then,
\begin{list}{$(\theenumi.\theenumii)$}{\usecounter{enumii}\leftmargin=.4cm \labelwidth=.8cm\itemsep=0.2cm\topsep=.1cm\renewcommand{\theenumii}{\arabic{enumii}}}
	\item\label{lemma:main_i1} $\omega_i^{ \theta_i  }\in A_{\zeta \theta_i }$ with $\Big[\omega_i^{ \theta_i  }\Big]_{ A_{\zeta \theta_i }} \le [\vec \omega]_{A_{(\vec p,\tilde{p}), (\vec{r},s)}}^{\theta_i }$, for every $1\le i\le m-1$.
