\begin{proof}[\bf Proof of Lemma \ref{lemma:main}]~~

\emph{{\textbf{\textsf The preparation of the proof:}}}

We first classify the index introduced above as follows.
Since \((\vec{r}, s) \preceq (\vec{p}, \tilde{p})\) and $\sum\limits_{i=1}^{m-1} \frac{1}{\delta_{i}} \geq 0$, we can divide this discussion into two cases as follows.


\begin{list}{\rm (\theenumi)}{\usecounter{enumi}\leftmargin=1.2cm \labelwidth=1cm \itemsep=0.2cm \topsep=.2cm \renewcommand{\theenumi}{Case: \Roman{enumi}}}

\item \label{P1} Let \(\sum\limits_{i=1}^{m-1} \frac{1}{\delta_i} > 0\), set \(\zeta = \sum\limits_{i=1}^{m+1} \frac{1}{\delta_i}\). Then, 
\[
\zeta = \sum_{i=1}^{m-1} \frac{1}{\delta_i} + \frac{1}{\varrho} > \frac{1}{\varrho}.
\]
Let \(\mathcal{I} = \left\{i: 1 \leq i \leq m-1, \delta_i^{-1} \neq 0\right\} \neq \emptyset\) and \(\mathcal{I}^{\prime} = \{1, \ldots, m-1\} \backslash \mathcal{I}\).

Set
\[
\frac{1}{\upsilon_i} := \frac{1}{\delta_i} \left( \sum_{j=1}^{m-1} \frac{1}{\delta_j} \right)^{-1} = \frac{1}{\delta_i} \left( \sum_{j=1}^{m+1} \frac{1}{\delta_j} - \frac{1}{\delta_m} - \frac{1}{\delta_{m+1}} \right)^{-1} = \frac{1}{\delta_i} \left( \zeta - \frac{1}{\varrho} \right)^{-1}
\]
for every \(i \in \mathcal{I}\), and note that \(\sum\limits_{i \in \mathcal{I}} \frac{1}{\upsilon_i} = 1\);

\item \label{P2} Let $\sum\limits_{i=1}^{m-1} \frac{1}{\delta_i}=0$. If $\delta_m^{-1} \neq 0$, then
 for $1 \leq j \leq m-1$,  $p_j=r_j$ and $\frac{1}{\varrho}=\frac{1}{\delta_{m+1}}+\frac{1}{\delta_m}=\zeta$.
If $\delta_m^{-1} = 0$, then
 for $1 \leq j \leq m$,  $p_j=r_j$ and 
 $\frac{1}{\varrho}=\frac{1}{\delta_{m+1}}=\zeta$.
\end{list}

Before the formal proof we need to compute some estimates that are commonly used in below proof.
We start observing that equalities \eqref{eq3.4} in $(i)$, or \eqref{eq3.5} and \eqref{eq3.6} in case $(ii)$, easily yields
\begin{align}\label{eq3.9}
	\fint_B W^{\frac{\delta_{m+1}}{r_m}} d \widetilde{\omega}=\left(\fint_B \widetilde{\omega} d x\right)^{-1}\left(\fint_B \omega^{{\delta_{m+1}}} d x\right)
\end{align}
and whenever $\delta_m^{-1} \neq 0$ (i.e., $r_m<p_m$ )
\begin{align*}
	\fint_B W^{-\left(\frac{p_m}{r_m}\right)^{\prime}} d \widetilde{\omega}=\fint_B \omega_m^{-{r_m}\left(\frac{p_m}{r_m}\right)^{\prime}} \widetilde{\omega}^{-\frac{r_m}{\delta_m}\left(\frac{p_m}{r_m}\right)^{\prime}} d \widetilde{\omega}=\left(\fint_B \widetilde{\omega} d x\right)^{-1}\left(\fint_B \omega_m^{-{\delta_m}} d x\right) .
\end{align*}
These equalities yield if $\delta_m^{-1} \neq 0$
\begin{align}\notag
	&\left(\fint_B W^{\frac{\delta_{m+1}}{r_m}} d \widetilde{\omega}\right)\left(\fint_B W^{-\left(\frac{p_m}{r_m}\right)^{\prime}} d \widetilde{\omega}\right)^{\frac{\frac{\delta_{m+1}}{r_m}}{\left(\frac{p_m}{r_m}\right)^{\prime}}}\\ \label{eq3.10}
	&=\left(\fint_B \widetilde{\omega} d x\right)^{-1-\frac{\delta_{m+1}}{\delta_m}}\left(\fint_B \omega^{\delta_{m+1}} d x\right)\left(\fint_B \omega_m^{-\delta_m} d x\right)^{\frac{\delta_{m+1}}{\delta_m}}.
\end{align}
Thus, if $\delta_m^{-1} \neq 0$ and $\sum\limits_{i=1}^{m-1} \frac{1}{\delta_i}>0$ then
\begin{align}\notag
	&\left(\fint_B W^{\frac{\delta_{m+1}}{r_m}} d \widetilde{\omega}\right)\left(\fint_B W^{-\left(\frac{p_m}{r_m}\right)^{\prime}} d \widetilde{\omega}\right)^{\frac{\frac{\delta_{m+1}}{r_m}}{\left(\frac{p_m}{r_m}\right)^{\prime}}}\\ \label{eq3.11}
	&=\left[\left(\fint_B \widetilde{\omega}^{1-\left(\zeta \varrho\right)^{\prime}} d x\right)^{\frac{1}{\varrho}\left(\zeta \varrho-1\right)}\left(\fint_B \omega^{\delta_{m+1}} d x\right)^{\frac{1}{\delta_{m+1}}}\left(\fint_B \omega_m^{-\delta_m} d x\right)^{\frac{1}{\delta_m}}\right. \\ \notag
&\quad \quad \left.\times(\fint_B \widetilde{\omega} d x)^{-\frac{1}{\varrho}}\left(\fint_B \widetilde{\omega}^{1-\left(\zeta \varrho\right)^{\prime}} d x\right)^{-\frac{1}{\varrho}\left(\zeta \varrho-1\right)}\right]^{\delta_{m+1}}.
\end{align}
On the other hand, if $\sum\limits_{i=1}^{m-1} \frac{1}{\delta_i}>0$ and $\delta_m^{-1}=0$,
\begin{align}\notag
&\fint_B W^{\frac{\delta_{m+1}}{r_m}} d \widetilde{\omega}=\left(\fint_B \widetilde{\omega} d x\right)^{-1}\left(\fint_B \omega^{{\delta_{m+1}}} d x\right)\\ \label{eq3.12}
&=\left[\left(\fint_B \widetilde{\omega}^{1-\left(\zeta \varrho\right)^{\prime}} d x\right)^{\frac{1}{\varrho}\left(\zeta \varrho-1\right)}\left(\fint_B \omega^{{\delta_{m+1}}} d x\right)^{\frac{1}{\delta_{m+1}}}\right.\left.(\fint_B \widetilde{\omega} d x)^{-\frac{1}{\varrho}}\left(\fint_B \widetilde{\omega}^{1-\left(\zeta \varrho\right)^{\prime}} d x\right)^{-\frac{1}{\varrho}\left(\zeta \varrho-1\right)}\right]^{\delta_{m+1}}.
\end{align}


\emph{{\textbf{\textsf The formal proof:}}}


\emph{Proof to $(i.1)$.}~~

Assuming $\vec{\omega} \in A_{(\vec{p},\tilde{p}), (\vec{r},s)}$, we fix an index $1 \leq i \leq m-1$ and define the index sets:
\[
\mathcal{I} := \{j : 1 \leq j \leq m, \delta_j^{-1} \neq 0\}, \quad \mathcal{I}' := \{1,\ldots,m\} \setminus \mathcal{I}.
\]
We then set the exponents:
\[
\frac{1}{\upsilon_i} := \frac{\theta_i}{\delta_{m+1}}, \quad \frac{1}{\upsilon_j} := \frac{\theta_i}{\delta_j} \text{ for } j \in \mathcal{I} \setminus \{i\},
\]
which satisfy the normalization condition $\frac{1}{\upsilon_i} + \sum_{j \in \mathcal{I}\setminus\{i\}} \frac{1}{\upsilon_j} = 1$. It follows from Hölder's inequality that
\begin{align}
	&\fint_B \omega_i^{{\theta_i}} d x=\fint_B\left(\omega^{{\theta_i}} \prod_{\substack{1 \leq j \leq m \\ j \neq i}} \omega_j^{-{\theta_i}}\right) d x\\ \notag
	&\quad \leq\left(\fint_B \omega^{{\theta_i} \upsilon_i} d x\right)^{\frac{1}{\upsilon_i}}\left(\prod_{i \neq j \in \mathcal{I}}\left(\fint_B \omega_j^{-\frac{\theta_i}{\upsilon_j}}\right)^{\frac{1}{\upsilon_j}}\right)\left(\prod_{i \neq j \in \mathcal{I}^{\prime}} \underset{B}{\operatorname{ess\sup}} \, \omega_j^{-{\theta_i}}\right)\\
	&\quad \quad =\left(\fint_B \omega^{{\delta_{m+1}}} d x\right)^{\frac{\theta_i}{\delta_{m+1}}}\left(\prod_{i \neq j \in \mathcal{I}}\left(\fint_B \omega_j^{-{\delta_j}}\right)^{\frac{\theta_i}{\delta_j}}\right)\left(\prod_{i \neq j \in \mathcal{I}^{\prime}} \underset{B}{\operatorname{ess\sup}} \, \omega_j^{-1}\right)^{\theta_i} .
\end{align}
For $p_i = r_i$, $\theta_i = \gamma/(1-\gamma)$ yields $\omega_i^{\theta_i} \in A_1$ satisfying $[\omega_i^{\theta_i}]_{A_1} \leq [\vec{\omega}]^{\theta_i}$. When $p_i > r_i$, the relation $\theta_i(1 - (\zeta\theta_i)') = -\delta_i$ implies $\omega_i^{\theta_i/p_i} \in A_{\zeta\theta_i}$, it can be deduced that $[\omega_i^{\theta_i/p_i}]_{A_{\zeta\theta_i}} \leq [\vec{\omega}]^{\theta_i}$.


 \emph{Proof to $(i.2)$.}


\eqref{P1}: 
Using Hölder's inequality, we obtain
\begin{align} \label{eq3.13}
 \left(\fint_B \widetilde{\omega}^{1-\left(\zeta \varrho\right)^{\prime}} d x\right)^{\zeta \varrho-1}
	&=\left(\fint_B \prod_{i \in \mathcal{I}} \omega^{-\frac{\delta_i}{\upsilon_i} } \prod_{i \in \mathcal{I}^{\prime}} \omega_i^{- \varrho\left(\left(\zeta \varrho\right)^{\prime}-1\right)} d x\right)^{\zeta \varrho-1}
	\leq \prod_{i \in \mathcal{I}}\left(\fint_B \omega_i^{-{\delta_i}} d x\right)^{\frac{\varrho}{\delta_i}}\left(\prod_{i \in \mathcal{I}^{\prime}} \underset{B}{\operatorname{ess\sup}}\, \omega_i^{-{1}}\right)^{\varrho} .
\end{align}
If $\delta_m^{-1} \neq 0$, from Hölder's inequality with $\frac{\delta_{m+1}}{\varrho}=1+\frac{\delta_{m+1}}{\delta_m}>1$, it follows that
\begin{align}\label{eq3.14}
	\fint_B \widetilde{\omega} d x & =\fint_B \omega^{{\varrho}} \omega_m^{-{\varrho}} d x \leq\left(\fint_B \omega^{{\delta_{m+1}}} d x\right)^{\frac{\varrho}{\delta_{m+1}}} \left(\fint_B \omega_m^{-{\delta_m}} d x\right)^{\frac{\varrho}{\delta_m}}.
\end{align}
If $\delta_m^{-1}=0$ then $\varrho=\delta_{m+1}$ and
\begin{align}\label{eq3.15}
	\fint_B \widetilde{\omega} d x & =\fint_B \omega^{{\varrho}} \omega_m^{-{\varrho}} d x \leq\left(\fint_B \omega^{{\delta_{m+1}}} d x\right)^{\frac{\varrho}{\delta_{m+1}}} \left(\underset{B}{\operatorname{ess} \sup }\, \omega_m^{-{1}}\right)^{\varrho}.
\end{align}
Combining estimate \eqref{eq3.13} with either \eqref{eq3.14} or \eqref{eq3.15}, it can be deduced that
\[
[\widetilde{\omega}]_{A_{\zeta\varrho}} \leq [\vec{\omega}]_{A_{(\vec{p},\tilde{p}),(\vec{r},s)}}.
\]
This establishes the property $(i.2)$.


\eqref{P2}:
When $\delta_m = 0$, using $\widetilde{\omega} \in A_1$, we obtain
\begin{align*}
	&\quad \fint_B \widetilde{\omega} d x=\fint_B \omega^{{\delta_{m+1}}} \omega_m^{-{\delta_{m+1}}} d x \leq \fint_B \omega^{{\delta_{m+1}}} d x \, \underset{B}{\operatorname{ess\sup}} \, \omega_m^{-{\delta_{m+1}}}\\
	&\leq[\omega]_{A_{(\vec{p},\tilde{p}), (\vec{r},s)}}^{\delta_{m+1}}\left(\prod_{i=1}^{m-1} \underset{B}{\operatorname{ess\inf}} \,\omega_i^{}\right)^{\delta_{m+1}} \leq[\omega]_{A_{(\vec{p},\tilde{p}), (\vec{r},s)}}^{\varrho} \underset{B}{\operatorname{ess\inf}}\, \widetilde{\omega}. \\
\end{align*}

When $\delta_m \neq 0$, to show $\widetilde{\omega} \in A_1$, we use Hölder's inequality with $\frac{\delta_{m+1}}{\varrho}=1+\frac{\delta_{m+1}}{\delta_m}>1$ to obtain
\begin{align*}
	&\quad \fint_B \widetilde{\omega} d x=\fint_B \omega^{{\varrho}} \omega_m^{-{\varrho}} d x\\
	& \leq\left(\fint_B \omega^{{\delta_{m+1}}} d x\right)^{\frac{{\varrho}}{\delta_{m+1}}} \left(\fint_B \omega_m^{-{\delta_m}} d x\right)^{\frac{\varrho}{\delta_m}}\\
	&\leq[\omega]_{A_{(\vec{p},\tilde{p}), (\vec{r},s)}}^{\varrho}\left(\prod_{i=1}^{m-1} \underset{B}{\operatorname{essinf}}\, \omega_i^{}\right)^{\varrho} \leq[\omega]_{A_{(\vec{p},\tilde{p}), (\vec{r},s)}}^{\varrho} \underset{B}{\operatorname{essinf}}\, \widetilde{\omega}. \\
\end{align*}



\emph{Proof to $(i.3)$.}

\eqref{P1}:
Recall from the proof of $(i.2)$ that we established $\zeta\varrho > 1$. Applying Hölder's inequality with exponent $\zeta\varrho$, 
\[
1=\left(\fint_B \widetilde{\omega}^{\frac{\varrho}{\zeta}} \widetilde{\omega}^{-\frac{\varrho}{\zeta}} d x\right)^{\zeta \varrho} \leq\left(\fint_B \widetilde{\omega} d x\right)\left(\fint_B \widetilde{\omega}^{1-\left(\zeta \varrho\right)^{\prime}} d x\right)^{\zeta \varrho-1} .
\]
This, \eqref{eq3.11} and \eqref{eq3.13} yield if we further assume that $\delta_m^{-1} \neq 0$ (that is $r_m<p_m$ ):
\begin{align}\notag
	&\left[\left(\fint_B W^{\frac{\delta_{m+1}}{r_m}} d \widetilde{\omega}\right)\left(\fint_B W^{-\left(\frac{p_m}{r_m}\right)^{\prime}} d \widetilde{\omega}\right)^{\frac{\frac{\delta_{m+1}}{r_m}}{\left(\frac{p_m}{r_m}\right)^{\prime}}}\right]^{{\frac{1}{\delta_{m+1}}}}\\ \notag
	&\leq\left(\fint_B \widetilde{\omega}^{1-\left(\zeta \varrho\right)^{\prime}} d x\right)^{\frac{1}{\varrho}\left(\zeta \varrho-1\right)}\left(\fint_B \omega^{\delta_{m+1}} d x\right)^{\frac{1}{\delta_{m+1}}}\left(\fint_B \omega_m^{-\delta_m} d x\right)^{\frac{1}{\delta_m}} \\ \notag
	&\leq \prod_{i \in \mathcal{I}}\left(\fint_B \omega_i^{-{\delta_i}} d x\right)^{\frac{1}{\delta_i}}\left(\prod_{i \in \mathcal{I}^{\prime}} \underset{B}{\operatorname{ess\sup}}\, \omega_i^{-{1}}\right)^{1} \left(\fint_B \omega^{\delta_{m+1}} d x\right)^{\frac{1}{\delta_{m+1}}}\left(\fint_B \omega_m^{-\delta_m} d x\right)^{\frac{1}{\delta_m}}\\ \notag
	&\leq[\vec{\omega}]_{A_{(\vec{p},\tilde{p}), (\vec{r},s)}}^{\delta_{m+1}}.
\end{align}
This establishes that $W \in A_{\frac{p_m}{r_m}, \frac{\delta_{m+1}}{r_m}}(\widetilde{\omega})$ with 
$[W]_{A_{\frac{p_m}{r_m},\frac{\delta_{m+1}}{r_m}}}(\widetilde{\omega}) \leq [\vec{\omega}]^{\delta_{m+1}}$. 
When $\delta_m^{-1} = 0$ ($r_m = p_m$), from \eqref{eq3.12} and \eqref{eq3.13}, it follows that
\begin{align*}
	\left(\fint_B W^{\frac{\delta_{m+1}}{r_m}} d \widetilde{\omega}\right) &\leq\left[\left(\fint_B \widetilde{\omega}^{1-\left(\zeta \varrho\right)^{\prime}} d x\right)^{\frac{1}{\varrho}\left(\zeta \varrho-1\right)}\left(\fint_B \omega^{{\delta_{m+1}}} d x\right)^{\frac{1}{\delta_{m+1}}}\right]^{\delta_{m+1}}\\
	&\leq\left[\left(\prod_{i \in \mathcal{I}}\left(\fint_B \omega_i^{-{\delta_i}} d x\right)^{\frac{1}{\delta_i}}\right)\left(\prod_{i \in \mathcal{I}^{\prime}} \underset{B}{\operatorname{ess\sup}}\, \omega_i^{-{1}}\right)\left(\fint_B \omega^{{\delta_{m+1}}} d x\right)^{\frac{1}{\delta_{m+1}}}\right]^{\delta_{m+1}}\\
	&\leq[\vec{\omega}]_{A_{(\vec{p},\tilde{p}), (\vec{r},s)}}^{\delta_{m+1}} \underset{B}{\operatorname{ess\inf}} \, \omega_m^{{\delta_{m+1}}}=[\vec{\omega}]_{A_{(\vec{p},\tilde{p}), (\vec{r},s)}}^{\delta_{m+1}} \underset{B}{\operatorname{ess} \inf } \, W^{\frac{\delta_{m+1}}{r_m}}.
\end{align*}
since in this case $\varrho=\delta_{m+1}$ and $W=\omega_m^{{r_m}}=\omega_m$. 





\eqref{P2}:
If $\delta_m^{-1} = 0$, we can note that
\begin{align}\label{eq3.16}
	1=\fint_B \widetilde{\omega} \widetilde{\omega}^{-1} d x \leq\left(\fint_B \widetilde{\omega} d x\right) \underset{B}{\operatorname{ess} \sup } \,\widetilde{\omega}^{-1} \leq\left(\fint_B \widetilde{\omega} d x\right) \prod_{i=1}^{m-1} \underset{B}{\operatorname{ess} \sup } \, \omega_i^{-{\varrho}} .
\end{align}
It derives from this and \eqref{eq3.9} that
\begin{align*}
	&\quad \fint_B W^{\frac{\delta_{m+1}}{r_m}} d \widetilde{\omega}=\left(\fint_B \widetilde{\omega} d x\right)^{-1}\left(\fint_B \omega^{{\delta_{m+1}}} d x\right)\\
	&\leq[\vec{\omega}]_{A_{(\vec{p},\tilde{p}), (\vec{r},s)}}^{\delta_{m+1}}\left(\prod_{i=1}^{m-1} \underset{B}{\operatorname{ess} \sup }\,  \omega_i^{-{\delta_{m+1}}}\right)\left(\prod_{i=1}^m \underset{B}{\operatorname{ess} \sup }\, \omega_i^{-{1}}\right)^{-\delta_{m+1}}\\
	&=[\vec{\omega}]_{A_{(\vec{p},\tilde{p}), (\vec{r},s)}}^{\delta_{m+1}}\left(\underset{B}{\operatorname{ess} \sup } \, \omega_m^{-{1}}\right)^{-\delta_{m+1}}=[\vec{\omega}]_{A_{(\vec{p},\tilde{p}), (\vec{r},s)}}^{\delta_{m+1}}\left(\underset{B}{\operatorname{ess} \sup }\, W^{-\frac{\delta_{m+1}}{r_m}}\right)^{-1}.
\end{align*}
Here we have used the fact that in this case $\varrho = \delta_{m+1}$ and $W = \omega_m^{r_m} = \omega_m$, since $p_m = r_m$ by assumption. It follows $W \in A_{1,\frac{\delta_{m+1}}{r_m}}(\widetilde{\omega})$ from $[W]_{A_{1,\frac{\delta_{m+1}}{r_m}}(\widetilde{\omega})} \leq [\vec{\omega}]_{A_{(\vec{p},\tilde{p}),(\vec{r},s)}}^{\delta_{m+1}}.$
Note that since $0 < \widetilde{\omega} < \infty$ a.e., the measures $\mathrm{d}x$ and $\widetilde{\omega}\mathrm{d}x$ share the same null sets. Hence, $\esssup$ and $\essinf$ coincide for both measures.




If $\delta_m^{-1} \neq 0$,
in this case, from \eqref{eq3.10} and \eqref{eq3.16} it can be deduced that
\begin{align*}
	&\quad \left(\fint_B W^{\frac{\delta_{m+1}}{r_m}} d \widetilde{\omega}\right)\left(\fint_B W^{-\left(\frac{p_m}{r_m}\right)^{\prime}} d \widetilde{\omega}\right)^{\frac{\frac{\delta_{m+1}}{r_m}}{\left(\frac{p_m}{r_m}\right)^{\prime}}}\\ 
	&=\left(\fint_B \widetilde{\omega} d x\right)^{-1-\frac{\delta_{m+1}}{\delta_m}}\left(\fint_B \omega^{\delta_{m+1}} d x\right)\left(\fint_B \omega_m^{-\delta_m} d x\right)^{\frac{\delta_{m+1}}{\delta_m}}\\
	&\leq\left(\fint_B \omega^{{\delta_{m+1}}} d x\right)\left(\fint_B \omega_m^{-{\delta_m}} d x\right)^{\frac{\delta_{m+1}}{\delta_m}}\left(\prod_{i=1}^{m-1} \underset{B}{\operatorname{ess} \sup }\, \omega_i^{-{1}}\right)^{-\delta_{m+1}}\\
	&\leq[\vec{\omega}]_{A_{(\vec{p},\tilde{p}), (\vec{r},s)}}^{\delta_{m+1}}.
\end{align*}
Thus we get $(i .3)$, hence 
this completes the proof of $(i)$.


 \emph{Proof of $(ii)$}. 

Given the conditions $\omega_i^{\theta_i/p_i} \in A_{\zeta\theta_i}$ for $1 \leq i \leq m-1$, we have $\widetilde{\omega} \in A_{\zeta\varrho}$ by \eqref{eq3.5}, along with $W \in A_{p_m/r_m, \delta_{m+1}/r_m}(\widetilde{\omega})$. Given $\omega_m$ as specified in \eqref{eq3.6}, our objective is to demonstrate that $\vec{\omega} \in A_{(\vec{p},\tilde{p}),(\vec{r},s)}$. As in previous arguments, we consider two distinct cases.


\eqref{P1}:
Set $\upsilon_i=\zeta(m-1) \theta_i$ for $1 \leq i \leq m-1$ and $\upsilon_m=(m-1)\left(\zeta \varrho\right)^{\prime}$, considering
\[
\begin{aligned}
\sum_{i=1}^m \frac{1}{\upsilon_i} & =\frac{1}{(m-1)\zeta} \sum_{i=1}^{m-1} \frac{1}{\theta_i}+\frac{1}{(m-1)\left(\zeta \varrho\right)^{\prime}} \\
& =1-\frac{1}{(m-1)\zeta} \sum_{i=1}^{m-1} \frac{1}{\delta_i}+\frac{1}{m-1}-\frac{1}{m-1} \frac{1}{\zeta \varrho} \\
& =1-\frac{1}{(m-1)\zeta}\left(\zeta-\frac{1}{\varrho}\right)+\frac{1}{m-1}-\frac{1}{m-1} \frac{1}{\zeta \varrho} \\
& =1.
\end{aligned}
\]
It follows from Hölder's inequality with the exponents $\upsilon_i, 1 \leq i \leq m$ that
\begin{align*}
	1&=\left(\fint_B \widetilde{\omega}^{-\frac{1}{(m-1)\zeta \varrho}} \widetilde{\omega}^{\frac{1}{(m-1)\zeta \varrho}} d x\right)^{\zeta(m-1)}=\left(\fint_B \widetilde{\omega}^{\left(1-\left(\zeta \varrho\right)^{\prime}\right) \frac{1}{\upsilon_m}} \prod_{i=1}^{m-1} \omega_i^{\frac{\theta_i}{\upsilon_i}} d x\right)^{\zeta(m-1)}\\
	&\leq\left(\fint_B \widetilde{\omega}^{1-\left(\zeta \varrho\right)^{\prime}} d x\right)^{\frac{1}{\varrho}\left(\zeta \varrho-1\right)} \prod_{i=1}^{m-1}\left(\fint_B \omega_i^{{\theta_i}} d x\right)^{\frac{1}{\theta_i}}
\end{align*}
Given $\mathcal{I} = \{j : 1 \leq j \leq m-1, \delta_j^{-1} \neq 0\} \neq \emptyset$ and $\mathcal{I}^{\prime} = \{1, \ldots, m-1\} \backslash \mathcal{I}$, we note that $\theta_i ((\zeta \theta_i)^{\prime} - 1) = \delta_i$. It derives from above estimates that  
\begin{align*}
	&\quad \left(\prod_{i \in \mathcal{I}}\left(\fint_B \omega_i^{-\frac{\delta_i}{p_i}} d x\right)^{\frac{1}{\delta_i}}\right)\left(\prod_{i \in \mathcal{I}^{\prime}} \underset{B}{\operatorname{ess} \sup }\, \omega_i^{-{1}}\right)\\
    &\leq \prod_{i=1}^{m-1}\left[\omega_i^{{\theta_i}}\right]_{A_{\zeta \theta_i}}^{\frac{1}{\theta_i}}\left(\fint_B \omega_Q^{{\theta_i}} d x\right)^{-\frac{1}{\theta_i}}\\
	& \leq \left(\prod_{i=1}^{m-1}\left[\omega_i^{{\theta_i}}\right]_{A_{\zeta \theta_i}}^{\frac{1}{\theta_i}}\right) \left(\fint_B \widetilde{\omega}^{1-\left(\zeta \varrho\right)^{\prime}} d x\right)^{\frac{1}{\varrho}\left(\zeta \varrho-1\right)}.
\end{align*}
When $\frac{1}{\delta_m} \neq 0$,
this and \eqref{eq3.11} yield that
\begin{align*}
	&\quad \left(\fint_B \omega^{\delta_{m+1}} d x\right)^{\frac{1}{\delta_{m+1}}}\left(\fint_B \omega_m^{-\delta_m} d x\right)^{\frac{1}{\delta_m}}\left(\prod_{i \in \mathcal{I}}\left(\fint_B \omega_i^{-{\delta_i}} d x\right)^{\frac{1}{\delta_i}}\right)\left(\prod_{i \in \mathcal{I}^{\prime}} \underset{B}{\operatorname{ess} \sup } \,\omega_i^{-{1}}\right)\\
	&\leq \left(\prod_{i=1}^{m-1}\left[\omega_i^{\frac{\theta_i}{p_i}}\right]_{A_{\zeta \theta_i}}^{\frac{1}{\theta_i}}\right) \left[\left(\fint_B W^{\frac{\delta_{m+1}}{r_m}} d \widetilde{\omega}\right)\left(\fint_B W^{-\left(\frac{p_m}{r_m}\right)^{\prime}} d \widetilde{\omega}\right)^{\frac{\frac{\delta_{m+1}}{r_m}}{\left(\frac{p_m}{r_m}\right)^{\prime}}}\right]^{\frac{1}{\delta_{m+1}}}\\
	&\quad \quad \times (\fint_B \widetilde{\omega} d x)^{\frac{1}{\varrho}}\left(\fint_B \widetilde{\omega}^{1-\left(\zeta \varrho\right)^{\prime}} d x\right)^{\frac{1}{\varrho}\left(\zeta \varrho-1\right)}\\
	& \leq [W]^{\frac{1}{\delta_{m+1}}}_{A_{\frac{p_m}{r_m}, \frac{\delta_{m+1}}{r_m}}(\widetilde{\omega})}[\widetilde{\omega}]_{A_{\zeta\varrho}}^{\frac{1}{\varrho}}\left(\prod_{i=1}^{m-1}\left[\omega_i^{{\theta_i}}\right]_{A_{\zeta\theta_i}}^{\frac{1}{\theta_i}}\right).
\end{align*}
On the other hand, if $\frac{1}{\delta_m}=0$, we obtain \eqref{eq3.12}:
\begin{align*}
	&\quad \left(\fint_B \omega^{\delta_{m+1}} d x\right)^{\frac{1}{\delta_{m+1}}}\left(\underset{B}{\operatorname{ess} \sup } \,\omega_m^{-{1}}\right)\left(\prod_{i \in \mathcal{I}}\left(\fint_B \omega_i^{-{\delta_i}} d x\right)^{\frac{1}{\delta_i}}\right)\left(\prod_{i \in \mathcal{I}^{\prime}} \underset{B}{\operatorname{ess} \sup } \,\omega_i^{-{1}}\right)\\
	&\leq \left(\prod_{i=1}^{m-1}\left[\omega_i^{\frac{\theta_i}{p_i}}\right]_{A_{\zeta \theta_i}}^{\frac{1}{\theta_i}}\right) \left[\left(\fint_B W^{\frac{\delta_{m+1}}{r_m}} d \widetilde{\omega}\right)\left(\fint_B W^{-\left(\frac{p_m}{r_m}\right)^{\prime}} d \widetilde{\omega}\right)^{\frac{\frac{\delta_{m+1}}{r_m}}{\left(\frac{p_m}{r_m}\right)^{\prime}}}\right]^{\frac{1}{\delta_{m+1}}}\\
	&\quad \quad \times (\fint_B \widetilde{\omega} d x)^{\frac{1}{\varrho}}\left(\fint_B \widetilde{\omega}^{1-\left(\zeta \varrho\right)^{\prime}} d x\right)^{\frac{1}{\varrho}\left(\zeta \varrho-1\right)}\\
	& \leq [W]^{\frac{1}{\delta_{m+1}}}_{A_{1, \frac{\delta_{m+1}}{r_m}}(\widetilde{\omega})}[\widetilde{\omega}]_{A_{\zeta\varrho}}^{\frac{1}{\varrho}}\left(\prod_{i=1}^{m-1}\left[\omega_i^{{\theta_i}}\right]_{A_{\zeta\theta_i}}^{\frac{1}{\theta_i}}\right)\left(\underset{B}{\operatorname{ess} \sup } \, W^{-\frac{\delta_{m+1}}{r_m}}\right),
\end{align*}
since in this case $p_m=r_m, \varrho=\delta_{m+1}$, and $W=\omega_m^{{r_m}}=\omega_m$. 


\eqref{P2}: If $\delta_m^{-1} = 0$, hence $\theta_i=\zeta$ for every $1 \leq i \leq m-1$. It follows from Hölder's inequality that
\begin{align}\notag
	\underset{B}{\operatorname{ess\inf}}\left(\prod_{i=1}^{m-1} \omega_i\right) &\leq\left(\fint_B \prod_{i=1}^{m-1} \omega_i^{ \frac{\theta_i}{m-1}} d x\right)^{{(m-1)\zeta}}\\ \label{eq3.17}
    &\leq \prod_{i=1}^{m-1}\left(\fint_B \omega_i^{{\theta_i}} d x\right)^{\frac{1}{\theta_i}} \leq \prod_{i=1}^{m-1}\left[\omega_i^{{\theta_i}}\right]_{A_1}^{\frac{1}{\theta_i}} \underset{B}{\operatorname{ess\inf}}\, \omega_i^{}.
\end{align}
The last estimate we have used that in the present scenario $\zeta\theta_i=1$. 
From this and \eqref{eq3.9}, it can be deduced that
\begin{align*}
	\left(\fint_B \omega^{{\delta_{m+1}}} d x\right)^{\frac{1}{\delta_{m+1}}}&=\left(\fint_B W^{\frac{\delta_{m+1}}{r_m}} d \widetilde{\omega}\right)^{\frac{1}{\delta_{m+1}}}\left(\fint_B \widetilde{\omega} d x\right)^{\frac{1}{\delta_{m+1}}}\\
    &\leq [W]^{\frac{1}{\delta_{m+1}}}_{A_{1, \frac{\delta_{m+1}}{r_m}}(\widetilde{\omega})}[\widetilde{\omega}]_{A_1}^{\frac{1}{\delta_{m+1}}}\underset{B}{\operatorname{ess} \inf } \,W^{\frac{1}{r_m}} \underset{B}{\operatorname{ess} \inf } \,\widetilde{\omega}^{\frac{1}{\delta_{m+1}}}\\
	&\leq [W]^{\frac{1}{\delta_{m+1}}}_{A_{1, \frac{\delta_{m+1}}{r_m}}(\widetilde{\omega})}[\widetilde{\omega}]_{A_1}^{\frac{1}{\delta_{m+1}}}\underset{B}{\operatorname{ess} \inf }\, \omega_m^{} \underset{B}{\operatorname{ess} \inf }\left(\prod_{i=1}^{m-1} \omega_i^{\frac{1}{p_i}}\right)\\
	&\leq [W]^{\frac{1}{\delta_{m+1}}}_{A_{1, \frac{\delta_{m+1}}{r_m}}(\widetilde{\omega})}[\widetilde{\omega}]_{A_1}^{\frac{1}{\delta_{m+1}}}\left(\prod_{i=1}^{m-1}\left[\omega_i^{{\theta_i}}\right]_{A_1}^{\frac{1}{\theta_i}}\right)\left(\prod_{i=1}^m \underset{B}{\operatorname{ess\inf}} \, \omega_i^{}\right),
\end{align*}
where we have used that $p_m=r_m$,  $\omega_m=W^{\frac{p_m}{r_m}}=W$ and that $\varrho=\delta_{m+1}$. This readily leads to the desired estimate.

If $\delta_m^{-1} \neq 0$, by \eqref{eq3.10} and \eqref{eq3.17}, we obtain
\begin{align*}
	&\quad \left(\fint_B \omega^{\delta_{m+1}} d x\right)^{\frac{1}{\delta_{m+1}}}\left(\fint_B \omega_m^{-\delta_m} d x\right)^{\frac{1}{\delta_m}}\\
	& =\left(\fint_B W^{\frac{\delta_{m+1}}{r_m}} d \widetilde{\omega}\right)^{\frac{1}{\delta_{m+1}}}\left(\fint_B W^{-\left(\frac{p_m}{r_m}\right)^{\prime}} d \widetilde{\omega}\right)^{\frac{1}{r_m\left(\frac{p_m}{r_m}\right)^{\prime}}}\left(\fint_B \widetilde{\omega} d x\right)^{\frac{1}{\varrho}}\\
	& \leq [W]^{\frac{1}{\delta_{m+1}}}_{A_{\frac{p_m}{r_m}, \frac{\delta_{m+1}}{r_m}}(\widetilde{\omega})}[\widetilde{\omega}]_{A_1}^{\frac{1}{\varrho}} \underset{B}{\operatorname{ess} \inf }\left(\prod_{i=1}^{m-1} \omega_i^{}\right)\\
	& \leq [W]^{\frac{1}{\delta_{m+1}}}_{A_{\frac{p_m}{r_m}, \frac{\delta_{m+1}}{r_m}}(\widetilde{\omega})}[\widetilde{\omega}]_{A_1}^{\frac{1}{\delta_{m+1}}}\left(\prod_{i=1}^{m-1}\left[\omega_i^{{\theta_i}}\right]_{A_1}^{\frac{1}{\theta_i}}\right)\left(\prod_{i=1}^{m-1} \underset{B}{\operatorname{ess} \inf } \, \omega_i^{}\right).
\end{align*}
This immediately establishes that $\vec{\omega} \in A_{(\vec{p},\tilde{p}), (\vec{r},s)}$ with the required bound, thereby completing the proof of part $(ii)$.
Finally, we note that equations \eqref{eq3.7} and \eqref{eq3.8} follow directly from the definition of $\varrho$ combined with either \eqref{eq3.4} in $(i)$ or \eqref{eq3.6} in $(ii)$, which concludes the entire proof.
\end{proof}

\begin{lemma}\label{lem:Li 5.3}
Let $\eta \in [0,m)$, $\vec{p} = (p_i)_{i=1}^m$ with $1 < p_1, \dots, p_m < \infty$, $\frac{1}{{\tilde{p}}} := \sum\limits_{i=1}^m \frac{1}{p_i} - \eta > 0$, $\vec{r} = (r_i)_{i=1}^m$ with $1 \leq r_1, \dots, r_m < \infty$, and $s \in [1, \infty)$ such that $(\vec{r}, s) \preceq (\vec{p}, \tilde{p})$. For each $1 \leq i \leq m$, we define
\[
\frac{1}{\theta_i} := \zeta - \frac{1}{\delta_i} = \sum_{j=1}^{m+1} \frac{1}{\delta_j} - \frac{1}{\delta_i} > 0
\]
where we used the notation introduced below Sect. \ref{Sec.extro}. 
\begin{list}{$(\theenumi)$}{\usecounter{enumi}\leftmargin=1.2cm \labelwidth=1cm \itemsep=0.2cm \topsep=.2cm \renewcommand{\theenumi}{\roman{enumi}}}

\item\label{lem:Li:5.3_1}
For any $\vec{\omega} = (\omega_1, \ldots, \omega_m) \in A_{(\vec{p},\tilde{p}), (\vec{r},s)}$ with $\omega = \prod_{i=1}^m \omega_i$, then $
[\omega_i^{\theta_i}]_{A_{\zeta\theta_i}} \leq [\vec{\omega}]_{A_{(\vec{p},\tilde{p}),(\vec{r},s)}}^{\theta_i}$, for all $1 \leq i \leq m$, and
$[\omega^{\delta_{m+1}}]_{A_{\zeta\delta_{m+1}}} \leq [\vec{\omega}]_{A_{(\vec{p},\tilde{p}),(\vec{r},s)}}^{\delta_{m+1}}.$


\item \label{lem:Li:5.3_2}
Suppose $\omega_i^{\theta_i} \in A_{\zeta\theta_i}$ for all $1 \leq i \leq m$, and let $\omega := \prod_{i=1}^m \omega_i$ with $\omega^{\delta_{m+1}} \in A_{\zeta\delta_{m+1}}$. Then 
\[
[\vec{\omega}]_{A_{(\vec{p},\tilde{p}), (\vec{r},s)}} 
\leq [\omega^{\delta_{m+1}}]_{A_{\zeta\delta_{m+1}}}^{\frac{1}{\delta_{m+1}}} 
\prod_{i=1}^m [\omega_i^{\theta_i}]_{A_{\zeta\theta_i}}^{\frac{1}{\theta_i}}.
\]
\end{list}

\end{lemma}

\begin{proof}

\emph{{\textbf{\textsf (i):}}}
From Lemma \ref{lemma:main} $(i.1)$, it can be deduced that $\omega_i^{\theta_i} \in A_{\zeta\theta_i}$ with $[\omega_i^{\theta_i}]_{A_{\zeta\theta_i}} \leq [\vec{\omega}]_{A_{(\vec{p},\tilde{p}),(\vec{r},s)}}^{\theta_i}$
for all $1 \leq i \leq m-1$. The identical argument extends to the case $i=m$.
To complete the proof of $(i)$, we must verify $\omega^{\delta_{m+1}} \in A_{\zeta\delta_{m+1}}$. We partition the index set by defining $\mathcal{I} := \{1 \leq i \leq m \mid \delta_i^{-1} \neq 0\}, \quad \mathcal{I}' := \{1,\dots,m\}\setminus\mathcal{I}.$

If $\mathcal{I} = \emptyset$,
hence $\zeta = \delta_{m+1}^{-1}$, it follows that
\begin{align*}
&\quad \left[\omega^{{\delta_{m+1}}}\right]_{A_{\zeta \delta_{m+1}}}=\left[\omega^{{\delta_{m+1}}}\right]_{A_1}=\sup _Q\left(\fint_B \omega^{{\delta_{m+1}}} d x\right) \underset{B}{\operatorname{ess} \sup } \, \omega(x)^{-{\delta_{m+1}}}\\
&\leq \sup _Q\left(\fint_B \omega^{{\delta_{m+1}}} d x\right) \prod_{i=1}^m \underset{B}{\operatorname{ess} \sup } \, \omega_i(x)^{-{\delta_{m+1}}} \leq [\vec{\omega}]_{A_{(\vec{p},\tilde{p}), (\vec{r},s)}}^{\delta_{m+1}} .
\end{align*}

If $\mathcal{I} \neq \emptyset$, for each $i \in \mathcal{I}$
	\[
	\frac{1}{\upsilon_i}:=\frac{1}{\delta_i}\left(\sum_{j=1}^m \frac{1}{\delta_j}\right)^{-1}=\frac{1}{\delta_i}\left(\sum_{j=1}^{m+1} \frac{1}{\delta_j}-\frac{1}{\delta_{m+1}}\right)^{-1}=\frac{1}{\delta_i}\left(\zeta-\frac{1}{\delta_{m+1}}\right)^{-1},
	\]	
	and note that $\sum_{i \in \mathcal{I}} \frac{1}{\upsilon_i}=1$. 
It follows from Hölder's inequality that
\begin{align*}
&\left[\omega^{{\delta_{m+1}}}\right]_{A_{\zeta \delta_{m+1}}} = \sup _Q\left(\fint_B \omega^{{\delta_{m+1}}} d x\right)\left(\fint_B \omega^{{\delta_{m+1}}\left(1-\left(\zeta \delta_{m+1}\right)^{\prime}\right)} d x\right)^{\zeta \delta_{m+1}-1}\\
&\leq \sup_Q\left( \fint_B \omega^{{\delta_{m+1}}} d x\right) \left(\fint_B \prod_{i \in \mathcal{I}} \omega_i^{-\frac{\delta_i}{ \upsilon_i}} d x\right)^{\zeta \delta_{m+1}-1}\prod_{i \in \mathcal{I}'}\underset{B}{\operatorname{ess} \sup } \, \omega_i(x)^{-{\delta_{m+1}}}\\
&\leq \sup_Q\left( \fint_B \omega^{{\delta_{m+1}}} d x\right) \left(\prod_{i \in \mathcal{I}}\left(\fint_B \omega_i^{-{\delta_i}} d x\right)^{\frac{\delta_{m+1}}{\delta_i}}\right)\prod_{i \in \mathcal{I}'}\underset{B}{\operatorname{ess} \sup } \, \omega_i(x)^{-{\delta_{m+1}}}\\
&\leq [\vec{\omega}]_{A_{(\vec{p},\tilde{p}), (\vec{r},s)}}^{\delta_{m+1}}.
\end{align*}
This completes the proof of $(i)$.

\emph{{\textbf{\textsf (ii):}}}
If $\mathcal{I}=\emptyset$, for each $1 \leq i \leq m$ we have $\delta_i^{-1}=0$ and $\theta_i=\zeta=\delta_{m+1}$. It follows from Hölder's inequality that
\begin{align*}
	&\underset{B}{\operatorname{ess} \inf } \, \omega \leq\left(\fint_B \omega^{\frac{\delta_{m+1}}{m}} d x\right)^{\frac{1}{m \delta_{m+1}}}=\left(\fint_B \prod_{i=1}^m \omega_i^{ \frac{\theta_i}{m}} d x\right)^{\frac{1}{m \delta_{m+1}}}\\
	&\leq \prod_{i=1}^m\left(\fint \omega^{{\theta_i}{}} d x\right)^{\frac{1}{\delta_{m+1}}} \leq \prod_{i=1}^m\left[\omega_i^{{\theta_i}{}}\right]_{A_1}^{\frac{1}{\theta_i}} \underset{B}{\operatorname{ess} \inf } \, \omega_i
\end{align*}
and thus
\begin{align*}
[\vec{\omega}]_{A_{(\vec{p},\tilde{p}), (\vec{r},s)}}&=\sup _B\left(\fint_B \omega^{{\delta_{m+1}}} d x\right)^{\frac{1}{\delta_{m+1}}} \prod_{i=1}^m \underset{B}{\operatorname{ess} \sup } \, \omega_i(x)^{-1}\\
	&\leq \left[\omega^{{\delta_{m+1}}}\right]_{A_1}^{\frac{1}{\delta_{m+1}}}\left(\underset{B}{\operatorname{ess} \inf } \, \omega^{}\right)\leq\left[\omega^{{\delta_{m+1}}}\right]_{A_1}^{\frac{1}{\delta_{m+1}}} \prod_{i=1}^m\left[\omega_i^{{\theta_i}}\right]_{A_1}^{\frac{1}{\theta_i}}
\end{align*}
If $\mathcal{I} \neq \emptyset$, define
\[
\frac{1}{\theta_{m+1}}:=\zeta-\frac{1}{\delta_{m+1}}=\sum_{j=1}^{m+1} \frac{1}{\delta_j}-\frac{1}{\delta_{m+1}}>0
\]
Since $\sum\limits_{i=1}^{m+1} \frac{1}{\theta_i}=m\zeta$, it can be deduced from Hölder's inequality that
\begin{align*}
	1&=\left(\fint_B \omega^{- \frac{1}{m\zeta}} \omega^{ \frac{1}{m\zeta}} d x\right)^{m\zeta}=\left(\fint_B \omega^{- \frac{1}{m\zeta}} \prod_{i=1}^m \omega_i^{ \frac{1}{m\zeta}} d x\right)^{m\zeta}\\
	&\leq\left(\fint_B \omega^{-{\theta_{m+1}}} d x\right)^{\frac{1}{\theta_{m+1}}} \prod_{i=1}^m\left(\fint_B \omega_i^{{\theta_i}{}} d x\right)^{\frac{1}{\theta_i}}\\
	&=\left(\fint_B \omega^{{\delta_{m+1}}\left(1-\left(\zeta \delta_{m+1}\right)^{\prime}\right)} d x\right)^{\frac{1}{\delta_{m+1}}\left(\zeta \delta_{m+1}-1\right)} \prod_{i=1}^m\left(\fint_B \omega_i^{{\theta_i}} d x\right)^{\frac{1}{\theta_i}} .
\end{align*}
Together with our standing hypotheses, this establishes the required estimate
\begin{align*}
[\vec{\omega}]_{A_{(\vec{p},\tilde{p}), (\vec{r},s)}}&=\sup _B\left(\fint_B \omega^{{\delta_{m+1}}} d x\right)^{\frac{1}{\delta_{m+1}}}\left(\prod_{i \in \mathcal{I}}\left(\fint_B \omega_i^{-{\delta_i}} d x\right)^{\frac{1}{\delta_i}}\right) \prod_{i \in \mathcal{I}' } \underset{B}{\operatorname{ess} \sup } \, \omega_i(x)^{-1}\\
&\leq\left[\omega^{{\delta_{m+1}}}\right]^{\frac{1}{\delta_{m+1}}}_{A_{\zeta \delta_{m+1}}} \prod_{i=1}^m\left[\omega_i^{{\theta_i}}\right]^{\frac{1}{\theta_i}}_{A_{\zeta \theta_i}}\\
	&\quad \times\sup_B\left(\fint_B \omega^{{\delta_{m+1}}\left(1-\left(\zeta \delta_{m+1}\right)^{\prime}\right)} d x\right)^{-\frac{1}{\delta_{m+1}}\left(\zeta \delta_{m+1}-1\right)} \prod_{i=1}^m\left(\fint_B \omega_i^{{\theta_i}} d x\right)^{-\frac{1}{\theta_i}}\\
&\leq\left[\omega^{{\delta_{m+1}}}\right]^{\frac{1}{\delta_{m+1}}}_{A_{\zeta \delta_{m+1}}} \prod_{i=1}^m\left[\omega_i^{{\theta_i}}\right]^{\frac{1}{\theta_i}}_{A_{\zeta \theta_i}}.
\end{align*}
This completes the proof.

\end{proof}

\subsection{Proof of Theorem \ref{op.to.jh}}~~

In this subsection, we want to prove Theorem \ref{op.to.jh}. Before this, we need some Lemmas as follows.

\begin{lemma}[\cite{Damain2014}, Lemma 2.2.1]\label{dam_RH}
Let $\omega \in A_{\infty}$ and define
\[
\rho_\omega=1+\frac{1}{6\left(32 A_0^2\left(4 A_0^2+A_0\right)^2\right)^{C_\mu}[\omega]_{A_{\infty}}},
\]
where $A_0$ is defined in  Definition \ref{quasi-metric} and \ref{def:doubling} below. Then
\[
\left(\fint_B \omega^r d \mu\right)^{1 / r} \leq 2(4 A_0)^{C_\mu} \fint_{2 A_0 B} \omega d \mu
\]
for any ball $B \in X$.
\end{lemma}

By the Cauchy integral trick, we can obtain the following theorem, whose proof are same as \cite[Theorem 4.3]{Tor2019}.

\begin{theorem}\label{thm:multilinear:main:I}
Let $T_{\vec \eta}$ be an $m$--linear operator. Let $m \in \N$, $\eta \in [0,m)$, $p_1,\dots,p_m \in [1, \infty)$ and $\frac{1}{{\tilde{p}}}:=\sum\limits_{i = 1}^m {\frac{1}{{{p_i}}}} - \eta >0$. Suppose that there exist increasing functions $\phi_i: [1, \infty)\to [0, \infty)$ such that for all $\vec \omega = (\omega_1, \dots, \omega_m)$ satisfying $\omega_i^{\theta_i}\in A_{t_i},$ where $\theta_i > 0$, $1 <t_i< \infty$, for $ 1\leq i\leq m$. Then
\begin{align}\label{product-weight}
    \left\|{T}_{\vec{\eta}}(\vec{f})\right\|_{L^{\tilde{p}}(\omega^{\tilde{p}})} \lesssim \prod_{i=1}^m \phi_i\left([\omega_i^{\theta_i}]_{A_{t_i}}\right)\left\|f_i\right\|_{L^{p_i}(\omega_i^{p_i})},
\end{align}
where $\omega:=\prod\limits_{i=1}^m \omega_i$.

Then for all ${\bf b}=\left(b_1, \ldots, b_m\right) \in \mathrm{BMO}^m$ and ${\bf k }\in \N_0^m$, for each $\omega_i$ with $1\le j\le m$, there exist some $1<\tau_i<\infty$ such that $\omega_i^{\tau_i \theta_i} \in A_{t_i}$, then
\begin{equation}
\label{multi-commutator-I}
\left\|{T}_{\vec{\eta}}^{{\bf b, k}}(\vec{f})\right\|_{L^{\tilde{p}}(\omega^{\tilde{p}})}
\leq {\bf k}!\prod_{i=1}^m \frac1{R_i^{k_i}}\phi_i
\left(4^{\theta_iR_i}[\omega_i^{\theta_i\tau_i}]^{1/\tau_i}_{A_{t_i}}\right)\|b_i\|^{k_i}_{\BMO} \|f_i\|_{L^{p_i}\left(\omega_i^{p_i}\right)},
\end{equation}	
where $R_i=\frac{\min\{1, t_i-1\}}{\tau_i'\theta_i}$, $1\le i\le m$.
\end{theorem}



