\begin{lemma}\label{extra.t.b.pre}
Let $m \in \N$, $\eta \in [0,m)$, $r_1,\cdots,r_m ,s' \in [1,\infty)$, $p_1,\dots,p_m \in [1, \infty)$, and $\frac{1}{{\tilde{p}}}:=\sum\limits_{i = 1}^m {\frac{1}{{{p_i}}}} - \eta >0$, such that $(\vec{r}, s) \prec (\vec{p}, \tilde{p})$. Let $\gamma_i > 0$ with $i \in \{1,\ldots,m\}$ satisfying below \eqref{keychosse}. If $\vec{\omega} \in A_{(\vec{p},\tilde{p}), (\vec{r},s)}$, for all ${\bf b}=\left(b_1, \ldots, b_m\right) \in \mathrm{BMO}^m$, such that
\[
\vec{v}:=\left(v_1, \ldots, v_m\right):=\left(\omega_1 e_{b_1}, \ldots, \omega_m e_{b_m}\right):=\left(\omega_1 e^{-\operatorname{Re}\left(z_1\right) p_1 b_1}, \ldots, \omega_m e^{-\operatorname{Re}\left(z_m\right) p_m b_m}\right).
\]
then $\vec{v} \in A_{(\vec{p},\tilde{p}), (\vec{r},s)}$.
\end{lemma}


\begin{proof}[Proof of Lemma \ref{extra.t.b.pre}]
By Lemma \ref{lem:Li 5.3} $(i)$, applied to $\vec{\omega} \in A_{(\vec{p},\tilde{p}), (\vec{r},s)}$, it follows that 
\begin{align*}
\left\{\begin{array}{l}
\left[\omega^{\delta_{m+1}}\right]_{A_{\zeta \delta_{m+1}}} \leq [\vec{\omega}]_{A_{(\vec{p},\tilde{p}),(\vec{r}, s)}}^{\delta_{m+1}};\\
\left[\omega_i^{\theta_i}\right]_{A_{\zeta \theta_i}}^{\zeta \delta_i - 1} = [\omega_i^{-\delta_i}]_{A_{\zeta \delta_i}} \leq [\vec{\omega}]_{A_{(\vec{p},\tilde{p}),(\vec{r}, s)}}^{\delta_{m+1}},\quad i= 1,\ldots,m.
\end{array}\right.
\end{align*}
From Lemma \ref{dam_RH}, for a given weight $\omega$, we use the notation $\rho(\omega)$ instead of $\rho_\omega$. Then there exist 
\begin{align*}
	\varrho=\varrho(\vec \omega)=\min \left\{\rho\left(v^{\delta_{m+1}}\right), \rho\left(v_1^{-\delta_1}\right),\ldots, \rho\left(\omega_m^{-\delta_m}\right)\right\}>1
\end{align*}
so that
\begin{align}\label{keychosse_0}
	\varrho^{\prime} \approx \max \left\{\left[\omega^{{\delta_{m+1}}{}}\right]_{A_{\zeta \delta_{m+1}}},\left[\omega_1^{-{\delta_1}{}}\right]_{A_{\zeta \delta_1}}, \ldots,\left[\omega_m^{-{\delta_m}{}}\right]_{A_{\zeta \delta_m}}\right\} \leq [\vec{\omega}]^{\Xi}_{A_{(\vec{p},\tilde{p}),(\vec{r}, s)}},
\end{align}
where $\Xi=\max \left\{ {\frac{{{p_1r_1}}}{{{p_1} - {r_1}}}, \cdots ,\frac{{{p_mr_m}}}{{{p_m} - {r_m}}},\frac{{\tilde{p}'s'}}{{\tilde{p}' - s'}}} \right\}$.

It follows from the reverse Hölder inequalities that
\[
\left(\fint_B \omega^{{\delta_{m+1}}{} \varrho} d x\right)^{\frac{1}{\varrho}} \leq 2(4 A_0)^{C_\mu} \fint_{2 A_0 B} \omega^{{\delta_{m+1}}} d x
\]
and, for $i=1, \ldots, m$,
\[
\left(\fint_B \omega_i^{-{\delta_i}{} \varrho} d x\right)^{\frac{1}{\varrho}} \leq 2(4 A_0)^{C_\mu} \fint_{2 A_0 B} \omega_i^{-{\delta_i}{}} d x.
\]
From the previous estimates, the Hölder's inequality with $\sum\limits_{i=1}^m \frac{p}{p_i}=1$, and $\omega:=\prod\limits_{i=1}^m \omega_i$, it derives that
\begin{align}\notag
&\quad \left(\fint_B v^{\delta_{m+1}} d x\right)^{\frac{1}{\delta_{m+1}}} \prod_{i=1}^m\left(\fint_B v_i^{-{\delta_i}{}} d x\right)^{\frac{1}{\delta_i}} =\left(\fint_B \omega^{{\delta_{m+1}}} \prod_{i=1}^m e_{b_i}^{{\delta_{m+1}}{}} d x\right)^{\frac{1}{\delta_{m+1}}} \prod_{i=1}^m\left(\fint_B \omega_i^{-{\delta_i}{}} e_{b_i}^{-{\delta_i}{}} d x\right)^{\frac{1}{\delta_i}}\\ \notag
& \leq \left(\fint_B \omega^{{\delta_{m+1}}{} \varrho} d x\right)^{\frac{1}{\delta_{m+1} \varrho}} \prod_{i=1}^m\left(\fint_B \omega_i^{-{\delta_i}{} \varrho} d x\right)^{\frac{1}{\delta_i \varrho}} \left(\fint_B \prod_{i=1}^m e_{b_i}^{{\delta_{m+1}}{} \varrho^{\prime}} d x\right)^{\frac{1}{\delta_{m+1 \varrho^{\prime}}}}\prod_{i=1}^m\left(\fint_B e_{b_i}^{-{\delta_i}{} \varrho^{\prime}} d x\right)^{\frac{1}{\delta_i \varrho^{\prime}}}\\ \notag
&\leq 2^{(1+2C_{\mu})\zeta}A_0^{\zeta C_{\mu}}[\vec{\omega}]_{A_{(\vec{p},\tilde{p}),(\vec{r}, s)}} \prod_{i=1}^m\left(\fint_B (e_{b_i})^{p_i \cdot \frac{\delta_{m+1}}{p} \varrho^{\prime}} d x\right)^{\frac{p}{\delta_{m+1} \varrho^{\prime} p_i}}\left(\fint_B (e_{b_i})^{p_i \cdot (-\frac{\delta_i}{p_i} \varrho^{\prime})} d x\right)^{\frac{1}{\delta_i \varrho^{\prime}}}\\ \label{keychosse_1}
& \leq_{} 2^{(1+2C_{\mu})\zeta}A_0^{\zeta C_{\mu}}[\vec{\omega}]_{A_{(\vec{p},\tilde{p}),(\vec{r}, s)}} \prod_{i=1}^m\left[e_{b_i}^{\frac{\delta_{m+1}p_i}{p} \varrho^{\prime}}\right]_{A_{1+\frac{\delta_{m+1} p_i}{\delta_ip}}}^{\frac{p}{\delta_{m+1} \varrho^{\prime} p_i}} \lesssim_{C_{\mu},A_0,\zeta} 4^{ \sum\limits_{i=1}^m \gamma_i} [\vec{\omega}]_{A_{(\vec{p},\tilde{p}),(\vec{r}, s)}},
\end{align}
where the last estimate holds by \cite[Lemma 3.5]{Tor2019},  provided
\begin{align}\label{keychosse}
	\gamma_i\varrho^{\prime} \leq  \min \left\{\frac{1}{\delta_i}, \frac{p}{\delta_{m+1} p_i}\right\}.
\end{align}
Thus, we get $\vec{v} \in A_{(\vec{p},\tilde{p}), (\vec{r},s)}$.
\end{proof}





