\section{\bf Quantitative weighted estimates}\label{sec.qwe}


\subsection{Sharp-type estimates}\label{sharp}
~~

\begin{definition}
Let $(X,\mu,\mathcal{B})$ be a ball-basis measure space. We say that $\B$ satisfies the Besicovitch $D_0$-condition with a constant $D_0 \in \mathbb{N}$ if for any collection $\mathcal{S} \subseteq \B$ one can find a subcollection $\mathcal{S}^{\prime} \subseteq \mathcal{S}$ such that
\[
\bigcup_{A \in \mathcal{S}} A=\bigcup_{A \in \mathcal{S}^{\prime}} A, \quad \sum_{A \in \mathcal{S}^{\prime}} \chi_A(x) \leq D_0
\]
We say that $\B$ is a martingale system if $D_0=1$.
\end{definition}

Recall that
\begin{align*}
M^{\B,w}_{r} f(x):=\sup _{B \in \B: x \in B}\left(\frac{1}{w(B)} \int_B|f(x)|^r d w(x)\right)^{1 / r}.
\end{align*}
Replacing $f$ in the proof of \cite[Theorem 6.3]{K2019} with $f^r$, we can obtain the following lemma.
\begin{lemma}\label{lem:M-Besi}
Let $(X,\mu,\mathcal{B})$ be a Besicovitch-type ball-basis measure space with the constant $D_0$. Let $1 \leq r<\infty$, then for any weight $w$,  
\begin{align}
&\|M^{\B,w}_{r}\|_{L^r(X, w) \to L^{r, \infty}(X, w)} \le D_0^{1/r}, 
\\
&\|M^{\B,w}_{r}\|_{L^s(X, w) \to L^s(X, w)} \le c_s D_0^{\frac1{sr}}, \quad r<s<\infty. 
\end{align}
\end{lemma}


