\begin{theorem}\label{est:form}
Let $(X,\mu,\mathcal{B})$ be a Besicovitch-type ball-basis measure space. Let $m \in \N$, $\eta \in [0,m)$, $r_1,\cdots,r_m ,s' \in [1,\infty)$, $p_1,\dots,p_m \in (1,\infty)$, and $\frac{1}{{{\tilde{p}}}}:=\sum\limits_{i = 1}^m {\frac{1}{{{p_i}}}}- \eta \in (0,1]$. If $(\vec{r}, s) \prec (\vec{p},\tilde{p})$ and $\vec{\omega} \in A_{(\vec{p},\tilde{p}),(\vec{r}, s)}^\mathcal{B}$, then 
	\begin{align}\label{eq:main-est_}
\sup\limits_{\mathcal{S} \subseteq \B} \left\|\mathcal{A}_{\eta, \mathcal{S}, \vec{r}, s'}\right\|_{\prod\limits_{j=1}^{m} L^{p_j}\left(\omega_j^{p_j}\right) \times L^{{\tilde{p}}'}\left(\omega^{-{\tilde{p}}'}\right) \rightarrow \mathbb{R}}
&\lesssim_{\vec{p},\vec{r},\eta,X} [\vec{\omega}]^{\varTheta}_{A_{(\vec{p},\tilde{p}),(\vec{r}, s)}^\mathcal{B}}.
