Below, we provide examples confirming that our bounds are sharp.

\textbf{Sharpness of \( \varTheta \):}  
Take \( m = 1 \), \( X = \mathbb{R} \), \( \eta = 0 \), \( p_1 = 4 \), \( r_1 = 2 \), \( \tilde{p} = q = 4 \), \( s' = 2 \), \( \tilde{p}' = \frac{4}{3} \). Let \( \mathcal{S} = \{ [0, 2^{-j}) : j \geq 0 \} \), \( b_1(x) = \lambda x \), \( \omega_1 = x^\delta \), \( \omega = x^\delta \) with \( [\vec{\omega}]_{A_{(4,4),(2,4)}} \sim \delta \), and \( f_1(x) = x^{-1/8} \chi_{[0,1]}(x) \).

The operator is that
\[
\mathscr{A}_{0, \mathcal{S}, 2}^{}(f_1)(x) = \sum_{Q \in \mathcal{S}}  \left\langle |f_1| \right\rangle_{2, Q} \chi_Q(x).
\]
For \( Q_j = [0, 2^{-j}) \):
\[
\left\langle |f_1| \right\rangle_{2, Q_j} = \left( 2^j \int_0^{2^{-j}} x^{-1/4} \, dx \right)^{1/2} \sim 2^{-j/4}.
\]
% so each term is \( \lambda \cdot 2^{-5j/4} \). 
The norm
\[
\left\| \mathscr{A}_{0, \mathcal{S}, 2}^{}(f_1) \right\|_{L^4(x^{4\delta})}^4 \sim \sum_{j=0}^\infty \int_{2^{-j-1}}^{2^{-j}} (\lambda \cdot 2^{-j/4})^4 x^{4\delta} \, dx \sim \lambda^4 \delta^{-1}, \quad \left\| \mathscr{A}_{0, \mathcal{S}, 2}^{}(f_1) \right\|_{L^4(x^{4\delta})} \sim \lambda \delta^2.
\]
Since \( \varTheta = \max \left\{ \frac{4}{2}, \frac{4/3}{4/3 - 2} \right\} = 2 \), the bound is \( \lambda \delta^2 \), matching the norm. If \( \varTheta = 2 - \epsilon \), the bound \( \lambda \delta^{2 - \epsilon} \) is dominated by \( \lambda \delta^2 \) as \( \delta \to \infty \), and the inequality fails. Thus, \( \varTheta = 2 \) is sharp.




\subsection{Bloom-type estimates}~~


We introduce several necessary lemmas as follows.
\begin{lemma}\label{pre_1}
   Let  $1 \leq r_i, t \leq \infty$ with $i \in \tau$, and \(\mathbf{b} = (b_1, \ldots, b_{m}) \in (L_{loc}^1(X))^m\). Suppose that $\mathbf{t}$ and $\mathbf{k}$ are both multi-indexs with \(0 \le \mathbf{t} \le \mathbf{k}\), given a dyadic cube $Q$, 
   \begin{align*}
      C_{{\bf k}, {\bf t}}= \prod_{i \in \tau} \laa \left|f_i (b_i - b_{i,Q})^{t_i}\right|\raa_{r_i,Q}  \laaa \prod_{i \in \tau}  \left|b_i - b_{i,Q}\right|^{k_i - t_i}g\raaa_{t,Q}.
   \end{align*}
Then
   \begin{align*}
      C_{{\bf k}, {\bf t}}\leq  \sum_{\tau' \subseteq \tau} \left( \prod_{i_1 \in \tau'} \left\langle \left| b_{i_1} - b_{i_1,Q} \right|^{k_{i_1}} f_{i_1} \right\rangle_{r_{i_1},Q} 
      \left\langle \prod_{i_2 \in \tau \backslash \tau'} \left| b_{i_2} - b_{i_2,Q} \right|^{k_{i_2}} g \right\rangle_{t,Q} 
      \prod_{i_3 \in \tau \backslash \tau'} \left\langle f_{i_3} \right\rangle_{r_{i_3},Q} \right).
   \end{align*}
\end{lemma}
