\begin{proof}[Proof of Lemma \ref{pre_1}]
For $x_i, y \in X$ with $i \in \tau:=({\tau(1),\cdots,\tau(|\tau|)}) \subseteq \{1,\cdots,m\}$, we denote
\begin{align*}
   \varphi(\vec x, y) = \left(\prod_{i \in \tau}\left|f_i(x_i) (b_i(x_i) - b_{i,Q})^{t_i}\right|\right)  \left(\prod_{i \in \tau}  \left|b_i(y) - b_{i,Q}\right|^{k_i - t_i}g(y)\right) \chi_{Q^{|\tau| + 1}}(\vec x,y),
\end{align*}
where $\chi_{Q^{|\tau| + 1}}(\vec x,y)=\chi_{Q}(y)\prod\limits_{i \in \tau}\chi_{Q}(x_i)$. Then it follows that
$$
C_{{\bf k}, {\bf t}} = \big\|\|\varphi(\vec x, y)\|_{L^t_{y}(\frac{d y}{\mu(Q)})}\big\|_{L^{\vec{r}}_{\vec{x}}\Big(\frac{d {\vec x}}{\mu(Q)^{|\tau|}}\Big)},
$$
where the mixed norm is defined by
\begin{align*}
\|\cdot\|_{L^{\vec{r}}_{\vec{x}}\Big(\frac{d {\vec x}}{\mu(Q)^{|\tau|}}\Big)}:&=\|\cdot\|_{L^{\vec{r}}_{\vec{x}}\left(\frac{d x_{\tau(1)}}{\mu(Q)} \cdots \frac{d x_{\tau(|\tau|)}}{\mu(Q)}\right)}\\
   &=\Big\| \cdots \big\|\|\cdot\|_{L^{r_{\tau(1)}}_{x_{\tau(1)}}(\frac{d x_{\tau(1)}}{\mu(Q)})}\big\|_{L^{r_{\tau(2)}}_{x_{\tau(2)}}(\frac{d x_{\tau(2)}}{\mu(Q)})} \cdots \Big\|_{L^{r_{\tau(|\tau|)}}_{x_{\tau(|\tau|)}}(\frac{d x_{\tau(|\tau|)}}{\mu(Q)})}.\\
\end{align*}
Note that 
$\left|b_i(x_i)- b_{i,Q}\right|^{k_i-t_i}\left|b_i(y)- b_{i,Q}\right|^{t_i} \leq\left|b_i(x_i)- b_{i,Q}\right|^{k_i}+\left|b_i(y)- b_{i,Q}\right|^{k_i}$, then we obtain
\begin{align*}
   \varphi(\vec x, y) &\leq \prod_{i \in \tau}\big(\left|b_i(x_i)- b_{i,Q}\right|^{k_i}+\left|b_i(y)- b_{i,Q}\right|^{k_i}\big) \times F(\vec x) g(y)\chi_{Q^{|\tau| + 1}}(\vec x,y)\\
   &= \left(\sum_{\tau' \subseteq \tau} C_{|\tau|}^{|\tau'|} \left(\prod_{i \in \tau'}\left|b_i(x_i)- b_{i,Q}\right|^{k_i}\prod_{j \in \tau \backslash \tau'} \left|b_j(y)- b_{j,Q}\right|^{k_j} \right) \right)F(\vec x) g(y)\chi_{Q^{|\tau| + 1}}(\vec x,y)
\end{align*}
where $F(\vec x)=\prod\limits_{i \in \tau}f_i(x_i)$.

Considering the fact that $\|\chi_{Q}(y)\|_{L^t_y\left(\frac{dy}{\mu(Q)}\right)} = 1$, it follows readily that 
\begin{align*}
   &\quad C_{{\bf k}, {\bf t}}\\
   &\leq  \left\|\Big\|\sum_{\tau' \subseteq \tau} \left(\left(\prod_{i \in \tau'}\left|b_i(x_i)- b_{i,Q}\right|^{k_i}\prod_{j \in \tau \backslash \tau'} \left|b_j(y)- b_{j,Q}\right|^{k_j} \right)F(\vec x) g(y)\chi_{Q^{|\tau| + 1}}(\vec x,y)\right)\Big\|_{L^t_{y}(\frac{d y}{\mu(Q)})}\right\|_{L^{\vec{r}}_{\vec{x}}\Big(\frac{d {\vec x}}{\mu(Q)^{|\tau|}}\Big)}\\
   &\le \sum_{\tau' \subseteq \tau} \left( \prod_{i_1 \in \tau'} \left\langle \left| b_{i_1} - b_{i_1,Q} \right|^{k_{i_1}} f_{i_1} \right\rangle_{r_{i_1},Q} 
   \left\langle \prod_{i_2 \in \tau \backslash \tau'} \left| b_{i_2} - b_{i_2,Q} \right|^{k_{i_2}} g \right\rangle_{t,Q} 
   \prod_{i_3 \in \tau \backslash \tau'} \left\langle f_{i_3} \right\rangle_{r_{i_3},Q} \right).\qedhere
\end{align*}



\end{proof}

