Since $r_i < p_i$, by Hölder's inequality, 
\begin{align*}
	\left([\omega_i^{p_i}]_{A_{p_i/r_i}} \prod_{j=1}^{k_ir_i-1}\left[(\mu_i^{p_i})^{1-\frac{j}{k_ir_i}} (\omega_i^{p_i})^{\frac{j}{k_ir_i}}\right]_{A_{p_i/r_i}}\right) \lesssim \left([\omega_i^{p_i}]^{\frac{k_ir_i+1}{2}}_{A_{p_i/r_i}(X)} \left[\mu_i^{p_i}\right]^{\frac{k_ir_i-1}{2}}_{A_{p_i/r_i}(X)}\right),
\end{align*}
Thus, 
\begin{align}
&\left\|\left[A^{k_ir_i}_{\tilde{\mathcal{S}},\varphi_i}(|f_i|^{r_i})\right]^{\frac{1}{r_i}}\right\|_{L^{p_i}(\mu_i^{p_i})} 
\lesssim \left([\omega_i^{p_i}]^{\frac{k_ir_i+1}{2}}_{A_{p_i/r_i}(X)} \left[\mu_i^{p_i}\right]^{\frac{k_ir_i-1}{2}}_{A_{p_i/r_i}(X)}\right)^{\max \left\{\frac{1}{r_i}, \frac{1}{p_i-r_i}\right\}}\|f_i\|_{L^{p_i}\left(\mu_i^{p_i} {\varphi_i}^{k_i p_i}\right)}.\label{bloom:eq:2}
\end{align}
Analogously, set $\varphi_0 := \left(\omega^{}/\mu_0\right)^{\frac{-1}{(R+1)}}$ and we obtain
\begin{align}
\left\|\left[A^{(R+1)s'}_{\tilde{\mathcal{S}},\varphi_0}(|g|^{s'})\right]^{\frac{1}{s'}}\right\|_{L^{\tilde{p}'}(\mu_0^{-\tilde{p}'})} \lesssim \left([\omega^{-\tilde{p}'}]^{\frac{(R+1)s'+1}{2}}_{A_{\tilde{p}/s'}(X)} 
[\mu_0^{-\tilde{p}'}]^{\frac{(R+1)s'-1}{2}}_{A_{\tilde{p}/s'}(X)}\right)^{\max\left\{ \frac{1}{s'},\frac{1}{\tilde{p}'-s'}\right\} } \|g\|_{L^{\tilde{p}'}(\omega^{-\tilde{p}'})}.\label{bloom:eq:3}
\end{align}

Combining \eqref{bloom:eq:1}, \eqref{bloom:eq:2}, \eqref{bloom:eq:3}, and the fact that 
$$\sum_{\mathcal{J} \subseteq \{1,\cdots,m\}}\prod\limits_{i \in \mathcal{J}} \left([\omega_i^{p_i}]^{\frac{k_ir_i+1}{2}}_{A_{p_i/r_i}(X)} \left[\mu_i^{p_i}\right]^{\frac{k_ir_i-1}{2}}_{A_{p_i/r_i}(X)}\right)^{\max \left\{\frac{1}{r_i}, \frac{1}{p_i-r_i}\right\}} \le \prod\limits_{i=1}^m \left([\omega_i^{p_i}]^{\frac{k_ir_i+1}{2}}_{A_{p_i/r_i}(X)} \left[\mu_i^{p_i}\right]^{\frac{k_ir_i-1}{2}}_{A_{p_i/r_i}(X)}\right)^{\max \left\{\frac{1}{r_i}, \frac{1}{p_i-r_i}\right\}},$$
we have 
\begin{align*}
    &\quad  \left\|{\mathcal A}_{\eta ,\S,\tau,\vec{r},s'}^\mathbf{b,k,t}\right\|_{\prod\limits_{i=1}^{m} L^{p_i}\left(\omega^{p_i}_i\right) \times  L^{\tilde{p}'}(\omega^{-\tilde{p}'}) \rightarrow \mathbb{R}} \lesssim    \prod_{i = 1}^m \|b_i\|_{\mathrm{BMO}_{\varphi_i}(X)}^{k_i}\cdot \mathcal{N}_{0},
    \end{align*}
where $\varpi_i:= \begin{cases}\mu_i, & i \in \mathcal{J};\\ \omega_i, & i \in \mathcal{J}^c,\end{cases}$
 and
  \begin{align*}
    \mathcal{N}_{0}
:=&\left\|\mathcal{A}_{\eta,\S,\vec{r},s'}\right\|_{\prod\limits_{i=1}^{m} L^{p_i}(\varpi^{p_i}_i)\times L^{\tilde{p}'}(\mu_0^{-\tilde{p}'})\rightarrow \mathbb{R}} \cdot \left([\omega^{-\tilde{p}'}]^{\frac{(R+1)s'+1}{2}}_{A_{\tilde{p}/s'}(X)} 
    [\mu_0^{-\tilde{p}'}]^{\frac{(R+1)s'-1}{2}}_{A_{\tilde{p}/s'}(X)}\right)^{\max\left\{ \frac{1}{s'},\frac{1}{\tilde{p}'-s'}\right\} } \\
    &\cdot \prod\limits_{i=1}^m \left([\omega_i^{p_i}]^{\frac{k_ir_i+1}{2}}_{A_{p_i/r_i}(X)} \left[\mu_i^{p_i}\right]^{\frac{k_ir_i-1}{2}}_{A_{p_i/r_i}(X)}\right)^{\max \left\{\frac{1}{r_i}, \frac{1}{p_i-r_i}\right\}}. \qedhere
  \end{align*}
\end{proof}






\subsection{Local decay-type estimates.}~~


The main purpose of this subsection is to prove Theorem~\ref{thm:local}. We first define
\begin{align*}
\widetilde{\mathcal{M}}^{\B}_{\eta, L(\log L)^{\vec r}} (\vec{f}) 
:= \sup_{B \in \B: B \ni x} \mu(B)^{\eta}\prod_{i=1}^m \||f_i|^{r_i}\|_{L(\log L)^{r_i}, B}^{\frac1{r_i}}. 
\end{align*}
We establish the Coifman-Fefferman inequality as follows.
\begin{lemma}\label{lem:Ub}
Under the assumption of Theorem \ref{thm:local}. For any nonnegative functions $f_i \in L_b^{r_i}(X)$ with $\supp f_i \subseteq B_0$, $i=1,\cdots,m$, and for all $p \in (1,\infty)$ , $\omega \in A_{p,\mathcal{B}}$, 
\begin{align}\label{TbM-1} 
\| T_{\vec \eta}(\vec{f}) \|_{L^1(B_0, \omega)}
\lesssim [\omega]_{A_{p, \B}} \| \mathcal{M}^{\B}_{\eta,\vec{r}}(\vec{f}) \|_{L^1(B_0^{3}, \omega)}. 
\end{align}
Suppose that ${\bf t,k }\in \N_0^m$ with \(\mathbf{0} \le \mathbf{t} \leq \mathbf{k}\), and multi-symbol $\mathbf{b}=\left(b_1, \ldots, b_m\right) \in\left(L_{l o c}^1(X)\right)^m$. If $A_{\infty, \B}$ satisfies the sharp reverse H\"{o}lder inequality, then
{\begin{align}\label{TbM-2} 
\|T_{\vec \eta}^{{\bf b, k}} (\vec{f})\|_{L^1(B_0, \omega)}
\lesssim \|\boldsymbol{b}\|^{\bf k} [\omega]_{A_{\infty}}^{\kappa}  
\|\widetilde{\mathcal{M}}^{\B}_{\eta, L(\log L)^{\vec r}}(\vec{f})\|_{L^1(B^3_0, \omega)}
\end{align}}
with $\kappa: = \sum \limits_{i=1}^{m}k_i -t_i$ and $\|\boldsymbol{b}\|^{\bf k} :=\prod\limits_{i =1}^m\|b_i\|_{\rm{BMO}}^{k_i}$,
where the implicit constant is independent of $B_0$, $[\omega]_{A_{p, \B}}$, and $\vec{f}$.
\end{lemma}

Next, we prove Theorem \ref{thm:local} as follows.

\begin{proof}[\bf Proof of Theorem \ref{thm:local}]~~

For $q_0 > 1$ and for any nonnegative function $ h \in L^{q_0}(\mu)$, the Rubio de Francia operator is defined by
\begin{align*}
\mathcal{R}h 
:= \sum_{k=0}^{\infty} \frac{1}{2^k} \frac{M_{\B}^{k}h}{\|M_{\B}\|^k_{L^{q_0}(\mu)\to L^{q_0}(\mu)}}. 
\end{align*}
Then one can check that 
\begin{equation}\label{eq:RdF}
\begin{aligned}
&h \leq \mathcal{R}h, \quad 
\|\mathcal{R}h\|_{L^{q_0}(\mu)} \leq 2 \|h\|_{L^{q_0}(\mu)}, 
\\ 
&\text{and}\quad  
[\mathcal{R}h]_{A_{1, \B}} \leq 2 \|M_{\B}\|_{L^{q_0}(\mu) \to L^{q_0}(\mu)} \leq 2\C_0^{\frac{1}{q_0}}, 
\end{aligned}
\end{equation}
where the last estimates follows from \cite[(2.9)]{Cao23}. For $p,q > 1$ (to be chosen), the Riesz theorem guarantees the existence of that $0 \leq h \in L^{q'}(B, \mu)$ with $\|h\|_{L^{q^{\prime}}(B, \mu)} = 1$ satisfying 
\begin{align}\label{Iqq}
\mathcal{L}(t)^{\frac1q} 
&:= \mu \left(\left\{x \in B:  \left\|T_{\vec \eta}^{{\bf b, k}}(\vec f)(x)\right\|_{\mathbb{V}} > t \, \mathcal{M}^{\B}_{\vec \eta,\vec r}(\vec{f^{\star}})(x)  \right\}\right)^{\frac1q}
\nonumber\\
& \leq \frac{1}{t} \left\| \frac{\left\|T_{\vec{\eta}}^{{\bf b, k}}(\vec f)\right\|_{\mathbb{V}}}{\mathcal{M}^{\B}_{\vec \eta,\vec r}(\vec{f^{\star}})} \right\|_{L^q(B, \mu)}
\overset{\text{(\ref{eq:RdF})}}{\leq} \frac{1}{t} \int_B \left\|T_{\vec{\eta}}^{{\bf b, k}}(\vec f)\right\|_{\mathbb{V}}
\frac{h}{\mathcal{M}^{\B}_{\vec \eta,\vec r}(\vec{f^{\star}})} \, d\mu
\nonumber\\
& \leq \frac{1}{t} \int_B \left\|T_{\vec{\eta}}^{{\bf b, k}}(\vec f)\right\|_{\mathbb{V}}
\frac{\mathcal{R}h}{\mathcal{M}^{\B}_{\vec \eta,\vec r}(\vec{f^{\star}})} \, d\mu
= t^{-1} \left\|\left\| T_{\vec{\eta}}^{{\bf b, k}}(\vec f) \right\|_{\mathbb{V}}\right\|_{L^1(B, \omega)},
\end{align}
where
\[
\omega := \omega_1 \omega_2^{1-p}, \quad 
\omega_1 := \mathcal{R}h, 
\quad\text{and}\quad 
\omega_2 := \mathcal{M}^{\B}_{\vec \eta,\vec r}(\vec{f^{\star}})^{p'-1}.
\] 



To establish $\omega \in A_{\infty}$, from Lemma \ref{lem:CR}, we set $r_0=\max\limits_{i = 1,\cdots,m} r_i$ and pick $p>1+(m - \eta)/r_0$ (equivalently, $\frac{p'-1}{r_0}<\frac1{m - \eta}$), it follows that
\begin{align}\label{eq:MMf}
	[\omega_2]_{A_{1, \B}}
\leq \big[\big(\mathcal{M}^{\B}_{\vec \eta}(|f_1^{\star}|^{r_0}, \ldots, |f_m^{\star}|^{r_0}) \big)^{\frac{p'-1}{r_0}}\big]_{A_{1, \B}},
\end{align}
thus, $[\omega_2]_{A_{1, \B}} \leq C_{m,\eta}$.
Then \eqref{eq:RdF} and \eqref{eq:MMf} imply that $\omega=\omega_1 \omega_2^{1-p} \in A_{p, \B}$ from
\begin{align}\label{wapcc}
[\omega]_{A_{p, \B}} 
\leq [\omega_1]_{A_{1, \B}} [\omega_2]_{A_{1, \B}}^{p-1}
\leq 2 \boldsymbol{C}_0^{\frac{1}{q'}} C_m^{p-1}
\leq 2 \boldsymbol{C}_0 C_m^{p-1}. 
\end{align}

For any ball $B' \in \mathcal{B}$ and locally integrable function $f$, we have the following property
\begin{align}\label{fLL}
\|f_i\|_{L(\log L)^{r_i}, B'} 
\le \|f_i\|_{L(\log L)^{\lfloor r_i \rfloor}, B'} 
\lesssim \fint_{B'} M^{\lfloor r_i \rfloor}(f \mathbf{1}_{B'}) \, d\mu.
\end{align}
Therefore, from \eqref{Iqq}, \eqref{wapcc}, \eqref{fLL}, and Lemma \ref{lem:Ub}, it follows that 
\begin{align*}
\mathcal{L}(t)^{\frac1q} 
& \le c_0 \, t^{-1} \|\boldsymbol{b}\|^{\bf k} [\omega]_{A_{p,\B}}^{\kappa+1}  
\|\widetilde{\mathcal{M}}^{\B}_{\eta, L(\log L)^{\vec r}}(\vec{f})\|_{L^1(B^{(3)}, \omega)} 
\\
& \le c_0 \, t^{-1} \|\boldsymbol{b}\|^{\bf k} [\omega]_{A_{p,\B}}^{\kappa+1} 
\|\mathcal{M}^{\B}_{\vec \eta,\vec r}(\vec{f^{\star}})\|_{L^1(B^{(3)}, \omega)} 
\\ 
& = c_0 \, t^{-1} \|\boldsymbol{b}\|^{\bf k} [\omega]_{A_{p,\B}}^{\kappa+1} \|\mathcal{R}h\|_{L^1(B^{(3)}, \mu)}
\\ 
&\leq c_0 \, t^{-1} \|\boldsymbol{b}\|^{\bf k} [\omega]_{A_{p,\B}}^{\kappa+1}  
\|\mathcal{R}h\|_{L^{q'}(B^{(3)}, \mu)}  \mu(B^{(3)})^{\frac1q}
\\ 
& \le c_0 \, t^{-1} \|\boldsymbol{b}\|^{\bf k} \mu(B)^{\frac1q}
\le c_0 \, t^{-1} \|\boldsymbol{b}\|^{\bf k} q^{\kappa+1}  \mu(B)^{\frac1q}, 
\end{align*}
where $c_0 > 1$ is a constant that may change from line to line but remains independent of $q$.

Consequently, for all $t > t_0 := c_0 e \|\boldsymbol{b}\|^{\mathbf{k}}$, selecting
\[
q = \left(\frac{t}{c_0 e \|\boldsymbol{b}\|^{\mathbf{k}}}\right)^{\frac{1}{\kappa + 1}} > 1
\]
yields the estimate
\begin{align}\label{It-1}
\mathcal{L}(t) &\leq e^{-q} \mu(B) = \exp\left(-\left(\frac{t}{c_0 e \|\boldsymbol{b}\|^{\mathbf{k}}}\right)^{\frac{1}{\kappa + 1}}\right) \mu(B) \nonumber \\
&=: \exp\left(-\left(\frac{\varDelta t}{\|\boldsymbol{b}\|^{\mathbf{k}}}\right)^{\frac{1}{\kappa + 1}}\right) \mu(B),
\end{align}
where $\varDelta := (c_0 e)^{-1}$ depends only on $m$, $p$, and $\mathcal{C}_0$. For $0 < t \leq t_0$, we have
\begin{align}\label{It-2}
\mathcal{L}(t) &\leq e \cdot \exp\left(-\left(\frac{\gamma t}{\|\boldsymbol{b}\|^{\mathbf{k}}}\right)^{\frac{1}{\kappa + 1}}\right) \mu(B).
\end{align}
Combining \eqref{It-1} and \eqref{It-2}, We have that
\[
\mu\left(\left\{x \in B : \|T_{\vec{\eta}}^{\mathbf{b,k}}(\vec{f})(x)\|_{\mathbb{V}} > t \mathcal{M}_{\vec{\eta},\vec{r}}^{\mathcal{B}}(\vec{f}^\star)(x)\right\}\right) \leq e \cdot e^{-\left(\frac{\varDelta t}{\|\boldsymbol{b}\|^{\mathbf{k}}}\right)^{\frac{1}{\kappa + 1}}} \mu(B)
\]
for all $t > 0$.
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem:Ub}]
    We focus on proving \eqref{TbM-2}, since the estimate \eqref{TbM-1} can be implied through \eqref{TbM-2}.
  Fix $B_0 \in \mathcal{B}$ with $\cup_{i=1}^m\supp(f_i) \subseteq B_0$. We claim that there exist a sparse family $\S$ such that for a.e. $x \in B_0$, 
\begin{align}
&\label{Tf-sparse}  \left\|T_{\vec{\eta}}^{{\bf b, k}}(\vec f)(x)\right\|_{\mathbb{V}} 
\lesssim \C \sum_{\mathbf{0} \le \mathbf{t} \leq \mathbf{k}} {\mathscr A}_{\eta ,\S,{\vec r}}^\mathbf{b,k,t}(\vec{f})(x), 
\\ 
\label{BBSS} & \text{and} \quad B \subseteq B_0^{3} \, \text{ for all } \, B \in \S_1 \cup \S_2. 
\end{align}

Since $p \in (1, \infty)$ and $\omega \in A_{p, \B}$. By Lemma \ref{lem:Ainfty}, for any $\alpha \in (0, 1)$, for any $B \in \B$, and for any measurable subset $E \subseteq B$, 
\begin{align}\label{EBAp}
\mu(E) \ge \alpha \mu(B) \quad\Longrightarrow \quad 
\omega(E) \ge \alpha^p \, [\omega]_{A_{p, \B}}^{-1} \omega(B).
\end{align} 
Let $\S$ be an $\delta$-sparse family with $\delta \in (0, 1)$ such that $B \subseteq B_0^{3}$ for all $B \in \S$. Then, there exists a pairwise disjoint family $\{E_B\}_{B \in \S}$ such that $E_B \subseteq B$ and $\mu(E_B) \ge \delta \mu(B)$ for all $B \in \S$.

It follows from this and \eqref{EBAp} that
\begin{equation}\label{0608_1}
\omega(B) \le \delta^{-p} [\omega]_{A_{p, \B}} \omega(E_B) \quad\text{ for all } B \in \S, 
\end{equation}


Set $\kappa: = \sum \limits_{i=1}^{m}k_i -t_i$ and $\|\boldsymbol{b}\|^{\bf k} :=\prod\limits_{i =1}^m\|b_i\|_{\rm{BMO}}^{k_i}$. From Lemma \ref{lem:PhiPhi}, \eqref{e:fw}, and \eqref{0608_1}, 
\begin{align}
&\quad \left\|{\mathscr A}_{\eta ,\S,{\vec r}}^\mathbf{b,k}(\vec f)\right\|_{L^1(B_0, \omega)}\notag \\
 &\le \sum_{B \in \S} \mu(B)^{\eta + 1} \left(\fint_B \prod_{i=1}^m |b_i - b_{i,B}|^{k_i - t_i} \omega  d \mu \right) \prod_{i =1}^m \left\langle (b_i - b_{i, B})^{t_i} f_i \right\rangle_{r_i, B} 
\nonumber \\
&\lesssim \sum_{B \in \S} \mu(B)^{\eta + 1} \|\omega\|_{L(\log L)^{\kappa}, B} \prod_{i=1}^{m}\left( \|(b_i - b_{i, B})^{k_i - t_i}\|^{\frac{1}{k_i - t_i}}_{\exp L^{\frac{1}{k_i - t_i}}, B}\right)^{k_i - t_i} \nonumber\\
&\quad\quad \quad \times\left( \|(b_i - b_{i, B})^{ t_i}\|^{\frac{1}{ t_i}}_{\exp L^{\frac{1}{ t_i}}, B}\right)^{ t_i} \||f_i|^{r_i}\|_{L(\log L)^{r_i}, B}^{\frac1r}
\nonumber \\
&=\sum_{B \in \S} \mu(B)^{\eta + 1} \|\omega\|_{L(\log L)^{\kappa}, B} \prod_{i=1}^{m} \|b_i - b_{i, B}\|^{k_i - t_i}_{\exp L, B} 
\|b_i\|^{t_i}_{\rm BMO} \langle f_i \rangle_{r_i,B}
\nonumber \\
&\lesssim \|\boldsymbol{b}\|^{\bf k} [\omega]_{A_{\infty}}^{\kappa} 
\sum_{B \in \S} \mu(B)^{\eta}  
 \||f_i|^{r_i}\|_{L(\log L)^{r_i}, B}^{\frac1{r_i}} \, \omega(B)
\nonumber \\
&\lesssim \|\boldsymbol{b}\|^{\bf k} [\omega]_{A_{p,\B}}^{\kappa+1}  
\sum_{B \in \S} \inf_{x \in B} \widetilde{\mathcal{M}}^{\B}_{\eta, L(\log L)^{\vec r}}(\vec{f})(x)  \, \omega(E_B)
\nonumber \\
&\le \|\boldsymbol{b}\|^{\bf k} [\omega]_{A_{p,\B}}^{\kappa+1}  
\sum_{B \in \S} \int_{E_B} \widetilde{\mathcal{M}}^{\B}_{\eta, L(\log L)^{\vec r}}(\vec{f})  \, \omega \, d\mu
\nonumber \\ 
&\le \|\boldsymbol{b}\|^{\bf k} [\omega]_{A_{p,\B}}^{\kappa+1}  
\|\widetilde{\mathcal{M}}^{\B}_{\eta, L(\log L)^{\vec r}}(\vec{f})\|_{L^1(B^3_0, \omega)}, \label{eq:ASB}
\end{align}
