\begin{lemma}\label{lem:CR}
Let $(X,\mu,\mathcal{B})$ be a ball-basis measure space. Let $m \in \mathbb{N}_0$, $\eta_i \in [0,1)$  for $i=1,\cdots,m$, and the fractional total order $\eta {\rm{ = }}\sum\limits_{i = 1}^m {{\eta _i}} \in [0,m)$. If $0<\delta<\frac{1}{m - \eta}$, then 
	\begin{align}\label{eq:CR}
	\left[(\mathcal{M}^{\B}_{\vec \eta}(\vec{f}))^{\delta}\right]_{A_{1,\B}} 
	\leq \frac{c_m}{1-(m - \eta)\delta}.
	\end{align}
	\end{lemma}
\begin{proof}
Our proof is inspired by \cite[Theorem 3.4]{GR} and \cite[Lemma~1]{OPR} and only presents the details.
For any fixed $B \in \mathcal{B}$ and $x \in B$, we split $\vec{f}=(f_1, \ldots, f_m)$ by $f_i^0 := f_i \chi_{B^{\dagger}}$ and $f_i^{\infty} := f_i \chi_{X \setminus B^{\dagger}}$ for $i=1, \ldots, m$, it follows that 
\begin{align}\label{eq:CR-1}
\fint_B \mathcal{M}_{\vec \eta}^{\B}(\vec{f})^{\delta} d\mu 
&\le \underbrace{\sum_{\alpha_1, \ldots, \alpha_m \in \{0, \infty\} \atop \exists \alpha_i = \infty} 
\fint_B \mathcal{M}^{\B}_{\vec \eta}(f_1^{\alpha_1}, \ldots, f_m^{\alpha_m})^{\delta} d\mu}_{\mathbb{M}_1} + \underbrace{\fint_B \mathcal{M}^{\B}_{\vec \eta}(\vec{f}^0)^{\delta} d\mu}_{\mathbb{M}_2}. 
\end{align}



For $\mathbb{M}_1$, let $\alpha_1, \ldots, \alpha_m \in \{0, \infty\}$ with $\alpha_i = \infty$ for some $i$.  Let $A \in \B$ and $y \in A \cap B$, then we have the following  implications
\begin{align}\label{AFB}
\int_A |f_i^{\infty}| \, d\mu \neq 0 
\quad\Longrightarrow\quad 
\mu(A) > 2\mu(B) 
\quad\Longrightarrow\quad 
x \in B \subseteq A^{\dagger}.
\end{align}
When $\mu(A) \leq 2\mu(B)$, property \eqref{list:B4} yields $A \subseteq B^{\dagger}$, and thus
\[
\int_A |f_i^\infty| \, d\mu = \int_{A \setminus B^\dagger} |f_i| \, d\mu = 0.
\]
The second implication in \eqref{AFB} is immediate from \eqref{list:B4} and $A \cap B \neq \emptyset$. From \eqref{list:B4}, we deduce that
\begin{align*}
\prod_{i=1}^m \langle |f_i^{\alpha_i}| \rangle_{\eta_i,A} 
&\leq \prod_{i=1}^{m} \left(\frac{\mu(A^{\dagger})}{\mu(A)}\right)^{1-\eta_i} \langle |f_i^{\alpha_i}| \rangle_{\eta_i,A^{\dagger}} \\
&= \left(\frac{\mu(A^{\dagger})}{\mu(A)}\right)^{m-\eta} \prod_{i=1}^{m}\langle |f_i^{\alpha_i}| \rangle_{\eta_i,A^{\dagger}} \\
&\leq \C_0^{m - \eta} \mathcal{M}^{\B}_{\vec{\eta}}\left(f_1^{\alpha_1}, \ldots, f_m^{\alpha_m}\right)(x),
\end{align*}
which yields the estimate
\begin{align}\label{eq:CR-3}
\mathcal{M}^{\B}_{\vec{\eta}}(f_1^{\alpha_1}, \ldots, f_m^{\alpha_m})(y)
\leq \C_0^{m - \eta} \mathcal{M}^{\B}_{\vec{\eta}}(\vec{f})(x), \quad \forall x, y \in B.
\end{align}

For $\mathbb{M}_2$, we set $K_0 := \prod_{i=1}^m \langle |f_i| \rangle_{\eta_i,B^{\dagger}}
\le \mathcal{M}^{\B}_{\vec \eta}(\vec{f})(x),$
and it follows from Proposition \ref{lem:M} that 
\begin{align}\label{eq:CR-2}
\fint_B \mathcal{M}^{\B}_{\vec \eta}(\vec{f}^0)^{\delta} d\mu 
&=\frac{\delta}{\mu(B)} \int_0^{\infty} \lambda^{\delta} 
\mu\left(\{x \in B: \mathcal{M}^{\B}_{\vec \eta}(\vec{f}^0)(x)^{\delta}>\lambda\}\right) \frac{d\lambda}{\lambda}
\nonumber\\ 
&\le K_0^{\delta} + \frac{\delta}{\mu(B)} \int_{K_0}^{\infty} \lambda^{\delta} 
\mu(\{x \in X: \mathcal{M}^{\B}_{\eta}(\vec{f}^0)(x)^{\delta}>\lambda\}) \frac{d\lambda}{\lambda}
\nonumber\\ 
&\le K_0^{\delta} + \frac{c \, \delta}{\mu(B^{\dagger})} \int_{K_0}^{\infty} \lambda^{\delta-\frac{1}{m - \eta}} 
\prod_{i=1}^m \|f_i^0\|_{L^1(X, \mu)}^{\frac{1}{m - \eta}} \frac{d\lambda}{\lambda}
\nonumber\\ 
&= K_0^{\delta} \left[1 + \frac{c \, \delta^2}{1-(m - \eta)\delta} \left(K_0^{-1} 
\prod_{i=1}^m \langle |f_i| \rangle_{\eta_i,B^{\dagger}} \right)^{\frac{1}{m - \eta}} \right]
\nonumber\\ 
&\le \frac{c}{1-(m - \eta)\delta} \mathcal{M}^{\B}_{\vec \eta}(\vec{f})(x)^{\delta},
\end{align}
where $c>0$ varies from line to line and is independent of $B$.

Combining estimates \eqref{eq:CR-1}, \eqref{eq:CR-2}, and \eqref{eq:CR-3}, we conclude that
\begin{align*}
\fint_B \mathcal{M}^{\B}_{\vec{\eta}}(\vec{f})^{\delta} d\mu 
\leq \frac{c}{1-m\delta} \mathcal{M}^{\B}_{\vec{\eta}}(\vec{f})(x)^{\delta}, \quad \forall x \in B.
\end{align*}
This establishes \eqref{eq:CR}. 
\end{proof}
