\subsection{Mixed weak-type estimates}


\begin{lemma}\label{lem:TM} 
Under the assumption of Theorem \ref{thm:weak}, for any $p \in (0, \infty)$ and $\omega \in A_{\infty, \B}$, 
\begin{align}\label{eq:C-F}
\|{T}_{\vec \eta}(\vec{f})\|_{L^p(X, \omega)} 
\lesssim \|\mathcal{M}^{\B}_{\vec \eta, \vec r}(\vec{f})\|_{L^p(X, \omega)}.
\end{align}
\end{lemma}

\begin{proof}
We use the $A_\infty$ extrapolation theorem to prove our desired result. For a family $\mathcal{F}$ of function pairs, if there exists $p_0\in(0,\infty)$ such that for every $\omega_0\in A_{\infty,\mathcal{B}}$,
\begin{align}\label{eq:fg-some}
\|f\|_{L^{p_0}(X,\omega_0)} \leq C_1\|g\|_{L^{p_0}(X,\omega_0)}, \quad \forall(f,g)\in\mathcal{F},
\end{align}
then for all $p\in(0,\infty)$ and $\omega\in A_{\infty,\mathcal{B}}$,
\begin{align}\label{eq:fg-every}
\|f\|_{L^p(X,\omega)} \leq C_2\|g\|_{L^p(X,\omega)}, \quad \forall(f,g)\in\mathcal{F}.
\end{align}
This result follows from \cite[Theorem 3.34]{Martell2022} on $A_{\infty,\mathcal{B}}$ extrapolation in Banach function spaces, where the hypothesis is verified by estimate \cite[(2.9)]{Cao23}. 

Since $\omega \in A_{\infty, \B}$ and Lemma \ref{lem:Ainfty}, for any $\alpha \in (0, 1)$, it follows that there exists $\beta \in (0, 1)$ such that for any $B \in \B$ and any measurable subset $E \subseteq B$, 
\begin{align}\label{EBB}
\mu(E) \ge \alpha \mu(B) \quad\Longrightarrow \quad 
\omega(E) \ge \beta \omega(B).
\end{align} 
Combining this with \eqref{EBB}, we obtain that $\omega(B) \lesssim \omega(E_B) $ holds for all $B \in \mathcal{S}$. Then
\begin{align}\label{eq:ASp=1}
\left\|\mathscr{A}_{\vec \eta, \S, \vec r}(\vec{f})\right\|_{L^1(X, \omega)}
& \leq \sum_{B \in \S} \prod_{i=1}^m \langle f_i \rangle_{\eta_i,r_i,B} \omega(B)
\lesssim \sum_{B \in \S} \Big(\inf_{B} \mathcal{M}^{\B}_{\vec \eta, \vec r}(\vec{f}) \Big) \omega(E_B)
\nonumber \\ 
& \leq \sum_{B \in \S} \int_{E_B} \mathcal{M}^{\B}_{\vec \eta, \vec r}(\vec{f}) \, \omega \, d\mu
\leq \left\|\mathcal{M}^{\B}_{\vec \eta, \vec r}(\vec{f})\right\|_{L^1(X, \omega)}, 
\end{align} 
where the implicit constants are independent of $\S$. As a consequence, Theorem \ref{S.d.main} and \eqref{eq:ASp=1} imply 
\begin{align}\label{eq:TMp=1}
\|{T}_{\vec \eta}(\vec{f})\|_{L^1(X, \omega)}
\lesssim \|\mathcal{M}^{\B}_{\vec \eta, \vec r}(\vec{f})\|_{L^1(X, \omega)}. 
\end{align}
This establishes \eqref{eq:C-F} for the case $p=1$. 

For the general case $p \in (0, \infty)$, we observe that \eqref{eq:TMp=1} establishes \eqref{eq:fg-some} with $p_0 = 1$ for the pair $(f, g) = (T_{\vec{\eta}}(\vec{f}), \mathcal{M}^{\mathcal{B}}_{\vec{\eta}, \vec{r}}(\vec{f}))$. The desired estimate \eqref{eq:C-F} follows immediately from \eqref{eq:fg-every}.
\end{proof}

\begin{proof}[\bf Proof of Theorem \ref{thm:weak}]~


Our approach combines the techniques from \cite{CMP} and \cite{LOP}. Define the Rubio de Francia iteration operator
\[
\mathcal{R}h := \sum_{j=0}^{\infty} \frac{S^j h}{(2K)^j}, \quad \text{where } Sf := \frac{M_{\mathcal{B}}(f \omega)}{\omega},
\]
with $K > 0$ to be chosen specified later. This construction immediately yields the key properties
\begin{align}\label{e:R-3}
h \leq \mathcal{R}h \quad \text{and} \quad S(\mathcal{R}h) \leq 2K \mathcal{R}h.
\end{align}

We claim that there exists some $l > 1$ such that:
\begin{list}{\rm (\theenumi)}{\usecounter{enumi}\leftmargin=1.2cm \labelwidth=1cm \itemsep=0.2cm \topsep=.2cm \renewcommand{\theenumi}{\alph{enumi}}}
\item \label{RhAi}
$\mathcal{R}h \cdot \omega v^{\frac{\tilde{r}}{l}} \in A_{\infty,\mathcal{B}}$;
    \item \label{e:R-2}  $\|\mathcal{R}h\|_{L^{s',1}(X, \omega v^{\tilde{r}})} \leq 2\|h\|_{L^{s',1}(X, \omega v^{\tilde{r}})}$.
\end{list}

%From the fact that $\|f^q\|_{L^{p,\infty}(X, \sigma)}= \|f\|^q_{L^{pq,\infty}(X, \sigma)}$, where $\sigma$ is a weight.

Observing that for any weight $\sigma$ on $(X, \mu)$ and $0<p,q<\infty$, it follows that
\begin{align}\notag
&\quad \bigg\| \frac{\|T_{\vec \eta}(\vec{f})\|_{\mathbb{V}}}{v}
\bigg\|_{L^{\tilde{r},\infty}(X, \omega v^{\tilde{r}})}^{\frac{\tilde{r}}{l}}
= \bigg\| \bigg|\frac{\|T_{\vec \eta}(\vec{f})\|_{\mathbb{V}}}{v}\bigg|^{\frac{\tilde{r}}{l}} \bigg\|_{L^{l,\infty}(X, \omega v^{\tilde{r}})}\\ \label{Tff-1}
&=\sup_{0 \le h \in L^{l',1}(X, \omega v^{\tilde{r}}) \atop \|h\|_{L^{l',1}(X, \omega v^{\tilde{r}})}=1}
\bigg|\int_{X} \left\|T_{\vec \eta}(\vec{f})\right\|_{\mathbb{V}}^{\frac{\tilde{r}}{l}} h \, \omega \, v^{\frac{\tilde{r}}{l'}} d\mu  \bigg|
\leq \sup_{0 \le h \in L^{l',1}(\omega v^{\tilde{r}}) \atop \|h\|_{L^{l',1}(X, \omega v^{\tilde{r}})}=1} 
\int_{X} \left\|T_{\vec \eta}(\vec{f})\right\|_{\mathbb{V}}^{\frac{\tilde{r}}{l}} \mathcal{R}h \, \omega \, v^{\frac{\tilde{r}}{l'}} d\mu.
\end{align}
Fix a nonnegative function $h \in L^{l',1}(X, \omega v^{\tilde{r}})$ with $\|h\|_{L^{l',1}(X, \omega v^{\tilde{r}})} = 1$. Combining \eqref{RhAi}, Lemma~\ref{lem:TM}, and Hölder's inequality yields
\begin{align}\label{Tff-2}
&\quad \int_{X} \left\|T_{\vec \eta}(\vec{f})\right\|_{\mathbb{V}}^{\frac{\tilde{r}}{l}} \mathcal{R}h \, \omega \, v^{\frac{\tilde{r}}{l'}} d\mu
\nonumber \\ 
& \lesssim \int_{X} \mathcal{M}^{\B}_{\vec \eta,\vec r}(\vec{f})^{\frac{\tilde{r}}{l}} \mathcal{R}h \, \omega v^{\frac{\tilde{r}}{l'}} d\mu
 = \int_{X} \bigg(\frac{\mathcal{M}^{\B}_{\vec \eta,\vec r}(\vec{f})}{v}\bigg)^{\frac{\tilde{r}}{l}}
\mathcal{R}h \, \omega v^{\tilde{r}} d\mu
\nonumber \\ 
& \leq \bigg\|\bigg(\frac{\mathcal{M}^{\B}_{\vec \eta,\vec r}(\vec{f})}{v}\bigg)^{\frac{\tilde{r}}{l}} \bigg\|_{L^{s,\infty}(X, \omega v^{\tilde{r}})}
\|\mathcal{R}h\|_{L^{l',1}(X, \omega v^{\tilde{r}})}
\nonumber \\ 
& \lesssim \bigg\|\frac{\mathcal{M}^{\B}_{\vec \eta,\vec r}(\vec{f})}{v}\bigg\|_{L^{\tilde{r},\infty} (X, \omega v^{\tilde{r}})}^{\frac{\tilde{r}}{l}}
\|h\|_{L^{l',1}(X, \omega v^{\tilde{r}})},
\end{align}
where \eqref{e:R-2} was used in the last inequality. Consequently, it follows from \eqref{Tff-1} and \eqref{Tff-2} that 
\begin{equation*}
\bigg\|\frac{{T}_{\vec \eta}(\vec{f})}{v}\bigg\|_{L^{\tilde{r},\infty}(X, \, \omega v^{\tilde{r}})}
\lesssim \bigg\| \frac{\mathcal{M}^{\B}_{\vec \eta, \vec r}(\vec{f})}{v}\bigg\|_{L^{\tilde{r},\infty}(X, \, \omega v^{\tilde{r}})}.
\end{equation*}

It remains to show \eqref{RhAi} and \eqref{e:R-2}. The proof follows the strategy in \cite{CMP}. For the sake of completeness we present the details. 
Since $\omega \in A_{1, \B}$ and $v^{\tilde{r}} \in A_{\infty, \B}$, we have 
\begin{equation}\label{e:S-1}
\begin{aligned}
&\|Sf\|_{L^{\infty}(X, \omega v^{\tilde{r}})}
\leq [\omega]_{A_{1, \B}} \|f\|_{L^{\infty}(X, \omega v^{\tilde{r}})} 
\\
&\text{and}\quad v^{\tilde{r}} \in A_{q_0, \B} \text{ for some } q_0>1. 
\end{aligned}
\end{equation}
It follows from Lemma \ref{lem:A1} part \eqref{list:A11} that there exist $v_1, v_2 \in A_{1, \B}$ such that 
\begin{align}\label{vvv}
v^{\tilde{r}}=v_1 v_2^{1-q_0}.
\end{align} 

Note that the second inequality in \eqref{e:R-3} implies $\mathcal{R}h \cdot \omega \in A_{1,\mathcal{B}}$. Since $\omega \in A_{1,\mathcal{B}}$ by assumption, Lemma~\ref{lem:A1} part \eqref{list:A12} yields the existence of $\varepsilon_0 \in (0,1)$ such that
\begin{align}\label{Rww}
\text{$(\mathcal{R}h \cdot \omega) v_1^{\varepsilon} \in A_{1, \B}$ \, and \, 
$w v_2^{\varepsilon} \in A_{1, \B}$ \, for any $\varepsilon \in (0, \varepsilon_0)$.}
\end{align} 
Let \( p_0 > 1 + \frac{q_0 - 1}{\varepsilon_0} \) and choose \( \varepsilon \) satisfying \( 0 < \varepsilon < \min\left\{\varepsilon_0, \frac{1}{2p_0}\right\} \). Define \( l = \left(\frac{1}{\varepsilon}\right)' > 1 \). Using \eqref{Rww} and part \eqref{list:A11} of Lemma \ref{lem:A1}, we obtain \( \omega v_2^{\frac{q_0 - 1}{p_0 - 1}} \in A_{1, \mathcal{B}} \), and
\begin{align}\label{wv22}
\mathcal{R}h \cdot \omega v^{\tilde{r}} = \left[(\mathcal{R}h \cdot \omega) v_1^\varepsilon\right] v_2^{1 - (q_0 - 1)\varepsilon - 1} \in A_{(q_0 - 1)\varepsilon + 1, \mathcal{B}}.
\end{align}
This  \eqref{RhAi}. Furthermore, combining \eqref{vvv} with \eqref{wv22}, part \eqref{list:A11} of Lemma \ref{lem:A1} yields
\begin{align}\label{wpv}
\omega^{1 - p_0} v^{\tilde{r}} = v_1 \left(\omega v_2^{\frac{q_0 - 1}{p_0 - 1}}\right)^{1 - p_0} \in A_{p_0, \mathcal{B}}.
\end{align}


From  \eqref{wpv} and Proposition \ref{lem:M_0}, it can be deduced that
\begin{align}\label{e:S-2}
\|Sf\|_{L^{p_0}(X, \omega v^{\tilde{r}})} 
= \|M_{\mathcal{B}}(f w)\|_{L^{p_0}(X, \omega^{1-p_0} v^{\tilde{r}})} 
\leq c_1 \|f\|_{L^{p_0}(X, \omega v^{\tilde{r}})}.
\end{align}  
Next, applying the Marcinkiewicz interpolation theorem from \cite[Proposition A.1]{CMP}---valid in general measure spaces---along with \eqref{e:S-1} and \eqref{e:S-2}, we conclude that \( S \) is bounded on \( L^{p,1}(X, \omega v^{\tilde{r}}) \) for all \( p \geq p_0 \), with  
\begin{align*}
K(p) = 2^{\frac{1}{p}} \bigg[ c_1 \bigg( \frac{1}{p_0} - \frac{1}{p} \bigg)^{-1} + c_2 \bigg], \quad \text{where } c_2 := [\omega]_{A_{1, \mathcal{B}}}.
\end{align*}  
Since \( K(p) \) is decreasing in \( p \), it follows that for \( p \geq 2p_0 \),  
\begin{equation}\label{eq:Lp1}
\|Sf\|_{L^{p,1}(X, \omega v^{\tilde{r}})} \leq K \|f\|_{L^{p,1}(X, \omega v^{\tilde{r}})}, \quad K := 4p_0(c_1 + c_2).
\end{equation}  
Finally, since \( l' > 2p_0 \), applying \eqref{eq:Lp1} yields \eqref{e:R-2}. This completes the proof.
\end{proof}















