\subsection{Young functions and Orlicz spaces}~~


Let $(X,\mu,\mathcal{B})$ is a ball-basis measure space. A function $\Phi : [0, \infty) \rightarrow [0, \infty)$ is said to be a Young function, if $\Phi$ is continuous, convex, increasing function such that $\Phi(0)=0$ and $\Phi(t)/t \rightarrow \infty$ as $t \rightarrow \infty$.

Let $\Phi$ is a Young function and $B \in \B$, we define the normalized Luxemburg norm of $f$ on $B$ by 
\begin{equation*}
\|f\|_{\Phi, B}
= \inf \bigg\{\lambda>0; \fint_B \Phi \Big(\frac{|f(x)|}{\lambda}\Big) d\mu \leq 1 \bigg\}.
\end{equation*}
There are three useful examples. 
\begin{itemize}

\item $\Phi(t)=t^p$, $p>1$, then $\|f\|_{L^p, B} := \|f\|_{\Phi, B}$.

\item $\Phi(t)=t \log^r(e+t)$, $r>0$, then $\|f\|_{L(\log L)^r, B} := \|f\|_{\Phi, B}$. 

\item $\Phi(t)=e^{t^r}-1$, $r>0$, then $\|f\|_{\exp L^r, B} := \|f\|_{\Phi, B}$. 
\end{itemize}


%%%%%%%%%%%%%%%%%%%%%%%% LEMMA LEMMA LEMMA %%%%%%%%%%%%%%%%%%%%%%%%
\begin{lemma}[\cite{PRiv}]\label{lem:PhiPhi}
If $\Phi_0, \Phi_1, \ldots, \Phi_k$ are Young functions satisfying 
\[
\Phi_1^{-1}(t) \cdots \Phi_k^{-1}(t) \lesssim \Phi_0^{-1}(t) \quad\text{ for all } t>0, 
\] 
then for any $B \in \B$, 
\begin{equation*}
\|f_1 \cdots f_k\|_{\Phi_0, B} 
\lesssim \|f_1\|_{\Phi_1, B} \cdots \|f_k\|_{\Phi_k, B} .
\end{equation*}
In particular, for any $B \in \B$ and $\frac1s = \sum_{i=1}^k \frac{1}{s_i}$ with $s_1, \ldots, s_k \geq 1$, 
\begin{align*}
\fint_B |f_1 \ldots f_k g| \, d\mu
& \lesssim \| f_1 \|_{\exp L^{s_1}, B} \cdots \| f_k \|_{\exp L^{s_k}, B} \|g\|_{L(\log L)^{\frac{1}{s}}, B}. 
\end{align*}
\end{lemma}
