Set $X = \Rn$, $d\mu=dx$, and $\B$ as the collection of all cubes in $\Rn$, then $A_{\infty, \B}$ satisfies the sharp reverse H\"{o}lder property.


\begin{lemma}\label{lem:LlogL}
Assume that $A_{\infty, \B}$ satisfies the sharp reverse H\"{o}lder property. Let $s>1$, $t>0$, and $w \in A_{\infty, \B}$. Then for any $B \in \B$, 
\begin{align}
\label{e:w} &\| w^{\frac1s} \|_{L^s(\log L)^{st}, B}
\lesssim  [w]_{A_{\infty, \B}}^t \langle w \rangle_B^{\frac1s},
\\
\label{e:fw} &\| f w \|_{L(\log L)^t, B}
\lesssim  [w]_{A_{\infty, \B}}^t \langle w \rangle_B \inf_{x \in B} M_{w}(|f|^s)(x)^{\frac1s}. 
\end{align}
\end{lemma} 
\begin{proof}

Since $w \in A_{\infty, \B}$, based on our assumption, there exists $r_w \approx 1 + [w]_{A_{\infty, \B}}^{-1}$ such that $w \in RH_{r_w, \B}$. It follows from above that
\begin{align*}
&\|w^{\frac1s} \|_{L^s(\log L)^{st}, B}^s
\lesssim \|w\|_{L(\log L)^{st}, B}
\\ 
&\quad \lesssim \bigg(1 + \frac{1}{(r_w - 1)^{st}} \bigg)
\bigg( \fint_B w^{r_w} dx  \bigg)^{\frac{1}{r_w}}
\lesssim  [w]_{A_{\infty}}^{st} \langle w \rangle_B.
\end{align*}
To proceed, using Lemma \ref{lem:PhiPhi} and \eqref{e:w}, we obtain
\begin{align*}
\|fw\|_{L(\log L)^{t}, B}
&\lesssim \bigg( \fint_B |f|^s w \, d\mu \bigg)^{\frac1s}
\|w^{\frac{1}{s'}} \|_{L^{s'}(\log L)^{s't}, B}
\\ 
&\lesssim  [w]_{A_{\infty}}^t
\bigg( \frac{1}{w(B)} \int_B |f|^s w \, d\mu \bigg)^{\frac1s} \langle w \rangle_B
\\
&\lesssim  [w]_{A_{\infty}}^t \inf_{x \in B}
M_{\B, w}(|f|^s)^{\frac1s} \langle w \rangle_B. \quad \qedhere
\end{align*} 
\end{proof}


