	\section{Preliminaries}\label{Sec II}
	Throughout this paper, let $\mathbb{F}_q=\{0,1,\alpha,\ldots,\alpha^{q-2}\}$ denote the finite field with $q$ elements, and let $\mathbb{F}_q^*=\mathbb{F}_q\setminus \{0\}$.
	For $\alpha\in \mathbb{F}_q$, we use $\bm{\alpha}_{m\times n}$ (resp. $\bm{\alpha}_n$) to denote an $m\times n$ matrix with each entry being $\alpha$ (resp. vector of length $n$). If the sizes of matrices (or vectors) are clear, we will omit the subscript.
	Let $[n]$ denote the set $\{1,2,\ldots,n \}$.  
    For $m<n$, let $[m,n]$ denote the set $\{m+1,\ldots,n \}$.


	\subsection{Basics of linear codes}

	An $[n,k]_q$ linear code $C$ is a $k$-dimensional subspace of $\mathbb{F}_q^n$.
	For a vector $\mathbf{u}=(u_1,u_2,\ldots,u_{n})$ of $\mathbb{F}_q^n$, we respectively define $\text{Supp}(\mathbf{u})=\{i\mid  u_i\ne \mathbf{0} \}$ and $wt(\mathbf{u})=| \text{Supp}(\mathbf{u})|$ as its support and Hamming weight.
	The support of $C$ is $\text{Supp}(C)=\bigcup _{c \in C} \text{Supp}(\mathbf{c})$. Let $n(C)=|\text{Supp}(C)|$ be the \textit{effective length} of $C$.
	The minimum Hamming weight and error coefficient of $C$ are $d(C)=\min\{wt(\mathbf{c})\mid \mathbf{c}\in C \}$ and $e(C)=|\{ \mathbf{c}\mid  wt(\mathbf{c})=d(C),  \mathbf{c}\in C\}|$, respectively.
	If $C$ is an $[n,k]_q$ linear code of minimum Hamming weight $d$ and error coefficient $e$, then we denote the parameters of $C$ by $[n,k,d;e]_q$.




	Let $A_i(C)=|\{ \mathbf{c}\mid  wt(\mathbf{c})=i,  \mathbf{c}\in C\}|$, where $0\le i \le n$.
	For $1\le i\le n$, $(q-1)\mid A_i(C)$ or $A_i(C)=0$.
	The polynomial $\sum_{i=0}^n A_{i}(C)x^i$ is the weight enumerator of $C$.
	For a set of $\mathbb{F}_q$-linearly independent vectors $\mathbf{c}_1$, $\mathbf{c}_2$, $\ldots$, $\mathbf{c}_k$ in $\mathbb{F}_q^n$, let $\left \langle \mathbf{c}_1,\mathbf{c}_2,\ldots,\mathbf{c}_k \right \rangle$ denote the vector space generated by $\mathbf{c}_1,\mathbf{c}_2,\ldots,\mathbf{c}_k$.
	If $C=\left \langle \mathbf{c}_1,\mathbf{c}_2,\ldots,\mathbf{c}_{k^{\prime}} \right \rangle$, where $k^{\prime}<k$, then we denote $\left \langle C,\mathbf{c}_{k^{\prime}+1},\ldots,\mathbf{c}_k \right \rangle=\left \langle \mathbf{c}_1,\mathbf{c}_2,\ldots,\mathbf{c}_{k} \right \rangle$. 
    For $t$ linear codes $C_1$, $C_2$, $\ldots$, and $C_t$ of the same dimension, we denote by $C_1\times C_2\times\cdots\times C_t$ their juxtaposition code. 
	The extended code of an $[n,k]_q$ linear code $C$ is
	\begin{equation}
		\widehat{C} =\left\{\left(c_0,c_1,\ldots,c_{n-1},\sum_{i=0}^{n-1}c_i \right)\mid \left(c_0,c_1,\ldots,c_{n-1} \right)\in C \right \}.
	\end{equation}

	\begin{lemma}(\cite{huffman2010fundamentals}, p. 15) \label{Lem_binary-odd-even}
		If $C$ is an $[n,k,d]_2$ linear code with $2\nmid d$, then the extended code of $C$ is an $[n+1,k,d+1]_2$ linear code.
	\end{lemma}








	\subsection{Bounds on linear codes}



	The Griesmer bound is crucial for determining the optimality of linear codes.

	\begin{theorem}
		(Griesmer Bound, \cite{griesmer1960bound})  \label{Griesmer_Bound}
		If $\mathcal{C}$ is an $[n,k,d]_{q}$ linear code, then
		\begin{equation} 
			n \geq g_q(k, d) :\triangleq \sum\limits_{i=0}^{k-1}\left\lceil  \frac{d}{q^{i}}\right\rceil.
		\end{equation}
	\end{theorem}

	The linear code reaching this bound with equality is called a \textit{Griesmer code}.

	\begin{theorem}
		(Modified Griesmer Bound, \cite{mceliece1991modifications})  \label{Modifications_Griesmer_Bound}
		If $\mathcal{C}$ is an $[n,k\ge 2,d]_{q}$ linear code with maximum weight $m$, then,
		\begin{equation} 
			n \geq \mathsf{g}_q(k, d,m) :\triangleq \sum\limits_{i=0}^{k-2}\left\lceil  \frac{d}{q^{i}}\right\rceil+\left\lceil  \frac{m}{q^{k-1}}\right\rceil.
		\end{equation}
	\end{theorem}



