	Let $\mathcal{P}_k=\{\mathbf{p}_1,\mathbf{p}_2,\ldots,\mathbf{p}_{v_k} \}$ be the set of distinct points in the projective geometry $PG(k-1,q)$, where $v_k=\frac{q^k-1}{q-1}$. 
	% To avoid ambiguity, we agree that all points in $PG(k-1,q)$ are monoic.
	A $j$-flat is a projective subspace of dimension $j$ in $PG(k-1,q)$. $0$-flats and $(k-2)$-flats are called points and hyperplanes. 
	\textit{Multi-set} $\aleph$ in $PG(k-1,q)$ 
    is denoted by $\{m_i\cdot\mathbf{p}_i \mid m_i\in  \mathbb{N}_0, \mathbf{p}_i\in \mathcal{P}_k, 1\le i\le v_k\}$. 
     $\aleph$ can also be viewed as a mapping: $\mathcal{P}_k \to  \mathbb{N}_0$. 
     For $\mathbf{p}_i\in \mathcal{P}_k$, $\aleph(\mathbf{p}_i)=m_i$.  
	If $\mathcal{Q}$ is a subset of $\mathcal{P}_k$, then $\aleph(\mathcal{Q})=\sum_{\mathbf{p}\in \mathcal{Q}} \aleph(\mathbf{p})$.
	We define
	\begin{equation}
		[\aleph]=  (\overset{\aleph(\mathbf{p}_1)}{\overbrace{ \mathbf{p}_1,\ldots ,\mathbf{p}_1} },\ldots,
		\overset{\aleph(\mathbf{p}_{v_k})}{\overbrace{ \mathbf{p}_{v_k},\ldots ,\mathbf{p}_{v_k} }}),\; \mathbf{p}_i\in \mathcal{P}_k,
	\end{equation}
	and $\mathrm{Rank}(\aleph)=\mathrm{Rank}([\aleph])$.


	\begin{definition}\cite{landjev2001geometric}
		A multi-set $\aleph$ in $PG(k-1,q)$ is called an $(n,w;k-1,q)$-arc, if

		(1)  $\aleph(\mathcal{P}_k)=n$;

		(2)  $\aleph(H)\le w$ for any hyperplane $H$;

		(3) there exists a hyperplane $H_0$ with $\aleph(H_0)=w$.
	\end{definition}


	The integer $\aleph(\mathbf{p})$ is called the \textit{multiplicity} of point $\mathbf{p}$ and $n$ is called the \textit{cardinality} of multi-set $\aleph$.
	Let $C_{\aleph}$ be the $[n,k,n-w]_q$ linear code generated by $[\aleph]$.
	Then, the linear code $C_{\aleph}$ and the arc $\aleph$ are said to be  \textit{associated}.
	In this paper, the arc $\aleph$ and the associated linear code $C_\aleph$ will be treated equivalently.
	For example, we refer to $C_{\aleph}$ as being composed of points.
