	\subsection{The binary Solomon-Stiffler  and Belov-type minihypers}
	Let $A$ be a non-empty subset of $[k]$. 
 To describe $\mathcal{P}_{|A|}=PG(|A|-1,2)$ more precisely, we define 
	\begin{equation}
		\mathcal{P}_A=\{ (a_1,a_2,\ldots,a_k):a_i \in \mathbb{F}_2, \text{ if }  i \in A \text{, and } a_i=0 \text{ if } i\not\in A\}
	\end{equation}
	as the $|A|$-dimensional subspace associated with $A$ in $PG(k-1,2)$.
	\begin{definition}\cite{solomon1965algebraically}
		Let $A_1$, $A_2$, $\ldots$, $A_{h}$ be $h$ non-empty subsets of $[k]$, with $|A_1|\ge |A_2|\ge \ldots\ge |A_{h}|$.
		Then
		$\Im_{SS}=\bigcup _{i=1}^{h} \mathcal{P}_{A_i}$ is called an \textit{Solomon-Stiffler (SS)-type $\left\{\sum_{i=1}^{h}  v_{|{A_i}|}, \sum_{i=1}^{h} v_{|{A_i}|-1} ; k-1, 2\right\} $-minihyper}.  %
	\end{definition}

	\begin{definition}\cite{belov1974construction}\label{Belov_type_minihyper}
		Let $A_1$, $A_2$, $\ldots$, $A_{h}$ be $h$ non-empty subsets of $[k]$, with $|A_1|\ge |A_2|\ge \ldots\ge |A_{h}|= t\ge 4$.
		We define $\mathcal{P}_{T_t}$ to be a set of $t+1$ points in $PG(k-1,2)$ such that $\mathrm{Rank} (\mathcal{P}_{T_t})=t$ and $\sum_{\mathbf{p}\in \mathcal{P}_{T_t}}\mathbf{p}=\mathbf{0}$.

		Then
		$\Im_{BV_1}=\bigcup _{i=1}^{h-1} \mathcal{P}_{A_i} \bigcup   (\mathcal{P}_{A_{h}}\setminus \mathcal{P}_{T_t} )$
		and $\Im_{BV_2}=\bigcup _{i=1}^{h-1} \mathcal{P}_{A_i} \bigcup   (\mathcal{P}_{A_{h}}\setminus \mathcal{P}_{T_t} ) \bigcup  \{\mathbf{p} \}$ are called \textit{Belov-type minihypers}
		with parameters $\left\{\sum_{i=1}^{h}  v_{|{A_i}|}-t-1, \sum_{i=1}^{h} v_{|{A_i}|-1} -1; k-1, 2\right\} $ and $\left\{\sum_{i=1}^{h}  v_{|{A_i}|}-t, \sum_{i=1}^{h} v_{|{A_i}|-1} ; k-1, 2\right\} $, where $\mathbf{p}\in PG(k-1,2)$.
	\end{definition}

	For an $[n,k,d]_q$ linear code $C$, if $(s-1)2^{k-1}<d \le s2^{k-1}$, then $d$ can be written uniquely as $d=s2^{k-1}-\sum_{i=0}^{k-2}   \lambda_i 2^{i}$.
	We use
	$\bm{\lambda}=(\lambda_0,\ldots,\lambda_{k-2})$ to denote the \textit{$2$-adic anti-expansion vector} of $C$.


	\begin{example}
		Suppose $C$ is a $[11,4,5]_2$ linear code.
		Since $5=2^3-\sum_{i=0}^{1}2^i$, by the above definition, the $2$-adic anti-expansion vector of $C$ is $\bm{\lambda}=(1,1,0)$.
	\end{example}

	\begin{lemma} (\cite{helleseth1984further,landjev2007weighted} ) \label{Tho_finite_geometry_results}Let $C$ be an  $[n, k, d]_2$ Griesmer code with $2$-adic anti-expansion vector $\bm{\lambda}$.
		If $wt(\bm{\lambda})= 2$, then the associated minihyper of $C$ is an SS or Belov type minihyper.
	\end{lemma}


	Throughout this paper, since binary AFER-optimal linear codes possess the greatest potential for application, our construction results and examples in this paper are mainly binary.
	Additionally, we agree that $s_1$ and $s_2$ are two integers satisfying $s_1\ge 1$ and $s_2\ge 0$.
	\section{Iterative bounds for error coefficients of Griesmer optimal  linear codes}\label{Sec III}

	In this section, we propose five iterative lower bounds on the error coefficients of Griesmer optimal linear codes. We achieve this by analyzing the relationships between linear codes and their residual codes, as well as the structure of related minihypers. Similar to the Griesmer bound, our iterative lower bounds establish a direct connection between high-dimensional and low-dimensional AFER-optimal linear codes. Specifically, our bounds provide lower bounds on the error coefficients of $(k+1)$-dimensional Griesmer optimal linear codes based on the iterative results of AFER-optimal codes with dimensions $\leq k$.




	\subsection{Iterative lower bound I}

	In this subsection, we determine the parameters of all two-dimensional AFER-optimal linear codes. Building on this, we present the first iterative lower bound on the error coefficients of linear codes.



	\begin{definition}
		Let $\mathbf{u}=(u_1,u_2,\ldots,u_n)$ be a vector of $\mathbb{F}_q^n$, and let $A  $ be a  subset of $[n]$.
		Then, we define the puncture operation $\Upsilon $ on $\mathbf{u}$ with respect to $A  $ as
		\begin{equation}
			\Upsilon _{A  }(\mathbf{u})=(u_{i_1},u_{i_2},\ldots,u_{i_m}),
		\end{equation}
		where $\{i_1,i_2,\ldots,i_{m}\}=[n]\setminus {A  }$.
		Moreover, for an $[n,k]_q$ linear code $C$, the punctured code with respect to $A  $ is also denoted as
		\begin{equation}
			\Upsilon _{A  }(C)=\{ \Upsilon _{A  }(\mathbf{c}) \mid  \mathbf{c} \in C\}.
		\end{equation}

		In particular, when $A  =\mathrm{Supp}(\mathbf{c})$ is the support of a codeword $\mathbf{c}$ of $C$, we also use $	\Upsilon _{\mathbf{c}}(C)$ to denote $	\Upsilon _{A  }(C)$.  $\Upsilon _{\mathbf{c}}(C)$ is also called \textit{residual code} of $C$ under codeword $\mathbf{c}$.

		Let ${A  }_C=\mathrm{Supp}(C)$ be the support of $C$. Then, we define
		\begin{equation}
			\Phi  (C)=\{ \Upsilon _{[n]\setminus  {A  }_C}(\mathbf{c}) \mid  \mathbf{c} \in C\}.
		\end{equation}
	\end{definition}






	\begin{theorem}\label{AFER-Two-Dimension}
		Let $s$ and $t$ be two non-negative integers such that $s+t>0$ and $t<q$.
		Then, the $[s(q+1)+t+1,2,sq+t;(q-1)(t+1)]_q$ linear code is AFER-optimal.
		%		$d(s(q+1)+t+1,2,q)=sq+t$ and $e(s(q+1)+t+1,2,q)=(q-1)(t+1)$.
		%		and $C$ is an
		%		Then, the AFER-optimal
		%		the minimum error coefficient of $C$ is $(q-1)(t+1)$. % an AFER-optimal $[s(q+1)+t+1,2,sq+t]_q$ linear code has error coefficient $(q-1)(t+1)$.
	\end{theorem}
	\begin{proof}
		Two-dimensional Simplex code has parameters $[q+1,2,q;q^2-1]_q$.
		The $[s(q+1)+t+1,2,sq+t;(q-1)(t+1)]_q$ Griesmer optimal linear code can be obtained by simple juxtaposition and puncturing of two-dimensional Simplex code.
		Suppose $C$ is an $[s(q+1)+t+1,2,sq+t]_q$ AFER-optimal linear code.
		We prove this theorem in the following cases.

		\textbf{Case A:}  If $s=0$ and $0<t<q$, then $C$ is an MDS linear code. According to \cite{macwilliams1977theory}, the $[t+1,2,t]_q$ linear code has unique weight enumerator $W_C(x)=1+(q-1)(t+1)x^t+(q-1)(q-t)x^{t+1}$.
		Therefore, the minimum value of the error coefficient of $C$ is $(q-1)(t+1)$.

		\textbf{Case B:} If $s>0$ and $t=0$, then $C$ has at least $q-1$ codewords of minimum weight.

		\textbf{Case C:} If $s>0$ and $t>0$, then $C$ is a non-projective linear code.
		Let $\{ \mathbf{p}_1, \mathbf{p}_2, \ldots, \mathbf{p}_{q+1}\} $ be  the $q+1$ points in $PG(1
		,q)$, and let $m_i$ denotes the multiplicity of point $\mathbf{p}_i$ in $C$.
		% Then the code $C$ has the following weight enumerator
		% \begin{equation}
			%     W_C(x)=1+x^{\sum_{i\in [q+1]\setminus \{1\}} m_i }+x^{\sum_{i\in [q+1]\setminus \{2\}} m_i }+\cdots+x^{\sum_{i\in [q+1]\setminus \{q+1\}} m_i }.
			% \end{equation}
		By Lemma \ref{Griesmer_Point_multiplicity}, we have $m_i\le s+1$.     Since all points in  $PG(1,q)$ form a line and points are also hyperplanes, arbitrary $\delta>1$ different points in $PG(1,q)$ generate an  $[\delta,2,\delta-1]_q$ linear code.
		Therefore, a generator matrix of $C$ can be written as

		\begin{equation}
			G=  \left( [(s+1-s^{\prime})\cdot \mathcal{P}_2],G_1,G_{2},\ldots,G_{s^{\prime}} \right),
		\end{equation}
		where $G_i$ consists of different points.

		We use $C_i$ and $n_i$ to denote the code generated by $G_i$ and its length, respectively. It follows that $C_i$ is an $[n_i,2,n_i-1]_q$ linear code with weight enumerator $W_{C_i}(x)=1+(q-1)n_ix^{n_i-1}+(q-1)(q-n_i+1)x^{n_i}$.
		For $1\le i<j\le s^{\prime}$, $n_i+n_j> q+1$.
		% We have that
		%     \begin{equation}
			%         \begin{array}{cc}
				%             s(q+1)+t+1=\sum_{i}^{s+1} n_i,&  \\
				%             sq+t=\sum_{i}^{s+1} n_i-1,& \\
				%             n_i+n_j> q+1&1\le i<j\le s^{\prime}.
				%         \end{array}
			%     \end{equation}

		Let $C^{\prime}=C_1\times C_2\times \cdots\times C_{s^{\prime}}$. Then, $C^{\prime}$ is an $[(s^{\prime}-1)(q+1)+t+1,2,(s^{\prime}-1)q+t]_q$ linear code, and has the same error coefficient with $C$.
		In the following, we turn to prove $A_d(C^{\prime})\ge (q-1)(t+1)$ by recursion.

		\textbf{Case C.1:}
		If $s^{\prime} =1$, then $C^{\prime}$ is an $[t+1,2,t]_q$ MDS code. By (1), $C^{\prime}$ has unique error coefficient $(q-1)(t+1)$.

		\textbf{Case C.2: }
		If $s^{\prime} =2$, then $C^{\prime}$ is a juxtaposition code of $C_1$ and $C_2$, and their weight enumerator are  $W_{C_1}(x)=1+(q-1)n_1x^{n_1-1}+(q-1)(q-n_1+1)x^{n_1}$ and $W_{C_2}(x)=1+(q-1)(n_2)x^{n_2-1}+(q-1)(q-n_2+1)x^{n_2}$, respectively.
		Let $\mathbf{c}=(\mathbf{c}_1,\mathbf{c}_2)$ denote a codeword of $C^{\prime}$, where $\mathbf{c}_i\in C_i$.
		Then $C$ has the minimum error coefficient when all codewords $\mathbf{c}_1$ of weight $n_1$ are juxtaposited with
		codewords $\mathbf{c}_2$ of weight $n_2-1$.
		Therefore, $A_d(C)\ge n_2(q-1)-(q+1-n_1)(q-1)=(n_1+n_2-q-1)(q-1)=(t+1)(q-1)$.

		\textbf{Case C.3: }
		If $s^{\prime} \ge 3$, then, by Case C.2, $A_d(C_1\times C_2)\ge (n_1+n_2-q-1)(q-1)$.
		Similarly, we obtain $A_d(C_1\times C_2\times C_3)\ge (n_1+n_2+n_3-2(q-1) )(q-1)$ by using the same method.
		By induction, $A_d(C_1\times C_2\times \cdots \times C_{s^{\prime}})\ge (\sum_{i=1}^{s^{\prime}}n_i-s^{\prime}(q-1) )(q-1)=(t+1)(q-1)$.

		In conclusion, we complete the proof.
	\end{proof}




	Since Theorem \ref{AFER-Two-Dimension} determines the parameters of all two-dimensional AFER-optimal linear codes, we focus on linear codes with dimensions $k \geq 3$ in the subsequent discussions.

	Building on the results for two-dimensional AFER-optimal linear codes and by analyzing the relationship between linear codes and their residual codes, we present the following theorem.




	\begin{theorem}\label{Enhanced_GriesmerNound_q nmid}
		Let $C$ be an $[n,k,d]_q$ optimal linear code with $k\ge 3$.
		Let $t=q$ if $q\mid d$, and $t=d \mod{q}$ if $q\nmid d$.
		Then, we have
		\begin{equation}\label{Griesmer_type_bound_(2).2}
			A_d(C) \ge L_q^{(1)}(n,k):\triangleq t \left(e_{\left\lceil \frac{d}{q} \right\rceil}(n-d,k-1,q) +\Delta \right) +(q-1)+\Delta^{\prime},
		\end{equation}
		where $\Delta$ is the smallest non-negative integer such that $(q-1) \mid \left( \left\lfloor \frac{ L_q^{(1)}(n,k) -(q-1) }{t} \right\rfloor - \Delta \right)$, and $\Delta^{\prime}$ is the smallest non-negative integer such that $t \mid \left( L_q^{(1)}(n,k)-(q-1) -\Delta^{\prime}\right)$.
	\end{theorem}



	\begin{proof}
		Suppose $C$ is an $[n,k,d]_q$ linear code.
		Let $\mathbf{c}$ be a codeword of $C$ of minimum weight $d$.
		By Theorem 2.7.1 of \cite{huffman2010fundamentals}, we have $\Upsilon _{\mathbf{c}}(C)$ is an $\left[n - d, k - 1, \ge \frac{d}{q}  \right]_q$  linear code.
		Let us prove its error coefficient below.

        		We may assume that $C=\left \langle  C^{\prime}, \mathbf{c} \right \rangle $. 
		 According to the previous definition, for any codeword $\mathbf{c}^{\prime}$ of $C^{\prime}$, we have that
		\begin{equation}
			wt(\Upsilon _{\mathbf{c}}(\mathbf{c}^{\prime})) =n(\left \langle \mathbf{c},\mathbf{c}^{\prime}  \right \rangle )-d.
		\end{equation}

		Since $\left \langle \mathbf{c},\mathbf{c}^{\prime}  \right \rangle$ is an $[n,2,d]_q$ linear code, $n(\left \langle \mathbf{c},\mathbf{c}^{\prime}  \right \rangle )\ge g_q(2,d)=d+\lceil \frac{d}{q} \rceil$. 
				Let $\mathbf{c}_r=\Upsilon _{\mathbf{c}}(\mathbf{c}^{\prime})$. 
		That is,  $\mathbf{c}_r$ is a codeword of $\Upsilon _{\mathbf{c}}(C)$. 
		Then, it follows that $wt(\mathbf{c}_r)=\lceil \frac{d}{q} \rceil$ if and only if $n(\left \langle \mathbf{c},\mathbf{c}^{\prime}  \right \rangle )=g_q(2,d)$. 
		Thus,  $\Phi  (\left \langle \mathbf{c},\mathbf{c}^{\prime}  \right \rangle)$ is a $[g_q(2,d),2,d]_q$ linear code.
		Therefore, for every codeword $\mathbf{c}_r$ of weight $\lceil \frac{d}{q} \rceil$ in $\Upsilon _{\mathbf{c}}(C)$, we can find a corresponding two-dimensional Griesmer code in $C$, from which we have
		\begin{equation}
			A_d(C)\ge A_{\lceil \frac{d}{q} \rceil}(\Upsilon _{\mathbf{c}}(C))\frac{ e(g_q(2,d),2,q)-(q-1)  }{q-1}  +(q-1).
		\end{equation}

		%		Since $e_{\lceil \frac{d}{q} \rceil}(n-d,k-1,q)\le A_{\lceil \frac{d}{q} \rceil}(\Upsilon _{\mathbf{c}}(C))$, we get     \begin{equation}
			%		A_d(C)\ge e_{\left\lceil \frac{d}{q} \right\rceil}(n-d,k-1,q) \frac{ e(g_q(2,d),2,q)-(q-1)}{q-1}  +(q-1).
			%		\end{equation}

		By Theorem \ref{AFER-Two-Dimension}, we get $e(g_q(2,d),2,q)=(q-1)(t+1)$.
		Since $e_{\lceil \frac{d}{q} \rceil}(n-d,k-1,q)\le A_{\lceil \frac{d}{q} \rceil}(\Upsilon _{\mathbf{c}}(C))$, we have     \begin{equation}
			e_{\lceil \frac{d}{q} \rceil}(n-d,k-1,q)\le \left\lfloor \frac{A_d(C) -(q-1) }{t} \right\rfloor.
		\end{equation}


		Due to $(q-1)\mid e_{\lceil \frac{d}{q} \rceil}(n-d,k-1,q)$, we can make appropriate transformations to this equation to obtain Equation (\ref{Griesmer_type_bound_(2).2}). This completes the proof of this theorem.
	\end{proof}

\begin{remark}\label{one-step Griesmer bound}
%	定理4的推导过程中不涉及Griesmer最优性，所以适用于所有的最优线性码。然而，当且仅当$[n-w,k-1,d-\lfloor \frac{w}{q}\rfloor]_q$也是最优码时，$e_{\left\lceil \frac{d}{q} \right\rceil}(n-d,k-1,q)$才大于零，定理4才可能有较好的表现。例如，后文表III中的$[9,5,3;4]$线性码可以由定理4直接确定AFER-最优性。这种通过剩余码反推最优性的方法在Grassl的码表中被称为one-step Griesmer bound。
The proof of Theorem \ref{Enhanced_GriesmerNound_q nmid} does not involve Griesmer optimality, so it applies to all optimal linear codes. However, \( e_{\left\lceil \frac{d}{q} \right\rceil}(n-d,k-1,q) \) is greater than zero, and Theorem 4 can perform well, if and only if \( [n-w,k-1,d-\lfloor \frac{w}{q}\rfloor]_q \) is also an optimal code. For example,  \( [9,5,3;4]_2 \) linear code in Table \ref{Five_Binary_AFER} later can be directly determined to be AFER-optimal by Theorem \ref{Enhanced_GriesmerNound_q nmid} and $[6,4,2;3]_2$ AFER-optimal linear code in Table \ref{Four_Binary_AFER}. This method of inferring optimality through residual codes is called the \textit{one-step Griesmer bound} in Grassl's code table \cite{Grassl:codetables}. 
\end{remark}

