	\subsection{Iterative lower bound II}
	%By restricting our analysis to Griesmer optimal linear codes, we derive a lower bound for their error coefficients.
	%		In this subsection, we agree that Griesmer distance-optimal codes are not Griesmer codes.
				When restricting the Griesmer optimal types of linear codes, we can get another lower bound on the error coefficients of Griesmer optimal linear codes.


	Firstly, to precisely describe the Griesmer optimality of linear codes, we provide the following definition.

	\begin{definition}\label{def_Griesmer optimal}
		For an $[n,k,d]_q$ Griesmer optimal linear code, we define
		$\Gamma _q(n,k,d)= k$ for $ n = g_q(k, d) $. Otherwise, let
		$ \Gamma _q(n,k,d) $ be the smallest integer $k_1$ such that $ n - g_q(k_1, d) \geq g_q\left(k - k_1, \left\lceil \frac{d}{q^{k_1}} \right\rceil + 1 \right)$. 
	\end{definition}

	%It follows that, an $[n,k,d]_q$ linear code is Griesmer distance-optimal if and only if  $\Gamma _q(n,k,d)< k$.

	The following lemma characterizes the properties of Griesmer optimal linear codes.

	\begin{lemma}\label{Lem_critical length-optimal}
		Assume $C$ is an $[n,k,d]_q$ Griesmer optimal linear code with $k\ge 3$.
		Then, the following statements hold.

		(1)  If $\Gamma _q(n,k,d)< k$, then $q\mid d$.

		(2)  If $q\nmid d$, then $C$ is a Griesmer code.

		%		(3) $\Gamma _q(n,k,d)=1$ holds if and only if $C$ is Griesmer critical length-optimal.
	\end{lemma}
	\begin{proof}
		As $C$ is a Griesmer optimal linear code, we have $n\ge g_q(k,d)$ and $n<g_q(k,d+1)$.
		%Let $n^{\prime}=g_q(k,d)$.
		Since         \begin{equation}
			g_q(k,d+1)-g_q(k,d)= \sum\limits_{i=0}^{k-1}\left\lceil  \frac{d+1}{q^{i}}\right\rceil-\sum\limits_{i=0}^{k-1}\left\lceil  \frac{d}{q^{i}}\right\rceil =\left\{\begin{matrix}
				1,& q\nmid d, \\
				2,& q\mid d,
			\end{matrix}\right.
		\end{equation}
		it is easy to see (1) and (2) hold.
	\end{proof}


	\begin{definition}
		Let $C$ be an $[n,k,d]_q$ linear code and $\mathbf{v}$ be a vector of $\mathbb{F}_q^n$. Define
		\begin{equation}
			C+\mathbf{v}=\{ \mathbf{c}+  \mathbf{v}\mid  \mathbf{c}\in C\}.
		\end{equation}
	\end{definition}

	Based on the constraints of minimum-weight codewords, the following proposition is proposed.

	\begin{proposition}\label{Pro_SubCode_Residual}
		Suppose $C$ is an $[n,k,d]_q$ Griesmer optimal linear code.
		If $q\mid d$ and $\Gamma _q(n,k,d)\ge 2$, then for any codeword $\mathbf{c}$ of weight $d$ of $C$, we have
		\begin{equation}\label{Eq_Eq_minimum_linear_nonlinear_subcode}
			A_\frac{d}{q}(\Upsilon _{\mathbf{c}}(C))\le \min\{A_d(C^{\prime}),\min\{ A_d(C^{\prime}+ \alpha \mathbf{c})\mid \alpha\in \mathbb{F}_q^*\}\},
		\end{equation}
		where $C^{\prime}$ is a supplementary subcode of $\mathbf{c}$ such that $C=\left \langle \mathbf{c},C^{\prime}  \right \rangle $.
	\end{proposition}
	\begin{proof}
		Since $q\mid d$ and $\Gamma _q(n,k,d)\ge 2$, $\Upsilon _{\mathbf{c}}(C)$ is an $[n-d,k-1,\frac{d}{q}]_q$ Griesmer-optimal linear code.
		Let $\mathbf{c}^{\prime}$ be a codeword of $C^{\prime}$, and let $m=\max\{wt(\mathbf{c}^{\prime}), wt(\mathbf{c}^{\prime}+\alpha \mathbf{c})\mid \alpha\in \mathbb{F}_q^*\}$.
		According to Lemma 	\ref{Modifications_Griesmer_Bound}, we have \begin{equation}
			n(\Upsilon _{\mathbf{c}}(\left \langle \mathbf{c},\mathbf{c}^{\prime} \right \rangle ))-d\ge \mathsf{g}_q(2, d,m)-d=\left\lceil \frac{m}{q}\right\rceil.
		\end{equation}
		This formula takes the equality if and only if $m=d$.
		By Lemma \ref{replicated Simplex code}, at this time, $\left \langle \mathbf{c},\mathbf{c}^{\prime}  \right \rangle$ is a two-dimensional replicated Simplex code with possible $0$-coordinates.
		That is, $wt(\mathbf{c}^{\prime})=wt(\mathbf{c}^{\prime}+ \alpha \mathbf{c})=d$ holds for all $\alpha$ in $\mathbb{F}_q^*$. It is natural to conclude that Equation (\ref{Eq_Eq_minimum_linear_nonlinear_subcode}) is true.
	\end{proof}




	By characterizing the relationship between Griesmer distance-optimal linear code and its puncture and residual codes, we deduce the following theorem.

	\begin{theorem}\label{Theo_Extend_Code}
		If $C$ is an $[n,k,d]_q$ Griesmer optimal linear code with  $\Gamma _q(n,k,d)< k$.
		%		Let $n,k$, and $d$ be three positive integers such that .
		then
		\begin{equation}
			A_d(C)\ge L_q^{(2)}(n,k):\triangleq e(n-d-1,k-1,q).
		\end{equation}
	\end{theorem}
	\begin{proof}
		%		According to the convention above, $C$ is a Griesmer distance-optimal code but not Griesmer code.
		By Lemma \ref{Lem_critical length-optimal}, we have that $q\mid d$ and $n> g_q(k,d)$. %,  $n< g_q(k,d+1)$.
		It follows that $d(n-1,k,q)=d$.
		%		Suppose $C^{\prime}$ is an $[n-1,k,d]_2$ linear code.
		Let us prove the minimum error coefficient of $C$ in two different scenarios.



		(1) If puncture some position of $C$ yields  an $[n-1,k,d]_q$ linear code $C^{\prime}$, then we have
		\begin{equation}
			A_d(C)\ge  \min\{A_d(\tilde{C} ^{\prime})\mid  \tilde{C} ^{\prime} \text{ is a $(k-1)$-dimensional  linear subcode of } C^{\prime} \}.
		\end{equation}


		Let $\mathbf{c}^{\prime}$ be a codeword of weight $d$ of $C^{\prime}$. As $\Gamma _q(n-1,k,d)\ge 2$, we have  $\Upsilon _{\mathbf{c}^{\prime}}(C^{\prime})$ is an $[n-d-1,k-1,\frac{d}{q}]_q$ Griesmer optimal linear code.
		By Proposition \ref{Pro_SubCode_Residual}, we get
		\begin{equation}
			A_{\frac{d}{q}}\left( \Upsilon _{\mathbf{c}^{\prime}}(C^{\prime}) \right)\le \min\{A_d(\tilde{C} ^{\prime})\mid  \tilde{C} ^{\prime} \text{ is a $(k-1)$-dimensional  linear subcode of } C^{\prime} \}.
		\end{equation}

		As $e(n-d-1,k-1,q)\le e\left( \Upsilon _{\mathbf{c}^{\prime}}(C^{\prime}) \right)$, we can directly deduce that $A_d(C)\ge e(n-d-1,k-1,q)$.

		(2) If $C$ is not extended from an $[n,k,d]_q$ linear code, then puncture any position on $C$ deduce an $[n-1,k,d-1]_q$ linear code $C^{\prime\prime}$.
		Let $\mathbf{c}^{\prime\prime}$ be a codeword of weight $d-1$ of $C^{\prime \prime}$.
		As $q\nmid (d-1)$, $\Upsilon _{\mathbf{c}^{\prime\prime}}(C^{\prime\prime})$ is also an $[n-d-1,k-1,\frac{d}{q}]_2$ Griesmer optimal linear code.
		According to the proof of Theorem \ref{Enhanced_GriesmerNound_q nmid}, we have
		\begin{equation}
			A_{d-1}(C^{\prime\prime}) \ge (q-1)A_{\frac{d}{q}}(\Upsilon _{\mathbf{c}^{\prime\prime}}(C^{\prime\prime}))+(q-1)\ge (q-1)e(n-d-1,k-1,q)+(q-1).
		\end{equation}

		Since $C^{\prime\prime}$ is obtained by puncturing $C$, it follows that $A_d(C)\ge A_{d-1}(C^{\prime\prime})$.
		Thus, in this case, we have  $A_d(C)\ge (q-1)e(n-d-1,k-1,q)+(q-1)$.
		%		Similar with (1), for any codeword $\mathbf{c}_1^{\prime\prime}\in C^{\prime\prime} \setminus \mathbf{c}^{\prime\prime}$,
		%		$\Upsilon _{\mathbf{c}^{\prime\prime}}(\mathbf{c}_1^{\prime\prime})=\frac{d}{2}$ if and only if $wt(\mathbf{c}_1^{\prime})=d$.
	\end{proof}

	In Example \ref{Ex.first_bound}, the AFER-optimality of $[7s_2+5,3,4s_2+2;2]_2$ linear code remains undetermined. As the following example shows, its AFER-optimality can be solved by Theorem \ref{Lem_critical length-optimal}.
