	According to Definition \ref{def_Griesmer optimal}, we can deduce that Griesmer optimal linear codes have a specific subcode structure, as shown in the following proposition.


	\begin{proposition}\label{Generalized_Griesmer_code_code_chain}
		Let $C$ be an $[n,k,d]_q$ Griesmer optimal linear code, and let $k_1=\min\{\Gamma _q(n,k,d),k-1\}$.
		Then, $C$ has a linear subcode chain $C_{1}    \subset C_{2}\subset \cdots \subset C_{{k_1}}\subset C$ satisfies
		%$1$, $2$, $\ldots$, and $k_1$-dimensional  subcodes
		%$C_{1}$, $C_{2}$, $\ldots$, and $C_{{k_1}}$
		\begin{equation}\label{E_Code_Chain}
			%\left\{
			\begin{array}{cc}
				n(C_{1} )=g_q(1,d), \\
				n(C_{2})=g_q(2,d),\\
				\vdots\\
				n(C_{{k_1}})=g_q(k_1,d),
			\end{array} %\right.
		\end{equation}
		where $C_{i}$ is an $i$-dimensional linear subcode of $C$.
	\end{proposition}
	\begin{proof}
Before we formally begin the proof, we give a description of the punctured code of $C$ according to multiple codewords. 
    Let $k^{\prime}\le k_1$ be a positive integer and 
		let $\mathbf{c}_1$, $\mathbf{c}_2$, $\ldots$, $\mathbf{c}_{k^{\prime}}$ be $k^{\prime}$ linearly independent codewords of $C$.
       Suppose $A  =\mathrm{Supp}(\left \langle  \mathbf{c}_1,\mathbf{c}_2,\ldots,\mathbf{c}_{k^{\prime}} \right \rangle ) $.
		Then, it follows that, for all $\mathbf{c}_{r}\in \Upsilon _{A}(C)$, we have
		\begin{equation}
			wt(\mathbf{c}_{r})\ge d_r=\min \left\{
			n(\left \langle  \mathbf{c}_1,\mathbf{c}_2,\ldots,\mathbf{c}_{k^{\prime}},\mathbf{c} \right \rangle ) \mid  \mathbf{c}\in C\setminus \left \langle  \mathbf{c}_1,\mathbf{c}_2,\ldots,\mathbf{c}_{k^{\prime}} \right \rangle \right\}
			-
			n(\left \langle  \mathbf{c}_1,\mathbf{c}_2,\ldots,\mathbf{c}_{k^{\prime}} \right \rangle ).
		\end{equation}
		This is, $\Upsilon _{A}(C)$ is an $[n-|A  |,k-k^{\prime},d_r]_q$ linear code. 
		In the following, we prove that the proposition holds in two cases.

		\textbf{Case A}: When $ n = g_q(k, d) $.  %We have $ k_1 = k-1 $.
		Let $\mathbf{c}_{1}$ be a codeword of weight $d$ of $C$ and $A  _{1}=\mathrm{Supp}(\mathbf{c}_{1})$.
		Then,  $\Upsilon _{A  _1}(C)$ is an $[n-d,k-1$ linear code with minimum distance
		$\min\{n(\left \langle \mathbf{c}_{1},\mathbf{c}_{2}  \right \rangle )-d\mid \mathbf{c}_{2}\in C \setminus \left \langle  \mathbf{c}_1 \right \rangle   \}.$

		According to Theorem \ref{Griesmer_Bound}, for all codeword $\mathbf{c}_{2}$ of $C\setminus \left \langle  \mathbf{c}_1 \right \rangle $, $n(\left \langle \mathbf{c}_{1},\mathbf{c}_{2}  \right \rangle ) \ge g_q(2,d)$.
		Since $n-d=g_q\left(k-1,\left\lceil \frac{d}{q} \right\rceil\right)$, the $\left[n-d,k-1, \left\lceil \frac{d}{q} \right\rceil + 1\right]_q$ linear code violates the Griesmer bound. Thus, there must exist some codeword $\mathbf{c}_{2}$ of $C\setminus \left \langle  \mathbf{c}_1 \right \rangle $ such that $n(\left \langle \mathbf{c}_{1},\mathbf{c}_{2}  \right \rangle ) = g_q(2,d)$.
		By induction, we can find another linearly independent codewords $\mathbf{c}_{3}$, $\mathbf{c}_{4}$, $\ldots$, $\mathbf{c}_{{k-1}}$ of $C$ such that \begin{equation}
			n(\left \langle  \mathbf{c}_1,\mathbf{c}_2,\ldots,\mathbf{c}_{k^{\prime}} \right \rangle )=g_{q}(k^{\prime},d)
		\end{equation}
		holds for all $2\le k^{\prime}\le k-1=k_1$.
		Denote the linear codes $\left \langle \mathbf{c}_{1} \right \rangle $, $\left \langle \mathbf{c}_{1},\mathbf{c}_{2} \right \rangle $, $\ldots$,  $\left \langle \mathbf{c}_{1},\mathbf{c}_{2},\ldots,\mathbf{c}_{{k-1}} \right \rangle $ by $C_{1}$, $C_{2}$, $\ldots$, $C_{{k-1}}$.
		Then, Equation (\ref{E_Code_Chain}) can be derived immediately.

		\textbf{Case B}: When $ n > g_q(k, d) $.  We have $ k_1 $ is the smallest integer such that $ n - g_q(k_1, d) \geq g_q(k - k_1, \lceil \frac{d}{q^{k_1}} \rceil + 1) $ and $k_1\ge1$.
		Therefore, the $\left[n-g_{q}(k^{\prime},d),k-k^{\prime}, \left\lceil \frac{d}{q^{k^{\prime}}} \right\rceil  +1\right]_q$ linear code violates the Griesmer bound for $1\le k^{\prime}\le k_1-1$.
		Similar with Case A, we can find $k_1$ linearly independent codewords of $\mathbf{c}_{1}$, $\mathbf{c}_{2}$, $\ldots$, $\mathbf{c}_{{k_1}}$ of $C$ such that
		\begin{equation}
			n(\left \langle  \mathbf{c}_1,\mathbf{c}_2,\ldots,\mathbf{c}_{k^{\prime}} \right \rangle )=g_{q}(k^{\prime},d),
		\end{equation}
		holds for all $2\le k^{\prime}\le k_1$.
		This also implies Equation (\ref{E_Code_Chain}) holds.
	\end{proof}

	Relying on Propositions \ref{Pro_SubCode_Residual} and \ref{Generalized_Griesmer_code_code_chain}, the following theorem can be established.

	\begin{theorem}\label{Th. Enhanced_GriesmerNound_q mid d_based}
		Let $C$ be an $[n,k,d]_q$ Griesmer optimal linear code with $q\mid d$ and $k_1=\min\{\Gamma _q(n,k,d),k-1\}\ge 2$.
		Let $s=\left \lceil \frac{d}{q^{k-1}} \right\rceil $, and let $\mu_q(n,k) =\max\{ e(g_q(k_1,d),k_1,q),e_d(n-s,k-1,q)\}$.
		Then, we have
		%	\begin{equation}\label{Griesmer_type_bound_(2).1_based}
			%		e(n-d,k-1,q)\le \left\lfloor\frac{e(n,k,q)-\mu_q(n,k)-(q-1)}{q-1}\right\rfloor-\Delta,
			%	\end{equation}
		\begin{equation}\label{Griesmer_type_bound_(2).2_based}
			e(n,k,q)\ge L_q^{(3)}(n,k):\triangleq (q-1) (e(n-d,k-1,q)+\Delta) +\mu_q(n,k)+(q-1).
		\end{equation}
		where $\Delta$ is the smallest non-negative integer such that $(q-1) \mid \left( \left\lfloor\frac{L_q^{(3)}(n,k)-\mu_q(n,k)-(q-1)}{q-1}\right\rfloor-\Delta \right)$.
		%	Equivalently, it follows
	\end{theorem}
	\begin{proof} 
                		Since $k_1=\min\{\Gamma _q(n,k,d),k-1\}\ge 2$, the residual code of $C$ under codeword of weight $d$ has parameters $[n-d,k-1,\frac{d}{q}]_q$. 	
                With Proposition \ref{Generalized_Griesmer_code_code_chain}, there must exist some codeword $\mathbf{c}$ of weight $d$ in $C\setminus  C_{k-1}$ such that $C=\left \langle \mathbf{c},  C_{k-1} \right \rangle $. 
		It follows that \begin{equation}
			A_d(C)=A_d(C_{k-1})+\sum\limits_{i=0}^{q-2} A_d(C_{k-1}+\alpha^{i}\mathbf{c})+q-1.
		\end{equation} 
        It is easy to conclude that there must be at least one subcode in $ C_{k-1}+\mathbf{c}$, $\ldots$, and $C_{k-1}+\alpha^{q-2}\mathbf{c}$ with error coefficient less than  $\left\lfloor\frac{A_d(C)-A_d(C_{k-1})-(q-1)}{q-1}\right\rfloor$. 
        In the following, we complete the proof of this theorem by proving that the lower bound on the maximum error coefficient of $(k-1)$-dimensional linear subcode of $C$ is $\mu_q(n,k)$. 

		According to Proposition \ref{Generalized_Griesmer_code_code_chain}, $C$ has a $k_1$-dimensional linear subcode $C_{{k_1}}$ satisfies $n(C_{{k_1}})=g_q(k_1,d)$.
		Without loss of generality, assume that $C_{k-1}$ is a $(k-1)$-dimensional linear subcode of $C$ such that $C_{{k_1}}\subset C_{k-1}$.
	This implies $A_d(C_{k-1})\ge e(g_q(k_1,d),k_1,q)$.


        In addition, as there exists point $\mathbf{p}$ in $C$ repeats at least $s$ times, $C$ has a $(k-1)$-dimensional linear subcode $C_{k-1}^{\prime}$ satisfies $n(C_{k-1}^{\prime})\le n-s$. 
		Moreover, for the reason that $g_q(k-1,d+1)=g_q(k,d+1)-\left \lceil \frac{d+1}{q^{k-1}} \right\rceil\ge g_q(k,d+1)-s\ge n-s$, $\Phi (C_{k-1}^{\prime})$ is also an $[\le n-s,k-1,d]_q$ Griesmer optimal linear code. 
        Therefore, $C$ has a $(k-1)$-dimensional subcode has error coefficients at least $\mu_q(n,k)$. 




		By Proposition \ref{Pro_SubCode_Residual}, we have

		\begin{equation}
			A_\frac{d}{q}(\Upsilon _{\mathbf{c}}(C))\le \left\lfloor\frac{A_d(C)-\max\{A_d(C_{k-1}),A_d(C_{k-1}^{\prime})\}-(q-1)}{q-1}\right\rfloor=\left\lfloor\frac{A_d(C)-\mu_q(n,k)-(q-1)}{q-1}\right\rfloor.
		\end{equation}


		Since  $(q-1)\mid A_\frac{d}{q}(\Upsilon _{\mathbf{c}}(C))$, we can make appropriate transformations to this equation to obtain Equation (\ref{Griesmer_type_bound_(2).2_based}).
		Hence, this theorem is true.
	\end{proof}

	Under Theorem \ref{Th. Enhanced_GriesmerNound_q mid d_based}, we can prove that
	$[7s_2+4,3,4s_2+2;6]_2$ linear code is AFER-optimal, as shown in the following example.
	\begin{example}
		Let the notation be the same with Example \ref{Ex.first_bound}.
		Since $[7s_2+4,3,4s_2+2;6]_2$ linear code $C_1$ is a Griesmer code, $\Gamma _2(7s_2+4,3,4s_2+2)=3\ge 2$.
