	\subsection{Iterative lower bound IV} 	
	% This subsection analyzes the subcode structure of Griesmer optimal linear code, which allows us to generalize the results of the previous section.

	Using Proposition \ref{Generalized_Griesmer_code_code_chain}, we derive another lower bound on the error coefficients of Griesmer optimal linear codes, as presented in the following theorem.

	% We can derive the following theorem by using the subcode structure of Griesmer optimal linear codes.

	\begin{theorem}\label{k_Residue_Grismer_Bound}
		Let $C$ be an $[n,k,d]_q$ Griesmer optimal linear code with $k_1=\min\{\Gamma _q(n,k,d),k-1\}\ge 2$.
		Let $k_2<k_1$ be a positive integer.
		Define $\varsigma_q(k_2,d) =e(g_q(k_2+1,d),k_2+1,q) - e(g_q(k_2,d),k_2,q) $.
		Then, we have
		\begin{equation}\label{Eq_Improved_Griesmer_type_bound_k_Residue}
			A_d(C)\ge L_q^{(4)}(n,k):\triangleq
			\max\left\{
			\frac{\left( e(n-g_q(k_2,d),k-k_2,q)+ \Delta\right)\varsigma_q(k_2,d)}{q-1}
			+ e(g_q(k_2,d),k_2,q)+\Delta^{\prime}
			\mid 1\le k_2< k_1\right\},
		\end{equation}
		where $\Delta$ is the smallest non-negative integer such that $(q-1) \mid  \left( \left\lfloor \frac{ L_q^{(4)}(n,k) - e(g_q(k_2,d),k_2,q) }{\varsigma_q(k_2,d)} \right\rfloor-\Delta \right)$ and
		$\Delta^{\prime}$ is the smallest non-negative integer such that $\varsigma_q(k_2,d) \mid \left( L_q^{(4)}(n,k) - e(g_q(k_2,d),k_2,q) -\Delta^{\prime}\right)$.
	\end{theorem}
	\begin{proof}
		According to Proposition \ref{Generalized_Griesmer_code_code_chain}, we can find $k_1$ bases vectors  $\mathbf{c}_{1}$, $\mathbf{c}_{2}$, $\ldots$, $\mathbf{c}_{{k_1}}$ of $C$, such that \begin{equation}
			n(\left \langle  \mathbf{c}_1,\mathbf{c}_2,\ldots,\mathbf{c}_{k_2} \right \rangle )=g_{q}(k_2,d)
		\end{equation}
		holds for all $2\le k_2< k_1$.
		This is, $\left \langle  \mathbf{c}_1,\mathbf{c}_2,\ldots,\mathbf{c}_{k_2} \right \rangle$ is a $[g_{q}(k_2,d),k_2,d]_q$ Griesmer code.
		Let $C_{{k_2}}=\left \langle  \mathbf{c}_1,\mathbf{c}_2,\ldots,\mathbf{c}_{k_2} \right \rangle$ and $A  =\mathrm{Supp}(C_{{k_2}})$.
		Since $k_2<k_1$, the $\left[n-g_{q}(k_2,d),k-k_2,\left\lceil \frac{d}{q} \right\rceil+1\right]_q$ linear code violates the Griesmer bound, and $\Upsilon _{A  }(C) $ is an $\left[n-g_{q}(k_2,d),k-k_2,\left\lceil \frac{d}{q} \right\rceil\right]_q$ Griesmer code.
		It follows that, for any codeword $\mathbf{c}$ of $C\setminus C_{{k_2}}$, $\Upsilon _{A  }(\mathbf{c})$ has weight $\left\lceil \frac{d}{q^{k_2}} \right\rceil$ if and only if $n(\left \langle  \mathbf{c}_1,\mathbf{c}_2,\ldots,\mathbf{c}_{k_2},\mathbf{c} \right \rangle)=g_q(k_2+1,d)$.
		At this time, $\left \langle  \mathbf{c}_1,\mathbf{c}_2,\ldots,\mathbf{c}_{k_2},\mathbf{c} \right \rangle$ is an $[g_{q}(k_2+1,d),k_2+1,d]_q$ Griesmer code with error coefficient at least $e(g_q(k_2+1,d),k_2+1,q)$.
		Therefore, we have the following constrains relationship
		\begin{equation}
			\frac{e(n-g_q(k_2,d),k-k_2,q)}{A_d(C) - e(g_q(k_2,d),k_2,q)}	\le
			\frac{q-1}{e(g_q(k_2+1,d),k_2+1,q) - e(g_q(k_2,d),k_2,q)}=\frac{q-1}{\varsigma_q(k_2,d)}.
		\end{equation}

		Since $(q-1)\mid e\left(\Upsilon _{A  }(C) \right)$, we can directly derive that,
		\begin{equation}
			A_d(C)\ge	\frac{\left( e(n-g_q(k_2,d),k-k_2,q)+ \Delta\right)\varsigma_q(k_2,d)}{q-1}
			+ e(g_q(k_2,d),k_2,q)+\Delta^{\prime}.
		\end{equation}
		As this formula holds for $1\le k_2\le k_1$,  we get Equation (\ref{Eq_Improved_Griesmer_type_bound_k_Residue}).
		Hence, we complete the proof.
	\end{proof}



	The implementation of Theorem \ref{k_Residue_Grismer_Bound} depends on the special subcode structure of Griesmer optimal linear codes.
	If $k_2=1$, then Theorems \ref{Enhanced_GriesmerNound_q nmid} and \ref{k_Residue_Grismer_Bound} are the same. 
	When we have more information about AFER-optimal linear codes of low dimensions, Theorem \ref{k_Residue_Grismer_Bound} may perform better than Theorems \ref{Enhanced_GriesmerNound_q nmid} and \ref{Th. Enhanced_GriesmerNound_q mid d_based}, as shown in the following example.

	\begin{example}
		Set $q=2$.
