	\begin{theorem}\label{Theo_Mix_lower_bound}
		With notation as above, let \( C \) be an \( [n,k,d]_q \) optimal linear code for $k\ge 3$. Then
		\begin{equation}\label{Eq_five_lower_bounds}
			e(n,k,q) \ge \max \left\{
			\begin{array}{cl}
				L_q^{(1)}(n,k), & \text{unconditional (Theorem \ref{Enhanced_GriesmerNound_q nmid})}, \\
				L_q^{(2)}(n,k), & \Gamma_q(n,k,d) < k \text{ (Theorem \ref{Theo_Extend_Code})}, \\
				L_q^{(3)}(n,k), & q \mid d \text{ and } \Gamma_q(n,k,d) \ge 2 \text{ (Theorem \ref{Th. Enhanced_GriesmerNound_q mid d_based})}, \\
				L_q^{(4)}(n,k), & \Gamma_q(n,k,d) \ge 2 \text{ (Theorem \ref{k_Residue_Grismer_Bound})}, \\
				L_q^{(5)}(n,k), & n = g_q(k,d) \text{ and the maximum rank of the associated Griesmer minihyper is known (Theorem \ref{Theo_minihyper_rank_bound})},
			\end{array}
			\right.
		\end{equation}
	where the first bound applies to any optimal linear code but performs better for those that are optimal under the one-step Griesmer bound (Remark \ref{one-step Griesmer bound}); the remaining four bounds apply only to Griesmer optimal codes, whose specific optimality is characterized by \( \Gamma_q(n,k,d) \).
	\end{theorem}



