		\begin{lemma}\label{Lem_non-extendable_even_codes}
			An $[n,k,d]_2$ linear code with $2\mid d$ is non-extendable if and only if $\Upsilon _{\mathbf{c}}(C)$ has parameters $[n-d,k-1,\frac{d}{2}]_2$ for all codewords $\mathbf{c}$ of weight $d$ of $C$.
		\end{lemma}
		\begin{proof}
			Let $C^{\prime}$ be the complement of $\mathbf{c}$ such that $C=\left \langle C^{\prime}, \mathbf{c} \right \rangle $.
			Let $\mathbf{c}^{\prime}$ be a codeword of $C^{\prime}$.
			Then $C$ is  non-extendable if and only if for all codewords $\mathbf{c}$ of weight $d$ of $C$, there must exist some codeword $\mathbf{c}^{\prime}$ of weight $d$ in $C^{\prime}$ such that $wt(\mathbf{c}+\mathbf{c}^{\prime})=d$. That is to say, no matter which linear extension operation is applied to \( C \), there will always be a codeword of minimum weight that cannot be extended.




			If $wt(\mathbf{c}^{\prime})>d$ or $wt(\mathbf{c}^{\prime}+\mathbf{c})>d$, then $n(\left \langle \mathbf{c},\mathbf{c}^{\prime} \right \rangle )\ge \mathsf{g}_2\left(2,d,\max\{ wt(\mathbf{c}^{\prime}),wt(\mathbf{c}^{\prime}+\mathbf{c})\}\right) >g_2(2,d)$.
			It follows that $\Upsilon _{\mathbf{c}}(\mathbf{c}^{\prime})> n(\left \langle \mathbf{c},\mathbf{c}^{\prime} \right \rangle )-d>\frac{d}{2}$.
			Similarly, $\Upsilon _{\mathbf{c}}(\mathbf{c}^{\prime})=\frac{d}{2}$ if and only if $wt(\mathbf{c}^{\prime})=wt(\mathbf{c}^{\prime}+\mathbf{c})=d$, i.e., $\Phi (\left \langle \mathbf{c},\mathbf{c}^{\prime} \right \rangle)$ is a two-dimensional replicated Simplex code.
			Therefore, if $\Upsilon _{\mathbf{c}}(C)$ has parameters $[n-d,k-1,\frac{d}{2}]_2$ for all codewords $\mathbf{c}$ of weight $d$ of $C$, then there always exist some codewords $\mathbf{c}^{\prime}$ in $C$ such that $wt(\mathbf{c}+\mathbf{c}^{\prime})=d$.


			Thus, we finish the proof.
		\end{proof}

		\begin{remark}
			In \cite{maruta2001extendability}, Maruta  provided a sufficient condition for binary linear codes with even-distances to be non-extendable.
			Therefore, Lemma \ref{Lem_non-extendable_even_codes} can be seen as an improvement on Maruta's results.
		\end{remark}

		Next, let us determine the lower bound on the error coefficients for binary even-distance non-extendable linear codes.



		\begin{definition}
			Suppose $n,k$, and $d$ are three positive integers such that $d\le d(n,k,2)$. We define
			\begin{equation}
				\underline{e}_d(n,k,2):=\min \{A_d(C)\mid \text{ $C$ is an $[n,k,d]_2$ linear code } \}.
			\end{equation}
		\end{definition}		


		\begin{theorem}\label{L_extendability_Linear_codes}
			Let $C$ be an $[n,k,d]_2$ linear code with $2\mid d$, and let $s=\left\lceil \frac{n}{2^{k}-1} \right\rceil$.
			If $C$ is non-extendable, then we have $A_d(C)\ge  \max \{ e_d(n-s,k-1,2)+2, e_d(n-s,k-1,2)+\underline{e}_{\frac{d}{2}}(n-d,k-1,2)+1\}$.
		\end{theorem}
		\begin{proof}
			Since $C$ is non-extendable, by Lemma \ref{Lem_non-extendable_even_codes}, for all codewords $\mathbf{c}$ of weight $d$ of $C$, $\Upsilon_{\mathbf{c}}(C)$ has parameters $[n-d,k-1,\frac{d}{2}]_2$.




			As $|PG(k-1,2)|=2^{k-1}$, there must exist some point has multiply $s$ in $C$.
			Without loss of generality, we may assume that a generator matrix of $C$ is
			\begin{equation}
				G=
				\left(
				\begin{array}{cc}
					\mathbf{1}_{s}&\mathbf{x}\\
					\mathbf{0}&G_1
				\end{array}
				\right),
			\end{equation}
			where $wt((\mathbf{1}_{s},\mathbf{x}))=d$.
			It follows that $G_1$ generates an $[n-s,k-1,\ge d]_2$ linear code $C_1$.
			According to Proposition \ref{Pro_SubCode_Residual}, $A_{\frac{d}{2}}(\Upsilon_{\mathbf{c}}(C))\le \min\{A_d(C^{\prime}), A_d(C^{\prime}+ \mathbf{c})\}$ and
			$A_{\frac{d}{2}}(\Upsilon_{\mathbf{c}}(C))\ge \underline{e}_{\frac{d}{2}}(n-d,k-1,2)\ge 1$.
			Thus, we have $A_d(C)\ge A_d(C_1)+A_{\frac{d}{2}}(\Upsilon_{\mathbf{c}}(C))+1\ge  \max \{ e_d(n-s,k-1,2)+2, e_d(n-s,k-1,2)+\underline{e}_{\frac{d}{2}}(n-d,k-1,2)+1\}$.
			Hence, this theorem is true.
		\end{proof}

		With the help of Theorem  \ref{L_extendability_Linear_codes}, we prove that $[31s_2 +7,5,16s_2 +2;5]_2$ linear code is AFER-optimal, as shown in the following theorem.

		\begin{theorem}\label{Theo_[7,5,2]}
			%	The matrix $([s_2 \cdot \mathcal{P}_{[5]}],G_{[7,5,2;5]_2})$ generates a
			The	$[31s_2 +7,5,16s_2 +2;5]_2$ linear code is AFER-optimal.
		\end{theorem}
		\begin{proof}
			Let $C$ be a $[31s_2 +7,5,16s_2 +2;e]_2$ AFER-optimal linear code.
			By case 4 of Theorem \ref{Theo_Mix_lower_bound}, we have $e\ge 4$.
			It is easy to check that $([s_2 \cdot \mathcal{P}_{[5]}],G_{[7,5,2;5]_2})$ generates a $[31s_2 +7,5,16s_2 +2;5]_2$ linear code, where $G_{[7,5,2;5]_2}$ is listed in the appendix. Thus, we have $4\le e \le 5$.

			According to Lemma \ref{Griesmer_Point_multiplicity}, any point in $C$ repeats at most $s_2 +2$ times.
			If $C$ has some point $\mathbf{p}$ repeats $s+2$ times, then shorten related coordinates on $C$ will deduce a $[30s_2 +5,4,16s_2 +2]_2$ linear code.
			By case 1 of Theorem \ref{Theo_Mix_lower_bound}, we have $e(30s_2 +5,4,2)\ge 10>5$.
			Therefore, any point in $C$ has multiply less than $s_2 +2$.
			We will prove that the $[31s_2 +7,5,16s_2 +2;5]_2$ linear code is AFER-optimal in two cases.

			\textbf{Case A:}
			If $C$ is non-extendable, then by Theorem \ref{L_extendability_Linear_codes}, we have $e\ge e_{16s_2 +2}(30s_2 +6,4,2)+2\ge 5$.
			By \cite{Grassl:codetables}, there is no $[8,5,3]_2$ linear code.
			Therefore, $C$ is non-extendable for $s_2=0$ and  $e\ge 5$.

			\textbf{Case B:}
			If C is extendable, then $s_2\ge 1$.
			Because the extended code of $C$ has an odd distance, we can obtain an $[31s_2+9,5,16s_2+4]_2$ linear code after two extensions.
			According to Lemmas \ref{Tho_finite_geometry_results} and  \ref{Lem_Belov-type}, there only exist two SS-type $[31s_2+9,5,16s_2+4]_2$ linear codes have different weight enumerators, with associated minihypers $\Im_1=\mathcal{P}_{[4]}\bigcup  \mathcal{P}_{[3,5]}$ and $\Im_2=\mathcal{P}_{[4]}\bigcup  \mathcal{P}_{[2,4]}$.
			Since any points in $C$ have multiply not exceeding $s+1$, we get $C$ by puncturing the two $[31s_2+9,5,16s_2+4]_2$ linear codes.
			After traversal puncturing two $[40,5,20]_2$ linear codes associated with $\Im_1$ and $\Im_2$, we obtain only $[38,5,18;5]_2$ linear code. Thus, $e\ge 5$ at this point.
		\end{proof}




		\subsection{Binary AFER-optimal linear codes form Solomon-Stiffler and Belov Codes}

		In this subsection, we mainly determine AFER-optimal Griesmer codes that are SS or Belov Codes with the help of classification results in \cite{helleseth1984further}.
		%Let $s$ and $k$ be two positive integers.
		We assume that $C$ is an  $[n, k, d]_2$ Griesmer code and with $2$-adic anti-expansion vector $\bm{\lambda}=(\lambda_0,\ldots,\lambda_{k-2})$.

		The following two lemmas give the restrictive conditions that Griesmer codes are SS or Belov-type linear codes.

		\begin{lemma}\cite{belov1974construction}\label{Lemma_not_SS_type}
			If $\sum_{i=0}^{k-2} \lambda_i (i+1)>  k\left\lceil \frac{d}{2^{k-1}} \right\rceil $, then $C$ is not an SS-type linear code.
		\end{lemma}


		\begin{lemma}\label{Lem_Belov-type}
			If $C$ is a Belov-type linear code, then there exists a positive integer $k_{bv}\ge 4$ such that $\lambda_{k_{bv}-1}=0$ and $\lambda_i=1$ for $1\le i\le k_{bv}-2$.
		\end{lemma}
		\begin{proof}
			Let $\Im$ be the associated minihyper of $C$.
			According to Definition \ref{Belov_type_minihyper}, $\Im$ has a sub-multi-set $\Im^{\prime}$ contains all $i$-flats in $\Im$ that are not $\{ v_{i+1}, v_i;i,q\}$-arcs.
			%		Suppose $\Im^{\prime}$ is a $\left\{\sum_{i=0}^{k-2} \epsilon_{i} v_{i+1}, \sum_{i=0}^{k_{bv}-2} \epsilon_{i} v_{i} ; k-1, 2\right\} $-minihyper.
			Since $\eth_{k_{bv}}(\Im^{\prime})$ generates a $[k_{bv}+1,k_{bv},2]_2$ or $[k_{bv},k_{bv},1]_2$ linear code, $d\pmod{2^{k_{bv}}}=2^{k_{bv}-1}-2$ or $2^{k_{bv}-1}-1$. It follows that $\lambda_{k_{bv}-1}=0$ and $\lambda_i=1$ for $1\le i\le k_{bv}-2$.
		\end{proof}










		\begin{theorem}\label{Theo_SS_h=2}
			Let $k\ge 4$, $k_1$, and $k_2$ be three positive integers such that $k_2<k_1<k$. Then, the following statements hold.

			(1)
			If $k_1\ge k_2+2$ or $k_2\ge 3$,  then, $s_1\cdot \mathcal{P}_{[k]}\setminus (\mathcal{P}_{[k_1]}\bigcup  \mathcal{P}_{[k-k_2+1,k]})$ generates an $[s_1v_k-v_{k_1}-v_{k_2},k,s_12^{k-1}-2^{k_1-1}-2^{k_2-1}]_2$ AFER-optimal linear code with error coefficient
			\begin{equation}
				\left\{
				\begin{array}{cc}
					2^{k}+2^{k-|A_1|-| A_2|}- 2^{k-|A_1|} - 2^{k-|A_2|},& \text{ if } |A_1|+|A_2|\le k. \\
					2^{k}-2^{k-|A_1|} -2^{k-| A_2|}+1 ,& \text{ if } |A_1|+|A_2|> k.
				\end{array}
				\right.
			\end{equation}

			(2) For $k\ge 4$, $s_1\cdot \mathcal{P}_{[k]}\setminus (\mathcal{P}_{[4]}\setminus \mathcal{P}_{T_4})$ generates an $[s_1v_k-10,k,s_12^{k-1}-6;5\cdot 2^{k-3}]_2$ AFER-optimal linear code.
		\end{theorem}
		\begin{proof}
			(1)
			According to Lemma \ref{Lem_Belov-type}, when $k_1\ge k_2+2$ or $k_2\ge 3$, the $[s_1v_k-v_{k_1}-v_{k_2},k,s_12^{k-1}-2^{k_1-1}-2^{k_2-1}]_2$ is a SS-type Griesmer code.
			For $A\in [k]$ and $\mathbf{x}\in \mathbb{F}_2^k$, let $\mathbf{x}_{A}$ be a vector obtained from $\mathbf{x}$ by puncturing at the coordinates in $[k]\setminus  A$.
			We put $\mathbf{x}_{A}=\mathbf{0}$ whenever $\mathbf{x}=\mathbf{0}$ or $A=\emptyset$.
			For a multi-set of points $\aleph$ in $PG(k-1,2)$, we define $\sigma_{\aleph}(\mathbf{x})=\mathbf{x} [\aleph]$.

			Since $\Im=\mathcal{P}_{A_1}\bigcup  \mathcal{P}_{A_2}$, we have
			\begin{equation}
				wt(\sigma_{\Im}(\mathbf{x}))= \left\{
				\begin{array}{ll}
					0,                          & \text{ if } \mathbf{x}_{A_1}=\mathbf{0},\mathbf{x}_{A_2}=\mathbf{0};                                     \\
					2^{|A_1|-1} ,               & \text{ if } \mathbf{x}_{A_1}\ne \mathbf{0},\mathbf{x}_{A_2}=\mathbf{0};                                  \\
					2^{|A_2|-1} ,               & \text{ if } \mathbf{x}_{A_1}=\mathbf{0},\mathbf{x}_{A_2}\ne\mathbf{0};                                   \\
					2^{|A_1|-1} +2^{|A_2|-1} ,  & \text{ if } \mathbf{x}_{A_1}\ne\mathbf{0},\mathbf{x}_{A_2}\ne\mathbf{0}, \mathbf{x}_{A_1\bigcap A_2}=\mathbf{0};    \\
					2^{|A_1|-1} +2^{|A_2|-1}  , & \text{ if } \mathbf{x}_{A_1}\ne\mathbf{0},\mathbf{x}_{A_2}\ne\mathbf{0}, \mathbf{x}_{A_1\bigcap A_2}\ne \mathbf{0}.
				\end{array}\right.
			\end{equation}
			Consequently, we have
			\begin{equation}
				\begin{array}{rl}
					e(\Im)=& 2^{k-|A_1|-|A_2|+|A_1\bigcap A_2|}\left(
					2^{|A_1| +| A_2|-2|A_1\bigcap A_2|} \left(2^{|A_1\bigcap A_2|}-1 \right)
					+\left(2^{A_1-|A_1\bigcap A_2|}-1 \right) \left(2^{A_2-|A_1\bigcap A_2|}-1 \right)
					\right)\\
					=& 2^{k-|A_1|-| A_2|}  \left(  2^{|A_1|+|A_2|}+2^{|A_1 \bigcap A_2|}-2^{|A_1|}-2^{|A_2|}\right). \\
					%				=&2^{k}+2^{k-|A_1|-| A_2|}- 2^{k-|A_1|} - 2^{k-|A_2|}
				\end{array}
			\end{equation}

			It follows that $\Im$ has the minimum error coefficient if and only if $|A_1 \bigcap A_2|$ takes the smallest value.
			As $|A_1|+|A_2|-k \le  |A_1 \bigcap A_2| \le |A_2|$ and $|A_1 \bigcap A_2|\ge 0$, the smallest error coefficient of $\Im$ is $2^{k}+2^{k-|A_1|-| A_2|}- 2^{k-|A_1|} - 2^{k-|A_2|}$ for $|A_1|+|A_2|\le k $, and $2^{k}-2^{k-|A_1|} -2^{k-| A_2|}+1$ for $|A_1|+|A_2|> k $.

			(2)
			For $k=4$, the Belov-type linear code with minihyper $\mathcal{P}_{[4]}\setminus \mathcal{P}_{T_4}$ has parameters $[15s_2+5,4,8s_2+2;10]_2$.
			As $C$ is a Griesmer code, by Case 2 of Theorem \ref{Theo_Mix_lower_bound}, $e(15s_2+5,4,2)\ge e_{4s_2+1}(7s_2+3,3,2)+e(14s_2+4,3,2)+1\ge 10$.
			Thus, $C$ is AFER-optimal.


			For $k\ge 5$, since $[s_1v_k-10,k,s_12^{k-1}-6]_2$ linear code $C$ satisfies both Lemmas \ref{Lemma_not_SS_type} and \ref{Lem_Belov-type},  $C$ is an SS or Belov-type code.
			If $C$ is an SS-type linear code, then by the proof of (1), we have $e(C)=21\cdot 2^{k-5}$.
			If $C$ is a Belov-type linear code, the associated minihyper of $C$ is $\mathcal{P}_{[4]}\setminus \mathcal{P}_{T_4}$.
			By Lemma \ref{minihyper_kissing_number}, it follows that $e(C)=5\cdot 2^{k-3}$.
			Since $5\cdot 2^{k-3}<21\cdot 2^{k-5}$, we have (2) also holds.
		\end{proof}


