\section*{Introduction}

Among the few strands of motivation for the material below are the various classification results for maps between matrix spaces preserving spectral and/or algebraic structure, variations of which abound in the literature: \cite{MR2853129,2501.06840v2,GogicPetekTomasevic,MR832991,Petek-HM,Petek-TM,zbMATH01100760,PetekSemrl,MR859735,MR1311919,Semrl2,Semrl} and \emph{their} references will provide a still-small sample. Consider, as one concrete entry point, the main result of \cite{Petek-HM}. Here and throughout the paper we refer to a(n often partial) self-function $M_n\xrightarrow{\phi}M_n$ of the space of $n\times n$ matrices as
\begin{itemize}
\item \emph{commutativity-}(or just \emph{C-})\emph{preserving} if $\phi(X)$ and $\phi(Y)$ commute whenever $X$ and $Y$ to;
\item \emph{spectrum-}(or just \emph{S-})\emph{preserving} if $X$ and $\phi(X)$ have the same spectrum (as a subset of $\bC^n$);

\item and \emph{CS-preserving} if both conditions are met.
\end{itemize}
Denote by $\Ad_g$ the conjugation action $g\cdot g^{-1}$ on a group $\G$ by an element $g\in \G$. \cite[Main theorem]{Petek-HM}, then, says that for positive integers $n\ge 3$ the continuous, CS-preserving self-maps of the (real) algebra $H_n\le M_n:=M_n(\bC)$ of $n\times n$ self-adjoint matrices are precisely those of the form
\begin{itemize}[wide]
\item $\Ad_T (-)^{\bullet}$ for some unitary $T\in \U(n)$ where the symbol $\bullet$ is either blank or `$t$', denoting transposition;
\item or
  \begin{equation}\label{eq:sa.reord.spc}
    X
    \xmapsto{\quad}
    \Ad_T \diag\left(\eta_j(X),\ 1\le j\le n\right)
    ,\quad
    T\in \U(n)
  \end{equation}
  where
  \begin{equation*}
    \eta_1(X)\le \cdots\le \eta_n(X)
  \end{equation*}
  is the non-increasing ordering of the (real) spectrum of $X=X^*$. 
\end{itemize}

The present note is partly concerned with a variant of that result valid for special unitary matrices instead. %To mitigate verbosity, we will frequently abbreviate the phrases `commutativity- (spectrum-)preserving' to \emph{C- (respectively S-)preserving} and the conjunction to \emph{CS-preserving}.

\begin{theoremN}\label{thn:cls.sun}
  Let $n\in \bZ_{\ge 3}$. The continuous CS-preserving maps $\SU(n)\to M_n$ are precisely those of the form
  \begin{enumerate}[(a),wide]
  \item\label{item:thn:cls.sun:cj} $\Ad_T (-)^{\bullet}$ for $\bullet\in \{\text{blank},\ t\}$ and some $T\in \GL(n)$;

  \item\label{item:thn:cls.sun:ord} or
    \begin{equation*}
      \D
      \ni
      X
      \xmapsto{\quad}
      \Ad_T(\lambda_j(X))_j
      \in M_n
      \quad
      \left(\text{some $T\in \GL(n)$}\right),
    \end{equation*}
    where $\lambda_j(X):=\exp(2\pi i x_j)$ for the unique
    \begin{equation*}
      x_1\le x_2\le \cdots\le x_n\le x_1+1
      ,\quad
      \sum_j x_j=0
    \end{equation*}
    for which $\exp(2\pi i x_j)$ constitute the spectrum of $X$.  \qedhere
  \end{enumerate}
\end{theoremN}

Item \Cref{item:thn:cls.sun:ord} in \Cref{thn:cls.sun} (where tuples are meant as the respective diagonal matrices) perhaps requires some unpacking. It follows from \cite[Lemmas 1 and 2]{MR210096}, auxiliary to describing the $n^{th}$ symmetric power
\begin{equation*}
  \left(\bS^1\right)^{[n]}
  :=
  \left(\bS^1\right)^n/S_n
  ,\quad
  S_n:=\text{$n$-symbol permutation group}
\end{equation*}
of the circle, that
\begin{equation}\label{eq:morton.ident}
  \left\{(x_j)\in \bR^n
    \ :\
    \begin{aligned}
      x_1\le x_2\le &\cdots\le x_n\le x_1+1\\
      \sum_j x_j&=0
    \end{aligned}
  \right\}
  \xmapsto[\quad\cong\quad]{\quad}
  \left(\exp 2\pi i x_j\right)_j
\end{equation}
is (after identifying tuples up to permutation) a homeomorphism onto
\begin{equation}\label{eq:tor.sun}
  \left\{(\zeta_j)\in \left(\bS^1\right)^{[n]}\ :\ \prod_j \zeta_j=1\right\}
  \subset
  \left(\bS^1\right)^{[n]}. 
\end{equation}
This, incidentally, is intimately linked to the geometry of \emph{Weyl-group} actions on \emph{maximal tori} \cite[Chapter IV]{btd_lie_1995} of compact Lie groups: \Cref{eq:tor.sun} is the quotient $\T/W$ of that action on the maximal torus
\begin{equation*}
  \T:=\left\{(\zeta_j)\in \left(\bS^1\right)^{n}\ :\ \prod_j \zeta_j=1\right\}
  \le
  \SU(n)
  ,\quad
  W=S_n\text{ acting by permutations},
\end{equation*}
and Morton's homeomorphism \Cref{eq:morton.ident} is an instance of the fact \cite[\S 4.8, Theorem]{hmph_cox} that for a simply-connected, simple compact Lie group $\G$ the respective quotient
\begin{equation*}
  \G/\left(\text{adjoint action}\right)
  \xrightarrow[\quad\cong\quad]{\quad\text{\cite[Proposition IV.2.6]{btd_lie_1995}}\quad}
  \T/W
\end{equation*}
is always identifiable with a simplex in the Lie algebras $Lie(T)$. This is what underlies the continuous \emph{eigenvalue selection}
\begin{equation*}
  \SU(n)\ni X
  \xmapsto{\quad}
  \lambda_1(X)
  \quad
  \left(\text{notation of \Cref{thn:cls.sun}}\right)
\end{equation*}
in \cite[Remark 1.4(3)]{2501.06840v2}, applicable more generally \cite[Theorem A]{2502.08847v1} to simply-connected compact Lie groups. As the preceding discussion makes clear,
\begin{equation*}
    \SU(n)\ni X
    \xmapsto{\quad}
    \left(\lambda_j(X)\right)_{j}
    \in
    \left(\bS^1\right)^n
\end{equation*}
is a continuous spectrum ordering (the title's \emph{spectral selection}). 

\Cref{thn:cls.sun} will in fact recover \cite[Main theorem]{Petek-HM} (in a slightly stronger form: the codomain is all of $M_n$ as opposed to $H_n$)

\begin{theoremN}\label{thn:cls.sa}
  Let $n\in \bZ_{\ge 3}$. The continuous CS-preserving maps $H_n\to M_n$ are precisely those of the form
  \begin{enumerate}[(a),wide]
  \item\label{item:thn:cls.sa:cj} $\Ad_T (-)^{\bullet}$ for $\bullet\in \{\text{blank},\ t\}$ and some $T\in \GL(n)$;

  \item\label{item:thn:cls.sa:ord} or of the form \Cref{eq:sa.reord.spc} for some $T\in \GL(n)$.  \qedhere
  \end{enumerate}
\end{theoremN}

