\section{Circle configuration spaces and special unitary groups}\label{se:sun}

The \emph{configuration space} \cite[p.vii]{fh_config} $\cC^n(\bS^1)$ of $n$-tuples in $\bS^1$ with distinct entries can be thought of as the space of simple-spectrum diagonal unitary matrices. It is not unnatural to pose the analogous problem for the subspace \emph{special} unitary matrices, and to note the distinction between the two cases.

Recall that a group acts \emph{simply transitively} on a set (\emph{sharply 1-transitively} in \cite[Definition post Theorem 9.7]{rot-gp}) if the action is both free and transitive. 

\begin{lemma}\label{le:su.diag.1trans}
  For $n\in \bN$ the action of the symmetric group $S_n$ on
  \begin{equation*}
    \cC^n(\bS^1)_{\Pi=1}
    :=
    \left\{(z_i)\in \cC^n(\bS^1)\ :\ \prod_i z_i=1\right\}
  \end{equation*}
  is simply transitive. 
\end{lemma}
\begin{proof}    
  The discrete group $S_n$ acts freely on the manifold $\cC^n(\bS^1)_{\Pi=1}$, so
  \begin{equation}\label{eq:princ.sn.fib}
    \cC^n(\bS^1)_{\Pi=1}
    \xrightarrowdbl{\quad}
    \cC^n(\bS^1)_{\Pi=1}/S_n
  \end{equation}
  is an \emph{$S_n$-principal covering} in the sense of \cite[\S 14.1]{td_alg-top}. By \cite[Lemmas 1 and 2]{MR210096} the base space $\cC^n(\bS^1)_{\Pi=1}/S_n$ of that covering can be identified with the interior
  \begin{equation*}
    \left\{(x_i)_{i=1}^n\in \bR^n\ :\ \sum_i x_i=0\quad\text{and}\quad x_1<x_2<\cdots<x_n<x_1+1\right\}
  \end{equation*}
  of a simplex, and is thus \emph{contractible} \cite[\S 2.1]{td_alg-top}. It follows \cite[Theorem 14.4.1]{td_alg-top} that the principal fibration \Cref{eq:princ.sn.fib} is trivial:
  \begin{equation*}
    \cC^n(\bS^1)_{\Pi=1}
    \cong
    (\cC^n(\bS^1)_{\Pi=1}/S_n)\times S_n
  \end{equation*}
  as $S_n$-spaces, concluding the proof. 
\end{proof}

The following result is a special unitary version of \cite[Proposition 2.2]{2501.06840v2}. 

\begin{theorem}\label{th:su.tor}
  For $n\in \bZ_{>0}$ a continuous CS-preserving map $\D\xrightarrow{\phi}M_n$ defined on the $n\times n$ diagonal special unitary group $\D\le \SU(n)$ is either
  \begin{enumerate}[(a),wide]
  \item\label{item:th:su.tor:cj} conjugation $\Ad_T$ by some $T\in \GL(n)$;

  \item\label{item:th:su.tor:ord} or
    \begin{equation*}
      \D
      \ni
      X
      \xmapsto{\quad}
      \Ad_T(\lambda_j(X))_j
      \in M_n,
    \end{equation*}
    where $\lambda_j(X):=\exp(2\pi i x_j)$ for the unique
    \begin{equation*}
      x_1\le x_2\le \cdots\le x_n\le x_1+1
      ,\quad
      \sum_j x_j=0
    \end{equation*}
    for which $\exp(2\pi i x_j)$ constitute the spectrum of $X$.
  \end{enumerate}  
\end{theorem}
\begin{proof}
  There is a common core to the present argument and that proving the unitary branch of \cite[Proposition 2.2]{2501.06840v2}. First, there is no loss in assuming $\phi$ takes diagonal values: this is so after composing with a conjugation for simple-spectrum matrices, and hence also generally by continuity. This means that $\phi$ simply permutes diagonal entries:
  \begin{equation*}
    \forall\left(Y=(y_j)_j\in \D\right)
    \exists\left(\tau\in S_n\right)
    \quad:\quad
    \phi(Y)=(y_{\tau j})_j.
  \end{equation*}
  The permutation $\tau$ is constant along (path-)components of $\D$, and uniquely determined for simple-spectrum $Y$. This gives a map
  \begin{equation}\label{eq:comps2sn}
    \pi_0\left(\cC^n(\bS^1)_{\Pi=1}\right)
    \ni
    C
    \xmapsto{\quad}
    \tau_C\in S_n,
  \end{equation}
  and hence also a self-map $\tau_{\bullet}$ on $S_n$ after identifying the domain $\pi_0\left(\cC^n(\bS^1)_{\Pi=1}\right)$ of \Cref{eq:comps2sn} with $S_n$ equivariantly, as allowed by \Cref{le:su.diag.1trans}. For the same reasons as in the proof of \cite[Proposition 2.2]{2501.06840v2}, we have
  \begin{equation}\label{eq:trnsp.lipsch}
    \forall\left(\theta\in S_n\right)
    \forall\left(\text{c-simple transposition }\sigma\in S_n\right)      
    \quad:\quad
    \tau_{\theta\sigma}
    =
    \tau_{\Ad_{\theta}\sigma\cdot \theta}
    \in
    \left\{
      \tau_{\theta}
      ,\
      \Ad_{\theta}\sigma\cdot \tau_{\theta}
    \right\},
  \end{equation}
  where
  \begin{equation*}
    \left\{
      \text{\emph{c-simple} transpositions (`c' for `cyclic')}
    \right\}
    :=
    \left\{
      (1\ 2)
      ,\ 
      (2\ 3)
      ,\ 
      \cdots
      ,\ 
      (n-1\ n)
      ,\ 
      (n\ 1)
    \right\}.
  \end{equation*}  
  By \Cref{pr:chartaus} $\tau_{\bullet}$ is either constant or right translation by some element of $S_n$; the two options respectively corresponding to those of the statement, the proof is complete.
\end{proof}

Note also the parallels to the description of continuous CS-preserving self-maps of the space $H_n$ of Hermitian $n\times n$ matrices in \cite[Main theorem]{Petek-HM}. The immediately-guessable Hermitian analogue of \Cref{th:su.tor}, however, does \emph{not} hold: \Cref{ex:herm.hyb} below provides a continuous self-map of the diagonal Hermitian matrices which is neither a conjugation $\Ad_T$, $T\in \GL(n)$ nor of the form
\begin{equation*}
  X
  \xmapsto{\quad}
  \Ad_T(\lambda_j(X))_j
  \in M_n,
\end{equation*}
for the non-decreasing enumeration
\begin{equation*}
  \lambda_1(X)\le \lambda_2(X)\le \cdots\le \lambda_n(X)
\end{equation*}
of the spectrum of $X$.  

\begin{example}\label{ex:herm.hyb}
  We describe a self-map of the space $H_{n,d}$ of diagonal $n\times n$ Hermitian matrices (i.e. diagonal and real) for $n=3$ (the `$d$' subscript is for `diagonal'). We employ the notation
  \begin{equation*}
    [c\ a\ b]
    :=
    \begin{pmatrix}
      c&0&0\\
      0&a&0\\
      0&0&b
    \end{pmatrix}
    ,\quad \left(a\le b\le c\right)\subset \bR.
  \end{equation*}
  With those conventions, the map in question will be
  \begin{alignat*}{2}
    [a\ b\ c]&\xmapsto{\quad}[a\ b\ c]
               ,\quad
               [a\ c\ b]&\xmapsto{\quad} [a\ c\ b]\\
    [b\ a\ c]&\xmapsto{\quad}[a\ b\ c]
               ,\quad
               [b\ c\ a]&\xmapsto{\quad} [a\ c\ b]\\
    [c\ a\ b]&\xmapsto{\quad}[a\ b\ c]
               ,\quad
               [c\ b\ a]&\xmapsto{\quad} [a\ b\ c]\\
  \end{alignat*}
  The (easily checked) claim is that this is indeed a well-defined continuous self-map of $H_{3,d}$: there are compatibility constraints for the cases $a=b$ or $b=c$ (or both), and all such hold. 
\end{example}

