\begin{remark}\label{re:need.cyc}
  It was crucial, in \Cref{pr:chartaus}, that the transpositions $\sigma$ of \Cref{eq:trnsp.lipsch} range over the full contingent of $n$ c-simples: only the generators $(j\ j+1)$, $1\le j\le n-1$ of $S_n$ would not have sufficed, per \Cref{ex:just.n1}. 
\end{remark}

\begin{example}\label{ex:just.n1}
  The following self-map of $S_3$ is neither a right translation nor constant, but nevertheless satisfies \Cref{eq:trnsp.lipsch} with $\sigma$ ranging only over the two generators $(1\ 2)$ and $(2\ 3)$ of $S_3$. 
  \begin{equation*}
    \emptyset,\ (2\ 3)\xmapsto{\quad}\emptyset
    ,\quad
    (1\ 2)\xmapsto{\quad}(1\ 2)
    ,\quad
    (1\ 3),\ (1\ 3\ 2)\xmapsto{\quad}(1\ 3)
    ,\quad
    (1\ 2\ 3)\xmapsto{\quad}(1\ 2\ 3),
  \end{equation*}
  where `$\emptyset$' stands for the identity of $S_n$ in order to avoid confusion between it and the symbol `1' in cycle-decomposition notation.
\end{example}

\Cref{le:dichot} below is a preliminary remark moving us closer to eventually proving \Cref{thn:cls.sun}. Some terminology will help streamline the statement.

\begin{definition}\label{def:dichot.diag}
  Let $\T\le \SU(n)$ be a maximal torus and $\T\xrightarrow{\phi}M_n$ a continuous map preserving both spectra and commutativity, falling into one of two qualitatively distinct types by \Cref{th:su.tor}. 

  We say that $\phi$ \emph{reorders} (or \emph{is a reordering}) if it is of type \Cref{item:th:su.tor:ord} and \emph{conjugates} (or simply \emph{is a conjugation}) if it is of type \Cref{item:th:su.tor:cj} instead. 
\end{definition}

\begin{lemma}\label{le:dichot}
  The restrictions of continuous CS-preserving map $\SU(n)\to M_n$ to maximal tori either all conjugate or all reorder in the sense of \Cref{def:dichot.diag}.
\end{lemma}
\begin{proof}
  Maximal tori being mutually conjugate \cite[Theorem IV.1.6]{btd_lie_1995}, they constitute the connected space $\cT\left(\SU(n)\right)\cong \SU(n)/N(\T)$ (with $N(\bullet)$ denoting normalizers) for any fixed maximal torus $\T$. To conclude, observe that
  \begin{equation*}
    \cT(\SU(n))
    =
    \left\{\T\ :\ \phi|_{\T}\text{ conjugates}\right\}
    \sqcup
    \left\{\T\ :\ \phi|_{\T}\text{ reorders}\right\}
  \end{equation*}
  is a disjoint union into closed subsets (so that one must be empty by connectedness). Indeed, the continuity of $\phi$ makes both the conjugation and reordering conditions closed:
  \begin{itemize}[wide]
  \item conjugation can be expressed (for continuous maps already known to preserve commutativity and spectra) as $\phi|_{\T}$ being a group morphism;

  \item while reordering can be phrased as constancy of $\phi|_{\T}$ along Weyl-group orbits.
  \end{itemize}
\end{proof}

