Some notation extending that introduced in \Cref{thn:cls.sun} will help with the latter's proof.

\begin{notation}\label{not:eigs}
  Recall the $\lambda_j(X)$ of \Cref{thn:cls.sun}. More generally:
  \begin{equation*}
    \forall\left(S\subseteq [n]\right)
    \forall(X\in \SU(n))
    \quad:\quad
    \lambda_S(X)
    :=
    \text{multiset }
    \left\{\lambda_j(X)\ :\ j\in S\right\}.
  \end{equation*}
  Also:
  \begin{equation*}
    \forall\left(S\subseteq [n]\right)
    \quad:\quad    
    E_S(X):=\sum_{j\in S}\left(\text{$\lambda_j$-eigenspace of $X$}\right).
  \end{equation*}
  Note that $\dim E_S(X)\ge |S|$, with equality whenever $\lambda_S(X)$ and $\lambda_{[n]\setminus S}(X)$ are disjoint, which situation we reference by calling $U$ \emph{$S$-isolated}.

  We similarly write
  \begin{equation*}
    \forall\left(\Lambda\subseteq \bC\right)
    \forall\left(T\in M_n\right)
    \quad:\quad
    E_{\Lambda}(T):=\sum_{\lambda\in \Lambda}\left(\text{$\lambda$-eigenspace of $T$}\right),
  \end{equation*}
  so that $E_S(X)=E_{\lambda_S(X)}(X)$ for $X\in \SU(n)$. 
\end{notation}

We also write
\begin{equation*}
  \bG(d,V)
  :=
  \left\{\text{$d$-dimensional subspaces of }V\right\}
  ,\quad
  \bG(V)\left(\text{or }\bG V\right):=\bigcup_d \bG(d,V)
\end{equation*}
for the various \emph{Grassmannians} (\cite[Example 1.36]{lee2013introduction}, \cite[Example 1.1.3]{ww_twst}) of a finite-dimensional (mostly complex) vector space $V$. 

We record the following observation, but omit the routine proof (cf. its parallel \cite[Lemma 2.3]{2501.06840v2}). 

\begin{lemma}\label{le:def.grs.crsp}
  Let $n\in \bZ_{\ge 1}$ and $\SU(n)\xrightarrow{\phi}M_n$ be a continuous commutativity- and spectrum-preserving map. Fix also subsets $S,S'\subseteq [n]$. 

  The correspondence
  \begin{equation}\label{eq:psi.corresp}
    \bG(|S|,\bC^n)
    \ni
    W=E_S(U)
    \xmapsto[\quad\text{some $S$- and $S'$-isolated }U\in \SU(n)\quad]{\quad\Psi_{S\to S'}=\Psi_{\phi,S\to S'}\quad}
    E_{\lambda_{S'}(U)}(\phi U)
    \in
    \bG(|S'|,\bC^n)
  \end{equation}
  is a well-defined continuous map, independent of the choice of $S$- and $S'$-isolated $U\in \SU(n)$ in the sense of \Cref{not:eigs}.  \qedhere
\end{lemma}
Notational abbreviations include $\Psi_S:= \Psi_{S\to S'}$ and omitting braces for singletons, as in $\Psi_{j\to j'}$ or $\Psi_j$.

We next dispose of the arguably less interesting (not-quite) half of \Cref{thn:cls.sun}.

\begin{proposition}\label{pr:thn:cls.sun:ord}
  Let $n\in \bZ_{\ge 3}$ and $\SU(n)\xrightarrow{\phi}M_n$ be a continuous spectrum- and commutativity-preserving map.

  If $\phi|_{\T}$ reorders for at least one maximal torus $\T\le \SU(n)$ then it is of the type listed as \Cref{item:thn:cls.sun:ord} in \Cref{thn:cls.sun}. 
\end{proposition}
\begin{proof}

