\section{Lipschitz self-maps of Coxeter groups}\label{se:cox.lip}

It might be of some interest to observe that \Cref{pr:chartaus} is an instance of a wider pattern, to be further examined in \Cref{th:cox.lip}: the latter applies to \emph{Coxeter systems} \cite[p.2]{bb_comb-cox} $(W,S)$ and their underlying \emph{Coxeter groups}, $W$, with $S_n$ realized as one such as usual, via \cite[Example 1.2.3]{bb_comb-cox}: the system $S\subseteq S_n$ of generators is
\begin{equation*}
  S
  :=
  \left\{(i\ i+1)\ :\ 1\le i\le n-1\right\}. 
\end{equation*}
For background on Coxeter groups we refer the reader to standard sources such as \cite{bb_comb-cox,hmph_cox}, with more specific citations where needed. The following piece of vocabulary is meant as reminiscent of the \emph{Lipschitz} maps ubiquitous \cite[\S 1.4]{bbi} in metric geometry, providing shorthand for \Cref{eq:trnsp.lipsch}.

\begin{definition}\label{def:s.lip}
  Let $W$ be a group and $W'\xrightarrow{\phi}2^W$ a partial function for $W'\subseteq W$.

  A self-map $\tau_{\bullet}\in W^W$ is \emph{(right-)$\phi$-Lipschitz} if
  \begin{equation}\label{eq:phi.lip}
    \forall\left(\theta\in W'\right)
    \forall\left(\sigma\in \phi(\theta)\right)      
    \quad:\quad
    \tau_{\sigma\theta}\in \left\{\tau_{\theta},\ \sigma\tau_{\theta}\right\}.
  \end{equation}
  When $\phi$ takes a constant value $T\in 2^W$ we refer to $\tau$ as \emph{(right-)$T$-Lipschitz}. Explicitly:
    \begin{equation}\label{eq:tlip}
      \forall\left(\theta\in W\right)
      \forall\left(\sigma\in T\right)      
      \quad:\quad
      \tau_{\sigma\theta}\in \left\{\tau_{\theta},\ \sigma\tau_{\theta}\right\}.
    \end{equation}
    We will mostly be interested in the case when $(W,S)$ is a Coxeter system and $\phi$ takes values in its set $\Ad_W S$ of \emph{reflections} \cite[\S 1.3, p.12]{bb_comb-cox}.
\end{definition}

\begin{remarks}\label{res:runif}
  \begin{enumerate}[(1),wide]
  \item\label{item:res:runif:1lip.brh} It follows from \cite[Theorem 2.2.2]{bb_comb-cox} that for a Coxeter system $(W,S)$ the $S$-Lipschitz condition means precisely that
    \begin{equation*}
      \forall\left(\theta,\eta\in W\right)
      \quad:\quad
      \tau_{\theta\eta^{-1}}\le \theta\eta^{-1}
    \end{equation*}
    for the \emph{Bruhat order} \cite[Deﬁnition 2.1.1]{bb_comb-cox} on $(W,S)$. This is, in other words, the requirement that $\tau$ be \emph{contractive} (i.e. distance non-increasing, or \emph{1-Lipschitz} in the language of \cite[Definition 1.1]{grm_mtr-struct}, say) with respect to a poset-valued distance. 

  \item\label{item:res:runif:why.rght} \Cref{def:s.lip} speaks of the \emph{right}-handed Lipschitz property because plainly, condition \Cref{eq:tlip} is invariant under right translation on $W$.
  \end{enumerate}
\end{remarks}

The following observation is immediate.

\begin{lemma}\label{le:mon}
  If $\tau_i\in W^W$, $i=0,1$ are $\phi_i$-Lipschitz respectively, then $\tau_1\circ \tau_0$ is $\phi$-Lipschitz for
  \begin{equation*}
    \left\{w\in \mathrm{dom}~\phi_0\ :\ \phi_0(w)\subseteq \phi_1\left(\tau_w\right)\right\}
    \ni w
    \xmapsto{\quad\phi\quad}
    \phi_0(w).
  \end{equation*}
  In particular, $T$-Lipschitz self-maps constitute a monoid for any $T\subseteq W$.  \qedhere
\end{lemma}

%\newpage

We call a Coxeter system $(W,S)$ (or, slightly loosely, the underlying group) as \emph{finitary} if the Coxeter graph contains no edges labeled `$\infty$'. 

\begin{theorem}\label{th:cox.lip}
  Let $(W,S)$ be a finitary Coxeter system and $T$ its set of reflections. The right $T$-Lipschitz self-maps $\tau\in W^W$ are precisely those of the form
  \begin{equation}\label{eq:pi.iota.trnsl}
    \left(\cdot w\right) \circ \iota_{(J_i)}\circ\pi_{(J_i)}
    ,\quad
    w\in W
  \end{equation}
  where
  \begin{itemize}[wide]
  \item $(J_i)_{i}$ is a tuple of subsets $J_i\subset S$, each consisting of the vertices of a connected component of the \emph{Coxeter graph} \cite[\S 1.1, p.1]{bb_comb-cox} of $(W,S)$;

  \item we denote the corresponding projection and respectively inclusion by
    \begin{equation*}
      W\xrightarrowdbl{\quad\pi_{(J_i)}\quad}\prod_i W_{J_i}
      \quad\text{and}\quad
      \prod_i W_{J_i}\lhook\joinrel\xrightarrowdbl{\quad\iota_{(J_i)}\quad} W;
    \end{equation*}

  \item and $\left(\cdot w\right)$ is right translation by some $w\in W$. 
  \end{itemize}
\end{theorem}

\begin{remark}\label{re:red.conn}
  The maps of the form \Cref{eq:pi.iota.trnsl} plainly constitute a monoid, contained in that (\Cref{le:mon}) of all $T$-Lipschitz maps. To prove the opposite inclusion it will thus suffice, upon precomposing an arbitrary $T$-Lipschitz map $\tau$ with right translation by $\tau_1^{-1}$ and restricting attention to individual connected components of the Coxeter graph, to argue that
  \begin{equation}\label{eq:ws.conn}
    \left((W,S)\text{ connected }\ \text{and}\ \tau_1=1\right)
    \quad
    \xRightarrow{\quad}
    \quad
    \tau_{\bullet}\in \left\{\id,\ 1\right\}.
  \end{equation}
  It is in the form \Cref{eq:ws.conn} that we address the claim, after some preparation.  
\end{remark}

Short of being trivial, the simplest examples of Coxeter systems are the \emph{dihedral groups} $I_2(m)$, $m\in \bZ_{\ge 2}\sqcup\{\infty\}$ of \cite[Example 1.2.7]{bb_comb-cox}:
\begin{equation*}
  I_2(m):=\braket{r_i,\ i=1,2}/\left(r_i^2=1,\ (r_1r_2)^m=1\right)  
\end{equation*}
with the last relation empty for $m=\infty$. The corresponding Coxeter graph is connected for all $m\ge 3$. 

\begin{lemma}\label{le:fin.dih}
  \Cref{th:cox.lip} holds for the finite dihedral groups $I_2(m)$, $m\in \bZ_{\ge 3}$. 
\end{lemma}
\begin{proof}
  We prove the claim in the form of \Cref{eq:ws.conn}, noting that in this case the Coxeter graph \emph{is} connected. The even- and odd-$m$ cases are slightly different, the chief distinction lying in the fact that in the former case the \emph{longest element} \cite[Proposition 2.3.1]{bb_comb-cox}
  \begin{equation*}
    w_0
    :=
    \underbracket{\ r_1r_2\cdots r_1r_2\ }_{\text{$m$ letters}}
    =
    \underbracket{\ r_2r_1\cdots r_2r_1\ }_{\text{$m$ letters}}
  \end{equation*}
  is \emph{not} a reflection (i.e. a conjugate of some $r_i$). We treat only the (slightly more laborious) even branch, leaving the other to the reader.

  As just noted, $w_0$ is not a reflection. The products $r_i w_0$, however, both are. Per the $T$-Lipschitz condition, $\tau_{r_i w_0}\in \left\{1,\ r_i w_0\right\}$ respectively for $i=1,2$. Because furthermore
  \begin{equation*}
    \tau_{w_0}=\tau_{r_i^2 w_0}
    \in
    \left\{\tau_{r_i w_0},\ r_i \tau_{r_i w_0}\right\}
    ,\quad i=1,2,
  \end{equation*}
  we have either
  \begin{equation*}
    \left(
      \tau_{r_i w_0}=1=\tau_{w_0}
      ,\ i=1,2
    \right)
    \quad\text{or}\quad
    \left(
      \tau_{r_i w_0}=r_i w_0
      \quad\text{and}\quad\tau_{w_0}=w_0
    \right).
  \end{equation*}
  In the latter case $\tau=\id$ (via the $S$-Lipschitz condition) by simply noting that every element of $I_2(m)$ appears as a right-hand segment of $w_0$. In the former situation, note first that odd-length alternating words in $r_i$ are also annihilated by $\tau$, inductively on length: if $\tau_{r_i (r_j r_i)^k}=1$ ($2k+3\le m$) then the one hand
  \begin{equation*}
    \tau_{r_i (r_j r_i)^{k+1}}
    \in \left\{1,\ r_i (r_j r_i)^{k+1}\right\}
    \quad
    \left(\text{$T$-Lipschitz property}\right)
  \end{equation*}
  while on the other
  \begin{equation*}
    \tau_{r_i (r_j r_i)^{k+1}}
    \in
    \left\{
      1,\ r_i,\ r_j,\ r_i r_j
    \right\},
  \end{equation*}
  forcing the first option $\tau_{r_i (r_j r_i)^{k+1}}=1$. But then
  \begin{equation*}
    \tau_{r_i (r_j r_i)^{k+1}}
    \in
    \left\{
      \tau_{(r_j r_i)^{k+1}}
      ,\
      r_i\tau_{(r_j r_i)^{k+1}}
    \right\}
  \end{equation*}
  implies
  \begin{equation*}
    \tau_{(r_j r_i)^{k+1}}
    \in
    \left\{1,\ r_i\right\},
  \end{equation*}
  with 1 being the only possibility due to 

  \begin{equation*}
    \tau_{(r_j r_i)^{k+1}}
    \in
    \left\{
      \tau_{r_i(r_j r_i)^{k}}
      ,\
      r_j\tau_{r_i(r_j r_i)^{k}}
    \right\}
    =
    \left\{1,\ r_j\right\}.
  \end{equation*}
\end{proof}

\begin{remark}\label{re:s.lip.only}
  It is not unnatural at this stage to ask whether (vagaries of the proof notwithstanding) \Cref{le:fin.dih} goes through for $S$- (rather than $T$-)Lipschitz maps. It does not: for any $m\in \bZ_{\ge 3}$ the self-map of $W:=I_2(m)=\Braket{r_1,r_2}$ removing, for every $w\in W$, the terminal $r_2$ letter in a \emph{reduced expression} \cite[\S 1.4]{bb_comb-cox} for $w$ if one such exists will be $S$-Lipschitz, fixing $r_1$ and annihilating $r_2$.

  For $m=3$, say, this is the unique $S$-Lipschitz map acting as
  \begin{equation*}
    w_0=
    r_1r_2r_1=r_2 r_1 r_2
    \xmapsto{\quad}
    r_2 r_1
  \end{equation*}
  on the longest element (its other values are then easily filled in).

  %This same gadget functions rather generally: \Cref{le:rm.trail}.
  This same gadget functions rather generally: \Cref{ex:fold}.
\end{remark}

\begin{example}\label{ex:fold}
  Consider any Coxeter system $(W,S)$ and declare elements $w,w'\in W$ \emph{$s$-adjacent}, $s\in S$ if $w'=sw$ (reversing the convention of \cite[p.10]{ron_build_2e_2009} for \emph{Coxeter complexes}, in other words). Every reflection $t\in T:=\Ad_WS$ determines a \emph{root} $\alpha_T\ni 1$ \cite[Proposition 2.6]{ron_build_2e_2009}, and the \emph{folding} map $W\to \alpha_T$ of \cite[p.15]{ron_build_2e_2009} is clearly 1-Lipschitz with respect to the Bruhat order and hence (\Cref{res:runif}\Cref{item:res:runif:1lip.brh}) $S$-Lipschitz.

  A more concrete description of such a map would be
  \begin{equation*}
    \tau_w
    :=
    \begin{cases}
      ws&\text{if $\exists$ reduced $w=s_1\cdots s_{k-1} s$}\\
      w&\text{otherwise}
    \end{cases}
    ;
  \end{equation*}
  that this is precisely the folding corresponding to $t:=s\in S$ follows from \cite[Corollary 1.4.6]{bb_comb-cox} and the characterization of roots given in \cite[Proposition 2.6(ii)]{ron_build_2e_2009}.
\end{example}

