\pf{th:cox.lip}
\begin{th:cox.lip}
  Per \Cref{re:red.conn}, assume that $(W,S)$ connected and $\tau_1=1$. 

  \begin{enumerate}[(I),wide]


  \item\label{item:th:cox.lip:tau.on.s} \textbf{: $\tau|_S\in \left\{\id_S,\ 1\right\}.$} Or: either $\tau_s=s$ for all $s\in S$, or $\tau_s=1$ for all $s\in S$. This follows from \Cref{le:fin.dih}: any two generators $s,s'\in S$, if connected in the (finitary!) Coxeter graph of $(W,S)$, generate a finite dihedral group $I_2(m)$, $m\in \bZ_{\ge 3}$. This means that they are simultaneously left invariant or sent to $1$ by $\tau_{\bullet}$. Because we are assuming Coxeter-graph connectedness, any two generators can be linked by a path.    

  \item\label{item:th:cox.lip:ww.id.s} \textbf{: If $\tau_w=w$ for some $w\ne 1$ then $\tau|_S=\id|_S$.} If $w=s_1\cdots s_k$ is a reduced expression for $w$, then $k\ge 1$ because $w\ne 1$. The $S$-Lipschitz property implies that
    \begin{equation*}
      \tau_{s_i\cdots s_k}=s_i\cdots s_k
      ,\quad
      \forall 1\le i\le k,
    \end{equation*}
    so in particular $\tau_{s_k}=s_k$. We then have $\tau_s=s$ for all $s\in S$ by step \Cref{item:th:cox.lip:tau.on.s}. 

  \item\label{item:th:cox.lip:if.id.then.id} \textbf{: If $\tau_y=y$ for some $y\ne 1$ then $\tau=\id$.} We already know from \Cref{item:th:cox.lip:ww.id.s} that $\tau|_S=\id_S$. Let $k\ge 2$ be the minimal \emph{length} \cite[\S 1.4]{bb_comb-cox} of an element with $\tau_w\ne w$ and $w=s_1\cdots s_k$ a reduced expression for such a word. We then have
    \begin{equation*}
      \tau_w=x:=s_2\cdots s_k,
    \end{equation*}
    and switch focus to the (again $T$-Lipschitz) map
    \begin{equation*}
      \tau'_{\bullet}:= (\cdot x^{-1})\circ\tau_{\bullet}\circ (\cdot x).
    \end{equation*}
    We have $\tau_x=x$ and hence $\tau'_1=1$, and also $\tau'_{s_1}=1$. Step \Cref{item:th:cox.lip:ww.id.s} applied to $\tau'$ yields $\tau'_{s}=1$ for \emph{all} $s\in S$, and in particular for $s_2$. But then
    \begin{equation*}
      \tau'_{s_2}=1
      \xRightarrow{\quad}
      \tau_{s_3\cdots s_k}=\tau_{s_2s_2s_3\cdots s_k}=\tau'_{s_2}\cdot s_2\cdots s_k=s_2\cdots s_k,
    \end{equation*}
    contradicting the minimality of $k$ for the length of an element on which $\tau_{\bullet}$ is not identical. The contradiction proves that there are no $w$ with $\tau_w\ne w$, and we are done.

  \item \textbf{: If $\tau_y=1$ for some $y\ne 1$ then $\tau=1$.} We at least have $\tau|_S=1$ by the preceding step \Cref{item:th:cox.lip:if.id.then.id}, so we again proceed by induction, in similar fashion: suppose $w=s_1\cdots s_k$ is a minimal-length element on which $\tau$ is not $1$, so that by the $S$-Lipschitz property we have $\tau_w=s_1$. This time set
    \begin{equation*}
      \tau'_{\bullet}:= \tau_{\bullet}\circ (\cdot s_2\cdots s_k)
      \quad
      \left(\text{again $T$-Lipschitz}\right).
    \end{equation*}


    The sequel is much as before: $\tau'_1=1$ and $\tau'_{s_1}=s_1$, so that $\tau'=\id$ by \Cref{item:th:cox.lip:if.id.then.id}; this contradicts
    \begin{equation*}
      \tau'_{s_2}=\tau_{s_2s_2s_3\cdots s_k}=\tau_{s_3\cdots s_k}=1
    \end{equation*}
    and concludes the proof.  \qedhere
  \end{enumerate}
\end{th:cox.lip}

