\begin{proof}[Proof of Theorem~\ref{energyminthm}]
The $p > n$ case is proven in~\cite{ball}. Let $\{f_k\} \subset \mathcal{A}^n_{\phi}$ be a minimizing sequence. By lemma~\ref{wlsc}, $E[f] < \infty$ so $J_f > 0$ a.e. 

The remaining properties follow from Lemma~\ref{wlsc}, and the following chain of inequalities completes the proof.
\[\inf_{f \in \mathcal{A}^p_{\phi}} E[f] \le E[f_0] \le \liminf_{k_j \to \infty} E[f_{k_j}] =\inf_{f \in \mathcal{A}^p_{\phi}} E[f] \]
\end{proof}
\section{Examples}\label{examples}
 \begin{example}\label{ex-ctyonto}
    Let $\mathbb D$ be the unit disk in $\mathbb C$ and define a sequence of disjoint balls $B_k$ ($k=1, 2, \dots) $ with centers $\omega_k : = 1 -\frac{1}{k}$ and radii $2s_k$ where $s_k := 10^{-k}$. On each $B_k$, define 
    \[G_k(\omega_k + re^{i\theta}) = \begin{cases} \omega_k + 2(r-s_k)e^{i\theta} & s_k \le r \le 2s_k \\ \omega_k + \frac{\log(s_k/r)}{k^4} & s_ke^{-k^{4}} < r < s_k \\ \omega_k + 2 & r \le s_ke^{-k^{4}}
    \end{cases}\]

    We claim the map $G: \overline{\mathbb D} \to \overline{\mathbb C}$ 

    \[G(z) = \begin{cases} G_k(z) & z \in B_k, k=1, 2, \dots \\ z & \text{otherwise}
    \end{cases}\]
is not surjective nor can it be extended continuously to $S^1(0)$ when we allow the Jacobian to be 0 on a set of positive measure. 
First, observe that 
\begin{align*}
    \|G\|_{W^{1,2}(\mathbb D, \mathbb C)} &\le C + \sum_{k=1}^\infty \|DG_k(z)\|_{L^2(B_k)} \\ &\le C + \sum_{k=1}^{\infty } \sqrt{C_1 10^{-2k} + \frac{8\pi}{k^4}} \\ &\le C+C_2 \sum_{k=1}^\infty \left(10^{-k} + \frac{1}{k^2}\right) < \infty
\end{align*}
so $G \in W^{1,2}(\mathbb D, \mathbb C)$ and moreover, since $\displaystyle \lim_{x \to \omega} G(z) = \omega $ for all $\omega \in \partial \mathbb D \setminus \{1\}$, the trace of $G$ on the boundary must also equal the identity mapping. Thus, $G - \text{id} \in W^{1,2}_0 (\mathbb D, \mathbb C)$. 


    The mapping is clearly continuous on $\mathbb D$ but since $G$ maps the centers $w_k$ of each $B_k$ to $w_k + 2$, which has real part larger than 2, it fails to be continuous up to the boundary. Additionally, since $G(\mathbb D) \setminus \overline{ \mathbb D} \neq \emptyset$, $G$ is not a surjective map. 
\end{example}
\begin{example}\label{ex-ctybdry}
    Let $\mathbb D$ again be the unit disk in $\mathbb C$ and define $G:\overline{\mathbb D} \to \overline{\mathbb D} $ as 
\[G(re^{i\theta}) = \begin{cases} 2(r-1/2)e^{i\theta} & 1/2 \le r \le 1 \\ 1-2r & r < 1/2
\end{cases}\]
Observe that $G$ is the identity on the boundary and $J_G \ge 0$ a.e. However, for any point $z \in (0,1) \times \{0\}$, $G^{-1}(z)$ is the union of a single point in $ \mathbb D \setminus \overline{B(0,1/2)} $ and a circle of radius $r_0 \in (0, 1/2)$, causing monotonicity to fail.
\end{example}
\begin{example}\label{mtexample}
    Consider the rectangle $R = \{(x,y) \in \mathbb R^2 : |x| \le 1, |y| \le 2\}$. Define $H: R \to \mathbb R^2$ 
    \[ H(x_1, x_2) = \begin{cases}
        (x_1, |x_1|x_2) & |x_2|\le 1 \\ (x_1, [2(|x_2|-1)+(2-|x_2|)|x_1|]\sgn(x_2) & 1 < |x_2| \le 2
    \end{cases}\]
    Despite having an almost everywhere positive Jacobian and being the identity on the boundary $\partial R$, $H$ is not injective.
\end{example}

