\begin{equation}
\mathbf{x}^{(4)} \in \argminA_{\mathbf{x}^{(4)} \in \mathbb{R}^{N}_{\geq 0}} \norm{\mathbf{C} - \mathbf{A} \, \text{diag}(\mathbf{x}^{(4)}) \, \mathbf{A}^H}_2^2 %+ \gamma \|\mathbf{x}\|_1
