\title{\textbf{A contemporary approach on revisited cost allocation using airport games: the effects of code-sharing}}

\author{Alejandro Saavedra-Nieves$^1$, M. Gloria Fiestras-Janeiro$^2$}


\date{\footnotesize \emph{
		$^1$ \underline{Corresponding author}. CITMAga. Departamento de Estat{\'i}stica, An{\'a}lise Matem{\'a}tica y Optimizaci{\'o}n, Universidade de Santiago de Compostela. \texttt{alejandro.saavedra.nieves@usc.es}\\
