\section{Proofs}

Below, we prove that the configuration value for airport games particularly satisfy such property.
\begin{proposition}\label{BCCCairports}
    Let $(N,c,\mathcal{B})$ be an airport game with coalition configuration. Thus, the configuration value for airport games satisfies (BC-CC).
\end{proposition}
\begin{proof}
To prove this, take $i,j\in N$ that corresponds to two movements of airplanes that are operated strictly by the same set of airlines, that is satisfying that $\mathcal{B}^i=\mathcal{B}^j$ or equivalently that $\bar{a}(i)=\bar{a}(j)$. Without loss of generality, we assume that $\tau(i)<\tau(j)$. Thus, using Theorem \ref{theoremCV}, we have that
\begin{equation*}
	CV_{\bar{a}(k),\tau(k)}(N,c,\mathcal{B})=\sum_{a\in \bar{a}(k)}\sum_{t=1}^{\tau(k)}\frac{c_{t}-c_{t-1}}{{|\mathcal{A}_{\geq t}|}{|N^{a}_{\geq t}|}}
	\end{equation*}
for $k\in \{i,j\}$, and that
\begin{equation*}
	CV_{\bar{a}(i),\tau(i)}(N,c,\mathcal{B}_{-j})=\sum_{a\in \bar{a}(i)}\sum_{t=1}^{\tau(i)}\frac{c_{t}-c_{t-1}}{{(|\mathcal{A}_{\geq t}|+1)}{(|N^{a}_{\geq t}|+1)}}
	\end{equation*}
and 
\begin{equation*}
	CV_{\bar{a}(j),\tau(j)}(N,c,\mathcal{B}_{-i})=\sum_{a\in \bar{a}(i)}\sum_{t=1}^{\tau(i)}\frac{c_{t}-c_{t-1}}{{(|\mathcal{A}_{\geq t}|+1)}{(|N^{a}_{\geq t}|+1)}}+\sum_{a\in \bar{a}(i)}\sum_{t=\tau(i)+1}^{\tau(j)}\frac{c_{t}-c_{t-1}}{{|\mathcal{A}_{\geq t}|}{|N^{a}_{\geq t}|}}.
	\end{equation*}
Thus, it clearly holds that
\[CV_{\bar{a}(i),\tau(i)}(N,c,\mathcal{B})-CV_{\bar{a}(i),\tau(i)}(N,c,\mathcal{B}_{-j})=CV_{\bar{a}(j),\tau(j)}(N,c,\mathcal{B})-CV_{\bar{a}(j),\tau(j)}(N,c,\mathcal{B}_{-i}),\]
concluding the proof.
\end{proof}

