\title{MalVol-25: A Diverse, Labelled and Detailed Volatile Memory Dataset for Malware Detection and Response Testing and Validation}

\author{Dipo~Dunsin*, Mohamed~Chahine~Ghanem, Eduardo Almeida Palmieri
