\subsection{Upper bounds on topological complexities.} In the next results, a subset $\mathcal{S}\subseteq \mathcal{P}(\omega)$ is said to be \emph{hereditary} if $A \in \mathcal{S}$ and $B\subseteq A$ implies $B \in \mathcal{S}$. 


\begin{prop}\label{prop:maintooltopological}
Let $T: X\to X$ be a continuous function, where $X$ is a second countable topological space. 
Let also $\mathcal{F}\subseteq \mathcal{P}(\omega)$ be a hereditary closed set. Then 
$$
\left\{x \in X: \{n \in \omega: T^n x \in U\}\notin \mathcal{F}
\text{ for all nonempty open }U\subseteq X
\right\}
$$
%for all nonempty open $U\subseteq X$ 
is a $G_\delta$-set. 
%for each open $U\subseteq X$.  
\end{prop}
\begin{proof}
%[Proof of Proposition \ref{prop:maintooltopological}]
    Fix a nonempty open $U\subseteq X$, set 
    $
    Y_U:=\left\{x \in X: \{n \in \omega: T^n x \in U\}\notin \mathcal{F}\right\},
    $ 
    and define $\mathcal{G}:=\mathcal{P}(\omega)\setminus \mathcal{F}$. Since $\mathcal{F}$ is hereditary closed, $\mathcal{G}$ is open and
    $$
    \forall A,B\subseteq \omega, \quad 
    (A\subseteq B \text{ and }A \in \mathcal{G}) \implies B \in \mathcal{G}.
    $$
    Let $(\mathcal{G}_k: k \in \omega)$ be a sequence of basic clopen sets of $\mathcal{P}(\omega)$ such that $\mathcal{G}=\bigcup_k \mathcal{G}_k$. For each $k \in \omega$, there exists $F_k \in \mathrm{Fin}$ such that $\mathcal{G}_k=\{S\subseteq \omega: S \cap [0,\max F_k]=F_k\}$. Accordingly, define the open set 
    $
    \widehat{\mathcal{G}}_k:=\{S\subseteq \omega: F_k\subseteq S \cap [0,\max F_k]\}. 
    $ 
    Then, it is routine to check that $\mathcal{G}=\bigcup_k  \widehat{\mathcal{G}}_k$. At this point, notice that
    $$
    Y_U=\bigcup_{k\in \omega}Y_{k}, 
    \quad \text{ where}\quad 
    Y_{k}:=\left\{x \in X: \{n \in \omega: T^n x \in U\}\in \widehat{\mathcal{G}}_k\right\}. 
    $$
    Now, it is easy to check that each $Y_{k}$ is open: suppose that we can pick $x \in Y_k$. Then $T^nx \in U$ for all $n \in F_k$. Since each $T^n$ is continuous, there exists an open neighborhood $V$ of $x$ such that $T^n[V]\subseteq U$ for all $n \in F_k$. Hence $V\subseteq Y_k$. This implies that $Y_k$ is open, hence $Y_U$ is open. By hypothesis, there exists a countable base of open sets $(U_m)$. The conclusion follows by the fact that the claimed set can be rewritten as $\bigcap_m Y_{U_m}$. 
    \end{proof}


Hereafter, we write also 
$$
\hat{\Pi}^0_1:=\left\{\mathcal{S}\subseteq \mathcal{P}(\omega): \mathcal{S} \text{ is hereditary closed}\right\},
$$
and we define, recursively for positive integers $k$, the modified versions of Borel pointclasses by 
$$
\hat{\Sigma}^0_{2k}:=\left\{\bigcup\nolimits_{j \in \omega}\mathcal{S}_j:\, \forall j \in \omega, \mathcal{S}_j \in \hat{\Pi}^0_{2k-1} 
%\text{ for all }j \in \omega
\right\}
$$
and 
$$
\hat{\Pi}^0_{2k+1}:=\left\{\bigcap\nolimits_{j \in \omega}\mathcal{S}_j:\, \forall j \in \omega, \mathcal{S}_j \in \hat{\Sigma}^0_{2k}. 
%\text{ for all }j \in \omega
\right\}
$$
For instance, $\hat{\Sigma}^0_2$ is the family of subsets $\mathcal{S}\subseteq \mathcal{P}(\omega)$ which can be written as countable union of hereditary closed sets, $\hat{\Pi}^0_3$ is the family of all $\mathcal{S}\subseteq \mathcal{P}(\omega)$ which can be written as countable union of countable intersection of hereditary closed sets, etc.; we will use also the standard notation of Borel classes $\Sigma^0_k(X)$ and $\Pi^0_k(X)$ as in \cite[Chapter 22]{MR1321597}. 

Given a hereditary subset $\mathcal{F}\subseteq \mathcal{P}(\omega)$ (in place of an ideal on $\omega$) and a continuous function $T$ on a topological space $X$ (in place of a continuous linear operator on a topological vector space), it still makes sense to write 
$$
\mathrm{HC}_T(\mathcal{F})
$$
for the set of all points $x \in X$ such that $\{n \in \omega: T^nx \in U\} \notin \mathcal{F}$ for all nonempty open sets $U\subseteq X$; equivalently, this is the set of hypercyclic points of $T$ with respect to the Furstenberg family $\mathcal{P}(\omega)\setminus \mathcal{F}$, as defined in \cite{MR3847081}. 


%\textcolor{red}{Premise notation, also standard notation.}
\begin{thm}\label{thm:mainnewtopological}
    Let $T: X\to X$ be a continuous function, where $X$ is a second countable topological space and pick a subset $\mathcal{F}\subseteq \mathcal{P}(\omega)$. Then the following hold\textup{:}
    \begin{enumerate}[label={\rm (\roman{*})}]
\item \label{item:thmtopol01} If $\mathcal{F} \in \hat{\Pi}^0_{1}$ then $\mathrm{HC}_T(\mathcal{F}) \in \Pi^0_2(X)$\textup{;}
\item \label{item:thmtopol02} If $\mathcal{F} \in \hat{\Pi}^0_{2k+1}$ for some $k\ge 1$ then $\mathrm{HC}_T(\mathcal{F}) \in \Sigma^0_{2k+1}(X)$\textup{;} 
\item \label{item:thmtopol03} If $\mathcal{F} \in \hat{\Sigma}^0_{2k}$ for some $k\ge 1$ then $\mathrm{HC}_T(\mathcal{F}) \in \Pi^0_{2k}(X)$\textup{.} 
\end{enumerate}
\end{thm}
\begin{proof}
    \ref{item:thmtopol01}. This is just a rewriting of Proposition \ref{prop:maintooltopological}. Items \ref{item:thmtopol02} and \ref{item:thmtopol03} are obtained by induction on $k$. For instance, if $\mathcal{F} \in \hat{\Sigma}^0_2$, then $\mathcal{F}=\bigcup_j \mathcal{F}_j$ for some sequence $(F_j)$ in $ \hat{\Pi}^0_1$. Taking into account that each $\mathrm{HC}_T(\mathcal{F}_j)$ is $G_\delta$ (i.e., belongs to $\Pi^0_2(X)$) and 
    $$
    \mathrm{HC}_T(\mathcal{F})=\bigcap\nolimits_{j \in \omega} \mathrm{HC}_T(\mathcal{F}_j),
    $$
    it follows that $\mathrm{HC}_T(\mathcal{F}) \in \Pi^0_2(X)$. Similarly, if $\mathcal{F}=\bigcap_j \mathcal{F}_j \in \hat{\Pi}^0_3$ for some $(F_j)$ in $ \hat{\Sigma}^0_2$, we obtain with a similar reasoning $\mathrm{HC}_T(\mathcal{F})=\bigcup_j \mathrm{HC}_T(\mathcal{F}_j) \in \Pi^0_3(X)$, and so on. 
\end{proof}

As first consequence, we obtain an alternative proof of Theorem \ref{thm:startingthm}\ref{item:02}:
\begin{cor}\label{cor:Fsigma}
Let $T: X\to X$ be a continuous linear operator, where $X$ is a 
second countable topological vector space, 
and let $\mathsf{I}$ be a $F_\sigma$-ideal on $\omega$. Then $\mathrm{HC}_T(\mathsf{I})$ is a $G_{\delta}$-set. 
\end{cor}
\begin{proof}
    Pick a sequence $(\mathcal{S}_j)$ of closed subsets of $\mathcal{P}(\omega)$ such that $\mathsf{I}=\bigcup_j \mathcal{S}_j$. For each $j \in \omega$, define $\mathcal{F}_j:=\{A\subseteq \omega: A\subseteq B \text{ for some }B \in \mathcal{S}_j\}$. Then each $\mathcal{F}_j$ is hereditary closed and $\mathsf{I}=\bigcup_j \mathcal{F}_j$, i.e., $\mathsf{I} \in \hat{\Sigma}^0_2$. Therefore $\mathrm{HC}_T(\mathsf{I}) \in \Pi^0_2(X)$  
    by Theorem \ref{thm:mainnewtopological}\ref{item:thmtopol03}. 
\end{proof}

