\subsection{Lower bounds on topological complexities.} Before we proceed to the proof of Theorem \ref{thm:mainnegativekarl}, we recall the notion of frequently hypercyclicity (which is stronger than upper frequently hypercyclicity); see e.g. \cite[Chapter 9]{MR2919812}. To this aim, for each $n \in \omega$, define the lscsm $\mu_n: \mathcal{P}(\omega) \to [0,\infty]$ by 
$$
\forall S\subseteq \omega, \quad 
\mu_n(S):=\frac{|S\cap [0,n)]}{n+1}.
$$
Let also $\mathsf{d}^\star$ and $\mathsf{d}_\star$ be the upper and lower asymptotic density on $\omega$, respectively, i.e., 
$$
\forall S\subseteq \omega, \quad 
\mathsf{d}^\star(S):=\limsup_{n\to \infty}\mu_n(S) 
\quad \text{ and }\quad 
\mathsf{d}_\star(S):=\liminf_{n\to \infty}\mu_n(S). 
$$
In particular, it is immediate that $\mathsf{Z}=\{S\subseteq \omega: \mathsf{d}^\star(S)=0\}$, hence a continuous map $T: X\to X$ is upper frequently hypercyclic if and only if there exists $x \in X$ such that $\mathsf{d}^\star(\{n \in \omega: T^nx \in U\})>0$ for all nonempty open sets $U\subseteq X$. 
\begin{defi}
Let $T:X\to X$ be a continuous map, where $X$ is a topological space. Then $T$ is \textbf{frequently hypercyclic} if there exists $x \in X$ such that 
$$
\mathsf{d}_\star(\{n \in \omega: T^nx \in U\})>0
$$
for all nonempty open sets $U\subseteq X$. 
\end{defi}

Of course, also the above definition depends on the underlying topology on $X$, hence it makes sense to speak about norm frequently hypercyclicity, pointwise frequently hypercyclicity, etc. 
Lastly, we write $s^\frown t$ to denote the concatenation of two sequences $s\in \mathbf{R}^{<\omega}$ and $t\in \mathbf{R}^{<\omega}\cup \mathbf{R}^\omega$, and $0^n:=(0,0,\ldots,0)$ where $0$ is repeated $n$ times.



