$$
%Accordingly, $s^{(0)} \in \mathbf{R}^{<\omega}$ has lenght $(x_0+2)\hat{m}_0$. 

\item Suppose that, for some $t \in \omega$, the integer $m_{t} \in \omega$ and the finite sequence $s^{(t)}\in \mathbf{R}^{<\omega}$ have been defined, with $\hat{m}_t:=m_t+k_{t}$. For convenience, set also 
%$$
%\alpha_t:=\hat{m}_0+\cdots+\hat{m}_t, 
%\quad 
%\beta_t:=\hat{m}_0(x_0+1)+\cdots+\hat{m}_t(x_t+1), 
%$$ 
%and $\gamma_t:=\alpha_t+\beta_t$. 
$$
\alpha_t:=\sum_{j=0}^t \hat{m}_j, \,\, 
\beta_t:=\sum_{j=0}^t (x_j+1)\hat{m}_j,\,\,\text{ and }\,\,
\gamma_t:=\sum_{j=0}^t (x_j+2)\hat{m}_j.
$$

\item 
Pick an integer $m_{t+1} > \max\{k_{t+1}, (t+1)^2\alpha_t\}$ such that 
$$
%\forall j \in \{0,1,\ldots,t+1\}, \quad 
\forall m\ge m_{t+1}, \forall j \in [0,t+1],\quad 
\mu_{\alpha_t+m}(S_{j}\setminus [0,\alpha_t)) \ge  (1-\varepsilon_{t+1}) \,\mathsf{d}_\star(S_{j}). 
$$
%for all $j \in \{0,1,\ldots,t+1\}$, 
%which is again possible since $\varphi$ is a lscsm. 
Note that this is again possible. 
Set $\hat{m}_{t+1}:=m_{t+1}+k_{t+1}$ and define 
\begin{equation}\label{eq:defst}
s^{(t+1)}:=0^{(x_{t+1}+1)\hat{m}_{t+1}}\text{ }^\frown \left(\frac{y_n}{\tilde{w}_{n+1,\beta_t+(x_{t+1}+1)\hat{m}_{t+1}+n}}: n \in [\alpha_t, \alpha_t+\hat{m}_{t+1})\right).
\end{equation}
\end{enumerate}

Accordingly, for each $t \in \omega$, the finite sequence $s^{(t)}$ has lenght $(x_t+2)\hat{m}_t$, hence $s^{(0)}\text{ }^\frown s^{(1)}\text{ }^\frown \cdots \text{ }^\frown s^{(t)}$ has lenght $\gamma_t$. Finally, define the sequence $f(x)$ by 
$$
f(x):=s^{(0)}\text{ }^\frown s^{(1)}\text{ }^\frown s^{(2)}\text{ }^\frown \ldots 
$$

\medskip

\begin{claim}\label{claim:continuity}
    $f$ is well defined and continuous. 
\end{claim}
\begin{proof}
Suppose that $X=\ell_p$ (the case $X=c_0$ being similar). As it follows by \eqref{eq:defst}, each $s^{(t)}$ contains a block of components of $y$, each one divided by values $\ge 1$. Since the norm of a sequence is invariant under the addition of zeros, we get $\|f(x)\|\le \|y\|$ for each $x \in \Delta$. Hence $f(x) \in X$ for each $x \in \Delta$, that is, $f$ is well defined. 

For the second claim, we show something stronger, namely, $f$ is norm continuous. Fix $\varepsilon>0$ and pick $n_0 \in \omega$ such that $\|0^n\text{ }^\frown (y_n,y_{n+1}, \ldots)\|< \varepsilon/2$ for all $n\ge n_0$. Pick 
%$t \in \omega$ such that $\hat{m}_t \ge n_0$ and consider 
$x,x^\prime \in \Delta$ such that $x_n=x^\prime_n$ for all 
$n\in [0, n_0]$. 
%$n\in [0,t]$. 
Taking again into account that the denominators in \eqref{eq:defst} are $\ge 1$, it follows that 
\begin{displaymath}
    \begin{split}
        \|f(x)-f(x^\prime)\|&\le 2\|0^n\text{ }^\frown (y_n,y_{n+1}, \ldots)\|<\varepsilon. 
    \end{split}
\end{displaymath}
In particular, $f$ is pointwise continuous. 
%\textcolor{red}{[Complete]}
\end{proof}

At this point, for each $x \in \Delta$, define the map $\iota_x: \omega\to \omega$ such that, if $n=\gamma_{t-1}+(x_t+1)\hat{m}_t+u$ for some $u \in [0,m_t)$ then $\iota_x(n):=\alpha_{t-1}+u$ (where, by convention, we assume that $\alpha_{-1}:=\beta_{-1}:=\gamma_{-1}:=0$); in all remaining cases $\iota_x(n):=0$. 

\begin{claim}\label{claim:equivalence}
Fix $x \in \Delta$ and $i \in \omega$. Then
%Fix $n \in \omega$ with $\iota(n)\neq 0$. Then, for each $x \in \Delta$, we have 
$$
T^nf(x) \in V_{i}
\quad \text{ if and only if }\quad 
T^{\iota_x(n)}y \in V_{i}
$$
for all sufficiently large $n \in \omega$ with $\iota_x(n)\neq 0$. 
\end{claim}
\begin{proof}
Set $\iota:=\iota_x$, and recall that $m_j>k_j$ for all $j \in \omega$ and $(k_j: j \in \omega)$ is increasing. Pick an integer $n \in \omega$ with $\iota(n)\neq 0$. Hence there exist $t,u \in \omega$ such that $n=\gamma_{t-1}+(x_t+1)\hat{m}_t+u$ and $u \in [0,m_t)$. Notice that by construction $n\ge \hat{m}_t \ge 1$. In addition, suppose that $t\ge i$ (hence, we remove only finitely many $n$, and $m_t>k_t\ge k_i$). 

    On the one hand, we have 
\begin{displaymath} 
\begin{split}
T^{\iota(n)}y&=(w_1w_2\cdots w_{\iota(n)}y_{\iota(n)}, w_2w_3\cdots w_{{\iota(n)}+1}y_{{\iota(n)}+1}, \ldots)\\
&=(w_1w_2\cdots w_{\alpha_{t-1}+u}y_{\alpha_{t-1}+u}, w_2w_3\cdots w_{{\alpha_{t-1}+u}+1}y_{{\alpha_{t-1}+u}+1}, \ldots).
\end{split}
    \end{displaymath}   
In particular, for all integers $j \in [0,k_{i}]$, we get 
$$
(T^{\iota(n)}y)_{j}
%=w_{1+j}w_{2+j}\cdots w_{\alpha_{t-1}+u+j}y_{\alpha_{t-1}+u+j}
=\tilde{w}_{1+j,\alpha_{t-1}+u+j}y_{\alpha_{t-1}+u+j}.
$$

    On the one hand, setting $z:=f(x)$, we have that 
\begin{displaymath} 
    T^nz =(w_1w_2\cdots w_nz_n, w_2w_3\cdots w_{n+1}z_{n+1}, \ldots).%, w_{k_m+1}w_{k_m+2}\cdots w_{k_m+n-1}z_{k_m+n-1}
    %&=\left(\tilde{w}_{k+1,n-1}z_{k+1}: k \in \omega\right)\\
    %&=(w_1w_2\cdots w_nz_n, w_2w_3\cdots w_{n+1}z_{n+1}, \ldots)
    \end{displaymath}   
It follows that, for each integer $j \in [0,k_{i}]$, we have
\begin{displaymath} 
\begin{split}
(T^nz)_j&=w_{1+j}w_{2+j}\cdots w_{n+j}z_{n+j}\\
&=w_{1+j}w_{2+j}\cdots w_{\gamma_{t-1}+(x_t+1)\hat{m}_t+u+j} z_{\gamma_{t-1}+(x_t+1)\hat{m}_t+u+j}\\
&=w_{1+j}w_{2+j}\cdots w_{\gamma_{t-1}+(x_t+1)\hat{m}_t+u+j} \cdot \frac{y_{\alpha_{t-1}+u+j}}{\tilde{w}_{\alpha_{t-1}+u+j+1,\beta_{t-1}+(x_t+1)\hat{m}_{t}+\alpha_{t-1}+u+j}}\\
&=w_{1+j}w_{2+j}\cdots w_{\gamma_{t-1}+(x_t+1)\hat{m}_t+u+j} \cdot \frac{y_{\alpha_{t-1}+u+j}}{\tilde{w}_{\alpha_{t-1}+u+j+1,\gamma_{t-1}+(x_t+1)\hat{m}_{t}+u+j}}\\
&=w_{1+j}w_{2+j}\cdots w_{\alpha_{t-1}+u+j}y_{\alpha_{t-1}+u+j}
\end{split}
    \end{displaymath}  
Therefore $(T^nz)_j=(T^{\iota(n)}y)_j$ for all $j \in [0,k_i]$.    
\end{proof}


\begin{claim}\label{claim:inclusion1}
$D\subseteq f^{-1}[\mathrm{UFHC}(B_{\bm{w}})]$. 
\end{claim}
\begin{proof}
Fix $x \in D$, so that $x \in \omega^\omega$ satisfies $\liminf_n x_n<\infty$ and $x_n\le n$ for all $n \in \omega$. In particular, there exist $j\in \omega$ and an infinite set $Q\subseteq \omega$ such that $x_n=j$ for all $n \in Q$. At this point, it is enough to show that the sequence $z:=f(x)$ is (pointwise) upper frequently hypercyclic for $B_{\bm{w}}$. To this aim, fix an integer $i \in \omega$. 
%and recall that $g^{-1}(i) \in \mathrm{Fin}^+$. 
Thanks to Claim \ref{claim:equivalence}, there exists $F\in \mathrm{Fin}$ such that 
$$
A\setminus F\subseteq \{n \in \omega: T^nz \in V_i\}, 
\quad \text{ where }\,\, A:=\{n \in \iota_x^{-1}((0,\infty)): T^{\iota_x(n)}y \in V_i\}.
$$
Now, recall that $\mathsf{d}_\star(S_i)=\mathsf{d}_\star(\{n \in \omega: T^ny \in V_i\})>0$ since $y$ is pointwise frequently hypercyclic. It follows by the construction of $f(x)$ that 
$$
\mathsf{d}^\star\left(\bigcup\nolimits_{t \in Q\setminus [0,i]}(S_i \cap [\alpha_{t-1},\alpha_{t-1}+m_t))\right)\ge \mathsf{d}_\star(S_i)>0.
$$
Moreover, by the definition of $\iota_x$, we have 
$$
%\forall t\in g^{-1}(i)\setminus \{0\}, \quad 
\iota_x^{-1}\left[S_i \cap [\alpha_{t-1},\alpha_{t-1}+m_t)\right]=(S_i \cap [\alpha_{t-1},\alpha_{t-1}+m_t))+\beta_{t-1}+(x_t+1)\hat{m}_t\subseteq A.  
$$
for all integers $t>i$. This implies, by the above observations of the standard properties of $\mathsf{d}^\star$, see e.g. \cite{MR4054777}, that 
\begin{displaymath}
    \begin{split}
        \mathsf{d}^\star(\{n \in \omega: T^nz \in V_i\})&\ge \mathsf{d}^\star(A\setminus F)=\mathsf{d}^\star(A) \\
        &\hspace{-20mm}\ge \mathsf{d}^\star\left(\bigcup\nolimits_{t \in Q\setminus [0,i]}(S_i \cap [\alpha_{t-1},\alpha_{t-1}+m_t))+\beta_{t-1}+(x_t+1)\hat{m}_t\right)\\
        &\hspace{-20mm}\ge \mathsf{d}^\star\left(\bigcup\nolimits_{t \in Q\setminus [0,i]}(S_i \cap [\alpha_{t-1},\alpha_{t-1}+m_t))+\sum_{u<t}(u+1)\hat{m}_u+(j+1)\hat{m}_t\right)\\
        &\hspace{-20mm}\ge \mathsf{d}^\star\left(\bigcup\nolimits_{t \in Q\setminus [0,i]}(S_i \cap [\alpha_{t-1},\alpha_{t-1}+m_t))+(j+2)\hat{m}_t\right)\\
        &\hspace{-20mm}\ge 
        \limsup_{t \to \infty, t \in Q}\frac{|S_i \cap [\alpha_{t-1}, \alpha_{t-1}+m_t))|}{m_t+(j+2)\hat{m}_t}\\
        %&\hspace{-20mm}\ge \limsup_{t \to \infty, t \in Q} \mu_{m_t+(j+2)\hat{m}_t}(S_i\setminus [0,\alpha_{t-1}))
        &\hspace{-20mm}=
        \limsup_{t \to \infty, t \in Q}\mu_{\alpha_{t-1}+m_t}(S_i \setminus [0,\alpha_{t-1})) \cdot \frac{\alpha_{t-1}+m_t}{m_t+(j+2)\hat{m}_t}\\%{m_t+(j+2)\hat{m}_t}
        &\hspace{-20mm}
        \ge \mathsf{d}_\star(S_i)\cdot \liminf_{t \to \infty}\frac{\alpha_{t-1}+m_t}{m_t+(j+2)\hat{m}_t} \\
        &\hspace{-20mm}
        \ge \mathsf{d}_\star(S_i)\cdot \liminf_{t \to \infty}\frac{1}{1+(j+2)\hat{m}_t/m_t} \\
        &\hspace{-20mm}
        \ge \mathsf{d}_\star(S_i)\cdot \frac{1}{1+2(j+1)}>0. 
    \end{split}
\end{displaymath}
Therefore $z \in \mathrm{UFHC}(B_{\bm{w}})$.  
\end{proof}

\begin{claim}\label{claim:inclusion2}
$f^{-1}[\mathrm{UFHC}(B_{\bm{w}})]\subseteq D$.
\end{claim}
\begin{proof}
Fix $x \in \Delta\setminus D$,  so that $x \in \omega^\omega$ satisfies $\lim_n x_n=\infty$ and $x_n\le n$ for all $n \in \omega$. We claim that $\mathsf{d}_\star(\{n \in \omega: z_n=0\})=1$, where $z:=f(x)$. In fact, taking into account the above construction (so that, for each $t \in \omega$, we have $z_n=0$ for all $n \in [\gamma_{t-1}, \gamma_{t-1}+(x_t+1)\hat{m}_t)$, and $\gamma_{t-1}\le \hat{m}_t$), we obtain  
\begin{displaymath}
    \begin{split}
        \mathsf{d}_\star(\{n \in \omega: z_n=0\})
        &\ge \liminf_{t \to \infty} \, \min_{i \in [\gamma_{t-1}+(x_t+1)\hat{m}_t, \gamma_t)} \, \mu_i(\{n \in \omega: z_n=0\})\\
        &\ge \liminf_{t \to \infty} \, \frac{(x_t+1)\hat{m}_t}{\gamma_{t-1}+(x_t+2)\hat{m}_t}\\
        &\ge \liminf_{t \to \infty} \, \frac{(x_t+1)\hat{m}_t}{\hat{m}_t+(x_t+2)\hat{m}_t}=1.
    \end{split}
\end{displaymath}
In particular, we get $z\notin \mathrm{UFHC}(B_{\bm{w}})$. 
\end{proof}

At this point, the identity $D=f^{-1}[\mathrm{UFHC}(B_{\bm{w}})]$ follows putting together Claim \ref{claim:inclusion1} and Claim \ref{claim:inclusion2}. This concludes the proof. 
\end{proof}

Now, we recall the following characterization by Bayart and Rusza \cite{MR3334899}:
\begin{thm}\label{thm:bayartRuzsa}
    Let $\bm{w}$ be a bounded sequence of positive reals and consider the weighted backward shift $B_{\bm{w}}$ on $\ell_p$, with $p \in [1,\infty)$. Then the following are equivalent\textup{:}
    \begin{enumerate}[label={\rm (\roman{*})}]
    \item $B_{\bm{w}}$ is norm frequently hypercyclic\textup{;}
    \item $B_{\bm{w}}$ is norm upper frequently hypercyclic\textup{;}
\item condition \eqref{eq:conditionufhc} holds\textup{.}
    \end{enumerate}
 \end{thm}
\begin{proof}
    See \cite[Theorem 4]{MR3334899}. 
\end{proof}

Putting together the above results, we obtain a proof of Theorem \ref{thm:mainnegativekarl}. 
\begin{proof}
    [Proof of Theorem \ref{thm:mainnegativekarl}] 
    Thanks to Theorem \ref{thm:bayartRuzsa}, the weighted backward shift $B_{\bm{w}}$ is norm frequently hypercyclic. Hence, it is also pointwise frequently hypercyclic. The conclusion follows by Theorem \ref{thm:main}. The second part is immediate by the fact that constant sequence $(\lambda, \lambda, \ldots)$ satisfies \eqref{eq:conditionufhc} if $\lambda>1$. 
\end{proof}

In particular, we have the following consequence: 
\begin{cor}
    Consider the unilateral backward shift $B$ on $\ell_2$, endowed with the product topology. Then $\mathrm{UFHC}(2B)$ is $G_{\delta\sigma}$ but not $F_{\sigma\delta}$. 
\end{cor}
\begin{proof}
    It follows by Theorem \ref{thm:topologicalanalyticP} and Theorem \ref{thm:mainnegativekarl}. 
\end{proof}

