\subsection{[Non-]equivalence of $\mathsf{I}$-hypercyclicity for different topologies} Finally, we proceed to the proofs of Theorem \ref{thm:equivalenceweaklynorm} and Theorem \ref{thm:nonequivalence}. Here, if $y \in \ell_p$ and $S\subseteq \omega$, we write $y \upharpoonright S$ for the sequence defined by $(y \upharpoonright S)_n:=y_n$ if $n \in S$ and $(y \upharpoonright S)_n:=0$ if $n \notin S$; in addition, $A+B:=\{x+y: x \in A, y \in B\}$ for each $A,B\subseteq \omega$. 
\begin{proof}
[Proof of Theorem \ref{thm:equivalenceweaklynorm}]
The implications \ref{item:1equivalenthyperc} $\implies$ \ref{item:2equivalenthyperc} $\implies$ \ref{item:3equivalenthyperc} are obvious. To prove \ref{item:3equivalenthyperc} $\implies$ \ref{item:1equivalenthyperc}, fix $p \in [1,\infty)$ and let us suppose that $T:=B_{\bm{w}}$ is pointwise $\mathsf{I}$-hypercyclic on $\ell_p$, hence it is possible to pick a sequence $y \in \ell_p$ such that its orbit $\mathrm{orb}(y, T)$ is $\tau^p$-dense 
(the proof in the case where the underlying space is $c_0$ is analogous, hence we omit it). 
Let $(s^{(i)}: i \in \omega)$ be an enumeration of $c_{00} \cap \mathbf{Q}^\omega$. %, which is norm dense in $\ell_p$. 
For each $i \in \omega$, pick the smallest $m_i\in \omega$ such that $s^{(i)}_n=0$ for all $n> m_i$. Up to relabeling, we can suppose without loss of generality that $m_i \le \max\{1,i\}$ for all $i \in \omega$. For each $i,j \in \omega$, define  
$$
U(i,j):=\left\{x \in \ell_p: |x_n-s^{(i)}_n| < 2^{-j} \text{ for all }n\le m_i\right\},
$$
which is a $\tau^p$-open set. Pick a bijection $h: \omega\to \omega^2$ and, for each $t \in \omega$, define 
$$
S_t:=\left\{n \in \omega: T^ny \in U(h(t))\right\} \in \mathsf{I}^+. 
$$
Since countably generated ideals are clearly $F_\sigma$, it is possible to pick a lscsm $\varphi$ such that $\mathsf{I}=\mathrm{Fin}(\varphi)$ as in \eqref{eq:mazur}. In particular, $\varphi(S_t)=\infty$ for all $t \in \omega$. 
%we proceed similarly as in \cite[Theorem 4.1]{MR2091459}, which corresponds to the case $\mathsf{I}=\mathrm{Fin}$. Since $\mathsf{I}$ is an ideal with the Baire property, there exists an infinite partition $\{I_n: n \in \omega\}$ of $\omega$ such that $I_n\notin \mathsf{I}$ for all $n \in \omega$, see \cite[Proposition 4.3 and Figure 2]{FKL24}. 

Observe that $\|T\|>1$: indeed, in the opposite, we would have $|w_n|\le 1$ for all $n\ge 1$. Pick $i \in \omega$ such that $s^{(i)}=
%e^{(0)}
(1,0,0,\ldots)$. Thus $S_{h^{-1}(i,1)}=\{n \in \omega: (T^ny)_0 \in (\nicefrac{1}{2},\nicefrac{3}{2})\}\in \mathsf{I}^+$ (in particular, it is infinite). Considering that $(T^ny)_0=w_1\cdots w_n y_n$ for all $n\ge 1$, it follows that there exist infinitely many $n \in\omega$ such that 
$|y_n| \ge |w_1\cdots w_n y_n| = |(T^ny)_0| \ge \nicefrac{1}{2}$. This contradicts the hypothesis that $y \in \ell_p$.\footnote{The same claim $\|T\|>1$ does not hold in larger spaces: in fact, it is well known that the (unilateral unweighted) backward shift $B$ on $\mathbf{R}^\omega$ is pointwise hyperyclic (and has norm $1$), see e.g. the first part of the proof of \cite[Theorem 1]{MR1658096}.}

At this point, set for convenience $F_{-1}:=\{0\}$ and $m_{-1}:=0$, and define recursively a sequence $(F_t: t \in \omega)$ of nonempty finite subsets of $\omega$ as it follows. For each $t \in \omega$, choose a nonempty finite subset $F_t\subseteq S_t$ such that: 
\begin{enumerate}[label={\rm (\roman{*})}]
\item [(a)] $\min(F_t)>\max(F_{t-1})+m_{t-1}$, 
\item [(b)] $\|y \upharpoonright [\min F_t, \infty)\|_p \le 1/2^t\|T\|^{\max F_{t-1}}$ (which is possible since $\lim y=0$), and 
\item [(c)] $\varphi(F_t)\ge t$ (which is possible since $\varphi$ is lower semicontinuous). 
\end{enumerate}

Now, fix $i \in \omega$ and define $F^{(i)}:=\bigcup_{j \in\omega} F_{h^{-1}(i,j)}$.
Considering that 
$$
\varphi(F^{(i)})\ge \sup_{j \in \omega}\varphi(F_{h^{-1}(i,j)})\ge \sup_{j \in \omega} {h^{-1}(i,j)} = \infty,
$$
we obtain that $F^{(i)} \in \mathsf{I}^+$ by the representation \eqref{eq:mazur}. In addition, since countably generated ideals are $Q^+$-ideals, for each $j \in \omega$ there exists $g_{i,j} \in F_{h^{-1}(i,j)}$ such that 
$$
G^{(i)}:=\{g_{i,j}: j \in \omega\}
$$
belongs to $\mathsf{I}^+$. 

To conclude the proof, we claim that 
$$
z:=y \upharpoonright \bigcup\nolimits_{i} (G^{(i)}+[0,m_i]) %(F_t+[0,m_t])
$$
is norm $\mathsf{I}$-hypercyclic (notice that, of course, $z \in \ell_p$).  
In fact, suppose that $n=g_{i,j}$ for some $i,j \in \omega$ and set for simplicity $t:=h^{-1}(i,j)$ so that $g_{i,j} \in F_t$. Then it follows by construction that % and $\varepsilon>0$. 
%It follows by construction that, if $n \in F_{h^{-1}(i,j)}$ for some $j \in \omega$, then  
\begin{displaymath}
    \begin{split}
        \|T^{n}z-s^{(i)}\|_p
        &\le \|T^{n}(z \upharpoonright [{n},{n}+m_i])-s^{(i)}\|_p
        +\|T^n (z \upharpoonright (n+m_i,\infty))\|_p\\
        &\le \|T^n(y \upharpoonright [n,n+m_i])-s^{(i)}\|_p
        +\|T^n (y \upharpoonright [\min F_{t+1},\infty))\|_p\\
        &\le 2^{-j}(m_i+1)^{1/p}
        +\|T\|^n \|(y \upharpoonright [\min F_{t+1},\infty))\|_p\\
        &\le 2^{-j}(i+2)^{1/p}+\|T\|^{\max F_t}  \|(y \upharpoonright [\min F_{t+1},\infty))\|_p\\
        &\le 2^{-j}(i+2)+2^{-t}. 
    \end{split}
\end{displaymath}
Taking into account that $\lim_j h(i,j)=\infty$ for each $i \in \omega$, it follows that the subsequence $(T^nz: n \in G^{(i)})$ is norm convergent to $s^{(i)}$. Recalling that $G^{(i)} \in \mathsf{I}^+$, we obtain by \cite[Lemma 3.1(iii)]{MR3920799} that $s^{(i)}$ is an $\mathsf{I}$-cluster point of $\mathrm{orb}(z,T)$. Since the set of $\mathsf{I}$-cluster points is closed, see e.g. \cite[Lemma 3.1(iv)]{MR3920799}, and the set $\{s^{(i)}: i \in \omega\}$ is norm dense in $\ell_p$, we conclude that 
$$
\Gamma_{\mathrm{orb}(z,T)}(\mathsf{I})=\ell_p. 
$$
Therefore $T$ is norm $\mathsf{I}$-hypercyclic. 
\end{proof}

\begin{rmk}\label{rmk:onlycountablygenerated}
    An inspection of the proof of Theorem \ref{thm:equivalenceweaklynorm} reveals that we used the $Q^+$-property and a stronger variant of the $P^+$-property (to obtain $F^{(i)} \in \mathsf{I}^+$). 
%
    Here, we recall that an ideal $\mathsf{I}$ on $\omega$ is a $P^+$\emph{-ideal} if for all decreasing sequences $(S_n)$ with values in $\mathsf{I}^+$, there exists $S \in \mathsf{I}^+$ such that $S\setminus S_n$ is finite for all $n \in\omega$. It is known that every $G_{\delta\sigma}$-ideal on $\omega$ is a $P^+$-ideal, see \cite[Corollary 2.7]{MSP24} and \cite[Proposition 3.2]{FKL24}. In particular, all $F_\sigma$-ideals (including $\mathrm{Fin}$) are $P^+$-ideals. On the other hand, it is easy to see that $\mathsf{Z}$ is not a $P^+$-ideal, cf. \cite[Figure 1]{FKL24}. 

    %Now, suppose that $\mathsf{I}$ is an analytic $P$-ideal on $\omega$. 
    This implies that the strategy of the above proof could be adapted, in the best case, for ideals which are both $P^+$ and $Q^+$ (which are commonly known as \emph{selective ideals}). However, it is known that, if $\mathsf{I}$ is an analytic $P$-ideal, then it is selective if and only if it is countably generated. On a different direction, Todor\v{c}evi\'c found an example of an analytic selective
ideal which is not generated by an almost disjoint family; see \cite[Section 1]{MR3351990} and references therein. 
\end{rmk}

\begin{rmk}
   The analogue claim of Theorem \ref{thm:equivalenceweaklynorm} holds replacing $\ell_p$ (or $c_0$) with an arbitrary infinite-dimensional Banach lattice $X\subseteq c_0$ such that $c_{00} \cap \mathbf{Q}^\omega$ is relatively dense in $X$. The proof would go on the same lines, taking into account that norm convergence and pointwise convergence coincide on finite-dimensional subspaces, and that the sequence $z$ belongs to $X$ since $|z|\le |y|$ implies $\|z\|\le \|y\|$. 
\end{rmk}

