\begin{proof}
    [Proof of Theorem \ref{thm:nonequivalence}]
    Fix $p \in [1,\infty)$, define the function $f: \omega \to \mathbf{R}$ by 
    $$
    %\forall n \in \omega, \quad 
    f(n):=\left((n+2)\log(n+2)\right)^{1/p},
    $$
    for all $n \in \omega$ and the weight sequence $\bm{w}=(w_0,w_1,w_2,\ldots)$ defined by 
    $
    w_n:=\frac{f(n+1)}{f(n)}
    $ 
    for all $n \in \omega$. 
    %In particular, we have 
    %$$
    %w_0w_1\cdots w_n=\frac{f(n+1)}{f(0)}=\left(\right)^{1/p}
    %$$
    %$$
    %\bm{w}:=\left(2^{1/p}, \left(\frac{3}{2}\right)^{1/p}, \left(\frac{4}{3}\right)^{1/p}, \ldots \right). 
    %\left(\left(\frac{n+2}{n+1}\right)^{1/p}: n \in \omega\right). 
    %$$
    Then $\bm{w}$ is decreasing and $\lim_nw_n=1$. 
    We claim that $T:=B_{\bm{w}}$ satisfies the required properties. 

    First, observe that $\sup_n |w_0\cdots w_n|= \sup_n f(n+1)/f(0)=\infty$, hence $T$ is norm $\mathrm{Fin}$-hypercyclic, see e.g. \cite[Theorem 4.8 and Example 4.9]{MR2919812}. In addition, as it follows by Theorem \ref{thm:bayartRuzsa}, $T$ is norm $\mathsf{Z}$-hypercyclic if and only if condition \eqref{eq:conditionufhc} holds. However, the latter one fails since 
    $$
    \sum_{n\in\omega}\frac{1}{(w_0\cdots w_n)^p}\ge \sum_{n\ge 3}\frac{1}{n\log(n)}=\infty.
    $$ 
    Hence $T$ is not norm $\mathsf{Z}$-hypercyclic. To complete the proof, we need only to show that $T$ is pointwise $\mathsf{Z}$-hypercyclic. 

    %For, let $\mathsf{d}^\star(S):=\limsup_n |S \cap [0,n)|/n$ be the upper asymptotic density of $S\subseteq \omega$, so that $\mathsf{Z}=\{S\subseteq \omega:\mathsf{d}^\star(S)=0\}$.
    %Observe also that 
    %$$
    %\forall n \in \omega, \forall \bm{x} \in \ell_p, \quad 
    %T^n\bm{x}=\left(\left(\frac{n+2}{2}\right)^{1/p}x_n, \left(\frac{n+3}{3}\right)^{1/p}x_{n+1}, \left(\frac{n+4}{4}\right)^{1/p}x_{n+2}, \ldots \right)
    %$$
    %for all $n \in \omega$ and $\bm{x} \in \ell_p$. 
    For, let $(s^{(i)}: i \in \omega)$ be an enumeration of $c_{00}\cap \mathbf{Q}^\omega$ and let $m_i \in \omega$ be the smallest \emph{positive} integer such that $s^{(i)}_n=0$ for all $n\ge m_i$. Up to relabeling, suppose without loss of generality that 
    %$m_i \le i$ for all $i \in\omega$. 
    \begin{equation}\label{eq:relabelingsi}
    \forall i \in \omega, \forall n \in \{0,1,\ldots,m_i-1\}, \quad 
    |s^{(i)}_n|\le 2^{i/p}
    \end{equation}
    (notice that this is really possible). Pick also a function $h: \omega \to \omega$ such that $H_k:=h^{-1}(k)$ is infinite for all $k \in \omega$. 

    At this point, define recursively an increasing sequence $(n_i: i \in \omega)$ of positive integers as it follows. Set for simplicity $n_{-1}:=0$ and, if $n_{i-1}$ is given for some $i\ge 1$, define 
    \begin{equation}\label{eq:defni}
    n_i:=1+\max\{n_{i-1},2^{h(i)}m_{h(i)}, 3^{2^i(m_{h(i)}+3)^2}\}.
    \end{equation}
    Now, for each $i \in \omega$, define the interval of integers 
    $$
    J_i:=\omega \cap \left[n_i!,\, n_i!\left(1+\frac{n_i}{2^{h(i)}}\right)\right].
    $$
    Define also the finite sequence of rationals $y^{(i)} \in \mathbf{Q}^{<\omega}$ as it follows. Observe that the lenght of $s^{(h(i))}$ is $m_{h(i)}$. Set $q_i:=|J_i|-r_im_{h(i)}$, where $r_i:=\lfloor |J_i|/m_{h(i)}\rfloor$, and define 
    \begin{displaymath}
        \begin{split}
            t^{(i,j)}:=\left(\frac{s^{(h(i))}_0}{w_1w_2\cdots w_{n_i!+jm_{h(i)}}}, 
    \right. &\, \frac{s^{(h(i))}_1}{w_2w_3\cdots w_{n_i!+jm_{h(i)}+1}} 
    , \cdots,  \\
    & \left.
    \frac{s^{(h(i))}_{m_{h(i)}-1}}{w_{m_{h(i)}}w_{m_{h(i)}+1}\cdots w_{n_i!+(j+1)m_{h(i)}-1}} \right)
        \end{split}
    \end{displaymath}
     %r^{(i)}. 
    for each $j \in \{0,1,\ldots,r_i-1\}$. 
    Accordingly, set 
    $$
    z^{(i)}:=t^{(i,0)}
    \text{ }\hspace{-.5mm}^\frown t^{(i,1)}
    \text{ }\hspace{-.5mm}^\frown \ldots
    \text{ }\hspace{-.5mm}^\frown t^{(i,r_i-1)}
    \text{ }\hspace{-.5mm}^\frown 0^{q_i},
    $$
    with the convention that $0^0:=\emptyset$. Notice that $|z^{(i)}|=r_im_{h(i)}+q_i=|J_i|$. 
    Lastly, we claim that the infinite sequence 
    \begin{equation}\label{eq:definizionez}
    z:=z^{(0)} \text{ }\hspace{-.5mm}^\frown z^{(1)} \text{ }\hspace{-.5mm}^\frown z^{(2)} \text{ }\hspace{-.5mm}^\frown 
 \ldots
    \end{equation}
    is pointwise $\mathsf{Z}$-hypercyclic. (Informally, $z$ is a sequence made by the concatenation of all $z^{(i)}$, each of one is supported on $J_i$ and made by suitable rescaled blocks of $s^{h(i)}$.)

    For, we need to show first that the sequence $z$ defined in \eqref{eq:definizionez} belongs to $\ell_p$. Notice that the map $n\mapsto f(n+1)/f(n)$ is decreasing and $n\mapsto f(n)$ is increasing. 
    It follows by \eqref{eq:relabelingsi} and the above construction that 
\begin{displaymath}
        \begin{split}
            \|z\|_p^p
            &=\sum_{i \in \omega}\sum_{n \in J_i}|z^{(i)}_n|^p 
            =\sum_{i \in \omega}\sum_{j\in r_i}\sum_{n \in m_{h(i)}+1}|t^{(i,j)}_n|^p \\
            %&\le \sum_{i \in \omega}\sum_{j\in r_i}\sum_{n \in m_{h(i)}+1}|t^{(i,j)}_n|^p\\
            &\le \sum_{i \in \omega}\sum_{n \in m_{h(i)}}r_i|t^{(i,0)}_n|^p\\
            &\le \sum_{i \in \omega}\sum_{n \in m_{h(i)}}r_i\cdot \frac{\left|s^{(h(i))}_n\right|^p}{(w_{m_{h(i)}}w_{m_{h(i)}+1}\cdots w_{n_i!+m_{h(i)}-1})^p}\\
            &\le \sum_{i \in \omega}\sum_{n \in m_{h(i)}}\frac{|J_i|}{m_{h(i)}}\cdot \frac{2^{h(i)}(w_1w_2\cdots w_{m_{h(i)}-1})^p}{(w_1w_2\cdots w_{n_i!+m_{h(i)}-1})^p}\\
            &= \sum_{i \in \omega}|J_i|\cdot 2^{h(i)} \cdot \left(\frac{f(m_{h(i)})}{f(n_i!+m_{h(i)})}\right)^p\\
            &\le \sum_{i \in \omega}(n_i!\cdot n_i \cdot 2^{-h(i)})\cdot 2^{h(i)}\cdot \frac{(m_{h(i)}+2)\log(m_{h(i)}+2)}{n_i! \log(n_i!)}.
            %\\& \le \sum_{n \in \omega} \sum_{i=0}^{|I_n|-1}\left|y^{(n)}_i\right|^p \\
            %& \le \sum_{n \in \omega} \frac{t_n}{w_{n,h(n),0}^p} \sum_{i=0}^{m_{h(n)}} \left|s^{(h(n))}_i\right|^p\\
            %&\le \sum_{n \in \omega} \frac{|I_n|}{(m_{h(n)}+1)w_{n,h(n),0}^p} \sum_{i=0}^{m_{h(n)}} \left|s^{(h(n))}_i\right|^p
        \end{split}
    \end{displaymath}
Recalling that $n!\ge (n/3)^n$ for all nonzero $n \in \omega$, we obtain by \eqref{eq:defni} that 
\begin{displaymath}
    \begin{split}
        \|z\|_p^p \le &\sum_{i \in \omega}n_i \cdot \frac{(m_{h(i)}+2)\log(m_{h(i)}+2)}{n_i \log(n_i/3)}\\
        &\le \sum_{i \in \omega}\frac{(m_{h(i)}+2)^2}{\log(n_i/3)}\le \sum_{i \in \omega}\frac{1}{2^i}=2.
    \end{split}
\end{displaymath}

To complete the proof, we show that $z$ is pointwise $\mathsf{Z}$-hypercyclic. 
Indeed, for each $j\in \omega$ there exists an infinite set $W_j\subseteq \omega$ such that $h(i)=j$ for all $i \in W_j$. It follows, for each $j \in \omega$, that 
\begin{displaymath}
    \begin{split}
        \mathsf{d}^\star(\{k \in \omega: (T^kz)_n=&s^{(j)}_n \text{ for all }n\in m_j+1\})\ge \limsup_{i \in W_j}\frac{|J_i|/m_j}{\max J_i}\\
        &\ge \limsup_{i \in W_j} \frac{n_i!\cdot n_i/(2^jm_j)}{n_i!(1+n_i/2^j)}=\frac{1}{m_j}>0. 
    \end{split}
\end{displaymath}
Hence, each $s^{(j)}$ is a pointwise $\mathsf{Z}$-cluster point of the orbit of $z$. This completes the proof since the set of $\mathsf{Z}$-cluster points is $\tau^p$-closed and $\{s^{(j)}: j \in \omega\}$ is $\tau^p$-dense in $\ell_p$. 
\end{proof}


