\subjclass[2010]{17A30, 17A60, 17B38, 17D25}
\keywords{pre-Novikov algebra, pre-Lie algebra, right Novikov dialgebra, affinization, pre-Novikov bialgebra, Yang-Baxter equation}
\footnote{
Corresponding author: Y. Hong (yyhong@hznu.edu.cn).
