\section{Pre-Lie (co)algebras from pre-Novikov (co)algebras and right-Novikov (co)dialgebras}
In this section, we show that there is a pre-Lie algebra structure on the tensor product of a pre-Novikov algebra and a right Novikov dialgebra. Moreover, if we take the right Novikov dialgebra as a special right Novikov algebra on the vector space of Laurent polynomials, the tensor product of a pre-Novikov algebra and this right Novikov algebra being a pre-Lie algebra characterizes this pre-Novikov algebra, which is called an affinization of pre-Novikov algebras. Dually, we  show that there is a completed pre-Lie coalgebra structure on the tensor product of a pre-Novikov coalgebra and a completed right Novikov co-dialgebra and also give an affinization of pre-Novikov coalgebras.

\subsection{Pre-Lie algebras from pre-Novikov algebras and right-Novikov dialgebras}
Recall that a {\bf pre-Lie algebra} is a vector space $A$ with a binary operation $\circ :A\otimes A \rightarrow A$ satisfying
\begin{align}
(a\circ b)\circ c-a\circ (b\circ c)&=(b\circ a)\circ c-b\circ (a\circ c),\quad a,b,c\in A.
\end{align}
Denote it by $(A,\circ)$. If the binary operation $\circ$ also satisfies
\begin{align}
(a\circ b)\circ c=(a\circ c)\circ b, \quad a,b,c\in A,
\end{align}
then we call $(A,\circ)$ a {\bf Novikov algebra}.

 Let $(A,\circ )$ be a pre-Lie algebra. Then $A$ is a Lie algebra under the bracket operation $[a,b]=a\circ b-b\circ a$ for all $a$, $b\in A$, which is denoted by $(\mathcal{G}(A),[\cdot,\cdot])$. $(\mathcal{G}(A),[\cdot,\cdot])$ is called the {\bf sub-adjacent Lie algebra } of $(A,\circ )$. We also call $(A,\circ )$ the {\bf compatible pre-Lie algebra structure } on  the Lie algebra $(\mathcal{G}(A),[\cdot,\cdot])$.

\begin{definition}\label{pNov}\cite{HBG}
A {\bf pre-Novikov algebra} is a vector space $A$ with binary operations $\vartriangleleft,\vartriangleright: A\otimes A\rightarrow A$  satisfying
\begin{align}
a\vartriangleright (b\vartriangleright c)&=(a\circ b)\vartriangleright c+b\vartriangleright(a\vartriangleright c)-(b\circ a)\vartriangleright c,\label{pN-1}\\
a\vartriangleright(b\vartriangleleft c)&=(a\vartriangleright b)\vartriangleleft c+b\vartriangleleft(a\circ c)-(b\vartriangleleft a)\vartriangleleft c,\\
(a\circ b)\vartriangleright c&=(a\vartriangleright c)\vartriangleleft b,\label{e20}\\
(a\vartriangleleft b)\vartriangleleft c&=(a\vartriangleleft c)\vartriangleleft b, \label{pN-4} \quad a,b,c\in A,
\end{align}
where $a\circ b:=a\vartriangleleft b+a\vartriangleright b$. Denote it by $(A,\vartriangleleft,\vartriangleright)$.
\end{definition}

\begin{proposition}\cite[Proposition 3.33]{HBG}\label{an}
Let $(A,\vartriangleleft,\vartriangleright)$ be a pre-Novikov algebra. The binary operation
\begin{align}
a\circ b:=a\vartriangleleft b+a\vartriangleright b, \quad  a,b\in A, \label{e13}
\end{align}
defines a Novikov algebra $(A,\circ)$, which is called the \textbf{associated Novikov algebra} of $(A,\vartriangleleft,\vartriangleright)$.
\delete{Furthermore, $(A,L_{\vartriangleright},R_{\vartriangleleft})$ is a representation of $(A,\circ)$. Conversely, let $A$ be a vector space equipped with binary operations $\vartriangleleft$ and $\vartriangleright$. If $(A, \circ)$ defined by Eq. \eqref{e13} is a Novikov algebra and $(A,L_{\vartriangleright},R_{\vartriangleleft})$ is a representation of $(A,\circ)$, then $(A,\vartriangleleft,\vartriangleright)$ is a pre-Novikov algebra.}
\end{proposition}


