Next, we recall the definitions of  right Novikov dialgebras and right Novikov algebras.
\begin{definition}\cite{KS,XBH}
A {\bf right Novikov dialgebra} $(B,\dashv,\vdash)$ is a vector space $B$ equipped with two binary operations $\dashv$, $\vdash: B\otimes B\longrightarrow B$ satisfying the following compatibility conditions
\begin{align}
&x \vdash (y\vdash z)=y\vdash (	x\vdash z),\;\;	x\vdash (y\dashv z)=y\dashv (x\dashv  z),\label{RN-di1}\\
&(x\vdash y -x\dashv y)\vdash z=0,\;\;x \dashv(y\vdash z-y\dashv z)=0,\label{RN-di2}\\
&x \vdash (y\vdash z-z\dashv y)=(x\vdash y)\vdash z-(x\vdash z)\dashv y,\label{RN-di3}\\
&x \dashv ( y\vdash z -z\dashv y )=(x \dashv y) \dashv z-(x \dashv z) \dashv y,\quad x, y,z \in B.\label{RN-di4}
\end{align}
\end{definition}



\begin{definition}
A {\bf right Novikov algebra} $(B, \diamond)$ is a vector space $B$ equipped with a binary operation $\diamond: B\otimes B\longrightarrow B$ satisfying the following compatibility conditions
\begin{align}
&(x\diamond y)\diamond z-x\diamond(y\diamond z)=(x\diamond z)\diamond y-x\diamond (z\diamond y),\label{e18}\\
&x\diamond (y\diamond z)=y\diamond(x\diamond z),\qquad x,y,z\in B.\label{e19}
\end{align}
\end{definition}

\begin{remark}
If $(B,\dashv,\vdash)$ is a right Novikov dialgebra where $\dashv=\vdash$, then $(B,\diamond:=\dashv=\vdash)$ is a right Novikov algebra. Therefore, right Novikov algebras are special right Novikov dialgebras.
\end{remark}

\begin{definition}\cite{HBG}
A {\bf $\ZZ$-graded right Novikov algebra} is a right Novikov algebra $(B,\diamond )$ with a linear decomposition
    $B=\oplus_{i\in \ZZ} B_i$ such that  $B_i \diamond B_j\subset B_{i+j}$ for all $i, j\in \ZZ$.

A {\bf $\ZZ$-graded pre-Lie algebra}  is a pre-Lie algebra $(L,\circ)$ with a linear decomposition $L=\oplus_{i\in \ZZ} L_i$ such that $L_i\circ L_j\subset L_{i+j}$ for all $i, j\in \ZZ$.
\end{definition}

\begin{example}\label{rN-ex}\cite{HBG}
Let $B={\bf k}[t,t^{-1}]$ be the vector space of Laurent polynomials  with a binary operation $\diamond$ given by
$$t^i\diamond t^j\coloneqq \frac{d}{dt}(t^i)t^j=it^{i+j-1},\quad i, j\in \mathbb{Z}.$$
Then $(B,\diamond)$ is a right Novikov algebra. Moreover, let $B_i={\bf k}t^{i+1}$ for each $i\in \mathbb{Z}$. Then
    $(B=\oplus_{i\in \mathbb{Z}}B_i, \diamond)$ is a $\ZZ$-graded
    right Novikov algebra.
\end{example}

Next, we present a construction of pre-Lie algebras from pre-Novikov algebras and right Novikov dialgebras.
