	\end{flalign}
	Then $(A\otimes B,\circ)$ is a pre-Lie algebra, which is called \textbf{the induced pre-Lie algebra} from $(A,\vartriangleleft,\vartriangleright)$ and $(B,\dashv,\vdash)$.
\end{theorem}
