\subsection{Completed pre-Lie coalgebras from pre-Novikov coalgebras and completed right-Novikov co-dialgebras}
We first recall the definition of pre-Novikov coalgebras.
\begin{definition}\cite{LH}\label{co1}
A \textbf{pre-Novikov coalgebra} is a vector space $A$ with linear maps $\alpha, \beta:A\rightarrow A\otimes A$ satisfying
%$R_1=0,R_2=0,R_3=0,R_4=0,$
%where $R_i:A\rightarrow A\otimes A\otimes A$ are linear maps defined by $(i=1,2,3,4)$
\begin{eqnarray}
&&\label{cob1}(\alpha\otimes \id)\alpha(a)+(\tau\otimes \id)(\id\otimes \alpha)\beta(a)-(\id\otimes(\alpha+\beta))\alpha(a)-(\tau\otimes \id)(\beta\otimes \id)\alpha(a)=0,\\
&&\label{cob2}(\id\otimes\beta)\beta(a)+(\tau\otimes \id)((\alpha+\beta)\otimes \id)\beta(a)-((\alpha+\beta)\otimes \id)\beta(a)-(\tau\otimes \id)(\id\otimes \beta)\beta(a)=0,\\
&&\label{cob3}(\id \otimes \tau)(\beta\otimes \id)\alpha(a)-((\alpha+\beta)\otimes \id)\beta(a)=0,\\
&&\label{cob4}(\id\otimes\tau)(\alpha\otimes \id)\alpha(a)-(\alpha\otimes \id)\alpha(a)=0,\quad  a\in A.
\end{eqnarray}
Denote it by $(A,\alpha,\beta)$.
\end{definition}

Let $V$ and $W$ be vector spaces. Suppose that $\phi:V\rightarrow W$ is a linear map. Then there is an induced dual linear map $\phi^*:W^*\rightarrow V^*$ defined by
\begin{align}
\langle \phi^*(f),v\rangle=\langle f, \phi(v)\rangle,\quad  v\in V,f\in W^*.\label{a1}
\end{align}
It is easy to see that
$(A,\alpha,\beta)$ is a pre-Novikov coalgebra if and only if $(A^*,\alpha^*,\beta^*)$ is a pre-Novikov algebra, if $A$ is finite-dimensional.






By \cite[Lemma 2.10]{HBG}, we need to recall the notion of completed tensor products. \delete{Hence we can obtain a coalgebra structure on the Laurent polynomials whose graded linear map dual is the right Novikov algebra of Laurent polynomials in Example \ref{rN-ex}.}

Let $C=\oplus_{i\in \ZZ} C_i$ and $D=\oplus_{j\in \ZZ} D_j$ be $\ZZ$-graded vector spaces. We call the {\bf completed tensor product} of $C$ and $D$ to be the vector space
$$C\hatot  D\coloneqq \prod_{i,j\in\ZZ} C_i\ot D_j.
$$
If $C$ and $D$ are finite-dimensional, then $C\hatot  D$ is just the usual tensor product $C\otimes D$.

In general, an element in $C\hatot  D$ is an infinite  sum $\sum_{i,j\in\ZZ} \ts_{ij} $ with $\ts_{ij}\in C_i\ot D_j$. So $\ts_{ij}=\sum_\alpha c_{i\alpha}\ot d_{j\alpha}$ for pure tensors $c_{i\alpha}\ot d_{j\alpha}\in C_i\ot D_j$ with $\alpha$ in a finite index set.
Thus a general term of $C\hatot  D$ is a possibly infinite sum
\vspace{-.2cm}
\begin{equation}\label{eq:ssum}
 \sum_{i,j,\alpha} c_{i\alpha}\ot d_{j\alpha},
 \end{equation}
where $i,j\in \ZZ$ and $\alpha$ is in a finite index set (which might depend on $i,j$).

With these notations, for linear maps $f:C\to C'$ and $g:D\to D'$, define
$$ f\hatot g: C\hatot D \to C' \hatot D',
\quad \sum_{i,j,\alpha} c_{i\alpha}\ot d_{j\alpha}\mapsto  \sum_{i,j,\alpha} f(c_{i\alpha})\ot g(d_{j\alpha}).
\vspace{-.2cm}
$$
Also the twist map $\tau$ has its completion

$$ \widehat{\tau}: C\hatot C \to C\hatot C, \quad
\sum_{i,j,\alpha} c_{i\alpha} \ot d_{j\alpha} \mapsto \sum_{i,j,\alpha} d_{j\alpha}\ot c_{i\alpha}.
$$
Finally, we define a completed coproduct to be a linear map
$$ \Delta: C\to C\hatot C, \quad \Delta(a)
:=\sum_{i,j,\alpha} a_{1i\alpha}\ot a_{2j\alpha}.
$$
%
Then we have the well-defined map

$$ (\Delta \hatot \id)\Delta(a)=(\Delta \hatot \id)\Big(\sum_{i,j,\alpha} a_{1i\alpha}\ot a_{2j\alpha}\Big) :=\sum_{i,j,\alpha} \Delta(a_{1i\alpha})\ot a_{2j\alpha}
\in C\hatot C \hatot C.
$$

\begin{definition}
 A {\bf \complete right Novikov co-dialgebra} is a triple $(B,\da,\db)$, where $B$ is a vector space and
$\da,\db: B\rightarrow B\hatot B$ are linear maps satisfying for all $x\in B$
\begin{eqnarray}
	&&\label{RNov-Codialg-1} ( \id \hatot\db )\db(x)=(\tau \hatot \id)(\id \hatot\db )\db(x),(\id \hatot \da)\db(x)=(\tau \hatot \id)(\id \hatot\da )\da(x),\\
	&&\label{RNov-Codialg-2}(\db \hatot \id)\db(x)=(\da \hatot\id )\db(x),( \id\hatot\db )\da(x)=(\id \hatot\da )\da(x),\\
	&&\label{RNov-Codialg-3}(\id \hatot\db )\db(x)-(\id \hatot\tau )(\id \hatot\da(b) )\db(x)=(\db \hatot \id)\db(x)-(\id \hatot\tau )(\db \hatot \id)\da(x),\\
	&&\label{RNov-Codialg-4}(\id \hatot\db )\da(x)-(\id \hatot\tau )(\id \hatot\da(b) )\da(x)=(\da \hatot \id)\da(x)-(\id \hatot\tau )(\da \hatot \id)\da(x).
\end{eqnarray}
\end{definition}
\begin{remark}
	If $B$ is finite-dimensional, then $(B,\da,\db)$ is called a {\bf  right Novikov co-dialgebra}.
\end{remark}


\begin{definition}
\begin{enumerate}
\item \cite{HBG}  A {\bf \complete right Novikov coalgebra} is a pair $(B,\Delta)$, where $B=\oplus_{i\in \ZZ}B_i$ is a $\mathbb{Z}$-graded vector space and
    $\Delta: B\rightarrow B\hatot  B$ is a linear map satisfying
    \begin{eqnarray}
        &&\label{top-Nov-Coalg-1}(\Delta \hatot  \id)\Delta(x)-(\id \hatot  \widehat{\tau})(\Delta \hatot  \id)\Delta(x)=(\id \hatot  \Delta)\Delta(x)-(\id \hatot  \widehat{\tau})(\id \hatot  \Delta )\Delta(x),\\
        &&\label{top-Nov-Coalg-2}(\id \hatot  \Delta)\Delta(x)=(\widehat{\tau}\hatot  \id) (\id \hatot  \Delta)\Delta(x),\;\;\; x\in B.
    \end{eqnarray}
\item
A {\bf \complete pre-Lie coalgebra}
 is a pair $(L, \delta)$, where
$L=\oplus_{i\in \ZZ} L_i$
  is a $\ZZ$-graded vector space and $\delta: L\rightarrow L\hatot L$ is a linear map satisfying
    \begin{align}
    (\id\hatot \delta)\delta(a)-(\tau\hatot \id)(\id \hatot \delta)\delta(a)=(\delta\hatot \id)\delta(a)-(\tau\hatot \id)(\delta\hatot \id)\delta(a),  \;\; a\in L\label{co-pL}.
    \end{align}
\end{enumerate}
\end{definition}

\begin{remark}
When $B$ (resp. $L$)  is finite-dimensional, $(B, \Delta)$ (resp. $(L, \delta)$) is just a right Novikov coalgebra (resp. a pre-Lie coalgebra).
 If $(B,\da,\db)$ is a completed right Novikov co-dialgebra in which $\da=\db$, then $(B,\Delta:=\da=\db)$ is a completed right Novikov coalgebra.
\end{remark}

\begin{example}\mlabel{Laurent-coproduct}\cite{HBG}
Let $B\coloneqq {\bf k}[t,t^{-1}]$  with a linear map $\Delta: B\rightarrow B \hatot  B$ given by
\begin{eqnarray}\mlabel{eq:laurentco}
     \notag
\Delta(t^j)=\sum_{i\in \mathbb{Z}}(i+1)t^{-i-2}\otimes  t^{j+i} , j\in \mathbb{Z}.
\end{eqnarray}
Then $(B={\bf k}[t,t^{-1}], \Delta)$ is a \complete right Novikov coalgebra.
\end{example}

