		&\quad\quad-(\tau\otimes \id)(\beta\otimes \id)\alpha(a)\big)\bullet(\widehat{\tau}\hatot\id)(\id\hatot\widehat{\tau})(\id\hatot\da)\db(x)\\
		&\quad\quad+\big((\id \otimes \tau)(\beta\otimes \id)\alpha(a)-((\alpha+\beta)\otimes \id)\beta(a)\big)\bullet(\db\hatot \id)\db(x)\\
