Let $k=2$. Comparing the coefficients of $t^{-1}\otimes t^{-1}\otimes 1$, we obtain
\begin{flalign*}
0=\sum_{[a]} (a_{[2]}\otimes a_{[12]}\otimes a_{[11]}-a_{[12]} \otimes a_{[2]}\otimes a_{[11]})=\tau_{13}\tau_{23}((\id\otimes\tau)(\alpha\otimes \id)\alpha(a)-(\alpha\otimes \id)\alpha(a)),
\end{flalign*}
where $\tau_{13}(a_1\otimes a_2\otimes a_3)=a_3\otimes a_2\otimes a_1$, $\tau_{23}(a_1\otimes a_2\otimes a_3)=a_1\otimes a_3\otimes a_2$, for all $a_1$, $a_2$, $a_3\in A$.
 Comparing the coefficients of $1\otimes t^{-1}\otimes t^{-1}$, we get
\begin{flalign*}
0&=\sum_{(a),[a]} (a_{[1](1)}\otimes a_{[2]}\otimes a_{[1](2)}-a_{(11)} \otimes a_{(12)}\otimes a_{(2)}-a_{(1)[1]}\otimes a_{(1)[2]}\otimes a_{(2)})\\
&=(\id \otimes \tau)(\beta\otimes \id)\alpha(a)-((\alpha+\beta)\otimes \id)\beta(a).
\end{flalign*}
Similarly, let $k=0$. Comparing the coefficients of $t^{-1}\otimes t^{-3}\otimes 1$,
we obtain
\begin{flalign*}
	0&=\sum_{(a),[a]} (a_{[12]}\otimes a_{[2]}\otimes a_{[11]}+a_{(2)[2]}\otimes a_{(1)}\otimes a_{(2)[1]}-a_{[22]}\otimes a_{[21]}\otimes a_{[1]}\\
	&\quad-a_{[2](2)}\otimes a_{[2](1)}\otimes a_{[1]}-a_{(12)} \otimes a_{(11)}\otimes a_{(2)}-a_{(1)[2]}\otimes a_{(1)[1]}\otimes a_{(2)})\\
	&=\tau_{13}((\alpha\otimes \id)\alpha(a)+(\tau\otimes \id)(\id\otimes \alpha)\beta(a)-(\id\otimes(\alpha+\beta))\alpha(a)-(\tau\otimes \id)(\beta\otimes \id)\alpha(a))\\
	&\quad +(\tau\ot \id)((\id \otimes \tau)(\beta\otimes \id)\alpha(a)-((\alpha+\beta)\otimes \id)\beta(a))\\
	&\quad-\tau_{13}\tau_{23}((\id\otimes\tau)(\alpha\otimes \id)\alpha(a)-(\alpha\otimes \id)\alpha(a)).
\end{flalign*}
 Comparing the coefficients of $1\otimes t^{-3}\otimes t^{-1}$, we obtain
\begin{flalign*}
0&=\sum_{(a),[a]} (a_{(1)}\ot a_{(21)}\ot a_{(22)}+a_{[2]}\otimes a_{[1](1)} \otimes a_{[1](2)}-a_{[1](1)}\otimes a_{[2]}\otimes a_{[1](2)}-a_{(21)}\ot a_{(1)}\ot a_{(22)})\\
&=(\id\otimes\beta)\beta(a)+(\tau\otimes \id)((\alpha+\beta)\otimes \id)\beta(a)-((\alpha+\beta)\otimes \id)\beta(a)-(\tau\otimes \id)(\id\otimes \beta)\beta(a)\\
&\quad +(\tau\ot \id)((\id \otimes \tau)(\beta\otimes \id)\alpha(a)-((\alpha+\beta)\otimes \id)\beta(a))\\
&\quad -((\id \otimes \tau)(\beta\otimes \id)\alpha(a)-((\alpha+\beta)\otimes \id)\beta(a)).
\end{flalign*}
Obviously, Eqs. \eqref{cob1}-\eqref{cob4} hold, hence $(A, \alpha ,\beta)$ is a pre-Novikov coalgebra.

This completes the proof.
