\section{Completed pre-Lie bialgebras from pre-Novikov bialgebras and quadratic right Novikov algebras}
In this section, we first give the reason why we choose a quadratic right Novikov algebra instead of a right Novikov dialgebra with a special bilinear form in the finite dimensional case. Then we give a construction of compelted pre-Lie bialgebras from pre-Novikov bialgebras and quadratic $\ZZ$-graded right Novikov algebras and lift the affinization of pre-Novikov algebras to the context of bialgebras.


\subsection{Constructions of finite-dimensional pre-Lie bialgebras from the view of quadratic algebras}\label{3.1}
First, we recall the definition of pre-Novikov bialgebras.
\begin{definition}\cite{LH}
Let $(A, \lhd, \rhd)$ be a pre-Novikov algebra and $(A,\alpha,\beta)$ be a pre-Novikov coalgebra. If they also satisfy the following conditions:
\begin{align}
(\tau\alpha+\beta)(a\circ b)&=((L_{\vartriangleright}+2R_{\vartriangleleft})(a)\otimes \id+ \id\otimes L_{\circ}(a))(\tau\alpha+\beta)(b)\label{lfd1}\\
&\quad+(\id\otimes R_{\circ}(b))(2\tau\alpha+\beta)(a)-(R_{\vartriangleleft}(b)\otimes\id)\tau\alpha (a),\nonumber\\
\tau\alpha(a\circ b-b\circ a)&=((L_{\vartriangleright}+R_{\vartriangleleft})(a)\otimes\id+\id\otimes L_{\circ}(a))\tau\alpha (b)\label{lfd2}\\
&\quad-((L_{\vartriangleright}+R_{\vartriangleleft})(b)\otimes\id+\id\otimes L_{\circ}(b))\tau\alpha (a),\nonumber\\
(\alpha+\beta)(a\vartriangleright b+b\vartriangleleft a)&=(\id\otimes (R_{\vartriangleright}+L_{\vartriangleleft})(b))(2\tau\alpha+\beta)(a)-(L_{\vartriangleleft}(b)\otimes\id)\alpha (a)\label{lfd3}\\
&\quad+((L_{\vartriangleright}+2R_{\vartriangleleft})(a)\otimes\id+\id\otimes(L_{\vartriangleright}+R_{\vartriangleleft})(a))(\alpha+\beta)(b),\nonumber\\
(\alpha+\beta-\tau\alpha-\tau\beta)(b\vartriangleleft a)&=(\id\otimes L_{\vartriangleleft}(b))(\tau\alpha+\beta)(a)-( L_{\vartriangleleft}(b)\otimes \id)(\alpha+\tau\beta)(a)\label{lfd4}\\
&\quad+(\id\otimes R_{\vartriangleleft}(a))(\alpha+\beta)(b)-(R_{\vartriangleleft}(a)\otimes\id)(\tau\alpha+\tau\beta)(b),\nonumber\\
(\id\otimes R_{\circ}(b)-R_{\vartriangleleft}&(b)\otimes\id)(\tau\alpha+\beta)(a)=(\id\otimes R_{\circ}(a)-R_{\vartriangleleft}(a)\otimes\id)(\tau\alpha+\beta)(b),\label{lfd5}\\
\tau\alpha(a\circ b)&=(\id\otimes R_{\circ}(b))\tau\alpha(a)+((L_{\vartriangleright}+R_{\vartriangleleft})(a)\otimes\id)(\tau\alpha+\beta)(b),\label{lfd6}\\
(\id\otimes(R_{\vartriangleright}+L_{\vartriangleleft})(b))\tau\alpha(a)&=((R_{\vartriangleright}+L_{\vartriangleleft})(b)\otimes \id)\alpha(a)+(\id \otimes(L_{\vartriangleright}+R_{\vartriangleleft})(a))(\tau\alpha+\tau\beta)(b)\label{lfd7}\\
&\quad-((L_{\vartriangleright}+R_{\vartriangleleft})(a)\otimes\id)(\alpha+\beta)(b),\nonumber\\
(\alpha+\beta)(b\vartriangleleft a)&=(\id\otimes(R_{\vartriangleright}+L_{\vartriangleleft})(b))(\tau\alpha+\beta)(a)+(R_{\vartriangleleft}(a)\otimes\id)(\alpha+\beta)(b),\;\;a, b\in A,\label{lfd8}
\end{align}
then we call $(A,\vartriangleleft,\vartriangleright,\alpha,\beta)$ a \textbf{pre-Novikov bialgebra}.
\end{definition}

\begin{example}\label{ex1}\cite{LH}
Let $(A=\mathbf{k}e_1\oplus \mathbf{k}e_2,\vartriangleleft,\vartriangleright)$ be a two-dimensional vector space with binary operations
$\vartriangleleft,\vartriangleright$ given by
\begin{flalign*}
&e_i\vartriangleright e_j=0, \;\;i,j\in\{1,2\},\\
e_1\vartriangleleft e_1=e_1,\quad &e_1\vartriangleleft e_2=e_2,\quad e_2\vartriangleleft e_1=e_2,\quad e_2\vartriangleleft e_2 =0.
\end{flalign*}
Then $(A,\vartriangleleft,\vartriangleright)$ is a pre-Novikov algebra. Define linear maps $\alpha,\beta:A\rightarrow A\otimes A$ by
\begin{flalign*}
&\alpha(e_1)=e_2\otimes e_2, \quad \ \ \alpha(e_2)=0,\\
&\beta(e_1)=-e_2\otimes e_2, \quad  \beta(e_2)=0.
\end{flalign*}
Then $(A,\vartriangleleft,\vartriangleright,\alpha,\beta)$ is a pre-Novikov bialgebra.
\end{example}

\begin{definition}\cite{HBG}
	Let $(A,\circ )$ be a Novikov algebra. If there is a skew-symmetric nondegenerate bilinear form $\omega (\cdot,\cdot)$ on $A$ satisfying
	\begin{align}
		\omega (a\circ b,c)-\omega (a\circ c+c\circ a,b)+\omega (c\circ b,a)=0 ,\quad a,b,c\in A,\label{qn}
	\end{align}
	then $(A,\circ ,\omega(\cdot,\cdot))$ is called a \textbf{quasi-Frobenius Novikov algebra}.
\end{definition}

\begin{proposition}\cite[Theorem 2.10]{LH}\label{qN-PN}
	Let $(A,\circ ,\omega(\cdot,\cdot))$ be a quasi-Frobenius Novikov algebra. Then there is a compatible pre-Novikov algebra structure on $A$ given by
	\begin{align}
		\omega (a\vartriangleright b,c)&=\omega(a\circ c+c\circ a,b),\label{t11}\\
		\omega(a\vartriangleleft b,c)&=\omega(a,c\circ b),\quad a,b,c\in A,\label{t12}
	\end{align}
	such that $(A,\circ )$ is the associated Novikov algebra of $(A,\vartriangleleft,\vartriangleright)$. This pre-Novikov algebra is called the \textbf{associated pre-Novikov algebra} of $(A,\circ ,\omega(\cdot,\cdot))$.
\end{proposition}
\begin{definition}
Let $(A,\vartriangleleft,\vartriangleright)$ be a pre-Novikov algebra. If there is a skew-symmetric nondegenerate bilinear form $\omega(\cdot,\cdot)$ on $A$ such that Eqs. (\ref{t11}) and (\ref{t12}) hold, where $a\circ b=a \vartriangleleft b+a\vartriangleright b$ for all $a$, $b\in A$, then $(A,\vartriangleleft,\vartriangleright, \omega(\cdot,\cdot))$ is called a {\bf quadratic pre-Novikov algebra}.
\end{definition}

\begin{definition}\cite{LH}
	Let $(A,\vartriangleleft,\vartriangleright)$, $(A^*,\vartriangleleft_\ast,\vartriangleright_\ast)$ be pre-Novikov algebras and $(A,\circ)$, $(A^\ast,\circ_\ast)$ be their associated Novikov algebras respectively. If a quasi-Frobenius Novikov algebra $(B, \cdot, \omega(\cdot,\cdot))$ satisfies the following conditions:
	\begin{enumerate}
		\item $B$ is the direct sum of $A$ and $A^*$ as vector spaces,
		\item $(A,\vartriangleleft,\vartriangleright)$ and $(A^*,\vartriangleleft_\ast,\vartriangleright_\ast)$ are pre-Novikov subalgebras of $(B,\trianglelefteq,\trianglerighteq)$, which is the associated pre-Novikov algebra of $(B, \cdot, \omega(\cdot,\cdot))$,
		\item the bilinear form $\omega(\cdot,\cdot)$ on $B=A\oplus A^*$ is given by
		\begin{flalign}
			\omega(a+f,b+g)=\langle f,b\rangle -\langle g,a\rangle,\quad  a,b\in A,\;\;f, g\in A^*,\label{man}
		\end{flalign}
	\end{enumerate}
	then  $(B, \cdot, \omega(\cdot,\cdot))$ is called a {\bf double construction of quasi-Frobenius Novikov algebras} associated to $(A,\vartriangleleft,\vartriangleright)$ and $(A^*,\vartriangleleft_\ast,\vartriangleright_\ast)$. Denote it by $(A\oplus A^*,A,A^*,\omega(\cdot,\cdot))$.
\end{definition}
\begin{remark}\label{rmk1}
In this case, $(B,\trianglelefteq,\trianglerighteq,  \omega(\cdot,\cdot))$ is a quadratic pre-Novikov algebra.
\end{remark}
