Next, we recall some results about pre-Lie bialgebras.

\begin{definition}\cite{Bai1, LZB} \label{pre-lia3}
Let $(L, \circ)$ be a pre-Lie algebra and $(L,
\delta)$ be a pre-Lie coalgebra. If the following
compatibility conditions are satisfied:
\begin{align}
&(\delta-\tau\delta)(a\circ b)-(L_{\circ}(a)\otimes \id)(\delta-\tau\delta)(b)-(\id\otimes L_{\circ}(a))(\delta-\tau\delta)(b)\label{eq:pre-Lbi1}\\
&\quad-(\id\otimes R_{\circ}(b))\delta(a)+(R_{\circ}(b)\otimes \id)\tau\delta(a)=0, \nonumber\\
&\delta(a\circ b-b\circ a)-(\id\otimes (R_{\circ}(b)-L_{\circ}(b)))\delta(a)-(\id \otimes(L_{\circ}(a)-R_{\circ}(a)))\delta(b)\label{eq:pre-Lbi2}\\
&\quad-(L_{\circ}(a)\otimes\id)\delta(b)+(L_{\circ}(b)\otimes\id)\delta(a)=0,\quad     a, b\in L,\nonumber
\end{align}
then we call $(L, \circ,\delta)$ a {\bf pre-Lie bialgebra}.
\end{definition}

Recall that
a Lie algebra $(\mathcal{G},[\cdot, \cdot])$ is called a  \textbf{symplectic Lie algebra} (or \textbf{quasi-Frobenius Lie algebra}) if there is a nondegenerate skew-symmetric bilinear form  $\omega_p(\cdot,\cdot)$ (called a 2-cocycle)  on  $ \mathcal{G} $, that is,
	\begin{align}
		\omega_p ([x,y],z)+\omega_p ([y,z],x)+\omega_p ([z,x],y)=0 ,\quad x,y,z\in \mathcal{G}.
	\end{align}
	We denote it by $(\mathcal{G}, [\cdot, \cdot],\omega_p(\cdot, \cdot))$.

	A symplectic Lie algebra $(\mathcal{G}, [\cdot, \cdot],\omega_p(\cdot, \cdot))$ is called a {\bf para-K$\ddot{\texttt{a}}$hler Lie algebra} if $\mathcal{G}=\mathcal{G}_1\oplus\mathcal{G}_2$ is the direct sum of the underlying vector spaces of two Lie subalgebras in which $\omega_p(\mathcal{G}_i,\mathcal{G}_i)=0$ for $i=1,2$. Denote it by $(\mathcal{G}_1\bowtie\mathcal{G}_2,\mathcal{G}_1,\mathcal{G}_2,\omega_p(\cdot, \cdot))$.


\begin{proposition}\cite{Bai1}\label{qL-PL}
	Let	$(\mathcal{G},[\cdot, \cdot],\omega_p(\cdot, \cdot))$ be a symplectic Lie algebra. Then there is  a compatible pre-Lie algebra structure $\circ$ on $\mathcal{G}$ given by
	\begin{align}\label{t13}
		\omega_p(x\circ y,z)=-\omega_p(y,[x,z]),\quad x,y,z\in \mathcal{G}.
	\end{align}
\end{proposition}

\begin{definition}\cite{LZB}
Let $(L, \circ)$ be a pre-Lie algebra. If  there is a nondegenerate skew-symmetric bilinear form $\omega_p(\cdot,\cdot)$ on $L$ such that Eq. (\ref{t13}) holds, where $[x,z]=x\circ z-z\circ x$ for all $x$, $z\in L$, then $(L, \circ, \omega_p(\cdot,\cdot))$ is called a {\bf quadratic pre-Lie algebra}.
\end{definition}

\begin{remark}\label{rmk2}
By Proposition \ref{qL-PL}, for a para-K$\ddot{\texttt{a}}$hler Lie algebra $(\mathcal{G}, [\cdot, \cdot],\omega_p(\cdot, \cdot))$, there is a  quadratic pre-Lie algebra $(\mathcal{G}, \circ,\omega_p(\cdot, \cdot))$.
\end{remark}
