\subsection{A general construction of completed pre-Lie bialgebras from pre-Novikov bialgebras and quadratic $\mathbb{Z}$-graded right Novikov algebras}

Based on the discussion in Section \ref{3.1}, for lifting the conclusion of Theorem \ref{di-pre-L} to a bialgebraic version, we need to replace right Novikov dialgebras by right Novikov algebras.


First, we recall some basic facts about quadratic $\mathbb{Z}$-graded right Novikov algebras.

\begin{definition}\mlabel{def:quad}\cite{HBG}
Let $(B=\oplus_{i\in \ZZ}B_i, \diamond)$ be a $\ZZ$-graded right Novikov algebra. A bilinear form
$(\cdot,\cdot)$  on $B$ is called {\bf graded} if there exists some $m\in \ZZ$ such that
\begin{eqnarray*}
(B_i,B_j)=0, \;\;\; \text{for any $i$, $j\in \mathbb{Z}$ satisfying $i+j+m\neq 0$.}
\end{eqnarray*}
\delete{The bilinear form is called {\bf invariant} if it satisfies
\begin{eqnarray}\label{Rbilinear1}
(a\diamond b,c)=-(a, b\diamond c+c\diamond b),\quad a,b,c\in B.
\end{eqnarray}}
A {\bf quadratic  $\ZZ$-graded right Novikov algebra}, denoted by $(B=\oplus_{i\in \ZZ}B_i, \diamond,
(\cdot,\cdot))$, is a $\ZZ$-graded right Novikov algebra $(B,\diamond)$ together
with a symmetric  nondegenerate graded bilinear form
$(\cdot,\cdot)$ satisfying Eq. (\ref{Nov-qua}).  In particular, when $B=B_0$, then it is just a quadratic right Novikov algebra.
\end{definition}
For a quadratic $\ZZ$-graded right Novikov algebra $(B=\oplus_{i\in \ZZ}B_i, \diamond, (\cdot, \cdot))$, the nondegenerate symmetric bilinear form $(\cdot,\cdot)$ induces multilinear forms $(\cdot,\cdot)_k, k\geq 2$, by
\vspace{-.2cm}
{\small
\begin{equation} \label{eq:pairb}
(\cdot,\cdot)_k: (\underbrace{B\hatot \cdots \hatot
B}_{k\text{-fold}}) \ot (\underbrace{B \ot \cdots \ot
B}_{k\text{-fold}}) \to \bfk,
    \Big(\hspace{-.3cm}\sum_{i_1,\cdots,i_k,\alpha} a_{1i_1\alpha}\ot \cdots \ot a_{ki_k\alpha}, b_1\ot \cdots \ot b_k\Big)_k\coloneqq \hspace{-.4cm}\sum_{i_1,\cdots,i_k,\alpha} \prod_{\ell=1}^k(a_{\ell i_\ell\alpha}, b_\ell)
\end{equation}
}
with the notation in Eq.~\eqref{eq:ssum} and homogeneous elements $b_i\in B$.
Further the forms are {\bf left nondegenerate} in the sense that if
$$\Big(\sum_{i_1,\cdots, i_k,\alpha} a_{1i_1\alpha}\ot \cdots \ot a_{ki_k\alpha}, b_1\ot \cdots \ot b_k\Big)_k=\Big(\sum_{j_1,\cdots, j_k,\beta} b_{1j_1\beta}\ot \cdots \ot b_{kj_k\beta}, b_1\ot \cdots \ot b_k\Big)_k
$$
for all homogeneous elements $b_1, \ldots,b_k\in B$, then
$$\sum_{i_1,\cdots, i_k,\alpha} a_{1i_1\alpha}\ot \cdots \ot a_{ki_k\alpha}=\sum_{j_1,\cdots, j_k,\beta} b_{1j_1\beta}\ot \cdots \ot b_{kj_k\beta}.
$$
%

\begin{example}\label{Laurent-Bilinear}\cite{HBG}
Let $(B=\oplus_{i\in \mathbb{Z}}{\bf k}t^i, \diamond)$ be the $\mathbb{Z}$-graded right Novikov algebra given in Example \ref{rN-ex}.
Define a bilinear form $(\cdot,\cdot)$ on $B$ by
\begin{eqnarray}\label{Laurent-Bilinear-1}
(t^i,t^j)=\delta_{i+j+1,0}, ~~~~~i, j\in \mathbb{Z}.
\end{eqnarray}
Then $(B={\bf k}[t,t^{-1}], \diamond, (\cdot, \cdot))$
is a quadratic $\mathbb{Z}$-graded right Novikov algebra.
\end{example}

\begin{example}\label{quadratic-ex}\cite{HBG}
