	%\vspb
	%\end{eqnarray*}
 Then $(B, \diamond, (\cdot,\cdot ))$ is a quadratic right Novikov algebra.
\end{example}

\begin{lemma}\mlabel{lem:cop}\cite{HBG}
Let $(B=\oplus_{i\in \ZZ}B_i, \diamond, (\cdot, \cdot))$ be a quadratic $\ZZ$-graded right Novikov algebra. Let $\Delta:B\rightarrow B\hatot B$ be the dual of $\diamond$ under the left nondegenerate bilinear form in Eq.~\eqref{eq:pairb}, that is,
\begin{equation}\label{eq:coproduct-self}
(\Delta(x), y\otimes z)=(x, y\diamond z),\quad x,y,z\in B.
\end{equation}
Then $(B,\Delta)$ is a \complete right Novikov coalgebra.
\end{lemma}


