\begin{definition}\label{pre-lia3}
Let $(L, \circ)$ be a pre-Lie algebra and $(L,
\delta)$ be a \complete pre-Lie coalgebra. If the following
compatibility conditions are satisfied:
\begin{align}
&(\delta-\widehat{\tau}\delta)(a\circ b)-(L_{\circ}(a)\hatot \id)(\delta-\widehat{\tau}\delta)(b)-(\id\hatot L_{\circ}(a))(\delta-\widehat{\tau}\delta)(b)\label{eq:pre-Lbi1}\\
&\quad-(\id\hatot R_{\circ}(b))\delta(a)+(R_{\circ}(b)\hatot \id)\widehat{\tau}\delta(a)=0, \nonumber\\
&\delta(a\circ b-b\circ a)-(\id\hatot (R_{\circ}(b)-L_{\circ}(b)))\delta(a)-(\id \hatot(L_{\circ}(a)-R_{\circ}(a)))\delta(b)\label{eq:pre-Lbi2}\\
&\quad-(L_{\circ}(a)\hatot\id)\delta(b)+(L_{\circ}(b)\hatot\id)\delta(a)=0,\quad     a, b\in L,\nonumber
\end{align}
then we call $(L, \circ,\delta)$ a {\bf \complete pre-Lie bialgebra}. If $L$  is finite-dimensional,  $(L, \circ,\delta)$ is just the usual pre-Lie bialgebra.
\end{definition}

