\section{Completed pre-Lie bialgebras from  pre-Novikov Yang-Baxter equation}
In this section, we construct symmetric completed solutions of the $S$-equation from symmetric solutions of  the pre-Novikov Yang-Baxter equation.

First, we introduce some notations.
Let $(A,\vartriangleleft,\vartriangleright)$ be a pre-Novikov algebra and $(A,\circ)$ be the associated Novikov algebra. For convenience, we define binary operations $\odot$ and $\star$ on $A$ by
$$a\odot b:=a\vartriangleright b+b\vartriangleleft a,\qquad a\star b:=a\circ b+b\circ a, \quad  a,b \in A.$$
Let $V$ be a vector space with a binary operation $\ast$. Let $r=\sum\limits_{i}x_i\otimes y_i \in V\otimes V$ and $r^{'}=\sum\limits_{i}x_i^{'}\otimes y_i^{'} \in V\otimes V$. Set
\begin{eqnarray*}
r_{12}\ast r_{13}^{'}:=\sum_{i,j}x_i\ast x_j^{'}\otimes y_i\otimes y_j^{'},\;r_{13}\ast r_{23}^{'}:=\sum_{i,j}x_i\otimes x_j^{'}\otimes y_i\ast y_j^{'},\\
r_{12}\ast r_{23}^{'}:=\sum_{i,j}x_i\otimes y_i\ast x_j^{'} \otimes y_j^{'},\;r_{23}\ast r_{13}^{'}:=\sum_{i,j}x_j^{'}\otimes x_i\otimes y_i\ast y_j^{'}.\\
\end{eqnarray*}
\begin{definition}\cite{LH}
Let $(A,\vartriangleleft,\vartriangleright)$ be a pre-Novikov algebra, $r\in A\otimes A$ and $(A,\circ)$ be the associated Novikov algebra of $(A,\vartriangleleft,\vartriangleright)$. The following equation
\begin{flalign}
r_{12}\circ r_{13}+r_{23}\odot r_{13}-r_{12}\vartriangleleft r_{23}=0\label{yb}
\end{flalign}
is called the \textbf{pre-Novikov Yang-Baxter equation (p-NYBE)} in $(A,\vartriangleleft,\vartriangleright)$.
\end{definition}


\begin{proposition}\cite{LH}\label{pN-coboundary}
Let $(A,\vartriangleleft,\vartriangleright)$ be a pre-Novikov algebra and $r\in A\otimes A$ be a symmetric solution of p-NYBE in $(A,\vartriangleleft,\vartriangleright)$. Let $\alpha,\beta:A\rightarrow A\otimes A$ be linear maps defined by
\begin{flalign}
\alpha(a):&=(L_{\circ}(a)\otimes \id+\id \otimes(L_{\vartriangleright}+R_{\vartriangleleft})(a))\tau r,\label{e11}\\
\beta(a):&=-(L_{\vartriangleright}(a)\otimes \id+\id \otimes (L_{\circ}+R_{\circ})(a))r, \quad a\in A.\label{e12}
\end{flalign}
Then $(A,\vartriangleleft,\vartriangleright,\alpha,\beta)$ is a pre-Novikov bialgebra.
\end{proposition}

Let ($L=\oplus_{i\in \ZZ}L_i ,\circ )$ be a $\ZZ$-graded pre-Lie algebra.
Suppose that $r=\sum_{i,j,\alpha}a_{i\alpha}\otimes b_{j\alpha}\in L\hatot L$ as in Eq.~\meqref{eq:ssum}.
We denote
\begin{eqnarray*}
&&r_{12}\circ r_{13}:=\!\sum_{i,j,k,l,\alpha, \beta}a_{i\alpha}\circ a_{k\beta}\otimes b_{j\alpha}\otimes b_{l\beta},\;r_{12}\circ r_{23}:=\!\sum_{i,j,k,l,\alpha, \beta}a_{i\alpha}\otimes b_{j\alpha}\circ a_{k\beta}\otimes b_{l\beta},\\
&& [r_{13}, r_{23}]:=\!\sum_{i,j,k,l,\alpha,\beta} a_{i\alpha}\otimes a_{k\beta}\otimes (b_{j\alpha}\circ b_{l\beta}-b_{l\beta}\circ b_{j\alpha}),
\end{eqnarray*}
provided the sums make sense. Note that these sums make sense when $r=\sum_{i\in \ZZ, \alpha} c_{i,\alpha}\otimes d_{-i-s,\alpha}\in L\widehat{\otimes} L $ for some fixed $s\in \ZZ$, which is the case that we are interested in the sequel.

\begin{definition}
Let ($L=\oplus_{i\in \ZZ}L_i ,\circ )$ be a $\ZZ$-graded pre-Lie algebra.
If $r\in L\hatot L$ satisfies the {\bf $S$-equation } (see \cite{Bai1})
$$-r_{12}\circ r_{13}+r_{12}\circ r_{23}+[r_{13}, r_{23}]=0
$$
as an element in $L \hatot L \hatot L$, then $r$ is called a {\bf completed solution of the  $S$-equation} in $L$.
\end{definition}

Next, we present a construction of symmetric completed solutions of the  $S$-equation from symmetric solutions of the p-NYBE.
\begin{theorem}\mlabel{pro:p-NYBE}
Let $(A,\vartriangleleft,\vartriangleright)$ be a pre-Novikov algebra and $\big(B=\oplus_{i\in
\ZZ}B_i,\diamond, (\cdot, \cdot)\big)$ be a quadratic $\ZZ$-graded
right  Novikov algebra. Let $(L:=A\otimes B,\circ)$ be the induced pre-Lie
algebra from $(A,
\vartriangleleft,\vartriangleright)$ and $\big(B=\oplus_{i\in
	\ZZ}B_i,\diamond, (\cdot, \cdot)\big)$ in Theorem \ref{t5}. Suppose that $r=\sum_\alpha x_\alpha\otimes y_\alpha\in
A\otimes A$ is a symmetric solution of p-NYBE in $A$.
Then for a basis $\{e_p\}_{p\in \Pi}$ consisting of homogeneous
elements of $B$ and its homogeneous dual basis $\{f_p\}_{p\in
\Pi}$ associated with the bilinear form $(\cdot, \cdot)$, the
tensor element
\begin{eqnarray}\label{eq:S-e}
r_L\coloneqq \sum_{p\in \Pi} \sum_\alpha
(x_\alpha\otimes e_p)\otimes (y_\alpha\otimes f_p) \in
L \hatot L
\end{eqnarray}
is a symmetric completed solution of the $S$-equation in $L$. Furthermore, if the quadratic $\mathbb{Z}$-graded right Novikov algebra is
$(B, \diamond, (\cdot,\cdot))$ $=({\bf k}[t,t^{-1}], \diamond,
(\cdot, \cdot))$ from Example~\mref{Laurent-Bilinear}, then
\begin{eqnarray}\label{eq:affine} r_L=\sum_{ i\in
\mathbb{Z}}\sum_\alpha x_\alpha t^i\,\otimes \,y_\alpha t^{-i-1}\in L
\hatot  L
\end{eqnarray}
is a symmetric completed solution of the $S$-equation in $L$ if and
only if $r$ is a symmetric solution of  the p-NYBE in $A$.
\end{theorem}
%If $B$ is a finite-dimensional right Novikov algebra, then Eq. \eqref{eq:S-e} is a finite sum.

\begin{proof} Applying the notation in Eq.~\eqref{eq:pairb}, we have
\begin{eqnarray*}
\Big(e_q\otimes e_s, \sum_{p\in \Pi}e_p\otimes
f_p\Big)=\sum_{p\in \Pi}(e_q, e_p)(e_s,f_p)=(e_q, e_s).
\end{eqnarray*}
Due to the bilinear form $(\cdot, \cdot)$ on $B$ is symmetric and nondegenerate, we obtain
$\sum_{p\in \Pi}e_p\otimes f_p=\sum_{p\in
\Pi}f_p\otimes e_p$. Hence, $r_L$ is also symmetric. Therefore we have
\begin{align*}
&\quad-r_{12}\circ r_{13}+r_{12}\circ r_{23}+[r_{13}, r_{23}]\\
&=\sum_{p,q\in \Pi}\sum_{\alpha,\beta} \Big( (-x_\alpha \vartriangleright x_\beta \ot e_p\diamond e_q+x_\beta\vartriangleleft x_\alpha \ot e_q\diamond e_p)\ot (y_\alpha\ot f_p)\ot( y_\beta\ot f_q)\\
&\quad+(x_\alpha\ot e_p)\ot(y_\alpha\vartriangleright x_\beta\ot f_p\diamond e_q-x_\beta\vartriangleleft y_\alpha\ot e_q\diamond f_p)\ot(y_\beta\ot f_q)\\
&\quad+(x_\alpha\ot e_p)\ot(x_\beta\ot e_q)\ot(y_\alpha\vartriangleright y_\beta\ot f_p\diamond f_q-y_\beta\vartriangleleft y_\alpha\ot f_q\diamond f_p\\
&\quad-y_\beta \vartriangleright y_\alpha\ot f_q\diamond f_p+y_\alpha\vartriangleleft y_\beta\ot f_p\diamond f_q)\Big).
\end{align*}
For $s$, $u$, $v\in \Pi$, adopting the notation in Eq.~\eqref{eq:pairb} we have
 \begin{eqnarray*}
	&\Big(e_s\otimes e_u\otimes e_v, \sum\limits_{p,q\in \Pi} e_p\diamond e_q\otimes f_p\otimes f_q\Big)=(e_s, e_u\diamond e_v),\\
	&\Big(e_s\otimes e_u\otimes e_v, \sum\limits_{p,q\in \Pi} e_q\diamond e_p\otimes f_p\otimes f_q\Big)=(e_s, e_v\diamond e_u),\\
	&\Big(e_s\otimes e_u\otimes e_v, \sum\limits_{p,q\in \Pi} e_p\otimes
	f_p\diamond  e_q\otimes f_q\Big)=-(e_s, e_u\diamond e_v+e_v\diamond  e_u).
\end{eqnarray*}
Then by the nondegenerate property of $(\cdot,\cdot)$ on $B$,
we obtain
\begin{eqnarray*}
\sum_{p,q\in \Pi}e_p\otimes f_p\diamond e_q\otimes
f_q=-\sum_{p,q\in \Pi}(e_p\diamond e_q\otimes  f_p\otimes
f_q+e_q\diamond e_p\otimes f_p\otimes f_q).
\end{eqnarray*}
Similarly, we get
\begin{eqnarray*}
&&\sum_{p,q\in \Pi} e_p\otimes e_q\otimes f_p\diamond f_q=-\sum_{p,q\in \Pi}(e_p\otimes e_q\diamond f_p\otimes f_q+e_p\otimes e_q\otimes f_q\diamond f_p),\\
&&\sum_{p,q\in \Pi}e_p\otimes e_q\diamond f_p\otimes
f_q=\sum_{p,q\in \Pi} e_q\diamond e_p\otimes  f_p\otimes
f_q,\\
&&\sum_{p,q\in \Pi} e_p\otimes e_q\otimes
f_q\diamond f_p=\sum_{p,q\in \Pi} e_p\diamond e_q\otimes
f_p\otimes f_q.
\end{eqnarray*}
Then we have
\begin{align*}
&\quad-r_{12}\circ r_{13}+r_{12}\circ r_{23}+[r_{13}, r_{23}]\\
&=\sum_{p,q\in \Pi}\sum_{\alpha,\beta} \Big( (x_\beta\vartriangleleft x_\alpha\ot e_q\diamond e_p)\ot( y_\alpha\ot f_p)\ot(y_\beta\ot f_q)\\
&\quad-(x_\alpha\ot e_q\diamond e_p)\ot(x_\beta\vartriangleleft y_\alpha \ot f_p)\ot(y_\beta\ot f_q)
-(x_\alpha\ot e_q\diamond e_p)\ot( y_\alpha\vartriangleright x_\beta\ot f_p)\ot(y_\beta\ot f_q)\\
&\quad-(x_\alpha\ot e_q\diamond e_p)\ot( x_\beta\ot f_p)\ot(y_\alpha\vartriangleright y_\beta\ot f_q)
-(x_\alpha\ot e_q\diamond e_p)\ot( x_\beta\ot f_p)\ot(y_\alpha\vartriangleleft y_\beta\ot f_q)\Big)\\
&\quad-\sum_{p,q\in \Pi}\sum_{\alpha,\beta} \Big((x_\alpha \vartriangleright x_\beta\ot e_p\diamond e_q)\ot(y_\alpha \ot f_p)\ot(y_\beta\ot f_q)\\
&\quad+(x_\alpha\ot e_p\diamond e_q)\ot(y_\alpha\vartriangleright x_\beta \ot f_p)\ot(y_\beta\ot f_q)+(x_\alpha\ot e_p\diamond e_q)\ot( x_\beta\ot f_p)\ot(y_\alpha\vartriangleright y_\beta\ot f_q)\\
&\quad+(x_\alpha\ot e_p\diamond e_q)\ot( x_\beta\ot f_p)\ot( y_\beta\vartriangleright y_\alpha\ot f_q)+(x_\alpha\ot e_p\diamond e_q)\ot( x_\beta\ot f_p)\ot(y_\alpha\vartriangleleft y_\beta\ot f_q)\\
&\quad+(x_\alpha\ot e_p\diamond e_q)\ot(x_\beta \ot f_p)\ot( y_\beta\vartriangleleft y_\alpha\ot f_q)\Big)\\
&=(r_{13}\vartriangleleft r_{12}-r_{12}\odot r_{23}-r_{13}\vartriangleright r_{23}-r_{13}\vartriangleleft r_{23})\bullet(e_q\diamond e_p\ot f_p\ot f_q)\\
&\quad-(r_{12}\vartriangleright r_{13}+r_{12}\vartriangleright r_{23}+r_{13}\star r_{23})\bullet (e_p\diamond e_q\ot f_p\ot f_q)\\
&=0.
\end{align*}
