\begin{align*}
&r_{13}\vartriangleleft r_{12}-r_{12}\odot r_{23}-r_{13}\vartriangleright r_{23}-r_{13}\vartriangleleft r_{23}=0,\\
&r_{12}\vartriangleright r_{13}+r_{12}\vartriangleright r_{23}+r_{13}\star r_{23}=0.
\end{align*}
Therefore, $-r_{12}\circ r_{13}+r_{12}\circ r_{23}+[r_{13}, r_{23}]=0$.}} Thus, $r_L$ is a symmetric completed
solution of  S-equation in $L$.

Moreover, if $(B, \diamond, (\cdot, \cdot))=({\bf k}[t,t^{-1}],
\diamond, (\cdot, \cdot))$, then we note that $\{t^{-i-1}|i\in \mathbb{Z}\}$ is the basis of ${\bf k}[t, t^{-1}]$ dual to $\{t^{i}|i\in
\mathbb{Z}\}$ associated with the bilinear form defined by $(t^i, t^j)=\delta_{i+j+1,0}$ for
all $i$, $j\in \mathbb{Z}$. Suppose that $r_L$ given by Eq. \eqref{eq:affine} is a symmetric completed
solution of  the $S$-equation in $L$.
Setting $i=0$, we conclude
that $r$ is symmetric since $\widehat{\tau }r_L=\sum_{ i\in
	\mathbb{Z}}\sum_\alpha y_\alpha t^{-i-1}\otimes x_\alpha t^{i} =\sum_{
	j\in \mathbb{Z}} \sum_\alpha y_\alpha t^{j}\otimes x_\alpha t^{-j-1}$.
%Since $\widehat{\tau }r_L=\sum_{ i\in
%\mathbb{Z}}\sum_\alpha y_\alpha t^{-i-1}\otimes x_\alpha t^{i} =\sum_{
%j\in \mathbb{Z}} \sum_\alpha y_\alpha t^{j}\otimes x_\alpha t^{-j-1}$, we conclude
%that $r$ is symmetric by setting $i=0$.
We compute
\begin{align*}
&0=r_{12}\circ r_{13}+r_{12}\circ r_{23}+[r_{13}, r_{23}]\\
&\ \ =\sum_{i,j\in \mathbb{Z}}\sum_{\alpha,\beta}\Big((jx_\beta\vartriangleleft x_\alpha t^{i+j-1}-ix_\alpha\vartriangleright x_\beta t^{i+j-1})\ot y_\alpha t^{-i-1}\ot y_\beta t^{-j-1}\\
&\quad+x_\alpha t^i\ot(-(i+1)y_\alpha\vartriangleright x_\beta t^{j-i-2}-jx_\beta\vartriangleleft y_\alpha t^{j-i-2})\ot y_\beta t^{-j-1}\\
&\quad+x_\alpha t^i\ot x_\beta t^j\ot(-(i+1)y_\alpha\vartriangleright y_\beta t^{-i-j-3}+(j+1)y_\beta\vartriangleleft y_\alpha t^{-i-j-3}\\
&\quad+(j+1)y_\beta\vartriangleright y_\alpha t^{-i-j-3}-(i+1)y_\alpha\vartriangleleft y_\beta t^{-i-j-3})\Big).
\end{align*}
Comparing the coefficients of $1\otimes t^{-1}\otimes t^{-2}$
yields that $r$ is a symmetric solution of the p-NYBE in
the pre-Novikov algebra $A$.

This completes the proof.
\end{proof}

\begin{example}
Let $(A=\mathbf{k}e_1\oplus \mathbf{k}e_2\oplus \mathbf{k}e_3\oplus \mathbf{k}e_4,\vartriangleleft,\vartriangleright)$ be a 4-dimensional vector space with binary operations
$\vartriangleleft,\vartriangleright$  defined by non-zero products
\begin{flalign*}
	&e_1\vartriangleleft e_1=e_1,\quad e_1\vartriangleleft e_2= e_2\vartriangleleft e_1=e_2,\\
	&e_1\vartriangleright e_3=e_2\vartriangleright e_4=-2e_3,\qquad e_1\vartriangleright e_4=-2e_4,\\
	&e_1\vartriangleleft e_3=e_2\vartriangleleft e_4=e_3\vartriangleleft e_1=e_4\vartriangleleft e_2=e_3,\quad e_1\vartriangleleft e_4=e_4\vartriangleleft e_1=e_4.
\end{flalign*}
One can directly check that $(A,\vartriangleleft,\vartriangleright)$ is a pre-Novikov algebra and $r:= e_2\otimes e_3+e_3\otimes e_2$ is a symmetric solution of  the p-NYBE in the pre-Novikov algebra $(A,\vartriangleleft,\vartriangleright)$.

Let $(B, \diamond, (\cdot, \cdot))=({\bf k}[t,t^{-1}], \diamond, (\cdot, \cdot))$ be the quadratic $\mathbb{Z}$-graded right Novikov algebra given in Example \ref{Laurent-Bilinear}.
Then by Theorem \ref{pro:p-NYBE}, $r_L:=\sum_{ i\in
	\mathbb{Z}}\big( (e_2\ot t^i)\otimes( e_3\ot t^{-i-1})+(e_3\ot t^i)\otimes( e_2\ot t^{-i-1})  \big)$ is a symmetric completed solution of  the $S$-equation in $A\ot B$.

Let  $(C,\tilde{\diamond})$ be the quadratic  right Novikov algebra given in Example \ref{quadratic-ex}. Then by Proposition \ref{pro:p-NYBE}, $\tilde{r_L}:= (e_2\ot x)\otimes( e_3\ot y)+(e_3\ot x)\otimes( e_2\ot y)+(e_2\ot y)\otimes( e_3\ot x)+(e_3\ot y)\otimes( e_2\ot x)  $ is a symmetric solution of the $S$-equation in $A\ot C$.
\end{example}




\begin{proposition}\mlabel{pL-coboundary}
Let $(A, \circ)$ be a \complete pre-Lie algebra and $r\in A\otimes A$ be a symmetric completed solution of the $S$-equation in $(A,\circ)$. Let $\delta:A\rightarrow A\otimes A$ be a linear map defined by
\begin{equation} \label{eq:rdelta}
\delta(a):=(L_{\circ}(a)\hatot  \id+\id \hatot (L_{\circ}(a)-R_{\circ}(a)))r,\quad a\in A.
\end{equation}
 Then $(A,\circ,\delta)$ is a \complete pre-Lie bialgebra.
\end{proposition}
\begin{proof}
The proof follows from the same argument as presented in \cite[proposition 6.1]{Bai1}.
\end{proof}




\begin{proposition}
Under the same assumption as in Proposition~\ref{pro:p-NYBE}, let $\alpha_r,\beta_r:A\rightarrow A\ot A$  be linear maps defined by Eq. \eqref{e11} and Eq. \eqref{e12} with $r\in A\ot A$ and $\delta:L\rightarrow L\hatot L$ be a linear map defined by Eq. \eqref{co-dipL}. Then $(A,\vartriangleleft,\vartriangleright,\alpha_r,\beta_r)$ is a pre-Novikov bialgebra and hence $(L,\circ ,\delta)$ is a completed pre-Lie bialgebra by Theorem \ref{thm-bi}. It coincides with the completed pre-Lie bialgebra with $\delta$ defined by Eq. \eqref{eq:rdelta} through $r_L$ by Proposition \ref{pro:p-NYBE}, where $r_L$ is defined by Eq. \eqref{eq:S-e}. That is, the following diagram commutes:
$$  \xymatrix{
\text{ symmetric solutions}\atop \text{of p-NYBE} \ar[rr]^-{\rm Prop. \ref{pN-coboundary}}   \ar[d]_-{\rm Thm. \mref{pro:p-NYBE}}&& \text{pre-Novikov}\atop \text{ bialgebras} \ar[d]_-{\rm Thm. \mref{thm-bi}}\\
\text{symmetric solutions}\atop \text{of S-equations} \ar[rr]^-{\rm
Prop. \mref{pL-coboundary}}
            && \text{pre-Lie}\atop \text{ bialgebras}  }
$$
\end{proposition}

\begin{proof}
Obviously, $(A,\vartriangleleft,\vartriangleright,\alpha_r,\beta_r)$ is a pre-Novikov bialgebra by Proposition \ref{pN-coboundary}.
By Theorem \ref{thm-bi}, there is a \complete pre-Lie
bialgebra structure $(L, \circ, \delta)$ on
$L$ where $\delta$ is induced from $\alpha_r,\beta_r$ by Eq.
(\mref{co-dipL}). For all $a\in A$, $b\in B$, we have
\begin{eqnarray*}
\delta(a\otimes b)&=& \sum_{i,j,\beta}\sum_\alpha(-(a\vartriangleright x_\alpha\otimes b_{1i\beta})\otimes (y_\alpha\otimes b_{2j\beta})-(x_\alpha\otimes b_{1i\beta})\otimes (a\star y_\alpha\otimes
b_{2j\beta})\\
&&-(x_\alpha\otimes b_{2j\beta})\otimes (a\circ y_\alpha\otimes
b_{1i\beta})-(a\odot x_\alpha\otimes b_{2j\beta})\otimes (y_\alpha\otimes
b_{1i\beta})).
\end{eqnarray*}
On the other hand,
{\small \begin{eqnarray*}
		&&(L_{\circ}(a\otimes b)\hatot  \id+\id \hatot ( L_{\circ}(a\otimes b)-R_{\circ}(a\otimes b)))\sum_{p\in \Pi}\sum_\alpha (x_\alpha\otimes e_p)\otimes (y_\alpha \otimes f_p)\\
		&=&\sum_{p\in \Pi}\sum_\alpha\Big((a\vartriangleright x_\alpha\otimes b\diamond e_p-x_\alpha\vartriangleleft
		a\otimes e_p\diamond b)\otimes (y_\alpha\otimes f_p) \\
		&&\qquad \quad +(x_\alpha\otimes
		e_p)\otimes (a\vartriangleright y_\alpha\otimes b\diamond f_p-y_\alpha\vartriangleleft
		a\otimes f_p\diamond b-y_\alpha\vartriangleright
		a\otimes f_p\diamond b+a\vartriangleleft y_\alpha\otimes b\diamond f_p)\Big).
\end{eqnarray*}}
For the basis elements $e_q$, $e_s\in B$, we have
\begin{eqnarray*}
\Big(e_q\otimes e_s, \sum_{p\in \Pi} b\diamond e_p\otimes
f_p\Big) &=&(e_q,b\diamond e_s)=(-e_q\diamond e_s-e_s\diamond e_q, b).
\end{eqnarray*}
Similarly, we obtain
\begin{eqnarray*}
\Big(e_q\otimes e_s, \sum_{i,j,\beta} b_{1i\beta}\otimes b_{2j\beta}\Big)=(e_q\diamond
e_s, b),~~~\Big(e_q\otimes e_s, \sum_{p\in \Pi} e_p\otimes
f_p\diamond b\Big)=(e_q\diamond e_s,b).
\end{eqnarray*}
 Hence by the nondegeneracy of $(\cdot, \cdot)$, we get
\begin{eqnarray*}
&&\sum_{p\in \Pi} b\diamond e_p\otimes f_p=\sum_{p\in \Pi}b\diamond f_p\otimes e_p=\sum_{p\in \Pi} e_p\otimes b\diamond f_p=-\sum_{i,j,\beta}(b_{1i\beta}\otimes b_{2j\beta}+b_{2j\beta}\otimes b_{1i\beta}),\\
&&\sum_{p\in \Pi}e_p\otimes f_p\diamond b=\sum_{i,j,\beta}
b_{1i\beta}\otimes b_{2j\beta},\qquad\quad\sum_{p\in \Pi}e_p\diamond
b\otimes f_p=\sum_{i,j,\beta} b_{2j\beta}\otimes b_{1i\beta}.
\end{eqnarray*}
Therefore, we obtain
\begin{eqnarray*}
	&&(L_{\circ}(a\otimes b)\hatot  \id+\id \hatot ( L_{\circ}(a\otimes b)-R_{\circ}(a\otimes b)))\sum_{p\in \Pi}\sum_\alpha (x_\alpha\otimes e_p)\otimes (y_\alpha \otimes f_p)\\
	&=&-\sum_{i,j,\beta}\sum_\alpha\Big((a\vartriangleright x_\alpha\otimes b_{1i\beta})\otimes
	(y_\alpha\otimes b_{2j\beta})+(a\vartriangleright x_\alpha\otimes b_{2j\beta})\otimes(y_\alpha\otimes b_{1i\beta})\\
	&&\hspace{0.4cm}+(x_\alpha\vartriangleleft a\otimes b_{2j\beta})\otimes (y_\alpha\otimes b_{1i\beta})
	+(x_\alpha\otimes b_{1i\beta})\otimes (a\vartriangleright y_\alpha\otimes b_{2j\beta})\\
	&&\hspace{0.4cm}+(x_\alpha\otimes b_{2j\beta})\otimes (a\vartriangleright y_\alpha\otimes b_{1i\beta})+(x_\alpha\otimes b_{1i\beta})\otimes (y_\alpha\vartriangleleft a\otimes b_{2j\beta})\Big)\\
	&&\hspace{0.4cm}+(x_\alpha\otimes b_{1i\beta})\otimes (y_\alpha\vartriangleright a\otimes b_{2j\beta})+(x_\alpha\otimes b_{2j\beta})\otimes (a\vartriangleleft y_\alpha\otimes b_{1i\beta})\\
	&&\hspace{0.4cm}+(x_\alpha\otimes b_{1i\beta})\otimes (a\vartriangleleft y_\alpha\otimes b_{2j\beta})\Big)\\
	&=& \delta(a\otimes b).
\end{eqnarray*}

This completes the proof.
\end{proof}




