In \cite{RT23} in the setting with isotropic surface energies, the different scaling behaviour of microstructures with affine boundary conditions was deduced with the behaviour depending only on the complexity of the boundary data encoded in their lamination order.
Here we prove that this remains valid, if in \cref{eq:L1_energy} we consider generic regularization directions. Indeed, due to the one-dimensional structure of the lamination convex hull, it suffices to choose $\mathcal{N} = \{\nu\}$ such that $\nu \cdot e_1 \neq 0$ in order to recover the scaling from \cite{RT23} in which we considered the full gradient in the surface energy.
If, however, $\nu = \pm e_2$, then, the setting indeed changes and the scaling behaviour becomes that of a laminate of one order less.


\begin{thm}
\label{thm:L1_3wells}
Let $\K_3$ be given by \cref{eq:Lorent_wells}, $\Omega = (0,1)^2$, and $\nu \in \S^{1}$.
Consider the energy $E_\epsilon(u,\chi)$ as in \cref{eq:L1_energy} with $\mathcal{N} = \{\nu\}$, $u \in \mathcal{A}_F$, cf. \cref{eq:AdmissibleFunctionsL2}, for $F \in \K_3^{lc}\setminus \K_3$, and $\chi \in BV_\nu(\Omega;\K_3)$. Let $\mathcal{K}^1_3$ and $\mathcal{K}^2_3$ be as in \cref{eq:laminates_order}.
We then have the following scaling laws:
\begin{enumerate}
    \item\label[case]{itm:L1_3wells_i} \emph{First order laminates:} For $F \in \K_3^1$ there are constants $C = C(F) > 0$ and $\epsilon_0 = \epsilon_0(F,\nu)>0$ such that for any $\epsilon \in (0,\epsilon_0)$
    \begin{align*}
       C^{-1} |\nu_1|^{\frac{2}{3}} \epsilon^{\frac{2}{3}} \leq \inf_{\chi \in BV_\nu(\Omega;\K_3)} \inf_{u \in \mathcal{A}_F} E_\epsilon(u,\chi) \leq C |\nu_1|^{\frac{2}{3}} \epsilon^{\frac{2}{3}}.
    \end{align*}
    \item\label[case]{itm:L1_3wells_ii} \emph{Second order laminates:} For $F \in \K_3^2$ there are constants $C = C(F) > 0$ and $\epsilon_0 = \epsilon_0(F,\nu) > 0$ such that for any $\epsilon \in (0,\epsilon_0)$ we have
    \begin{align*}
        C^{-1} \left( |\nu_1|^{\frac{1}{2}} \epsilon^{\frac{1}{2}} + |\nu_2|^{\frac{2}{3}} \epsilon^{\frac{2}{3}} \right) \leq \inf_{\chi \in BV_\nu(\Omega;\K_3)} \inf_{u \in \mathcal{A}_F} E_\epsilon(u,\chi) \leq C \left( |\nu_1|^{\frac{1}{2}} \epsilon^{\frac{1}{2}} + |\nu_2|^{\frac{2}{3}} \epsilon^{\frac{2}{3}} \right).
    \end{align*}
\end{enumerate}
\end{thm}
\begin{rmk}
We highlight that the estimate from \cref{itm:L1_3wells_ii} for the second order laminates in fact includes matching bounds for both the non-degenerate case in which $\nu \cdot e_1 \neq 0$ and the degenerate case in which $\nu \cdot e_1 = 0$. Indeed, by a case distinction, for $F \in \K_3^2$, on the one hand, if $\nu \cdot e_1 \neq 0$ and if $\epsilon_0>0$ is sufficiently small we have that
    \begin{align*}
       C^{-1} |\nu_1|^{\frac{1}{2}} \epsilon^{\frac{1}{2}} \leq \inf_{\chi \in BV_\nu(\Omega;\K_3)} \inf_{u \in \mathcal{A}_F} E_\epsilon(u,\chi) \leq C |\nu_1|^{\frac{1}{2}} \epsilon^{\frac{1}{2}}.
    \end{align*}
    On the other hand, if $\nu \cdot e_1 = 0$, then
    \begin{align*}
        C^{-1} |\nu_2|^{\frac{2}{3}} \epsilon^{\frac{2}{3}} \leq \inf_{\chi \in BV_\nu(\Omega;\K_3)} \inf_{u \in \mathcal{A}_F} E_\epsilon(u,\chi) \leq C |\nu_2|^{\frac{2}{3}} \epsilon^{\frac{2}{3}}.
    \end{align*}
\end{rmk}


\subsubsection{Settings involving a higher number of wells}
\label{sec:introL14}

In order to illustrate that the above phenomenon is no coincidence, we show that it persists for a certain class of diagonal wells $\mathcal{K}_N$ having one-dimensional lamination convex hulls,
which had also been discussed with a full surface energy regularization in \cite{RT23}. Indeed, for $N \leq d+1$ we consider
\begin{align*}
\mathcal{K}_N:= \{A_1,A_2,\dots,A_N\} \subset \R^{d \times d}_{\diag},
\end{align*}
with
    \begin{gather} \label{eq:HigherLaminates_wells}
    \begin{aligned}
        A_1 &= 0, & A_2 & = \diag(1,0,\dots,0), \\
        A_3 &= \diag(\frac{1}{2},1,0,\dots,0), & A_4 &= \diag(\frac{1}{2},\frac{1}{2},1,\dots,0), \\
        A_j & = \diag(\frac{1}{2},\frac{1}{2},\dots,\frac{1}{2},1,0,\dots,0), &&
        \end{aligned}
    \end{gather}
for $j=5,6,\dots,N$, where for $A_j$ the entry $1$ is at the $(j-1)$-th diagonal entry.
For $d=2$ and $N = 3$ the set $\K_3$ is exactly the one defined in \cref{eq:Lorent_wells} above.
As in \cref{sec:introL13}, we again obtain a structure such that the lamination convex hull of the set $\mathcal{K}_N$ consists of one-dimensional segments (see \cref{fig:4_wells}): For $2 \leq \ell \leq N-1$
\begin{align*}
\K_N^{1} &:= \K_N^{(1)} \setminus \K_N = \{ \diag(\alpha,0,0,\dots,0) \in \R^{d \times d}: \alpha \in (0,1)\}, \\
\K_N^2 &:= \K_N^{(2)} \setminus \K_N^{(1)} = \{ \diag(\frac{1}{2},\alpha,0,\dots,0) \in \R^{d \times d}: \alpha \in (0,1) \}, \\
\K_N^3 &:= \K_N^{(3)} \setminus \K_N^{(2)} = \{ \diag(\frac{1}{2},\frac{1}{2},\alpha,0,\dots,0) \in \R^{d \times d}: \alpha \in(0,1)\}, \\
\mathcal{K}_N^{\ell} &:= \K_N^{(\ell)} \setminus \K_N^{(\ell-1)} = \{ \diag(\frac{1}{2},\frac{1}{2},\dots,\frac{1}{2},\alpha,0,\dots,0) \in \R^{d \times d} : \alpha \in (0,1)\},
\end{align*}
where $\K_N^\ell$ then has $(\ell-1)$ entries $1/2$, cf. \cref{sec:prelim_lam} for the definition of $K_N^{(\ell)}$.
Also in this setting, we show that in terms of lower bounds only the direction of the ``inner-most'' lamination is relevant for the scaling of the singularly perturbed model \cref{eq:L1_energy}, i.e. to obtain the ``classical'' isotropic scaling only $\nu \cdot e_1 \neq 0$ is necessary.

