For ease of notation, in this section we consider the row-wise cross product of a vector and a matrix defined by
\begin{align*}
    (v \times M)_j := v_1 M_{j2} - v_2 M_{j1}, \ v \in \R^2, M \in \R^{2 \times 2}, j=1,2.
\end{align*}
In particular, using this notation, there is a rank-one connection between two matrices $A, B \in \R^{2 \times 2}$, i.e., $A-B = a \otimes n$ for $a, n \in \R^2 \setminus \{0\}$, if and only if $A\neq B$ and
\begin{align*}
    n \times (A-B) = 0.
\end{align*}

Given this set-up, our main result is given by the following comparison estimate.

\begin{thm} \label{cor:DiscreteToSharp}
Let $\Omega \subset \R^2$ be an open, bounded polygonal domain. Let $R \in SO(2)$.
   Let $\K = \{A_1,A_2,\dots,A_N\} \subset \R^{2 \times 2}$ and $F \notin \K$.
    Let $p \in [1,\infty)$ and consider $\mathcal{T}_h^R$ defined in \cref{eq:Triangulation}, and the discrete energy $E_{el,h}^{p}(u,\chi)$ for $u \in \mathcal{A}^{p,R}_{h,F}$ and $\chi \in \mathcal{C}^R_h$, cf. \cref{eq:admissible_discrete}, defined in \cref{eq:energy_discrete}.
    Then the following results hold:
    \begin{enumerate}
    \item \emph{Isotropic setting:}
     Assume that for any $A_j, A_k \in \K$ with $j \neq k$ it holds
\begin{align}\label{eq:assumption-wells}
(Re_1) \times (A_j - A_k) \neq 0, \ (Re_2) \times (A_j - A_k) \neq 0, \ \Big(R\begin{psmallmatrix} 1/\sqrt{2} \\ 1/\sqrt{2} \end{psmallmatrix}\Big) \times (A_j - A_k) \neq 0.
\end{align}
   Then, there are constants $C = C(\K,R,p,F,\Omega) > 0$ and $h_0 = h_0(\Omega,R,p)>0$ such that for all $h \in (0,h_0)$
    \begin{align*}
        E_{el,h}^p(u,\chi) \geq C \left( \int_{\Omega} |\nabla u - \chi|^p dx + h \Vert D \chi \Vert_{TV(\Omega)} +h \right).
    \end{align*}
    In particular, we have
    \begin{align*}
        \inf_{u\in\mathcal{A}^{p,R}_{h,F}} \inf_{\chi\in\mathcal{C}^R_h}  E_{el,h}^p(u,\chi) \geq C \Big( \inf_{\chi \in BV(\Omega;\K)} \inf_{\substack{u \in W^{1,p}(\Omega;\R^2) \\ u(x) = Fx  \text{ on } \p \Omega}}\int_{\Omega} |\nabla u - \chi|^p dx + h \Vert D \chi \Vert_{TV(\Omega)} +h\Big).
    \end{align*}
    %with the energy $E_h^{p}(u,\chi) := \int_\Omega |\nabla u - \chi|^p dx + h \Vert D \chi \Vert_{TV(\Omega)}$.

    \item \emph{Anisotropic setting:}
    Assume that there exists $v \in \Big\{e_1, e_2, \begin{psmallmatrix} 1/\sqrt{2} \\ 1/\sqrt{2} \end{psmallmatrix}\Big\}$ such that for any $j\neq k$
    \begin{align}
    \label{eq:assumption-wells-deg}
        (Rw) \times (A_j - A_k) \neq 0, \quad \text{for every } w\in\Big\{e_1,e_2,\begin{psmallmatrix} 1/\sqrt{2} \\ 1/\sqrt{2} \end{psmallmatrix}\Big\}\setminus\{v\}.
    \end{align}
    Then, there are constants $C = C(\K,R,p,F,\Omega,v) > 0$ and $h_0 = h_0(\Omega,R,p)>0$ such that for all $h \in (0,h_0)$
    \begin{align*}
        E_{el,h}^p(u,\chi)  \geq C \left( \int_\Omega|\nabla u - \chi|^p + h \Vert D_{R \nu} \chi \Vert(\Omega)+h\right),
    \end{align*}
    with $\nu \in \S^1$ such that $\nu \cdot v = 0$.
    \end{enumerate}
\end{thm}

We emphasize that the result on the \emph{isotropic} case is not new. It only recovers the setting already analysed in \cite{L09} for the general $N$-well problem in two-dimensions which in \cite{L09} is even considered with $SO(2)$ symmetry. In the two-well case, it recovers the result from \cite{CM99}. Our main contribution is the bound in the \emph{anisotropic} setting. Its proof relies on similar ideas as in \cite{L09}.

\subsubsection{Applications}
\label{sec:intro_appl}
We will consider two prototypical examples -- the Lorent three-well setting and the Tartar square. In both settings, it is interesting to trace the effects of anisotropy.

We begin by discussing the discrete version of the Lorent three-well problem, introduced in \cref{sec:introL13}. It admits laminates up to order two.

\begin{cor}
\label{cor:Lorent_discrte}
    Let $\Omega = (0,1)^2$, $R \in SO(2)$, $\mathcal{T}_h^R$ be the triangulation defined in \cref{eq:Triangulation}, $\K_3$ be given in \cref{eq:Lorent_wells}, and $F \in \K_3^{lc} \setminus \K = \K_3^1 \cup \K_3^2$, cf. \cref{eq:laminates_order}.
    Let $E_{el,h}(u,\chi) := E_{el,h}^2(u,\chi)$ be defined in \cref{eq:energy_discrete} for $p=2$ and $u \in \mathcal{A}^{2,R}_{h,F}$, $\chi \in \mathcal{C}^R_h$, cf. \cref{eq:admissible_discrete}.
    Then there are constants $C = C(R,F) > 0$ and $h_0 = h_0(R,F)> 0$ such that one of the following applies.
    \begin{enumerate}
    \item\label[case]{itm:Lorent_discrete_i} \emph{Isotropic setting.} If $R \in SO(2)$ is such that $R^T e_1 \notin \{\pm e_1, \pm e_2, \pm 2^{-1/2}(e_1+e_2)\}$ we have for any $h \in (0,h_0)$
    \begin{align*}
        \inf_{u \in \mathcal{A}^{2,R}_{h,F}} \inf_{\chi \in \mathcal{C}^R_h} E_{el,h}(u,\chi) \geq \begin{cases}
            C h^{\frac{2}{3}}, & F \in \K_3^1, \\
            C h^{\frac{1}{2}}, & F \in \K_3^2.
        \end{cases}
    \end{align*}
    \item\label[case]{itm:Lorent_discrete_ii} \emph{Anisotropic setting.}
    If $R^T e_1 \in \{\pm e_1, \pm e_2, \pm 2^{-1/2}(e_1+e_2)\}$ it holds for any $h \in (0,h_0)$
    \begin{align*}
        \inf_{u \in \mathcal{A}^{2,R}_{h,F}} \inf_{\chi \in \mathcal{C}^R_h} E_{el,h}(u,\chi) \geq \begin{cases}
            C h, & F \in \K_3^1, \\
            C h^{\frac{2}{3}}, & F \in \K_3^2.
        \end{cases}
    \end{align*}
    \end{enumerate}
    Moreover, the matching upper bounds hold, that is for every $h \in (0,h_0)$
    \begin{align*}
        \inf_{u \in \mathcal{A}^{2,R}_{h,F}} \inf_{\chi \in \mathcal{C}^R_h} E_{el,h}(u,\chi) \leq \begin{cases}
            C^{-1} h^{\frac{2}{3}}, & F \in \K_3^1, \\ C^{-1} h^{\frac{1}{2}}, & F \in \K_3^2,
        \end{cases}
    \end{align*}
    in the \emph{isotropic setting}, and
    \begin{align*}
        \inf_{u \in \mathcal{A}^{2,R}_{h,F}} \inf_{\chi \in \mathcal{C}^R_h} E_{el,h}(u,\chi) \leq \begin{cases}
            C^{-1} h, & F \in \K_3^1, \\ C^{-1} h^{\frac{2}{3}}, & F \in \K_3^2,
        \end{cases}
    \end{align*}
    in the \emph{anisotropic setting}.
\end{cor}

Let us comment on these results. In the isotropic setting, we recover the lower scaling bounds from the continuous setting. A discretized version of the upper bounds from the continuous setting shows that these estimates are sharp. The more interesting setting arises in the anisotropic situation. Here, for second order laminate boundary conditions, the lower bounds also match the anisotropic ones in the Lorent three-well problem in \cref{thm:L1_3wells}. For boundary data consisting of first order laminates, we observe a difference to the continuum -- due to the limitation of the size of the lengths scales, a scaling bound of the order $h$ emerges in the discrete setup, while it vanishes completely in the continuum. Again, a discretization of the upper bounds from the continuous setting yields the sharpness of these estimates. We expect that similar behaviour is observed for other well configurations.

As a second example and as an extreme case, we consider the setting of the Tartar square. This is a setting of four diagonal matrices which play a prominent role both in inner-mathematical settings \cite{T93, MS03, FS08} and materials \cite{CS13,BFKK94,IKRTZ24}. Indeed, while these four diagonal matrices are pairwise incompatible, they still admit microstructure and display a first loss of rigidity in that approximate solutions become flexible.
  They are given by $T_4 := \{A_1,A_2,A_3,A_4\}$ with
  \begin{align} \label{eq:Tartar}
    A_1 &= \begin{pmatrix} -1 & 0 \\ 0 & -3 \end{pmatrix}, & A_2 &= \begin{pmatrix} -3 & 0 \\ 0 & 1 \end{pmatrix}, &  A_3 &= \begin{pmatrix} 1 & 0 \\ 0 & 3 \end{pmatrix}, & A_4 &= \begin{pmatrix} 3 & 0 \\ 0 & -1 \end{pmatrix}.
  \end{align}
As is well-known in the case of the Tartar square, we have that $T_4^{lc} = T_4$, but its quasiconvex hull is given by $T_4^{qc}:= \{J_1, J_2, J_3, J_4 \}^{\textup{conv}} \cup \bigcup\limits_{j=1}^{4}[A_j,J_j]$ (see \cite[Theorem 9.4]{Ri18}), where
for a set $M\subset \R^{d\times d}$, the notation $M^{\textup{conv}}$ denotes the convex hull of $M$. Here the auxiliary matrices $J_1, \dots, J_4$ are given as
  \begin{align} \label{eq:Tartar_aux}
    J_1 &= \begin{pmatrix} -1 & 0 \\ 0 & -1 \end{pmatrix}, & J_2 &= \begin{pmatrix} -1 & 0 \\ 0 & 1 \end{pmatrix}, &  J_3 &= \begin{pmatrix} 1 & 0 \\ 0 & 1 \end{pmatrix}, & J_4 &= \begin{pmatrix} 1 & 0 \\ 0 & -1 \end{pmatrix}.
  \end{align}

With this notation in hand, we prove the following scaling law for the discrete version of the Tartar energy.


\begin{cor}
\label{cor:Tartar_discrete}
    Let $\Omega=(0,1)^2$, $R \in SO(2)$, and let $T_4 = \{A_1,A_2,A_3,A_4\}$ be the Tartar square given in \cref{eq:Tartar} and let $F \in T_4^{qc}\setminus T_4$. Consider the discrete energy $E_{el,h}(u,\chi) := E_{el,h}^2(u,\chi)$ for $u \in \mathcal{A}^{2,R}_{h,F}$, $\chi \in \mathcal{C}^R_h$, cf. \cref{eq:admissible_discrete}, defined in \cref{eq:energy_discrete}.
    Then, for any $R \in SO(2)$ and any $\eta>0$ there exist constants $C_{\eta} >0,C  = C(F,R) >0$ and $h_0 = h_0(F,R) > 0$ such that for all $h \in (0,h_0)$
    \begin{align*}
        \inf_{u \in \mathcal{A}^{2,R}_{h,F}} \inf_{\chi \in \mathcal{C}^R_h} E_{el,h}(u,\chi) \geq C \exp(-C_\eta |\log h|^{\frac{1}{2}+\eta}).
    \end{align*}
\end{cor}

Let us comment on this result. Contrary to the setting from \cref{cor:Lorent_discrte}, the lower scaling bound holds for all lattice structures in our class of lattices, independently of the choice of the rotation $R$.
This is due to the fact that the Tartar square is extremely rigid, in the sense that no rank-one connections are present. Hence, independently of the precise lattice structure, the lower bound directly follows from an application of the isotropic setting from \cref{cor:DiscreteToSharp} for any rotation $R \in SO(2)$. We remark that the lower bound is essentially sharp. An upper bound of the form $C^{-1} \exp(-C' |\log h|^{\frac{1}{2}})$ (with a constant $C'>0$)  had been deduced in \cite{C99}. The loss of $\eta>0$ in the exponent in \cref{cor:Tartar_discrete} is expected to be a technical artifact, which had already been present in the discussion of its continuous counterpart in \cite{RT22}.






\subsection{Relation to the literature}
Let us connect our results to the literature on martensitic phase transformations. In the literature, martensitic phase transformations are considered with various types of surface energies, including sharp \cite{KM1,KM2,CO,CO1}, diffuse \cite{Z14},
mixed ones \cite{BMC09} and discrete regularizations \cite{D03, L01, L09, ABC07}. In fact, Lorent \cite{L09} proved that under additional technical assumptions on the finite element discretization, for a model with frame indifference, the discrete and continuous, diffuse energies are scaling equivalent.
 We refer to \cite{KK11, CC14, CC15, CDZ17, KO19, RTZ19, RRT23, RT24, GRTZ24, TZ24, AKKR24, IKRTZ24} for further results on scaling laws for shape-memory alloys with various types of surface energy regularizations.
Also experimentally, one observes different transitions: In \cite{BvTA86} one observes atomistically sharp interfaces while in \cite{MvTA86} rather diffuse boundaries are observed. Measurements of surface energies are experimentally notoriously difficult and, hence, the precise structure is often not known. Thus, it is particularly important to deduce mathematical results \emph{independently} of the precise form of the surface energies. By discussing the scaling laws from \cite{RT23, RT22} in the context of various surface regularizations, it is our objective to illustrate and prove that these results are rather robust in the choice of the surface energies and to identify for an interesting class of martensitic phase transformations minimal anisotropic conditions recovering the known scaling laws for isotropic singular perturbation contributions.




\subsection{Outline of the article}
The remainder of the article is structured as follows. We begin by discussing some preliminary results in \cref{sec:prelim}. In particular, we recall the relevant $BV$ set-up and the associated high-frequency bounds and the Fourier analysis from \cite{RT22, RT23}. In \cref{sec:L1AnisotropicSurf} we turn to the setting of anisotropic, sharp surface energies. We present both upper and lower bound results in the outlined highly anisotropic settings and thus provide the proofs of \cref{thm:L1_3wells,thm:L1_mult_wells}. In \cref{sec:diffuse} we turn to the discussion of diffuse energies. Here we provide comparison results such as \cref{thm:comparison} which relate diffuse surface energies with the sharp energies and also present the lower bounds in the setting of anisotropic fractional energies. Finally, we consider discrete (anisotropic) situations in \cref{sec:discrete} and present the proof of \cref{cor:DiscreteToSharp} and the applications from \cref{cor:Lorent_discrte,cor:Tartar_discrete}.




\section{Preliminaries}
\label{sec:prelim}

In this section, we collect various auxiliary results which we will use in the following sections.

\subsection{On the lamination convex hull}
\label{sec:prelim_lam}
For the convenience of the reader we recall the lamination convex hull of a set $\K \subset \R^{d\times d}$.

\begin{defi}
\label{def:lam_hull}
Let $\K \subset \R^{d \times d}$. The \emph{lamination convex hull} $\K^{lc}$ of $\K$ is given by
\begin{align*}
\K^{lc}:= \bigcup\limits_{j=0}^{\infty} \K^{(j)},
\end{align*}
where
\begin{align*}
\K^{(0)}:= \K, \
\K^{(j)}:= \{\lambda A + (1-\lambda) B: \ A, B \in \K^{(j-1)}, \ \lambda \in [0,1], \ \rank(A-B) = 1\}.
\end{align*}
For $j\geq 1$, we refer to the elements of $\K^j := \K^{(j)}\setminus \K^{(j-1)}$ as \emph{laminates of order $j$}.
\end{defi}

In what follows below, we will prove that in our geometric settings with anisotropic surface energies, the interaction between the directional dependences in the anisotropy (in the surface energies) and the lamination orders of the boundary data will determine the scaling behaviour of the investigated microstructures.


\subsection{Directional derivative in a $BV$ sense} \label{sec:prelim_directBV}
Given $\Omega\subseteq\R^d$ open, for a function $f \in BV(\Omega;\R^n)$ we denote the total variation norm of the measure $Df$ by
$\Vert Df \Vert_{TV(\Omega)}$.
Building on the definition of $BV$ functions, we consider functions for which only a single directional
derivative exists as a measure.
Let $f \in L^1(\Omega;\R^n)$ and $\nu \in \S^{d-1}$. We write $f \in BV_\nu(\Omega;\R^n)$ if the
distributional derivative of $f$ in direction $\nu$ is a $\R^n$-valued Radon-measure, denoted by $D_\nu f$,
i.e. for every $\phi \in C^\infty_c(\Omega;\R^n)$ it holds that
\begin{align*}
  \int_\Omega f \cdot \p_\nu \phi dx = - \int_\Omega \phi \cdot d(D_\nu f).
\end{align*}
The
total variation norm of this measure, again denoted by $\Vert D_\nu f \Vert_{TV(\Omega)}$, is given as
\begin{align*}
  \Vert D_\nu f \Vert_{TV(\Omega)} = \sup \left\{\int_\Omega f \cdot \p_\nu \phi dx: \phi \in
  C^1_c(\Omega; \R^n), \Vert \phi \Vert_{\infty} \leq 1 \right\}.
\end{align*}

As shown in \cite[Thm 3.103]{AFP00}, for $f \in BV_\nu(\Omega;\R^n)$ it holds
\begin{align} \label{eq:AnisoBV_slicing}
  \Vert D_\nu f \Vert_{TV(\Omega)} = \int_{\Omega_\nu} \Vert Df_y^{\nu} \Vert_{TV(\Omega^{\nu}_{y})} dy,
\end{align}
where we introduce the notation
\begin{align*}
  \Omega_\nu := \Pi_{\nu^\perp} \Omega \subset \R^d
\end{align*}
as the orthogonal projection of $\Omega$ onto $\nu^\perp$, and for $y \in \Omega_\nu$, we set
\begin{align*}
  \Omega^\nu_y := \{t \in \R: y + t \nu \in \Omega\} \subset \R.
\end{align*}
Hence, the total variation norm of $D_\nu f$ is given by integration of the one-dimensional total
variation norms of the distributional derivatives of
\begin{align*}
  f^\nu_y: \Omega^\nu_y \to \R^n, \quad f^\nu_y(t) := f(y+t\nu).
\end{align*}
In particular, for $f \in BV_\nu(\Omega;\R^n)$ for almost every $y \in \Omega_\nu$ we have
$f^\nu_y \in BV(\Omega^\nu_y;\R^n)$.

As a remark,  let $E \subset \Omega$ be a set of finite perimeter, then it holds
\begin{align*}
    \Vert D_\nu \chi_{E} \Vert_{TV(\Omega)} = \int_{\p E \cap \Omega} |n_{\p E} \cdot \nu| d \mathcal{H}^{d-1},
\end{align*}
where $n_{\p E}$ is the outer unit normal of $E$.
We will often exploit this in the sequel.

\subsection{Directional high frequency control}
As a preparation for our discussion of sharp energies, we deduce lower bounds for the surface energies. Here we follow similar ideas as in \cite{CO,CO1,RT22, RRT23} but with only directional control for the surface energies. For the convenience of the reader, we hence recall the arguments.
These arguments use Fourier methods, thus let us recall the definition of the Fourier transform of one-periodic functions $u \in L^2(\T^d;\R^n)$ as $\mathcal{F}[u] \in \ell^2(\Z^d;\C^n)$
\begin{align} \label{eq:FourierTrafo}
    \mathcal{F}[u](k): = \hat{u}(k) := \int_{\T^d} u(x) e^{-2\pi i k \cdot x} dx, \quad k \in \Z^d.
\end{align}
In the following, we often consider the one-periodic extension of a function $u \in L^2((0,1)^d;\R^n)$ without changing the notation and hence also define the Fourier transform of such functions as above.

In order to motivate our arguments in the following sections, we recall part of the strategy from the isotropic setting from \cite{CO,CO1,RT22, RRT23} in two dimensions.
As a central ingredient for the lower bound, we use the surface energy to control high frequencies. More precisely, viewing $\chi \in BV((0,1)^2;\K)$ as a periodic function, we have
\begin{align*}
  \sum_{|k| \geq \lambda} |\hat{\chi}(k)|^2 \leq C \lambda^{-1} (\Vert D \chi \Vert_{TV((0,1)^2)} + \Per((0,1)^2)).
\end{align*}
As a complementary step, the elastic energy is used to control the frequencies of the associated ``multiplier'' in the form of a coercivity bound in the complement of certain non-elliptic regions. The analysis of these multipliers shows that the only regions without coercivity are given by the complement of cones (cf.\ the discussion below).
 As a consequence, it seems natural to conjecture that it suffices to have only control of high frequencies in direction of the axes of these cones instead of requiring control in all directions.



Our first step towards the anisotropic setting, thus, is showing an analogous high frequency control as above, but using only a single direction.
\begin{lem} \label{lem:HighFreqDir}
Let $d\geq 2$, $n \geq 1$, let
  $\Omega = (0,1)^d$, $\nu \in \S^{d-1}$, and $f \in BV_\nu(\Omega;\R^n) \cap L^\infty(\Omega;\R^n)$, then there is a constant $C = C(d) > 0$ independent of $\nu$ and $f$, such that for any $\lambda >0$ it
  holds
  \begin{align*}
    \sum_{k \in \Z^d: |k \cdot \nu| \geq \lambda} |\hat{f}(k)|^2 \leq C \lambda^{-1} \Vert f\Vert_{L^\infty} \left( \Vert D_\nu f \Vert_{TV(\Omega)} + \Vert f \Vert_{L^\infty} \Per(\Omega) \right),
  \end{align*}
  where we extend $f$ one-periodically.
\end{lem}

\begin{proof}
We preliminarily notice that, in the case $\lambda\le1$, the statement is straightforward.
Indeed,
$$
\sum_{k \in \Z^d: |k \cdot \nu| \geq \lambda} |\hat{f}(k)|^2\le\|f\|_{L^2(\Omega)}^2\le\|f\|_{L^\infty(\Omega)}^2\le\lambda^{-1}\|f\|_{L^\infty(\Omega)}^2,
$$
which yields the statement by taking $C\ge\Per(\Omega)^{-1}.$
We are then left to prove the result in the case $\lambda>1$.

We use the notation introduced in \cref{sec:prelim_directBV}, i.e.\ we set $\Omega_\nu = \Pi_{\nu^\perp} \Omega$ the orthogonal projection of $\Omega$ onto $\nu^\perp$, and for $y \in \Omega_\nu$ we set $\Omega_y^\nu = \{t \in \R: y + t \nu \in\Omega\}$.
For given $f \in BV_\nu(\Omega;\R^n)$, we consider the one-periodic extension of $f$. Thus, let us first consider $f \in BV_\nu(\T^d;\R^n)$.

    \emph{Step 1: Estimate on a difference quotient.} We claim that, for every $|h|<1$
    \begin{align} \label{eq:DiffQuotBV}
        \int_{\T^d} \frac{|f(x+h\nu)-f(x)|}{|h|} dx \leq \Vert D_\nu f \Vert_{TV(\T^d)}.
    \end{align}


    To show \cref{eq:DiffQuotBV}, we begin by noting that for a given connected domain of integration $Q \subset \R^d$ and for  $f^\nu_y \in BV(Q^\nu_y;\R^n)$, by the Fundamental Theorem (and approximation), we obtain that
    \begin{align*}
        \int_{Q_y^\nu\cap(Q_y^\nu-h)}|f^\nu_y(t+h) - f^\nu_y(t)| dt \leq |h| \Vert {D}f^\nu_y \Vert_{TV(Q^\nu_y)}.
    \end{align*}

    We choose $Q \subset \R^d$ as a rotated cube with one face in direction $\nu$, such that $\Omega \subset Q\cap(Q-h\nu)$,
    see \cref{fig:HighFreq_Cube}.
    Thus, by \cref{eq:AnisoBV_slicing} and the periodicity of $f$
    \begin{align*}
        \int_{\T^d} |f(x+h\nu) - f(x)| dx &\leq \int_{Q\cap(Q-h\nu)} |f(x+h \nu) - f(x)| dx \\
        &= \int_{Q_{\nu}} \int_{Q_y^\nu\cap(Q_y^\nu-h)} |f^\nu_y(t+h) - f^\nu_y(t)| dt dy \\
        & \leq |h| \int_{Q_{\nu}} \Vert D f^\nu_y \Vert_{TV(Q^\nu_y)} dy = |h| \Vert D_\nu f \Vert_{TV(Q)} \leq |h| C(Q,d) \Vert D_\nu f  \Vert_{TV(\T^d)},
    \end{align*}
    where the constant $C(Q,d) \geq \#\{z \in \Z^d: (\overline{\Omega} + z) \cap Q \neq \emptyset\}> 0$ is chosen large enough and independent of $\nu$ such that it is larger than the number of copies of $\overline{\Omega}$ required to cover $Q$.
