  \emph{Step 2: Fourier estimate.} Let $f \in BV_\nu(\Omega;\R^n) \cap L^\infty(\Omega;\R^n)$ be as in the statement. Then by step 1, the one-periodic extension, still denoted by $f$, satisfies
  \begin{align*}
    \int_{\T^d} \frac{|f(x+h \nu)-f(x)|^2}{|h|} dx \leq 4 \Vert f \Vert_{L^\infty} \int_{\T^d}
    \frac{|f(x+h \nu)-f(x)|}{|h|} dx \leq 4 C \Vert f \Vert_{L^\infty} \Vert D_\nu f \Vert_{TV(\T^d)}.
  \end{align*}

 With this estimate in hand, we can reformulate the difference quotient in Fourier space which turns the estimate into
  \begin{align*}
    4 C \Vert f \Vert_{L^\infty} \Vert D_\nu f \Vert_{TV(\T^d)} \geq |h|^{-1}\sum_{k \in \Z^d} |(e^{2 \pi i h k
    \cdot \nu} -1) \hat{f}(k)|^2.
  \end{align*}
  Integrating this inequality for $L < 1$ over $h \in (-L,L)$, we get
  \begin{align*}
    8 L C \Vert f \Vert_{L^\infty} \Vert D_\nu f \Vert_{TV(\T^d)}& \geq L^{-1} \int_{-L}^L \sum_{k \in \Z^d}
                                                        |e^{2\pi i h k \cdot \nu} -1|^2 |\hat{f}(k)|^2 dh \\
    &= L^{-1} \sum_{k \in \Z^d} |\hat{f}(k)|^2
    \int_{-L}^{L} |e^{2 \pi i h k \cdot \nu}-1|^2 dh.
  \end{align*}
  Calculating the integral on the right-hand side yields for $k \cdot \nu \neq 0$
  \begin{align*}
    \int_{-L}^L |e^{2 \pi i h k \cdot \nu} -1|^2 dh & = \int_{-L}^L (2-2\cos(2\pi h k \cdot \nu)) dh
                                                      = \Big[2h - \frac{2 \sin(2 \pi h k \cdot \nu)}{2
                                                      \pi k \cdot \nu}\Big]_{h = -L}^L \\
    & = 4L - \frac{4 \sin(2 \pi L k \cdot \nu)}{2 \pi k \cdot \nu} \geq 4L - \frac{2}{\pi| k \cdot \nu|}.
  \end{align*}
  Hence, after restricting the series in $k$ to $|k \cdot \nu| \geq L^{-1}$
  \begin{align*}
    8 L C \Vert f \Vert_{L^\infty} \Vert D_\nu f \Vert_{TV(\T^d)} &\geq L^{-1} \sum_{|k \cdot \nu|\geq L^{-1}} |\hat{f}(k)|^2 (4L - \frac{2}{\pi |k\cdot \nu|}) \\
    &\geq L^{-1} \sum_{|k \cdot \nu|\geq L^{-1}}|\hat{f}(k)|^2 (4L - \frac{2}{\pi L^{-1}}) \\
    &=\frac{4\pi-2}{\pi} \sum_{|k \cdot \nu|\geq L^{-1}} |\hat{f}(k)|^2.
  \end{align*}
  Setting $L = \lambda^{-1} <1$, and observing that $\Vert D_\nu f \Vert_{TV(\T^d)} \leq \Vert D_\nu f \Vert_{TV(\Omega)} + \Vert f \Vert_{L^\infty}  \Per(\Omega)$, shows the statement.
\end{proof}


\subsection{Fourier localization}
In this section we recall some of the relevant tools to derive our Fourier-based lower bounds in \cref{sec:intro_L1}. They build on the strategy from \cite{RT23}, see also \cite{CO1,KW16}.
For this we introduce the following truncated cone for $j \in \{1,2,\dots,d\}$ and $\mu, \lambda > 0$
\begin{align} \label{eq:TruncCone_1}
    C_{j,\mu,\lambda} &:= \{k \in \Z^d: |k|^2 - k_{j}^2 \leq \mu^2 |k|^2, \ |k_{j}| \leq \frac{2}{|\nu_1|} \lambda \},
\end{align}
and the following (infinitely extended) cones %for $j \in \{1,2,\dots,d\}$ and $\mu > 0$
\begin{align} \label{eq:Cone_j}
    C_{j,\mu} &:= \{k \in \Z^d: |k|^2 - k_j^2 \leq \mu^2 |k|^2\}.
\end{align}
For these cones let $m_{j,\mu,\lambda}(D), m_{j,\mu}(D)$ be the corresponding Fourier multipliers acting on $f \in L^2(\T^d;\R)$ as
\begin{align*}
    m_{j,\mu,\lambda}(D) f(x) & = \sum_{k \in \Z^d} m_{j,\mu,\lambda}(k) \hat{f}(k) e^{2 \pi i k \cdot x}.
\end{align*}
They are given (for instance) by
\begin{align} \label{eq:multiplier}
    \begin{split}
    m_{j,\mu,\lambda}(k) &= \big(1-\varphi(2|k|)\big)\varphi\Big(\frac{\sqrt{|k|^2-k_{j}^2}}{\mu |k|} \Big) \varphi\Big(\frac{|\nu_1||k_{j}|}{2 \lambda}\Big) + \varphi(2|k|) \in C^\infty(\R^d), \\
    m_{j,\mu}(k) &= \big(1-\varphi(2|k|)\big)\varphi\Big(\frac{\sqrt{|k|^2-k_j^2}}{\mu |k|} \Big)  + \varphi(2|k|) \in C^\infty(\R^d),
    \end{split}
\end{align}
where
\begin{align*}
        \varphi \in C^\infty([0,+\infty);[0,1]), \quad \varphi(x) = 1,\varphi'(x)\le0, x \in [0,1], \quad \varphi(x) = 0, x \notin (0,2).
    \end{align*}
    Thus the multipliers satisfy for $k \in \Z^d$
    \begin{align*}
        m_{j,\mu,\lambda}(k) & = 1, \ k \in C_{j,\mu,\lambda}, & m_{j,\mu,\lambda}(k) & = 0, \ k \notin C_{j,2\mu,2\lambda}, \\
        m_{j,\mu}(k) & = 1, \ k \in C_{j,\mu} & m_{j,\mu}(k) & =0, \ k \notin C_{j,2\mu}.
    \end{align*}
    With this choice of multipliers we are able to apply Marcinkiewicz's multiplier theorem \cite[Cor. 6.2.5]{Grafakos} (combined with the transference principle \cite[Thm. 4.3.7]{Grafakos}).
    These multipliers have been considered in the context of shape-memory alloys in \cite{RT22,RT23}.

We start by giving a Fourier interpretation of the elastic energy. For notational convenience, here and in what follows below, we will use the notation $\R^{d \times d}_{\diag}$ to denote the diagonal matrices.

\begin{lem} \label{lem:ElasticFourier}
Let $d \geq 2$ and $\Omega = (0,1)^d$.
For $u \in H^1_0(\Omega;\R^d)$ and $\chi \in L^2(\Omega;\R^{d \times d}_{\diag})$ let the elastic energy $E_{el}(u,\chi)$ be given by
\begin{align*}
    E_{el}(u,\chi) = \int_\Omega |\nabla u - \chi|^2 dx.
\end{align*}
Then,
\begin{align*}
    E_{el}(u,\chi) \geq |\hat{\chi}(0)|^2 + \sum_{k \in \Z^d \setminus \{0\}} \sum_{j =1}^d \frac{|k|^2-k_j^2}{|k|^2} |\hat{\chi}_{jj}(k)|^2,
\end{align*}
    where we consider the one-periodic extensions of $u$ and $\chi$ without changing the notation.
\end{lem}

\begin{proof}
    We consider the one-periodic extensions of $u$ and $\chi$ and switch to Fourier space
    \begin{align*}
        E_{el}(u,\chi) =|\hat{\chi}(0)|^2 + \sum_{k \in \Z^d \setminus \{0\}} |2 \pi i \hat{u} \otimes k - \hat{\chi}|^2.
    \end{align*}
    For any given $\chi$, we solve the related Euler-Lagrange equation.
    That is, we choose $\hat{u}(k)$ such that it fulfils
     \begin{align*}
     2 \pi i (\hat{u} \otimes k ) k = \hat{\chi} k, \quad k \neq 0.
     \end{align*}
     Plugging this choice of $\hat{u}(k)$ into the above Fourier representation and using that $\chi$ is diagonal then gives the desired result.
\end{proof}

Combining \cref{lem:HighFreqDir,lem:ElasticFourier}, we can deduce a first Fourier localization argument.
\begin{lem} \label{lem:Localization}
Let $d \geq 2$, $\Omega = (0,1)^d$, and $\nu \in \S^{d-1}$ be such that $\nu \cdot e_1 \neq 0$.
Consider the energy to be given for $\epsilon > 0$ and $\chi \in BV_\nu(\Omega;\R^{d \times d}_{\diag})\cap L^\infty(\Omega;\R^{d\times d}_{\diag})$ by
\begin{align*}
    E_\epsilon(\chi) = \inf_{u \in H^1_0(\Omega;\R^d)} \int_\Omega |\nabla u - \chi|^2 dx + \epsilon \Vert D_\nu \chi \Vert_{TV(\Omega)}.
\end{align*}
Extending $\chi$ one-periodically and
considering the cones $C_{1,\mu,\lambda}$ and $C_{j,\mu}$ for $\mu \in (0,\frac{|\nu_1|}{2})$, $\lambda >0$, and $j=2,3,\dots,d$ defined in \cref{eq:TruncCone_1,eq:Cone_j}
it holds
\begin{align*}
    \sum_{k \notin C_{1,\mu,\lambda}} |\hat{\chi}_{11}(k)|^2 + \sum_{j=2}^d \sum_{k \notin C_{j,\mu}} |\hat{\chi}_{jj}(k)|^2 \leq C \left( \mu^{-2} + \Vert \chi \Vert_{L^\infty} (\lambda \epsilon)^{-1} \right) E_\epsilon(\chi) + C \Vert \chi \Vert_{L^\infty}^2 \lambda^{-1} \Per(\Omega),
\end{align*}
where $C = C(d) > 0$ is a constant independent of $\nu,\mu,\lambda$ and $\chi$.
\end{lem}

\begin{proof}
    By \cref{lem:ElasticFourier}, we get
    \begin{align*}
        \inf_{u \in H^{1}_0(\Omega;\R^d)} \int_\Omega |\nabla u - \chi|^2 dx \geq \sum_{j=1}^d \sum_{k \in \Z^d} \frac{|k|^2-k_j^2}{|k|^2} |\hat{\chi}_{jj}(k)|^2,
    \end{align*}
    where we set the multiplier to be equal to one for $k =0$.
    For $j \in \{1,\dots,d\}$ and $k \notin C_{j,\mu}$ it therefore holds
    \begin{align*}
        \frac{|k|^2-k_j^2}{|k|^2} > \mu^2,
    \end{align*}
    and thus
    \begin{align} \label{eq:EllipticityEst}
        \sum_{j=1}^d \sum_{k \notin C_{j,\mu}} |\hat{\chi}_{jj}(k)|^2 \leq \mu^{-2} \sum_{j=1}^d \sum_{k \in \Z^d} \frac{|k|^2-k_j^2}{|k|^2} |\hat{\chi}_{jj}(k)|^2 \leq \mu^{-2} \inf_{u \in H^1_0(\Omega;\R^d)} \int_\Omega |\nabla u - \chi|^2 dx.
    \end{align}

    To improve the estimate on $\chi_{11}$ to a bound outside of the truncated cone $C_{1,\mu,\lambda}$ instead of in the complement of the infinitely extended cone $C_{1,\mu}$, we note that due to the assumptions that $\nu \cdot e_1 \neq 0$ and $\mu < \frac{|\nu_1|}{2}$
    \begin{align*}
        \{k \in \Z^d: |k|^2 - k_1^2 \leq \mu^2 |k|^2, |k \cdot \nu| \leq \lambda \} \subset C_{1,\mu,\lambda}.
    \end{align*}
    Indeed, for $k=(k_1,k')$ and $\nu = (\nu_1,\nu') \neq \pm e_1$, using that $\mu < \frac{|\nu_1|}{2}$, we have $\mu^2/(1-\mu^2) \leq |\nu_1|^2/(4 |\nu'|^2)$.
    Hence, for $k$ such that $|k \cdot \nu| \leq \lambda$ and $|k'|^2=|k|^2 -k_1^2 \leq \mu^2 |k|^2$, by exploiting the reverse triangle inequality we observe that
    \begin{align} \label{eq:ineq_inclusion_cones}
    |k\cdot\nu|=|k_1\nu_1+k'\cdot\nu'|\ge|k_1||\nu_1|-\mu|k||\nu'|\ge|k_1|\Big(|\nu_1|-\frac{\mu|\nu'|}{\sqrt{1-\mu^2}}\Big)\ge|k_1|\frac{|\nu_1|}{2}.
    \end{align}
    Hence, it holds that
    \begin{align*}
        |k_1| \leq \frac{2}{|\nu_1|} \lambda.
    \end{align*}
    Note, that here it is of importance that $\nu_1 \neq 0$. %, for $\nu_1 = 0$ the inclusion is direct. %the sets are not well defined in that case I would say, anyway in the statement we exclude $\nu_1=0$


    By \cref{eq:EllipticityEst,lem:HighFreqDir} it follows that
    \begin{align*}
        \sum_{k \notin C_{1,\mu,\lambda}} |\hat{\chi}_{11}(k)|^2 & \leq \sum_{k\notin C_{1,\mu}} |\hat{\chi}_{11}(k)|^2 + \sum_{|k \cdot \nu| > \lambda} |\hat{\chi}_{11}(k)|^2 \\
        & \leq \mu^{-2} \sum_{k \in \Z^d} \frac{|k|^2-k_1^2}{|k|^2} |\hat{\chi}_{11}(k)|^2 \\
        & \quad + C(d) \lambda^{-1} \Vert \chi_{11} \Vert_{L^\infty} \big( \Vert D_\nu \chi_{11} \Vert_{TV(\Omega)} + \Vert \chi_{11} \Vert_{L^\infty} \Per(\Omega) \big).
    \end{align*}

    Summing this estimate and \cref{eq:EllipticityEst} for $j=2,3,\dots,d$, we get for $\chi \in L^\infty(\Omega;\R^{d\times d}_{\text{diag}})$
    \begin{align*}
        \sum_{k \notin C_{1,\mu,\lambda}} |\hat{\chi}_{11}(k)|^2 + \sum_{j=2}^d \sum_{k \notin C_{j,\mu}} |\hat{\chi}_{jj}(k)|^2
        &\leq C(d)(\mu^{-2} + \Vert \chi \Vert_{L^\infty} (\lambda \epsilon)^{-1}) E_\epsilon(\chi) \\
        & \quad + C(d) \Vert \chi \Vert_{L^\infty}^2 \lambda^{-1} \Per(\Omega).
    \end{align*}
\end{proof}

With this result we have a combination of an ellipticity estimate of the form \cref{eq:EllipticityEst} and a high frequency control in one direction using \cref{lem:HighFreqDir}. The next result provides a low frequency control, with similar methods as in \cite[Lem. 4.2]{RT23}.

\begin{lem} \label{lem:LowFreqEst}
    Assume that the same conditions hold as in \cref{lem:ElasticFourier} and further assume that $\inf_{u \in H^1_0(\Omega;\R^d)} E_{el}(u,\chi) > 0$. Viewing $\chi \in L^2(\Omega;\R^{d \times d}_{\diag})$ as a function on $\T^d$, there is a constant $C > 0$ such that for any $\bar{\lambda}> 1$
    \begin{align*}
        \sum_{|k_1| \leq \bar{\lambda}} |\hat{\chi}_{11}(k)|^2 \leq C \bar{\lambda}^2 \inf_{u \in H^1_0(\Omega;\R^d)} E_{el}(u,\chi).
    \end{align*}
\end{lem}
\begin{proof}
    The proof relies on the diagonal structure of $\chi$ and the zero boundary data which we impose on the functions $u$.
    For $u \in H^1_0(\Omega;\R^d)$, seen as a function on $\T^d$, it holds by Poincar\'e's inequality in $x_2$ and as $\chi_{12} = 0$
    \begin{align*}
        \sum_{|k_1| \leq \bar{\lambda}} |\hat{u}_1(k)|^2 & \leq \int_{\Omega} |u_1(x)|^2 dx \le \int_\Omega |\p_2 u_1(x)|^2 dx \\
        & = \int_\Omega |\p_2 u_1 - \chi_{12}|^2 dx \leq E_{el}(u,\chi).
    \end{align*}
    Choosing $v \in H^1_0(\Omega;\R^d)$ such that $E_{el}(v,\chi) \leq 2 \inf_{u \in H^1_0(\Omega;\R^d)} E_{el}(u,\chi)$, where we use that $\inf_{u \in H^1_0(\Omega;\R^d)} E_{el}(u,\chi) > 0$, implies for $\bar{\lambda} > 1$
    \begin{align*}
        \sum_{|k_1| \leq \bar{\lambda}} |\hat{\chi}_{11}(k)|^2 & \leq 2 \sum_{|k_1| \leq \bar{\lambda}} \Big( |\widehat{\p_1 v_1}(k) - \hat{\chi}_{11}(k)|^2 + |2 \pi i k_1 \hat{v}_1(k)|^2\Big) \\
        & \leq 2 E_{el}(v,\chi) + 8 \pi^2 \bar{\lambda}^2 \sum_{|k_1| \leq \bar{\lambda}} |\hat{v}_{1}(k)|^2 \\
        & \leq C \bar{\lambda}^2 E_{el}(v,\chi) \leq 2 C \bar{\lambda}^2 \inf_{u \in H^1_0(\Omega;\R^d)} E_{el}(u,\chi)
    \end{align*}
    which yields the result.
\end{proof}

As a final ingredient, for more than two wells, we rely on a commutator estimate. With this we can use the truncation of one cone, cf. \cref{lem:Localization}, and carry it over to another one and reduce its size in the process.
This gives rise to an iterative procedure, where the number of iterations determines the scaling in \cref{thm:L1_3wells,thm:L1_mult_wells}.

\begin{lem}[{\cite[Lem. 3]{RT22}, \cite[Prop. 4.6]{RT23}}] \label{lem:CommutatorEst}
    Let $d \geq 2$, $\Omega = (0,1)^d$, $\nu \in \S^{d-1}$ with $\nu \cdot e_1 \neq 0$.
    For $\mu \in (0,\frac{|\nu_1|}{2})$ and $\lambda > 0$,
    let $m_{1,\mu,\lambda}(D)$ be given by \cref{eq:multiplier}.
    Moreover, for $t > 0$ let $\psi_t(x) = \max\{|x|,|x|^t\}$.
    Let $f_1, f_2 \in BV_\nu(\Omega;\R) \cap L^\infty(\Omega;\R)$ and let $g: \R \to \R$ be a polynomial of degree two with $f_2 = g(f_1)$. Then for any $\gamma \in (0,1)$ there is a constant $C = C(g,\gamma,\Vert f_1 \Vert_{L^\infty}) >0$ such that
    \begin{align*}
        \Vert f_2 - g(m_{1,\mu,\lambda}(D) f_1) \Vert_{L^2} \leq C \psi_{1-\gamma}\left( \Vert f_1 - m_{1,\mu,\lambda}(D) f_1 \Vert_{L^2} \right).
    \end{align*}
\end{lem}

\begin{proof}
    By the triangle inequality we can assume without loss of generality that $g(x) = x^2$.
    Invoking Hölder's inequality, we get
    \begin{align*}
        \Vert f_2 - g(m_{1,\mu,\lambda}(D) f_1) \Vert_{L^2} & = \left\Vert f_1^2 - \left( m_{1,\mu,\lambda}(D) f_1 \right)^2 \right\Vert_{L^2} \\
        & \leq \Vert f_1 - m_{1,\mu,\lambda}(D) f_1 \Vert_{L^{2+2\gamma}} \ \Vert f_1 + m_{1,\mu,\lambda}(D) f_1 \Vert_{L^{\frac{2+2\gamma}{\gamma}}}.
    \end{align*}
    By virtue of the interpolation inequality of $L^p$ spaces and the $L^p$-$L^p$ multiplier bounds from Marcinkiewicz's theorem and the transference principle \cite[Cor. 6.2.5, Thm. 4.3.7]{Grafakos}, we get the desired estimate. For details we refer to \cite[Prop. 4.6]{RT23}.
\end{proof}

\begin{cor} \label{cor:CommutatorEst_Applied}
Let $d \geq 2$, $\Omega = (0,1)^d$, $\nu \in \S^{d-1}$ with $\nu \cdot e_1 \neq 0$, $\lambda > 0$, and $\mu \in (0,\frac{|\nu_1|}{16})$.
    %Under the same assumptions as in \cref{lem:Localization}, suppose further that
Let $\chi\in BV_\nu(\Omega;\R^{d\times d}_\diag)\cap L^\infty(\Omega;\R^{d\times d}_\diag)$, extended one-periodically, and suppose that
    \begin{align*}
        \sum_{j=2}^d \alpha_j \chi_{jj} = g(\chi_{11}),
    \end{align*}
    for a polynomial $g: \R \to \R$ of degree two and coefficients $\alpha_j \in \R$.
    Let $m_{j,\mu,\lambda}$ and $m_{j,\mu}$ be as in \cref{eq:multiplier}.
    Then for any $\gamma \in (0,1)$ there is $C = C(d,g,\gamma, \Vert \chi_{11} \Vert_{L^\infty})>0$ such that
    \begin{align} \label{eq:CommutatorEst_Applied_1}
    \begin{split}
        \Big\Vert \sum_{j=2}^d \alpha_j m_{j,\mu}(D) \chi_{jj} - g(m_{1,\mu,\lambda}(D) \chi_{11}) \Big\Vert_{L^2}
        &\leq C \psi_{1-\gamma}(\Vert \chi_{11} - m_{1,\mu,\lambda}(D) \chi_{11} \Vert_{L^2})\\
        &\quad + \sum_{j=2}^d |\alpha_j| \Vert \chi_{jj} - m_{j,\mu}(D) \chi_{jj} \Vert_{L^2}.
        \end{split}
    \end{align}
    Moreover, there is $M >0$ such that for $\lambda_2 = M \mu \lambda < \lambda$ it holds that
    \begin{align*}
        \sum_{j=2}^d |\alpha_j| \Vert \chi_{jj} - m_{j,\mu,\lambda_2}(D) \chi_{jj} \Vert_{L^2}
      & \leq C \psi_{1-\gamma}(\Vert \chi_{11} - m_{1,\mu,\lambda}(D) \chi_{11} \Vert_{L^2}) \\
      & \quad + 2 \sum_{j=2}^d |\alpha_j| \Vert \chi_{jj} - m_{j,\mu}(D) \chi_{jj} \Vert_{L^2}.
    \end{align*}
    % Here $m_{j,\mu,\lambda_2}(D)$ is the Fourier multiplier corresponding to the cone
    % \begin{align} \label{eq:cone_trunc_2}
    %     C_{j,\mu,\lambda_2} = \{ k \in \Z^d: |k|^2-k_j^2 \leq \mu^2 |k|^2, |k_j| \leq \frac{2}{|\nu_1|} \lambda_2\}.
    % \end{align}
\end{cor}

\begin{proof}
    The first statement is a direct consequence of \cref{lem:CommutatorEst} and the triangle inequality:
    \begin{align*}
    &\Big\Vert \sum_{j=2}^d \alpha_j m_{j,\mu}(D) \chi_{jj} - g(m_{1,\mu,\lambda}(D) \chi_{11}) \Big\Vert_{L^2} \\
    &\qquad \leq \Big\Vert \sum_{j=2}^d \alpha_j m_{j,\mu}(D) \chi_{jj} - \sum_{j=2}^d \alpha_j  \chi_{jj} \Big\Vert_{L^2}
         + \Big\Vert \sum_{j=2}^d \alpha_j  \chi_{jj} - g(m_{1,\mu,\lambda}(D) \chi_{11}) \Big\Vert_{L^2} \\
    & \qquad \leq \sum_{j=2}^d |\alpha_j| \Vert \chi_{jj} - m_{j,\mu}(D) \chi_{jj} \Vert_{L^2} + \Vert f_2 - g(m_{1,\mu,\lambda}(D) f_1) \Vert_{L^2},
    \end{align*}
    with $f_1 = \chi_{11}$ and $f_2 = \sum_{j=2}^d \alpha_j \chi_{jj}$.

    To see the second claim, we note that,
    since the support of $\mathcal{F}[g(m_{1,\mu,\lambda}(D) \chi_{11})]$ is contained in $C_{1,2\mu,2\lambda}+C_{1,2\mu,2\lambda}$ (in the sense of the Minkowski sum),
    there is an $M > 0$, independent of $\mu$, $\lambda$, $\nu$, such that with $\lambda_2 = M \mu \lambda$
    \begin{align} \label{eq:convolution_supp}
        \mathcal{F}[g(m_{1,\mu,\lambda}(D) \chi_{11})](k) = 0, \quad \text{for } |k_j| > \frac{2}{|\nu_1|} \lambda_2, \text{ for any } j \in \{2,\dots,d\}.
    \end{align}
    Furthermore, we use that $|m_{j,\mu}(k) - m_{j,\mu,\lambda_2}(k)| \leq \chi_{\{k: |k_j| \geq \frac{2}{|\nu_1|} \lambda_2\}}(k) m_{j,\mu}(k)$, thus
    \begin{align*}
        \Vert m_{j,\mu}(D) \chi_{jj} - m_{j,\mu,\lambda_2}(D) \chi_{jj} \Vert_{L^2} & \leq \Vert \chi_{\{k: |k_j| \geq \frac{2}{|\nu_1|} \lambda_2\}}(D) m_{j,\mu}(D) \chi_{jj} \Vert_{L^2},
    \end{align*}
    and after an application of the triangle inequality
    \begin{align} \label{eq:improving_truncation}
    \begin{split}
        \Vert \chi_{jj} - m_{j,\mu,\lambda_2}(D) \chi_{jj} \Vert_{L^2} & \leq \Vert \chi_{jj} - m_{j,\mu}(D) \chi_{jj} \Vert_{L^2} \\
        & \quad + \Vert \chi_{\{k: |k_j| \geq \frac{2}{|\nu_1|} \lambda_2\}}(D) m_{j,\mu}(D) \chi_{jj} \Vert_{L^2}.
        \end{split}
    \end{align}
    Here, with slight abuse of notation, we define $\chi_{\{k: |k_j| \geq \frac{2}{|\nu_1|} \lambda_2\}}(D)$ as the Fourier multiplier associated with the function $\chi_{\{k: |k_j| \geq \frac{2}{|\nu_1|} \lambda_2\}}(k) $ in Fourier space. 

    Using the fact that as $\mu < \frac{1}{2\sqrt{2}}$ we have $m_{j,\mu}(k) m_{\ell,\mu}(k) = \delta_0(k)$ for $j \neq \ell$, we see that $m_{j,\mu}(D) \chi_{jj}$ and $m_{\ell,\mu}(D) \chi_{\ell \ell}$ have disjoint Fourier support away from zero.
    In particular the functions $\alpha_j \chi_{\{|k_j| \geq 2 |\nu_1|^{-1} \lambda_2\}}(D)m_{j,\mu}(D) \chi_{jj}$ have pairwise disjoint Fourier support, hence, after summing \cref{eq:improving_truncation} over $j = 2, \dots, d$ with the weights $|\alpha_j|$, we get
    \begin{align}
    \label{eq:cor_comm1}
    \begin{split}
        \sum_{j=2}^d |\alpha_j| \Vert \chi_{jj} - m_{j,\mu,\lambda_2}(D) \chi_{jj} \Vert_{L^2} & \leq \sum_{j=2}^d |\alpha_j| \Vert \chi_{jj} - m_{j,\mu}(D) \chi_{jj} \Vert_{L^2}\\
        & \quad + C(d) \Big\Vert \sum_{j=2}^d \alpha_j \chi_{\{|k_j| \geq \frac{2}{|\nu_1|} \lambda_2\}}(D) m_{j,\mu}(D) \chi_{jj} \Big\Vert_{L^2}.
        \end{split}
    \end{align}

    In the following, we write $k = (k_1,k')$ with $k' = (k_2,\dots,k_d) \in \Z^{d-1}$ and also use $|k'|_\infty = \max\{|k_2|,\dots,|k_d|\}$.
    Since $\mu < \frac{1}{4}$, we remark that $\chi_{\{|k_j| \geq \frac{2}{|\nu_1|} \lambda_2\}}(k) m_{j,\mu}(k) = \chi_{\{|k'|_\infty \geq \frac{2}{|\nu_1|} \lambda_2\}}(k) m_{j,\mu}(k)$ for $j=2,\dots,d$ and moreover by \cref{eq:convolution_supp}, we can further control the second term in \cref{eq:cor_comm1} as follows
    \begin{align}
    \label{eq:cor_comm2}
    \begin{split}
        & \Big\Vert \sum_{j=2}^d \alpha_j \chi_{\{|k_j| \geq \frac{2}{|\nu_1|} \lambda_2 \}}(D) m_{j,\mu}(D) \chi_{jj} \Big\Vert_{L^2} \\
        &\qquad = \Big\Vert \chi_{\{|k'|_\infty \geq \frac{2}{|\nu_1|} \lambda_2 \}}(D) \Big( \sum_{j=2}^d \alpha_j m_{j,\mu}(D) \chi_{jj} - g(m_{1,\mu,\lambda}(D) \chi_{11}) \Big) \Big\Vert_{L^2} \\
        &\qquad \leq \Big\Vert \sum_{j=2}^d \alpha_j m_{j,\mu}(D) \chi_{jj} - g(m_{1,\mu,\lambda}(D) \chi_{11}) \Big\Vert_{L^2}.
    \end{split}
    \end{align}

    Thus, gathering \cref{eq:cor_comm1}, \cref{eq:cor_comm2} and the first statement \cref{eq:CommutatorEst_Applied_1}, we can conclude
    \begin{align*}
        \sum_{j=2}^d |\alpha_j| \Vert \chi_{jj} - m_{j,\mu,\lambda_2}(D) \chi_{jj} \Vert_{L^2} & \leq (C(d)+1) \sum_{j=2}^d |\alpha_j| \Vert \chi_{jj} - m_{j,\mu}(D) \chi_{jj} \Vert_{L^2} \\
        & \quad + C(d) \psi_{1-\gamma}(\Vert \chi_{11}- m_{1,\mu,\lambda}(D) \chi_{11} \Vert_{L^2}).
    \end{align*}
\end{proof}

Let us compare the use of the nonlinear relation with the one from \cite{RT23}. In \cite{RT23} the nonlinear relation is exploited in the form $\chi_{kk} = g(\sum_{j \neq k} \alpha_j \chi_{jj})$. This strategy hence requires working with truncated cones in \emph{all but one} direction. In contrast, in the formulation of \cref{cor:CommutatorEst_Applied}, since the polynomial relation is inverted, it is clear why there is only a single truncation necessary in order to ``propagate'' the truncation to the other diagonal entries.


\begin{rmk}\label{rmk:corollary-variant}
In the sequel, when dealing with higher order laminates, we need to iterate the cone localization from above.
For this reason, we will exploit the following variant of \cref{cor:CommutatorEst_Applied}, whose proof is identical.

In the context of \cref{cor:CommutatorEst_Applied}, let $1\le k\le d$ be the component we want to (further) localize and let $\lambda_k>0$ denote the localization length of $\chi_{kk}$.
If $\chi_{kk}$ has the nonlinear relation
$$
\sum_{j=k+1}^d\alpha_j\chi_{jj}=g(\chi_{kk})
$$
then, for any $\gamma\in(0,1)$ and given $\lambda_{k+1}=M\mu\lambda_k$ it holds that
\begin{align*}
\sum_{j=k+1}^d|\alpha_j| \|\chi_{jj}-m_{j,\mu,\lambda_{k+1}}(D)\chi_{jj}\|_{L^2} &\le C\psi_{1-\gamma}\big(\|\chi_{kk}-m_{k,\mu,\lambda_k}(D)\chi_{kk}\|_{L^2}\big) \\
&\qquad +2\sum_{j=k+1}^d|\alpha_j|\|\chi_{jj}-m_{j,\mu}(D)\chi_{jj}\|_{L^2}.
\end{align*}

We will also apply \cref{cor:CommutatorEst_Applied} and the above variant by replacing $\nu\cdot e_1$ with $\nu\cdot e_n$ for some $1\le n\le d$, with the definitions of $C_{j,\mu,\lambda}, C_{j,\mu}, m_{j,\mu,\lambda}$ and $m_{j,\mu}$ modified accordingly.
\end{rmk}


\subsection{Fractional surface energies in $L^2$-based settings}
\label{sec:prelim_frac}

For the proofs of the lower bound of \cref{thm:L1_3wells,thm:L1_mult_wells} we invoke Fourier methods, relying on \cref{lem:HighFreqDir} for the surface energy.
Therefore we can also replace the sharp surface energy by a fractional $L^2$-based surface energy, giving rise to a similar high frequency control as in \cref{lem:HighFreqDir}.

By extending $\chi \in L^\infty((0,1)^d;\R^{d\times d}_\diag)$ one-periodically, we consider for $s \in (0,\frac{1}{2})$
\begin{align*}
    E_{surf}^s(\chi) := \left( \sum_{k \in \Z^d\setminus\{0\}} |k \cdot \nu|^{2s} |\hat{\chi}(k)|^2 \right)^{\frac{1}{2s}}.
\end{align*}
It then follows directly that it holds
\begin{align*}
   \left( \sum_{k \in \Z^d: |k \cdot \nu| \geq \lambda} |\hat{\chi}(k)|^2 \right)^{\frac{1}{2s}} \leq \lambda^{-1} E_{surf}^s(\chi).
\end{align*}

Based on this observation, we have an analogous result as in \cref{lem:Localization}.
\begin{lem} \label{lem:LocalizationFrac}
    Let $d \geq 2$, $\Omega = (0,1)^d$, and $\nu \in \S^{d-1}$ such that $\nu \cdot e_1 \neq 0$.
    Consider for $\epsilon > 0$, $s \in (0,\frac{1}{2})$ and $\chi \in H^s_\nu(\Omega;\R^{d\times d}_{\diag})$, cf. \cref{eq:anisotropic_Hs}, the following energy
    \begin{align*}
        E_{\epsilon,s}(\chi) = \inf_{u \in H^{1}_0(\Omega;\R^d)} \int_{\Omega} |\nabla u - \chi|^2 dx + \epsilon E_{surf}^s(\chi).
    \end{align*}
    Then, it holds
    \begin{align*}
        \sum_{k \not\in C_{1,\mu,\lambda}} |\hat{\chi}_{11}(k)|^2 + \sum_{j=2}^d \sum_{k \notin C_{j,\mu}} |\hat{\chi}_{jj}(k)|^2 \leq \psi_{2s}\big( (\mu^{-2} + (\lambda \epsilon)^{-1}) E_{\epsilon,s}(\chi) \big),
    \end{align*}
    where, for $\mu \in (0,\frac{|\nu_1|}{2})$, $\lambda > 0$, the cones $C_{1,\mu,\lambda},C_{j,\mu}$ are given as in \cref{eq:TruncCone_1,eq:Cone_j}, and $\psi_t(x) = \max\{|x|, |x|^t\}$ for $t > 0$.
\end{lem}
\begin{proof}
    We argue as in the proof of \cref{lem:Localization}.
    By \cref{lem:ElasticFourier} we have
    \begin{align*}
        E_{\epsilon,s}(\chi) \geq \sum_{j=1}^d \sum_{k \in \Z^d} \frac{|k|^2-k_j^2}{|k|^2} |\hat{\chi}_{jj}(k)|^2 + \epsilon \left( \sum_{k \in \Z^d \setminus \{0\}} |k \cdot \nu|^{2s} |\hat{\chi}(k)|^2 \right)^{\frac{1}{2s}}.
    \end{align*}
    Consequently, for $j \in \{1,\dots,d\}$ and $k \notin C_{j,\mu}$ we have $|k|^2 - k_j^2 \geq \mu^2 |k|^2$ and, hence,
    \begin{align*}
        \sum_{j=1}^d\sum_{k \notin C_{j,\mu}} |\hat{\chi}_{jj}(k)|^2 \leq \mu^{-2} \sum_{j=1}^d \sum_{k \in \Z^d} \frac{|k|^2-k_j^2}{|k|^2} |\hat{\chi}_{jj}(k)|^2 \leq \mu^{-2} E_{\epsilon,s}(\chi).
    \end{align*}

    For the surface energy it is immediate that it holds
    \begin{align*}
        \sum_{|k \cdot \nu| \geq \lambda} |\hat{\chi}(k)|^2 \leq \lambda^{-2s} \sum_{k \in \Z^d \setminus \{0\}} |k \cdot \nu|^{2s} |\hat{\chi}(k)|^2 \leq (\lambda \epsilon)^{-2s} E_{\epsilon,s}(\chi)^{2s}.
    \end{align*}
    Moreover, if we combine both the above estimates %and use \cref{eq:ineq_inclusion_cones},
    we arrive at
    \begin{align*}
        \sum_{k \notin C_{1,\mu,\lambda}} |\hat{\chi}_{11}(k)|^2 & + \sum_{j=2}^{d}\sum_{k \notin C_{j,\mu}} |\hat{\chi}_{jj}(k)|^2 \leq \sum_{j=1}^d \sum_{k \notin C_{j,\mu}} |\hat{\chi}_{jj}(k)|^2 + \sum_{|k \cdot \nu| \geq \lambda} |\hat{\chi}_{11}(k)|^2 \\
        & \leq \mu^{-2} E_{\epsilon,s}(\chi) + (\lambda \epsilon)^{-2s} E_{\epsilon,s}(\chi)^{2s} \\
        & \leq 2\max\{ (\mu^{-2} + (\lambda \epsilon)^{-1}) E_{\epsilon,s}(\chi), \big((\mu^{-2} + (\lambda \epsilon)^{-1}) E_{\epsilon,s}(\chi)\big)^{2s}\} \\
        & = 2\psi_{2s}((\mu^{-2} + (\lambda \epsilon)^{-1})E_{\epsilon,s}(\chi))
    \end{align*}
    and the result is proven.
\end{proof}

As we will see below in \cref{sec:L1AnisotropicSurf} an estimate of this form is sufficient to deduce the lower scaling estimates, consequently, we will be able to generalize \cref{thm:L1_mult_wells} to fractional surface energies as stated in \cref{thm:frac_energy}.



\section{Sharp surface energies -- Proofs of \cref{thm:L1_3wells,thm:L1_mult_wells}}
\label{sec:L1AnisotropicSurf}

In this section we focus on the sharp anisotropic surface energies introduced in \cref{sec:intro_L1} and seek to identify minimal assumptions on the surface energy in order to ensure the same scaling as with isotropic surface energy penalizations.





\subsection{Two-well problem}


As motivation, we begin by considering a simple two-well gradient inclusion $\nabla u \in \{0,e_1 \otimes e_1\}$.
In the standard models in the literature a quantification of this problem is most often considered with an isotropic surface penalization.
There are also instances where only the oscillation in $e_1$ direction is penalized, as for instance in the seminal works \cite{KM1,KM2,C1}. As we view the two-well problem as a prototypical model set-up which we will then, in the following sections, generalize to more complex microstructures, we briefly present the proof of \cref{prop:L1_2wells}.


We use similar Fourier methods as in \cite{RT22, RT23} and argue in three steps.
We first give the arguments for the lower and upper bounds in the case of $\nu \cdot e_1 \neq 0$, afterwards we present the upper bound construction for $\nu \cdot e_1 = 0$.
With this we have a full characterisation of which directions are required in the surface energy to have the same scaling as the isotropic surface penalization.

\begin{proof}[Proof of \cref{prop:L1_2wells} for $\nu \cdot e_1 \neq 0$]

  \emph{Step 1: Lower bound.}
  We first assume that $F_\alpha = 0$ and $A-B = e_1 \otimes e_1$,  namely $A=(1-\alpha)e_1\otimes e_1$, $B=-\alpha e_1\otimes e_1$.
  The general case will be recovered at the end of the proof.
  We define for $\chi \in BV_\nu(\Omega;\{A,B\})$
  \begin{align*}
      E_\epsilon(\chi):= \inf_{u \in \mathcal{A}_{F_\alpha}} E_\epsilon(u,\chi) = \inf_{u \in \mathcal{A}_{F_\alpha}} \int_{\Omega} |\nabla u - \chi|^2 dx + \epsilon \Vert D_\nu \chi\Vert_{TV(\Omega)}.
  \end{align*}
  Thus, after
  extending $\chi$ and $\nabla u$ one-periodically, we can apply \cref{lem:ElasticFourier} to obtain
  \begin{align*}
    \int_{\Omega} |\nabla u - \chi|^2 dx \geq \sum_{k \in \Z^d \setminus \{0\}}
    \frac{|k|^2-k_1^2}{|k|^2} |\hat{f}|^2 + |\hat{f}(0)|^2,
  \end{align*}
  where we wrote $f = \chi_{11} \in BV_\nu(\Omega;\{1-\alpha,-\alpha\})$.

\Cref{lem:Localization} then implies for $\mu \in (0,\frac{|\nu_1|}{2})$, $\lambda >1$
\begin{align*}
    \sum_{k \notin C_{1,\mu,\lambda}} |\hat{f}(k)|^2 \leq C(d,\alpha) \Big( (\mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(\chi) + \lambda^{-1} \Per(\Omega) \Big),
\end{align*}
where the truncated cone $C_{1,\mu,\lambda}$ is defined in \cref{eq:TruncCone_1}.

Moreover, by an application of \cref{lem:LowFreqEst} for $\bar{\lambda} = \frac{2}{|\nu_1|} \lambda > 1$, for $\lambda > 1 > \frac{|\nu_1|}{2}$,
\begin{align}\label{eq:LowFreqEst_2wells}
    \sum_{|k_1| \leq 2 \lambda/|\nu_1|} |\hat{f}(k)|^2 \leq C \frac{\lambda^2}{|\nu_1|^2} E_\epsilon(\chi).
\end{align}
With this, we have control over the Fourier mass of $f$ in the whole space partitioned into $\Z^d =(C_{1,\mu,\lambda}^c\cap\Z^d)\cup \{k \in \Z^d :|k_1| \leq \frac{2}{|\nu_1|} \lambda\}$, cf. \cref{fig:TwoWellFourier}, as follows
\begin{align*}
    \sum_{k \in \Z^d} |\hat{f}(k)|^2 & \leq \sum_{|k_1| \leq 2\lambda/|\nu_1|} |\hat{f}(k)|^2 + \sum_{k \notin C_{1,\mu,\lambda}} |\hat{f}(k)|^2 \\
    & \leq C \left( \frac{\lambda^2}{|\nu_1|^2} + \mu^{-2} + (\lambda \epsilon)^{-1} \right) E_{\epsilon}(\chi) + C \lambda^{-1} \Per(\Omega).
\end{align*}

