    \label{fig:branching}
\end{figure}


  In what follows, we now make the $\nu$ dependence explicit by considering the unit-cell construction in more detail.
  The interfaces of the optimal (in the sense of scaling) construction in $\omega$
  (see \cite[Lemma 3.1]{RT23} for details) are either given by a straight line
  with unit normal $e_1$, or normal in direction $(-h, \frac{1-\alpha}{2}\ell)^T$,
  and thus, denoting the normal by $n$, in the first case  it holds that $|n
  \cdot \nu| = |\nu_1|$  and in the second case
  \begin{align*}
  |n \cdot \nu| \leq C(\alpha)( |\nu_1| + \frac{\ell}{h} |\nu_2|).
  \end{align*}
  Hence, through a scaling argument and by summing all the self-similar contributions of $\omega_{j,k}$, we get for sufficiently large $N \in \N$
  \begin{equation}\label{eq:bra1-nu}
      \int_{Q} |\nabla u - \chi|^2 dx + \epsilon \Vert D_\nu \chi \Vert_{TV(Q)}
      \leq C(\alpha) \left( \frac{L^3}{N^2 H}+\epsilon HN|\nu_1|+\epsilon L j_0|\nu_2| \right),
  \end{equation}
  for
  \begin{align*}
      j_0 + 1 \sim \log\Big(\frac{HN}{L}\Big).
  \end{align*}
  We now turn to the case $Q=\Omega$.
  Hence, for $H=L=1$, after optimizing the first two terms in $N$, i.e. choosing $N \sim |\nu_1|^{-1/3} \epsilon^{-1/3}$, we get
  \begin{align*}
      \int_\Omega |\nabla u - \chi|^2 dx + \epsilon \Vert D_\nu \chi \Vert_{TV(\Omega)} \leq C(\alpha) \left(|\nu_1|^{\frac{2}{3}} \epsilon^{\frac{2}{3}} + \epsilon |\log (|\nu_1|\epsilon)| |\nu_2| \right).
  \end{align*}
  Using that $\epsilon |\log(|\nu_1|\epsilon)| |\nu_2| \leq C |\nu_1|^{2/3} \epsilon^{2/3}$ for small $\epsilon < \epsilon_0(|\nu_1|)$, we deduce the desired upper bound.
  \end{proof}

\begin{proof}[Proof of \cref{prop:L1_2wells} for $\nu \cdot e_1 = 0$]
In the case of $\nu \cdot e_1 = 0$ the argument uses that for a simple laminate in $e_1$ direction, we do not pay surface energy, and thus can do an infinitely fine oscillation of the two phases.
Indeed, $E_\epsilon(u,\chi) \geq 0$ is direct. To obtain a suitable upper bound on the energy, we now choose for any $N \in \N$ the functions
\begin{align*}
    \tilde{u}_N(x_1) &= \begin{cases} (1-\alpha) x_1 a & x_1 \in (0,\frac{\alpha}{N}), \\
    - \alpha x_1 a + \frac{\alpha}{N} a& x_1 \in [\frac{\alpha}{N},\frac{1}{N}),
    \end{cases} \\
    \chi_N(x) & = \begin{cases} A & x_1 \in (0,\frac{\alpha}{N}), \\
    B & x_1 \in [\frac{\alpha}{N},\frac{1}{N}),
    \end{cases}
\end{align*}
and extend both $\frac{1}{N}$-periodically.
We fix $u_N \in W^{1,\infty}(\Omega;\R^{d})$ as
\begin{align*}
    u_N(x_1,x') = \tilde{u}_N(x_1) \psi(N \dist(x',\p (0,1)^{d-1})) + F_\alpha x
\end{align*}
for some bump function $\psi \in C^\infty(\R;[0,1])$ such that $\psi(t) = 1$ for $t  \geq 1$ and $\psi(t) = 0$ for $t \leq \frac{1}{2}$.
Here $a \in \R^d \setminus \{0\}$ is given by the relation $A-B = a \otimes e_1$.
We have that $\chi_{N} \in BV(\Omega;\{A,B\})$ and $u_{N} \in W^{1,\infty}(\Omega;\R^{d})$ fulfils the Dirichlet data.
Moreover, as $\nu \cdot e_1 = 0$, it holds
\begin{align*}
    \int_\Omega \chi_N(x) \p_\nu \phi(x) dx = \int_{(0,1)} \chi_N\Big(x_1,\frac{1}{2}\Big) \int_{(0,1)^{d-1}} {\rm div}'(\phi(x_1,x')\nu) dx' dx_1 =  0
\end{align*}
for every $\phi \in C^1_c(\Omega;\R)$, thus $\Vert D_\nu \chi \Vert_{TV(\Omega)} =0$.
Hence, we infer that
\begin{align*}
    E_\epsilon(u_N,\chi_N) = \int_\Omega |\nabla u_N(x) - \chi_N(x)|^2 dx \leq \frac{C}{N}.
\end{align*}
    As the functions $u$ and $\chi$ are admissible for any $N \in \N$, passing to the limit yields the optimal energy $\inf_{\chi \in BV_\nu(\Omega;\{A,B\})} \inf_{u \in \mathcal{A}_{F_{\alpha}}} E_\epsilon(u,\chi) = 0$.
\end{proof}

\subsection{The three-well problem of Lorent}
In this section we now consider the three-well setting due to Lorent. As outlined in \cref{sec:introL13}, in this situation one obtains both first and second order laminates, depending on the boundary condition.


We split the proof of \cref{thm:L1_3wells} into several steps. We start by showing the scaling for $F \in \K_3^1$ for both $\nu \cdot e_1 \neq 0$ and $\nu \cdot e_1 = 0$, both of which are essentially covered by \cref{prop:L1_2wells}. In contrast to the argument given above, due to our specific choices of the possible boundary data, we do not only work with one of the entries of the matrix $\chi-F$ (see the comments in \cref{rmk:lower_bound_first_laminate} below).

In a second step, we will consider $F \in \K_3^2$ where we can exploit the determinedness of $\chi_{22}$ in terms of $\chi_{11}$ to obtain the scaling of second order laminates. Here as long as $\nu \cdot e_1 \neq 0$, we obtain a scaling law of the order $\epsilon^{\frac{1}{2}}$ as in the isotropic setting. If, however, $\nu \cdot e_1 = 0$, the scaling does not change with respect to the one for first order laminates, as we can construct an infinitely fine simple laminate within a branching construction, without paying surface energy for the simple laminate. This then yields the same scaling as in the two-well setting in \cref{prop:L1_2wells}, cf. \cref{fig:LaminateInBranching}.

\begin{lem}
\label{lem:scal-first}
    Under the same assumptions as in \cref{thm:L1_3wells}, let $F_\alpha = \diag(\alpha,0) \in \K_3^1$ for $\alpha \in (0,1)$.
    If $\nu \cdot e_1 \neq 0$ there is a constant $C = C(\alpha) >0$ and $\epsilon_0 = \epsilon_0(\alpha,|\nu_1|) > 0$ such that
    \begin{align*}
    C^{-1} |\nu_1|^{\frac{2}{3}} \epsilon^{\frac{2}{3}} \leq \inf_{\chi \in BV_\nu(\Omega;\K_3)} \inf_{u \in \mathcal{A}_{F_\alpha}} E_\epsilon(u,\chi)  \leq C |\nu_1|^{\frac{2}{3}} \epsilon^{\frac{2}{3}}.
    \end{align*}
    If instead $\nu \cdot e_1 = 0$, we have
    \begin{align*}
        \inf_{\chi \in BV_\nu(\Omega;\K_3)} \inf_{u \in \mathcal{A}_{F_\alpha}} E_\epsilon(u,\chi) = 0.
    \end{align*}
\end{lem}
\begin{proof}

\emph{Upper bounds:}
    As $A_1$ and $A_2$ are rank-one connected in $e_1$ direction, we directly note that the upper bound construction in the proof of \cref{prop:L1_2wells} also yields an upper bound construction in this setting (after an adaptation of parameters). Thus, we have
    \begin{align*}
        \inf_{\chi \in BV_\nu(\Omega;\K_3)} \inf_{u \in \mathcal{A}_{F_\alpha}} E_\epsilon(u,\chi) \leq \begin{cases}
            C(\alpha)|\nu_1|^{\frac{2}{3}} \epsilon^{\frac{2}{3}}, & \nu \cdot e_1 \neq 0, \\
            0, & \nu \cdot e_1 = 0.
        \end{cases}
    \end{align*}

    \emph{Lower bound for $\nu \cdot e_1 \neq 0$:} For any $u\in\mathcal{A}_{F_\alpha}, \chi\in BV_\nu(\Omega;\K_3)$, by considering $\nabla u - F_\alpha$ and $\chi - F_\alpha$, we can reduce to the case $F_\alpha = 0$ (cf.\ proof of \cref{prop:L1_2wells}).
    With a slight abuse of notation, we still write $u$ and $\chi$ for the modified functions, hence $u\in H^1_0(\Omega;\R^2)$ and $\chi \in \K_3 - F_\alpha$.
    For the function $\chi_{11}$ we exploit the same ideas as in the two-well case but will make use of both the $\chi_{11}$ and the $\chi_{22}$ components.
    To be more precise by \cref{lem:ElasticFourier} it holds
    \begin{align*}
        \int_\Omega |\nabla u - \chi|^2 dx \geq \sum_{k \in \Z^2} \left( \frac{|k|^2 - k_1^2}{|k|^2} |\hat{\chi}_{11}(k)|^2 + \frac{|k|^2 - k_2^2}{|k|^2} |\hat{\chi}_{22}(k)|^2 \right) \geq \sum_{k \in \Z^2} \frac{|k|^2 - k_1^2}{|k|^2} |\hat{\chi}_{11}(k)|^2,
    \end{align*}
    where we fix the multipliers to be equal to one in $k = 0$.
    Moreover, it holds
    \begin{align*}
        \Vert D_\nu \chi \Vert_{TV(\Omega)} \geq \Vert D_\nu \chi_{11} \Vert_{TV(\Omega)},
    \end{align*}
    and thus, following the ideas of \cref{prop:L1_2wells}, by \cref{lem:Localization}, we deduce for $\lambda>1$ and $\mu\in(0,\frac{|\nu_1|}{16})$, that
    \begin{align*}
        \Vert \chi_{11} - m_{1,\mu,\lambda}(D) \chi_{11} \Vert_{L^2}^{2} + \Vert \chi_{22} - m_{1,\mu}(D) \chi_{22} \Vert_{L^2}^{2} &\leq \sum_{k \notin C_{1,\mu,\lambda}} |\hat{\chi}_{11}(k)|^2 + \sum_{k \notin C_{2,\mu}} |\hat{\chi}_{22}(k)|^2 \\
        &\leq C (\mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + C \lambda^{-1} \Per(\Omega),
    \end{align*}
    where we consider the smooth cut-off multipliers as in \cref{eq:multiplier}.
    Applying moreover \cref{cor:CommutatorEst_Applied} with $\chi_{22} = -4 (\chi_{11}+\alpha)(\chi_{11}-1+\alpha)$, yields for $\lambda_2=M\mu\lambda < \lambda$ %(if we choose $\mu$ sufficiently small)
    \begin{align*}
        \Vert \chi_{22} - m_{2,\mu,\lambda_2}(D) \chi_{22} \Vert_{L^2}^{2} &\leq C(\alpha) \psi_{1-\gamma}(\Vert \chi_{11} - m_{1,\mu,\lambda}(D) \chi_{11} \Vert_{L^2}^{2}) + 4 \Vert \chi_{22} - m_{2,\mu}(D) \chi_{22} \Vert_{L^2}^{2} \\
        & \leq C(\alpha) \psi_{1-\gamma}\Big((\mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + \lambda^{-1} \Per(\Omega)\Big),
    \end{align*}
    with $\psi_{1-\gamma}(x) = \max\{|x|,|x|^{1-\gamma}\}$.

    In conclusion, using that $1-m_{2,\mu,\lambda_2}(k) \geq 1 - m_{2,\mu,\lambda}(k) \geq 0$,
    \begin{align*}
       & \Vert \chi_{11}-m_{1,\mu,\lambda}(D) \chi_{11} \Vert_{L^2}^{2} + \Vert \chi_{22} - m_{2,\mu,\lambda}(D) \chi_{22} \Vert_{L^2}^{2} \\
       &\leq C \psi_{1-\gamma}\Big((\mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + \lambda^{-1} \Per(\Omega)\Big).
    \end{align*}
    Applying \cref{lem:LowFreqEst} for both $\chi_{11}$ and $\chi_{22}$ with the frequency cut-off given by $\bar{\lambda} = \frac{4}{|\nu_1|} \lambda$ we get
    \begin{align*}
        \Vert \chi_{11} \Vert_{L^2}^{2} + \Vert \chi_{22} \Vert_{L^2}^{2} & \leq 2 \Vert \chi_{11} - m_{1,\mu,\lambda}(D) \chi_{11} \Vert_{L^2}^{2} + 2 \sum_{|k_1| \leq \frac{4}{|\nu_1|} \lambda} |\hat{\chi}_{11}(k)|^2 + \\
        & \quad + 2 \Vert \chi_{22} - m_{2,\mu,\lambda}(D) \chi_{22} \Vert_{L^2}^{2} + 2 \sum_{|k_2| \leq \frac{4}{|\nu_1|}\lambda} |\hat{\chi}_{22}(k)|^2 \\
        & \leq C \psi_{1-\gamma}\Big((\mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + \lambda^{-1} \Per(\Omega)\Big)\\
        & \quad + C |\nu_1|^{-2} \lambda^2 E_\epsilon(u,\chi) \\
        & \leq C \psi_{1-\gamma}\Big((|\nu_1|^{-2} \lambda^2 + \mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + \lambda^{-1} \Per(\Omega)\Big).
    \end{align*}
    Fixing $\mu^{-2} \sim |\nu_1|^{-2} \lambda^2$ and $\lambda \sim |\nu_1|^{2/3} \epsilon^{-1/3}$ (which are compatible with the constrains $\mu<\frac{|\nu_1|}{16}$ and $\bar\lambda>1$) yields
    \begin{align}
    \label{eq:second_trunc}
        \Vert \chi_{11} \Vert_{L^2}^{2} + \Vert \chi_{22} \Vert_{L^2}^{2} \leq C \psi_{1-\gamma}\Big(|\nu_1|^{-\frac{2}{3}} \epsilon^{-\frac{2}{3}} E_\epsilon(u,\chi) + |\nu_1|^{-\frac{2}{3}} \epsilon^{\frac{1}{3}} \Per(\Omega)\Big).
    \end{align}

    By the fact that $\Vert \chi_{11} \Vert_{L^2}^{2} + \Vert \chi_{22} \Vert_{L^2}^{2} = \Vert \chi \Vert_{L^2}^{2} \geq c > 0$, we can show the desired lower bound for $\epsilon < \epsilon_0(|\nu_1|,\alpha)$.
    Indeed, we have either
    \begin{align*}
        C \leq |\nu_1|^{-\frac{2}{3}} \epsilon^{-\frac{2}{3}} E_\epsilon(u,\chi) + |\nu_1|^{-\frac{2}{3}} \epsilon^{\frac{1}{3}} \Per(\Omega),
    \end{align*}
    or
    \begin{align*}
        C^{\frac{1}{1-\gamma}} \leq |\nu_1|^{-\frac{2}{3}} \epsilon^{-\frac{2}{3}} E_\epsilon(u,\chi) + |\nu_1|^{-\frac{2}{3}} \epsilon^{\frac{1}{3}} \Per(\Omega),
    \end{align*}
    depending on the case distinction in $\psi_{1-\gamma}$. In conclusion, after absorbing the perimeter term, we arrive at
    \begin{align*}
        E_{\epsilon}(u,\chi) \geq \frac{1}{2}\min\{C,C^{\frac{1}{1-\gamma}}\} |\nu_1|^{\frac{2}{3}} \epsilon^{\frac{2}{3}}.
    \end{align*}
\end{proof}

\begin{rmk} \label{rmk:lower_bound_first_laminate}
Let us comment on a technical aspect which is specific to our anisotropic surface energies and which does not arise in this form in the isotropic setting.
    We observe that for specific choices of $F_\alpha \in \K^{1}_3$ (both in the isotropic and anisotropic settings) it may happen that $\chi_{11}$ vanishes. Indeed, we recall that $\chi \in \K_3 - F_\alpha = \{\diag(-\alpha, 0), \diag(1-\alpha,0), \diag(1/2-\alpha,1)\}$ for $\alpha \in (0,1)$ and, hence, $\chi_{11}=0$ can occur for $\alpha = 1/2$.
    For this reason, in the above proof, we also used $\chi_{22}$ in the lower bound, in order to deduce a uniform lower bound in \cref{eq:second_trunc}. To this end, in the above argument, we used a commutator estimate already for \emph{first} order laminates (while in the isotropic setting commutators only enter for \emph{second} and \emph{higher} order laminates).
    In the setting of \cite{RT23} (while also here $\chi_{11}=0$ may arise) it is \emph{not} necessary to use a commutator estimate of the form \cref{lem:CommutatorEst} for first order laminates, as -- due to the isotropy of the surface energy -- in that article the first high frequency localization truncates the cones in \emph{all} directions.
    In our setting this truncation is not present due to the anisotropy of the surface energy and we, hence, require an extra step to show the lower bound.

    As an alternative argument, also in our anisotropic setting, one could have avoided an application of the commutator estimate at the expense of using further information on the $\chi_{22}$ component. Indeed, one could have restricted to a bound of the form
    \begin{align}
    \label{eq:single_trunc}
        \Vert \chi_{11} \Vert_{L^2}^{2}  \leq C \psi_{1-\gamma}\Big(|\nu_1|^{-\frac{2}{3}} \epsilon^{-\frac{2}{3}} E_\epsilon(u,\chi) + |\nu_1|^{-\frac{2}{3}} \epsilon^{\frac{1}{3}} \Per(\Omega)\Big),
    \end{align}
    and then, in a second step, invoked information on the average of $\chi_{22}$. To this end, we note that by Jensen's inequality, it holds that
    \begin{align*}
    |\langle \nabla u \rangle_{\Omega} - \langle \chi \rangle_{\Omega}|^{2} \leq E_{el}(u,\chi),
    \end{align*}
    where $\langle \cdot \rangle_{\Omega}$ denotes the average on $\Omega$. In particular, we here use that by the imposed boundary conditions and the fundamental theorem of calculus, $\langle \nabla u \rangle_{\Omega} = F_\alpha$ and that $F_{22} = 0$ for all $F \in \K^1_3$.

    Hence, considering the second component we have
    \begin{align*}
        |\{x \in \Omega: \chi(x) =A_3\}|^2 \leq |\langle \chi_{22}\rangle_{\Omega}|^2 \leq |F_\alpha-\langle \chi \rangle_{\Omega}|^2 \leq E_{el}(u,\chi).
    \end{align*}
    In particular,
    \begin{align*}
        \Vert \chi_{11} \Vert_{L^2}^2 &\geq \min\{\alpha^2,(1-\alpha)^2\} |\{x \in \Omega: \chi \neq A_3\}| \geq C(\alpha) (|\Omega| - |\{x \in \Omega: \chi = A_3\}|) \\
        &\geq C(\alpha)(|\Omega|-E_{el}(u,\chi)^{\frac{1}{2}}).
    \end{align*}
    Returning to \cref{eq:single_trunc} with this additional information and rearranging the inequality, one then infers that
    \begin{align*}
      c \leq  \Vert \chi_{11} \Vert_{L^2}^{2} + C E_{el}(u,\chi)^{\frac{1}{2}} \leq C \psi_{1-\gamma}\Big(|\nu_1|^{-\frac{2}{3}} \epsilon^{-\frac{2}{3}} E_\epsilon(u,\chi) + |\nu_1|^{-\frac{2}{3}} \epsilon^{\frac{1}{3}} \Per(\Omega)\Big) + C E_{el}(u,\chi)^{\frac{1}{2}},
    \end{align*}
    which also concludes the argument after an absorption of the perimeter and additional elastic energy terms.
\end{rmk}

Turning now to the second order laminates, we consider
\begin{align*}
    F = \begin{pmatrix}
        \frac{1}{2} & 0 \\ 0 & \alpha
    \end{pmatrix} \in \K_3^2
\end{align*}
for some $\alpha \in (0,1)$ and note that $\chi_{22} - F_{22} \in \{-\alpha,1-\alpha\} \not\ni 0$. Thus, we now aim to control the Fourier mass of $\chi_{22}$.

\begin{lem}\label{lem:scal-second}
    Under the same assumptions as in \cref{thm:L1_3wells}, let $F_\alpha = \diag(\frac{1}{2},\alpha) \in \K_3^2$ for $\alpha \in (0,1)$.
    If $\nu \cdot e_1 \neq 0$ there are constants $C = C(\alpha) > 0$ and $\epsilon_0 = \epsilon_0(\alpha,|\nu_1|) > 0$ such that for any $\epsilon \in (0,\epsilon_0)$
    \begin{align*}
        C^{-1} |\nu_1|^{\frac{1}{2}} \epsilon^{\frac{1}{2}} \leq \inf_{u \in \mathcal{A}_{F_\alpha}} \inf_{\chi \in BV_\nu(\Omega;\K_3)} E_\epsilon(u,\chi) \leq C |\nu_1|^{\frac{1}{2}} \epsilon^{\frac{1}{2}}.
    \end{align*}

    If $\nu \cdot e_1 = 0$, we have with $C = C(\alpha) > 0$ and $\epsilon_0 = \epsilon_0(\alpha,|\nu_2|) > 0$ for all $\epsilon \in (0,\epsilon_0)$
    \begin{align*}
        C^{-1} |\nu_2|^{\frac{2}{3}} \epsilon^{\frac{2}{3}} \leq \inf_{u \in \mathcal{A}_{F_\alpha}} \inf_{\chi \in BV_\nu(\Omega;\K_3)} E_\epsilon(u,\chi) \leq C |\nu_2|^{\frac{2}{3}} \epsilon^{\frac{2}{3}}.
    \end{align*}
\end{lem}
 Again, we split the proof into two parts, first for $\nu \cdot e_1 \neq 0$ and the second part for $\nu \cdot e_1 =0$.

\begin{proof}[Proof for $\nu \cdot e_1 \neq 0$]
    \emph{Upper bound:} As for the first-order branching construction, the claimed upper scaling bound in $\epsilon$ is already known (cf. \cite{KW16,RT23}).
    We just need to focus on the dependence of the prefactor on $\nu$.
    In particular, we will follow the strategy of the proof of \cite[Thm. 1.2 (ii)]{RT23}. This consists in concatenating two orders of branching constructions; an outer one between gradients $A_3$ and $\diag(1/2,0)$, and then replacing the regions in which $\nabla u\approx \diag(1/2,0)$ with an inner branched lamination between $A_1$ and $A_2$.

    Let $\{\omega_{j,k}\}$ be the (outer) first-order branching covering as in the Step 2 of the proof of \cref{prop:L1_2wells} (now with switched roles between $x_1$ and $x_2$ because of the structure of the wells).
    In each cell $\omega_{j,k}$ we can produce an inner branching construction
    (see \cite{RT23} for details) so that estimate \cref{eq:bra1-nu} applies as follows
    \begin{align*}
    \int_{\omega_{j,k}} |\nabla u-\chi|^2 dx + \epsilon\Vert D_\nu\chi\Vert_{TV(\omega_{j,k})} \leq C(\alpha)\Big( \frac{h_j^3}{M^2\ell_j}+\epsilon\ell_j(M|\nu_1|+k_0|\nu_2|) \Big),
    \end{align*}
    where $M\in\N$, $M\sim(2\theta)^jN^2$ denotes the number of oscillations of the zeroth generation of this inner branching construction (the dependence of $M$ on $j$ is dropped for notational simplicity) and $k_0\sim\log(N)$.
    Summing this for every $k$ and every (outer) generation $j$ and by also adding the surface energy term of the outer branching construction (which comes by attaching the $\omega_{j,k}$-cells together), by the relations \cref{eq:parameters} we obtain
    \begin{align*}
    \int_{\Omega} |\nabla u-\chi|^2 dx + \epsilon\Vert D_\nu\chi\Vert_{TV(\Omega)} \leq C(\alpha) \Big( \frac{1}{N^2}+\epsilon (N^2+j_0)|\nu_1|+\epsilon (k_0+N)|\nu_2| \Big).
    \end{align*}
    Optimizing as $N\sim(\epsilon|\nu_1|)^{-\frac{1}{4}}$ we deduce the claimed upper scaling bound.
    Due to the construction, the bounds from  \cref{eq:PropertiesBranching} still hold for $u$ and $\chi$.

    \emph{Lower bound:}
    %Without loss of generality we assume $F_\alpha = 0$ and thus $\chi \in \K_3-F_\alpha$.
    Analogously as in the previous proofs, by subtracting the boundary conditions we can assume that $u\in H^1_0(\Omega;\R^2)$ and $\chi\in\K_3-F_\alpha$.
    For the readers' convenience we recall the (truncated) cones from \cref{eq:TruncCone_1,eq:Cone_j}: for $\mu \in (0,\frac{|\nu_1|}{16})$,
$\lambda > 0$, $j=1,2$
\begin{align*}
  C_{j,\mu,\lambda} = \{ k \in \Z^d: |k|^2 - k_{j}^2 \leq \mu^2 |k|^2, \ |k_{j}| \leq \frac{2}{|\nu_1|} \lambda\} , \quad C_{2,\mu} = \{ k \in
  \Z^d: |k|^2 - k_2^2 \leq \mu^2 |k|^2\}.
\end{align*}
% As it will be used below, for $\lambda_2 \in (0,\lambda)$ we also consider the truncated cone as in \cref{eq:cone_trunc_2}
% \begin{align*}
%     C_{2,\mu,\lambda_2} = \{k \in \Z^d: |k|^2 - k_2^2 \leq \mu^2 |k|^2, \ |k_2| \leq \frac{2}{|\nu_1|} \lambda_2\}.
% \end{align*}
For the multipliers defined in \cref{eq:multiplier} %and similarly for the truncated cone $C_{2,\mu,\lambda_2}$, and
we infer by \cref{lem:Localization}
\begin{align*}
  \Vert \chi_{11} - m_{1,\mu,\lambda}(D) \chi_{11} \Vert_{L^2}^2 + \Vert \chi_{22} -
  m_{2,\mu}(D) \chi_{22} \Vert_{L^2}^2 &\leq \sum_{k \notin C_{1,\mu,\lambda}} |\hat{\chi}_{11}(k)|^2 + \sum_{k \notin C_{2,\mu}} |\hat{\chi}_{22}(k)|^2 \\
  & \leq C (\mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + C \lambda^{-1} \Per(\Omega).
\end{align*}
Here the constant $C>0$ only depends on $\alpha$.

Using that $\chi_{22} = 1-\alpha-4\chi_{11}^2$, we deduce from an application of \cref{cor:CommutatorEst_Applied} with $\lambda_2 = M \mu \lambda$ for any $\gamma \in (0,1)$
\begin{align} \label{eq:Lorent_iteration}
  \Vert \chi_{22} - m_{2,\mu,\lambda_2}(D) \chi_{22} \Vert_{L^2}^{2} \leq C(\alpha) \psi_{1-\gamma}(\Vert
  \chi_{11} - m_{1,\mu,\lambda}(D) \chi_{11} \Vert_{L^2}^{2}) + 4 \Vert \chi_{22} - m_{2,\mu}(D)
  \chi_{22} \Vert_{L^2}^{2},
\end{align}
with $\psi_t(x) = \max\{|x|^t,|x|\}$ for $t > 0$.

Now we use this estimate on $\chi_{22} - m_{2,\mu,\lambda_2}(D) \chi_{22}$ to improve the lower
bound in comparison to the two-well case.
Using \cref{lem:LowFreqEst} for $\chi_{22}$, we get for $\bar{\lambda} = \frac{4}{|\nu_1|} \lambda_2$
\begin{align} \label{eq:Lorent_low_freq}
\sum_{|k_2| \leq 4 \lambda_2/|\nu_1|} |\hat{\chi}_{22}(k)|^2 \leq C \frac{\lambda_2^2}{|\nu_1|^2} E_{el}(u,\chi).
\end{align}
Thus, as in the proof of the two-well problem in \cref{prop:L1_2wells}, the idea is to combine \cref{eq:Lorent_iteration,eq:Lorent_low_freq} to have an estimate of $\Vert \chi_{22} \Vert_{L^2}^2$ in terms of the energy depending on the parameters $\mu, \lambda_2$ and then to optimize in these parameters.
To be precise, we have
\begin{align*}
    \Vert \chi_{22} \Vert_{L^2}^2 & \leq 2 \sum_{k \in C_{2,2\mu,2\lambda_2}} |\hat{\chi}_{22}(k)|^2 + 2 \Vert \chi_{22} - m_{2,\mu,\lambda_2}(D) \chi_{22} \Vert_{L^2}^2 \\
    & \leq 2 \sum_{|k_2| \leq 4 \lambda_2/|\nu_1|} |\hat{\chi}_{22}(k)|^2 + 2 \Vert \chi_{22} - m_{2,\mu,\lambda_2}(D) \chi_{22} \Vert_{L^2}^2.
\end{align*}
Thus, plugging in \cref{eq:Lorent_iteration,eq:Lorent_low_freq}, yields with $\lambda_2 = M \mu \lambda$ and a constant $C = C(\alpha) > 0$

\begin{align*}
    \Vert \chi_{22} \Vert_{L^2}^2 & \leq C |\nu_1|^{-2} \lambda_2^2 E_{el}(u,\chi) + C \psi_{1-\gamma}(\Vert \chi_{11}- m_{1,\mu,\lambda}(D) \Vert_{L^2}^2) + C \Vert \chi_{22} - m_{2,\mu}(D) \chi_{22} \Vert_{L^2}^2 \\
    & \leq C \left( |\nu_1|^{-2} \lambda_2^2 E_\epsilon(u,\chi) + \psi_{1-\gamma}\Big((\mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + \lambda^{-1} \Per(\Omega) \Big) \right) \\
    & \leq C \psi_{1-\gamma}\Big((|\nu_1|^{-2} \mu^2 \lambda^2 + \mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + \lambda^{-1} \Per(\Omega) \Big).
\end{align*}
As $\Vert \chi_{22} \Vert_{L^2}^2 \geq C \min\{\alpha^2,(1-\alpha)^2\} > 0$, fixing $\mu^{-2} \sim |\nu_1|^{-1} \lambda$ and $\lambda \sim |\nu_1|^{1/2} \epsilon^{-1/2}$, we argue as in the proof of \cref{lem:scal-first}, i.e. considering the two cases for $\psi_{1-\gamma}$ and carrying out an absorption argument for the perimeter term, we arrive at
\begin{align*}
    E_\epsilon(u,\chi) \geq \frac{1}{2} \min\{C,C^{\frac{1}{1-\gamma}}\} |\nu_1|^{\frac{1}{2}} \epsilon^{\frac{1}{2}}.
\end{align*}
\end{proof}

\begin{proof}[Proof for $\nu \cdot e_1 = 0$]
\emph{Upper bound:}
We construct a (cut-off) simple laminate of $A_1$ and $A_2$ within a branching construction using $A_3$.
See \cref{fig:LaminateInBranching} for an illustration of a laminate within a branching construction.
As a first-order branching construction has been already explained in the proof of \cref{prop:L1_2wells}, we only give an outline of the argument.


Considering a reference cell $\omega = (0,h) \times (0,\ell)$ with $0 < \ell < h \leq 1$, we decompose this into further subdomains given by
\begin{align*}
  \omega_1 &= \{ (x_1,x_2) \in \omega: x_2 \in (0,(1-\alpha) \frac{\ell}{2})\},\\
  \omega_2 &= \{ (x_1,x_2) \in \omega: x_2 \in [(1-\alpha) \frac{\ell}{2}, (1-\alpha) \frac{\ell}{2} + \alpha \frac{\ell}{2}\frac{x_1}{h}) \}, \\
  \omega_3 & = \{ (x_1,x_2) \in \omega: x_2 \in [(1-\alpha) \frac{\ell}{2} + \alpha \frac{\ell}{2} \frac{x_1}{h}, (1-\alpha) \ell + \alpha \frac{\ell}{2} \frac{x_1}{h}) \}, \\
  \omega_4 &= \{ (x_1,x_2) \in \omega: x_2 \in [(1-\alpha) \ell + \alpha \frac{\ell}{2} \frac{x_1}{h},\ell)\}.
\end{align*}

For $r < h$ such that $\frac{h}{r} \in \N$ and a bump function $\phi \in C^\infty(\R;[0,1])$ with $\phi(t) = 0$ for $t \leq 0$ and $\phi(t) = 1$ for $t \geq 1$, we then define the continuous function
\begin{align*}
 \tilde{u}(x_1,x_2) =
  \begin{cases}
    \begin{pmatrix}
      \operatorname{Lam}_r(x_1) \phi(\frac{x_2}{r}) \phi(\frac{(1-\alpha) \frac{\ell}{2}-x_2}{r}) \\ -\alpha x_2
    \end{pmatrix}, & (x_1,x_2) \in \omega_1, \\[15pt]
    \begin{pmatrix}
      0 \\ (1-\alpha)x_2 - (1-\alpha) \frac{\ell}{2}
    \end{pmatrix}, & (x_1,x_2) \in \omega_2, \\[15pt]
    \begin{pmatrix}
      \operatorname{Lam}_r(x_1) \phi(\frac{x_2-(1-\alpha) \frac{\ell}{2} - \alpha \frac{\ell}{2} \frac{x_1}{h}}{r}) \phi(\frac{(1-\alpha)\ell + \alpha
      \frac{\ell}{2} \frac{x_1}{h}-x_2}{r}) \\ - \alpha x_2 + \alpha \frac{\ell}{2} \frac{x_1}{h}
    \end{pmatrix}, & (x_1,x_2) \in \omega_3, \\[15pt]
    \begin{pmatrix}
      0 \\ (1-\alpha)x_2 - (1-\alpha) \ell
    \end{pmatrix}, & (x_1,x_2) \in \omega_4.
  \end{cases}
\end{align*}
Here we used
\begin{align*}
  \operatorname{Lam}_r(t) = \begin{cases} - \frac{1}{2}t, & t \in [0,\frac{r}{2}), \\ \frac{1}{2}t-\frac{r}{2}, & t \in [\frac{r}{2},r),
  \end{cases}
\end{align*}
  and extended it $r$-periodically.
Setting also
\begin{align*}
  \tilde{\chi}(x_1,x_2) =
  \begin{cases}
    \begin{pmatrix}
       \operatorname{Lam}'_r(x_1) & 0 \\ 0 & -\alpha
    \end{pmatrix}, & (x_1,x_2) \in \omega_1 \cup \omega_3, \\
    \begin{pmatrix}
      0 & 0 \\ 0 & 1-\alpha
    \end{pmatrix}, & (x_1,x_2) \in \omega_2 \cup \omega_4,
  \end{cases}
\end{align*}
we can calculate the energy contribution of $u(x) = \tilde{u}(x) + F_\alpha x$ and $\chi = \tilde{\chi} + F_\alpha$. Note that $F_\alpha = \operatorname{diag}(1/2,\alpha)$.
We have
\begin{align*}
  \int_\omega |\nabla u (x) - \chi(x)|^2 dx = \int_\omega |\nabla\tilde{u}(x) - \tilde{\chi}(x)|^2 dx \leq C(\alpha)(rh + \frac{\ell^3}{h}),
\end{align*}
where the first term is determined by the size of the cut-off areas in $\omega_1$ and $\omega_2$ (i.e., by the inner laminate), and the second term is due to the error we make by adjusting the interfaces away from $e_2$ to achieve
the refinement in $e_1$ direction (i.e., the usual elastic energy originating from branching).
Moreover, as we do not penalize oscillation in the $e_1$ direction, it holds
\begin{align*}
  \Vert D_{e_2} \chi \Vert_{TV(\omega)} + \Per(\omega) = \Vert D_{e_2} \tilde{\chi} \Vert_{TV(\omega)} + \Per(\omega) \leq C(\alpha) h,
\end{align*}
and thus in total
\begin{align*}
  \int_\omega |\nabla u(x) - \chi(x)|^2 dx + \epsilon \Vert D_{e_2} \chi \Vert_{TV(\omega)} + \epsilon \Per(\omega) \leq C(\alpha)(r h + \frac{\ell^3}{h} + \epsilon h).
\end{align*}
As for any $h > 0$ we can choose $r<\epsilon$ %arbitrarily small, e.g. by setting $r = \frac{h}{K}$ for some $K \in \N$ very large,
the contribution of the $r h$ term is negligible.
Hence,
\begin{align*}
  \int_\omega |\nabla u(x) - \chi(x)|^2 dx + \epsilon \Vert D_{e_2} \chi \Vert_{TV(\omega)} + \epsilon \Per(\omega) \leq C(\alpha) (\frac{\ell^3}{h} + \epsilon h).
\end{align*}
This is the same energy contribution as for the standard branching construction, thus concluding as in the proof of \cref{prop:L1_2wells} (see also \cite[Sec. 3]{RT23}), we get
\begin{align*}
 \inf_{\chi \in BV_\nu(\Omega;\K_3)} \inf_{u \in \mathcal{A}_{F_\alpha}} \int_{(0,1)^2} |\nabla u - \chi|^2 dx + \epsilon \Vert D_{e_2} \chi \Vert_{TV((0,1)^2)} \leq C(\alpha) \epsilon^{\frac{2}{3}}.
\end{align*}

