As it is used below in the proof of \cref{cor:Lp_3wells}, we emphasize that the above constructed function satisfies that $u \in W^{1,\infty}(\Omega;\R^2), \chi \in BV(\Omega;\K_3)$ with
\begin{align*}
    \nabla u \in BV(\Omega;\R^{2\times2}), \ \Vert D\nabla u\Vert_{TV(\Omega)} \leq C(\alpha) (\Vert D \chi \Vert_{TV(\Omega)} + \Per(\Omega)),
\end{align*}
and thus the bounds from \cref{eq:PropertiesBranching} also hold in this setting.

\emph{Lower bound:}
Again, by considering $\K_3-F_\alpha$, we reduce to the case of zero boundary conditions.
In the case of $\nu \cdot e_1 = 0$ we have $\nu \cdot e_2 \neq 0$, instead of the high frequency control in $k_1$, we consider a high frequency control in $k_2$ for $\chi_{22}$.
Indeed, let $\mu < \frac{|\nu_2|}{16}$, $\lambda >0$, as in \cref{eq:ineq_inclusion_cones} we have
\begin{align*}
    C_{2,\mu,\lambda} := \{ k \in \Z^{2}: |k|^2 - k_2^2 \leq \mu^2 |k|^2, \ |k_2| \leq \frac{2}{|\nu_2|} \lambda\} \supset \{k \in \Z^{2}: |k|^2 - k_1^2 \leq \mu^2 |k|^2,\ |k \cdot \nu| \leq \lambda\}
\end{align*}
    and thus we can bound the Fourier mass of $\chi_{22}$ outside of $C_{2,\mu,\lambda}$ in terms of the energy, cf. \cref{lem:Localization},
    \begin{align*}
        \sum_{k \notin C_{2,\mu,\lambda}} |\hat{\chi}_{22}(k)|^2 \leq C (\mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + C \lambda^{-1} \Per(\Omega),
    \end{align*}
    with a constant $C = C(\alpha) > 0$.
    Notice that the definition of the cone is analogous to that in \cref{eq:TruncCone_1}, but different as the second direction plays the role of the first. This is not the cone given in \cref{eq:TruncCone_1} for $j=2$, as there the truncation is dependent on the parameter $|\nu_1|$, here on $|\nu_2|$.
    Following now the proof of \cref{prop:L1_2wells} for $f = \chi_{22}$ with a suitable change of coordinates, we get
    \begin{align*}
        E_{\epsilon}(u,\chi) \geq C |\nu_2|^{\frac{2}{3}} \epsilon^{\frac{2}{3}}.
    \end{align*}
\end{proof}
With \cref{lem:scal-first,lem:scal-second} proved, we combine their estimates to deduce the desired lower bound in \cref{thm:L1_3wells}.

\begin{proof}[Conclusion of \cref{thm:L1_3wells}]
We finally combine the above discussion by rewriting the lower bound estimate in a concise way.
We notice that for $\nu_1 = 0$ there is nothing to prove as \cref{itm:L1_3wells_i,itm:L1_3wells_ii} are given by \cref{lem:scal-first,lem:scal-second} respectively.
If $\nu_1 \neq 0$, we choose $\epsilon_0$ to be small depending on $\nu$, i.e.\
fix $\epsilon_0$ to fulfil
\begin{align*}
    |\nu_2|^{\frac{2}{3}} \epsilon_0^{\frac{2}{3}} \leq |\nu_1|^{\frac{1}{2}} \epsilon_0^{\frac{1}{2}}.
\end{align*}
With this choice, for every $\epsilon<\epsilon_0$, it holds
\begin{align*}
    \inf_{u \in \mathcal{A}_F} \inf_{\chi \in BV_\nu(\Omega;\K_3)} E_\epsilon(u,\chi) \geq C |\nu_1|^{\frac{1}{2}} \epsilon^{\frac{1}{2}} \geq \frac{C}{2} \left( |\nu_1|^{\frac{1}{2}} \epsilon^{\frac{1}{2}} + |\nu_2|^{\frac{2}{3}} \epsilon^{\frac{2}{3}} \right).
\end{align*}
The upper bound follows by adding the two upper bounds from \cref{lem:scal-first,lem:scal-second}.
\end{proof}


\begin{rmk} \label{rmk:lower_bound_component}
    As can be seen in the above proof of \cref{lem:scal-second} (and later analogously in the proof of \cref{thm:L1_mult_wells}), it would be possible to deduce the above scaling behaviour for $\nu \cdot e_1 \neq 0$ also for an even more degenerate anisotropic surface energy of the following type
    \begin{align*}
        E_{\textup{surf}}^{r}(\chi) = \Vert D_\nu (\chi : r) \Vert_{TV(\Omega)},
    \end{align*}
    for $r\in \R^{d \times d}$ such that $|r| = 1$ and
    \begin{align*}
        \Vert D_\nu (\chi : r) \Vert_{TV(\Omega)} \geq C(\K,d, r) \Vert D_{\nu} \chi_{11} \Vert_{TV(\Omega)}.
    \end{align*}
    Here we denoted the Frobenius scalar product of matrices by $\chi : r = \sum_{i,j=1}^{d} \chi_{ij} r_{ij}$.
    A sufficient condition on $r \in \R^{d \times d}$ is the following:
    \begin{align*}
        (A_{j})_{11} \neq (A_{k})_{11} \text{ if and only if } A_j :r \neq A_k : r.
    \end{align*}
    For the three-wells from $\K_3$ in \cref{eq:Lorent_wells} this translates into the condition that
    \begin{align*}
        r \notin \{r_{11} = 0\} \cup \{r_{11} = 2 r_{22}\} \cup \{ r_{11} = -2 r_{22}\}.
    \end{align*}
\end{rmk}



\subsection{Higher order laminates}
We next turn to the scaling behaviour of higher order laminates.
Due to the anisotropic energies, we cannot immediately invoke the argument from \cite{RT23}. As an important technical novelty, we have to treat the relevant nonlinear relations between the components of the phase indicator substantially more carefully. This is due to the fact that, initially, our surface energy (potentially) only controls high frequencies in the $k_1$ direction. Thus, particularly the first step in the localization is crucial, as this will iteratively allow us the further high frequency reduction steps in the other conical directions.

As in the setting of the three-well problem of Lorent in the previous section, the key idea is to use that $\chi_{11}$ determines the other diagonal entries. In \cite{RT23} $\chi_{22}$ is written as a nonlinear polynomial of a combination of the remaining diagonal entries $\chi_{11},\chi_{33},\dots,\chi_{N-1,N-1}$.
  In the case of $\nu = e_1$, if only such a relation were available, this would lead to an issue with our argument as none of the cones in the $e_3, \dots, e_{N-1}$ directions is initially localized in the high frequencies (due to our anisotropic energies).
  The central novel idea is to rely on additional structure: More precisely, we will instead use that $\chi_{22}$ is given by a \emph{nonlinear} polynomial of $\chi_{11}$ plus a \emph{linear} one in $\chi_{33},\dots,\chi_{N-1,N-1}$.

To elaborate on the strategy of the proof of \cref{thm:L1_mult_wells}, let us analyse the four well setting in three dimensions in the case of $\nu \cdot e_1 \neq 0$ first.
  Let $N=4$ and $d=3$, and thus consider $\K_4 = \{A_1, A_2, A_3, A_4\}$ with
  \begin{align*}
  A_1 & = \begin{pmatrix}
      0 & 0 & 0 \\ 0 & 0 & 0 \\ 0 & 0 & 0
  \end{pmatrix}, &
  A_2 &= \begin{pmatrix}
      1 & 0 & 0 \\ 0 & 0 & 0 \\ 0 & 0 & 0
  \end{pmatrix}, &
  A_3 & = \begin{pmatrix}
      \frac{1}{2} & 0 & 0 \\ 0 & 1 & 0 \\ 0 & 0 & 0
  \end{pmatrix}, &
  A_4 &= \begin{pmatrix}
      \frac{1}{2} & 0 & 0 \\ 0 & \frac{1}{2} & 0 \\ 0 & 0 & 1
  \end{pmatrix}.
  \end{align*}
We will subsequently generalize the lower bound to the family of wells from \cref{sec:introL14}.


\begin{prop} \label{prop:L1_4wells}
    Let $\alpha \in (0,1)$ and $F_\alpha = \diag(1/2,1/2,\alpha) \in \K_4^3$. Let $\nu \in \S^2$ with $\nu \cdot e_1 \neq 0$.
    There exist constants $C= C(\alpha)>0$ and $\epsilon_0 = \epsilon_0(\alpha,|\nu_1|) > 0$ such that for any $\epsilon \in (0,\epsilon_0)$
    \begin{align*}
        \inf_{u \in \mathcal{A}_{F_\alpha}} \inf_{\chi \in BV_\nu(\Omega;\K_4)} E_\epsilon (u,\chi) \geq C |\nu_1|^{\frac{2}{5}} \epsilon^{\frac{2}{5}},
    \end{align*}
    where $\mathcal{A}_{F_\alpha}$ is given in  \cref{eq:AdmissibleFunctionsL2}.
\end{prop}

Let us outline the strategy of proof for the derivation of the lower bound in \cref{prop:L1_4wells}.
To show this result, we first use the nonlinear relation for $\tilde{\chi} = \chi - F_\alpha: \Omega \to \K_3 - F_\alpha$
  \begin{align} \label{eq:nonlinRel4Wells}
    2 \tilde{\chi}_{22} +  \tilde{\chi}_{33} = 1-8\tilde{\chi}_{11}^2 - \alpha.
  \end{align}
  After a first application of the first localization \cref{lem:Localization} with
  \begin{align*}
    C_{1,\mu,\lambda} = \{k \in \Z^3: |k|^2-k_1^2 \leq \mu^2 |k|^2, |k_1| \leq \frac{2}{|\nu_1|} \lambda\}, \ C_{j,\mu} = \{ k \in \Z^3: |k|^2-k_j^2 \leq \mu^2 |k|^2\},
  \end{align*}
  for $\mu < \frac{|\nu_1|}{16}$, $\lambda > 0$ and $j=2,3$ and their smoothed out multipliers, cf.\ \cref{eq:multiplier}, we have
  \begin{align*}
    &\Vert\tilde{\chi}_{11} - m_{1,\mu,\lambda}(D) \tilde{\chi}_{11} \Vert_{L^2}^2 + \sum_{j=2,3} \Vert \tilde{\chi}_{jj} - m_{j,\mu}(D) \tilde{\chi}_{jj} \Vert_{L^2}^2\\
    &\qquad\qquad \leq C(\alpha)(\mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + C(\alpha) \lambda^{-1} \Per(\Omega).
  \end{align*}
  Using the above nonlinear relation \cref{eq:nonlinRel4Wells}, we aim to truncate $C_{2,\mu}$ and $C_{3,\mu}$ by means of \cref{cor:CommutatorEst_Applied}.





\begin{proof}[Proof of \cref{prop:L1_4wells}]
Without loss of generality, by subtracting $F_\alpha$, we assume $F_\alpha = 0$ and $\chi \in \K_4-F_\alpha$.
    We observe that differently from the situation in \cref{rmk:lower_bound_component}, it suffices to only deduce a lower bound for $\chi_{33}$. 
    We aim to use \cref{cor:CommutatorEst_Applied}. After an application of  the first localization \cref{lem:Localization} for $\mu < \frac{|\nu_1|}{16}$, $\lambda > 0$ and a constant $C = C(\alpha) > 0$
    \begin{align}\label{eq:estimate}
    \begin{split}
        &\Vert \chi_{11} - m_{1,\mu,\lambda}(D) \chi_{11} \Vert_{L^2}^2 + \sum_{j=2,3} \Vert \chi_{jj} - m_{j,\mu}(D) \chi_{jj} \Vert_{L^2}^2 \\
        &\qquad\qquad \leq C (\mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + C \lambda^{-1} \Per(\Omega).
    \end{split}
    \end{align}
    To achieve the energy bound, we use \cref{cor:CommutatorEst_Applied} to truncate the cone corresponding to $\chi_{22}$, which in turn is used to reduce the size of $C_{3,\mu}$ even further.
    In detail we apply \cref{cor:CommutatorEst_Applied} compounded with \cref{eq:estimate} for $2\chi_{22} +\chi_{33} = 1 - \alpha - 8 \chi_{11}^2$ and get for $\lambda_2 = M \mu \lambda$
    \begin{align} \label{eq:iteration_1_4wells}
    \Vert \chi_{22} - m_{2,\mu,\lambda_2}(D) \chi_{22} \Vert_{L^2}^{2} \leq C \psi_{1-\gamma}\Big( (\mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + C \lambda^{-1} \Per(\Omega)\Big).
    \end{align}
    %where we already used the first localization.
    Here we used the truncated cone $C_{2,\mu,\lambda_2}$ defined in \cref{eq:TruncCone_1} with the corresponding smooth multiplier defined in \cref{eq:multiplier}.

    Iterating now the comparison argument, using $\chi_{33} = 1- \alpha - 4\chi_{22}^2$ we can improve the estimate on the Fourier mass of $\chi_{33}$ in the sense that we can truncate the corresponding cone $C_{3,\mu}$ on a scale $\lambda_3 = M \mu \lambda_2 = M^2 \mu^2 \lambda$.
    Indeed, by a variant of the commutation estimate from \cref{cor:CommutatorEst_Applied} (see \cref{rmk:corollary-variant}) and \cref{eq:iteration_1_4wells}
\begin{align*}
    \Vert \chi_{33} - m_{3,\mu,\lambda_3}(D) \chi_{33} \Vert_{L^2}^{2} &\leq C \psi_{1-\gamma}\Big(\Vert \chi_{22}-m_{2,\mu,\lambda_2}(D) \chi_{22} \Vert_{L^2}^{2}\Big) + 4 \Vert \chi_{33} - m_{3,\mu}(D) \chi_{33} \Vert_{L^2}^{2} \\
    & \leq C \psi_{(1-\gamma)^2}\Big((\mu^{-2}+(\lambda \epsilon)^{-1})E_\epsilon(u,\chi) + \lambda^{-1} \Per(\Omega)\Big).
\end{align*}
As above, the multiplier is of the form as in \cref{eq:multiplier} for the truncated cone $C_{3,\mu,\lambda_3}$ defined in \cref{eq:TruncCone_1}.

    By \cref{lem:LowFreqEst} with $\bar{\lambda} = 4 \lambda_3/|\nu_1|$ we can control the ``missing'' (low frequency) region and infer
    \begin{align*}
        \Vert \chi_{33} \Vert_{L^2}^2 &\leq 2 \Vert \chi_{33}- m_{3,\mu,\lambda_3} \chi_{33} \Vert_{L^2}^2 + 2 \sum_{|k_3| \leq 4 \lambda_3/|\nu_1|} |\hat{\chi}_{33}(k)|^2 \\
        & \leq C \psi_{(1-\gamma)^2}\Big((\mu^{-2}+(\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + \lambda^{-1} \Per(\Omega)\Big) + C \frac{\lambda_3^2}{|\nu_1|^2} E_\epsilon(u,\chi).
    \end{align*}
    We now choose the parameters $\mu$ and $\lambda_3$, that is, $\lambda$, in an optimal way.
    To be more precise, we fix $\mu^{-1} \sim \frac{\lambda_3}{|\nu_1|} \sim \frac{\mu^2 \lambda}{|\nu_1|}$, i.e. $\mu \sim |\nu_1|^{1/3} \lambda^{-1/3}$ and get
    \begin{align*}
        \Vert \chi_{33} \Vert_{L^2}^{2} & \leq C \psi_{(1-\gamma)^2}\Big((|\nu_1|^{-2/3} \lambda^{2/3} + (\lambda \epsilon)^{-1})E_\epsilon(u,\chi) + \lambda^{-1} \Per(\Omega)\Big) + |\nu_1|^{-2/3} \lambda^{2/3} E_\epsilon(u,\chi) \\
        & \leq C \psi_{(1-\gamma)^2} \Big((|\nu_1|^{-2/3} \lambda^{2/3} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + \lambda^{-1} \Per(\Omega)\Big).
    \end{align*}
    Optimizing the energy contributions in $\lambda$ by choosing $\lambda \sim |\nu_1|^{2/5} \epsilon^{-3/5}$ yields, after absorbing the perimeter term,
    \begin{align*}
        E_\epsilon(u,\chi) \geq C |\nu_1|^{\frac{2}{5}} \epsilon^{\frac{2}{5}}.
    \end{align*}
    Here we used that $\Vert \chi_{33} \Vert_{L^2}^{2} \geq C \min^2\{\alpha,1-\alpha\}$ and the fact that the function $\psi_{(1-\gamma)^2}$ does not influence the scaling behaviour, cf. the proof of \cref{lem:scal-first}.
\end{proof}


\begin{proof}[Proof of \cref{thm:L1_mult_wells}]
With the previous results in hand, the remainder of the proof of \cref{thm:L1_mult_wells} is exactly the same as in \cite{RT23} with the same modifications as above for four wells. For the convenience of the reader we recall the main ideas.
Without loss of generality, we reduce to the case of $F = 0$ by considering $\chi - F \in \K_N - F$.
We first clarify the nonlinear relations. Each component determines the following ones, that is
\begin{align*}
    \sum_{n=j+1}^{N-1} \alpha_k \chi_{nn} = g_j(\chi_{jj}).
\end{align*}
The relations are given as follows

\begin{align*}
    \sum_{n=j+1}^{N-1} 2^{-n+j+1} \chi_{nn}= 4 F_{jj}-4F_{jj}^2 - \sum_{n=j+1}^{N-1} 2^{-n+j+1} F_{nn} +4\chi_{jj} - 8 F_{jj} \chi_{jj} - 4 \chi_{jj}^2 =: g_j(\chi_{jj}).
\end{align*}

\emph{The case $\nu \cdot e_1 \neq 0$:}
By \cref{lem:Localization} we obtain for a constant $C = C(d,F) > 0$
\begin{align} \label{eq:Localization_mult_wells}
\begin{split}
    &\Vert \chi_{11} - m_{1,\mu,\lambda}(D) \chi_{11} \Vert_{L^2}^{2} + \sum_{j=2}^{d} \Vert \chi_{jj} - m_{j,\mu}(D) \chi_{jj} \Vert_{L^2}^{2} \\
    &\qquad \leq C (\mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + C \lambda^{-1} \Per(\Omega).
    \end{split}
\end{align}
To facilitate the reading, we recall the definition of the truncated cones $C_{j,\mu,\lambda_2}$ in \cref{eq:TruncCone_1}
\begin{align*}
    C_{j,\mu,\lambda_2} = \{k \in \Z^d: |k|^2 - k_j^2 \leq \mu^2 |k|^2, |k_j| \leq \frac{2}{|\nu_1|} \lambda_2\},
\end{align*}
and that $m_{j,\mu,\lambda_2}(D)$ denote their smooth Fourier multipliers as in \cref{eq:multiplier}.
By \cref{cor:CommutatorEst_Applied}, in combination with \cref{eq:Localization_mult_wells}, we have for $\lambda_2 = M \mu \lambda$
\begin{align*}
\sum_{j=2}^{d} \Vert \chi_{jj} - m_{j,\mu,\lambda_2}(D) \chi_{jj} \Vert_{L^2}^{2} \leq C 2^d \psi_{1-\gamma}\Big((\mu^{-2}+(\lambda \epsilon)^{-1}) E_\epsilon(u,\chi)  + \lambda^{-1} \Per(\Omega)\Big).
\end{align*}
Here we exploited that $\alpha_k \in [2^{-d},1]$ for $k \in \{2,3,\dots,d\}$.
Then an iterative application of the higher-order variant of \cref{cor:CommutatorEst_Applied} (\cref{rmk:corollary-variant}) yields, in combination with \cref{eq:Localization_mult_wells}, after $\ell-1$ many iterations
\begin{align} \label{eq:iterated_commutator_mult_wells}
    \sum_{j=\ell}^{d} \Vert \chi_{jj} - m_{j,\mu,\lambda_{\ell}}(D) \chi_{jj} \Vert_{L^2}^{2} \leq  C \psi_{(1-\gamma)^{\ell-1}}\Big((\mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) +\lambda^{-1} \Per(\Omega)\Big),
\end{align}
with $\lambda_\ell = M \mu \lambda_{\ell-1} = M^{\ell-1} \mu^{\ell-1} \lambda$ and a constant $C = C(d,F,\ell) > 0$.


As we have already seen in the proof of \cref{thm:L1_3wells} for $F \in \K_3^1$, it might happen, that we need information on more than one $\chi_{jj}$, cf. \cref{rmk:lower_bound_first_laminate}.
Depending on $\ell \in \{1,\dots,N-2\}$ we have for some $\alpha \in (0,1)$, given by the boundary data,
\begin{align*}
    (\chi_{\ell \ell},\chi_{\ell+1,\ell+1}) \in \{ (-\alpha,0), (1-\alpha,0), (\frac{1}{2}-\alpha,1), (\frac{1}{2}-\alpha,\frac{1}{2})\}.
\end{align*}
In particular, $(\chi_{\ell \ell}, \chi_{\ell+1,\ell+1}) \neq 0$.
For $\ell = N-1$, we already have $\chi_{N-1,N-1} \in \{-\alpha, 1-\alpha\}$ with $\alpha \in (0,1)$, it holds $\chi_{N-1,N-1} \neq 0$.

Thus, if $N = d+1$, setting $\chi_{NN} \equiv 0$, we obtain that if $F \in \K_N^{\ell}$ for some $\ell \in \{1,2,\dots,N-1\}$, then it holds $(\chi_{\ell \ell},\chi_{\ell+1,\ell+1}) \neq 0$. Hence, we note that the control for two diagonal components $\chi_{jj}$ is sufficient for deducing the desired lower bound.

By \cref{eq:iterated_commutator_mult_wells} we have
\begin{align*}
    \Vert \chi_{\ell \ell} - m_{\ell,\mu,\lambda_{\ell}}(D) \chi_{\ell \ell} \Vert_{L^2}^{2} &+ \Vert \chi_{\ell+1,\ell+1} - m_{\ell+1,\mu,\lambda_{\ell}}(D) \chi_{\ell+1,\ell+1} \Vert_{L^2}^{2} \\
    & \leq C \psi_{(1-\gamma)^{\ell-1}}\Big((\mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + \lambda^{-1} \Per(\Omega)\Big).
\end{align*}


As in the proof of \cref{prop:L1_4wells} we use \cref{lem:LowFreqEst} to gain control over $\Vert m_{\ell,\mu,\lambda_{\ell}}(D) \chi_{\ell \ell} \Vert_{L^2}^2$ and $\Vert m_{\ell+1,\mu,\lambda_{\ell}}(D) \chi_{\ell+1,\ell+1} \Vert_{L^2}^2$.
For this let $\bar{\lambda} = 4 \lambda_{\ell}/|\nu_1|$, then
\begin{align*}
    \Vert m_{\ell,\mu,\lambda_{\ell}}(D) \chi_{\ell \ell} \Vert_{L^2}^2 &+ \Vert m_{\ell+1,\mu,\lambda_{\ell}}(D) \chi_{\ell+1,\ell+1} \Vert_{L^2}^2 \\
    & \leq \sum_{|k_{\ell}|  \leq 4 \lambda_{\ell}/|\nu_1|} |\hat{\chi}_{\ell \ell}(k)|^2 + \sum_{|k_{\ell+1}| \leq 4 \lambda_{\ell}/|\nu_1|} |\hat{\chi}_{\ell+1,\ell+1}(k)|^2 \\
    & \leq C \frac{\lambda_{\ell}^2}{|\nu_1|^2} E_{\epsilon}(u,\chi).
\end{align*}
These two estimates combined give
\begin{align*}
    \Vert \chi_{\ell \ell} \Vert_{L^2}^2 + \Vert \chi_{\ell+1,\ell+1} \Vert_{L^2}^2
    &\leq 2 \Vert \chi_{\ell \ell} - m_{\ell,\mu,\lambda_{\ell}}(D) \chi_{\ell \ell} \Vert_{L^2}^2 + 2 \Vert \chi_{\ell+1,\ell+1} - m_{\ell+1,\mu,\lambda_{\ell}}(D) \chi_{\ell+1,\ell+1} \Vert_{L^2}^2 \\
    & \quad + 2\Vert m_{\ell,\mu,\lambda_{\ell}}(D) \chi_{\ell \ell} \Vert_{L^2}^2 + 2\Vert m_{\ell+1,\mu,\lambda_{\ell}}(D) \chi_{\ell+1,\ell+1} \Vert_{L^2}^2  \\
    & = C \psi_{(1-\gamma)^{\ell-1}}\Big((\mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + \lambda^{-1} \Per(\Omega)\Big) + C \frac{\lambda_{\ell}^2}{|\nu_1|^2} E_\epsilon(u,\chi) \\
    & \leq C \psi_{(1-\gamma)^{\ell-1}}\Big((\frac{\lambda_{\ell}^2}{|\nu_1|^2} + \mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + \lambda^{-1} \Per(\Omega)\Big).
\end{align*}
Arguing as in the proof of \cref{prop:L1_4wells}, we optimize this in $\mu$ and $\lambda$ by fixing $\mu \sim |\nu_1|^{1/\ell} \lambda^{-1/\ell}$ and $\lambda \sim |\nu_1|^{2/(\ell+2)} \epsilon^{-\ell/(\ell+2)}$ (such a choice of parameters is compatible with the constraints on $\mu$ and $\bar\lambda$) and thus
\begin{align*}
    \Vert \chi_{\ell \ell} \Vert_{L^2}^2 + \Vert \chi_{\ell+1,\ell+1} \Vert_{L^2}^2 \leq C \psi_{(1-\gamma)^{\ell-1}}\Big(|\nu_1|^{-2/(\ell+2)} \epsilon^{-2/(\ell+2)} E_\epsilon(u,\chi) + |\nu_1|^{2/(\ell+2)} \epsilon^{\ell/(\ell+2)} \Per(\Omega)\Big).
\end{align*}
Using that
\begin{align*}
    \Vert \chi_{\ell \ell} \Vert_{L^2}^2 + \Vert \chi_{\ell+1,\ell+1} \Vert_{L^2}^2 \geq C(F) > 0,
\end{align*}
after arguing similarly as in the proof of \cref{prop:L1_2wells}, that is considering the two cases for $\psi_{(1-\gamma)^{\ell-1}}$ and absorbing the perimeter, we obtain with $C = C(d,F,\ell) > 0$ and for $\epsilon < \epsilon_0(d,F,\ell,|\nu_1|)$

\begin{align} \label{eq:HigherOrderScaling_1}
    E_\epsilon(u,\chi) \geq C |\nu_1|^{\frac{2}{\ell+2}} \epsilon^{\frac{2}{\ell+2}}.
\end{align}

\emph{The case $\nu \cdot e_1 = \dots = \nu \cdot e_{n} = 0$ and $\nu \cdot e_{k+1} \neq 0$, with $0 < n < \ell$:}
We argue similarly, but we start the iterative application of \cref{cor:CommutatorEst_Applied} for the $n+1$ diagonal entry $\chi_{n+1,n+1}$.

Note that due to the change of roles of the coordinate directions, the truncated cones in this setting are given by
\begin{align*}
    C_{j,\mu,\lambda}= \{k \in \Z^d: |k|^2-k_j^2 \leq \mu^2 |k|^2, |k_j| \leq \frac{2}{|\nu_n|} \lambda\},
\end{align*}
i.e. the truncation depends on $|\nu_n|$ instead of $|\nu_1|$ as above in \cref{thm:L1_3wells} in the case $\nu \cdot e_1 = 0$.


By \cref{lem:Localization}, with the roles of the axes changed such that $n+1$ is the first coordinate direction, we get
\begin{align*}
    &\quad \Vert \chi_{n+1,n+1} - m_{n+1,\mu,\lambda}(D) \chi_{n+1,n+1} \Vert_{L^2}^{2} + \sum_{j=2}^d \Vert \chi_{n+j,n+j} - m_{n+j,\mu}(D) \chi_{n+j,n+j} \Vert_{L^2}^{2} \\
    &\leq C (\mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(\chi) + C \lambda^{-1} \Per(\Omega).
\end{align*}
Applying an analogous iteration of a variant of \cref{cor:CommutatorEst_Applied} as above, now starting at $j = n+1$ instead of $j=1$, we deduce
\begin{align*}
    & \quad \sum_{j=\ell-n}^d \Vert \chi_{n+j,n+j} - m_{k+j,\mu,\lambda_{\ell-n}}(D) \chi_{n+j,n+j} \Vert_{L^2}^{2} \\
    &\leq C \psi_{(1-\gamma)^{\ell-n-1}}\Big((\mu^{-2} + (\lambda \epsilon)^{-1}) E_\epsilon(u,\chi) + \lambda^{-1} \Per(\Omega)\Big).
\end{align*}
Concluding as above for $\nu \cdot e_1 \neq 0$ to get \cref{eq:HigherOrderScaling_1}, while taking the off-set in the index into account, i.e. having $\ell-n$ instead of $\ell$, yields (where the constant can be chosen to be independent of $n$)
\begin{align*}
    E_\epsilon(u,\chi) \geq C |\nu_{n+1}|^{\frac{2}{\ell-n+2}} \epsilon^{\frac{2}{\ell-n+2}}.
\end{align*}
Here the scaling depends on $\nu_{n+1}$ instead of $\nu_1$ as above in \cref{eq:HigherOrderScaling_1} as we start our arguments with $\chi_{n+1,n+1}$ instead of $\chi_{11}$ and with the corresponding high frequency control in the direction $e_{n+1}$. This is due to the assumption that $\nu \cdot e_{n+1} \neq 0$.

\emph{The case $\nu \cdot e_1 = \dots = \nu \cdot e_{\ell} = 0$:}
If $\nu \cdot e_j = 0$ for $j=1,\dots,\ell$, we consider an $\ell$-th order simple laminate of arbitrary fine oscillations, as those directions are not penalized, yielding a minimizing sequence, with energies converging to zero.
We refer to the proof of \cref{prop:L1_2wells} for $\nu \cdot e_1 = 0$ for a similar setting.

\emph{Conclusion of the proof.}
As above, to combine the derived estimates we choose $\epsilon$ sufficiently small depending on $\nu$, that is for $0 \leq n < \ell$ being the index such that $\nu_{n+1} \neq 0$, $\nu_j = 0$ for $j \leq n$, we fix $\epsilon$ such that for all $n < j < \ell \leq d$
\begin{align*}
    |\nu_{j+1}|^{\frac{2}{\ell-j+2}} \epsilon^{\frac{2}{\ell-j+2}} \leq |\nu_{n+1}|^{\frac{2}{\ell-n+2}} \epsilon^{\frac{2}{\ell-n+2}},
\end{align*}
which is possible as $2/(\ell-j+2) > 2/(\ell-n+2)$.
Hence, we arrive at
\begin{align*}
    |\nu_{n+1}|^{\frac{2}{\ell-n+2}} \epsilon^{\frac{2}{\ell-n+2}} \geq \frac{1}{\ell-n} \left( \sum_{j=n}^{\ell-1} |\nu_{j+1}|^{\frac{2}{\ell-j+2}} \epsilon^{\frac{2}{\ell-j+2}} \right) \geq \frac{1}{\ell} \left( \sum_{j=0}^{\ell-1} |\nu_{j+1}|^{\frac{2}{\ell-j+2}} \epsilon^{\frac{2}{\ell-j+2}} \right),
\end{align*}
where we used that $\nu_{j+1} = 0$ for $0 \leq j < n$.
\end{proof}

We conclude our discussion of sharp interface models by highlighting that the above arguments also allow us to treat situations in which the set $T_{4}$ is given by the Tartar square (see \cref{sec:intro_appl}). This is of particular interest as it is an instance of an extremely rigid phase transition involving laminates of infinite order.

\begin{rmk}[On the Tartar square with anisotropic sharp interface energies]
    With the same arguments as above, it is possible to generalize the scaling of the Tartar square, cf. \cref{eq:Tartar}, that was derived in \cite{RT22} to a setting involving anisotropic surface energies.
    To be precise, for any $F \in T_{4}^{qc} \setminus T_4$, $\nu \in \S^1$ and $\eta \in (0,\frac{1}{2})$ it holds
    \begin{align*}
        \inf_{u \in \mathcal{A}_F} \inf_{\chi \in BV_\nu((0,1)^2;T_4)} \int_\Omega |\nabla u - \chi|^2 dx + \epsilon \Vert D_\nu \chi \Vert_{TV((0,1)^2)} \geq C \exp ( -  c_\eta |\log(\epsilon)|^{\frac{1}{2}+\eta}),
    \end{align*}
    for some constant $c_\eta>0$.
    Compared to the settings from above, there are no degenerate directions for the lower scaling bound in the Tartar square.
    This is due to the fact, that there are no rank-one connections present in the Tartar square and that, hence, each diagonal entry determines the corresponding other entry uniquely.
    As a consequence, if $\nu \cdot e_1 \neq 0$, we start by truncating the cone in $e_1$ direction, else we have $\nu \cdot e_2 \neq 0$ and thus can start by truncating the cone in $e_2$ direction.
\end{rmk}

\subsection{Proof of \cref{thm:frac_energy}}
\label{sec:frac_proof}

Building on the observations from \cref{sec:prelim_frac}, we conclude the proof of \cref{thm:frac_energy} analogously as in the (local) sharp interface arguments.

\begin{proof}[Proof of \cref{thm:frac_energy}]
\emph{Lower bound.}
We note that for $t_1,t_2 \in (0,1)$
\begin{align*}
    \psi_{t_1} \circ \psi_{t_2} (x) = \psi_{t_1t_2}(x),
\end{align*}
and thus
\begin{align*}
    \psi_{1-\gamma} \circ \psi_{2s} = \psi_{(1-\gamma)2s}.
\end{align*}
Setting $\gamma_s = 1-2s+2s \gamma \in (0,1)$, we combine \cref{cor:CommutatorEst_Applied,lem:LocalizationFrac} and get with a constant $C = C(d,F,s) > 0$
\begin{align*}
    \sum_{j=2}^d |\alpha_j| \Vert \chi_{jj}-m_{j,\mu,\lambda}(D)\chi_{jj}\Vert_{L^2}^{2} &\leq C \psi_{1-\gamma} \circ \psi_{2s}((\mu^{-2}+(\lambda \epsilon)^{-1})E_{\epsilon,s}(\chi)) \\
    &= C \psi_{1-\gamma_s}((\mu^{-2}+(\lambda\epsilon)^{-1})E_{\epsilon,s}(\chi)).
\end{align*}
Therefore, the remainder of the proof follows as the proof of \cref{thm:L1_mult_wells} also for the fractional surface energy.


\emph{Upper bound.}
Thanks to an interpolation argument, we prove that we can directly exploit the $BV$-regular upper bounds $\chi$ of \cref{thm:L1_mult_wells}.
For this, we argue similarly to \cite[Prop. 1.3]{BO13} but taking into account the anisotropy of the surface energy.
Let $\chi\in BV_\nu(\Omega;\K_N)$.
We first claim that for $\chi$ seen as a function on the torus $\T^d$ it holds
\begin{align*}
    \sum_{k \in \Z^d \setminus \{0\}} |k \cdot \nu|^{2s} |\hat{\chi}(k)|^2 \leq C(s) \int_{-\frac{1}{2}}^{\frac{1}{2}} \int_{\T^d} \frac{|\chi(x+h\nu)-\chi(x)|^2}{|h|^{1+2s}} dx dh + \Vert \chi \Vert_{L^2}^2.
\end{align*}
Indeed, this follows from observing that by Plancherel's theorem
\begin{align*}
    \int_{-\frac{1}{2}}^{\frac{1}{2}} \int_{\T^d} \frac{|\chi(x+h\nu)-\chi(x)|^2}{|h|^{1+2s}} dx dh = \int_{-\frac{1}{2}}^{\frac{1}{2}} \sum_{k \in \Z^d} \frac{|e^{2\pi i h k \cdot \nu}-1|^2}{|h|^{1+2s}} |\hat{\chi}(k)|^2 dh,
\end{align*}
and by noting that for $k \in \Z^d$ with $|k \cdot \nu|>1$ we have $(2|k\cdot \nu|)^{-1} \leq 2^{-1}$ and hence
\begin{align*}
    B_\nu(k) := |k \cdot \nu|^{-2s} \int_{-\frac{1}{2}}^{\frac{1}{2}} \frac{|e^{2\pi i h k \cdot \nu}-1|^2}{|h|^{1+2s}} dh \geq 8 |k \cdot \nu|^{-2s} \int_{0}^{\frac{1}{2|k \cdot \nu|}} \frac{\sin^2(\pi h |k \cdot \nu|)}{|h|^{1+2s}} dh \geq C(s)^{-1} > 0
\end{align*}
for a constant $C(s)$ independent of $k$.
With this in hand, by monotone convergence we have
\begin{align*}
    \sum_{k \in \Z^d \setminus\{0\}} |k \cdot \nu|^{2s} |\hat{\chi}(k)|^2 & = \sum_{|k \cdot \nu|>1} |k \cdot \nu|^{2s} |\hat{\chi}(k)|^2 + \sum_{|k \cdot \nu|\leq 1} |k \cdot \nu|^{2s} |\hat{\chi}(k)|^2 \\
    & \leq C(s) \sum_{|k \cdot \nu|>1} |k \cdot \nu|^{2s} B_\nu(k) |\hat{\chi}(k)|^2 + \sum_{|k \cdot \nu|\leq 1} |\hat{\chi}(k)|^2 \\
    & \leq C(s) \int_{-\frac{1}{2}}^{\frac{1}{2}} \int_{\T^d} \frac{|\chi(x+h\nu)-\chi(x)|^2}{|h|^{1+2s}} dx dh + \Vert \chi \Vert_{L^2}^2.
\end{align*}
We now fix $\tilde{\chi}: \R^d \to \K_N$ by setting
\begin{align*}
    \tilde{\chi}(x) := \begin{cases} \chi(x) & x \in (-1,2)^d, \\
    0 & \text{else}.
    \end{cases}
\end{align*}
Noting that for all $x \in (0,1)^d$ and $h \in [-\frac{1}{2},\frac{1}{2}]$ it holds that $x + h \nu \in (-1,2)^d$, by the definition of $\tilde{\chi}$ we infer that
\begin{align*}
    \sum_{k \in \Z^d \setminus \{0\}} |k \cdot \nu|^{2s} |\hat{\chi}(k)|^2 \leq C(s) \int_{\R} \int_{\R^d} \frac{|\tilde{\chi}(x+h\nu)-\tilde{\chi}(x)|^2}{|h|^{1+2s}} dxdh + \Vert \chi \Vert_{L^2}^2.
\end{align*}
Using a slicing argument together with a Gagliardo-Nirenberg type inequality \cite[Theorem 1]{BM18} (see also \cite[Theorem 2]{RZZ19})
\begin{align*}
    \int_\R \int_{\R^d} \frac{|\tilde{\chi}(x+h\nu) - \tilde{\chi}(x)|^2}{|h|^{1+2s}} &= \int_{\nu^\perp} \int_{\R} \int_{\R} \frac{|\tilde{\chi}_y^\nu(t+h)-\tilde{\chi}_y^\nu(t)|^2}{|h|^{1+2s}} dhdtdy \\
    &\leq C(s,d,\K) \int_{\nu^\perp} (\Vert \tilde{\chi}^\nu_y\Vert_{L^1(\R)} + \Vert D\tilde{\chi}^\nu_y \Vert_{TV(\R)})^{2s} dy.
\end{align*}
By the uniformly compact support of the functions $\tilde{\chi}$ on each slice and as $2s < 1$, we can further bound this by Jensen's inequality
\begin{align*}
    \int_{\nu^\perp} (\Vert \tilde{\chi}^\nu_y\Vert_{L^1(\R)} + \Vert D\tilde{\chi}^\nu_y \Vert_{TV(\R)})^{2s} dy &\leq C \Big( \int_{\nu^\perp} \Vert \tilde{\chi}^\nu_y\Vert_{L^1(\R)} + \Vert D\tilde{\chi}^\nu_y \Vert_{TV(\R)} dy \Big)^{\frac{1}{2s}} \\
    &= C \Big( \Vert \tilde{\chi} \Vert_{L^1(\R^d)} + \Vert D_\nu \tilde{\chi} \Vert_{TV(\R^d)} \Big)^{\frac{1}{2s}}.
\end{align*}
Thus, by the relation between $\chi$ and $\tilde{\chi}$, we conclude
\begin{align*}
    \sum_{k \in \Z^d \setminus \{0\}} |k \cdot \nu|^{2s} |\hat{\chi}(k)|^2 \leq C(s,d,\K)(1 + \Per(\Omega) + \Vert D_\nu \chi \Vert_{TV(\Omega)})^{\frac{1}{2s}}.
\end{align*}
In particular, this implies
\begin{align*}
    E_{\epsilon,s}(\chi) \leq C(s,d,\K) E_{\epsilon}(\chi) + C(s,d,\K) \epsilon (1+\Per(\Omega)).
\end{align*}
Thus, the matching upper bounds for the sharp interface model in \cref{thm:L1_mult_wells} are still applicable which yields the desired result.

\end{proof}



\section{Diffuse surface energies}
\label{sec:diffuse}

\subsection{Diffuse to sharp interface model -- the lower bound} \label{sec:diffuse1}
Following the arguments of \cite{KK11}, we show that in the continuous model,
the minimal diffuse energy can be controlled by the lower bound for the sharp interface energy. Hence,
the lower scaling estimates for the sharp interface model which had been deduced in the previous section for various anisotropic situations also give rise to lower scaling estimates for the diffuse energy.
We show this lower bound for any \emph{discrete set} of wells and also for a more general framework covering both the gradient and symmetrized gradient settings.
Combined with the upper bounds from the next subsection, this will lead to sharp scaling results in our model problems also for anisotropic, diffuse interface energies.


\subsubsection{The scalar-valued setting}
We first show the lower bound in the scalar-valued case, and afterwards will reduce the general vector-valued setting to the one-dimensional one by a projection argument.
\begin{lem} \label{lem:LowerDiffSharp_1D}
  Let $p,q \in [1,\infty)$ and $\Omega \subset \R^d$ be bounded and let $\K = \{A_{1}, \dots, A_{N}\} \subset \R$.
  For any $U \in L^p(\Omega;\R)\cap W^{1,q}(\Omega;\R)$, $f \in L^\infty(\Omega;\K)$ there exist $\tilde{f} \in BV(\Omega;\K)$ and a constant $C = C(\K,p,q) > 0$ such that for any $\epsilon >0$
  \begin{align}
  \label{eq:comparison_diff_sharp}
    \int_{\Omega} |U-f|^{p} + \epsilon^q |\nabla U|^{q} dx \geq C \epsilon \Vert D \tilde{f} \Vert_{TV(\Omega)}
    \quad\text{and}\quad
    |U-f| \geq C |U-\tilde{f}|.
  \end{align}
  For $q = 1$, the same result holds with $\Vert D U \Vert_{TV(\Omega)}$ instead of $\|\nabla U\|_{L^1(\Omega)}$ (on the left-hand side of \cref{eq:comparison_diff_sharp}), for $U \in BV(\Omega;\R)$ instead of $U \in W^{1,1}(\Omega;\R)$.
\end{lem}

\begin{proof}
  Up to relabelling, we can assume that $-\infty < A_1 < A_2 < \dots < A_N < + \infty$.
We start by giving the argument for the first inequality in \cref{eq:comparison_diff_sharp}.
We assume for simplicity that $U$ coincides with its Lebesgue representative.
In this case, for scalar-valued functions, the validity of the coarea formula
for Sobolev functions is known (cf.\ \cite{MSZ03}).
We, hence, invoke Young's inequality for $q>1$ and the coarea formula to get
\begin{align*}
  \int_\Omega |U-f|^p + \epsilon^q |\nabla U|^q dx & \geq \epsilon \int_\Omega |U-f|^{\frac{p(q-1)}{q}} |\nabla U| dx = \epsilon \int_\R \int_{U^{-1}(t) \cap \Omega} |t-f|^{\frac{p(q-1)}{q}}
                                                        d \mathcal{H}^{d-1}(x) dt \\
  & \geq \epsilon \sum_{k=1}^{N-1} \int_{A_{k}+\frac{c}{4}}^{A_{k+1}-\frac{c}{4}} \int_{U^{-1}(t) \cap \Omega} |t-f|^{\frac{p(q-1)}{q}} d\mathcal{H}^{d-1}(x) dt,
\end{align*}
where in the last inequality we introduced $c = \min \{ A_{k+1}-A_k : k = 1, \dots, N-1\}$.

As for $t \in (A_k + \frac{c}{4},A_{k+1}-\frac{c}{4})$ we have $\dist(t,\K) \geq \frac{c}{4}$, we can control $|t-f(x)|^{\frac{p(q-1)}{q}} \geq C$ with a constant $C = C(\K,p,q) > 0$.
Plugging this lower bound into the above inequality yields
\begin{align*}
  \int_\Omega |U-f|^p + \epsilon^q |\nabla U|^q dx & \geq C \epsilon \sum_{k=1}^{N-1} \int_{A_k + \frac{c}{4}}^{A_{k+1} - \frac{c}{4}} \mathcal{H}^{d-1}(\{x \in \Omega: U(x) =t\}) dt.
\end{align*}


For every $k \in \{1,\dots,N-1\}$ there is $t_k \in (A_k+\frac{c}{4}, A_{k+1}-\frac{c}{4})$, which, without loss of generality, we may assume to be a Lebesgue point for the function $t \mapsto \mathcal{H}^{d-1}(\{x
\in \Omega: U(x) = t \})$, such that
\begin{align*}
  \int_{A_k+\frac{c}{4}}^{A_{k+1}-\frac{c}{4}} \mathcal{H}^{d-1}(\{x \in \Omega: U(x) = t\}) dt &\geq (A_{k+1}-A_k - \frac{c}{2}) \mathcal{H}^{d-1}(\{x \in \Omega: U(x) = t_k\}) \\
  &\geq \frac{c}{2}
  \mathcal{H}^{d-1}(\{x \in \Omega: U(x) = t_k\}).
\end{align*}
Therefore, combined with the previous bound, we obtain
\begin{align*}
  \int_\Omega |U-f|^p + \epsilon^q |\nabla U|^q dx \geq C \epsilon \sum_{k=1}^{N-1} \mathcal{H}^{d-1}(\{x \in \Omega: U(x) = t_k\}).
\end{align*}
In particular, we obtain a sequence of $t_k$ such that $t_k < t_{k+1}$ for all $k \in \{1,\dots,N-2\}$.

The idea now is to define a new phase indicator with BV-seminorm which is exactly determined by these measures.
To this end let $h: \R \to \R$ be given as $h(t)= \sum_{k=1}^{N} A_k \chi_{(t_{k-1},t_k]}(t) \in \K$ and with slight abuse of notation, we set $t_0 := -\infty, t_N := \infty$. We define $\tilde{f} = (h \circ U) : \Omega \to \K$, and
claim that $\tilde{f} \in BV(\Omega;\K)$ and that it satisfies
\begin{align*}
  \Vert D \tilde{f} \Vert_{TV(\Omega)} \leq C \sum_{k=1}^{N-1} \mathcal{H}^{d-1}(\{x \in \Omega: U(x) = t_k\}).
\end{align*}

The claim will be shown by an approximation argument. To this end, let $h_j \in C^\infty(\R;\R)$ be a mollification of $h$ fulfilling $\supp(h-h_j) \subset \bigcup_{k=1}^{N-1}
(t_k-\frac{1}{j},t_k+\frac{1}{j})$, $|h_j'| \leq C j \chi_{\supp(h-h_j)}$, and $|h_j| \leq \max\K$.
By construction, it holds that $h_j(t) \to h(t)$ for every $t\neq t_k$, $k=1,\dots, N-1$.
Since the sets $\{U=t_k\}$ have Hausdorff dimension $d-1$, by the boundedness of $\Omega$, and
boundedness of $h_j$, the dominated convergence theorem implies $h_j \circ U  \to h \circ U = \tilde{f}$ in $L^1(\Omega)$.
As the BV-seminorm is lower semicontinuous with respect to the (strong) $L^1$ convergence, we deduce
\begin{align*}
  \Vert D \tilde{f} \Vert_{TV(\Omega)} \leq \liminf_{j \to \infty} \Vert D (h_j \circ U) \Vert_{TV(\Omega)}.
\end{align*}

As $h_j$ is smooth, we can use the chain rule to further bound the total variation norm.
Indeed, by the coarea formula
\begin{align*}
  \Vert D (h_j \circ U) \Vert_{TV(\Omega)} &= \int_\Omega |h_j'(U(x))| |\nabla U(x)| dx = \int_\R |h_j'(t)| \mathcal{H}^{d-1}(\{x \in \Omega: U(x) = t\}) dt \\
  & \leq C j \sum_{k=1}^{N-1} \int_{t_k-\frac{1}{j}}^{t_k + \frac{1}{j}} \mathcal{H}^{d-1}(\{x \in \Omega: U(x) = t\}) dt \\
  & \to \frac{C}{2} \sum_{k=1}^{N-1} \mathcal{H}^{d-1}(\{x \in \Omega: U(x) = t_k\}).
\end{align*}
Here we used that the $t_k$ are Lebesgue points of the function $t \mapsto \mathcal{H}^{d-1}(\{x \in \Omega: U(x) = t \})$.

Thus, with this definition, $\tilde{f} \in BV(\Omega;\K)$ and also the desired upper bound from \cref{eq:comparison_diff_sharp} follows.



If $q = 1$, we do not use Young's inequality, but neglect the first term. We give the argument for $U \in BV(\Omega;\R)$ and note that the statement for $U \in W^{1,1}(\Omega;\R)$ is also covered by this.
By the coarea formula for BV functions \cite[Thm 3.40]{AFP00}
\begin{align*}
    \int_\Omega |U - f|^p dx &+ \epsilon \Vert DU \Vert_{TV(\Omega)} \geq \epsilon \Vert DU \Vert_{TV(\Omega)} = \epsilon \int_{\R} \Vert D \chi_{\{U > t\}} \Vert_{TV(\Omega)} dt \\
    &\geq \epsilon \sum_{k=1}^{N-1} \int_{A_{k}}^{A_{k+1}} \Vert D \chi_{\{U>t\}} \Vert_{TV(\Omega)} dt \geq \epsilon \sum_{k=1}^{N-1} |A_{k+1}-A_k| \Vert D \chi_{\{U> t_{k}\}} \Vert_{TV(\Omega)},
\end{align*}
for some $t_k \in (A_k,A_{k+1})$.
Considering the function $h: \R \to \R$ and $\tilde{f} = h \circ U$ as above, we write $h$ as
\begin{align*}
    h(t) = A_1 + \sum_{k=1}^{N-1} (A_{k+1}-A_k) \chi_{(t_k,\infty)}(t),
\end{align*}
and thus it holds
\begin{align*}
    \tilde{f}(x) = h \circ U(x) &= A_{1} + \sum_{k=1}^{N-1} (A_{k+1}-A_k) \chi_{\{U>t_k\}}(x).
\end{align*}
In particular, we have
\begin{align*}
    \epsilon \Vert D \tilde{f} \Vert_{TV(\Omega)} & \leq \epsilon \sum_{k=1}^{N-1} |A_{k+1}-A_k| \ \Vert D \chi_{\{U>t_k\}}\Vert_{TV(\Omega)} \\
    & \leq \int_\Omega |U-f|^p dx + \epsilon \Vert DU\Vert_{TV(\Omega)}.
\end{align*}


Now we prove the second inequality from \cref{eq:comparison_diff_sharp}. %, we claim that for almost every $x \in \Omega$ it holds $|U(x)-f(x)| \geq c |U(x)-\tilde{f}(x)|$.
For this, let $x \in \Omega$ and $k \in \{1,\dots,N-1\}$ be such that $U(x) \in (\frac{A_k+A_{k-1}}{2}, \frac{A_k+A_{k+1}}{2}]$, where we set $A_0 = -\infty$ and $A_{N+1} = \infty$. In particular, $|U(x)-A_k| =
\dist(U(x),\K)$.
We distinguish two cases, which are illustrated in \cref{fig:LowerDiffSharp_1D}.

On the one hand, if $U(x) \in (t_{k-1},t_k]$, we have $\tilde{f}(x) = A_k$ and thus $|U(x)-\tilde{f}(x)| = \dist(U(x),\K) \leq |U(x)-f(x)|$.


On the other hand, if $U(x) \notin (t_{k-1},t_k]$, we have either
\begin{align*}
U(x) > t_k > A_k + \frac{c}{4}\quad \text{or} \quad U(x) \leq t_{k-1} < A_k - \frac{c}{4},
\end{align*}
and hence $\dist(U,\K) = |U(x)-A_k| > \frac{c}{4}$.
This means that %$U(x)$ is far away from $\K$, hence
$|U(x)- f(x)| \geq \frac{c}{4}$ and furthermore
\begin{align*}
    |U(x) - \tilde{f}(x)| \leq |U(x)-f(x)| + |f(x) -\tilde{f}(x)| \leq |U(x)-f(x)| + \diam(\K) \leq C |U(x)-f(x)|.
\end{align*}
This concludes the proof. %pointwise estimate $|U(x)-f(x)| \geq C |U(x)-\tilde{f}(x)|$ and, thus, also the second inequality  in \cref{eq:comparison_diff_sharp} is shown.

