Seeking to deduce the same scaling laws from \cref{sec:intro_L1} for diffuse surface energies,
we also generalize \cref{lem:LowerDiffSharp_1D} to anisotropic surface energies:
\begin{cor} \label{cor:DiffuseToSharp_Aniso_1D}
  Let $p,q \in [1,\infty)$, $\nu \in \S^{d-1}$ and $\Omega \subset \R^d$ be a bounded Lipschitz domain and let $\K = \{A_1,\dots,A_N\} \subset \R$. For any $U \in L^p(\Omega;\R)$ such that the weak directional
  derivative satisfies $\p_{\nu} U \in L^q(\Omega;\R)$ and $f \in L^\infty(\Omega; \K)$ there exist $\tilde{f} \in BV_{\nu}(\Omega;\K)$ and a constant $C = C(\K,p,q) > 0$ such that for any $\epsilon >0$
  \begin{align*}
    \int_\Omega |U-f|^p + \epsilon^q |\p_{\nu} U |^q dx \geq C \epsilon \Vert D_{\nu} \tilde{f} \Vert_{TV(\Omega)},
    \quad \text{and}\quad
    \int_\Omega|U-f|^p dx \geq C \int_\Omega|U - \tilde{f}|^p dx.
  \end{align*}
\end{cor}

\begin{proof}
The proof uses similar methods as above, with the addition of a splitting in direction $\nu$ and $\nu^\perp$.
We start by considering $U\in W^{1,p}(\R^d;\R)$.
For almost every $y \in \Omega_\nu$ (see \cref{sec:prelim_directBV} for the notation), we follow the arguments from the previous proof and obtain
  \begin{align*}
    \int_\Omega |U-f|^p + \epsilon^q |\p_\nu U|^q dx& \geq \epsilon \int_{\Omega_\nu} \int_{\Omega^\nu_y} |U^\nu_y(t)-f^\nu_y(t)|^{\frac{p(q-1)}{q}} |(U_y^\nu)'(t)| dt dy \\
    &\geq C \epsilon
    \int_{\Omega_\nu} \sum_{k=1}^{N-1} \mathcal{H}^0(\{s \in \Omega^\nu_y: U^\nu_y(s) = t_k^{y}\}) dy,
  \end{align*}
  where, for a.e.\ $y\in\Omega_\nu$, $t_k^y\in(A_k+\frac{c}{4},A_{k+1}-\frac{c}{4})$, with $c$ defined as in the proof of \cref{lem:LowerDiffSharp_1D}.

  The main difference with respect to the isotropic case, is that here we use a slicing argument, hence in the definition of the modified phase indicator $\tilde f$, the thresholds $t_k^y$ change from slice to slice, giving in principle measurability issues.
  To avoid this, we define $\tilde f$ to be piecewise constant in the variable $y$ as follows.

  Given $\delta>0$, we define $\mathcal{L}_\delta:=\{z\in\delta\Z^{d-1} : Q_\delta(z)\subset\Omega_\nu\}$, where $Q_\delta(z)=(0,\delta)^{d-1}+z$, and we use the notation $\mathcal{L}_\delta=\{z_j\}_{j=1}^{M}$, with $M=\#\mathcal{L}_\delta$ (the dependence on $\nu$ is omitted for the sake of clarity of exposition).
  From the above estimate, by an average argument, we get
  \begin{align}\label{eq:slicing-MM1}
  \begin{split}
      \int_\Omega |U-f|^p + \epsilon^q |\p_\nu U|^q dx& \geq C\epsilon \sum_{j=1}^M \int_{Q_\delta(z_j)}\sum_{k=1}^{N-1}\mathcal{H}^0(\{s \in \Omega^\nu_y: U^\nu_y(s) = t_k^y\}) dy\\
      &\ge C\epsilon\delta^{d-1} \sum_{j=1}^M \sum_{k=1}^{N-1}\mathcal{H}^0(\{s \in \Omega^\nu_{y_j}: U^\nu_{y_j}(s) = t_k^{y_j}\})
      \end{split}
  \end{align}
  with $y_j\in Q_\delta(z_j)$.
  In every cube, we now work as in the proof of \cref{lem:LowerDiffSharp_1D}, namely we define $h_j=\sum_{k=1}^N A_k\chi_{(t_{k-1}^{y_j},t_k^{y_j}]}$ and $\tilde f_j^\nu:=h_j\circ U_{y_j}^\nu$.
  Notice that as $U \in W^{1,p}(\R^d;\R)$ the functions $\tilde f_j^\nu$ are defined on the whole $\R$.
  Working as in the previous proof, for every $j$ we have
  \begin{equation}\label{eq:slicing-MM2}
    \|D\tilde f_j^\nu\|_{TV(\Omega_{y_j}^\nu)} \le C\sum_{k=1}^{N-1}\mathcal{H}^0(\{s \in \Omega^\nu_{y_j}: U^\nu_{y_j}(s)  = t_k^{y_j}\}).
    \end{equation}
  Defining
  \begin{align*}
  \tilde f(x) :=\begin{cases}
    \tilde f^\nu_j(t), &\Pi_{\nu^\perp}x=y\in Q_\delta(z_j),\, x=y+t\nu,\, j\in\{1,\dots,M\} \\
    A_1 & \text{otherwise},
  \end{cases}
  \end{align*}
  by slicing $\tilde f\in BV_\nu(\Omega;\K)$ and combining \cref{eq:slicing-MM1,eq:slicing-MM2} we get
  \begin{align*}
  \epsilon\|D_\nu\tilde f\|_{TV(\Omega)} &= \epsilon\sum_{j=1}^M \|D_\nu\tilde f\|_{TV(C_\delta(z_j))} = \epsilon\delta^{d-1}\sum_{j=1}^M \|D\tilde f_j^{\nu}\|_{TV(\Omega_{y_j}^\nu)}\\
  &\le C\int_\Omega|U-f|^p+\epsilon^q|\p_\nu U|^qdx,
  \end{align*}
  where $C_\delta(z_j):=\{x\in\Omega : \Pi_{\nu^\perp}x\in Q_\delta(z_j)\}.$

  %Here we used that as $\p_\nu U \in L^q(\Omega;\R)$ in particular $U \in BV_\nu(\Omega;\R)$ and thus $U^\nu_y \in BV(\Omega^\nu_y;\R)$, cf. \cref{sec:prelim_directBV}.
  For $U \in BV_\nu(\R^d;\R)$ we can then also follow the arguments in the proof of \cref{lem:LowerDiffSharp_1D} combined with the methods above to show the estimate.

We now prove the estimate regarding elastic energies.
Notice preliminarily that we can assume that $U\neq f$ in $L^p$ otherwise we can simply choose $\tilde
f=U$.

By definition of $\tilde f_j^\nu$, arguing as in the proof of \cref{lem:LowerDiffSharp_1D} the pointwise estimate holds $|U_{y_j}^\nu(t)-\tilde f_j^\nu(t)|\le C\dist (U_{y_j}^\nu(t),\K)$ a.e.\ in $\R$.
Hence, applying the triangle inequality twice, we may write
\begin{align*}
    &\int_{Q_\delta(z_j)}\int_{\Omega_y^\nu}|U_y^\nu(t)-(\tilde f)_y^\nu(t)|^p dt dy \\
    &\qquad \le 2^{p-1}\int_{Q_\delta(z_j)}\int_{\Omega_y^\nu}|U_y^\nu(t)-U_{y_j}^\nu(t)|^p dt dy + 2^{p-1}\int_{Q_\delta(z_j)}\int_{\Omega_y^\nu}|U_{y_j}^\nu(t)-\tilde f_j^\nu(t)|^p dt dy \\
    &\qquad \le 2^p\int_{Q_\delta(z_j)}\int_{\Omega_y^\nu}|U_y^\nu(t)-U_{y_j}^\nu(t)|^p dt dy + 2^{p-1}\int_{Q_\delta(z_j)}\int_{\Omega_{y}^\nu}\dist^p(U_y^\nu(t),\K) dt dy
\end{align*}
Eventually, since $U\in W^{1,p}(\R^d;\R)$ by assumption, we infer
\begin{align*}
    &\int_{Q_\delta(z_j)}\int_{\Omega_y^\nu}|U_y^\nu(t)-U_{y_j}^\nu(t)|^pdtdy = \int_{Q_\delta(z_j)}\int_{\Omega_y^\nu} |U(y+t\nu)-U(y_j+t\nu)|^p dtdy \\
    &\qquad\le \sup_{|h|\le\delta\sqrt{d-1}}\int_{C_\delta(z_j)\cap\Omega_\delta}|U(x)-U(x+h)|^pdx+C\int_{C_\delta(z_j)\setminus\Omega_\delta}|U(x)|^pdx \\
    &\qquad\le C \delta^p\|\nabla U\|_{L^p(\Omega_\delta^j)}^p+C\|U\|^p_{L^p(C_\delta(z_j)\setminus\Omega_\delta)},
\end{align*}
where $\Omega_\delta:=\{x\in\Omega:\dist(x,\p\Omega)>2\sqrt{d-1}\delta\}$,
and where we used the notation $\Omega_\delta^j=(B^{d-1}_{2\delta\sqrt{d-1}}(z_j)\times\R\nu)\cap\Omega$ which intersect a finite number of times.
Gathering the two above inequalities, and summing over $j$ we obtain
\begin{align*}
    \int_\Omega|U(x)-\tilde f(x)|^pdx\le C\int_\Omega\dist^p(U(x),\K)dx+C\delta^p\|\nabla U\|_{L^p(\Omega)}^p+C\int_{\Omega\setminus\Omega_\delta}|U(x)|^pdx + C |\Omega \setminus \Omega_\delta|.
\end{align*}
%with $\Omega_\delta=\bigcup_{j=1}^M (Q_\delta(z_j)\times\R\nu)\cap\Omega$.
Taking $\delta$ sufficiently small, the result follows for every $U\in W^{1,p}(\Omega;\R)$.
By an approximation argument, let $U_n\in W^{1,p}(\R^d;\R)$ converge to $U$ strongly in $L^p(\Omega)$ and $\p_\nu U_n$ converge to $\p_\nu U$ strongly in $L^q(\Omega)$ and let $\tilde f_n$ be their phase indicators (defined as above), we have that
\begin{align*}
\int_\Omega |U-\tilde f_n|^pdx \le C\int_\Omega|U-U_n|^pdx +C\int_\Omega|U_n-\tilde f_n|^pdx.
\end{align*}
By taking $n$ sufficiently large (and $\delta>0$ sufficiently small such
  that $C\delta^p\|\nabla U\|_{L^p(\Omega)}^p+C\|U\|_{L^p(\Omega\setminus\Omega_\delta)} + C |\Omega \setminus \Omega_\delta|<\frac{\eta}{2}$), the result follows:
\begin{align*}
&\int_\Omega |U-\tilde f_n|^pdx \le \eta +C\int_\Omega\dist^p(U_n(x),\K)dx\\
&\le \eta +C\int_\Omega\dist^p(U(x),\K)dx + C\int_\Omega|U-U_n|^pdx
\le 2 \eta +C\int_\Omega\dist^p(U(x),\K)dx ,
\end{align*}
after choosing $\eta \leq \int_\Omega\dist^p(U(x),\K)dx$.
Analogously, for $n$ sufficiently large we get
\begin{align*}
\|D_\nu\tilde f_n\|_{TV(\Omega)} \le C\int_\Omega|U_n-f|^p+\epsilon^q|\p_\nu U_n|^qdx \le C\int_\Omega|U-f|^p+\epsilon^q|\p_\nu U|^qdx+C \eta
\end{align*}
which gives the result.
\end{proof}


\subsubsection{The vector-valued setting}
In this section, we translate the results from the previous section to the vector-valued setting.

\begin{prop} \label{prop:DiffToSharp_Full}
  Let $p,q \in [1,\infty)$ and $\Omega \subset \R^d$ be bounded and let $\K =
  \{A_1,\dots,A_N\} \subset \R^n$. For any $U \in L^p(\Omega;\R^n)\cap W^{1,q}(\Omega;\R^n)$ and $\chi \in L^\infty(\Omega;\K)$ there exist $\tilde{\chi} \in BV(\Omega;\K)$ and a constant $C = C(\K,p,q) > 0$ such that for any $\epsilon >0$
  \begin{align*}
    \int_\Omega |U-\chi|^p + \epsilon^q |\nabla U|^q dx \geq C \epsilon \Vert D \tilde{\chi} \Vert_{TV(\Omega)}
    \quad\text{and}\quad
    |U-\chi|  \geq C  |U-\tilde{\chi}|.
  \end{align*}
  In particular,
  \begin{align*}
    \int_\Omega |U-\chi|^p + \epsilon^q |\nabla U|^q dx & \geq C \left( \int_\Omega |U-\tilde{\chi}|^p dx + \epsilon \Vert D \tilde{\chi} \Vert_{TV(\Omega)} \right).
  \end{align*}
\end{prop}

\begin{proof}
  The main idea is to invoke \cref{lem:LowerDiffSharp_1D} for a suitable projection of the wells onto a one-dimensional subspace in which there are still $N$ distinct wells.
  For this we choose
  \begin{align*}
    \zeta \in \mathbb{S}^{n-1} \setminus \left( \bigcup_{i \neq j} (A_i-A_j)^\perp \right)\neq \emptyset.
  \end{align*}
  By this choice of $\zeta$, we know that $A_i \cdot \zeta \neq A_j \cdot \zeta$ for any $i,j \in \{1,\dots,N\}, i \neq j$, hence there is a one-to-one correspondence of $\K' = \{A_1 \cdot \zeta, A_2 \cdot
  \zeta, \dots, A_N \cdot \zeta\}$ and $\K$.
  For further use in what follows below, we note that due to the discreteness of $\K$ and $\K'$ we can define a Lipschitz map
  \begin{align}
  \label{eq:map_h}
  h\in C^1(\R;\R^n) \mbox{ with } h(A_j \cdot \zeta) = A_j \mbox{ for all } j \in \{1,2,\dots,N\}.
  \end{align}

  Now we project the energy onto the direction $\zeta$ in the image:
  \begin{align*}
    \int_\Omega |U-\chi|^p + \epsilon^q |\nabla U|^q dx \geq \int_\Omega |U \cdot \zeta - \chi \cdot \zeta|^p + \epsilon^q |\nabla (U \cdot \zeta)|^q dx.
  \end{align*}

  The functions $U\cdot \zeta: \R^d \to \R$ and $\chi \cdot \zeta: \R^d \to \K'$ are admissible for \cref{lem:LowerDiffSharp_1D}, and thus there is $\tilde{f} \in BV(\Omega;\K')$ and $C =C(\K,p,q)>0$ such that
  \begin{align}
  \label{eq:first_step}
    \int_\Omega |U-\chi|^p + \epsilon^q |\nabla U|^q dx \geq C \epsilon \Vert D \tilde{f} \Vert_{TV(\Omega)}, \quad |U\cdot \zeta- \chi \cdot \zeta| \geq C |U \cdot \zeta - \tilde{f}|.
  \end{align}
  Using the determinedness of $\K$ in terms of $\K'$, i.e. using the function $h:\R \to \R^n$ from \cref{eq:map_h}, and the chain rule in BV \cite[Thm 3.96]{AFP00} hence shows that $\tilde{\chi} = h \circ \tilde{f} \in BV(\Omega;\K)$ and
  \begin{align*}
    \Vert D \tilde{\chi}\Vert_{TV(\Omega)} \leq C(\K) \Vert D \tilde{f} \Vert_{TV(\Omega)}.
  \end{align*}
  Combining this bound with \cref{eq:first_step} yields
  \begin{align*}
    \int_\Omega |U-\chi|^p + \epsilon^q |\nabla U|^q dx \geq C \epsilon \Vert D \tilde{\chi} \Vert_{TV(\Omega)}.
  \end{align*}


  The pointwise bound follows with the same argument as in the one-dimensional case. Let $x \in \Omega$ and $k \in \{1,\dots,N\}$ be such that $\dist(U(x),\K) = |U(x)-A_k|$.
  If $\tilde{\chi}(x) = A_k$, it is direct that $|U(x)-\chi(x)| \geq |U(x)-A_k| = |U(x)-\tilde{\chi}(x)|$.
  If $\tilde{\chi}(x) \neq A_k$, also $\tilde{f}(x) \neq A_k \cdot \zeta$, and we can deduce that $|U(x) \cdot \zeta - A_{k} \cdot \zeta| \geq C$ and thus also $\dist(U(x),\K) \geq C$ and hence
  \begin{align*}
    |U(x)-\tilde{\chi}(x)|& \leq |U(x)-\chi(x)| + |\chi(x)-\tilde{\chi}(x)| \leq |U(x)-\chi(x)| + \diam(\K) \\
    & \leq |U(x) - \chi(x)| + c \dist(U(x),\K) \leq C |U(x)-\chi(x)|.
  \end{align*}
  The two cases are illustrated in \cref{fig:LowerDiffSharp}.
  \begin{figure}
    \centering
    \begin{tikzpicture}[thick]
      \draw[->] (-4,-1) -- (4,1) node[below] {$\zeta$};

      \fill (-1/4,1) circle (0.1) node[left] {$A_{k}$};
      \fill (-2.25,0.5) circle (0.1) node[left] {$A_{k-1}$};
      \fill (1.5,-1.75) circle (0.1) node[right] {$A_{k+1}$};

      \draw[dashed, gray] (0,0) -- (-1/4,1); % A_k
      \draw[dashed, gray] (1,0.25) -- (1.5,-1.75); % A_{k+1}
      \draw[dashed, gray] (-2,-0.5) -- (-2.25,0.5); % A_{k-1}

      \draw[gray] (0,0) circle (0.05);
      \draw[gray] (1,0.25) circle (0.05);
      \draw[gray] (-2,-0.5) circle (0.05);

      \draw[{(-)}] (-1.4,-0.35) node[below right] {$t_{k-1}$} -- (0.8,0.2) node[below right] {$t_k$};
      \draw[dotted] (-119/80-41/80,2.05) -- (-119/80+41/80,-2.05);
      \draw[dotted] (17/20-41/80,2.05) -- (17/20+41/80,-2.05);


      \fill[draw = none, pattern = north west lines, pattern color = Blue] (-63/40,2.05) -- (-3/4,-5/4) -- (9/10,-1/5) -- (17/20-41/80,2.05) -- cycle;
      \fill[draw = none, pattern = north east lines, pattern color = Orange] (17/20-41/80,2.05) -- (31/8,2.05) -- (31/8,149/88) -- (9/10,-1/5) -- cycle;

      % draw Voronoi regions
      % A_{k-1} -> A_k
      \draw[gray,thin] (-63/40,2.05) -- (-3/4,-5/4);

      % A_k -> A_{k+1}
      \draw[gray,thin] (31/8,149/88) -- (-3/4,-5/4);

