\end{proof}

Also this result can be translated to anisotropic surface energies which proves \cref{thm:comparison}.


\begin{proof}[Proof of \cref{thm:comparison}]
  We split the energy into the $r$ component and the remainder.
  By an application of \cref{cor:DiffuseToSharp_Aniso_1D} it holds
  \begin{align*}
    \int_\Omega |U-\chi|^p + \epsilon^q |\p_\nu (U \cdot r)|^q dx
    & \geq \int_\Omega |U\cdot r -
    \chi \cdot r|^p + \epsilon^q |\p_\nu (U \cdot r)|^q dx\\
    & \geq C (\int_\Omega |U \cdot r -
    f_{r}|^p dx + \epsilon\Vert D_\nu f_{r} \Vert_{TV(\Omega)}),
  \end{align*}
  for some $f_{r}: \Omega \to \{A_1 \cdot r, A_2 \cdot r, \dots, A_N \cdot r\}$.
  We now define $\tilde{\chi} \in BV_{\nu}(\Omega, \K)$ by setting $\tilde{\chi} \cdot r = f_{r}$. To fix the part
  perpendicular to $r$, we choose $\Pi_{r^\perp} \tilde{\chi} = \tilde{\chi} - (\tilde{\chi} \cdot r) r$ as the projection
  of $\Pi_{r^\perp} U$ onto $\Pi_{r^\perp} \K = \{A_1 - (A_1 \cdot r) r, \dots, A_N -
  (A_N \cdot r) r\}$ with the additional constraint that $\tilde{\chi} = f_{r} r + \Pi_{r^\perp} \tilde{\chi} \in \K$.
  That is $\tilde{\chi}$ is chosen such that
  \begin{align*}
      |U(x) - \tilde{\chi}(x)| = \min \{|U(x)-A_k|: A_k \cdot r = f_{r}(x)\}, \quad \text{for a.e. } x\in\Omega.
  \end{align*}
  Then we have
  \begin{align*}
    \int_\Omega\left| U- \chi \right|^p dx \geq c \int_\Omega\left| U - \tilde{\chi} \right|^pdx.
  \end{align*}
    Indeed, by \cref{cor:DiffuseToSharp_Aniso_1D} and the pointwise estimate in the orthogonal part we get
\begin{align*}
\int_\Omega|U-\chi|^pdx &= \int_\Omega|U\cdot r-\chi\cdot r|^p+|\Pi_{r^\perp}U-\Pi_{r^\perp}\chi|^pdx \\
&\ge \int_\Omega|U\cdot r-f_r|^p + \dist^p(\Pi_{r^\perp}U,\Pi_{r^\perp}\K) dx = \int_\Omega |U-\tilde\chi|^pdx.
\end{align*}
    % Indeed, if $\chi \cdot r  =f_{r}$, this estimate follows directly by the definition of $\tilde{\chi}$. If $\chi \cdot r \neq f_{r}$, we know
    % \begin{align*}
    %     \dist(U,\K) \geq \dist(U \cdot r, \K \cdot r) \geq \frac{c}{4},
    % \end{align*}
    % as shown in the proof of \cref{lem:LowerDiffSharp_1D}. Concluding as in the proof above, the claim follows.
  In conclusion, by \cref{cor:DiffuseToSharp_Aniso_1D}, we obtain
  \begin{align*}
    \int_\Omega |U-\chi|^p + \epsilon^q |\p_\nu (U\cdot r)|^q dx &\geq C \int_\Omega
    |U - \tilde{\chi}|^p + |U \cdot r - \chi \cdot r|^p + \epsilon^q
                                                                      |\p_\nu (U \cdot r)|^q dx \\
    & \geq C \int_\Omega |U - \tilde{\chi}|^p dx + C \epsilon \Vert D_\nu f_{r} \Vert_{TV(\Omega)} \\
    & \geq C \left( \int_\Omega |U - \tilde{\chi}|^p dx + \epsilon \Vert D_{\nu} (\tilde{\chi}
      \cdot r) \Vert_{TV(\Omega)} \right).
  \end{align*}
\end{proof}

\subsection{Diffuse to sharp interface model -- the upper bound} \label{sec:diffuse2}

Based on the estimates in \cref{prop:DiffToSharp_Full,thm:comparison} in this section we provide a complementary upper bound. Due to the presence of ``lower order errors'', on its own, this upper bound does not show that the diffuse and sharp interface models display the same scaling behaviour. However, with the knowledge of known upper bounds (e.g. in our prototypical model scenarios), it implies that for all our applications the diffuse and sharp interface models admit the same $\epsilon$ scaling.

\begin{lem} \label{lem:DiffToSharp_Mollified}
    Let $\Omega = (0,1)^d$, $p,q \in [1,\infty)$. For any $U \in L^p(\R^d;\R^n)\cap BV(\R^d;\R^n)$ with $U = 0$ outside $\Omega$, $\chi \in L^\infty(\R^d;\R^n) \cap BV(\R^d;\R^n)$, and $\epsilon >0$ there exist $U_\epsilon \in C^\infty_0(\Omega;\R^n)$ %$U_\epsilon \in L^p(\R^d;\R^n) \cap W^{1,q}(\R^d;\R^n)$ with $U_\epsilon = 0$ outside $\Omega$
    and a constant $C = C(\Vert \chi \Vert_{L^\infty}, p, q, d) > 0$ such that
    \begin{align*}
        \int_{\Omega} |U_\epsilon - \chi|^p + \epsilon^q |\nabla U_\epsilon|^q dx &\leq C \Big( \int_{\Omega} |U - \chi|^p dx + \epsilon (1+\max\{\Vert U \Vert_{L^\infty}^{p-1}, \Vert U \Vert_{L^\infty}^{q-1}\})\Vert D \chi \Vert_{TV(\Omega)} \\
        & \quad +  \epsilon \max\{\Vert U \Vert_{L^\infty}^{p-1}, \Vert U \Vert_{L^\infty}^{q-1}\} ( \Vert DU - D\chi \Vert_{TV(\R^d)} +  \Per(\Omega)) \Big).
    \end{align*}
    Moreover, if we have $\operatorname{curl} U= 0$ or $\operatorname{curl} \operatorname{curl} U = 0$ in $\R^d$ it also holds $\operatorname{curl} U_{\epsilon} = 0$ or $\operatorname{curl} \operatorname{curl} U_\epsilon = 0$ in $\R^d$, respectively.
\end{lem}

We highlight that similar arguments would also work for more general $\mathcal{A}$-free differential inclusions as in \cite{RRTT24}.

\begin{proof}
We split the proof into two parts, first presenting the construction of the main estimate without adjusting the boundary conditions of the function $U_{\epsilon}$ and then correcting for this.

\emph{Step 1: The estimate without the boundary conditions.}
    Let us start by giving the argument for $U \in L^{p}(\R^d;\R^n) \cap BV(\R^d;\R^n)$ with $U = 0$ outside $\Omega$ and $\chi \in L^\infty(\R^d;\R^n) \cap BV(\R^d;\R^n)$, but without preserving the ``boundary condition''. We use this to show the full result with the preserved boundary conditions in what follows below.
    We set $U_\epsilon = U \ast \psi_\epsilon$, where $\psi_\epsilon$ is a radially symmetric mollifier with $\psi_\epsilon(x)=\epsilon^{-d}\psi(\epsilon^{-1}x)$, $\int_{\R^d} \psi_\epsilon dx = 1$, $\supp( \psi_\epsilon) \subset B_\epsilon(0)$.

    First let us consider some auxiliary results.
    By Young's convolution inequality, it holds for any $f \in L^r(\R^d;\R^n)$, $1 \leq r \leq \infty$, that
    \begin{align} \label{eq:DiffToSharp_Young}
        \Vert \nabla (f \ast \psi_\epsilon) \Vert_{L^r} \leq \Vert \nabla \psi_\epsilon \Vert_{L^1} \Vert f \Vert_{L^r} \leq \epsilon^{-1} \Vert \nabla \psi \Vert_{L^1} \Vert f \Vert_{L^r},
    \end{align}
    where we used
    \begin{align*}
        \int_{\R^d} |\nabla \psi_\epsilon(x)| dx = \int_{\R^d} \epsilon^{-d-1} |\nabla \psi(x/\epsilon)| dx = \epsilon^{-1} \Vert \nabla \psi \Vert_{L^1}.
    \end{align*}

    Next, since $U \in BV(\R^d;\R^n)$,
    \begin{align*}
        \int_{\R^d} U_\epsilon(x) \cdot \di \phi(x) dx & = \int_{\R^d} \int_{\R^d} U(x) \psi_\epsilon(y) \cdot \di \phi(x+y) dy dx \\ & = \int_{\R^d} U(x) \cdot \di(\phi \ast \psi_\epsilon)(x) dx \leq \Vert D U \Vert_{TV(\R^d)},
    \end{align*}
    and thus
    \begin{align} \label{eq:DiffToSharp_Gradient}
        \Vert \nabla U_\epsilon \Vert_{L^1} \leq \Vert D U \Vert_{TV(\R^d)}.
    \end{align}
    The same then holds for $\chi$, and $U - \chi$.
    As a last ingredient, we observe that
    \begin{align} \label{eq:DiffToSharp_ConvRate}
        \Vert \chi \ast \psi_\epsilon - \chi \Vert_{L^1} \leq C \epsilon \Vert D \chi \Vert_{TV(\R^d)}.
    \end{align}

    With this we can prove the claim.
    Starting with the diffuse elastic energy, we have
    \begin{align*}
        \int_{\R^d} |U_\epsilon - \chi|^p dx &\leq C(p) \left( \Vert (U-\chi) \ast \psi_\epsilon \Vert_{L^p}^p + \Vert \chi \ast \psi_\epsilon - \chi \Vert_{L^p}^p \right) \\
        & \leq C(p) \left( \Vert U - \chi\Vert_{L^p}^p + \Vert \chi \ast \psi_\epsilon - \chi \Vert_{L^\infty}^{p-1} \Vert \chi \ast \psi_\epsilon - \chi \Vert_{L^1} \right) \\
        & \leq C(p) \left( \Vert U - \chi \Vert_{L^p}^p + \epsilon \Vert \chi \Vert_{L^\infty}^{p-1} \Vert D \chi \Vert_{TV(\R^d)}\right),
    \end{align*}
    where in the last step we applied \cref{eq:DiffToSharp_ConvRate}.

    For the diffuse surface energy, %by the $L^1$-$L^\infty$ interpolation of $L^q$ and
    by \cref{eq:DiffToSharp_Young,eq:DiffToSharp_Gradient} we obtain that

    \begin{align*}
        \int_{\R^d} |\nabla U_\epsilon|^q dx & \leq \Vert \nabla U_\epsilon \Vert_{L^\infty}^{q-1} \Big( \Vert \nabla(U-\chi) \ast \psi_\epsilon \Vert_{L^1} + \Vert \nabla \chi \ast \psi_\epsilon \Vert_{L^1} \Big) \\ & \leq \epsilon^{1-q} \Vert \nabla \psi \Vert_{L^1}^{q-1} \Vert U \Vert_{L^\infty}^{q-1} \Big( \Vert DU - D\chi \Vert_{TV(\R^d)} + \Vert D\chi \Vert_{TV(\R^d)} \Big).
    \end{align*}

    As a consequence of the two inequalities above we obtain that
    \begin{align} \label{eq:DiffToSharp_NoBdry}
    \begin{split}
        \int_{\R^d} |U_\epsilon - \chi|^p + \epsilon^q |\nabla (U_\epsilon)|^q dx & \leq C(\Vert \chi \Vert_{L^\infty},p,q) \Big( \int_{\R^d} |U-\chi|^p dx + \epsilon \Vert D \chi \Vert_{TV(\R^d)} \\
        & \qquad  + \epsilon \Vert U \Vert_{L^\infty}^{q-1} \Vert D \chi \Vert_{TV(\R^d)} + \epsilon \Vert U \Vert_{L^\infty}^{q-1} \Vert DU - D \chi \Vert_{TV(\R^d)} \Big).
        \end{split}
    \end{align}


\emph{Step 2: Adjusting the boundary conditions.}

    Now we turn to the construction preserving the exterior data, i.e. we aim to construct $U_\epsilon \in L^p(\R^d;\R^n) \cap W^{1,q}(\R^d;\R^n)$ such that $U_\epsilon = 0$ outside $\Omega$.
    Let $U \in L^p(\R^d;\R^n) \cap BV(\R^d;\R^n)$ such that $U = 0$ outside $\Omega$ and $\chi \in L^\infty(\R^d;\R^n) \cap BV(\R^d;\R^n)$.

    By a translation we consider $\Omega' = (-1/2,1/2)^d$, $V := U(\cdot + 1/2(1,\dots,1)):\Omega'\to\R^n$, and $\chi' := \chi(\cdot + 1/2(1,\dots,1)):\Omega' \to \R^n$ in the following.
    We fix
    \begin{align*}
        \Omega'_\epsilon := (1-2\epsilon) \Omega' = (-\frac{1}{2}+\epsilon,\frac{1}{2}-\epsilon)^d \subset \Omega'.
    \end{align*}
    In particular, we have
    \begin{align*}
        \dist(\p\Omega',\p\Omega'_\epsilon) \geq \epsilon.
    \end{align*}


    We now choose $V_\epsilon = V^{(\epsilon)} \ast \psi_\epsilon$, where
    \begin{align*}
        V^{(\epsilon)}(y) = V(\frac{1}{1-2\epsilon}y), \ y \in \R^d.
    \end{align*}
    As $V = 0$ outside $\Omega'$, %and by the distance of the scaled boundary to $\p \Omega'$,
    we can infer $V_\epsilon = 0$ outside $\Omega'$.
    We now compare the energy for $V_\epsilon$ to that of $V \ast \psi_\epsilon$, which we can control with the arguments from step 1, as follows

    \begin{align*}
        \int_{\Omega'} |V_\epsilon - \chi'|^p + \epsilon^q |\nabla V_{\epsilon}|^q dy & \leq C(p,q) \Big( \int_{\Omega'} |V \ast \psi_{\epsilon} - \chi'|^p + \epsilon^q |\nabla (V \ast \psi_\epsilon)|^q dy \\
        & \quad + \Vert V_\epsilon - V \ast \psi_\epsilon \Vert_{L^p}^p + \epsilon^q \Vert \nabla V_\epsilon - \nabla (V \ast \psi_\epsilon) \Vert_{L^q}^q \Big).
    \end{align*}


    Hence, it remains to control
    \begin{align*}
        \Vert (V^{(\epsilon)} - V) \ast \psi_\epsilon \Vert_{L^p}^p + \epsilon^q \Vert \nabla (V^{(\epsilon)}-V) \ast \psi_\epsilon \Vert_{L^q}^q &\leq \Vert V^{(\epsilon)} - V \Vert_{L^p}^p + C \Vert V^{(\epsilon)} - V\Vert_{L^q}^q \\
        & \leq C \max\{\Vert U \Vert_{L^\infty}^{p-1}, \Vert U \Vert_{L^\infty}^{q-1}\} \Vert V^{(\epsilon)} - V \Vert_{L^1},
    \end{align*}
    where we invoked Young's convolution inequality and \cref{eq:DiffToSharp_Young}.
    Thus, using that $V, V^{(\epsilon)} = 0$ outside $\Omega'$ it holds
    \begin{align*}
        \int_{\R^d} |V^{(\epsilon)}(x) - V(x) | dx & \leq C \int_1^{\frac{1}{1-2\epsilon}} t^{-d} dt \, \Vert D V \Vert_{TV(\R^d)} \leq C (1- (1-2\epsilon)^{d}) \Vert D V \Vert_{TV(\R^d)} \\
        & \leq C(d) \epsilon \Vert D U \Vert_{TV(\R^d)},
    \end{align*}
    and, therefore, for $U_\epsilon(x) = V_\epsilon(x-1/2(1, \dots,1))$
    \begin{align*}
        \int_\Omega |U_\epsilon - \chi|^p + \epsilon^q |\nabla U_\epsilon|^q dx & \leq C(\Vert \chi \Vert_{L^\infty},p,q,d) \Big( \int_\Omega |U-\chi|^p dx \\
        & \quad + \epsilon (1+\max\{\Vert U \Vert_{L^\infty}^{p-1},\Vert U \Vert_{L^\infty}^{q-1}\}) \Vert D\chi \Vert_{TV(\Omega)}\\
        & \quad + \epsilon \max\{\Vert U \Vert_{L^\infty}^{p-1}, \Vert U \Vert_{L^\infty}^{q-1} \} (\Vert D U - D\chi \Vert_{TV(\R^d)} + \Per(\Omega))\Big).
    \end{align*}
    As $U_\epsilon$ is a combination of a rescaling and convolution of $U$, the differential constraint is preserved.
\end{proof}



For completeness, we also derive an estimate of the above type for the anisotropic setting.
\begin{cor} \label{cor:DiffToSharp_Aniso_Upper}
    Let $p,q \in [1,\infty)$, $\nu \in \S^{d-1}$, $\Omega = (0,1)^d$. For any $U, \chi \in L^p(\R^d;\R^n) \cap BV_\nu(\R^d;\R^n)$, with $U = 0$ outside $\Omega$ and $\epsilon > 0$ there exists $U_\epsilon \in L^p(\R^d;\R^n)$ such that $\p_\nu U_\epsilon \in L^q(\R^d;\R^n)$, $U_\epsilon = 0$ outside $\Omega$, and a constant $C = C(\Vert \chi \Vert_{L^\infty},p,q,d) > 0$ such that
    \begin{align*}
        \int_{\Omega} |U_\epsilon - \chi|^p + \epsilon^q |\p_\nu U_\epsilon|^q dx
        & \leq C \biggl( \int_{\Omega} |U-\chi|^p dx + \epsilon (1+\max\{\Vert U \Vert_{L^\infty}^{p-1},\Vert U \Vert_{L^\infty}^{q-1}\})\Vert D_\nu \chi \Vert_{TV(\Omega)} \\
        & \quad + \epsilon \max\{1,\Vert U \Vert_{L^\infty}^{p-1},\Vert U \Vert_{L^\infty}^{q-1}\}( \Vert D_\nu U - D_\nu \chi \Vert_{TV(\Omega)} +\Per(\Omega) \biggr)
    \end{align*}
    %As in \cref{lem:DiffToSharp_Mollified}
    Moreover, if we have $\operatorname{curl} U= 0$ or $\operatorname{curl} \operatorname{curl} U = 0$ in $\R^d$ it also holds $\operatorname{curl} U_{\epsilon} = 0$ or $\operatorname{curl} \operatorname{curl} U_\epsilon = 0$, respectively.
\end{cor}


\begin{proof}
    For given $U \in L^p(\R^d;\R^{n})$, we define $U_\epsilon(x) = \int_{\R} U(x-t\nu) \psi_\epsilon(t)dt$ with a one-dimensional mollifier $\psi_\epsilon$. That is, by $U_\epsilon$ we denote the function which is obtained by mollifying $U$ in direction $\nu$ on a scale $\epsilon$; we omit the $\nu$ dependence in the notation.
    Due to the fact that $(U_\epsilon)^\nu_y(t) = (U^\nu_y \ast \psi_\epsilon)(t)$, using the notation introduced in \cref{sec:prelim_directBV}, all the required estimates \cref{eq:DiffToSharp_Young,eq:DiffToSharp_Gradient,eq:DiffToSharp_ConvRate} have their respective analogous inequalities:
    \begin{align*}
        \Vert \p_\nu U_\epsilon \Vert_{L^r} &\leq \epsilon^{-1} \Vert \psi' \Vert_{L^1(\R)} \Vert U \Vert_{L^r}, \\
        \Vert \p_\nu U_\epsilon \Vert_{L^1} & \leq \Vert D_\nu U \Vert_{TV(\R^d)}, \\
        \Vert U_\epsilon - U \Vert_{L^1} & \leq C \epsilon \Vert D_\nu U \Vert_{TV(\R^d)}.
    \end{align*}
    Hence, the proof works as that of \cref{lem:DiffToSharp_Mollified}.  In particular, the changes required to not change the exterior data outside $\Omega$ are done by the same methods.

    As the function $U_\epsilon$ is essentially defined via a convolution and scaling, the differential constraint of the form $\operatorname{curl} U_\epsilon = 0$ or $\operatorname{curl curl} U_\epsilon = 0$ is still fulfilled in $\R^d$.
\end{proof}



\begin{rmk}
    We want to conclude this general analysis with two remarks.
    First, the same results as in \cref{sec:diffuse1,sec:diffuse2} hold if we consider periodic functions instead of prescribing the exterior data outside of $\Omega$.
    Second, we could also consider other differential constraints besides $\operatorname{curl} U = 0$ or $\operatorname{curl} \operatorname{curl} U = 0$ in $\R^d$.
    In general, in \cref{lem:DiffToSharp_Mollified,cor:DiffToSharp_Aniso_Upper} we can preserve the constraint $L(D) U = 0$ in $\R^d$ for any linear, homogeneous, constant coefficient differential operator $L(D)$, e.g. we could also consider $\di U = 0$ in $\R^d$.
    The role of the divergence operator for lower scaling bounds was discussed in \cite{RRT23}.
\end{rmk}


\subsection{Applications -- proof of \cref{cor:Lp_3wells}}
We now use the derived comparison results of the diffuse and sharp interface models to show \cref{cor:Lp_3wells}.
\begin{proof}[Proof of \cref{cor:Lp_3wells}]
Let us begin by recalling the upper bound constructions from \cref{sec:L1AnisotropicSurf} for \cref{thm:L1_3wells} for $U = \nabla u$. We recall that, as highlighted in \cref{eq:PropertiesBranching} and in the proofs of \cref{prop:L1_2wells,thm:L1_3wells}, we always have
\begin{align*}
    \Vert DU - D \chi \Vert_{TV(\Omega)} &\leq C(\K,F) (\Vert D \chi \Vert_{TV(\Omega)} + \Per(\Omega)), \\
    \Vert U \Vert_{L^\infty} &\leq C(\K,F).
\end{align*}
Thus, considering the functions $u_\epsilon,\chi_\epsilon$ defined in the respective upper bound, we use \cref{thm:comparison,cor:DiffToSharp_Aniso_Upper} (with $U = \nabla u_\epsilon$, $\chi = \chi_\epsilon$) to derive the scaling bounds.
Indeed, we obtain that
\begin{align*}
    & \quad c \inf_{\tilde{\chi}  \in BV_\nu(\Omega;\K_3)} \inf_{u \in \mathcal{A}_F}\left( \int_\Omega |\nabla u - \tilde{\chi}|^2 dx + \epsilon \Vert D_{\nu} \tilde\chi \Vert_{TV(\Omega)} \right) \\
    &\leq \inf_{\chi \in L^2(\Omega;\K_3)} \inf_{\substack{u \in \mathcal{A}_F \\ \p_\nu \nabla u \in L^{q}(\Omega;\R^{2 \times 2})}} \left( \int_\Omega |\nabla u - \chi|^2 + \epsilon^q |\p_\nu \nabla u|^q dx \right) \\
    & \leq C \left( \int_{\Omega} |\nabla u_\epsilon - \chi_\epsilon|^2 dx + \epsilon \Vert D_\nu \chi_{\epsilon} \Vert_{TV(\Omega)} + \epsilon \Per(\Omega) + \epsilon \Vert D_\nu\nabla u_{\epsilon} - D_\nu \chi_{\epsilon} \Vert_{TV(\Omega)} \right) \\
    & \leq C \left( \int_{\Omega} |\nabla u_{\epsilon} - \chi_{\epsilon}|^2 dx + \epsilon \Vert D_\nu \chi_{\epsilon} \Vert_{TV(\Omega)} + \epsilon \Per(\Omega) \right),
\end{align*}
where $C$ may depend on $\mathcal{K}$ and $F$.
In particular, after an absorption of the perimeter term, both the upper and lower bounds from \cref{cor:Lp_3wells} are proven by inserting the upper and lower bounds for the associated sharp interface models.
\end{proof}

\section{Discrete models and anisotropic surface energies}
\label{sec:discrete}
As a final prototypical example, we complement our discussion on possible regularizations by now considering the case of discrete models.
Indeed, discrete systems prevent oscillations at scales smaller than the grid size of the lattice.
As already known in the literature (see e.g.\ \cite{CM99,L09}), this produces a regularization effect comparable to the addition of a singular surface energy term in the continuous case. In our discussion, we recover these results in our model settings. Our main focus and novelty here, however, is on the analysis of anisotropic situations.
In this context, the orientation of the lattice naturally introduces an anisotropy which may affect the scaling depending on the geometry of $\K$.
This effect can be tracked into its continuous counterpart. In particular, this will allow us to invoke the scaling results from the previous sections.

\subsection{Quantitative surface penalization in discrete models}
In this section we consider discrete energies in the sense that, for $h \in (0,1)$ and $R \in SO(2)$, we fix a triangulation $\mathcal{T}_h^R$ of $\Omega$ on the scale $h$ and assume that $\nabla u$ and $\chi$ are constant on the triangles $\tau \in \mathcal{T}_h^R$.
By doing this we hence rule out -- and, in particular, ``penalize" -- oscillations on a scale finer than $h$.

For this reason, in certain instances, this discrete energy can be bounded from below by the continuous elastic energy contribution singularly perturbed by a sharp (anisotropic) surface penalization of the form given in \cref{eq:L1_energy}.

To observe this, we will make the energy contribution of three adjacent triangles explicit, and note that when a change of phase occurs, the ``middle" triangle $T_h'$ has to pay elastic energy, giving rise to a contribution which resembles the surface energy $\Vert D_\nu \chi \Vert_{TV(\Omega)}$.
We recall the notation for the lattice structures from \cref{eq:lattice}, \cref{eq:Triangulation}, the admissible deformations from \cref{eq:admissible_discrete} and the discrete energy from \cref{eq:energy_discrete}. We begin by deducing ``interior'' estimates. In the subsequent result, we will also incorporate associated boundary conditions.



In what follows, we focus on the anisotropic setting, more precisely, on the case in which we assume that there is a compatible direction of the wells which is perpendicular to one of the sides of the triangles. We allow for rank-one connections which are in exactly one of the directions $R e_1$, $R e_2$, or $R(e_1+e_2)$ for a fixed matrix $R\in SO(2)$. We note that this cannot yield a full surface penalization for the associated continuum model but will give rise to an anisotropic surface penalization.

\begin{lem}
\label{lem:DiscreteToSharp-aniso}
    Let $\K = \{A_1, A_2, \dots, A_N\} \subset \R^{2 \times 2}$. Let $T_h, T_h'$ denote the triangles from \cref{eq:lattice}. Assume that there exists $v \in \{e_1, e_2, 2^{-1/2}(e_1+e_2)\}$  such that for any $A_j, A_k \in \K $ with $j \neq k$ it holds
    \begin{align}
    \label{eq:assumption-wells-deg-lem}
        (Rw) \times [A_j - A_k] \neq 0, \quad \text{for every } w\in\{e_1,e_2,2^{-1/2}(e_1+e_2)\}\setminus\{v\}.
    \end{align}
    Let $p \in [1,\infty)$, $z \in h \Z^2$ and consider
    \begin{align}\label{eq:DefLargeTriangles}
        \Omega_j := %\Omega_j^z :=
        (RT_h \cup RT_h' \cup (RT_h+hRe_j)) + Rz,
    \end{align}
    for $j = 1,2$, illustrated in \cref{fig:UnionTriangles}.
    Then there is a constant $C = C(\K,R,p,v) > 0$ such that for any $u \in W^{1,p}(\Omega_1 \cup  \Omega_2;\R^2)$ and any $\chi \in L^\infty(\Omega_1 \cup \Omega_2;\K)$ which are affine or, respectively, constant on the triangles $R(T_h+z),R(T_h'+z),R(T_h+z+he_1),R(T_h+z+he_2)$,  it holds
    \begin{align*}
        \int_{\Omega_1 \cup \Omega_2} |\nabla u - \chi|^p dx \geq C h \Vert D_{R\nu} \chi \Vert_{TV(\Omega_1 \cup \Omega_2)},
    \end{align*}
    where $\nu \in \S^1$ is such that $\nu \cdot v = 0$.

    Moreover, defining
    \begin{align*}
    \Omega_j' := (RT_h \cup RT_h' \cup (RT_h'-hRe_j)) + Rz,
    \end{align*}
    for $j=1,2$, the same result holds with $\Omega_j'$ in place of $\Omega_j$.
\end{lem}


