\begin{proof}
    Without loss of generality, we can assume $z = 0$.
    We also start by considering $R=Id$; the general case will be reduced to this one below.
    We fix $x_0 \in T_h$ and $x_1 \in T_h'$ (see \cref{fig:triangulation}).
    For simplicity of exposition %and without loss of generality we assume that $v=2^{-1/2}(e_1+e_2)$,
    {we prove the estimate for $\Omega_1 \cup \Omega_2$ only,} with the estimate on $\Omega_1' \cup \Omega_2'$ being completely analogous.


\emph{Step 1: The case of $R= \operatorname{Id}$.}
    We first quantify the energy contribution of a possible change of phase in $\Omega_j$.
    Its main contribution concentrates on $T_h'$ and amounts to
    \begin{align}\label{eq:trinagle1}
    \begin{split}
        \int_{T_h'} |\nabla u - \chi|^p dx &\geq c h^2 \big| e_j \times (\chi(x_0+he_j) - \chi(x_1)) \big| - 2^{p} \int_{T_h \cup (T_h + h e_j)} |\nabla u - \chi|^p dx,
    \end{split}
    \end{align}
    for some $c=c(\K,p)>0$.
    To prove \cref{eq:trinagle1}, we first work on $\Omega_1$, i.e. with $j=1$. The estimate for $\Omega_2$ follows by switching the roles of the coordinates.
    Since $u$ is affine on each triangle in $\Omega_1\cup \Omega_2$, by tangential continuity along the edges of $T_{h}'$ it holds that
    \begin{align*}
        \p_1 u (x_1)= \p_1 u (x_0+h e_2), \ \p_2 u (x_1)= \p_2 u (x_0+h e_1), \ \p_1 u (x_1)- \p_2 u (x_1) = \p_1 u (x_0)- \p_2 u (x_0),
    \end{align*}
    and, hence,
    \begin{align}\label{eq:triangle2}
    \begin{split}
        \p_1 u (x_1) & =  \p_2 u(x_0+he_1) + \p_1 u(x_0) - \p_2 u(x_0) = \p_1 u(x_0+h e_2), \\
        \p_2 u (x_1) &= \p_2 u(x_0+he_1) = \p_1 u(x_0+he_2) + \p_2 u(x_0) - \p_1u(x_0).
    \end{split}
    \end{align}
    By exploiting the fact that $A^\frac{p}{2}+B^\frac{p}{2}\le\sqrt{2}(A+B)^\frac{p}{2}$ for $A,B\ge0$, relation \cref{eq:triangle2},
    by Jensen's inequality (in the form $|A-B|^p-2^{p-1}|B|^p\leq 2^{p-1}|A|^p$), and
    writing $\chi_j = \chi e_j$ for the $j$th column of $\chi$, we obtain
    \begin{align*}
        &\int_{T_h'} |\nabla u - \chi|^p dx \\
        & \quad = \frac{h^2}{2} \left( | \p_2 u(x_0+he_1) + \p_1u(x_0) - \p_2 u(x_0) - \chi_1(x_1)|^2 + |\p_2 u(x_0+he_1)-\chi_2(x_1)|^2 \right)^{\frac{p}{2}} \\
        & \quad \geq \frac{h^2}{2} \frac{1}{2^p\sqrt{2}} \left( |\p_1 u(x_0) - \p_2 u(x_0) - (\chi_1(x_1) - \chi_2(x_1)) |^p + |\p_2 u(x_0+he_1) - \chi_2(x_1)|^p \right)\\
        & \quad \geq \frac{h^2}{2} \frac{1}{2^p\sqrt{2}} \Big( 2^{1-p} |\chi_1(x_0) - \chi_1(x_1) - (\chi_2(x_0) - \chi_2(x_1))|^p +2^{1-p} |\chi_2(x_0+he_1) - \chi_2(x_1)|^p \\
        & \qquad - |\p_1 u(x_0) - \p_2 u(x_0) - (\chi_1(x_0) - \chi_2(x_0))|^p  - |\p_2 u(x_0+h e_1) - \chi_2(x_0+he_1)|^p \Big).
    \end{align*}
    Let $C_0 = \min\big\{|w \times(A_j-A_k)| : j\neq k, w\in\{e_1,e_2,2^{-1/2}\begin{psmallmatrix}1\\1\end{psmallmatrix}\} \setminus \{v\}\big\} > 0$ which is strictly positive thanks to \cref{eq:assumption-wells-deg-lem}.
    For simplicity of exposition, in the next two estimates we assume $v=2^{-1/2}(e_1+e_2)$. Hence, we deduce
    \begin{align*}
       & \int_{T_h'} |\nabla u - \chi|^p dx \\
       &\quad\geq 2^{-2p-1} h^2 \Big( | \begin{psmallmatrix} 1 \\ 1 \end{psmallmatrix} \times (\chi(x_0) - \chi(x_1))|^p + |e_1 \times (\chi(x_0+he_1) - \chi(x_1))|^p \Big) \\
        & \qquad - \frac{h^2}{2} \Big( |\p_1 u(x_0) - \p_2 u(x_0) - (\chi_1(x_0) - \chi_2(x_0))|^p  + |\p_2 u(x_0+h e_1) - \chi_2(x_0+he_1)|^p \Big) \\
        & \quad\geq 2^{-2p-1} h^2 \Big( | \begin{psmallmatrix} 1 \\ 1 \end{psmallmatrix} \times (\chi(x_0) - \chi(x_1))|^p + |e_1 \times (\chi(x_0+he_1) - \chi(x_1))|^p \Big) \\
        & \qquad - \frac{h^2}{2} \Big( 2^p|\nabla u(x_0) - \chi(x_0)|^p  + |\nabla u(x_0+h e_1) - \chi(x_0+he_1)|^p \Big) \\
        & \quad\geq 2^{-2p-1} C_0^{p-1} h^2  |e_1 \times (\chi(x_0+he_1)-\chi(x_1))| - 2^{p} \int_{T_h \cup T_h+he_1} |\nabla u - \chi|^p dx.
    \end{align*}
    Here, we used $\begin{psmallmatrix} 1 \\ 1 \end{psmallmatrix} \times \nabla u= \begin{psmallmatrix} -1 \\ 1 \end{psmallmatrix} \cdot \nabla u= \p_2 u - \p_1 u$ to denote the tangential components for the edges with normal $\begin{psmallmatrix} 1 \\ 1 \end{psmallmatrix}$, see the notation introduced in \cref{sec:intro_Tartar}.
    This proves \cref{eq:trinagle1} with $c =2^{-2p-1} C_0^{p-1} > 0$ depending only on $\K$, $v$, and $p$.


    We now combine \cref{eq:trinagle1} with the analogous inequality with $e_1$ and $e_2$ switched.
    We thus have
    \begin{align*}
    & \quad \int_{\Omega_1 \cup \Omega_2} |\nabla u - \chi|^p dx \\
    &  \geq \int_{T_h \cup ( T_h + h e_1) \cup (T_h + h e_2) } |\nabla u - \chi|^p dx + 2^{-p-1}\int_{T_h'} |\nabla u - \chi|^p dx + 2^{-p-1}\int_{T_h'} |\nabla u - \chi|^p dx\\
    &  \geq c h^2 2^{-p-1} \sum_{j=1}^2 \Big|e_j \times [\chi(x_0+he_j)-\chi(x_1)]\Big| \\
    & \quad + (1-2^{-1}-2^{-1}) \int_{T_h} |\nabla u - \chi|^{p} dx + (1-2^{-1}) \int_{(T_h + h e_1) \cup (T_h + h e_2)} |\nabla u - \chi|^{p} dx \\
    & \geq c 2^{-p-1} h^2 \sum_{j=1}^2 \Big| e_j \times [\chi(x_0+he_j) - \chi(x_1)] \Big|.
    \end{align*}

    For general $v \in \{e_1, e_2, 2^{-1/2}(e_1+e_2)\}$ we follow the same arguments as above and get
    \begin{align}\label{eq:lb-bigt}
    \begin{split}
        \int_{\Omega_1 \cup \Omega_2} |\nabla u - \chi|^p dx &\geq c 2^{-p-1} h^2 \Big( \sum_{j=1}^2 \Big| e_j \times [\chi(x_0+he_{j})- \chi(x_1)] \Big| + \Big| \begin{pmatrix}
           1/\sqrt{2} \\ 1/\sqrt{2}
        \end{pmatrix} \times [\chi(x_0) - \chi(x_1)] \Big| \\
        & \quad - \Big| v \times [\chi(x_v)-\chi(x_1)] \Big| \Big),
        \end{split}
    \end{align}
    where $x_v=x_0$ if $v=2^{-1/2}(e_1+e_2)$, $x_v=x_0+he_j$ if $v=e_j$ %$x_v \in \{x_0,x_0+he_1, x_0+he_2\}$ is the corresponding point for $v$
    , such that exactly the term with $v$ cancels.

    To relate this expression to the desired surface energy, we note that for $\nu \in \S^1$ such that $\nu \cdot v = 0$, it follows that
    \begin{align*}
        \Vert D_\nu \chi \Vert_{TV(\Omega_1 \cup \Omega_2)} & = h | \nu \cdot 2^{-1/2}(e_1 + e_2)| \ |\chi(x_0) - \chi(x_1)| + \sum_{j=1}^2 h |\nu \cdot e_j| \ |\chi(x_1)-\chi(x_0+he_j)| \\
        & \leq C h \Big( |\chi(x_0)-\chi(x_1)| + \sum_{j=1}^2 |\chi(x_1)-\chi(x_0+he_j)| - |\chi(x_1) - \chi(x_v)|\Big).
    \end{align*}
    From \cref{eq:lb-bigt}, exploiting the boundedness of $\chi$, we can also infer that
    \begin{align*}
        \int_{\Omega_1 \cup \Omega_2} |\nabla u - \chi|^p dx & \geq c 2^{-p-1} \frac{h^2}{\diam(\K)} \Big( \Big| \begin{pmatrix} 1/\sqrt{2} \\ 1/\sqrt{2} \end{pmatrix} \times [\chi(x_0) - \chi(x_1)] \Big| |\chi(x_0)- \chi(x_1)|  \\
        & \quad  + \sum_{j=1}^2 \Big| e_j \times [\chi(x_0+he_j) - \chi(x_1)] \Big| |\chi(x_0+he_j) -\chi(x_1)| \\
        & \quad - \Big| v \times [\chi(x_1) - \chi(x_v)] \Big| |\chi(x_1) - \chi(x_v)| \Big).
    \end{align*}
    Hence, gathering the two inequalities above and again by \cref{eq:assumption-wells-deg-lem}
    for a constant $C = C(\K,p,v) > 0$ we get
    \begin{align*}
        \int_{\Omega_1 \cup \Omega_2} |\nabla u - \chi|^p dx &\geq C h \left( h|\chi(x_0)-\chi(x_1)| + \sum_{j=1}^2 h |\chi(x_0+he_j)-\chi(x_1)| - h |\chi(x_1)-\chi(x_v)|\right) \\
        & \geq C h \Vert D_\nu \chi \Vert_{TV(\Omega_1 \cup \Omega_2)}.
    \end{align*}

Step 2: General rotations $R \in SO(2)$.
    Now we turn to the general (rotated) case.
    For given $R \in SO(2)$, consider $\tilde{\Omega}_j = R^T \Omega_j = (T_h \cup T_h' \cup (T_h + h e_j)) + z$ and the functions
    \begin{align*}
        \tilde{u}&: \tilde{\Omega}_1 \cup \tilde{\Omega}_2 \to \R^2, & \tilde{u}(x) &= u(Rx), \\
        \tilde{\chi}&: \tilde{\Omega}_1 \cup \tilde{\Omega}_2 \to \K R, & \tilde{\chi}(x) &= \chi(Rx) R.
    \end{align*}
    For those functions it holds that $\nabla \tilde{u}(x) = \nabla u (Rx) R$, and thus
    \begin{align*}
        \int_{\Omega_1 \cup \Omega_2} |\nabla u - \chi|^p dx &= \int_{R^T(\Omega_1 \cup \Omega_2)} |\nabla u (Rx) - \chi(Rx)|^p dx = \int_{\tilde{\Omega}_1 \cup \tilde{\Omega}_2} |\nabla \tilde{u} - \tilde{\chi}|^p dx, \\
        \Vert D_{R \nu} \chi \Vert_{TV(\Omega_1 \cup \Omega_2)} & = \Vert D_\nu \tilde{\chi} \Vert_{TV(\tilde{\Omega}_1 \cup \tilde{\Omega}_2)}.
    \end{align*}
    For the wells $A_j,A_k \in \K$, $j \neq k$, from \cref{eq:assumption-wells-deg-lem} it holds
    \begin{align*}
        e_j \times (A_j R - A_k R) = (Re_j) \times (A_j-A_k), \ \begin{pmatrix} 1 \\ 1 \end{pmatrix} \times (A_j R - A_k R) = (R \begin{pmatrix} 1 \\ 1 \end{pmatrix}) \times (A_j - A_k).
    \end{align*}
    Therefore the set $\tilde{\K} = \K R$ fulfils the compatibility conditions \cref{eq:assumption-wells-deg-lem} for $R = \operatorname{Id}$.
    Hence, the claim follows by applying the argument for $R = \operatorname{Id}$ to the functions $\tilde{u}$, $\tilde{\chi}$, and thus
    \begin{align*}
        \int_{\Omega_1 \cup \Omega_2} |\nabla u - \chi|^p dx &= \int_{\tilde{\Omega}_1 \cup \tilde{\Omega}_2} |\nabla \tilde{u} - \tilde{\chi}|^p dx \geq C(\tilde{\K},p,v) h \Vert D_\nu \tilde{\chi} \Vert_{TV(\tilde{\Omega}_1 \cup \tilde{\Omega}_2)} \\
        & = C(\K,R,p,v) h \Vert D_{R \nu} \chi \Vert_{TV(\Omega_1 \cup \Omega_2)}.
    \end{align*}
\end{proof}


With the above auxiliary result on ``interior estimates'' in hand, we now cover $\Omega$ with copies of $\Omega_1 \cup \Omega_2$ to relate the discretized setting to a sharp interface model. This, together with an estimate of the energy contributions which arise at the boundary allows us to provide the proof of \cref{cor:DiscreteToSharp}.

\begin{proof}[Proof of \cref{cor:DiscreteToSharp} in the anisotropic setting]
    Only the proof for the anisotropic setting is given, for the full isotropic surface penalization the arguments are analogous with the corresponding changes for the full derivative.
    By possibly replacing $\Omega$ by $R^T \Omega$, in the following we assume $R = \operatorname{Id}$.
    The general result follows by a rotation as done in the proof of \cref{lem:DiscreteToSharp-aniso}.
    Without loss of generality and for brevity of exposition, we assume that $v=2^{-\frac{1}{2}}(1,1)^T$ and thus $\nu = 2^{-\frac{1}{2}}(-1,1)^T$.
    We work in multiple steps, separating the analysis in the interior of the domain and close to the boundary.

    \emph{Step 1: Estimate on the interior.}
    We cover $\Omega$ by sets of the form $\Omega_1^z \cup \Omega_2^z$ as in \cref{eq:DefLargeTriangles}, i.e.
    \begin{align*}
        \Omega_1^z \cup \Omega_2^z = (T_h \cup T_h' \cup (T_h+h  e_1) \cup (T_h + e_2)) + z,
    \end{align*}
    where we now keep track of the dependence on $z \in h \Z^2$ in the notation.
    We define the discrete set $\mathcal{J}:=\{z\in h \Z^2 : (\Omega_{1}^z \cup
    \Omega_2^z) \subset \Omega\}$ and the set $\Omega_h := \cup_{z \in
      \mathcal{J}} \Omega_1^z \cup \Omega_2^z$.
    The interior set $\Omega_h\subset \Omega$ approximates $\Omega$ from the inside as $h\downarrow 0$ and may leave an $h$-neighbourhood of the boundary $\p \Omega$ not yet covered, which will be addressed in Step 2.

    As $\Omega_1^z \cup \Omega_2^z$ overlap at most six times for $z\in\mathcal{J}$, by an application of \cref{lem:DiscreteToSharp-aniso} we obtain the lower bound
    \begin{align} \label{eq:DiscreteToSharp_inner}
    \begin{split}
        \int_{\Omega} |\nabla u - \chi|^p dx & \geq \frac{1}{6} \sum_{z \in\mathcal{J}} \int_{(\Omega_1^z \cup \Omega_2^z) \cap \Omega} |\nabla u - \chi|^p dx \\
        & \geq \sum_{z \in \mathcal{J}} C' h \Vert D_{\nu} \chi \Vert_{TV(\Omega_1^z \cup \Omega_2^z)} \geq C' h \Vert D_{ \nu} \chi \Vert_{TV(\Omega_h)},
        \end{split}
    \end{align}
    with $C'>0$ depending on $\K$, $v$, and $p$.

    \emph{Step 2: Boundary layer.}
    To estimate the energy contribution of the boundary layer, we introduce the set of boundary triangles
    \begin{align*}
        \mathcal{I} := \{ \tau \in \mathcal{T}_h:
        |\tau \cap \Omega| > 0,  \
        \mathcal{H}^1(\overline{\tau} \cap \p \Omega) > 0\}.
    \end{align*}

    For a constant $\sigma=\sigma(\Omega) \in (0,\frac{1}{2})$ which will be fixed below, we decompose the set of boundary triangles into $\mathcal{I} = \mathcal{I}_{\textup{small}} \cup \mathcal{I}_1 \cup \mathcal{I}_2$, where
    \begin{align*}
        \mathcal{I}_{\textup{small}} &:= \{\tau \in \mathcal{I}: |\tau \cap \Omega| < \frac{1}{2}\sigma h^2\},\\
        \mathcal{I}_1 &:= \{ \tau \in \mathcal{I}\setminus \mathcal{I}_{\textup{small}}:  |\tau \setminus \Omega| > 0\}, \\
         \mathcal{I}_2  &:= \{ \tau \in \mathcal{I} \setminus \mathcal{I}_{\textup{small}}: |\tau \setminus \Omega| = 0\}.
    \end{align*}
    The triangles in $\mathcal{I}_1$ and $\mathcal{I}_2$ have non-degenerate area inside $\Omega$
    and, in particular, those in $\mathcal{I}_2$ have at least one edge that has a common line segment with $\p \Omega$.

    We will show that the energy on this boundary layer produces a contribution of order (at least) $h$.
    To prove this, the case in which the edges of $\Omega$ are aligned with the grid necessitates a careful treatment, since (a priori) in this case $u\in\mathcal{A}^{p,\Id}_{h,F}$ could laminate with the boundary condition without paying any energy.
    We thus split this analysis into two substeps, depending on the geometry of the domain.

    \emph{Step 2.1: Domains aligned with the grid.}
    Consider first the case in which $\Omega$ is a polygon with edges parallel to the directions of the triangulation, i.e.\ such that $n_{\p\Omega}\in\{\pm e_1,\pm e_2, \pm v\}$ $\mathcal{H}^1$-a.e.\ on $\p\Omega$, where $n_{\p\Omega}$ is the outer unit normal vector to $\p\Omega$.
    Notice that there exist $h_0=h_0(\Omega)>0$ and $C_0>0$ a universal constant such that, for every edge $\Gamma$ of $\Omega$ and for every $h<h_0$ it holds
    \begin{equation}\label{eq:C0}
    \#\{\tau\in\mathcal{I} : \bar{\tau}\cap\Gamma\neq\emptyset\} \ge \frac{C_0}{h}\mathcal{H}^1(\Gamma).
    \end{equation}
    We now split our discussion in two cases.

