    \textbf{Case 1:} Assume that there exists an edge $\Gamma$ of $\Omega$ whose distance (towards the interior of $\Omega$, i.e.\ oriented in direction $-n_\Gamma$) from the lattice lines orthogonal to $n_\Gamma$ is larger than $\sigma h$, see \cref{fig:discrete_case1}.
    In formulas, we assumed that $d_h(\Gamma)\ge\sigma h$, where
    \begin{equation*}\label{eq:distance-latt}
    d_h(\Gamma):=\min\{t\ge0 : \Gamma-t n_\Gamma\subset\mathbb{L}_h(n_\Gamma)\}, \quad
    \mathbb{L}_h(n_\Gamma):=\begin{cases}
    h\Z\times\R & n_\Gamma=\pm e_1,\\
    \R\times h\Z & n_\Gamma=\pm e_2,\\
    \{(t,z-t):t\in\R,z\in h\Z\} & n_\Gamma=\pm v.
    \end{cases}
    \end{equation*}
    In this case
    \begin{align*}
    \#\{\tau\in\mathcal{I}_1 : \bar{\tau}\cap\Gamma\neq\emptyset\} \ge \frac{1}{2}\#\{\tau\in\mathcal{I} : \bar{\tau}\cap\Gamma\neq\emptyset\}.
    \end{align*}
    Since $u\in\mathcal{A}^{p,\Id}_{h,F}$ and $\nabla u\equiv F$ outside $\Omega$, for every $\tau\in\mathcal{I}_1$ we have that $u(x) = Fx$ on $\tau$ and hence, using $F \notin \K$,
    \begin{align*}
    \int_{\tau\cap\Omega}|\nabla u-\chi|^p dx = \int_{\tau \cap \Omega} |F- \chi|^p dx \geq \sigma C' h^2.
    \end{align*}
    Consequently, by \cref{eq:C0} and the estimates above, we get
    \begin{equation}\label{eq:step3}
        \int_{\Omega} |\nabla u - \chi|^p dx \geq \sum_{\tau \in \mathcal{I}_1} \int_{\tau \cap \Omega} |\nabla u - \chi|^p dx \geq \sum_{\tau \in \mathcal{I}_1} \sigma C' h^2 \geq \frac{1}{2}C' C_0 \sigma h \mathcal{H}^1(\Gamma).
    \end{equation}

    \textbf{Case 2:} If case 1 does not take place, the edges of $\Omega$ have distance (towards the interior) from the lattice lines (parallel to that edge) smaller than $\sigma h$, i.e.\ $d_h(\Gamma)<\sigma h$.
    If there is one edge $\Gamma$ for which this distance is not zero, we define $\Omega'\subset\Omega$ as the polygon obtained by replacing $\Gamma$ with the closest lattice line orthogonal to $n_\Gamma$.
    Notice that, $u(x) = Fx$ also outside of $\Omega'$.
    Up to repeating this procedure a finite number of times, we obtain that all the edges of $\Omega'$ lie on lattice lines, depicted in \cref{fig:discrete_case2}.
    With a slight abuse of notation, we still denote $\Omega'$ as $\Omega$, in particular we have that $\mathcal{I}=\mathcal{I}_2$.

    In this case, due to the anisotropy, there might be an energy-free phase transition between $F$ and $\K$ on the boundary triangles.
    We separate the cases in which this phase transition does not happen (case 2(a)) with the one in which the transition takes place, case 2(b).
    In case 2(b) we need global arguments to prove that the lower bound is non-degenerate.

    For $w \in \{-e_1,-e_2,v\}$ we introduce the set
    \begin{align*}
        \mathcal{I}_2^w := \{ \tau \in \mathcal{I}_2: E_w(\tau) \subset \p \Omega\},
    \end{align*}
    where by $E_w(\tau)$ we denote the edge of $\tau$ with normal $w$.
    These are the sets of lattice triangle touching the edges of $\Omega$ that are orthogonal to $w$.


    \textbf{Case 2(a):}
    First let us assume that there is one edge $\Gamma$ of $\Omega$ with normal $w \in \{-e_1,-e_2,v\}$ such that in the majority of triangles at this edge $\chi$ is in an incompatible well to the boundary condition $F$, i.e.
    \begin{align*}
        \# \{\tau \in \mathcal{I}_2^w: \overline{\tau} \cap \Gamma \neq \emptyset, w \times[\chi - F] \neq 0 \text{ on } \tau\} \geq \frac{C_0}{2h} \mathcal{H}^1(\Gamma).
    \end{align*}
    For any such triangle $\tau$ it then holds
    \begin{align*}
        \int_{\tau \cap \Omega} |\nabla u - \chi|^p dx \geq \int_\tau |w \times (F-\chi)|^p dx \geq C' h^2.
    \end{align*}
    Here we have used that, as there is a line segment in $\p \tau \cap \Gamma$ perpendicular to $w$, by the boundary condition and the fact that $\nabla u$ is constant on $\tau$, we have
    \begin{align*}
        w \times \nabla u = w \times F.
    \end{align*}
    This yields that
    \begin{align} \label{eq:step2a}
        \int_\Omega |\nabla u- \chi|^p dx \geq \frac{1}{2}C' C_0 h \mathcal{H}^1(\Gamma).
    \end{align}
    This case can either happen, if all the wells are incompatible to $F$ in direction $w$, or if $\chi$ is ``badly'' chosen.


    \textbf{Case 2(b):} We are then left to consider the case in which for every edge of $\Omega$ (orthogonal to $w$) there exists (at least) one $A_w$ compatible to $F$ in direction $w$, i.e. $w \times (A_w-F) = 0$, and such that $\chi=A_w$ in the majority of the boundary triangles.
    Hence, there exist at least two (different) vectors $w_1,w_2\in\{-e_1,-e_2,v\}$, two edges $\Gamma_1,\Gamma_2\subset\p\Omega$ (orthogonal to $w_1$ and $w_2$ respectively) and two matrices (up to relabelling) $A_1,A_2\in\K$ such that $w_1\times(F-A_1)=0$, $w_2\times(F-A_2)=0$ and
    \begin{align*}
    &\#\{\tau \in \mathcal{I}_{2}^{w_1} : \bar\tau\cap\Gamma_1\neq\emptyset, \chi=A_{1} \text{ on } \tau\} \ge \frac{C_0}{2hN}\mathcal{H}^1(\Gamma_1), \\
    &\#\{\tau \in \mathcal{I}_{2}^{w_2} : \bar\tau\cap\Gamma_2\neq\emptyset, \chi=A_{2} \text{ on } \tau\} \ge \frac{C_0}{2hN}\mathcal{H}^1(\Gamma_2).
    \end{align*}
    From the fact that $F\notin\K$ we also infer that $A_1\neq A_2$. The factor $\frac{1}{N}$ here accounts for the fact that there might be multiple possible choices of $A_1, A_2$.

    As the edges of $\Omega$ lie on the lattice lines, we can cover the whole $\Omega$ by copies of $\Omega_1^z \cup \Omega_2^z$ and its flipped version $(\Omega_1')^z \cup (\Omega_2')^z$.
    Hence, by reasoning as in \cref{eq:DiscreteToSharp_inner} of Step 1, we have
    \begin{align*}
        \int_\Omega |\nabla u - \chi|^p dx \geq C' h \Vert D_{\nu} \chi \Vert_{TV(\Omega)}.
    \end{align*}
    We now prove that, either there exists a non-degenerate interface oriented in a direction not orthogonal to $v$ or we have a non-vanishing elastic energy contribution in the bulk.

    As $w_1 \neq w_2$, we can assume, without loss of generality, that $w_2=-e_2$.
    Let
    \begin{align*}
        E:=\bigcup_{\tau\in \mathcal{T}_{h} :\ \chi\equiv A_2 \text{ on } \tau} \tau
    \end{align*}
    and let $E'$ be a connected component of $E$ whose closure intersects $\Gamma_2$ and let $\ell:=\mathcal{H}^1(\p E'\cap\Gamma_2)$.
    For simplicity, assume also
    $\p E'\cap\Gamma_2=(0,\ell)\times\{0\}$.

    Denote $\gamma=\p E'\setminus\Gamma_2$, which is a connected piecewise affine path.
    We decompose it into the part inside $\Omega$ and the part on its boundary, that is, we write $\gamma=\gamma_{\rm in}\cup\gamma_{\rm b}:=(\gamma\setminus\p\Omega)\cup(\gamma\cap\p\Omega)$.
    Consider the stripe
    \begin{align*}
    S:=\Big\{(x_1,x_2)\in\Omega : x_2>0, \frac{\ell}{4}<x_1+x_2<\frac{3\ell}{4}\Big\},
    \end{align*}
    and let $f(x_1)$ be the length of the segment in direction $\nu$ originating
    from $(x_1,0)$ and ending on $\p\Omega$ (but not necessarily in $E'$).
    Here, we recall that $v = 2^{-1/2} (1, 1)^T$ and $\nu \cdot v = 0$.
    Notice that, as $\Omega$ is a polygonal domain and $S\cap\Gamma_2$
        is well-contained in $\Gamma_2$, $f(x_1)$ is bounded from below, hence up to reducing the
    value of $\sigma$, $\sigma< f(x_1)< \diam(\Omega)$ for every
    $x_1\in(\ell/4,3\ell/4)$.
    By connectedness of $\gamma$, we notice that
    \begin{align*}
    \int_{\gamma\cap \bar S}|\nu\cdot n_{\p E'}|d\mathcal{H}^1=\int_{\gamma_{\rm in}\cap S}|\nu\cdot n_{\p E'}|d\mathcal{H}^1+\int_{\gamma_{\rm b}\cap \bar S}|\nu\cdot n_{\p E'}|d\mathcal{H}^1\ge\frac{\ell}{2 \sqrt{2}}.
    \end{align*}
    Indeed, as $E'$ is connected $\gamma$ is a continuous path from $(0,0)$ to $(\ell,0)$ hence intersects $\p S$ both in $\{(\ell/4,0) + t \nu: t \in \R\}$ and $\{(3\ell/4,0) + t \nu: t \in \R\}$.
    By the choice of $S$, that is, $\p S \cap \Omega$ has normal $v$, and the
    fact that the segment $\gamma$ of $\p E'$ consists of line segments
    with possible directions $e_1,e_2,$ and $\nu$, $\gamma\cap S$ has to
    move a distance larger than $\ell/2$ in the directions $e_1$
    or $e_2$.

