    Since we have a control only of the interfaces inside $\Omega$, if
    \begin{align*}
    \int_{\gamma_{\rm in}\cap S}|\nu\cdot n_{\p E'}|d\mathcal{H}^1\ge\frac{\ell}{4 \sqrt{2}}
    \end{align*}
    then we infer that
    \begin{equation}\label{eq:anis-lb-h}
        \|D_{\nu}\chi\|_{TV(\Omega)}\geq C \int_{\gamma_{\rm in} \cap S} |\nu \cdot n_{\p E'}| d \mathcal{H}^2 \geq C_1\ell,
    \end{equation}
    with $C_1>0$ depending on $\K$.

    Consider now the opposite case, i.e.\ that
    \begin{align*}
    \int_{\gamma_{\rm in}\cap S}|\nu\cdot n_{\p E'}|d\mathcal{H}^1\le\frac{\ell}{4 \sqrt{2}} \leq \frac{\ell}{4}.
    \end{align*}
    In this case, loosely speaking, we can prove that there is a union of stripes (contained in $S$ and oriented in its same direction) fully contained in $E'$, in which we can perform an integration argument which provides a lower bound (see below).
    To be precise, let $I:=\{x_1\in(\ell/4,3\ell/4):((x_1,0)+\R\nu)\cap\gamma_{\rm in} = \emptyset\}$ be the set of starting points on $\p S \cap \Gamma_2$ such that the ray in direction $\nu$ does not intersect $\gamma_{\rm in}$.
    Then, with a slicing argument
    \begin{align*}
        \frac{\ell}{4} &\ge \int_{\gamma_{\rm in}\cap S}|\nu \cdot n_{\p E'}|d\mathcal{H}^1 \\
        &= \int_\frac{\ell}{4}^\frac{3\ell}{4}\mathcal{H}^0(\{x_2\in(0,f(x_1)):(x_1-x_2,x_2)\in\gamma_{\rm in}, n_{\p E'}(x_1-x_2,x_2)\neq\nu\})dx_1 \ge \frac{\ell}{2}-|I|.
    \end{align*}
    Hence, after a suitable change of variables and an application of Jensen's inequality and the fundamental theorem of calculus, we get
    \begin{align*}
    \int_{E'}|\nabla u-\chi|^pdx & \ge \int_{I}\int_0^{f(x_1)}|\p_{\nu} \tilde{u}(x_1-x_2,x_2)-A_2 \nu|^p dx_2 dx_1 \\
    &\ge \sigma\int_{I}\Big|\frac{1}{f(x_1)}\int_0^{f(x_1)}(\p_{\nu} u(x_1-x_2,x_2)-A_2 \nu) dx_2\Big|^p dx_1 \\
    &= \sigma\int_{I}\Big|\frac{u(x_1-f(x_1),f(x_1))-u(x_1,0)}{\sqrt{2}\ f(x_1)}-A_2\nu\Big|^p dx_1.
    \end{align*}
    Since, by the boundary conditions, $u(x_1-f(x_1),f(x_1))=F(x_1-f(x_1),f(x_1))^T$, $u(x_1,0)=F(x_1,0)^T$, and $F-A_2=a\otimes e_2$ for some $a\in\R^2\setminus\{0\}$ we infer that
    \begin{equation}\label{eq:anis-lb-h2}
    \int_{E'}|\nabla u-\chi|^pdx \ge \sigma\frac{\ell}{4} |(a\otimes e_2) \nu|^p\ge \sigma C_1\ell,
    \end{equation}
    up to reducing the value of $C_1$ if needed.
    Gathering \cref{eq:anis-lb-h,eq:anis-lb-h2} and repeating it for all the connected components of $E$ we infer that also in this case
    \begin{equation}\label{eq:step3c}
    \int_\Omega|\nabla u-\chi|^pdx \ge C_1\min\{h,\sigma\}\frac{C_0}{2}\mathcal{H}^1(\Gamma_2).
    \end{equation}

    \emph{Step 2.2: Domains not aligned with the grid.}
