\frac{dE_i}{dt} &=& \sum_{j=1}^{v} \beta_j m_{ij}S_i \frac{\sum_{k=1}^{u}p_{kj}I_k}{\sum_{k=1}^{u}(m_{kj}S_k+n_{kj}E_k+p_{kj}I_k+q_{kj}R_k)}-\upsilon_i E_I-\mu_i E_i\label{eq:Ei_Pa} \\
