\section{Introduction}
In  \cite{Young}, Young  formulates the equilibrium condition for the contact angle of a capillarity surface commonly known as Young’s law. We know that Euclidean capillary convex bodies in the upper half-space characterize the equilibrium states of liquid droplets contacting a hyperplane, while anisotropic capillary convex bodies may describe stable configurations of droplets with non-uniform density adhering to the hyperplane.
For comprehensive treatments of isotropic or anisotropic capillarity, we refer to \cite{Finn,Philippis}.




We consider the properly, embedded, smooth compact  hypersurface $\Sigma$ in the closure $\overline{\mathbb{R}^{n+1}_+}$ of half-space ${\mathbb{R}_+^{n+1}}=\{x\in \mathbb{R}^{n+1} :\<x,E_{n+1}\>> 0 \}$ with $\mathrm{int}(\Sigma)\subset \mathbb{R}_+^{n+1}$ and $\partial\Sigma\subset\partial\overline{\mathbb{R}_+^{n+1}}$, where $E_{n+1}$ denotes the $(n+1)$-coordinate unit vector. $\Sigma$
 is called a $\theta$-capillary hypersurface if $\Sigma$ intersects $\partial\overline{\mathbb{R}^{n+1}_+}$ at a constant contact angle $\theta \in (0,\pi)$. If $\Sigma$ is an anisotropic capillary hypersurface (as defined in \cite{Jia-Wang-Xia-Zhang2023} or below), the contact angle on the boundary is typically non-constant.

 To describe the anisotropic capillary hypersurface, we let $\mathcal{W}\subset \mathbb{R}^{n+1}$ be a given smooth closed strictly convex hypersurface containing the origin $O$ with a support function $F:\mathbb{S}^{n}\rightarrow\mathbb{R}_+$. The Cahn-Hoffman map associated with $F$ is given by
 \begin{align}\label{equ:Psi}
 \Psi:\mathbb{S}^n\rightarrow\mathbb{R}^{n+1},\quad	\Psi(x)=F(x)x+\nabla^{\mathbb{S}} {F}(x),
 \end{align}
where $\nabla^{\mathbb{S}}$ denotes the covariant derivative on $\mathbb{S}^n$ with standard round metric. $\mathcal{W}$ is called a Wulff shape with support function $F$. Let $\Sigma$ be a smooth compact orientable hypersurface in $\overline{\mathbb{R}_+^{n+1}}$ with boundary $\partial\Sigma\subset\partial\overline{\mathbb{R}_+^{n+1}}$, which encloses a bounded domain $\widehat{\Sigma}$. Let $\nu$ be the unit normal  of $\Sigma$ pointing outward of  $\widehat{\Sigma}$. Given a constant  $\omega_0 \in(-F(E_{n+1}), F(-E_{n+1}))$, we say $\Sigma$ is an \textbf{anisotropic $\omega_0$-capillary hypersurface} (see \cite{Jia-Wang-Xia-Zhang2023}) if
\begin{align}
	\label{equ:w0-capillary}
	\<\Psi(\nu),-E_{n+1}\>=\omega_0,\quad \text{on}\ \partial\Sigma.
\end{align}
If additionally, $\Sigma$ is convex, we call $\widehat{\Sigma}$ the \textbf{anisotropic $\omega_0$-capillary convex body} associated with $\Sigma$. 



For the convenience of description, we need a constant vector $E_{n+1}^F \in \mathbb{R}^{n+1}$ (ref. \cite{Jia-Wang-Xia-Zhang2023,Xia-arxiv}) defined as
 $$
 E_{n+1}^F= \begin{cases}\frac{\Psi\left(E_{n+1}\right)}{F\left(E_{n+1}\right)}, & \text { if } \omega_0<0, \\[5pt]
 	E_{n+1},  & \text { if } \omega_0=0,
 	\\[5pt]
  -\frac{\Psi\left(-E_{n+1}\right)}{F\left(-E_{n+1}\right)}, & \text { if } \omega_0>0.\end{cases}
 $$
 Note that $E_{n+1}^F$ is the unique vector in the direction $\Psi\left(E_{n+1}\right)$, whose scalar product with $E_{n+1}$ is 1 (see \cite{Jia-Wang-Xia-Zhang2023}*{eq. (3.2)}).


 The model example of anisotropic $\omega_0$-capillary hypersurface is the $\omega_0$-capillary Wulff shape $\W_{r_0,\omega_0}$ (see \cite{Jia-Wang-Xia-Zhang2023}) defined by \eqref{equ:crwo}, which is a part of a Wulff shape in $\overline{\mathbb{R}^{n+1}_+}$ such that the anisotropic capillary boundary condition \eqref{equ:w0-capillary} holds. %We denote ${\W_{r_0,\omega_0}}=\W_{r_0}(x_0)\cap\overline{\mathbb{R}_{+}^{n+1}}$, where $ x_0=r_0\omega_0E^F_{n+1}$ and  $\W_{r_0}(x_0)$ is defined in . And
 We denote $\mathcal{C}_{\omega_0}:=\W_{1,\omega_0}=\mathcal{T}(\W\cap\{x\in\mathbb{R}^{n+1}:\<x,E_{n+1}\>\geq -\omega_0\})$, where
 \begin{align}
 	\mathcal{T}:x\rightarrow x+\omega_0E_{n+1}^F,\quad
 \text{for}\  x\in \mathbb{R}^{n+1} ,
\label{equ:T=}
 \end{align}
  is a translation transformation.

 Let $(\Sigma,g)$ be an  anisotropic $\omega_0$-capillary hypersurface in $\overline{\mathbb{R}^{n+1}_+}$ with boundary supported on $\partial\overline{\mathbb{R}^{n+1}_+}$, where metric $g$ is induced from Euclidean space $(\mathbb{R}^{n+1},\<\cdot,\cdot\>)$. In \cite{Ding-Gao-Li-arxiv}, we introduced the anisotropic capillary quermassintegrals as follows:
 \begin{align*}%\label{equ:v1}
 \mathcal{V}_{0,\omega_0}(\Sigma):=|\widehat{\Sigma}|,
 \quad	\mathcal{V}_{1,\omega_0}({\Sigma})=\frac{1}{n+1}\left(
 	|\Sigma|_F+\omega_0|\widehat{\partial\Sigma}|
 	\right),
 \end{align*}
 and for $1\leq k\leq n$,
 \begin{align*}%\label{equ:Vk}
 	\mathcal{V}_{k+1,\omega_0}(\Sigma)=
 	\frac{1}{n+1}
 	\left(
 	\int_{\Sigma}H^F_kF(\nu)d\mu_g
 	+\frac{\omega_0}{n}
 	\int_{\partial\Sigma} H_{k-1}^{\bar{F}}\bar{F}(\bar{\nu})ds
 	\right),
 \end{align*}
 where $\widehat{\partial\Sigma}=\widehat{\Sigma}\cap \partial\overline{\mathbb{R}^{n+1}_+}$ denotes the domain enclosed  by $\partial\Sigma\subset\mathbb{R}^n=\partial\overline{\mathbb{R}^{n+1}_+}$,
 $|\cdot |$ denotes the volume of the domain in $ \mathbb{R}^n$ or $ \mathbb{R}^{n+1}$,
 $|\cdot |_F$ denotes the anisotropic area defined by \eqref{equ:F-area},
 $\bar{\nu}$  is the unit outward co-normal  of $\partial \Sigma\subset \mathbb{R}^n=\partial\overline{\mathbb{R}^{n+1}_+}$,
 $ds$ is the $(n-1)$-dimensional induced volume form of $\partial \Sigma$,
 $d\mu_g$ is the induced volume form of the metric $g$,
$\bar{F}$ is the support function of the new $(n-1)$-dimensional Wulff shape  $\overline{\W}=\partial\mathcal{C}_{\omega_0}$ in $\partial\overline{\mathbb{R}^{n+1}_+}=\mathbb{R}^n$,
$H_k^{{F}}(0\leq k\leq n,\,H_0^{{F}}=1,H^F_{n+1}=0)$ is the  normalized anisotropic $k$-mean curvature of $\Sigma\subset\mathbb{R}^{n+1}$ with respect to Wulff shape ${\W}$,
and $H_k^{\bar{F}}(0\leq k\leq n-1,\,H_0^{\bar{F}}=1)$ is the  normalized anisotropic $k$-mean curvature of $\partial\Sigma\subset\mathbb{R}^n$ with respect to Wulff shape $\overline{\W}$.

Specifically, if we take $\W$ to be the unit sphere, then $F = 1$, and the anisotropic case reduces to the classical isotropic geometry, and  the anisotropic capillary quermassintegrals
 matches the definition of  isotropic quermassintegrals \cite{Wang-Weng-Xia}*{eq.(1.8)} for  capillary hypersurfaces in the half-space.

 As shown in \cite{Ding-Gao-Li-arxiv}*{Theorem 6.2}, the first variation of $\mathcal{V}_{k+1,\omega_0}$ gives rise to $H^F_{k+1}$ with $-1\leq k\leq n$. Then in \cite{Ding-Gao-Li-arxiv}*{Theorem 1.4}, for convex anisotropic $\omega_0$-capillary hypersurface $\Sigma$, we  used the flow method to prove the following Alexandrov-Fenchel inequality for $l=0,1\leq k\leq n-1$ under certain conditions  (\cite{Ding-Gao-Li-arxiv}*{Condition 1.1}) on the given  Wulff shape $\W$ and constant $\omega_0$,
 \begin{align}\label{equ:A-F-lk}
 	\left(\frac{\mathcal{V}_{k, \omega_0}({\Sigma})}{|\widehat{\mathcal{C}}_{\omega_0}|}\right) ^{\frac{1}{n+1-k}}
 	\geq
 	\left(\frac{\mathcal{V}_{l, {\omega_0}}({\Sigma})}{|\widehat{\mathcal{C}}_{\omega_0}|}\right)^{\frac{1}{n+1-l}}, \quad 0\leq l \leq k\leq  n,
 \end{align}
 with equality holding if and only if $\Sigma$ is an $\omega_0$-capillary Wulff shape. Here $\widehat{\mathcal{C}}_{\omega_0}$  is the anisotropic $\omega_0$-capillary convex body  determined by $\mathcal{C}_{\omega_0}$. In \cite{Ding-Gao-Li-arxiv}*{Remark 1.1 (2)}, we remark that, if $\W=\mathbb{S}^n$ (i.e., the isotropic setting), the Condition 1.1 in \cite{Ding-Gao-Li-arxiv} is equivalent to constant contact angle $\theta\in \left(0,\frac{\pi}{2}\right]$.

 It is natural to consider whether the Condition 1.1 in \cite{Ding-Gao-Li-arxiv} can be removed and whether a more general range of $k$ and $l$, beyond $l=0,1\leq k\leq n-1$, can be addressed.


 In \cite{Xia-arxiv}, Mei, Wang, Weng and Xia proved the more general  Alexandrov-Fenchel inequality for mixed volumes of capillary convex bodies
 \begin{align}\label{equ:V>vv}
 	V^2\left(K_1, K_2, K_3, \cdots, K_{n+1}\right) \geq V\left(K_1, K_1, K_3, \cdots, K_{n+1}\right) V\left(K_2, K_2, K_3, \cdots, K_{n+1}\right),
 \end{align}
 where $V\left(K_1, K_2, \cdots, K_{n+1}\right)$ is the so-called mixed volume of
  a family of $\theta$-capillary convex bodies $K_i \subset \overline{\mathbb{R}_+^{n+1}}, i=1, \cdots, n+1$.
  And it is demonstrated that  the capillary quermassintegrals have alternative integral expressions which match the definition of mixed volumes. Furthermore, the Alexandrov-Fenchel inequality for quermassintegrals of $\theta$-capillary hypersurface with $\theta\in(0,\pi)$ is derived, and thus  this removes the restriction condition $\theta\in(0,\frac{\pi}{2}]$ under which the inequality was proven by flow method in \cite{Wang-Weng-Xia}.

  We remark that for the case of classical Euclidean convex body geometry in $\mathbb{R}^{n+1}$, % (where the convex body boundary is a closed hypersurface),
  if we replace the Euclidean geometric quantities in the integral form of the mixed volume $V(K_1,\cdots,K_{n+1})$ with anisotropic geometric quantities, the value of the mixed volume remains unchanged according to \eqref{equ:Q(AB)=Q(A)det(B)}, \eqref{equ:S_F}, and \eqref{u-hatu}.
   Therefore, there is no necessity to ``generalize" the inequality \eqref{equ:V>vv} from classical closed hypersurfaces in $\mathbb{R}^{n+1}$ (Euclidean framework) to the anisotropic case for closed hypersurfaces in $\mathbb{R}^{n+1}$. However, the situation differs for capillary convex bodies with boundaries: the Gauss map image of an anisotropic capillary convex hypersurface typically does not form a spherical cap but corresponds to irregular regions on the sphere. When transforming the mixed volume into an integral over spherical regions, only special cases can be reduced to the Euclidean capillary boundary scenario. Since the  inequality \eqref{equ:V>vv} for capillary convex bodies  cannot encompass the anisotropic capillary case, it becomes essential to extend inequality \eqref{equ:V>vv} for capillary convex bodies to the anisotropic capillary convex body framework.

 Inspired by \cite{Xia-arxiv}, we also need to  establish a theory for anisotropic capillary convex bodies in half-space. However, due to the asymmetry of the anisotropic Weingarten matrix \eqref{equ:S_F} and the complexity of anisotropic geometry, some challenges arise when extending Proposition 2.9 and Lemma 2.14 (then Proposition 2.15) in \cite{Xia-arxiv}.

Fortunately, in \cite{Ding-Gao-Li-arxiv}*{Lemma 7.4 (i)}, we established an alternative integral expression for the anisotropic capillary quermassintegrals $\mathcal{V}_{k+1,\omega_0}$ for $0\leq k\leq n$:
 \begin{align*}%\label{equ:Vk=Vkkklll}
 	\mathcal{V}_{k+1,\omega_0}(\Sigma)=\frac{1}{n+1}\int_{\Sigma}H_k^F\(F(\nu)+\omega_0\<\nu,E_{n+1}^F\>\) d\mu_g,
 \end{align*}
 then it can be proved that the  anisotropic capillary quermassintegrals match the mixed volume for anisotropic capillary convex bodies (see Lemma \ref{lemma:V-k=V(KKK,LLL)}), which is an extension of \cite{Xia-arxiv}*{Proposition 2.15}.
 Therefore, the main challenge of this paper lies in proving Lemma \ref{lemma:V12=V21}.


Similar to \cite{Xia-arxiv}, we define the anisotropic capillary Gauss map by $\widetilde{\nu_{{F}}}=\mathcal{T}\nu_{{F}}=\nu_{{F}}+\omega_0E_{n+1}^F$ and we use it to reparametrize anisotropic  support function $\hat{u}$ (see \eqref{u-hatu}) by $\hat{s}=\hat{ u}\circ \widetilde{\nu_{{F}}}^{-1}$ as a function on $\mathcal{C}_{\omega_0}$, which we called the \textbf{anisotropic capillary support function}, where $\nu_{{F}}$ and $\hat{ u}$ are respectively the anisotropic Gauss map and anisotropic support function defined in Section \ref{sec 2}. %Since $\Sigma$ can be reparameterized by the inverse anisotropic capillary Guass map, the anisotropic curvatures can be viewed as functions on $\mathcal{C}_{\omega_0}$.
 Let  $\mathcal{K}_{\omega_0}$ denote the collection of all anisotropic $\omega_0$-capillary convex bodies. We prove the following anisotropic capillary version of Alexandrov-Fenchel inequality with rigidity characterization, which extends Theorem 1.1 in \cite{Xia-arxiv}.



\begin{theorem}\label{thm:A-F-convex}
Given a Wulff shape $\W$ (or a Minkowski norm $F$) and a constant
  $\omega_0 \in\left(-F\left(E_{n+1}\right), F\left(-E_{n+1}\right)\right)$. Let $\widehat{\Sigma}_i \in \mathcal{K}_{\omega_0}$ for $1 \leq i \leq n+1$. Then
  \begin{align*}
  	V^2\left(\widehat{\Sigma}_1, \widehat{\Sigma}_2, \widehat{\Sigma}_3, \cdots, \widehat{\Sigma}_{n+1}\right) \geq V\left(\widehat{\Sigma}_1, \widehat{\Sigma}_1, \widehat{\Sigma}_3, \cdots, \widehat{\Sigma}_{n+1}\right) V\left(\widehat{\Sigma}_2, \widehat{\Sigma}_2, \widehat{\Sigma}_3, \cdots, \widehat{\Sigma}_{n+1}\right).
  \end{align*}
  Equality holds if and only if the anisotropic capillary support functions $\hat{s}_j$ of $\widehat{\Sigma}_j, j=1,2$, satisfy
  \begin{align}\label{equ:s=as+...}
  	\hat{s}_1=a \hat{s}_2+\sum_{i=1}^n a_i\frac{\<\nu, E_i\>}{F(\nu)}, \quad \text { on } \quad \mathcal{C}_{\omega_0},
  \end{align}
  for some constants $a>0, a_i \in \mathbb{R}, i=1, \cdots, n$, and $\left\{E_i\right\}_{i=1}^n$ the horizontal coordinate unit vectors of $\overline{\mathbb{R}_{+}^{n+1}}$. %Where is new anisotropic metric on $\mathbb{R}^{n+1}$ (see section).
 %up to translations.
 Here $\nu(\xi)$ is the unit  normal of $\xi\in\mathcal{C}_{\omega_0}$ pointing out of $\widehat{\mathcal{C}}_{\omega_0}$. % at piont $$
\end{theorem}
 We remark that, for any $\widehat\Sigma\in\mathcal{K}_{\omega_0}$, it holds that $\widetilde{\nu_F}(\Sigma)=\mathcal{C}_{\omega_0}$ by Lemma \ref{Lemma:gaussmap}.  %Proposition \ref{prop:xia-prpo2.6}.
  Denote by $\xi=\widetilde{\nu_F}(X)$ for $X\in\Sigma$, it is easy to check that $T_X\Sigma=T_{\xi}\mathcal{C}_{\omega_0}$, then the unit outward normals  of $\Sigma$ and $\mathcal{C}_{\omega_0}$ coincide at the corresponding points. Therefore, we use $\nu $ to denote the unit outer normal of $\Sigma$ or $\mathcal{C}_{\omega_0}$, depending on the context. Similarly, the unit outer co-normal vectors (of $\partial\Sigma$ in $\Sigma$) $\mu$ are treated in the same manner.



As a consequence of Theorem \ref{thm:A-F-convex}, we derive:
\begin{theorem}\label{thm:A-F-k}
	Given a Wulff shape $\W$ (or a Minkowski norm $F$) and a constant
	$\omega_0 \in\left(-F\left(E_{n+1}\right), F\left(-E_{n+1}\right)\right)$.
	For any anisotropic $\omega_0$-capillary convex body $\widehat{\Sigma} \in \mathcal{K}_{\omega_0}$, \eqref{equ:A-F-lk} is true, with equality holding if and only if $\Sigma$ is an $\omega_0$-capillary Wulff shape.
\end{theorem}
\begin{remark}
	If $\W=\mathbb{S}^n$, $\Sigma$ is a $\theta$-capillary hypersurface with $\omega_0=-\cos\theta$, and $\omega_0 \in\left(-F\left(E_{n+1}\right), F\left(-E_{n+1}\right)\right)$ is equivalent to  $\theta\in\left(0,\pi\right)$. Therefore, Theorem \ref{thm:A-F-convex} and \ref{thm:A-F-k} can be viewed as an extension of results in \cite{Xia-arxiv}.
\end{remark}

We mention that, there are numerous studies on the Alexandrov-Fenchel  inequality, as detailed in \cite{book-convex-body,Xia-arxiv,Shenfeld23,McCoy05,Guan-Li-09,Xia2017,Wei-Xiong-22,Wei-Xiong-21,Wang-Weng-Xia,Wang-Weng-Xia-2024-inverseMC,Mei-Wang-Weng-2024-MCF,Weng-Xia-22-ball,Hu-Wei-Yang-Zhou,Makuicheng,Ding-Li-JFA,Gao-Li-JGA}, and references therein.










The rest of this paper is organized as follows. In Section \ref{sec 2}, we briefly introduce some preliminaries on the anisotropic capillary hypersurfaces. In Section \ref{sec 3}, some properties about capillary convex bodies are obtained, and especially, several key lemmas are proved.
Section \ref{sec 4} proves the main Theorem \ref{thm:A-F-convex} and \ref{thm:A-F-k}.


\section{Preliminary}\label{sec 2}
\subsection{The Wulff shape and dual Minkowski norm}
Let $F$ be a smooth positive function on the standard sphere $(\mathbb{S}^n, g^{\mathbb{S}^n} ,\nabla^{\mathbb{S}})$ such that the matrix
\begin{equation*}%\label{equ:A_F>0}
A_{F}(x)~=~\nabla^{\mathbb{S}}\nabla^{\mathbb{S}} {F}(x)+F(x)g^{\mathbb{S}^n}, %>0 \text{ (positive definite)},
\quad x\in \mathbb{S}^n,
\end{equation*}
is positive definite on $  \mathbb{S}^n$,
where %$\nabla^{\mathbb{S}}$ denotes the covariant derivative on $\mathbb{S}^n$ and,
 $g^{\mathbb{S}^n}$ denotes the round metric on $\mathbb{S}^n$.
  Then there exists a unique smooth strictly convex hypersurface $\W$ defined by
\begin{align*}
\W=\{\Psi(x)|\Psi(x):=F(x)x+\nabla^{\mathbb{S}} {F}(x),~x\in \mathbb{S}^n\},
\end{align*}
whose support function is given by $F$ (see \cite{Xia2017}). We call $\W$ the Wulff shape determined by the function $F\in C^{\infty}(\mathbb{S}^n)$. When $F$ is a constant, the Wulff shape is just a round sphere.

The smooth function $F$ on $\mathbb{S}^n$ can be extended  to a $1$-homogeneous function on $\mathbb{R}^{n+1}$ by
\begin{equation*}
F(x)=|x|F({x}/{|x|}), \quad x\in \mathbb{R}^{n+1}\setminus\{0\},
\end{equation*}
and setting $F(0)=0$. Then it is easy to show that $\Psi(x)=DF(x)$ for $x\in \mathbb{S}^n$, where $D$ denotes the standard gradient on $\mathbb{R}^{n+1}$.

%In this paper we add an extra condition for $F$ to make the oblique boundary condition of flow  satisfies the non-degeneracy condition (i.e., \eqref{equ:boundary-nondegenracy}).
%\begin{align}\label{equ:condition}
%	\frac{\partial^2 F}{\partial E_{n+1}\partial E_{n+1}}(x)>0, \quad\text{ for } x\in\mathbb{S}^n\setminus\{E_{n+1},-E_{n+1}\}.
%\end{align}
%Specially, it's easy to check for $\W=\mathbb{S}^{n}$,
%$F(x)=\left(x_1^2+\cdots +x_{n+1}^2\right)^{\frac{1}{2}}$ satisfies condition \eqref{equ:condition}.


The homogeneous extension $F$ defines a Minkowski norm on $\mathbb{R}^{n+1}$, that is, $F$ is a norm on $\mathbb{R}^{n+1}$ and $D^2(F^2)$ is uniformly positive definite on $\mathbb{R}^{n+1}\setminus\{0\}$ (see \cite{Xia-phd}). We can define a dual Minkowski norm $F^0$ on $\mathbb{R}^{n+1}$ by
\begin{align*}%\label{s2:gam0}
F^0(\xi):=\sup_{x\neq 0}\frac{\langle x,\xi\rangle}{{F}(x)},\quad \xi\in \mathbb{R}^{n+1}.
\end{align*}
We call $\W$ the unit Wulff shape since
 $$\W=\{x\in \R^{n+1}: F^0(x)=1\}.$$
A Wulff shape of radius $r_0$ centered at $x_0$ is given by
\begin{align*}%\label{equ:w_r(x)}
	\W_{r_0}(x_0)=\{x\in\mathbb{R}^{n+1}:F^0(x-x_0)=r_0\}.
\end{align*}
An $\omega_0$-capillary Wulff shape of radius $r_0$ (see \cite{Jia-Wang-Xia-Zhang2023}) is given by
\begin{align}\label{equ:crwo}
	\W_{r_0,\omega_0}(E):=\{x\in\overline{\mathbb{R}_+^{n+1}}:F^0(x-r_0\omega_0E)=r_0\},
\end{align}
 which is a part of a Wulff shape cut by a hyperplane  $\{x_{n+1}=0\}$, here $E$ should satisfy $\<E,E_{n+1}\>=1$ which guarantees that  $\W_{r_0,\omega_0}(E)$ satisfies anisotropic capillary condition \eqref{equ:w0-capillary}. It is easy to see that $E-E_{n+1}^F\in \partial\overline{\mathbb{R}^{n+1}_+}$, since $\<E_{n+1},E_{n+1}^F\>=1$. If there is no confusion, we often take $E=E_{n+1}^F$ and we just write $\W_{r_0,\omega_0}:=\W_{r_0,\omega_0}(E^F_{n+1})$ in this paper.
%Namely, it is an intersection of a Wulff shape and $\mathbb{R}^{n+1}_+$.
%It is easy to check that the anisotropic normal of $\W_r(x_0)$ is $\nu_F(x)=\frac{x-x_0}{r}$. On $\W_r(x_0)\cap\{x_{n+1}=0\}$, we know $\<\nu_F,-E_{n+1}\>=\<\frac{x-x_0}{r},-E_{n+1}\>=\<\frac{x_0}{r},E_{n+1}\>$, which is a constant.


\subsection{Anisotropic curvature}
Let $(\Sigma,g,\nabla)\subset \overline{\mathbb{R}^{n+1}_+}$ be a $C^2$ hypersurface with $\partial\Sigma\subset\partial\overline{\mathbb{R}^{n+1}_+}$. %, which encloses a bounded domain  $\widehat{\Sigma}$. %Let $\nu$ be the unit normal of $\Sigma$ pointing outward of  $\hat{\Sigma}$.
The anisotropic Gauss map of $\Sigma$  is defined by $$\begin{array}{lll}\nu_F: &&\Sigma\to  \W\\
&&X\mapsto \Psi(\nu(X))=F(\nu(X))\nu(X)+\nabla^\mathbb{S} F(\nu(X)).\end{array} $$
%The anisotropic Weingarten map $S_F$ is the derivative of the anisotropic normal $\nu_F$.
The anisotropic principal curvatures $\k^F=(\k^F_1,\cdots, \k^F_n)$ of $\Sigma$ with respect to $\W$ at $X\in \Sigma$  are defined as the eigenvalues of
 \begin{align}\label{equ:S_F}
S_F=\mathrm{d}\nu_F=\mathrm{d}(\Psi\circ\nu)=A_F\circ \mathrm{d}\nu : T_X \Sigma\to T_{\nu_F(X)} \W=T_X \Sigma.
\end{align}
%The anisotropic principal curvature radii $\tau=(\tau_1,\cdots, \tau_n)$ of $\Sigma$ with respect to $\W$ at $X\in \Sigma$  are defined as $\tau_i=(\kappa^F_i)^{-1}$, if $\kappa^F_i\ne 0$, $i=1,\cdots,n$.

We define the normalized $k$-th elementary symmetric function $H^F_k=\sigma_k(\kappa^F)/\binom{n}{k}$ of the anisotropic principal curvature $\kappa^F$:
\begin{align*}%\label{equ:Hk}
H^F_k:=\binom{n}{k}^{-1}\sum_{1\leq {i_1}<\cdots<{i_k}\leq n} \kappa^F_{i_1}\cdots \kappa^F_{i_k},\quad k=1,\cdots,n,
\end{align*}
where $\binom{n}{k}=\frac{n!}{k!(n-k)!}$.
Setting $H^F_{0}=1$, $H^F_{n+1}=0$, and $H_F=nH_1^F$
for convenience. To simplify the notation, from now on, we use  $\sigma_k$ to denote function $\sigma_k(\kappa^F)$ of the anisotropic principal curvatures, if there is no confusion.
%When $\Sigma=\W\cap\overline{\mathbb{R}^{n+1}_+}\subset\W$, we have $\kappa^F(\Sigma)=(1,\cdots ,1)$ (see \cite{Xia2017}), and then $H^F_k=1$.



\subsection{New metric and anisotropic formulas}\label{subsec 2.3}
There are new metric on $\Sigma$ and $\mathbb{R}^{n+1}$, which were introduced by Andrews in \cite{And01} and reformulated by Xia in \cite{Xia13}.  This new Riemannian metric $G$ with respect to $F^0$ on $\mathbb{R}^{n+1}$ is defined as
\begin{align*}
	%\label{equ:G}
	G(\xi)(V,W):=\sum_{\alpha,\beta=1}^{n+1}\frac{\partial^2 \frac12(F^0)^2(\xi)}{\partial \xi^\alpha\partial \xi^\beta} V^\alpha W^\beta, \quad\hbox{ for } \xi\in \mathbb{R}^{n+1}\setminus \{0\}, V,W\in T_\xi{\mathbb{R}^{n+1}}.
\end{align*}
The third order derivative of $F^0$ gives a $(0,3)$-tensor
\begin{equation}\nonumber
	%\label{equ:Q}
	Q(\xi)(U,V,W):=\sum_{\alpha,\beta,\gamma=1}^{n+1} Q_{\alpha\beta\gamma}(\xi)U^\alpha V^\beta W^\gamma:=\sum_{\alpha,\beta,\gamma=1}^{n+1} \frac{\partial^3(\frac12(F^0)^2(\xi)}{\partial \xi^\alpha \partial \xi^\beta \partial \xi^\gamma}U^\alpha V^\beta W^\gamma,
\end{equation}
for $\xi\in \mathbb{R}^{n+1}\setminus \{0\},$ $U,V,W\in T_\xi{\mathbb{R}^{n+1}}.$

When we restrict the metric $G$ to $\mathcal{W}$,  the $1$-homogeneity of $F^0$ implies that
\begin{eqnarray*}
	&G(\xi)(\xi,\xi)=1,  \quad G(\xi)(\xi, V)=0, \quad \hbox{ for } \xi\in \W,\  V\in T_\xi \W.
	\\&Q(\xi)(\xi, V, W)=0, \quad \hbox{ for } \xi\in\W,\  V, W\in \mathbb{R}^{n+1}.
\end{eqnarray*}
For a smooth hypersurface $\Sigma$ in $\overline{\mathbb{R}_+^{n+1}}$, since $\nu_F(X)\in \W$ for $X\in \Sigma$, we have
%\begin{eqnarray*}
\begin{align}
	&G(\nu_F)(\nu_F,\nu_F)=1, \quad G(\nu_F)(\nu_F, V)=0, \quad \hbox{ for } V\in T_X \Sigma,\nonumber% \label{equ:G_0}
	\\
	&Q(\nu_F)(\nu_F, V, W)=0, \quad \hbox{ for } V, W\in \mathbb{R}^{n+1}.\nonumber%\label{equ:Q_0}
\end{align}	
%\end{eqnarray*}
%\end{comment}
This means  $\nu_F(X)$ is perpendicular to $T_X \Sigma$ with respect to the metric $G(\nu_F)$.
Then the Riemannian metric $\hat{g}$ on $\Sigma$ induced from $(\mathbb{R}^{n+1}, G)$  can be defined as
\begin{eqnarray*}
	\hat{g}(X):=G(\nu_F(X))|_{T_X \Sigma}, \quad X\in \Sigma.
\end{eqnarray*}

Denote by $\hat{g}_{ij}$ and $\hat{h}_{ij}$ the first and second fundamental form of $(\Sigma, \hat{g})\subset (\mathbb{R}^{n+1}, G)$, respectively, that is
$$\hat{g}_{ij}=G(\nu_F(X))(\p_i X, \p_j X),\quad \hat{h}_{ij}=-G(\nu_F(X))(\nu_F, \partial_i\p_j X).$$
If $\{\hat{g}^{ij}\}$ the inverse matrix of $\{\hat{g}_{ij}\}$, we can reformulate $\k^F$ as  the  eigenvalues of $\{\hat{h}_j^i\}=\{\hat{g}^{ik}\hat{h}_{kj}\}$.
It is easy to see that if $\Sigma=\W$, we have $\nu_F(\W)=X(\W)$, $\hat{h}_{ij}=\hat{g}_{ij}$ and $\kappa^F=(1,\cdots,1)$. If  $X\in\Sigma=\mathcal{C}_{\omega_0}\subset\mathcal{T}\W$, we have $\nu_F(X)=\mathcal{T}^{-1}X=X-\omega_0E_{n+1}^F$, then  $\kappa^F=(1,\cdots,1)$. In this case we denote $\mathring{g}:=G(\mathcal{T}^{-1}{\xi})|_{T_{{\xi}}\mathcal{C}_{\omega_0}}$ (for ${\xi}\in\mathcal{C}_{\omega_0}$), which is a Riemmannian metric on $\mathcal{C}_{\omega_0}$, and denote by $\mathring{\nabla}$ the Levi-Civita connection of $\mathring{g}$.

We denote by $\hat{\nabla}$ the Levi-Civita connections of $\hat{g}$ on $\Sigma$, then the anisotropic Gauss-Weingarten type formula and the anisotropic Gauss-Codazzi type equation are as follows.
\begin{lemma}[\cite{Xia13}*{Lemma 2.5}] \label{lem2-1}
	\begin{eqnarray}%\nonumber%\label{Gauss}
		\partial_i\partial_j X=-\hat{h}_{ij}\nu_F+\hat{\nabla}_{\partial_i } \partial_j+\hat{g}^{kl}A_{ijl}\partial_kX; \;\;\;\hbox{ (Gauss formula)}\label{equ:Gauss-formula}
		\end{eqnarray}
		\begin{eqnarray*}%\label{Weingarten}
		\partial_i \nu_F=\hat{g}^{jk}\hat{h}_{ij}\partial_k X;\;\; \hbox{ (Weingarten formula) }
	\end{eqnarray*}
		 $$\hat{R}_{i j k \ell}=\hat{h}_{i k} \hat{h}_{j \ell}-\hat{h}_{i \ell} \hat{h}_{j k}+\hat{\nabla}_{\partial_{\ell}} A_{j k i}-\hat{\nabla}_{\partial_k} A_{j \ell i}+A_{j k}^m A_{m \ell i}-A_{j \ell}^m A_{m k i} ;\quad	\text{(Gauss equation)}$$
	\begin{eqnarray*}%\label{Codazzi}
		\hat{\nabla}_k\hat{h}_{ij}+\hat{h}_j^lA_{lki}=\hat{\nabla}_j\hat{h}_{ik}+\hat{h}_k^lA_{lji}. \;\;\hbox{ (Codazzi equation) }
	\end{eqnarray*}
	Here, $\hat{R}$ is the Riemannian curvature tensor of $\hat{g}$ and  $A$ is a $3$-tensor
	\begin{eqnarray*}%\label{AA}
	A_{ijk}=-\frac12\left(\hat{h}_i^l Q_{jkl}+\hat{h}_j^l Q_{ilk}-\hat{h}_k^l Q_{ijl}\right),
	\end{eqnarray*} where $Q_{ijk}=Q(\nu_F)(\partial_i X, \partial_j X, \partial_k X)$. Note that the $3$-tensor $A$ on $(\Sigma,\hat{g})$ depends on $\hat{h}_i^j$. It is known that $Q$ is totally symmetric in all three indices, while $A$ is only symmetric for the first two indices.
\end{lemma}
Here $X$ and $\nu_F$ can be regarded as vector-valued functions in $\mathbb{R}^{n+1}$ with a fixed Cartesian coordinate. Hence, the terms $\partial_i\partial_j X$ and $\partial_i \nu_F$ are understood as the usual partial derivative on vector-valued functions. %For convenience, we also denote $X_i=\partial_iX$ and $X^i=\hat{g}^{ij}X_j$.
%Similar to \cite{Xia2017}

The case $\Sigma=\mathcal{C}_{\omega_0}$ is the most important case which will be used in this paper. Analogue to \cite{Xia-2017-convex}*{Proposition 2.2}, we rewrite Lemma \ref{lem2-1} in this case.

\begin{lemma}\label{lemma:Gauss-Weingarten}
	 Let $X \in \mathcal{C}_{\omega_0}\subset\mathcal{T}(\W)=\W+\omega_0E_{n+1}^F$.  We  have $\nu_{{F}}=\mathcal{T}^{-1}(X)$, $\partial_iX=\partial_i(\mathcal{T}^{-1}(X))$, $\mathring{h}_{ij}(X)=\mathring{g}_{ij}(X)=\hat{g}_{ij}(\mathcal{T}^{-1}(X))=\hat{h}_{ij}(\mathcal{T}^{-1}(X))$ with $\{e_i=\partial_iX\}_{i=1}^n\in T_X{\mathcal{C}_{\omega_0}}=T_{\mathcal{T}^{-1}(X)}\W$.
$$
A_{i j k}=-\frac{1}{2} Q_{i j k}=-\frac{1}{2} Q(\mathcal{T}^{-1}(X))\left(\partial_i X, \partial_j X, \partial_k X\right),
$$
and
\begin{align*}%\label{equ:Qjikl-syms}
	\mathring{\nabla}_i Q_{j k l}=\mathring{\nabla}_j Q_{i k l} .
\end{align*}
The Gauss-Weingarten formula and the Gauss equation are as follows:
\begin{align}
	\partial_i \partial_j X & =-\mathring{g}_{i j} \mathcal{T}^{-1}(X)+\mathring{\nabla}_{\partial_i} \partial_j-\frac{1}{2} \mathring{g}^{k l} Q_{i j l} \partial_k X ; \text { (Gauss formula) } \nonumber\\
	\partial_i \nu_F & =\partial_i X ; \text { (Weingarten formula) }\nonumber \\
	\mathring{R}_{i j k l} & =\mathring{g}_{i k} \mathring{g}_{j l}-\mathring{g}_{i l} \mathring{g}_{j k}+\frac{1}{4} \mathring{g}^{p m} Q_{j k p} Q_{m l i}-\frac{1}{4} \mathring{g}^{p m} Q_{j l p} Q_{m k i}. \text { (Gauss equation) }\nonumber%\label{equ:R=}
\end{align}
\end{lemma}
