\begin{align}\label{equ:G(vF,Y)=<v,Y>/F}
	G(\nu_F)(\nu_F,Y)=\<DF^0(DF(\nu)),Y\>=\<\frac{\nu}{F(\nu)},Y\>=\frac{\<Y,\nu\>}{F(\nu)},
\end{align}
for any $Y\in \mathbb{R}^{n+1}$.
