\begin{lemma}[Jia-Wang-Xia-Zhang, 2023, \cite{Jia-Wang-Xia-Zhang2023}*{Theorem 1.3}] \label{Thm1.2}
	Let  $\Sigma \subset \overline{\mathbb{R}_{+}^{n+1}}$ be a $C^2$ anisotropic $\omega_0$-capillary hypersurface, where $\omega_0 \in\left(-F\left(E_{n+1}\right)\right.,$ $\left.F\left(-E_{n+1}\right)\right)$.
