\section{Anisotropic $\omega_0$-capillary convex bodies and mixed volume in $\overline{\mathbb{R}^{n+1}_+}$}\label{sec 3}
In this section, we shall study  anisotropic $\omega_0$-capillary convex bodies in $\overline{\mathbb{R}^{n+1}_+}$, in the frame work of  Mei, Wang, Weng and Xia \cite{Xia-arxiv} for Euclidean (isotropic) $\theta$-capillary convex bodies. %Then inspired by \cite{Xia-arxiv,book-convex-body,Shenfeld19,Shenfeld22}.

\subsection{Anisotropic capillary convex bodies and convex functions}

	Given a Wulff shape $\W$ (or a Minkowski norm $F$). For $\omega_0\in\left(-F(E_{n+1}),F(-E_{n+1})\right)$, let $\Sigma$ be a strictly convex anisotropic $\omega_0$-capillary hypersurface in $\overline{\mathbb{R}_+^{n+1}}$ (satisfies anisotropic capillary boundary condition \eqref{equ:w0-capillary}), and $\widehat{\Sigma}\in\mathcal{K}_{\omega_0}$  the anisotropic $\omega_0$-capillary convex body associated with $\Sigma$. %If  $\widehat{\partial\Sigma}\subset \partial\overline{\mathbb{R}_{+}^{n+1}}$ contains the origin $O$, we denote $\widehat{\Sigma}\in \mathcal{K}^O_{\omega_0}$.



	The simplest capillary convex body $\widehat{\mathcal{C}}_{\omega_0}\in \K_{\omega_0}$ is the bounded domain enclosed by $\mathcal{C}_{\omega_0}$ and $\partial\overline{\mathbb{R}_+^{n+1}}$.

	Let $\mathcal{T}:\mathbb{R}^{n+1}\to \mathbb{R}^{n+1}$ be the translation given by \eqref{equ:T=}. %$$\mathcal{T}(X)= X+\omega_0E_{n+1}^F.$$
	Instead of using the usual anisotropic Gauss map $\nu_F$, it is more convenient to use the following map
	\begin{eqnarray*}%\label{cap Gauss map}
		\widetilde {\nu_F}:= \mathcal{T} \circ \nu_F: \Sigma \to \mathcal{C}_{\omega_0},\end{eqnarray*}
	which we call \textbf{ anisotropic capillary Gauss map} of $\Sigma$.

	 Next for any $\widehat{\Sigma}\in \mathcal {K}_{\omega_0}$ we give a parametrization of $\Sigma$   via the anisotropic capillary Gauss map $\widetilde {\nu_F}$.
	\begin{lemma}\label{Lemma:gaussmap}
			Given a Wulff shape $\W$ (or a Minkowski norm $F$), and a constant  $\omega_0\in\left(-F(E_{n+1}),F(-E_{n+1})\right)$. Denote  $\mathcal{S}:=\{x\in\mathbb{S}^n:\<DF(x),E_{n+1}\>\geq -\omega_0\}$.  %is a connecte domain in $			\mathbb{S}^{n}$.
			 For any  $\widehat{\Sigma}\in\mathcal{K}_{\omega_0}$, we have
		\begin{itemize}
			\item [(1)]  The Gauss map $\nu$ of $\Sigma$ has its spherical image $\mathcal{S}\subset\mathbb{S}^n$, and $\nu:\Sigma \to \mathcal{S}$ is a diffeomorphism.

			\item [(2)] The anisotropic capillary Gauss map $\widetilde{\nu_{{F}}}=\nu_{{F}}+\omega_0E_{n+1}^F$ of $\Sigma$ has its image in $\mathcal{C}_{\omega_0}=\(\W+\omega_0E_{n+1}^F\)\bigcap\overline{\mathbb{R}^{n+1}_+}$, and  $\widetilde {\nu_F}: \Sigma\to \mathcal{C}_{\omega_0}$  %has its image in
		%\begin{eqnarray*}
		%	\mathbb{S}^n_\theta :=\{ y\in \mathbb{S}^n \,|\,  y_{n+1} \geq \cos \theta\},
		%\end{eqnarray*}
	%	and $\nu: \Sigma\to \mathbb{S}^n_\theta$
	is a diffeomorphism.
		\end{itemize}
	\end{lemma}

	\begin{proof} (1) Since $\widehat{\Sigma}\in\mathcal{K}_{\omega_0}$, % is a smooth,  strictly convex capillary hypersurface,
		following the approach established in  \cite[Corollary 2.4 (ii)]{Wang-Weng-Xia}, we obtain the relation $B_{\alpha\beta}(X)=\sin\theta(X)\cdot B^{\partial}_{\alpha\beta}(X)$ for $X\in\partial\Sigma$, where $\theta(X)$ is a function on $\partial\Sigma$ which satisfies $\<\nu(X),E_{n+1}\>=\cos\theta(X)$,  $e_{\alpha},e_{\beta}\in T_X(\partial\Sigma)$, $B$ and $B^{\partial}$ are the second fundamental form of $\Sigma\subset\overline{\R^{n+1}_+}$ and $\partial\Sigma \subset \mathbb{R}^n$ respectively. An argument parallel to that of \cite[Corollary 2.5]{Wang-Weng-Xia} shows that $\partial\Sigma\subset \partial\overline{\R^{n+1}_{+}}$ is a  strictly convex, closed  hypersurface. %In particular, the Gauss map of $\p \Sigma$ is one-to-one on  boundary.

		 By \cite[Corollary 3.1 and Notes 3.2]{Ghomi}, we see that {the Gauss map $\nu$ of $\Sigma$ restricted to   $\p \Sigma$   is one-to-one} and furthermore, $\nu: \Sigma\to \nu(\Sigma)\subset \mathbb{S}^{n}$ is a diffeomorphism.
		 On the other hand,  it follows from \eqref{equ:w0-capillary} that $\nu(\partial \Sigma)=\partial\mathcal{S}$.
		  Also, since $\<DF(E_{n+1}),E_{n+1}\>=F(E_{n+1})>-\omega_0$, we have $E_{n+1}\in \mathcal{S}$ which lies in $\nu(\Sigma)$. It follows that $\nu(\Sigma)=\mathcal{S}$, then the assertion follows.

		  (2) Since  $\widehat{\mathcal{C}}_{\omega_0}\in\mathcal{K}_{\omega_0}$, by (1), the Gauss map $\nu^{\mathcal{C}_{\omega_0}}$ of $\mathcal{C}_{\omega_0}$ also has its image $\mathcal{S}$, and $\mathcal{C}_{\omega_0}=\mathcal{T}\(\W\cap\{x\in\mathbb{R}^{n+1}:\<x,E_{n+1}\>\geq-\omega_0\}\)\subset\mathcal{T}\W$ is diffeomorphic to its spherical image $\mathcal{S}$. This implies that $\(\nu^{\mathcal{C}_{\omega_0}}\)^{-1}\circ\nu: \Sigma\to\mathcal{C}_{\omega_0}$ is a diffeomorphic.

		 Denote by $\nu^{\W}$ the Gauss map of $\W$. Since $\nu^{\mathcal{C}_{\omega_0}}(\xi)=\nu^{\W}(\mathcal{T}^{-1}(\xi))$ for $\xi\in\mathcal{C}_{\omega_0}$ and $\nu_{{F}}(X)=DF(\nu(X))=\(\nu^{\W}\)^{-1}\circ\nu(X)$ for $X\in \Sigma$,  we have $\widetilde{\nu_{{F}}}=\mathcal{T}\circ\nu_{{F}}=\(\nu^{\mathcal{C}_{\omega_0}}\)^{-1}\circ\nu$. This completes the proof.
	\end{proof}



	From Lemma \ref{Lemma:gaussmap}, we can parametrize $\Sigma$ by the inverse anisotropic capillary Gauss map, i.e., $X:\mathcal{C}_{\omega_0}\to \Sigma$,  given by
