		\begin{eqnarray}\label{equ:s0}
			\hat{s}_o(\xi):=1+\omega_0G(\xi-\omega_0E_{n+1}^F)\(E_{n+1}^F  , \xi -\omega_0E_{n+1}^F\).
		\end{eqnarray} % Therefore $\ell$  is  the capillary support function of $\mathcal{C}_{\omega_0}$ (or of $\widehat{\mathcal{C}}_{\omega_0}$) 	.


		Similar to \cite{Xia-arxiv}, we have the  following lemma for anisotropic setting.
		\begin{lemma}\label{lemma:Xia-Lemma2.4}
			For the parametrization $X:\left(\mathcal{C}_{\omega_0},\mathring{g},\mathring{\nabla }\right)\rightarrow\Sigma$ of anisotropic $\omega_0$-capillary convex body $\widehat{\Sigma}$, we have
			\begin{itemize}
			\item[(1)] $X(\xi)=\mathring{\nabla} \hat{s}(\xi) +\hat{s}(\xi)\mathcal{T}^{-1}(\xi)$.

			\item[(2)]  $\mathring{\nabla}_{\mu_F}\hat{s}=\frac{\omega_0}{F(\nu)\<\mu,E_{n+1}\>}\hat{s}$ along $\partial\mathcal{C}_{\omega_0}$. %, where $\mu$ is the outward unit conormal to $\partial \mathcal{C}_{\omega_0}\subset \mathcal{C}_{\omega_0}$.

			\item[(3)] The anisotropic principal curvature radii of $\Sigma$ at $X(\xi)$ are given by the eigenvalues of $\tau_{ij}(\xi):=\mathring{\nabla}_{e_i}\mathring{\nabla}_{e_j}\hat{s}(\xi)+\mathring{g}_{i j} \hat{s}(\xi)-\frac{1}{2} Q_{i j k} \mathring{\nabla}_{e_k} \hat{s}(\xi)$  with respect to the metric $\mathring{g}$, where $\{e_i\}_{i=1}^n$ is an orthonormal frame on $(\mathcal{C}_{\omega_0},\mathring{g})$.  In particular, $(\tau_{ij})>0$ on $\mathcal{C}_{\omega_0}$.
		\end{itemize}	
	\end{lemma}

	\begin{proof}
	 (1) From \eqref{support}, for $\xi\in\mathcal{C}_{\omega_0}$, we have
	 		\begin{align}
				\mathring{\nabla}_{e_i} \hat{s}(\xi)=&G(\mathcal{T}^{-1}(\xi))\(D_{e_i} X, \xi -\omega_0E_{n+1}^F\)+G(\mathcal{T}^{-1}(\xi))\(X, e_i\)\nonumber
				\\
				&+Q(\mathcal{T}^{-1}(\xi))\(D_{e_i}(\mathcal{T}^{-1}(\xi)),\mathcal{T}^{-1}(\xi),X\)\nonumber
				\\
				=&G(\mathcal{T}^{-1}(\xi))\(X, e_i\), \quad 1\leq i\leq n.
				\label{equ:Ds}
			\end{align}
			Here the second equality follows from the fact that $Q(z)(z,\cdot,\cdot)=0$ and the fact that $D_{e_i} X$ is tangential to $\Sigma$ under the anisotropic metric $G(\mathcal{T}^{-1}(\xi))(\cdot,\cdot)$ in $T_{\xi}\mathbb{R}^{n+1}$, while $\mathcal{T}^{-1}(\xi)=\xi -\omega_0E_{n+1}^F=\nu_{{F}}(X(\xi))$ is anisotropic normal to $\Sigma$. The first assertion follows.

		(2) By the anisotropic capillary boundary condition, we have
		\begin{align*}
			-\omega_0=\<\nu_{{F}}(X(\xi)),E_{n+1}\>=\<\mathcal{T}^{-1}(\xi),E_{n+1}\>,\quad\xi\in\partial\mathcal{C}_{\omega_0}.
		\end{align*}
		Then for $\xi\in\partial\mathcal{C}_{\omega_0}$, we have
		\begin{align*}
			0=&\<X,E_{n+1}\>\overset{(1)}{=}\<\mathring{\nabla} \hat{s}(\xi) +\hat{s}(\xi)\mathcal{T}^{-1}(\xi),E_{n+1}\>
			\\
			=&\<\mathring{\nabla} \hat{s}(\xi),\nu\>\cdot\<E_{n+1},\nu\>+\<\mathring{\nabla} \hat{s}(\xi),\mu\>\cdot\<E_{n+1},\mu\>-\omega_0\hat{s}(\xi)
			\\
			=&\mathring{g}\(\mathring{\nabla}\hat{s},\mu_{{F}}\)\cdot F(\nu)\<E_{n+1},\mu\>-\omega_0\hat{s},
		\end{align*}
		where we use $E_{n+1}=\<E_{n+1},\nu\>\nu+\<E_{n+1},\mu\>\mu$ (see \cite{Jia-Wang-Xia-Zhang2023}), $\mathring{\nabla}\hat{s}\in T{\mathcal{C}_{\omega_0}}=T\W=T\Sigma$, and the fact that $G(\nu_{{F}})(Y,\mu_{{F}})=\frac{\<Y,\mu\>}{F(\nu)}$ for $\forall Y\in T\Sigma$ (see \cite[eq. (3.29)]{Ding-Gao-Li-arxiv}). The second assertion follows.

		(3)	%By (1) above, we have $\mathring{\nabla}_{e_i}\hat{s}=G(\mathcal{T}^{-1}\xi)\(\mathring{\nabla}_{e_i}\)$
		By \eqref{equ:Ds}, Lemma \ref{lemma:Gauss-Weingarten}, and  \eqref{equ:Gauss-formula}, for $\xi\in\partial\mathcal{C}_{\omega_0}$, we have at the normal coordinate of $\mathring{g}$
		\begin{align*}
			&\mathring{\nabla}_{e_i}\mathring{\nabla}_{e_j}\hat{s}(\xi)=e_i\left(G(\mathcal{T}^{-1}(\xi))\(D_{e_j} \xi, X\)\right) \\
			= & G(\mathcal{T}^{-1}(\xi))\(D_{e_i}D_{ e_j }\xi, X(\xi)\)+G(\mathcal{T}^{-1}(\xi))\(D_{e_j}( \mathcal{T}^{-1}(\xi)),D_{ e_i} X\)+Q(\mathcal{T}^{-1}(\xi))\(D_{ e_i} \xi, D_{e_j} \xi, X(\xi)\) \\
			= & -\delta_{i j} G(\mathcal{T}^{-1}(\xi))\(\mathcal{T}^{-1}(\xi), X(\xi)\)-\frac{1}{2} Q(\mathcal{T}^{-1}(\xi))\(D_{ e_i} \xi, D_{e_j} \xi, D_{e_k} \xi\) G(\mathcal{T}^{-1}(\xi))\(e_k, X(\xi)\) \\
			& \quad+G(\mathcal{T}^{-1}(\xi))\(\mathcal{T}^{-1}(\xi),\hat{h}_{i j}(X) \mathcal{T}^{-1}(\xi)\)+Q(\mathcal{T}^{-1}(\xi))\(D_{ e_i} \xi, D_{e_j} \xi, D_{e_k} \xi\) G(\mathcal{T}^{-1}(\xi))\(e_k, X(\xi)\) \\
			 =&-\delta_{i j} \hat{s}(\xi)+\hat{h}_{i j}(X(\xi))+\frac{1}{2} Q_{i j k} \mathring{\nabla}_{e_k} \hat{s}(\xi).
		\end{align*}

		Hence the anisotropic second fundamental form $\hat{h}_{ij}(X(\xi))$ is given by
		$$\hat{h}_{ij}(X(\xi))=\mathring{\nabla}_{e_i}\mathring{\nabla}_{e_j}\hat{s}(\xi)+\delta_{i j} \hat{s}(\xi)-\frac{1}{2} Q_{i j k} \mathring{\nabla}_{e_k} \hat{s}(\xi).$$
			By the Weingarten formula $D_{ e_i}\xi=D_{ e_i}(\mathcal{T}^{-1}(\xi))=D_{ e_i}\nu_{{F}}(\xi)=\hat{g}^{kl}\hat{h}_{ik}\cdot D_{e_l}X$, we see
			\begin{eqnarray*}
				\mathring{g}_{ij}&=&G(\mathcal{T}^{-1}(\xi))\(D_{ e_i}\xi, D_{e_j}\xi\)%=G(\mathcal{T}^{-1}\xi)\(D_{e_i}(\mathcal{T}^{-1}\xi), D_{e_j}(\mathcal{T}^{-1}\xi)\)
				\\&=&G(\mathcal{T}^{-1}(\xi))\(\hat{g}^{kl}\hat{h}_{ik}\cdot D_{e_l}X, \hat{g}^{pq}\hat{h}_{jp}\cdot D_{e_q}X\)=\hat{h}_{ik}\hat{h}_{jp}\hat{g}^{kp}.
			\end{eqnarray*}
			Hence \begin{eqnarray*}
				\hat{g}_{kp}=\mathring{g}^{ij}\hat{h}_{ik}\hat{h}_{jp}.
			\end{eqnarray*}
			It follows that the principal curvature radii, i.e., the eigenvalues of $\left(\hat{g}_{kp}\hat{h}^{jp}\right)$, are given by the eigenvalues of $\(\mathring{\nabla}_{e_i}\mathring{\nabla}_{e_j}\hat{s}(\xi)+\mathring{g}_{i j} \hat{s}(\xi)-\frac{1}{2} Q_{i j k} \mathring{\nabla}_{e_k} \hat{s}(\xi)\)$ with respect to the metric $\mathring{g}$. Here $\hat{h}^{ij}$ means the inverse of $\hat{h}_{ij}$. The third assertion follows. 		
		\end{proof}		
		\begin{definition}\label{defn-convex capillary fun}
			For $\omega_0\in (-F(E_{n+1}),F(-E_{n+1}))$, a function $f\in  C^{2}(\mathcal{C}_{\omega_0})$  is called an \textbf{anisotropic capillary function} if it satisfies the following   boundary condition
			\begin{eqnarray}
				\label{robin}
				\mathring{\nabla}_{\mu_F} f=\frac{\omega_0}{F(\nu)\<\mu,E_{n+1}\>} f\quad \text{on}\quad \partial \mathcal{C}_{\omega_0}.
			\end{eqnarray}	
			If in addition, $\tau[f](\xi)=\(\tau_{ij}[f](\xi)\):=\(\mathring{\nabla}_{e_i}\mathring{\nabla}_{e_j}f(\xi)+\mathring{g}_{i j} f(\xi)-\frac{1}{2} Q_{i j k} \mathring{\nabla}_{e_k} f(\xi)\)>0$ on $\mathcal{C}_{\omega_0}$, $f$ is called an \textbf{anisotropic capillary convex function} on $\mathcal{C}_{\omega_0}$.
		\end{definition}
		%where $\nu$ is the Gauss map of $\Sigma$.
		Similar to the isotropic case in \cite[Proposition 2.6]{Xia-arxiv}, the next proposition shows that an anisotropic capillary convex function on $\mathcal{C}_{\omega_0}$  yields an anisotropic  $\omega_0$-capillary convex body in $\overline{\R^{n+1}_+}$, and vice versa. This can be compared to the one-to-one correspondence of convex bodies in ${\R^{n+1}}$ and convex functions on Wulff shape $\W$ (\cite{Xia13}).

		\begin{proposition}\label{prop:xia-prpo2.6}
			Let $\hat{s}\in C^{2}(\mathcal{C}_{\omega_0})$. Then $\hat{s}$ is an anisotropic capillary convex function if and only if $\hat{s}$ is the anisotropic capillary support function of an anisotropic capillary convex body $\widehat{\Sigma}\in \mathcal{K}_{\omega_0}$. %hypersurface $\Sigma\subset \overline{\RR^{n+1}_+}$.
		\end{proposition}
		\begin{proof}
			We have already seen from Lemma \ref{lemma:Xia-Lemma2.4} that
			if $\hat{s}\in C^{2}(\mathcal{C}_{\omega_0})$ is the anisotropic capillary support function of an anisotropic  capillary convex hypersurface $\Sigma\subset \overline{\R^{n+1}_+}$, then  $\hat{s}$ is an anisotropic   capillary convex function.
			It remains to show the converse.

			Let $\hat{s}\in C^{2}(\mathcal{C}_{\omega_0})$ be an anisotropic  capillary convex function. Consider the hypersurface $\Sigma$ given by the map
			\begin{eqnarray*}
				X: &&\mathcal{C}_{\omega_0}\to\R^{n+1},\\
				&&X(\xi)=\mathring{\nabla} \hat{s}(\xi)+\hat{s}(\xi) \mathcal{T}^{-1}(\xi).
			\end{eqnarray*}

			For  $\xi\in\mathcal{C}_{\omega_0}$, we have $T_{\xi}\mathcal{C}_{\omega_0}=T_{\mathcal{T}^{-1}(\xi)}\W$, then $\mathcal{T}^{-1}(\xi)$ is the anisotropic normal of $\mathcal{C}_{\omega_0}$. It is easy to see $\<\xi, E_{n+1}\>=0$ for $\xi\in\mathcal{C}_{\omega_0}$, then $\<\mathcal{T}^{-1}(\xi),E_{n+1}\>=-\omega_0$ for $\xi\in\mathcal{C}_{\omega_0}$.
			It follows by the decomposition $E_{n+1}=\<E_{n+1},\nu\>\nu+\<E_{n+1},\mu\>\mu$, that
			\begin{align*}
				\<X(\xi), E_{n+1}\>=&\<\mathring{\nabla} \hat{s}(\xi)+\hat{s}(\xi)\mathcal{T}^{-1}(\xi), E_{n+1}\>
				= \<\mathring{\nabla}\hat{s},\mu\>\cdot  \< \mu, E_{n+1}\>-\omega_0\hat{s}(\xi)
				\\
				=&G(\mathcal{T}^{-1}\xi)\(\mathring{\nabla}\hat{s},\mu_{{F}}\)F(\nu)\<\mu,E_{n+1}\>-\omega_0\hat{s}(\xi)
				\\
				\overset{\eqref{robin}}{=}&0, \quad\xi\in\partial\mathcal{C}_{\omega_0},
			\end{align*}
			which implies $X(\p \mathcal{C}_{\omega_0})=\partial\Sigma\subset \partial \overline{\mathbb{R}^{n+1}_{+}}$.

			For   any tangent vector field $V=V^ie_i$ on $\mathcal{C}_{\omega_0}$, with normal orthonormal frame $\{e_i\}_{i=1}^n$ on $(\mathcal{C}_{\omega_0},\mathring{g})$,   by Lemma \ref{lemma:Gauss-Weingarten},  we obtain
			\begin{align}\label{derivative}
				D_{V}X(\xi)=&D_{V}(\mathring{\nabla} \hat{s}+\hat{s} \mathcal{T}^{-1}(\xi))
				=V^ie_i\left(e_j(\hat{s})\cdot e_j\right)+V^ie_i\left(\hat{s}\cdot \mathcal{T}^{-1}(\xi)\right)
				\nonumber
				\\=& {V}^i\cdot e_ie_j (\hat{s}) - V^i\cdot e_i(\hat{s})\cdot  \mathcal{T}^{-1}(\xi)
				-\frac{1}{2}V^i\cdot e_j(\hat{s})\cdot  Q_{i j k}\cdot  e_k \nonumber
				\\
				& + V^i\cdot e_i(\hat{s}) \cdot \mathcal{T}^{-1}(\xi)+ \hat{s}(\xi)V\nonumber\\=&\left.\(\mathring{\nabla}^2 \hat{s}+\hat{s}\mathring{g}-\frac{1}{2}Q(\mathcal{T}^{-1}(\xi))(\cdot,\cdot,\mathring{\nabla}\hat{s})\)\right|_{\xi}(V),\quad \forall\xi\in\mathcal{C}_{\omega_0}.	
				 	\end{align}
			Since  $(\tau_{ij}[\hat{s}])>0$, we see $X$ is an immersion.
			Also from \eqref{derivative}, we see that  at $\xi$,
			$$T_{X(\xi)}\Sigma={\rm span}\{D_{e_i}X(\xi)\}_{i=1}^n ={\rm span}\{e_i\}_{i=1}^n .$$
			It follows that
			$\nu_F(X(\xi))=\mathcal{T}^{-1}(\xi)=\xi-\omega_0E_{n+1}^F\in\W$ is the anisotropic normal to $\Sigma$ at $X(\xi)$.

			On the other hand, for $\xi\in {\rm int}(\mathcal{C}_{\omega_0})$, we claim that $\<X(\xi), E_{n+1}\>>0$ for each $\xi\in {\rm int}(\mathcal{C}_{\omega_0})$. To see this, %since $\mathcal{C}_{\omega_0}$ is strictly convex, there exist unique $\xi ' \in\mathrm{int}(\mathcal{C}_{\omega_0})$	such that $\nu(\xi)\neq E_{n+1}$. By continuity of $\<X(\xi),E_{n+1}\>$ with respect to $\xi\in\mathcal{C}_{\omega_0}$, it suffices to prove $\<X(\xi),E_{n+1}\>$  for each $\xi\in  {\rm int}(\mathcal{C}_{\omega_0})/\{\xi '\}$.
			for any $\xi_0\in  {\rm int}(\mathcal{C}_{\omega_0})$, assume $\mu_0$ is the unit co-normal  of $\xi_0\in\{x\in\mathcal{C}_{\omega_0}:\<x,E_{n+1}\>=\<\xi_0,E_{n+1}\>\}=\(\mathcal{C}_{\omega_0}\cap\{x_{n+1}=\<\xi_0,E_{n+1}\>\}\)\subset\mathcal{C}_{\omega_0}$ which satisfies $\<\mu_0,E_{n+1}\><0$ (if $E_{n+1}=\nu(\xi)$, take  $\mu_0$ as any unit vector satisfies $\<\mu_0,E_{n+1}\>= 0$). Then we take an arc-length parametrized  curve $\gamma(t):[0,a]\to \mathcal{C}_{\omega_0}$ (see Fig. \ref{fig:1}), which satisfies
			\begin{equation*}
				\renewcommand{\arraystretch}{1.5}
				\left\{
				\begin{array}{ll}
					 \gamma(a)=\xi_a\in\partial\mathcal{C}_{\omega_0},\quad \gamma(0)=\xi_0;
					\\
					\dot{\gamma}(t)=\mu_t;
					\\
					\<\mu_t,E_{n+1}\><0, \,\text{for}\, t\in(0,a].
				\end{array}	
				\right.
			\end{equation*}		
Here $\mu_t$ is the unit co-normal  of $\{x\in\mathcal{C}_{\omega_0}:\<x,E_{n+1}\>=\<\gamma(t),E_{n+1}\>\}\subset\mathcal{C}_{\omega_0}$ at point $\gamma(t)$. In fact $\gamma(t)$ is an  integral curve of $\mu_t$.			
