			Denote by $\nu_t$ the unit outer normal of $\mathcal{C}_{\omega_0}\in\mathbb{R}^{n+1}_+$ at point $\gamma(t)$ for $t\in(0,a]$, and write $\partial\mathcal{C}^t=\{x\in\mathcal{C}_{\omega_0}:\<x,E_{n+1}\>=\<\gamma(t),E_{n+1}\>\}$. Since    vectors $\nu_t,\mu_t,E_{n+1} \in \mathbb{R}^{n+1}$ are all orthogonal to an $(n-1)$-dimensional linear space $T(\partial\mathcal{C}^t)$, then $\nu_t,\mu_t$ and $E_{n+1}$ are on the same plane for $t\in(0,a]$.
			Obviously, $\<\nu_t,\mu_t\>=0$ and $\dot{\gamma}(t)=\mu_t$, and there is the decomposition $E_{n+1}=\<E_{n+1},\dot{\gamma}(t)\>\dot{\gamma}(t)+\<E_{n+1},\nu_t\>\nu_t$ for $t\in [0,a]$.
			 Then we can calculate
			\begin{align*}
			&	\<X(\xi_0), E_{n+1}\>=\<X(\xi_0), E_{n+1}\>-\<X(\xi_a), E_{n+1}\>
				\\=-&\int_0^a\<D_{\dot{\g}(t)}X(\g(t)), E_{n+1}\>dt
				\\=-&\int_0^a \left.\(\mathring{\nabla}^2 \hat{s}+\hat{s}\mathring{g}-\frac{1}{2}Q(\mathcal{T}^{-1}\xi)(\cdot,\cdot,\mathring{\nabla}\hat{s})\)\right|_{\gamma(t)}\(\dot{\gamma}(t), \dot{\gamma}(t)\)\cdot \< E_{n+1}, \dot{\gamma}(t)\>  dt.
			\end{align*}
			Since $(\tau_{ij}[\hat{s}])>0$ and $\< E_{n+1}, \dot{\g}(t)\><0$ for $t\in (0,a ]$, we obtain that $\<X(\xi_0), E_{n+1}\>>0$.
			Hence $X(\mathcal{C}_{\omega_0})\subset \overline{\R^{n+1}_+}$.

			Next, we shall prove $X(\mathcal{C}_{\omega_0})=\Sigma\subset \overline{\R^{n+1}_+}$ is a (locally) strictly convex and anisotropic capillary hypersurface.
			 In fact,
			$$\<\nu_F(X(\xi)), E_{n+1}\>=\<\mathcal{T}^{-1}(\xi), E_{n+1}\>=-\omega_0\quad \hbox{for}~\xi\in \p \mathcal{C}_{\omega_0},$$
			which implies that $X(\mathcal{C}_{\omega_0})$ is an anisotropic $\omega_0$-capillary hypersurface.
		By \eqref{derivative}, we have $D_{e_i}X=\sum_{j=1}^{n}\tau_{ij}[\hat{s}]e_j$, then $$D_{e_i}\nu_F=D_{e_i}(\xi-\omega_0E_{n+1}^F)=\(\mathring{\nabla}^2 \hat{s}+\hat{s}\mathring{g}-\frac{1}{2}Q(\mathcal{T}^{-1}(\xi))(\cdot,\cdot,\mathring{\nabla}\hat{s})\)^{-1} \cdot D_{e_j}X.$$
			Hence the eigenvalues of $\left.\(\mathring{\nabla}^2 \hat{s}+\hat{s}\mathring{g}-\frac{1}{2}Q(\mathcal{T}^{-1}(\xi))(\cdot,\cdot,\mathring{\nabla}\hat{s})\)^{-1}\right|_{\xi}$ gives the anisotropic principal curvature of $\Sigma$ at $X(\xi)$. Thus $X: \mathcal{C}_{\omega_0} \to \overline{\R^{n+1}_+}$ is strictly convex.

			Finally, we prove that $X: \mathcal{C}_{\omega_0}\to \overline{\R^{n+1}_+}$ is an embedding. For this, we look at the anisotopic capillary Gauss map $\widetilde{\nu_{{F}}}: \Sigma\to \mathcal{C}_{\omega_0}$. From the strictly convexity and anisotropic capillarity of $\Sigma$, we know from %\cite[Corollary 3.1]{Ghomi}
			Lemma  \ref{Lemma:gaussmap} (2)
			that the restriction of the anisotropic capillary Gauss map $\widetilde{\nu_{{F}}}$ of $\Sigma$ to its boundary  $\p \Sigma$ is one-to-one and furthermore, $\widetilde{\nu_{{F}}}$ is a diffeomorphism on $\Sigma$. %(as in the proof of Lemma \ref{Lemma:gaussmap}).
			On the other hand,
			$\widetilde{\nu_{{F}}}(\Sigma)= \mathcal{C}_{\omega_0}$, and hence $X(\mathcal{C}_{\omega_0})=\Sigma=\widetilde{\nu_F}^{-1}(\mathcal{C}_{\omega_0})$ is an embedding.		
			This completes the proof.
		\end{proof}





\subsection{Mixed volume  for anisotropic capillary convex bodies}
%First, we prove the Alexandrov-Fenchel inequalities for convex anisotropic $\omega_0$-capillary hypersurface.

 \begin{proposition}\label{prop:sK=sumSi}
 	Let $K_i \in \mathcal{K}_{\omega_0}, i=1, \cdots, m$. Then the Minkowski sum $K:=\sum_{i=1}^m \lambda_i K_i \in$ $\mathcal{K}_{\omega_0}$, where $\sum_{i=1}^m \lambda_i>0$ and $\lambda_1, \cdots, \lambda_m \geq 0$. Moreover,
\begin{align}
	\label{equ:sK=sumSi}
	\hat{s}_K=\sum_{i=1}^m \lambda_i \hat{s}_{K_i},
\end{align}
where $\hat{s}_K$ and $\hat{s}_{K_i}$ are the anisotropic capillary support functions of $K$ and $K_i$ respectively.
 \end{proposition}
\begin{proof}
	For convex bodies $K_i\in\mathcal{K}_{\omega_0}$, we denote $s_{K_i}(x)$ with $x\in\mathbb{S}^n$ as the classical support function of $K_{i}$. Then the classical support  function of convex bodies $K\in\overline{\mathbb{R}^{n+1}_+}$ is $s_K=\sum_{i=1}^{m}\lambda_is_{K_i}$. Since $\nu_{{F}}=\Psi(\nu)$,  where $\Psi$ is defiend by \eqref{equ:Psi}, the anisotropic support function of $K$ is  $\frac{{s_K}}{F}\circ\Psi^{-1}$ which is defined on $\W$.

	Let $\widetilde{s}_{K_i}(\xi)=\frac{s_{K_i}}{F}\circ\Psi^{-1}\circ\mathcal{T}^{-1}(\xi)$, with $\xi\in\(\W+\omega_0E_{n+1}^F\)$. By $\nu_{{F}}=\Psi(\nu)$, $\widetilde{\nu_{{F}}}=\mathcal{T}(\nu_{{F}})$, and the definition of anisotropic capillary support function, we have $\hat{s}_{K_i}=\left.\widetilde{s}_{K_i}\right|_{\mathcal{C}_{\omega_0}}$. We define
	\begin{align*}
		\hat{s}:=\sum_{i=1}^m \lambda_i \hat{s}_{K_i},
		\quad
		\widetilde{s}_K:=\sum_{i=1}^m \lambda_i \widetilde{s}_{K_i}=\frac{s_K}{F}\circ\Psi^{-1}\circ\mathcal{T}^{-1},
	\end{align*}	
	then
$$
\hat{s}:=\left.\widetilde{s}_{K}\right|_{\mathcal{C}_{\omega_0}}.
$$


From Lemma \ref{lemma:Xia-Lemma2.4} (2) and (3), it is easy to see $\hat{s} \in C^2\left(\mathcal{C}_{\omega_0}\right)$ is a capillary convex function, together with Proposition \ref{prop:xia-prpo2.6}, this creates a capillary convex body $L \in \mathcal{K}_{\omega_0}$ with anisotropic capillary support function $\hat{s}$.
%$$
%\hat{s}=\left.\frac{s_L}{F}\circ\Psi^{-1}\circ\mathcal{T}^{-1}\right|_{\mathcal{C}_{\omega_0}} \quad \text { in } \quad \mathcal{C}_{\omega_0}.
%$$
From Lemma \ref{lemma:Xia-Lemma2.4} (1), the position vector of $\partial L \cap \overline{\mathbb{R}_{+}^{n+1}}$ is given by
\begin{align}\label{equ:X-xi}
	X(\xi)=\mathring{\nabla} \hat{s}(\xi)+\hat{s}(\xi) \mathcal{T}^{-1}(\xi)=\mathring{\nabla} \widetilde{s}_K(\xi)+\widetilde{s}_K(\xi) \mathcal{T}^{-1}(\xi), \quad \xi \in \mathcal{C}_{\omega_0}.
\end{align}
Let  $\bar{g}(z)=G(z)|_{T_z\W}$  (for  $z\in\W$) be the metric of $(\W,\bar{g},\bar{\nabla})$ (defined in \cite{Xia13}*{Example 2.7}). Since $\mathring{g}:=G(\mathcal{T}^{-1}{(\xi)})|_{T_{{\xi}}\mathcal{C}_{\omega_0}}$ (for ${\xi}\in\mathcal{C}_{\omega_0}\subset\mathcal{T}\W$), we have $\mathring{g}=(\mathcal{T}^{-1}|_{\mathcal{C}_{\omega_0}})^{*}\bar{g}$. Then for any $f\in C^1(\mathcal{C}_{\omega_0})$ we have $\mathring{\nabla}(f\circ\mathcal{T}^{-1})=\bar{\nabla}f\circ\mathcal{T}^{-1}$, so \eqref{equ:X-xi} (the position vector of $L$) can be written as
\begin{align*}
X=\left.\left(\bar{\nabla} (\frac{s_K}{F}\circ\Psi^{-1})(z)+\frac{s_K}{F}\circ\Psi^{-1}(z)\cdot z\right) \right|_{z=\mathcal{T}^{-1}(\xi)}	, \quad \xi \in \mathcal{C}_{\omega_0}.
\end{align*}
By \cite{Xia13}*{Proposition 3.2}, the right hand side is exactly the position vector of $K$ restricting on $\mathcal{C}_{\omega_0}$, hence we conclude that $K=L \in \mathcal{K}_{\omega_0}$. The last assertion follows from $\hat{s}_K=\left.\widetilde{s}_K\right|_{\mathcal{C}_{\omega_0}}$.
\end{proof}

\begin{definition}[\cite{book-convex-body,Xia-arxiv}]
	The mixed discriminant $\mathcal{Q}:\left(\mathbb{R}^{n \times n}\right)^n \rightarrow \mathbb{R}$ is defined by	
	\begin{align}
		\operatorname{det}\left(\lambda_1 A_1+\cdots+\lambda_m A_m\right)=\sum_{i_1, \cdots, i_n=1}^m \lambda_{i_1} \cdots \lambda_{i_n} \mathcal{Q}\left(A_{i_1}, \cdots, A_{i_n}\right),\label{equ:QA}
	\end{align}
	for $m \in \mathbb{N}, \lambda_1, \cdots, \lambda_m \geq 0$ and the real symmetric matrices $A_1, \cdots, A_m \in \mathbb{R}^{n \times n}$. If $\left(A_k\right)_{i j}$ denotes the $(i, j)$-element of the matrix $A_k$, then	
\begin{align}\label{equ:Q1...n}
		\mathcal{Q}\left(A_1, \cdots, A_n\right)=\frac{1}{n!} \sum_{i_1, \cdots, i_n; j_1, \cdots, j_n} \delta_{j_1 \cdots j_n}^{i_1 \cdots i_n}\left(A_1\right)_{i_1 j_1} \cdots\left(A_n\right)_{i_n j_n}.
\end{align}

\end{definition}
From \eqref{equ:QA}, we check that for any invertible matrix $B\in \mathbb{R}^{n \times n}$, there holds
\begin{align}\label{equ:Q(AB)=Q(A)det(B)}
	\mathcal{Q}\left(A_1B, \cdots, A_nB\right)=\mathcal{Q}\left(A_1, \cdots, A_n\right)\det(B).
\end{align}
By \eqref{equ:Q1...n}, we have
\begin{align}\label{equ:pQ1...n}
	\frac{\partial}{\partial (A_1)_{ij}}\mathcal{Q}\left(A_1, \cdots, A_n\right)=\frac{1}{n!} \sum_{i, i_2, \cdots, i_n; j, j_2, \cdots, j_n} \delta_{jj_2 \cdots j_n}^{ii_2 \cdots i_n}\left(A_2\right)_{i_2 j_2} \cdots\left(A_n\right)_{i_n j_n}.
\end{align}
Then, we obtain
$$\mathcal{Q}(A_1,\cdots,A_n)=\sum_{i,j=1}^{n}(A_1)_{ij}\cdot \frac{\partial}{\partial (A_1)_{ij}} \mathcal{Q}\left(A_1, \cdots, A_n\right).$$
 Similarly, for fixed $i$, we have
 $$\frac{\partial}{\partial (A_1)_{ii}} \mathcal{Q}\left(A_1, \cdots, A_n\right)=\sum_{k,l=1}^{n}(A_2)_{kl}\cdot \frac{\partial^2}{\partial (A_1)_{ii}\partial (A_2)_{lk}} \mathcal{Q}\left(A_1, \cdots, A_n\right).$$
  If $A_1,\cdots,A_n$ are positive definite, by  an inductive proof (together with a unimodular transformation bringing $A_1$ and $A_2$ to diagonal forms) we know that $\mathcal{Q}(A_1,\cdots,A_n)>0$ and $\left(\frac{\partial}{\partial (A_1)_{ij}} \mathcal{Q}\left(A_1, \cdots, A_n\right)\right)_{n\times n}>0$ (or see \cite{book-convex-body}*{Page 328}).
%It is clear that the mixed discriminant $Q$ is a multilinear and symmetric function (see e.g. [1, Chapter 4, Section 25.4]).

\begin{definition}\label{def:V(f1,.,fn)}
	For any $f \in C^2\left(\mathcal{C}_{\omega_0}\right)$, set the $n\times n$ matrix $A[f]:=B\cdot \tau[f]\cdot B^T$, where $B$ satisfies $BB^T=\mathring{g}^{-1}$. A multi-variable function $V:\left(C^2\left(\mathcal{C}_{\omega_0}\right)\right)^{n+1} \rightarrow \mathbb{R}$ is defined by	
	\begin{align*}%\label{equ:V0,1,.n}
		V\left(f_0, \cdots, f_{n}\right)=\frac{1}{n+1} \int_{\mathcal{C}_{\omega_0}} f_0 \mathcal{Q}\left(A \left[f_1\right], \cdots, A \left[f_{n}\right]\right) {%\color{red}
		F(\nu)	\mathrm{d} {\mu_{g}}},
	\end{align*}
	for $f_i \in C^2\left(\mathcal{C}_{\omega_0}\right), 0 \leq i \leq n$, where $d\mu_g$ is the induced volume form of the metric $g$ on $\mathcal{C}_{\omega_0}$, which is induced from Euclidean space $(\mathbb{R}^{n+1},\<\cdot,\cdot\>)$. % Where $\mathrm{d} \hat{\mu}$ is the anisotropic area element of $\mathcal{C}_{\omega_0}$ with respect to $\W$ (see \eqref{equ:duF}).
\end{definition}
We remark that,  $g$ is denoted as the   metric  of  $\Sigma$ or $\mathcal{C}_{\omega_0}$ induced  from Euclidean space depending on the context.

The importance of the multi-linear function $V$ lies in its symmetry.
The following lemma plays a crucial role in establishing the symmetry of $V(f_1,\cdots,f_{n+1})$ (Lemma \ref{lemma:V12=V21}). This constitutes a fundamental distinction of anisotropic geometry in our work (while in the isotropic case  $\mathcal{Q}^{ij}$ satisfies the divergence-free condition). Specially,  if $f_2=\cdots=f_{n+1}$, \eqref{equ:0=Qjijfi-Q+Q} matches  \cite{Xia13}*{eq. (5.10)}.
\begin{lemma}
	\label{lemma:0=Qjijfi-Q+Q}
	For $f_i\in\C^2(\mathcal{C}_{\omega_0})$, $1\leq i\leq n$, denote by matrices $A_k=\tau[f_k]$,  %$(A_k)_{ij}=\tau_{ij}[f_k]$,
	 $\mathcal{Q}:=\mathcal{Q}\left(A_1, \cdots, A_n\right)$, and $\mathcal{Q}^{ij}:=\frac{\partial}{\partial (A_1)_{ij}}\mathcal{Q}\left(A_1, \cdots, A_n\right)$, then
	\begin{align}
		\mathring{\nabla}_j\mathcal{Q}^{ij}\mathring{\nabla}_if_1-\frac{1}{2}\mathcal{Q}^{ij}\mathring{\nabla}_if_1Q_{jkl}\mathring{g}^{kl}+\frac{1}{2}\mathcal{Q}^{ij}\mathring{\nabla}_lf_1Q_{ijk}\mathring{g}^{kl}=0.\label{equ:0=Qjijfi-Q+Q}
	\end{align}
\end{lemma}
\begin{proof}
	Without loss of generality, we compute in an orthogonal frame, i.e., $\mathring{g}_{ij}=\delta_{ij}$. From \cite{Xia13}*{eq.(5.2)}, we see
	\begin{align}\label{equ:pf-lemma:0=Qjijfi-Q+Q-0}
		\mathring{\nabla}_k\tau_{ij}-\mathring{\nabla}_j\tau_{ik}=\sum_{m=1}^{n}\frac{1}{2}Q_{ikm}\tau_{mj}-\frac{1}{2}Q_{ijm}\tau_{mk},\quad \forall k,i,j=1,\cdots, n.
	\end{align}
For any $k,l=2,\cdots,n$, for convenience, we use the symbols $$\mathbb{A}=(A_2)_{i_2j_2}\cdots(A_n)_{i_nj_n},$$ $$\hat{\mathbb{A}}_{k}=(A_2)_{i_2j_2}\cdots(A_{k-1})_{i_{k-1}j_{k-1}} (A_{k+1})_{i_{k+1}j_{k+1}}\cdots (A_n)_{i_nj_n},$$
and for { $k\neq l$}: $$\hat{\mathbb{A}}_{lk}=(A_2)_{i_2j_2}\cdots(A_{k-1})_{i_{k-1}j_{k-1}} (A_{k+1})_{i_{k+1}j_{k+1}}\cdots (A_{l-1})_{i_{l-1}j_{l-1}} (A_{l+1})_{i_{l+1}j_{l+1}}\cdots  (A_n)_{i_nj_n}.$$   	From  \eqref{equ:pQ1...n},  \eqref{equ:pf-lemma:0=Qjijfi-Q+Q-0}, and the antisymmetry of $ \delta_{jj_2\cdots j_n}^{ii_2\cdots i_n} $ with respect to $j$ and $j_k$, we have
	\begin{align}
		&\sum_{i,j=1}^{n}\mathring{\nabla}_j\mathcal{Q}^{ij}\mathring{\nabla}_if_1\nonumber
		\\
		=&
		\sum_{k=2}^{n}\sum_{\substack{i,i_2, \cdots, i_n;\\j, j_2, \cdots, j_n;\\m}}\frac{1}{2n!}\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}  \mathring{\nabla}_if_1\cdot \left(\mathring{\nabla}_j (A_k)_{i_kj_k}-\mathring{\nabla}_{j_k} (A_k)_{i_kj}\right)\cdot\hat{\mathbb{A}}_k\nonumber
		\\
		\overset{\eqref{equ:pf-lemma:0=Qjijfi-Q+Q-0}}{=}&\sum_{k=2}^{n}\sum_{\substack{i, i_2, \cdots, i_n;\\j, j_2, \cdots, j_n;\\m}}\frac{1}{2n!}\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}  \mathring{\nabla}_if_1\left(
		\frac{1}{2}Q_{i_kjm}(A_k)_{mj_k}-\frac{1}{2}Q_{i_kj_km}(A_2)_{mj}
		\right)\hat{\mathbb{A}}_k
		\nonumber
		\\
		=&\sum_{k=2}^{n}\sum_{\substack{i, i_2, \cdots, i_n;\\j, j_2, \cdots, j_n;\\m}}\frac{1}{2n!}\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}  \mathring{\nabla}_if_1\cdot
		Q_{i_kjm}\cdot(A_k)_{mj_k}
		\cdot \hat{\mathbb{A}}_k.\label{equ:pflemma3.17-0}
	\end{align}
 Fixed $k\in\{2,\cdots,n\}$, since the generalized Kronecker symbol $\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n} $ is nonvanishing only when $(i,i_2,\cdots ,i_n)$ is a permutation of $(1,\cdots,n)$,
 it follows that

		\begin{align}
		&\sum_{\substack{i, i_2, \cdots, i_n;\\j,j_2, \cdots, j_n;\\m}}
		 \delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}  \mathring{\nabla}_if_1\cdot
		Q_{i_kjm}\cdot(A_k)_{mj_k}
		\cdot \hat{\mathbb{A}}_k\nonumber
		\\
		=&\sum_{\substack{i, i_2, \cdots, i_n;\\j, j_2, \cdots, j_n}}
		\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}  \mathring{\nabla}_if_1\cdot
		Q_{i_kji}\cdot(A_k)_{ij_k}
		\cdot \hat{\mathbb{A}}_k\nonumber
		\\
		&+\sum_{l=2}^{n}\sum_{\substack{i, i_2, \cdots, i_n;\\j, j_2, \cdots, j_n}}
		\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}  \mathring{\nabla}_if_1\cdot
		Q_{i_kji_l}\cdot(A_k)_{i_lj_k}
		\cdot \hat{\mathbb{A}}_k\nonumber
		\\
		=:&\sum_{\substack{i, i_2, \cdots, i_n;\\j, j_2, \cdots, j_n}}
		\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}  \mathring{\nabla}_if_1\cdot
		Q_{i_kji}\cdot(A_k)_{ij_k}
		\cdot \hat{\mathbb{A}}_k
		+\sum_{l=2}^{n}B_{l,k},\label{equ:pflemma3.17-1}
	\end{align}
	where
$$B_{l,k}=:\sum_{\substack{i, i_2, \cdots, i_n;\\j, j_2, \cdots, j_n}}
	\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}  \mathring{\nabla}_if_1\cdot
	Q_{i_kji_l}\cdot(A_k)_{i_lj_k}
	\cdot \hat{\mathbb{A}}_k,$$
 and obviously
 $$B_{k,k}=\sum_{\substack{i, i_2, \cdots, i_n;\\ j, j_2, \cdots, j_n}}
	\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}\mathring{\nabla}_if_1\cdot
	Q_{i_kji_k}\cdot \mathbb{A}.$$
 When $k\neq l$,  %that is $i_k\neq j_k\in\{1,\cdots,n\}$,
  one can check that
\begin{align*}
	B_{l,k}=&\sum_{\substack{i, i_2, \cdots, i_n;\\j, j_2, \cdots, j_n}}
	\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}  \mathring{\nabla}_if_1\cdot
	Q_{i_kji_l}\cdot(A_k)_{i_lj_k}(A_l)_{i_lj_l}
	\cdot \hat{\mathbb{A}}_{kl}
	\\
	=&\sum_{\substack{i, i_2,\cdots , i_n;\\j, j_2, \cdots, j_n}}
	\delta_{jj_2\cdots j_k\cdots j_l\cdots  j_n}^{ii_2\cdots i_l\cdots i_k\cdots i_n}  \mathring{\nabla}_if_1\cdot
	Q_{i_lji_l}\cdot(A_k)_{i_kj_k}(A_l)_{i_kj_l}
	\cdot \hat{\mathbb{A}}_{kl}
	\\
	=&-B_{k,l},
\end{align*}
where we use the antisymmetry of $ \delta_{jj_2\cdots j_n}^{ii_2\cdots i_n} $ with respect to $i_k$ and $i_{l}$.	Summing both sides of equation \eqref{equ:pflemma3.17-1} over $k\in\{2\cdots,n\}$ yields
	\begin{align}
		&\sum_{k=2}^{n}\sum_{\substack{i, i_2, \cdots, i_n;\\j,j_2, \cdots, j_n;\\m}}
		\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}  \mathring{\nabla}_if_1\cdot
		Q_{i_kjm}\cdot(A_k)_{mj_k}
		\cdot \hat{\mathbb{A}}_k\nonumber
		\\
		=&\sum_{k=2}^{n}\sum_{\substack{i, i_2, \cdots, i_n;\\j, j_2, \cdots, j_n}}
		\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}  \mathring{\nabla}_if_1\cdot
		Q_{i_kji}\cdot(A_k)_{ij_k}
		\cdot \hat{\mathbb{A}}_k
		+\sum_{k,l=2}^{n}B_{l,k}\nonumber
		\\
		=&-\sum_{k=2}^{n}\sum_{\substack{i, i_2, \cdots, i_n;\\j, j_2, \cdots, j_n}}\mathring{\nabla}_{i_k}f_1\cdot
		Q_{i_kji}\cdot
		\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n} \cdot\mathbb{A}\nonumber
		\\
		&+\sum_{k=2}^{n}\sum_{\substack{i, i_2, \cdots, i_n;\\ j, j_2, \cdots, j_n}}\mathring{\nabla}_if_1\cdot Q_{i_kji_{k}}\cdot \delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}
		\cdot\mathbb{A}\nonumber
	\\
	=&-\sum_{\substack{i, i_2, \cdots, i_n;\\ j, j_2, \cdots, j_n; \\m}}\mathring{\nabla}_{m}f_1\cdot Q_{mji}\cdot
	\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}
	\cdot\mathbb{A}
	+\sum_{\substack{i, i_2, \cdots, i_n;\\ j, j_2, \cdots, j_n}}\mathring{\nabla}_{i}f_1\cdot Q_{iji}\cdot
	\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}
	\cdot\mathbb{A}\nonumber
	\\
		&+\sum_{\substack{i, i_2, \cdots, i_n;\\j, j_2, \cdots, j_n;\\m}}\mathring{\nabla}_if_1\cdot  Q_{mjm}\cdot	\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}
		\cdot\mathbb{A}-\sum_{\substack{i,i_2, \cdots, i_n;\\j, j_2, \cdots, j_n}}\mathring{\nabla}_if_1\cdot Q_{iji}\cdot	\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}
		\cdot\mathbb{A}\nonumber
		\\
		=&-\sum_{\substack{i, i_2, \cdots, i_n;\\j, j_2, \cdots, j_n;\\m}}\mathring{\nabla}_{m}f_1\cdot Q_{mji}\cdot
		\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}
		\cdot\mathbb{A}+\sum_{\substack{i, i_2, \cdots, i_n;\\j, j_2, \cdots, j_n;\\m}}\mathring{\nabla}_if_1\cdot  Q_{mjm}\cdot	\delta_{jj_2\cdots j_n}^{ii_2\cdots i_n}
		\cdot{\mathbb{A}}
		.\label{equ:pf-lem3.17-1}
	\end{align}
  Putting \eqref{equ:pf-lem3.17-1} and \eqref{equ:pQ1...n} in to \eqref{equ:pflemma3.17-0}, we obtain \eqref{equ:0=Qjijfi-Q+Q}.
\end{proof}
Then we can prove following lemma.
\begin{lemma}\label{lemma:V12=V21}
	Let $f_0,\cdots,f_n$ be anisotropic capillary convex functions, then $V(f_0,\cdots,f_n)$ is a symmetric and multi-linear function.
\end{lemma}
\begin{proof}
	The multi-linear property is obvious. By the symmetry of $\mathcal{Q}$, we just need to prove
	\begin{align*}
		V(f_0,f_1,f_2,\cdots,f_n)=V(f_1,f_0,f_2,\cdots,f_n).
	\end{align*}
		By the  $1$-homogeneity of $\mathcal{Q}$, we have
		\begin{align}
			\label{equ:pf-V12=V21-1}
			\mathcal{Q}=\mathcal{Q}^{ij}(A_1)_{ij}.
		\end{align}
		 From \cite{Xia13}*{Lemma 2.8}, for hypersurface $\mathcal{C}_{\omega_0},$ we assume $F(\nu)	\mathrm{d} {\mu_{g}}=\mathrm{d}{\mu}_F=\varphi\mathrm{d}\mu_{\mathring{g}}$, where $\mathrm{d}\mu_{\mathring{g}}$ is the induced volume form of $\mathcal{C}_{\omega_0}$ equipped with $\mathring{g}$, then
		\begin{align}
			\label{equ:pf-V12=V21-2}
			\partial_i\varphi=\varphi\cdot \partial_i\log\varphi=\varphi\sum_{k=1}^{n}A_{ik}^k(\mathcal{T}^{-1}(\xi))=-\frac{1}{2}\varphi\sum_{k=1}^{n}Q_{ikk},
		\end{align}
		where  $\{\partial_i\}_{i=1}^n$ is the  orthogonal frame (i.e., $\mathring{g}_{ij}(\xi)=\delta_{ij}$) which satisfies $e_{n}(\xi)=c(\xi)A_F(\nu(\xi))\mu(\xi)$ when $\xi\in\partial\mathcal{C}_{\omega_0}$. By \cite{Ding-Gao-Li-arxiv}*{Remark 3.1 (1)}, we know $e_{\alpha}\in T_{\xi}(\partial\mathcal{C}_{\omega_0})$ for $\xi\in\partial\mathcal{C}_{\omega_0}$ and $\alpha=1,\cdots,n-1$.

  On the other hand, if we let $X(\xi)=\mathring{\nabla}f_1(\xi)+f_1(\xi)\cdot \mathcal{T}^{-1}(\xi)$ for capillary convex function $f_1$ and any $\xi\in\partial\mathcal{C}_{\omega_0}$, then it follows from the proof of Proposition \ref{prop:xia-prpo2.6} that $\<X(\xi),E_{n+1}\>\equiv0$ and
		\begin{align}
			\tau_{\alpha n}[f_1](\xi)\overset{\eqref{derivative}}{=}&G(\mathcal{T}^{-1}(\xi))\(D_{e_{\alpha}}X,e_n\)=\frac{c(\xi)\<D_{e_{\alpha}}X,\mu\>}{F(\nu)}=\frac{c(\xi)\<D_{e_{\alpha}}X,E_{n+1}\>}{F(\nu)\<E_{n+1},\mu\>}\nonumber
			\\
			=&\frac{c(\xi){e_{\alpha}}(\<X,E_{n+1}\>)}{F(\nu)\<E_{n+1},\mu\>}=0, \label{equ:pf-V12=V21-3}	
		\end{align}
		where one uses the fact that $D_{e_{\alpha}}X\in T \mathcal{C}_{\omega_0}$ (by \eqref{derivative}),  $G(\nu_{{F}}(\xi))\(Y,A_F(\nu)\mu\)=\frac{\<Y,\mu\>}{F(\nu)}$ for any $ Y\in T \mathcal{C}_{\omega_0}$ (see \cite{Ding-Gao-Li-arxiv}*{eq. (3.29)}), and $E_{n+1}=\<E_{n+1},\nu\>\nu+\<E_{n+1},\mu\>\mu$.

 By Definition \ref{def:V(f1,.,fn)}, \eqref{equ:pf-V12=V21-1}$\thicksim$\eqref{equ:pf-V12=V21-3}, and divergence theorem, we have
	\begin{align*}
		&V\left(f_0, \cdots, f_{n}\right)=\frac{1}{n+1} \int_{\mathcal{C}_{\omega_0}} f_0 \mathcal{Q}\left(\tau \left[f_1\right], \cdots, \tau \left[f_{n}\right]\right) F(\nu)	\mathrm{d} {\mu_{g}}
		\\
		=&\frac{1}{n+1} \int_{\mathcal{C}_{\omega_0}}f_0\mathcal{Q}^{ij}\(\mathring{\nabla}_{i}\mathring{\nabla}_{j}f_1+\delta_{i j} f_1-\frac{1}{2}\sum_{k=1}^{n} Q_{i j k} \mathring{\nabla}_{k} f_1\)\varphi\mathrm{d}\mu_{\mathring{g}}
		\\
		=&\frac{1}{n+1} \int_{\mathcal{C}_{\omega_0}}
		-\varphi \mathcal{Q}^{ij}\mathring{\nabla}_{i}f_0 \mathring{\nabla}_{j}f_1- \varphi f_0\mathring{\nabla}_{j}\mathcal{Q}^{ij} \mathring{\nabla}_{i}f_1
		-f_0 \mathcal{Q}^{ij}\mathring{\nabla}_{j}f_1\partial_i\varphi
		\\
		&+\mathcal{Q}^{ij}\delta_{i j} f_1f_0\varphi-\frac{1}{2}\sum_{k=1}^{n}\mathcal{Q}^{ij} Q_{i j k} f_0\mathring{\nabla}_{k} f_1\varphi\ \mathrm{d}\mu_{\mathring{g}}
		+\frac{1}{n+1}\int_{\partial\mathcal{C}_{\omega_0}} f_0\varphi\mathcal{Q}^{in}\mathring{\nabla}_if_1 d \mathring{s}
		\\
		\overset{\eqref{robin}}{=}&\frac{1}{n+1} \int_{\mathcal{C}_{\omega_0}}
		-\varphi \mathcal{Q}^{ij}\mathring{\nabla}_{i}f_0 \mathring{\nabla}_{j}f_1
		+\mathcal{Q}^{ij}\delta_{i j} f_1f_0\varphi
		\\
		&-f_0\varphi\( \mathring{\nabla}_{j}\mathcal{Q}^{ij} \mathring{\nabla}_{i}f_1
		-\frac{1}{2}\sum_{k=1}^{n}Q_{ikk} \mathcal{Q}^{ij}\mathring{\nabla}_{j}f_1+\frac{1}{2}\sum_{k=1}^{n}\mathcal{Q}^{ij} Q_{i j k} \mathring{\nabla}_{k} f_1\)\ \mathrm{d}\mu_{\mathring{g}}
		\\
		&+\frac{1}{n+1}\int_{\partial\mathcal{C}_{\omega_0}} f_0\varphi\mathcal{Q}^{nn}\frac{c(\xi)\omega_0}{F(\nu(\xi))\<\mu(\xi),E_{n+1}\>}f_1 d \mathring{s}
		\\
			\overset{\eqref{equ:0=Qjijfi-Q+Q}}{=}&
		\frac{1}{n+1} \int_{\mathcal{C}_{\omega_0}}
		- \mathcal{Q}^{ij}\mathring{\nabla}_{i}f_0 \mathring{\nabla}_{j}f_1
		+\mathcal{Q}^{ij}\delta_{i j} f_1f_0 F(\nu)	\mathrm{d} {\mu_{g}}
		\\
		&+\frac{1}{n+1}\int_{\partial\mathcal{C}_{\omega_0}} f_0f_1 \varphi\mathcal{Q}^{nn}\frac{c(\xi)\omega_0}{F(\nu(\xi))\<\mu(\xi),E_{n+1}\>}d \mathring{s},
	\end{align*}
	which   is symmetric in $f_0$ and $f_1$, where $d \mathring{s}$ is the  area element induced on the boundary $\partial \mathcal{C}_{\omega_0}$
	from  $(\mathcal{C}_{\omega_0},\mathring{g})$. We finish the proof of the lemma.
\end{proof}
\begin{remark}
	By adapting the technique of  \cite{Xia-arxiv}*{Corollary 2.10}, since  $\hat{s}_o$ (defined by \eqref{equ:s0}) is anisotropic capillary support function of $\mathcal{C}_{\omega_0}$  and $\tau[\hat{s}_o]=I_n$ (see \eqref{equ:A[l]}),
 the anisotropic capillary Minkowski formula (see \cite{Jia-Wang-Xia-Zhang2023}*{Theorem 1.3}) can also be derived from Proposition \ref{lemma:V12=V21}.
\end{remark}

 In terms of the construction of mixed volumes for standard capillary convex bodies in  \cite{Xia-arxiv}, we similarly consider the combination of anisotropic capillary convex bodies $K:=\sum_{i=1}^m \lambda_i K_i$  for $K_1, \cdots, K_m \in \mathcal{K}_{\omega_0}$.  The mixed volume $V\left(K_{i_0}, \cdots, K_{i_{n}}\right)$ defined by
\begin{align}
	|K|=\sum_{i_0, \cdots, i_{n}=1}^m \lambda_{i_0} \cdots \lambda_{i_{n}} V\left(K_{i_0}, \cdots, K_{i_{n}}\right),\label{equ:|K|}
\end{align}
for anisotropic capillary convex bodies in $\mathcal{K}_{\omega_0}$ can be written as an integral over $\mathcal{C}_{\omega_0}$ by using the anisotropic  capillary support function.


\begin{proposition}\label{prop7.3}
	Let $K_1, \cdots, K_m \in \mathcal{K}_{\omega_0}$ and $\hat{s}_i$ be the anisotropic  capillary support function of $K_i$. Then we have
	\begin{align}\label{equ:VKKKLLL}
		V\left(K_{i_0}, \cdots, K_{i_{n}}\right)&=V\left(\hat{s}_{i_0}, \cdots, \hat{s}_{i_{n}}\right)
		\\
		&=\frac{1}{n+1} \int_{\mathcal{C}_{\omega_0}} \hat{s}_{i_0} \mathcal{Q}\left(A\left[\hat{s}_{i_2}\right], \cdots, A\left[\hat{s}_{i_{n}}\right]\right) F(\nu)	\mathrm{d} {\mu_{g}}
	   .\nonumber
	\end{align}
\end{proposition}
\begin{proof}
Denote $K:=\sum_{i=1}^m \lambda_i K_i$ and $\Sigma=\partial K\cap \mathbb{R}_+^{n+1}$.	Since $\widetilde{\nu_F}:\Sigma\to \mathcal{C}_{\omega_0}$ is a diffeomorphism and $\hat{s}_K(\xi)=\hat{u}_K(\widetilde{\nu_{{F}}}^{-1}(\xi))$ for $\xi\in\mathcal{C}_{\omega_0}$, we have %{\color{red}(the boundary of $K$ is $\Sigma$?)}
	\begin{align*}
		(n+1)|K|=\int_{\Sigma}\<X,\nu\>\mathrm{~d}\mu_g=\int_{\Sigma}\frac{\<X,\nu\>}{F(\nu)}\mathrm{~d}\mu_F=\int_{\mathcal{C}_{\omega_0}}
		\hat{s}_K\det(A[\hat{s}_K])F(\nu)	\mathrm{d} {\mu_{g}}.
	\end{align*}
	By  \eqref{equ:sK=sumSi}, $\hat{s}_K=\sum_{i=1}^{m}\lambda_i\hat{s}_i$, then we obtain
		\begin{align*}
		(n+1)|K|=&\int_{\mathcal{C}_{\omega_0}}
		\hat{s}_K\det(A[\hat{s}_K])F(\nu)	\mathrm{d} {\mu_{g}}
		\\
		=&\int_{\mathcal{C}_{\omega_0}}
		\(\sum_{i=1}^{m}\lambda_i\hat{s}_i\)\det(\lambda_iA[\hat{s}_1]+\cdots\lambda_mA[\hat{s}_m])F(\nu)	\mathrm{d} {\mu_{g}}
		\\
		\overset{\eqref{equ:QA}}{=}&\int_{\mathcal{C}_{\omega_0}}
		\(\sum_{i=1}^{m}\lambda_i\hat{s}_i\)
		\(\sum_{i_1, \cdots, i_n=1}^m \lambda_{i_1} \cdots \lambda_{i_n} \mathcal{Q}\left(A[{\hat{s}_{i_1}}], \cdots, A[\hat{s}_{i_n}]\right)\)
		F(\nu)	\mathrm{d} {\mu_{g}}
		\\
		=&\sum_{i_0, \cdots, i_n=1}^m \lambda_{i_0} \cdots \lambda_{i_n} \int_{\mathcal{C}_{\omega_0}} \hat{s}_{i_0} \mathcal{Q}
		\left(A[{\hat{s}_{i_1}}], \cdots, A[\hat{s}_{i_n}]\right)
	F(\nu)	\mathrm{d} {\mu_{g}}.
	\end{align*}
	Combining with \eqref{equ:|K|}, we have \eqref{equ:VKKKLLL}.
\end{proof}

Specially, from \cite{Ding-Gao-Li-arxiv}*{Lemma 7.6 (i)}, we can prove the following lemma.
\begin{lemma}\label{lemma:V-k=V(KKK,LLL)}
	Let $\widehat{\Sigma}\in\mathcal{K}_{\omega_0}$ be an anisotropic capillary convex body with anisotropic capillary support function $\hat{s}$ in $\mathcal{C}_{\omega_0}$. Then for $-1\leq k\leq n$, we have
	\begin{align*}
		\mathcal{V}_{k+1,\omega_0}(\Sigma)	=V\(\underbrace{\widehat{\Sigma}, \cdots, \widehat{\Sigma}}_{(n-k) \text { copies }}, \underbrace{\widehat{\mathcal{C}}_{\omega_0}, \cdots, \widehat{\mathcal{C}}_{\omega_0}}_{(k+1) \text { copies }}\).
	\end{align*}
\end{lemma}
\begin{proof}
	For $k=-1$, it is easy to check that
	\begin{align*}
		V\left(\widehat{\Sigma},\cdots,\widehat{\Sigma}\right)=&\frac{1}{n+1} \int_{\mathcal{C}_{\omega_0}} \hat{s} \mathcal{Q}\left(A\left[\hat{s}\right], \cdots, A\left[\hat{s}\right]\right) F(\nu)	\mathrm{d} {\mu_{g}}
		\\
		=&\frac{1}{n+1} \int_{\mathcal{C}_{\omega_0}} \hat{s} \det(A[\hat{s}]) F(\nu)	\mathrm{d} {\mu_{g}}
		\\
		=&\frac{1}{n+1} \int_{\Sigma} \hat{u}  d {\mu}_F
		\\
		=&|\widehat{\Sigma}|=\mathcal{V}_{0,\omega_0}(\Sigma),
	\end{align*}
 where we use	the fact that the support function of hypersurface  ${\partial\Sigma}\subset\partial\overline{\mathbb{R}^{n+1}_+}$ in $\mathbb{R}^{n+1}$ is everywhere zero.

 Now we conside the case  $k=0,\cdots,n$.
	Since the anisotropic support function of $\W$ is constant $1$, the anisotropic support function of $\widetilde{\W}=\W+\omega_0E_{n+1}^F$ is $$\hat{u}_0(X)=1+\omega_0G(\nu_{{F}}(X))\(E_{n+1}^F,\nu_{{F}}(X)\),$$ for $X\in\widetilde{\W}$. Then the anisotropic capillary support function of $\mathcal{C}_{\omega_0}=\widetilde{\W}\cap\overline{\mathbb{R}^{n+1}_+}$ is
$$\hat{s}_o(\xi)=\hat{u}_0\left(\widetilde{\nu_F}^{-1}(\xi)\right)=1+\omega_0G(\mathcal{T}^{-1}(\xi))\(E_{n+1}^F,\mathcal{T}^{-1}(\xi)\),\quad \xi\in\mathcal{C}_{\omega_0}.$$
Choose the normal coordinate $\{e_i=\partial_i\xi\}_{i=1}^n\in T_{\xi}\mathcal{C}_{\omega_0}$, by Lemma \ref{lemma:Gauss-Weingarten} we have
\begin{align}
	\mathring{\nabla}_{e_i}\left(
	G(\mathcal{T}^{-1}(\xi))\(E_{n+1}^F,\mathcal{T}^{-1}(\xi)\)
	\right)=&G(\mathcal{T}^{-1}(\xi))\(E_{n+1}^F,\partial_i(\mathcal{T}^{-1}(\xi))\)\nonumber
	\\
	=&G(\mathcal{T}^{-1}(\xi))\(E_{n+1}^F,e_i\),\label{equ:pf-lemma3.20-1}
\end{align}
and
\begin{align}
	&\mathring{\nabla}_{e_j}\mathring{\nabla}_{e_i}\left(
	G(\mathcal{T}^{-1}(\xi))\(E_{n+1}^F,\mathcal{T}^{-1}(\xi)\)
	\right)=\mathring{\nabla}_{e_j}\left(G(\mathcal{T}^{-1}(\xi))\(E_{n+1}^F,e_i\)\right)\nonumber
	\\
	=&G(\mathcal{T}^{-1}(\xi))\(E_{n+1}^F,\partial_j\partial_i\xi\)+Q(\mathcal{T}^{-1}(\xi))\(E_{n+1}^F,e_i,\partial_j(\mathcal{T}^{-1}(\xi))\)\nonumber
	\\
	=&G(\mathcal{T}^{-1}(\xi))\(E_{n+1}^F,-\delta_{i j} \mathcal{T}^{-1}(\xi)-\frac{1}{2}  Q_{i j k} e_k\)
	+Q(\mathcal{T}^{-1}(\xi))\(E_{n+1}^F,e_i,e_j\)	\nonumber
	\\
	=&-\delta_{i j}G(\mathcal{T}^{-1}(\xi))\(E_{n+1}^F, \mathcal{T}^{-1}(\xi)\)
	\label{equ:pf-lemma3.20-2}+\frac{1}{2}  Q_{i j k}G(\mathcal{T}^{-1}(\xi))\(E_{n+1}^F, e_k\).
\end{align}
Combination of \eqref{equ:pf-lemma3.20-1} and \eqref{equ:pf-lemma3.20-2} gives
\begin{align}\label{equ:A[X,v]}
	\tau_{ij}\left[G(\mathcal{T}^{-1}(\xi))\(E_{n+1}^F,\mathcal{T}^{-1}(\xi)\)\right]=0,
\end{align}
and then
\begin{align}\label{equ:A[l]}
	\tau[\hat{s}_o]=\tau[1]=[\delta_{i j}]=:I_n.
\end{align}

	From \cite{Ding-Gao-Li-arxiv}*{Lemma 7.6 (i)}, we can calculate that
	\begin{align*}
		\mathcal{V}_{k+1,\omega_0}(\Sigma)=&\frac{1}{n+1}\int_{\Sigma}H_k^F\(1+\omega_0G(\nu_{{F}})(\nu_{{F}},E_{n+1}^F)\) {\rm d}\mu_F
		\\
		=&\frac{1}{n+1}\int_{\mathcal{C}_{\omega_0}}\hat{s}_o\mathcal{Q}(
		 (\underbrace{\tau[\hat{s}],\cdots,\tau[\hat{s}]}_{(n-k) \text{ copies }},\underbrace{I_n,\cdots,I_n}_{k \text{ copies }})
		) F(\nu)	\mathrm{d} {\mu_{g}}
		\\
		=&V\(\underbrace{\hat{s}, \cdots, \hat{s}}_{(n-k) \text { copies }}, \underbrace{\hat{s}_o, \cdots, \hat{s}_o}_{(k+1) \text { copies }}\).
	\end{align*}
	Then we complete the proof.
\end{proof}
\begin{remark}\label{rk:3}
	In the proof process of \eqref{equ:A[X,v]}, it can be observed that $E_{n+1}^F$ in \eqref{equ:A[X,v]} may be substituted with an arbitrary constant vector in $\mathbb{R}^{n+1}$.
\end{remark}
From \eqref{equ:|K|} and Lemma \ref{lemma:V-k=V(KKK,LLL)}, we have a direct consequence (Steiner-type formula) as follows, which extends the result of \cite{Xia-arxiv}*{Proposition 2.16} to anisotropic capillary convex bodies.
\begin{lemma}
	Let $\widehat{\Sigma}\in\mathcal{K}_{\omega_0}$ be associated with a convex anisotropic $\omega_0$-capillary hypersurface $\Sigma$. Then for any $t>0$, there holds
	\begin{align*}
		|\widehat{\Sigma}+t\widehat{\mathcal{C}}_{\omega_0}|=\sum_{k=0}^{n+1}\binom{n+1}{k}t^k\mathcal{V}_{k,\omega_0}(\Sigma).
	\end{align*}
\end{lemma}


\section{The Alexandrov-Fenchel inequalities for mixed volume}\label{sec 4}
Based on the preparations in Section \ref{sec 3} (including definitions and properties of anisotropic capillary convex bodies in the anisotropic setting), we can prove the main Theorem \ref{thm:A-F-convex} following the process in \cite{Xia-arxiv}, or adapting the idea of \cite{Shenfeld19,Shenfeld22}.

We first derive the following lemma, which is inspired by \cite{Xia13}*{Lemma 5.4}.
\begin{lemma}
	\label{lemma:ker-A}
	Let $f(\xi)\in C^2(\mathcal{C}_{\omega_0})$ be a function such that $\tau[f]=0$. Then
	\begin{align}\label{equ:f=1-n+1}
		f=\sum_{\alpha=1}^{n+1}a_{\alpha}G(\mathcal{T}^{-1}(\xi))(\mathcal{T}^{-1}(\xi),E_{\alpha}),
	\end{align}
	for some constants $a_1,\cdots,a_{n+1}$.
	Furthermore, if $f$ also satisfies the boundary condition \eqref{robin}, then $a_{n+1}=0$, that is
	\begin{align*}%\label{equ:f=1-n+n}
		f=\sum_{i=1}^{n}a_{i}G(\mathcal{T}^{-1}(\xi))(\mathcal{T}^{-1}(\xi),E_{i}),
	\end{align*}
	for some constants $a_1,\cdots,a_{n}$.
\end{lemma}
\begin{proof}
	Let $e_{n+1}(\xi)=\mathcal{T}^{-1}(\xi)$ be the anisotropic normal vector of $\xi\in\mathcal{C}_{\omega_0}$ and $\{e_i(\xi)\}_{i=1}^n$ a local orthonormal frame field with respect to $\mathring{g}$ on $\mathcal{C}_{\omega_0}$ such that $\{e_{\alpha}\}_{\alpha=1}^{n+1}$ is positive-oriented orthonormal frame field with respect  to $G(\mathcal{T}^{-1}(\xi))$ in $T_{\xi}\mathbb{R}^{n+1}$ ($\xi\in\mathcal{C}_{\omega_0}$). By Lemma \ref{lemma:Gauss-Weingarten}, we have (in normal coordinates at a point, i.e. $\mathring{g}_{ij}=\delta_{ij}$ and $\mathring{\nabla}_{e_i}e_j=0$)
	\begin{align}\label{equ:ei-en+1}
	%\omega^{n+1}|_{\mathcal{C}_{\omega_0}}=0,\quad	
	e_i(e_{n+1})=e_i, \quad e_{i}(e_j)=-\frac{1}{2}\sum_{k=1}^nQ_{ijk}e_k-\delta_{ij}e_{n+1},
	\end{align}
	for $ i,j\in\{1,\cdots,n\}$. Denote by $f_i=e_i(f)$, and define a vector valued function \begin{align}\label{equ:Z=}
		Z(\xi)=\sum_{i=1}^{n}f_i(\xi)e_i(\xi)+f(\xi)e_{n+1}(\xi),\quad \xi\in\mathcal{C}_{\omega_0}.
	\end{align} Since $G(\mathcal{T}^{-1}(\xi))\(e_i,e_{n+1}\)=0$ and $G(\mathcal{T}^{-1}(\xi))\(e_{n+1},e_{n+1}\)=1$, we get
	\begin{align}\label{equ:f=}
	f=G(\mathcal{T}^{-1}(\xi))\(Z,e_{n+1}\).
	\end{align}
	From \eqref{equ:ei-en+1},  \eqref{equ:Z=} and $\tau[f]=0$, one derives
	\begin{align*}
		e_i(Z)=\sum_{j=1}^n\tau_{ij}[f]\cdot e_j=0.
	\end{align*}
	%where we denote $f_{ij}=\mathring{\nabla}_{e_i}\mathring{\nabla}_{e_j}f$.
	Then $Z(\xi)\in\mathbb{R}^{n+1}$ is a constant vector for $\xi\in\mathcal{C}_{\omega_0}$, and can be written as $Z=\sum_{\alpha=1}^{n+1}a_{\alpha}E_{\alpha}$ for some constants $a_{\alpha}$. Putting it into \eqref{equ:f=} yields \eqref{equ:f=1-n+1}.

	If in addition $f$ satisfies \eqref{robin}, we have
	\begin{align}
		\frac{\omega_0}{F(\nu)\<\mu,E_{n+1}\>} f
		=&
		\mathring{\nabla}_{\mu_F} f
		=\mathring{g}(\mathring{\nabla}f,\mu_{{F}})=G(\mathcal{T}^{-1}(\xi))\(\mathring{\nabla}f,\mu_{{F}}\)\nonumber
		\\
		=&\frac{\<\mathring{\nabla}{f},\mu\>}{F(\nu)}
		\quad \text{on}\quad \partial \mathcal{C}_{\omega_0},\nonumber
	\end{align}
	where the  last equality follows from \cite{Ding-Gao-Li-arxiv}*{eq. (3.29)}.
	Combining with $Z=\sum_{\alpha=1}^{n+1}a_{\alpha}E_{\alpha}$, \eqref{equ:Z=}, and $E_{n+1}=\<E_{n+1},\nu\>\nu+\<E_{n+1},\mu\>\mu$, %\eqref{equ:f=}, and \eqref{equ:Z=},
	 we have
	\begin{align*}
		a_{n+1}=&\<Z,E_{n+1}\>=\<fe_{n+1},E_{n+1}\>+\<\mathring{\nabla}f,\mu\>\<\mu,E_{n+1}\>
	\\
	=&-\omega_0f+\omega_0f=0.
	\end{align*}
	Here we use the fact that $\widehat{\mathcal{C}}_{\omega_0}\in\mathcal{K}_{\omega_0}$, which means $-\omega_0=\<\nu_{{F}}(\xi),E_{n+1}\>=\<\mathcal{T}^{-1}(\xi),E_{n+1}\>$.
	This completes the proof.	
\end{proof}

The following lemma will be crucially used in the subsequent analysis.

\begin{lemma}[ \cite{Shenfeld19}*{Lemma 1.4}]\label{lemma:3.1}
	 Let $\mathcal{A}$ be a symmetric matrix. Then the following conditions are equivalent:
\begin{itemize}
	\item [(i)] $\langle x, \mathcal{A} y\rangle^2 \geq\langle x, \mathcal{A} x\rangle\langle y, \mathcal{A} y\rangle$ for all $x, y$ such that $\langle y, \mathcal{A} y\rangle \geq 0$;
\item[(ii)] The positive eigenspace of $\mathcal{A}$ has dimension at most one.
\end{itemize}
The conclusion remains valid if $\mathcal{A}$ is a self-adjoint operator on a Hilbert space with a discrete spectrum, provided the vectors $x, y$ are chosen in the domain of $\mathcal{A}$.
\end{lemma}

We now establish the following result:
 \begin{theorem}\label{thm:V2>VV}
 	Let $f_1, \cdots, f_n \in C^2\left(\mathcal{C}_{\omega_0}\right)$ be anisotropic capillary convex functions on $\mathcal{C}_{\omega_0}$ and at least one of $f_k\,(2 \leq k \leq n)$ is positive. Then for any anisotropic capillary function $f \in C^2\left(\mathcal{C}_{\omega_0}\right)$, there holds
\begin{align}\label{equ:V2>VV}
	V^2\left(f, f_1, f_2, \cdots, f_n\right) \geq V\left(f, f, f_2, \cdots, f_n\right) V\left(f_1, f_1, f_2, \cdots, f_n\right) .
\end{align}
Equality holds if and only if $f(\xi)=a f_1(\xi)+\sum_{i=1}^n a_iG(\mathcal{T}^{-1}(\xi))\(\mathcal{T}^{-1}(\xi), E_i\)$ for some constants $a, a_i \in \mathbb{R}$. % and $\left\{E_i\right\}_{i=1}^n$ being the horizontal coordinate unit vectors of $\overline{\mathbb{R}_{+}^{n+1}}$.
 \end{theorem}
\begin{proof} Without loss of generality, we assume that $f_2$ is positive on $\mathcal{C}_{\omega_0}$. Define $\omega$ to be the following area measure on $\mathcal{C}_{\omega_0}$
$$
d \omega:=\frac{1}{n+1} \frac{Q\left(A\left[f_2\right], A\left[f_2\right], A\left[f_3\right],\cdots, A\left[f_n\right]\right)}{f_2} F(\nu)	\mathrm{d} {\mu_{g}} .
$$
We assume that  $L^2\left(\mathcal{C}_{\omega_0}, \omega\right)$ is the Hilbert space associated with the inner product $\langle,\rangle_{L^2(\omega)}$ given by
$$
\langle f, g\rangle_{L^2(\omega)}:=\int_{\mathcal{C}_{\omega_0}} f \cdot g d \omega, \quad \forall f, g \in L^2\left(\mathcal{C}_{\omega_0}, \omega\right) .
$$
Similarly we can define $W^{2,2}\left(\mathcal{C}_{\omega_0}, \omega\right)$ in terms of the inner product  $\langle,\rangle_{L^2(\omega)}$. Define the following operator similar to \cite{Xia-arxiv,Shenfeld19}:
$$
\begin{aligned}
\mathcal{A}:  \operatorname{dom}	&(\mathcal{A}) \subset L^2\left(\mathcal{C}_{\omega_0}, \omega\right) \rightarrow L^2\left(\mathcal{C}_{\omega_0}, \omega\right), \\
	 \mathcal{A}(f)=:&\frac{f_2 \mathcal{Q}\left(A[f], A\left[f_2\right], \cdots, A\left[f_n\right]\right)}{\mathcal{Q}\left(A\left[f_2\right], A\left[f_2\right], \cdots, A\left[f_n\right]\right)}
	\\
	=&\frac{f_2\mathcal{Q}^{ij}\tau_{ij}[f]}{\mathcal{Q}(A[f_2],A[f_2],\cdots,A[f_n])}
	\\
	=:&a^{ij}(\xi)\mathring{\nabla}_{i}\mathring{\nabla}_{j}f+b^i(\xi)\mathring{\nabla}_{i}f+c(\xi)f,\quad \xi\in \mathcal{C}_{\omega_0},
\end{aligned}
$$
where $a^{ij}=\frac{f_2\mathcal{Q}^{ij}}{\mathcal{Q}(A[f_2],A[f_2],\cdots,A[f_n])}$ is independent of $f$, and $\operatorname{dom}(\mathcal{A})$ is given by
$$
\operatorname{dom}(\mathcal{A}):=\left\{f \in W^{2,2}\left(\mathcal{C}_{\omega_0}, \omega\right): f\, \text{satisfies boundary condition \eqref{robin}}\right\} .
$$
Since $f_2>0$ and $f_2, \cdots, f_n$ are anisotropic capillary convex functions on $\mathcal{C}_{\omega_0}$, all the above objects are well-defined.


By the very definition of $\mathcal{A}$, \eqref{equ:V2>VV} is equivalent to
\begin{align}\label{equ:AAf2>fAffAf}
	\left(\left\langle f, \mathcal{A} f_1\right\rangle_{L^2(\omega)}\right)^2 \geq\langle f, \mathcal{A} f\rangle_{L^2(\omega)}\left\langle f_1, \mathcal{A} f_1\right\rangle_{L^2(\omega)},
\end{align}
for functions $f,\left\{f_i\right\}_{i=1}^n$ that satisfy the assumptions. Lemma \ref{lemma:3.1} reduces the proof to show that the positive eigenspace of $\mathcal{A}$ is at most one-dimensional.

Since $f_1, \cdots, f_n$ are anisotropic capillary convex functions and $f_2>0$, we know $[\mathcal{Q}^{ij}]>0$, and $[a^{ij}]>0$, then $\mathcal{A}$ is a uniformly elliptic operator with a Robin boundary condition. Lemma  \ref{lemma:V12=V21} implies
$$
\langle f, \mathcal{A} g\rangle_{L^2(\omega)}=\langle g, \mathcal{A} f\rangle_{L^2(\omega)}, \quad \forall f, g \in \operatorname{dom}(\mathcal{A}),
$$
which means that $\mathcal{A}$ is a self-adjoint operator on $\operatorname{dom}(\mathcal{A})$. Consider the following eigenvalue problem
\begin{eqnarray}\label{equ:eigenvalue-problem}
	\left\{
\begin{aligned}
	\mathcal{A} f & =\lambda f, & & \text { in } \mathcal{C}_{\omega_0}, \\
	\mathring{\nabla}_{\mu_F} f&=\frac{\omega_0}{F(\nu)\<\mu,E_{n+1}\>} f.\quad  & & \text { on } \partial \mathcal{C}_{\omega_0} .
\end{aligned}\right.
\end{eqnarray}
According to the classical spectral theory for compact, self-adjoint operators, the eigenvalue problem \eqref{equ:eigenvalue-problem} admits a sequence of real eigenvalues $\lambda_1 \geq \lambda_2 \geq \cdots$, where the first eigenvalue $\lambda_1$ is simple and its first eigenfunction has the same sign everywhere (see \cite{Chang-Wang-Wu}*{Theorem 5.10}, or see Krein-Rutman Theorem in \cite{Deimling}*{Theorem 19.3}, \cite{Du2006}*{Theorem 1.2}).
It is trivial to check that $f_2$ satisfies \eqref{equ:eigenvalue-problem} with $\lambda=1$. Since $f_2>0, f_2$ is the first eigenfunction with the first eigenvalue $\lambda_1=1$.

On the other hand, since $A[f_2],\cdots,A[f_n]$ are positive definite, by using Alexandrov's mixed discriminant inequality (see e.g. \cite{book-convex-body}*{Theorem 5.5.4}), we have
\begin{align}
	&\left(\mathcal{Q}\left(A[g], A\left[f_2\right], \cdots, A\left[f_n\right]\right)\right)^2\nonumber
	\\
	 \geq &\mathcal{Q}\left(A\left[f_2\right], A\left[f_2\right], \cdots, A\left[f_n\right]\right) \cdot \mathcal{Q}\left(A[g], A[g], A\left[f_2\right], \cdots, A\left[f_n\right]\right),\label{equ:Q2>QQ}
\end{align}
together with Lemma \ref{lemma:V12=V21}, for any function $g \in \operatorname{dom}(\mathcal{A})$ we have
	\begin{align}
	\langle\mathcal{A} g, \mathcal{A} g\rangle_{L^2(\omega)} & =\frac{1}{n+1} \int_{\mathcal{C}_{\omega_0}} \frac{f_2\left(\mathcal{Q}\left(A[g], A\left[f_2\right], \cdots, A\left[f_n\right]\right)\right)^2}{\mathcal{Q}\left(A\left[f_2\right], A\left[f_2\right], \cdots, A\left[f_n\right]\right)} F(\nu)	\mathrm{d} {\mu_{g}} \nonumber
	\\
	& \geq \frac{1}{n+1} \int_{\mathcal{C}_{\omega_0}} f_2 \mathcal{Q}\left(A[g], A[g], A\left[f_2\right], \cdots, A\left[f_n\right]\right) F(\nu)	\mathrm{d} {\mu_{g}} \nonumber
	\\
	& =\frac{1}{n+1} \int_{\mathcal{C}_{\omega_0}} g \mathcal{Q}\left(A[g], A\left[f_2\right], \cdots, A\left[f_n\right]\right) F(\nu)	\mathrm{d} {\mu_{g}} \nonumber
	\\
	& =\langle g, \mathcal{A} g\rangle_{L^2(\omega)} .\label{equ:AgAg>gAg}
\end{align}
Therefore, if $\lambda$ is an eigenvalue of the operator $\mathcal{A}$, the above inequality implies that $\lambda^2 \geq \lambda$, which means $\lambda \geq 1$ or $\lambda \leq 0$. Consequently, the positive eigenspace of $\mathcal{A}$ is of one dimension and is spanned by $f_2$. In view of Lemma  \ref{lemma:3.1}, we complete the proof of \eqref{equ:AAf2>fAffAf}.

Next, we characterize the equality case. If equality holds in \eqref{equ:V2>VV}, then also equality holds in \eqref{equ:AAf2>fAffAf}, that is
\begin{align}	
\left(\left\langle f, \mathcal{A} f_1\right\rangle_{L^2(\omega)}\right)^2=\langle f, \mathcal{A} f\rangle_{L^2(\omega)}\left\langle f_1, \mathcal{A} f_1\right\rangle_{L^2(\omega)} .\label{equ:fAf2=}
\end{align}


From \cite{Shenfeld19}*{Lemma 2.9 and its proof}, equality holds in \eqref{equ:fAf2=} if and only if $\widetilde{f}:=f-a f_1 \in$ $\operatorname{Ker}(\mathcal{A})$ for some constant $a \in \mathbb{R}$.

For $g=\tilde{f}$, equality holds in \eqref{equ:AgAg>gAg} and in turn in Alexandrov's mixed discriminant inequality \eqref{equ:Q2>QQ}. It follows from \cite{book-convex-body}*{Theorem 5.5.4} that $A[\tilde{f}]=c A\left[f_2\right]$ for some function $c: \mathcal{C}_{\omega_0} \rightarrow \mathbb{R}$. Since $\tilde{f} \in \operatorname{Ker}(\mathcal{A})$, we have
$$
0=\frac{f_2 \mathcal{Q}\left(A\left[\tilde{f}-c f_2\right], A\left[f_2\right], \cdots, A\left[f_n\right]\right)}{\mathcal{Q}\left(A\left[f_2\right], A\left[f_2\right], \cdots, A\left[f_n\right]\right)}=\mathcal{A} \tilde{f}-cf_2=-cf_2,
$$
which implies $c=0$, since $f_2>0$. Then $A[\tilde{f}]=0$,  combining with the fact that $\tilde{f}$ is an anisotropic capillary function, by Lemma \ref{lemma:ker-A}, we obtain   $$\tilde{f}=\sum_{i=1}^n a_iG(\mathcal{T}^{-1}(\xi))\(\mathcal{T}^{-1}(\xi), E_i\)$$ for some constants $a_i \in \mathbb{R}, i=1, \cdots, n$. Therefore, equality in \eqref{equ:V2>VV} holds if and only if $f=a f_1+\sum_{i=1}^n a_iG(\mathcal{T}^{-1}(\xi))\(\mathcal{T}^{-1}(\xi), E_i\)$. Combining with \eqref{equ:G(vF,Y)=<v,Y>/F}, we complete the proof.
\end{proof}
 \begin{proof}[\textbf{Proof of Theoren \ref{thm:A-F-convex}}]
 	Let $f$ and $f_i(i=1, \cdots, n)$ be the anisotropic capillary support functions $\hat{s}_{k}\ (1\leq k\leq n+1)$ of $\widehat{\Sigma}_1$ and $\widehat{\Sigma}_{i+1}(i=1, \cdots, n)$, in Theorem \ref{thm:A-F-convex}.  Obviously, $f$ and $f_i$ are anisotropic capillary convex functions. By a horizontal translation, we may assume $f_i>0$. Applying Theorem \ref{thm:V2>VV} and taking into account of Proposition \ref{prop7.3}, we obtain the desired inequality. Equality holds if and only if
 	\begin{align}\label{equ:f=af+...}
 		f=a f_1+\sum_{i=1}^n a_iG(\mathcal{T}^{-1}(\xi))\(\mathcal{T}^{-1}(\xi), E_i\).
 	\end{align}
 	It follows from $A[f]>0$, \eqref{equ:A[X,v]} and Remark \ref{rk:3} that the constant $a>0$.  For any convex anisotropic $\omega_0$-capillary hypersurface, we have  $\nu_{{F}}(X(\xi))=\mathcal{T}^{-1}(\xi)$ for $\xi\in\mathcal{C}_{\omega_0}$ by \eqref{equ:X(xi)=t-1VF}, which yields \eqref{equ:s=as+...} together  with \eqref{equ:G(vF,Y)=<v,Y>/F} and \eqref{equ:f=af+...}.
 \end{proof}

An application of Theorem \ref{thm:A-F-convex}, combined with the methodology developed in \cite{book-convex-body}*{Section 7.4 and equation (7.63)}, yields the following inequality for anisotropic capillary convex bodies.
 \begin{corollary}\label{cor:4.3}
 	Let $m \in\{1, \cdots, n+1\}$ and assume $K_0, K_1, \cdots, K_{m+1}, \cdots, K_{n+1} \in \mathcal{K}_{\omega_0}$, and $\hat{s}_j (0\le j\le n+1)$ are the capillary support function of $K_j$. Let
$$
V_{(i), {\omega_0}}:=V(\underbrace{\hat{s}_0, \cdots, \hat{s}_0}_{(m-i) \text { copies }} \underbrace{\hat{s}_1, \cdots, \hat{s}_1}_{i \text { copies }}, \hat{s}_{m+1}, \cdots, \hat{s}_{n+1}), \quad \text { for } \quad i=0, \cdots, m .
$$
Then $V_{(i), {\omega_0}}$ satisfies
$$
V_{(j), {\omega_0}}^{k-i} \geq V_{(i), {\omega_0}}^{k-j} V_{(k), {\omega_0}}^{j-i}, \quad 0 \leq i<j<k \leq m \leq n+1 .
$$
Equality holds if and only if $\hat{s}_0=a \hat{s}_1+\sum_{i=1}^n a_i\frac{\<\nu, E_i\>}{F(\nu)}$ for some constants $a>0$ and $a_i, 1 \leq i \leq n$.
 \end{corollary}
As a consequence, we finally arrive Theorem \ref{thm:A-F-k}.
\begin{proof}[\textbf{Proof of Theorem \ref{thm:A-F-k}}] By choosing $k=m=n+1, K_0=\widehat{\Sigma}$ and $K_1=\widehat{\mathcal{C}}_{\omega_0}$ in Corollary \ref{cor:4.3}, together with the fact that $V_{(n+1), {\omega_0}}=\left|\widehat{\mathcal{C}}_{\omega_0}\right|$ and Lemma \ref{lemma:V-k=V(KKK,LLL)}, we obtain the desired result.
\end{proof}













